\n  width: 36px;\r\n  height: 36px;\r\n  background: rgba(0,0,0,0.05);\r\n  border-radius: 10px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-size: 16px;\r\n}\r\n.footer-2-bottom {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  padding-top: 25px;\r\n  border-top: 1px solid rgba(0,0,0,0.08);\r\n  flex-wrap: wrap;\r\n  gap: 15px;\r\n}\r\n.footer-2-bottom p {\r\n  color: #888;\r\n  font-size: 12px;\r\n}\r\n.footer-2-payment {\r\n  display: flex;\r\n  gap: 15px;\r\n}\r\n.footer-2-payment span {\r\n  font-size: 22px;\r\n  color: #666;\r\n}\r\n@media (max-width: 1000px) {\r\n  .footer-2-newsletter { flex-direction: column; text-align: center; }\r\n  .footer-2-newsletter-form { max-width: 100%; width: 100%; }\r\n  .footer-2-grid { grid-template-columns: 1fr 1fr; gap: 40px; }\r\n}\r\n@media (max-width: 600px) {\r\n  .footer-2 { padding: 40px 20px 25px; }\r\n  .footer-2-newsletter { padding: 30px 20px; }\r\n  .footer-2-grid { grid-template-columns: 1fr; }\r\n  .footer-2-bottom { flex-direction: column; text-align: center; }\r\n}', NULL, NULL, 'Footer', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-01 20:47:38', '2026-06-04 22:11:17'),
