ion: none;\r\n}\r\n.footer-3-social a:hover {\r\n  background: #C9A84C;\r\n  color: #0a0a0a;\r\n  transform: translateY(-3px);\r\n}\r\n.footer-3-bottom {\r\n  background: rgba(0,0,0,0.4);\r\n  padding: 20px 40px;\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: 15px;\r\n}\r\n.footer-3-bottom p {\r\n  color: rgba(255,255,255,0.5);\r\n  font-size: 12px;\r\n}\r\n.footer-3-bottom-links {\r\n  display: flex;\r\n  gap: 25px;\r\n}\r\n.footer-3-bottom-links a {\r\n  color: rgba(255,255,255,0.5);\r\n  text-decoration: none;\r\n  font-size: 12px;\r\n  transition: color 0.3s ease;\r\n}\r\n.footer-3-bottom-links a:hover {\r\n  color: #C9A84C;\r\n}\r\n@media (max-width: 1000px) {\r\n  .footer-3-stats { grid-template-columns: repeat(2, 1fr); gap: 20px; }\r\n  .footer-3-grid { grid-template-columns: 1fr 1fr; gap: 40px; }\r\n}\r\n@media (max-width: 600px) {\r\n  .footer-3-top { padding: 30px 20px; }\r\n  .footer-3-main { padding: 40px 20px 25px; }\r\n  .footer-3-bottom { padding: 20px; flex-direction: column; text-align: center; }\r\n  .footer-3-stats { grid-template-columns: 1fr; }\r\n  .footer-3-grid { grid-template-columns: 1fr; }\r\n}', NULL, NULL, 'Footer', 'General', '[]', 1, 1, NULL, NULL, 1, 0, 0, 0, 1, '2026-06-01 20:48:52', '2026-06-04 22:11:12');
INSERT INTO `blocks` (`id`, `categorie_id`, `name`, `slug`, `description`, `thumbnail`, `icon`, `html_content`, `css_content`, `js_content`, `section_id`, `category`, `website_type`, `tags`, `is_responsive`, `is_free`, `width`, `height`, `usage_count`, `views_count`, `rating`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(158, NULL, 'ANNOUNCEMENT BAR', 'announcement-bar', NULL, NULL, 'fa-cube', '<div id=\"announcement-bar\">\r\n  <div class=\"announcement-inner\">\r\n    <span class=\"announcement-text\"><i class=\"fas fa-clock\"></i> Ouvert tous les jours &nbsp;|&nbsp; 11h00 – 23h00 &nbsp;|&nbsp; Réservez dès maintenant</span>\r\n    <a href=\"tel:+33123456789\" class=\"announcement-cta\"><i class=\"fas fa-phone\"></i> Appeler maintenant</a>\r\n  </div>\r\n</div>', '#announcement-bar {\r\n  background: #1E1E1E;\r\n  color: rgba(255,255,255,0.85);\r\n  font-size: 0.82rem;\r\n  font-weight: 500;\r\n  letter-spacing: 0.04em;\r\n  padding: 0.55rem 1rem;\r\n  position: relative;\r\n  z-index: 1000;\r\n}\r\n.announcement-inner {\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 1.5rem;\r\n  flex-wrap: wrap;\r\n}\r\n.announcement-text {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n}\r\n.announcement-text i {\r\n  color: #C89B3C;\r\n}\r\n.announcement-cta {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.4rem;\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  padding: 0.3rem 0.9rem;\r\n  border-radius: 50px;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  text-decoration: none;\r\n}\r\n.announcement-cta:hover {\r\n  background: #d9b560;\r\n}\r\n@media (max-width: 600px) {\r\n  .announcement-inner { flex-direction: column; gap: 0.8rem; }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-02 21:49:33', '2026-06-03 11:47:03'),
(159, NULL, 'HEADER / NAVIGATION', 'header-navigation', NULL, NULL, 'fa-cube', '<header class=\"site-header\" id=\"header\">\r\n  <div class=\"header-inner\">\r\n    <a href=\"#home\" class=\"logo\">\r\n      <span class=\"logo-mark\">M</span>\r\n      <div class=\"logo-text\">\r\n        <span class=\"logo-name\">Maison Dorée</span>\r\n        <span class=\"logo-tagline\">Fine Dining</span>\r\n      </div>\r\n    </a>\r\n    <nav class=\"main-nav\">\r\n      <ul class=\"nav-list\">\r\n        <li><a href=\"#home\" class=\"nav-link\">Accueil</a></li>\r\n        <li><a href=\"#about\" class=\"nav-link\">À Propos</a></li>\r\n        <li><a href=\"#menu\" class=\"nav-link\">Menu</a></li>\r\n        <li><a href=\"#gallery\" class=\"nav-link\">Galerie</a></li>\r\n        <li><a href=\"#services\" class=\"nav-link\">Services</a></li>\r\n        <li><a href=\"#testimonials\" class=\"nav-link\">Avis</a></li>\r\n        <li><a href=\"#blog\" class=\"nav-link\">Blog</a></li>\r\n        <li><a href=\"#contact\" class=\"nav-link\">Contact</a></li>\r\n      </ul>\r\n    </nav>\r\n    <a href=\"#reservation\" class=\"btn btn-gold header-cta\">Réserver une Table</a>\r\n    <button class=\"hamburger\" id=\"hamburger\"><span></span><span></span><span></span></button>\r\n  </div>\r\n  <div class=\"mobile-menu\" id=\"mobile-menu\">\r\n    <ul class=\"mobile-nav-list\">\r\n      <li><a href=\"#home\" class=\"mobile-nav-link\">Accueil</a></li>\r\n      <li><a href=\"#about\" class=\"mobile-nav-link\">À Propos</a></li>\r\n      <li><a href=\"#menu\" class=\"mobile-nav-link\">Menu</a></li>\r\n      <li><a href=\"#gallery\" class=\"mobile-nav-link\">Galerie</a></li>\r\n      <li><a href=\"#services\" class=\"mobile-nav-link\">Services</a></li>\r\n      <li><a href=\"#testimonials\" class=\"mobile-nav-link\">Avis</a></li>\r\n      <li><a href=\"#blog\" class=\"mobile-nav-link\">Blog</a></li>\r\n      <li><a href=\"#contact\" class=\"mobile-nav-link\">Contact</a></li>\r\n      <li><a href=\"#reservation\" class=\"btn btn-gold mobile-cta\">Réserver une Table</a></li>\r\n    </ul>\r\n  </div>\r\n</header>\r\n\r\n<script>\r\n(function(){\r\n  const header = document.getElementById(\'header\');\r\n  const hamburger = document.getElementById(\'hamburger\');\r\n  const mobileMenu = document.getElementById(\'mobile-menu\');\r\n  window.addEventListener(\'scroll\', function() {\r\n    header.classList.toggle(\'scrolled\', window.scrollY > 50);\r\n  });\r\n  if(hamburger) {\r\n    hamburger.addEventListener(\'click\', function() {\r\n      const open = mobileMenu.classList.toggle(\'open\');\r\n      hamburger.classList.toggle(\'open\', open);\r\n      document.body.style.overflow = open ? \'hidden\' : \'\';\r\n    });\r\n  }\r\n  if(mobileMenu) {\r\n    document.querySelectorAll(\'.mobile-nav-link, .mobile-cta\').forEach(function(link) {\r\n      link.addEventListener(\'click\', function() {\r\n        mobileMenu.classList.remove(\'open\');\r\n        hamburger.classList.remove(\'open\');\r\n        document.body.style.overflow = \'\';\r\n      });\r\n    });\r\n  }\r\n})();\r\n</script>', '.site-header {\r\n  position: sticky;\r\n  top: 0;\r\n  z-index: 999;\r\n  background: rgba(255,255,255,0.97);\r\n  backdrop-filter: blur(12px);\r\n  border-bottom: 1px solid #e8e0d0;\r\n  transition: box-shadow 0.3s;\r\n}\r\n.site-header.scrolled {\r\n  box-shadow: 0 6px 30px rgba(0,0,0,0.10);\r\n}\r\n.header-inner {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  height: 80px;\r\n  gap: 1.5rem;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n.logo {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.75rem;\r\n  text-decoration: none;\r\n}\r\n.logo-mark {\r\n  width: 44px;\r\n  height: 44px;\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  border-radius: 50%;\r\n  display: grid;\r\n  place-items: center;\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.3rem;\r\n  font-weight: 700;\r\n}\r\n.logo-text {\r\n  display: flex;\r\n  flex-direction: column;\r\n  line-height: 1.2;\r\n}\r\n.logo-name {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.1rem;\r\n  font-weight: 700;\r\n  color: #1E1E1E;\r\n}\r\n.logo-tagline {\r\n  font-size: 0.65rem;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n}\r\n.main-nav {\r\n  flex: 1;\r\n  display: flex;\r\n  justify-content: center;\r\n}\r\n.nav-list {\r\n  display: flex;\r\n  gap: 0.15rem;\r\n  list-style: none;\r\n}\r\n.nav-link {\r\n  padding: 0.45rem 0.8rem;\r\n  font-size: 0.87rem;\r\n  font-weight: 500;\r\n  color: #333;\r\n  border-radius: 8px;\r\n  transition: all 0.35s ease;\r\n  text-decoration: none;\r\n  position: relative;\r\n}\r\n.nav-link::after {\r\n  content: \'\';\r\n  position: absolute;\r\n  bottom: 2px;\r\n  left: 50%;\r\n  right: 50%;\r\n  height: 2px;\r\n  background: #C89B3C;\r\n  transition: all 0.35s ease;\r\n}\r\n.nav-link:hover {\r\n  color: #C89B3C;\r\n}\r\n.nav-link:hover::after {\r\n  left: 0.8rem;\r\n  right: 0.8rem;\r\n}\r\n.btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n  padding: 0.85rem 2rem;\r\n  border-radius: 50px;\r\n  font-size: 0.9rem;\r\n  font-weight: 600;\r\n  transition: all 0.35s ease;\r\n  text-decoration: none;\r\n}\r\n.btn-gold {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  box-shadow: 0 4px 20px rgba(200,155,60,0.3);\r\n}\r\n.btn-gold:hover {\r\n  background: #a07820;\r\n  transform: translateY(-2px);\r\n}\r\n.header-cta {\r\n  padding: 0.65rem 1.4rem;\r\n  font-size: 0.85rem;\r\n  flex-shrink: 0;\r\n}\r\n.hamburger {\r\n  display: none;\r\n  flex-direction: column;\r\n  gap: 5px;\r\n  padding: 4px;\r\n}\r\n.hamburger span {\r\n  display: block;\r\n  width: 26px;\r\n  height: 2px;\r\n  background: #1E1E1E;\r\n  border-radius: 2px;\r\n  transition: all 0.35s ease;\r\n}\r\n.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }\r\n.hamburger.open span:nth-child(2) { opacity: 0; }\r\n.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }\r\n.mobile-menu {\r\n  display: none;\r\n  flex-direction: column;\r\n  background: #fff;\r\n  border-top: 1px solid #e8e0d0;\r\n  padding: 1rem 24px 1.5rem;\r\n  box-shadow: 0 6px 30px rgba(0,0,0,0.10);\r\n}\r\n.mobile-menu.open { display: flex; }\r\n.mobile-nav-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 0.25rem;\r\n  list-style: none;\r\n}\r\n.mobile-nav-link {\r\n  display: block;\r\n  padding: 0.7rem 0;\r\n  font-size: 1rem;\r\n  font-weight: 500;\r\n  color: #333;\r\n  border-bottom: 1px solid #e8e0d0;\r\n  text-decoration: none;\r\n}\r\n.mobile-nav-link:hover { color: #C89B3C; }\r\n.mobile-cta { margin-top: 1rem; text-align: center; }\r\n\r\n@media (max-width: 1024px) {\r\n  .main-nav { display: none; }\r\n  .header-cta { display: none; }\r\n  .hamburger { display: flex; }\r\n}', NULL, NULL, 'Header', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-02 21:50:48', '2026-06-04 22:08:44'),
(160, NULL, 'Section Héro', 'section-hero', NULL, NULL, 'fa-cube', '<section class=\"hero-section\" id=\"home\">\r\n  <div class=\"hero-bg\">\r\n    <img src=\"https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=1920&q=80\" alt=\"Intérieur du restaurant\" class=\"hero-bg-img\">\r\n    <div class=\"hero-overlay\"></div>\r\n  </div>\r\n  <div class=\"hero-content\">\r\n    <div class=\"hero-left\">\r\n      <div class=\"hero-badge\"><i class=\"fas fa-star\"></i> Fine Dining Experience</div>\r\n      <h1 class=\"hero-title\">Découvrez des<br><em>Saveurs Exceptionnelles</em><br>Créées avec Passion</h1>\r\n      <p class=\"hero-subtitle\">Au cœur de Paris, Maison Dorée vous invite à un voyage culinaire d\'exception, où chaque plat raconte une histoire.</p>\r\n      <div class=\"hero-actions\">\r\n        <a href=\"#reservation\" class=\"btn btn-gold\"><i class=\"fas fa-calendar-check\"></i> Réserver une Table</a>\r\n        <a href=\"#menu\" class=\"btn btn-outline-light\"><i class=\"fas fa-utensils\"></i> Voir le Menu</a>\r\n      </div>\r\n    </div>\r\n    <div class=\"hero-right\">\r\n      <div class=\"hero-img-frame\">\r\n        <img src=\"https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=600&q=80\" alt=\"Plat signature\" class=\"hero-dish-img\">\r\n        <div class=\"hero-img-deco\"></div>\r\n      </div>\r\n      <div class=\"hero-stat hero-stat--1 float-card\"><span class=\"stat-number\">5000+</span><span class=\"stat-label\">Clients Satisfaits</span></div>\r\n      <div class=\"hero-stat hero-stat--2 float-card\"><span class=\"stat-number\">10+</span><span class=\"stat-label\">Années d\'Expérience</span></div>\r\n      <div class=\"hero-stat hero-stat--3 float-card\"><span class=\"stat-number\">50+</span><span class=\"stat-label\">Plats Signature</span></div>\r\n    </div>\r\n  </div>\r\n  <a href=\"#awards\" class=\"hero-scroll-cue\"><span class=\"scroll-line\"></span><i class=\"fas fa-chevron-down\"></i></a>\r\n</section>', '.hero-section {\r\n  position: relative;\r\n  min-height: 100svh;\r\n  display: flex;\r\n  align-items: center;\r\n  overflow: hidden;\r\n}\r\n.hero-bg {\r\n  position: absolute;\r\n  inset: 0;\r\n}\r\n.hero-bg-img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n  object-position: center;\r\n}\r\n.hero-overlay {\r\n  position: absolute;\r\n  inset: 0;\r\n  background: linear-gradient(135deg, rgba(20,15,5,0.82) 0%, rgba(30,22,8,0.5) 60%, rgba(0,0,0,0.3) 100%);\r\n}\r\n.hero-content {\r\n  position: relative;\r\n  z-index: 2;\r\n  display: grid;\r\n  grid-template-columns: 1fr 1fr;\r\n  gap: 3rem;\r\n  align-items: center;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n  width: 100%;\r\n}\r\n.hero-left {\r\n  padding: 2rem 0;\r\n}\r\n.hero-badge {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n  background: rgba(200,155,60,0.15);\r\n  border: 1px solid rgba(200,155,60,0.5);\r\n  color: #d9b560;\r\n  padding: 0.45rem 1rem;\r\n  border-radius: 50px;\r\n  font-size: 0.8rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.1em;\r\n  text-transform: uppercase;\r\n  margin-bottom: 1.5rem;\r\n}\r\n.hero-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(2.2rem, 4.5vw, 3.8rem);\r\n  font-weight: 600;\r\n  color: #fff;\r\n  line-height: 1.2;\r\n  margin-bottom: 1.5rem;\r\n}\r\n.hero-title em {\r\n  font-style: italic;\r\n  color: #d9b560;\r\n}\r\n.hero-subtitle {\r\n  font-size: 1.05rem;\r\n  color: rgba(255,255,255,0.75);\r\n  max-width: 500px;\r\n  margin-bottom: 2.5rem;\r\n  line-height: 1.75;\r\n}\r\n.hero-actions {\r\n  display: flex;\r\n  gap: 1rem;\r\n  flex-wrap: wrap;\r\n}\r\n.btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n  padding: 0.85rem 2rem;\r\n  border-radius: 50px;\r\n  font-size: 0.9rem;\r\n  font-weight: 600;\r\n  transition: all 0.35s ease;\r\n  text-decoration: none;\r\n}\r\n.btn-gold {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  box-shadow: 0 4px 20px rgba(200,155,60,0.3);\r\n}\r\n.btn-gold:hover {\r\n  background: #a07820;\r\n  transform: translateY(-2px);\r\n}\r\n.btn-outline-light {\r\n  background: transparent;\r\n  color: #fff;\r\n  border: 2px solid rgba(255,255,255,0.55);\r\n}\r\n.btn-outline-light:hover {\r\n  background: rgba(255,255,255,0.12);\r\n  border-color: #fff;\r\n}\r\n.hero-right {\r\n  position: relative;\r\n}\r\n.hero-img-frame {\r\n  position: relative;\r\n  border-radius: 24px;\r\n  overflow: hidden;\r\n  box-shadow: 0 30px 80px rgba(0,0,0,0.5);\r\n  aspect-ratio: 4/5;\r\n  max-width: 420px;\r\n  margin-left: auto;\r\n}\r\n.hero-dish-img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n}\r\n.hero-img-deco {\r\n  position: absolute;\r\n  inset: 0;\r\n  border-radius: 24px;\r\n  border: 2px solid rgba(200,155,60,0.3);\r\n  transform: translate(12px, 12px);\r\n  pointer-events: none;\r\n}\r\n.float-card {\r\n  position: absolute;\r\n  background: rgba(255,255,255,0.95);\r\n  backdrop-filter: blur(10px);\r\n  border-radius: 16px;\r\n  padding: 0.9rem 1.3rem;\r\n  text-align: center;\r\n  box-shadow: 0 12px 40px rgba(0,0,0,0.2);\r\n  animation: floatAnim 4s ease-in-out infinite;\r\n}\r\n.hero-stat--1 {\r\n  bottom: 20%;\r\n  left: -1.5rem;\r\n  animation-delay: 0s;\r\n}\r\n.hero-stat--2 {\r\n  top: 12%;\r\n  right: -1rem;\r\n  animation-delay: 1.3s;\r\n}\r\n.hero-stat--3 {\r\n  bottom: 3%;\r\n  right: 8%;\r\n  animation-delay: 2.5s;\r\n}\r\n@keyframes floatAnim {\r\n  0%, 100% { transform: translateY(0); }\r\n  50% { transform: translateY(-10px); }\r\n}\r\n.stat-number {\r\n  display: block;\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.5rem;\r\n  font-weight: 700;\r\n  color: #C89B3C;\r\n}\r\n.stat-label {\r\n  display: block;\r\n  font-size: 0.7rem;\r\n  color: #666;\r\n  font-weight: 500;\r\n  white-space: nowrap;\r\n}\r\n.hero-scroll-cue {\r\n  position: absolute;\r\n  bottom: 2rem;\r\n  left: 50%;\r\n  transform: translateX(-50%);\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  gap: 0.4rem;\r\n  color: rgba(255,255,255,0.5);\r\n  font-size: 0.75rem;\r\n  animation: bounce 2s ease infinite;\r\n}\r\n.scroll-line {\r\n  width: 1px;\r\n  height: 36px;\r\n  background: linear-gradient(to bottom, transparent, rgba(255,255,255,0.5));\r\n}\r\n@keyframes bounce {\r\n  0%, 100% { transform: translateX(-50%) translateY(0); }\r\n  50% { transform: translateX(-50%) translateY(6px); }\r\n}\r\n@media (max-width: 1024px) {\r\n  .hero-content { grid-template-columns: 1fr; text-align: center; }\r\n  .hero-right { display: none; }\r\n  .hero-subtitle { max-width: 600px; margin-inline: auto; }\r\n  .hero-actions { justify-content: center; }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 2, 1, 0, 0, 1, '2026-06-02 21:52:24', '2026-07-25 19:51:53'),
(161, NULL, 'About', 'about', NULL, NULL, 'fa-cube', '<section class=\"about-section\" id=\"about\">\r\n  <div class=\"about-grid\">\r\n    <div class=\"about-images\">\r\n      <div class=\"about-img-main\"><img src=\"https://images.unsplash.com/photo-1550966871-3ed3cbe818b0?w=600&q=80\" alt=\"Salle principale\"></div>\r\n      <div class=\"about-img-secondary\"><img src=\"https://images.unsplash.com/photo-1424847651672-bf20a4b0982b?w=300&q=80\" alt=\"Chef en cuisine\"></div>\r\n      <div class=\"about-img-badge\"><span>Depuis</span><strong>2014</strong></div>\r\n    </div>\r\n    <div class=\"about-content\">\r\n      <span class=\"section-tag\">Notre Histoire</span>\r\n      <h2 class=\"section-title\">Une Passion Transmise,<br><em>Une Cuisine Sublimée</em></h2>\r\n      <p class=\"about-text\">Fondée en 2014 par le Chef Julien Moreau, Maison Dorée est née d\'une vision : offrir à chaque convive une expérience gastronomique inoubliable, ancrée dans les traditions culinaires françaises.</p>\r\n      <p class=\"about-text\">Notre philosophie repose sur trois piliers : des ingrédients d\'exception sourcés auprès de producteurs locaux, une technique maîtrisée avec minutie, et une hospitalité sincère.</p>\r\n      <div class=\"about-pillars\">\r\n        <div class=\"pillar\"><i class=\"fas fa-seedling pillar-icon\"></i><div><strong>Notre Mission</strong><p>Sublimer les produits du terroir français dans chaque assiette.</p></div></div>\r\n        <div class=\"pillar\"><i class=\"fas fa-eye pillar-icon\"></i><div><strong>Notre Vision</strong><p>Être la référence de la gastronomie parisienne d\'exception.</p></div></div>\r\n      </div>\r\n      <a href=\"#chef\" class=\"btn btn-gold mt-4\">Rencontrer le Chef <i class=\"fas fa-arrow-right\"></i></a>\r\n    </div>\r\n  </div>\r\n</section>', '.about-section {\r\n  padding: 6rem 0;\r\n  background: #fff;\r\n}\r\n.about-grid {\r\n  display: grid;\r\n  grid-template-columns: 1fr 1fr;\r\n  gap: 5rem;\r\n  align-items: center;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n.about-images {\r\n  position: relative;\r\n}\r\n.about-img-main {\r\n  border-radius: 24px;\r\n  overflow: hidden;\r\n  aspect-ratio: 4/5;\r\n  box-shadow: 0 16px 60px rgba(0,0,0,0.14);\r\n}\r\n.about-img-main img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n}\r\n.about-img-secondary {\r\n  position: absolute;\r\n  bottom: -2.5rem;\r\n  right: -2.5rem;\r\n  width: 52%;\r\n  border-radius: 16px;\r\n  overflow: hidden;\r\n  border: 4px solid #fff;\r\n  box-shadow: 0 6px 30px rgba(0,0,0,0.10);\r\n  aspect-ratio: 1;\r\n}\r\n.about-img-secondary img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n}\r\n.about-img-badge {\r\n  position: absolute;\r\n  top: 2rem;\r\n  left: -1.5rem;\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  width: 80px;\r\n  height: 80px;\r\n  border-radius: 50%;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-size: 0.7rem;\r\n  font-weight: 600;\r\n  box-shadow: 0 6px 30px rgba(0,0,0,0.10);\r\n}\r\n.about-img-badge strong {\r\n  font-size: 1.4rem;\r\n  font-family: \'Playfair Display\', serif;\r\n  line-height: 1;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.section-title em {\r\n  font-style: italic;\r\n  color: #C89B3C;\r\n}\r\n.about-text {\r\n  color: #666;\r\n  margin-bottom: 1.25rem;\r\n  line-height: 1.8;\r\n}\r\n.about-pillars {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 1rem;\r\n  margin-top: 2rem;\r\n}\r\n.pillar {\r\n  display: flex;\r\n  gap: 1rem;\r\n  align-items: flex-start;\r\n}\r\n.pillar-icon {\r\n  color: #C89B3C;\r\n  font-size: 1.1rem;\r\n  margin-top: 0.1rem;\r\n  flex-shrink: 0;\r\n}\r\n.pillar strong {\r\n  display: block;\r\n  font-size: 0.92rem;\r\n  margin-bottom: 0.2rem;\r\n  color: #1E1E1E;\r\n}\r\n.pillar p {\r\n  font-size: 0.88rem;\r\n  color: #666;\r\n  margin: 0;\r\n}\r\n.btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n  padding: 0.85rem 2rem;\r\n  border-radius: 50px;\r\n  font-size: 0.9rem;\r\n  font-weight: 600;\r\n  transition: all 0.35s ease;\r\n  text-decoration: none;\r\n}\r\n.btn-gold {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  box-shadow: 0 4px 20px rgba(200,155,60,0.3);\r\n}\r\n.btn-gold:hover {\r\n  background: #a07820;\r\n  transform: translateY(-2px);\r\n}\r\n.mt-4 { margin-top: 1.5rem; }\r\n@media (max-width: 1024px) {\r\n  .about-grid { grid-template-columns: 1fr; gap: 3rem; }\r\n  .about-images { max-width: 500px; margin-inline: auto; }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 2, 0, 0, 0, 1, '2026-06-02 21:53:58', '2026-06-03 12:59:00'),
(162, NULL, 'STATISTICS', 'statistics', NULL, NULL, 'fa-cube', '<section class=\"stats-section\" id=\"stats\">\r\n  <div class=\"stats-bg\">\r\n    <img src=\"https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?w=1920&q=80\" alt=\"\">\r\n    <div class=\"stats-overlay\"></div>\r\n  </div>\r\n  <div class=\"stats-grid\">\r\n    <div class=\"stat-item\"><span class=\"stat-counter\" id=\"stat1\">0</span><span class=\"stat-suffix\">+</span><p class=\"stat-desc\">Clients Servis</p></div>\r\n    <div class=\"stat-item\"><span class=\"stat-counter\" id=\"stat2\">0</span><span class=\"stat-suffix\">ans</span><p class=\"stat-desc\">d\'Expérience</p></div>\r\n    <div class=\"stat-item\"><span class=\"stat-counter\" id=\"stat3\">0</span><span class=\"stat-suffix\">+</span><p class=\"stat-desc\">Couverts par Jour</p></div>\r\n    <div class=\"stat-item\"><span class=\"stat-counter\" id=\"stat4\">0</span><span class=\"stat-suffix\">+</span><p class=\"stat-desc\">Événements Organisés</p></div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n(function(){\r\n  var counters = [\r\n    {el: document.getElementById(\'stat1\'), target: 12400},\r\n    {el: document.getElementById(\'stat2\'), target: 10},\r\n    {el: document.getElementById(\'stat3\'), target: 280},\r\n    {el: document.getElementById(\'stat4\'), target: 150}\r\n  ];\r\n  function easeOut(t) { return 1 - Math.pow(1 - t, 3); }\r\n  function animateCounter(counter, target) {\r\n    if(!counter) return;\r\n    var start = null;\r\n    var duration = 2200;\r\n    function step(timestamp) {\r\n      if(!start) start = timestamp;\r\n      var elapsed = timestamp - start;\r\n      var progress = Math.min(elapsed / duration, 1);\r\n      counter.textContent = Math.floor(easeOut(progress) * target).toLocaleString(\'fr-FR\');\r\n      if(progress < 1) requestAnimationFrame(step);\r\n    }\r\n    requestAnimationFrame(step);\r\n  }\r\n  var observer = new IntersectionObserver(function(entries) {\r\n    entries.forEach(function(entry) {\r\n      if(entry.isIntersecting) {\r\n        counters.forEach(function(c) { animateCounter(c.el, c.target); });\r\n        observer.disconnect();\r\n      }\r\n    });\r\n  }, {threshold: 0.5});\r\n  var section = document.getElementById(\'stats\');\r\n  if(section) observer.observe(section);\r\n})();\r\n</script>', '.stats-section {\r\n  padding: 5rem 0;\r\n  position: relative;\r\n  overflow: hidden;\r\n}\r\n.stats-bg {\r\n  position: absolute;\r\n  inset: 0;\r\n}\r\n.stats-bg img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n}\r\n.stats-overlay {\r\n  position: absolute;\r\n  inset: 0;\r\n  background: rgba(20,15,5,0.85);\r\n}\r\n.stats-grid {\r\n  position: relative;\r\n  z-index: 2;\r\n  display: grid;\r\n  grid-template-columns: repeat(4, 1fr);\r\n  gap: 2rem;\r\n  text-align: center;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n.stat-item {\r\n  color: #fff;\r\n}\r\n.stat-counter {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(2.5rem, 4vw, 3.5rem);\r\n  font-weight: 700;\r\n  color: #d9b560;\r\n}\r\n.stat-suffix {\r\n  font-size: 1.3rem;\r\n  font-weight: 400;\r\n  color: #d9b560;\r\n  margin-left: 0.15rem;\r\n}\r\n.stat-desc {\r\n  font-size: 0.88rem;\r\n  color: rgba(255,255,255,0.65);\r\n  margin-top: 0.4rem;\r\n  letter-spacing: 0.05em;\r\n}\r\n@media (max-width: 1024px) {\r\n  .stats-grid { grid-template-columns: repeat(2, 1fr); }\r\n}\r\n@media (max-width: 600px) {\r\n  .stats-grid { grid-template-columns: 1fr; }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 3, 0, 0, 0, 1, '2026-06-03 08:00:06', '2026-06-03 12:59:03'),
(163, NULL, 'WHY CHOOSE US', 'why-choose-us', NULL, NULL, 'fa-cube', '<section class=\"why-section\" id=\"why-us\">\r\n  <div class=\"container\" style=\"max-width:1200px;margin:0 auto;padding:0 24px\">\r\n    <div class=\"section-header text-center\">\r\n      <span class=\"section-tag\">Nos Atouts</span>\r\n      <h2 class=\"section-title\">Pourquoi Choisir<br><em>Maison Dorée ?</em></h2>\r\n    </div>\r\n    <div class=\"why-grid\">\r\n      <div class=\"why-card\"><div class=\"why-icon\"><i class=\"fas fa-carrot\"></i></div><h3>Ingrédients Frais</h3><p>Produits sélectionnés chaque matin auprès de producteurs locaux et bio certifiés.</p></div>\r\n      <div class=\"why-card\"><div class=\"why-icon\"><i class=\"fas fa-hat-chef\"></i></div><h3>Chefs Experts</h3><p>Une brigade d\'élite formée dans les plus grandes maisons étoilées de France.</p></div>\r\n      <div class=\"why-card\"><div class=\"why-icon\"><i class=\"fas fa-concierge-bell\"></i></div><h3>Service Raffiné</h3><p>Un service attentionné, discret et personnalisé pour une expérience sans faille.</p></div>\r\n      <div class=\"why-card\"><div class=\"why-icon\"><i class=\"fas fa-gem\"></i></div><h3>Cadre Premium</h3><p>Une décoration épurée et luxueuse, pensée pour sublimer chaque moment.</p></div>\r\n      <div class=\"why-card\"><div class=\"why-icon\"><i class=\"fas fa-award\"></i></div><h3>Qualité Reconnue</h3><p>Récompensé par les plus grandes guides gastronomiques année après année.</p></div>\r\n      <div class=\"why-card\"><div class=\"why-icon\"><i class=\"fas fa-users\"></i></div><h3>Événements Privés</h3><p>Espaces dédiés pour vos célébrations, séminaires et dîners d\'affaires.</p></div>\r\n    </div>\r\n  </div>\r\n</section>', '.why-section {\r\n  padding: 6rem 0;\r\n  background: #F8F8F8;\r\n}\r\n.section-header {\r\n  text-align: center;\r\n  margin-bottom: 3.5rem;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.section-title em {\r\n  font-style: italic;\r\n  color: #C89B3C;\r\n}\r\n.why-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(3, 1fr);\r\n  gap: 1.75rem;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n.why-card {\r\n  background: #fff;\r\n  border: 1px solid #e8e0d0;\r\n  border-radius: 16px;\r\n  padding: 2.5rem 2rem;\r\n  text-align: center;\r\n  transition: all 0.35s ease;\r\n  position: relative;\r\n  overflow: hidden;\r\n}\r\n.why-card::after {\r\n  content: \'\';\r\n  position: absolute;\r\n  bottom: 0;\r\n  left: 0;\r\n  right: 0;\r\n  height: 3px;\r\n  background: linear-gradient(90deg, #C89B3C, #d9b560);\r\n  transform: scaleX(0);\r\n  transform-origin: left;\r\n  transition: transform 0.4s ease;\r\n}\r\n.why-card:hover {\r\n  transform: translateY(-6px);\r\n  box-shadow: 0 6px 30px rgba(0,0,0,0.10);\r\n  border-color: transparent;\r\n}\r\n.why-card:hover::after {\r\n  transform: scaleX(1);\r\n}\r\n.why-icon {\r\n  width: 64px;\r\n  height: 64px;\r\n  background: linear-gradient(135deg, rgba(200,155,60,0.12), rgba(200,155,60,0.05));\r\n  border: 1px solid rgba(200,155,60,0.2);\r\n  border-radius: 8px;\r\n  display: grid;\r\n  place-items: center;\r\n  margin: 0 auto 1.5rem;\r\n  font-size: 1.4rem;\r\n  color: #C89B3C;\r\n  transition: all 0.35s ease;\r\n}\r\n.why-card:hover .why-icon {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  border-color: #C89B3C;\r\n}\r\n.why-card h3 {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.1rem;\r\n  color: #1E1E1E;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.why-card p {\r\n  font-size: 0.88rem;\r\n  color: #666;\r\n  line-height: 1.7;\r\n}\r\n@media (max-width: 1024px) {\r\n  .why-grid { grid-template-columns: repeat(2, 1fr); }\r\n}\r\n@media (max-width: 768px) {\r\n  .why-grid { grid-template-columns: 1fr; }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 3, 0, 0, 0, 1, '2026-06-03 08:01:21', '2026-06-03 12:59:06'),
(164, NULL, 'SIGNATURE DISHES', 'signature-dishes', NULL, NULL, 'fa-cube', '<section class=\"dishes-section\" id=\"dishes\">\r\n  <div class=\"container\" style=\"max-width:1200px;margin:0 auto;padding:0 24px\">\r\n    <div class=\"section-header text-center\">\r\n      <span class=\"section-tag\">Notre Cuisine</span>\r\n      <h2 class=\"section-title\">Plats Signature</h2>\r\n      <p class=\"section-subtitle\">Des créations qui célèbrent l\'art de la cuisine française</p>\r\n    </div>\r\n    <div class=\"dishes-grid\">\r\n      <div class=\"dish-card\"><div class=\"dish-img-wrap\"><img src=\"https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=400&q=80\" alt=\"Saint-Pierre\"><span class=\"dish-badge\">Signature</span></div><div class=\"dish-body\"><h3>Saint-Pierre en Croûte d\'Herbes</h3><p>Fenouil confit, émulsion au beurre blanc, caviar osciètre</p><div class=\"dish-footer\"><span class=\"dish-price\">€ 48</span><a href=\"#reservation\" class=\"dish-cta\">Réserver</a></div></div></div>\r\n      <div class=\"dish-card\"><div class=\"dish-img-wrap\"><img src=\"https://images.unsplash.com/photo-1529692236671-f1f6cf9683ba?w=400&q=80\" alt=\"Wagyu\"><span class=\"dish-badge dish-badge--hot\">Chef\'s Pick</span></div><div class=\"dish-body\"><h3>Côte de Bœuf Wagyu</h3><p>Gratin dauphinois, jus de veau truffe noire, légumes du marché</p><div class=\"dish-footer\"><span class=\"dish-price\">€ 78</span><a href=\"#reservation\" class=\"dish-cta\">Réserver</a></div></div></div>\r\n      <div class=\"dish-card\"><div class=\"dish-img-wrap\"><img src=\"https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=400&q=80\" alt=\"Homard\"><div class=\"dish-body\"><h3>Homard Breton Rôti</h3><p>Risotto à l\'encre de seiche, bisque de crustacés, huile de basilic</p><div class=\"dish-footer\"><span class=\"dish-price\">€ 65</span><a href=\"#reservation\" class=\"dish-cta\">Réserver</a></div></div></div></div>\r\n      <div class=\"dish-card\"><div class=\"dish-img-wrap\"><img src=\"https://images.unsplash.com/photo-1488477181946-6428a0291777?w=400&q=80\" alt=\"Soufflé\"><span class=\"dish-badge dish-badge--sweet\">Dessert</span></div><div class=\"dish-body\"><h3>Soufflé Chocolat Valrhona</h3><p>Glace vanille bourbon, éclats de cacao, coulis de fruits rouges</p><div class=\"dish-footer\"><span class=\"dish-price\">€ 24</span><a href=\"#reservation\" class=\"dish-cta\">Réserver</a></div></div></div>\r\n    </div>\r\n    <div class=\"text-center mt-8\"><a href=\"#menu\" class=\"btn-outline-dark btn\" style=\"display:inline-flex;align-items:center;gap:0.5rem;padding:0.85rem 2rem;border-radius:50px;font-size:0.9rem;font-weight:600;\">Voir la Carte Complète <i class=\"fas fa-arrow-right\"></i></a></div>\r\n  </div>\r\n</section>', '.dishes-section {\r\n  padding: 6rem 0;\r\n  background: #fff;\r\n}\r\n.section-header {\r\n  text-align: center;\r\n  margin-bottom: 3.5rem;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.section-subtitle {\r\n  font-size: 1.05rem;\r\n  color: #666;\r\n  max-width: 600px;\r\n  margin: 0 auto;\r\n}\r\n.dishes-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(4, 1fr);\r\n  gap: 1.5rem;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n.dish-card {\r\n  background: #fff;\r\n  border: 1px solid #e8e0d0;\r\n  border-radius: 16px;\r\n  overflow: hidden;\r\n  transition: all 0.35s ease;\r\n}\r\n.dish-card:hover {\r\n  transform: translateY(-8px);\r\n  box-shadow: 0 16px 60px rgba(0,0,0,0.14);\r\n}\r\n.dish-img-wrap {\r\n  position: relative;\r\n  aspect-ratio: 4/3;\r\n  overflow: hidden;\r\n}\r\n.dish-img-wrap img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n  transition: transform 0.5s ease;\r\n}\r\n.dish-card:hover .dish-img-wrap img {\r\n  transform: scale(1.08);\r\n}\r\n.dish-badge {\r\n  position: absolute;\r\n  top: 0.75rem;\r\n  left: 0.75rem;\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  font-size: 0.7rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.05em;\r\n  padding: 0.25rem 0.7rem;\r\n  border-radius: 50px;\r\n}\r\n.dish-badge--hot { background: #E74C3C; }\r\n.dish-badge--sweet { background: #9b59b6; }\r\n.dish-body { padding: 1.25rem; }\r\n.dish-body h3 {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1rem;\r\n  color: #1E1E1E;\r\n  margin-bottom: 0.5rem;\r\n}\r\n.dish-body p {\r\n  font-size: 0.82rem;\r\n  color: #666;\r\n  line-height: 1.6;\r\n  margin-bottom: 1rem;\r\n}\r\n.dish-footer {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n}\r\n.dish-price {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.1rem;\r\n  font-weight: 700;\r\n  color: #C89B3C;\r\n}\r\n.dish-cta {\r\n  font-size: 0.8rem;\r\n  font-weight: 600;\r\n  color: #C89B3C;\r\n  border: 1px solid #C89B3C;\r\n  padding: 0.35rem 0.9rem;\r\n  border-radius: 50px;\r\n  text-decoration: none;\r\n}\r\n.dish-cta:hover {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n}\r\n.btn-outline-dark {\r\n  background: transparent;\r\n  color: #1E1E1E;\r\n  border: 2px solid #1E1E1E;\r\n  text-decoration: none;\r\n}\r\n.btn-outline-dark:hover {\r\n  background: #1E1E1E;\r\n  color: #fff;\r\n}\r\n.text-center { text-align: center; }\r\n.mt-8 { margin-top: 3rem; }\r\n@media (max-width: 1200px) {\r\n  .dishes-grid { grid-template-columns: repeat(2, 1fr); }\r\n}\r\n@media (max-width: 768px) {\r\n  .dishes-grid { grid-template-columns: 1fr; }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 2, 0, 0, 0, 1, '2026-06-03 08:02:34', '2026-06-03 12:59:10'),
(165, NULL, 'INTERACTIVE MENU (TABS)', 'interactive-menu-tabs', NULL, NULL, 'fa-cube', '<section class=\"menu-section\" id=\"menu\">\r\n  <div class=\"container\" style=\"max-width:1200px;margin:0 auto;padding:0 24px\">\r\n    <div class=\"section-header text-center\">\r\n      <span class=\"section-tag\">La Carte</span>\r\n      <h2 class=\"section-title\">Notre Menu</h2>\r\n    </div>\r\n    <div class=\"menu-tabs\">\r\n      <button class=\"tab-btn active\" data-tab=\"starters\">Entrées</button>\r\n      <button class=\"tab-btn\" data-tab=\"mains\">Plats Principaux</button>\r\n      <button class=\"tab-btn\" data-tab=\"seafood\">Fruits de Mer</button>\r\n      <button class=\"tab-btn\" data-tab=\"desserts\">Desserts</button>\r\n      <button class=\"tab-btn\" data-tab=\"drinks\">Boissons</button>\r\n    </div>\r\n    <div class=\"menu-panel active\" id=\"tab-starters\">\r\n      <div class=\"menu-items\">\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Velouté de Châtaignes</h4><p>Crème fraîche, noisettes torréfiées, huile de truffe</p></div><span class=\"menu-price\">€ 18</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Foie Gras Poêlé</h4><p>Chutney de figues, brioche maison, réduction balsamique</p></div><span class=\"menu-price\">€ 32</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Tartare de Saumon</h4><p>Avocat, citron vert, sésame, vinaigrette ponzu</p></div><span class=\"menu-price\">€ 22</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Burrata Truffée</h4><p>Tomates confites, pistou de roquette, truffe noire</p></div><span class=\"menu-price\">€ 26</span></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"menu-panel\" id=\"tab-mains\">\r\n      <div class=\"menu-items\">\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Magret de Canard Laqué</h4><p>Pommes sarladaises, jus aux cerises, purée de betterave</p></div><span class=\"menu-price\">€ 42</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Pigeon Rôti en Cocotte</h4><p>Chou farci, lentilles du Puy, jus corsé</p></div><span class=\"menu-price\">€ 52</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Noix de Veau Poêlée</h4><p>Morilles, asperges vertes, sauce crémée à l\'estragon</p></div><span class=\"menu-price\">€ 46</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Agneau de Lait Confit</h4><p>Tian de légumes provençaux, jus d\'agneau au romarin</p></div><span class=\"menu-price\">€ 54</span></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"menu-panel\" id=\"tab-seafood\">\r\n      <div class=\"menu-items\">\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Sole Meunière Classique</h4><p>Beurre noisette, câpres, citron, persil plat</p></div><span class=\"menu-price\">€ 58</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Saint-Jacques Poêlées</h4><p>Chou-fleur, roe de cabillaud, émulsion citron</p></div><span class=\"menu-price\">€ 44</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Turbot en Croûte de Sel</h4><p>Hollandaise aux herbes, légumes de saison</p></div><span class=\"menu-price\">€ 68</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Plateau de Fruits de Mer</h4><p>Huîtres, langoustines, crevettes, bulots, accompagnements</p></div><span class=\"menu-price\">€ 85</span></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"menu-panel\" id=\"tab-desserts\">\r\n      <div class=\"menu-items\">\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Paris-Brest Revisité</h4><p>Praliné noisette, chantilly légère, éclats de pralin</p></div><span class=\"menu-price\">€ 18</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Mille-feuille Vanille</h4><p>Feuilletage caramélisé, crème diplomate, caramel beurre salé</p></div><span class=\"menu-price\">€ 16</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Tarte Citron Meringuée</h4><p>Curd citron yuzu, meringue italienne, sorbet basilic</p></div><span class=\"menu-price\">€ 16</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Assiette de Fromages</h4><p>Sélection affinée, confiture de figues, noix, pain de campagne</p></div><span class=\"menu-price\">€ 22</span></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"menu-panel\" id=\"tab-drinks\">\r\n      <div class=\"menu-items\">\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Champagne Ruinart Blanc de Blancs</h4><p>Brut, notes de noisette et d\'agrumes — 75cl</p></div><span class=\"menu-price\">€ 110</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Bourgogne Pinot Noir</h4><p>Domaine Leroy, Chambolle-Musigny 2020 — 75cl</p></div><span class=\"menu-price\">€ 145</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Cocktail Maison Dorée</h4><p>Cognac, miel de fleurs, gingembre, citron, fumée de bois</p></div><span class=\"menu-price\">€ 22</span></div>\r\n        <div class=\"menu-item\"><div class=\"menu-item-info\"><h4>Eau Minérale Premium</h4><p>Evian ou San Pellegrino — 75cl</p></div><span class=\"menu-price\">€ 8</span></div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n(function(){\r\n  var tabs = document.querySelectorAll(\'.tab-btn\');\r\n  var panels = document.querySelectorAll(\'.menu-panel\');\r\n  tabs.forEach(function(btn) {\r\n    btn.addEventListener(\'click\', function() {\r\n      tabs.forEach(function(t) { t.classList.remove(\'active\'); });\r\n      panels.forEach(function(p) { p.classList.remove(\'active\'); });\r\n      btn.classList.add(\'active\');\r\n      var targetId = \'tab-\' + btn.getAttribute(\'data-tab\');\r\n      var target = document.getElementById(targetId);\r\n      if(target) target.classList.add(\'active\');\r\n    });\r\n  });\r\n})();\r\n</script>', '.menu-section {\r\n  padding: 6rem 0;\r\n  background: #F8F8F8;\r\n}\r\n.section-header {\r\n  text-align: center;\r\n  margin-bottom: 3.5rem;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.menu-tabs {\r\n  display: flex;\r\n  justify-content: center;\r\n  gap: 0.5rem;\r\n  flex-wrap: wrap;\r\n  margin-bottom: 2.5rem;\r\n}\r\n.tab-btn {\r\n  padding: 0.65rem 1.4rem;\r\n  border-radius: 50px;\r\n  font-size: 0.88rem;\r\n  font-weight: 600;\r\n  color: #666;\r\n  border: 1px solid #e8e0d0;\r\n  background: #fff;\r\n  transition: all 0.35s ease;\r\n  cursor: pointer;\r\n}\r\n.tab-btn:hover {\r\n  color: #C89B3C;\r\n  border-color: #C89B3C;\r\n}\r\n.tab-btn.active {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  border-color: #C89B3C;\r\n}\r\n.menu-panel {\r\n  display: none;\r\n}\r\n.menu-panel.active {\r\n  display: block;\r\n}\r\n.menu-items {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 0;\r\n  max-width: 800px;\r\n  margin: 0 auto;\r\n}\r\n.menu-item {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 1.5rem;\r\n  padding: 1.25rem 0;\r\n  border-bottom: 1px dashed #e8e0d0;\r\n  transition: all 0.35s ease;\r\n}\r\n.menu-item:last-child {\r\n  border-bottom: none;\r\n}\r\n.menu-item:hover {\r\n  padding-left: 0.5rem;\r\n}\r\n.menu-item-info h4 {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.02rem;\r\n  color: #1E1E1E;\r\n  margin-bottom: 0.2rem;\r\n}\r\n.menu-item-info p {\r\n  font-size: 0.82rem;\r\n  color: #999;\r\n}\r\n.menu-price {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.05rem;\r\n  font-weight: 700;\r\n  color: #C89B3C;\r\n  white-space: nowrap;\r\n  flex-shrink: 0;\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 2, 1, 0, 0, 1, '2026-06-03 09:56:57', '2026-06-03 12:59:16'),
(166, NULL, 'CHEF', 'chef', NULL, NULL, 'fa-cube', '<section class=\"chef-section\" id=\"chef\">\r\n  <div class=\"chef-grid\">\r\n    <div class=\"chef-image\">\r\n      <img src=\"https://images.unsplash.com/photo-1577219491135-ce391730fb2c?w=600&q=80\" alt=\"Chef Julien Moreau\">\r\n      <div class=\"chef-signature\"><span>Julien Moreau</span></div>\r\n    </div>\r\n    <div class=\"chef-content\">\r\n      <span class=\"section-tag\">Notre Chef</span>\r\n      <h2 class=\"section-title\">Julien Moreau,<br><em>L\'Âme de la Maison</em></h2>\r\n      <p class=\"about-text\">Formé auprès d\'Alain Ducasse et Joël Robuchon, le Chef Julien Moreau apporte à Maison Dorée plus de 20 ans d\'expérience dans les plus grands palaces parisiens. Sa cuisine, profondément ancrée dans la tradition française, s\'épanouit à travers des créations audacieuses qui surprennent et émeuvent.</p>\r\n      <div class=\"chef-awards\">\r\n        <div class=\"chef-award\"><i class=\"fas fa-star\"></i><span>Étoilé Michelin 2023</span></div>\r\n        <div class=\"chef-award\"><i class=\"fas fa-trophy\"></i><span>Chef de l\'Année 2022</span></div>\r\n        <div class=\"chef-award\"><i class=\"fas fa-graduation-cap\"></i><span>MOF Cuisine</span></div>\r\n      </div>\r\n      <a href=\"#\" class=\"btn btn-gold mt-4\">Rencontrer l\'Équipe <i class=\"fas fa-arrow-right\"></i></a>\r\n    </div>\r\n  </div>\r\n</section>', '.chef-section {\r\n  padding: 6rem 0;\r\n  background: #fff;\r\n}\r\n.chef-grid {\r\n  display: grid;\r\n  grid-template-columns: 1fr 1fr;\r\n  gap: 5rem;\r\n  align-items: center;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n.chef-image {\r\n  position: relative;\r\n  border-radius: 24px;\r\n  overflow: hidden;\r\n  aspect-ratio: 3/4;\r\n  max-width: 460px;\r\n  box-shadow: 0 16px 60px rgba(0,0,0,0.14);\r\n}\r\n.chef-image img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n}\r\n.chef-signature {\r\n  position: absolute;\r\n  bottom: 0;\r\n  left: 0;\r\n  right: 0;\r\n  background: linear-gradient(to top, rgba(0,0,0,0.75), transparent);\r\n  padding: 2rem 1.5rem 1.25rem;\r\n}\r\n.chef-signature span {\r\n  font-family: \'Cormorant Garamond\', serif;\r\n  font-size: 1.6rem;\r\n  font-style: italic;\r\n  color: #d9b560;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.section-title em {\r\n  font-style: italic;\r\n  color: #C89B3C;\r\n}\r\n.about-text {\r\n  color: #666;\r\n  line-height: 1.85;\r\n  margin-bottom: 1.5rem;\r\n}\r\n.chef-awards {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 0.75rem;\r\n  margin-top: 2rem;\r\n}\r\n.chef-award {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.75rem;\r\n  font-size: 0.9rem;\r\n  color: #333;\r\n}\r\n.chef-award i {\r\n  color: #C89B3C;\r\n  width: 18px;\r\n}\r\n.btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n  padding: 0.85rem 2rem;\r\n  border-radius: 50px;\r\n  font-size: 0.9rem;\r\n  font-weight: 600;\r\n  transition: all 0.35s ease;\r\n  text-decoration: none;\r\n}\r\n.btn-gold {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  box-shadow: 0 4px 20px rgba(200,155,60,0.3);\r\n}\r\n.btn-gold:hover {\r\n  background: #a07820;\r\n  transform: translateY(-2px);\r\n}\r\n.mt-4 { margin-top: 1.5rem; }\r\n@media (max-width: 1024px) {\r\n  .chef-grid { grid-template-columns: 1fr; gap: 3rem; }\r\n  .chef-image { max-width: 400px; margin-inline: auto; }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 3, 2, 0, 0, 1, '2026-06-03 09:58:10', '2026-06-03 14:47:00');
INSERT INTO `blocks` (`id`, `categorie_id`, `name`, `slug`, `description`, `thumbnail`, `icon`, `html_content`, `css_content`, `js_content`, `section_id`, `category`, `website_type`, `tags`, `is_responsive`, `is_free`, `width`, `height`, `usage_count`, `views_count`, `rating`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(167, NULL, 'Gallerie', 'gallerie', NULL, NULL, 'fa-cube', '<section class=\"gallery-section\" id=\"gallery\">\r\n  <div class=\"container\" style=\"max-width:1200px;margin:0 auto;padding:0 24px\">\r\n    <div class=\"section-header text-center\">\r\n      <span class=\"section-tag\">Notre Univers</span>\r\n      <h2 class=\"section-title\">Galerie</h2>\r\n    </div>\r\n    <div class=\"masonry-grid\" id=\"galleryGrid\">\r\n      <!-- Image 1 - Salle principale -->\r\n      <div class=\"masonry-item\"><img src=\"https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=600&q=80\" alt=\"Salle principale\"><div class=\"masonry-overlay\"><span>Ambiance</span></div></div>\r\n      <!-- Image 2 - Plat gastronomique (tall) -->\r\n      <div class=\"masonry-item\"><img src=\"https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=600&q=80\" alt=\"Plat gastronomique\"><div class=\"masonry-overlay\"><span>Cuisine</span></div></div>\r\n      <!-- Image 3 - Chef en cuisine -->\r\n      <div class=\"masonry-item\"><img src=\"https://images.unsplash.com/photo-1577219491135-ce391730fb2c?w=600&q=80\" alt=\"Chef en cuisine\"><div class=\"masonry-overlay\"><span>Chef</span></div></div>\r\n      <!-- Image 4 - Cave à vins -->\r\n      <div class=\"masonry-item\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?w=600&q=80\" alt=\"Cave à vins\"><div class=\"masonry-overlay\"><span>Cave à Vins</span></div></div>\r\n      <!-- Image 5 - Table dressée (wide) -->\r\n      <div class=\"masonry-item\"><img src=\"https://images.unsplash.com/photo-1544148103-0773bf10d330?w=800&q=80\" alt=\"Table dressée\"><div class=\"masonry-overlay\"><span>Art de la Table</span></div></div>\r\n      <!-- Image 6 - Dessert exquis -->\r\n      <div class=\"masonry-item\"><img src=\"https://images.unsplash.com/photo-1551024601-bec78aea704b?w=600&q=80\" alt=\"Dessert exquis\"><div class=\"masonry-overlay\"><span>Pâtisserie</span></div></div>\r\n      <!-- Image 7 - Événement privé -->\r\n      <div class=\"masonry-item\"><img src=\"https://images.unsplash.com/photo-1519167758481-83d55bd4e2f4?w=600&q=80\" alt=\"Événement privé\"><div class=\"masonry-overlay\"><span>Événements</span></div></div>\r\n      <!-- Image 8 - Ingrédients frais -->\r\n      <div class=\"masonry-item\"><img src=\"https://images.unsplash.com/photo-1490645935967-10de6ba17061?w=600&q=80\" alt=\"Ingrédients frais\"><div class=\"masonry-overlay\"><span>Produits</span></div></div>\r\n      <!-- Image 9 - Terrasse extérieure -->\r\n      <div class=\"masonry-item\"><img src=\"https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?w=600&q=80\" alt=\"Terrasse\"><div class=\"masonry-overlay\"><span>Terrasse</span></div></div>\r\n      <!-- Image 10 - Cocktail signature -->\r\n      <div class=\"masonry-item\"><img src=\"https://images.unsplash.com/photo-1556679343-c7306c1973b7?w=600&q=80\" alt=\"Cocktail\"><div class=\"masonry-overlay\"><span>Bar</span></div></div>\r\n      <!-- Image 11 - Cuisine ouverte -->\r\n      <div class=\"masonry-item\"><img src=\"https://images.unsplash.com/photo-1556911220-bda9f7f7597e?w=600&q=80\" alt=\"Cuisine ouverte\"><div class=\"masonry-overlay\"><span>Cuisine</span></div></div>\r\n      <!-- Image 12 - Salon privé -->\r\n      <div class=\"masonry-item\"><img src=\"https://images.unsplash.com/photo-1591348277239-0f035e2b9ad4?w=600&q=80\" alt=\"Salon privé\"><div class=\"masonry-overlay\"><span>Salon Privé</span></div></div>\r\n    </div>\r\n  </div>\r\n  <div class=\"lightbox\" id=\"lightbox\">\r\n    <button class=\"lightbox-close\" id=\"lightbox-close\"><i class=\"fas fa-times\"></i></button>\r\n    <button class=\"lightbox-prev\" id=\"lightbox-prev\"><i class=\"fas fa-chevron-left\"></i></button>\r\n    <div class=\"lightbox-content\"><img id=\"lightbox-img\" src=\"\" alt=\"\"></div>\r\n    <button class=\"lightbox-next\" id=\"lightbox-next\"><i class=\"fas fa-chevron-right\"></i></button>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n(function(){\r\n  var lightbox = document.getElementById(\'lightbox\');\r\n  var imgEl = document.getElementById(\'lightbox-img\');\r\n  var closeBtn = document.getElementById(\'lightbox-close\');\r\n  var prevBtn = document.getElementById(\'lightbox-prev\');\r\n  var nextBtn = document.getElementById(\'lightbox-next\');\r\n  if(!lightbox) return;\r\n  var items = document.querySelectorAll(\'.masonry-item img\');\r\n  var current = 0;\r\n  function open(index) {\r\n    current = index;\r\n    imgEl.src = items[index].src;\r\n    imgEl.alt = items[index].alt;\r\n    lightbox.classList.add(\'open\');\r\n    document.body.style.overflow = \'hidden\';\r\n  }\r\n  function close() {\r\n    lightbox.classList.remove(\'open\');\r\n    document.body.style.overflow = \'\';\r\n  }\r\n  function prev() { open((current - 1 + items.length) % items.length); }\r\n  function next() { open((current + 1) % items.length); }\r\n  items.forEach(function(img, i) {\r\n    img.closest(\'.masonry-item\').addEventListener(\'click\', function() { open(i); });\r\n  });\r\n  closeBtn.addEventListener(\'click\', close);\r\n  prevBtn.addEventListener(\'click\', prev);\r\n  nextBtn.addEventListener(\'click\', next);\r\n  lightbox.addEventListener(\'click\', function(e) { if(e.target === lightbox) close(); });\r\n  document.addEventListener(\'keydown\', function(e) {\r\n    if(!lightbox.classList.contains(\'open\')) return;\r\n    if(e.key === \'Escape\') close();\r\n    if(e.key === \'ArrowLeft\') prev();\r\n    if(e.key === \'ArrowRight\') next();\r\n  });\r\n})();\r\n</script>', '.gallery-section {\r\n  padding: 6rem 0;\r\n  background: #F8F8F8;\r\n}\r\n.section-header {\r\n  text-align: center;\r\n  margin-bottom: 3.5rem;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.masonry-grid {\r\n  columns: 4;\r\n  column-gap: 1rem;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n.masonry-item {\r\n  break-inside: avoid;\r\n  margin-bottom: 1rem;\r\n  position: relative;\r\n  border-radius: 8px;\r\n  overflow: hidden;\r\n  cursor: pointer;\r\n}\r\n.masonry-item img {\r\n  width: 100%;\r\n  display: block;\r\n  transition: transform 0.5s ease;\r\n}\r\n.masonry-item:hover img {\r\n  transform: scale(1.06);\r\n}\r\n.masonry-overlay {\r\n  position: absolute;\r\n  inset: 0;\r\n  background: rgba(30,20,5,0);\r\n  display: flex;\r\n  align-items: flex-end;\r\n  padding: 1rem;\r\n  transition: all 0.35s ease;\r\n}\r\n.masonry-item:hover .masonry-overlay {\r\n  background: rgba(30,20,5,0.5);\r\n}\r\n.masonry-overlay span {\r\n  color: #fff;\r\n  font-size: 0.8rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.1em;\r\n  text-transform: uppercase;\r\n  opacity: 0;\r\n  transform: translateY(6px);\r\n  transition: all 0.35s ease;\r\n}\r\n.masonry-item:hover .masonry-overlay span {\r\n  opacity: 1;\r\n  transform: none;\r\n}\r\n.lightbox {\r\n  display: none;\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 9999;\r\n  background: rgba(0,0,0,0.95);\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n.lightbox.open {\r\n  display: flex;\r\n}\r\n.lightbox-content {\r\n  max-width: 90vw;\r\n  max-height: 90vh;\r\n}\r\n.lightbox-content img {\r\n  max-width: 90vw;\r\n  max-height: 80vh;\r\n  object-fit: contain;\r\n  border-radius: 8px;\r\n}\r\n.lightbox-close,\r\n.lightbox-prev,\r\n.lightbox-next {\r\n  position: absolute;\r\n  background: rgba(255,255,255,0.1);\r\n  color: #fff;\r\n  border: 1px solid rgba(255,255,255,0.2);\r\n  border-radius: 50%;\r\n  width: 48px;\r\n  height: 48px;\r\n  display: grid;\r\n  place-items: center;\r\n  font-size: 1.1rem;\r\n  transition: all 0.35s ease;\r\n  cursor: pointer;\r\n}\r\n.lightbox-close { top: 1.5rem; right: 1.5rem; }\r\n.lightbox-prev { left: 1.5rem; top: 50%; transform: translateY(-50%); }\r\n.lightbox-next { right: 1.5rem; top: 50%; transform: translateY(-50%); }\r\n.lightbox-close:hover, .lightbox-prev:hover, .lightbox-next:hover {\r\n  background: #C89B3C;\r\n  border-color: #C89B3C;\r\n}\r\n@media (max-width: 1200px) { .masonry-grid { columns: 3; } }\r\n@media (max-width: 768px) { .masonry-grid { columns: 2; } }\r\n@media (max-width: 480px) { .masonry-grid { columns: 1; } }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 3, 4, 0, 0, 1, '2026-06-03 10:53:43', '2026-07-25 19:51:35'),
(168, NULL, 'TESTIMONIALS (CAROUSEL)', 'testimonials-carousel', NULL, NULL, 'fa-cube', '<section class=\"testimonials-section\" id=\"testimonials\">\r\n  <div class=\"container\" style=\"max-width:1200px;margin:0 auto;padding:0 24px\">\r\n    <div class=\"section-header text-center\">\r\n      <span class=\"section-tag\">Avis Clients</span>\r\n      <h2 class=\"section-title\">Ce Que Disent<br><em>Nos Convives</em></h2>\r\n    </div>\r\n    <div class=\"testimonials-carousel\">\r\n      <div class=\"testimonials-track\" id=\"testimonialsTrack\">\r\n        <div class=\"testimonial-card\"><div class=\"testimonial-stars\">★★★★★</div><blockquote>Une expérience transcendante. Chaque plat était une œuvre d\'art, et le service a dépassé toutes mes attentes.</blockquote><div class=\"testimonial-author\"><img src=\"https://i.pravatar.cc/80?img=1\" alt=\"Sophie\"><div><strong>Sophie Martin</strong><span>Journaliste Gastronomique</span></div></div></div>\r\n        <div class=\"testimonial-card\"><div class=\"testimonial-stars\">★★★★★</div><blockquote>Nous avons célébré notre anniversaire ici et ce fut absolument magique. L\'ambiance, la cuisine, tout était parfait.</blockquote><div class=\"testimonial-author\"><img src=\"https://i.pravatar.cc/80?img=8\" alt=\"Pierre\"><div><strong>Pierre Dubois</strong><span>Chef d\'Entreprise</span></div></div></div>\r\n        <div class=\"testimonial-card\"><div class=\"testimonial-stars\">★★★★★</div><blockquote>La truffe noire sur le foie gras était une révélation. Une carte des vins exceptionnelle.</blockquote><div class=\"testimonial-author\"><img src=\"https://i.pravatar.cc/80?img=5\" alt=\"Isabelle\"><div><strong>Isabelle Renard</strong><span>Critique Culinaire</span></div></div></div>\r\n        <div class=\"testimonial-card\"><div class=\"testimonial-stars\">★★★★★</div><blockquote>Dîner d\'affaires parfait. Discrétion, élégance, cuisine irréprochable. Nous reviendrons.</blockquote><div class=\"testimonial-author\"><img src=\"https://i.pravatar.cc/80?img=12\" alt=\"Thomas\"><div><strong>Thomas Bernard</strong><span>Directeur Commercial</span></div></div></div>\r\n        <div class=\"testimonial-card\"><div class=\"testimonial-stars\">★★★★★</div><blockquote>Le soufflé au chocolat Valrhona est le meilleur dessert que j\'aie jamais mangé.</blockquote><div class=\"testimonial-author\"><img src=\"https://i.pravatar.cc/80?img=9\" alt=\"Claire\"><div><strong>Claire Vincent</strong><span>Architecte</span></div></div></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"carousel-controls\">\r\n      <button class=\"carousel-btn\" id=\"prevTestimonial\"><i class=\"fas fa-chevron-left\"></i></button>\r\n      <div class=\"carousel-dots\" id=\"carouselDots\"></div>\r\n      <button class=\"carousel-btn\" id=\"nextTestimonial\"><i class=\"fas fa-chevron-right\"></i></button>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n(function(){\r\n  var track = document.getElementById(\'testimonialsTrack\');\r\n  var prevBtn = document.getElementById(\'prevTestimonial\');\r\n  var nextBtn = document.getElementById(\'nextTestimonial\');\r\n  var dotsWrap = document.getElementById(\'carouselDots\');\r\n  if(!track) return;\r\n  var cards = Array.from(document.querySelectorAll(\'.testimonial-card\'));\r\n  var current = 0;\r\n  var perPage = 1;\r\n  var total = 1;\r\n  var autoplay;\r\n  function getPerPage() {\r\n    if(window.innerWidth <= 480) return 1;\r\n    if(window.innerWidth <= 1024) return 2;\r\n    return 3;\r\n  }\r\n  function buildDots() {\r\n    if(!dotsWrap) return;\r\n    dotsWrap.innerHTML = \'\';\r\n    for(var i = 0; i < total; i++) {\r\n      var dot = document.createElement(\'button\');\r\n      dot.className = \'carousel-dot\' + (i === 0 ? \' active\' : \'\');\r\n      dot.addEventListener(\'click\', (function(idx) { return function() { goTo(idx); }; })(i));\r\n      dotsWrap.appendChild(dot);\r\n    }\r\n  }\r\n  function goTo(index) {\r\n    current = (index + total) % total;\r\n    var offset = current * perPage;\r\n    var cardW = cards[0].getBoundingClientRect().width + 24;\r\n    track.style.transform = \'translateX(-\' + (offset * cardW) + \'px)\';\r\n    var dots = document.querySelectorAll(\'.carousel-dot\');\r\n    dots.forEach(function(d, i) { d.classList.toggle(\'active\', i === current); });\r\n  }\r\n  function startAuto() { autoplay = setInterval(function() { goTo(current + 1); }, 5000); }\r\n  function stopAuto() { clearInterval(autoplay); }\r\n  prevBtn.addEventListener(\'click\', function() { stopAuto(); goTo(current - 1); startAuto(); });\r\n  nextBtn.addEventListener(\'click\', function() { stopAuto(); goTo(current + 1); startAuto(); });\r\n  window.addEventListener(\'resize\', function() {\r\n    var newPer = getPerPage();\r\n    if(newPer !== perPage) {\r\n      perPage = newPer;\r\n      total = Math.ceil(cards.length / perPage);\r\n      current = 0;\r\n      buildDots();\r\n      goTo(0);\r\n    }\r\n  });\r\n  perPage = getPerPage();\r\n  total = Math.ceil(cards.length / perPage);\r\n  buildDots();\r\n  startAuto();\r\n  var startX = 0;\r\n  track.addEventListener(\'touchstart\', function(e) { startX = e.touches[0].clientX; }, {passive: true});\r\n  track.addEventListener(\'touchend\', function(e) {\r\n    var diff = startX - e.changedTouches[0].clientX;\r\n    if(Math.abs(diff) > 50) {\r\n      stopAuto();\r\n      goTo(current + (diff > 0 ? 1 : -1));\r\n      startAuto();\r\n    }\r\n  });\r\n})();\r\n</script>', '.testimonials-section {\r\n  padding: 6rem 0;\r\n  background: #fff;\r\n}\r\n.section-header {\r\n  text-align: center;\r\n  margin-bottom: 3.5rem;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.section-title em {\r\n  font-style: italic;\r\n  color: #C89B3C;\r\n}\r\n.testimonials-carousel {\r\n  overflow: hidden;\r\n  margin: 0 -1rem;\r\n}\r\n.testimonials-track {\r\n  display: flex;\r\n  transition: transform 0.5s cubic-bezier(0.4,0,0.2,1);\r\n  gap: 1.5rem;\r\n  padding: 0.5rem 1rem 2rem;\r\n}\r\n.testimonial-card {\r\n  background: #fff;\r\n  border: 1px solid #e8e0d0;\r\n  border-radius: 24px;\r\n  padding: 2.5rem;\r\n  min-width: calc(33.333% - 1rem);\r\n  flex-shrink: 0;\r\n  box-shadow: 0 2px 12px rgba(0,0,0,0.06);\r\n  transition: all 0.35s ease;\r\n}\r\n.testimonial-card:hover {\r\n  box-shadow: 0 6px 30px rgba(0,0,0,0.10);\r\n  transform: translateY(-4px);\r\n}\r\n.testimonial-stars {\r\n  font-size: 1rem;\r\n  color: #C89B3C;\r\n  margin-bottom: 1rem;\r\n  letter-spacing: 2px;\r\n}\r\n.testimonial-card blockquote {\r\n  font-family: \'Cormorant Garamond\', serif;\r\n  font-size: 1.05rem;\r\n  font-style: italic;\r\n  color: #333;\r\n  line-height: 1.8;\r\n  margin-bottom: 1.5rem;\r\n}\r\n.testimonial-card blockquote::before {\r\n  content: \'«\';\r\n  color: #C89B3C;\r\n  font-size: 1.5rem;\r\n}\r\n.testimonial-author {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 1rem;\r\n}\r\n.testimonial-author img {\r\n  width: 52px;\r\n  height: 52px;\r\n  border-radius: 50%;\r\n  border: 2px solid #C89B3C;\r\n  object-fit: cover;\r\n}\r\n.testimonial-author strong {\r\n  display: block;\r\n  font-size: 0.9rem;\r\n  color: #1E1E1E;\r\n}\r\n.testimonial-author span {\r\n  font-size: 0.78rem;\r\n  color: #999;\r\n}\r\n.carousel-controls {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 1.5rem;\r\n  margin-top: 1rem;\r\n}\r\n.carousel-btn {\r\n  width: 44px;\r\n  height: 44px;\r\n  border-radius: 50%;\r\n  border: 1.5px solid #e8e0d0;\r\n  color: #666;\r\n  display: grid;\r\n  place-items: center;\r\n  transition: all 0.35s ease;\r\n  cursor: pointer;\r\n  background: transparent;\r\n}\r\n.carousel-btn:hover {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  border-color: #C89B3C;\r\n}\r\n.carousel-dots {\r\n  display: flex;\r\n  gap: 0.5rem;\r\n}\r\n.carousel-dot {\r\n  width: 8px;\r\n  height: 8px;\r\n  border-radius: 50%;\r\n  background: #e8e0d0;\r\n  transition: all 0.35s ease;\r\n  cursor: pointer;\r\n}\r\n.carousel-dot.active {\r\n  background: #C89B3C;\r\n  transform: scale(1.3);\r\n}\r\n@media (max-width: 1024px) {\r\n  .testimonial-card { min-width: calc(50% - 0.75rem); }\r\n}\r\n@media (max-width: 768px) {\r\n  .testimonial-card { min-width: calc(80% - 0.75rem); }\r\n}\r\n@media (max-width: 480px) {\r\n  .testimonial-card { min-width: calc(100% - 1rem); }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 2, 0, 0, 0, 1, '2026-06-03 10:55:57', '2026-06-03 12:29:51'),
(169, NULL, 'Vidéo Section', 'video-section', NULL, NULL, 'fa-cube', '<section class=\"video-section\" id=\"video\">\r\n  <div class=\"video-bg\">\r\n    <img src=\"https://images.unsplash.com/photo-1551218808-94e220e084d2?w=1920&q=80\" alt=\"Vue du restaurant\">\r\n    <div class=\"video-overlay\"></div>\r\n  </div>\r\n  <div class=\"video-content\">\r\n    <span class=\"section-tag\" style=\"color:#C89B3C\">Notre Histoire en Vidéo</span>\r\n    <h2 class=\"section-title\" style=\"color:#fff\">Plongez dans<br><em>l\'Univers Maison Dorée</em></h2>\r\n    <button class=\"play-btn\" id=\"playBtn\"><i class=\"fas fa-play\"></i></button>\r\n  </div>\r\n  <div class=\"video-modal\" id=\"videoModal\">\r\n    <div class=\"video-modal-inner\">\r\n      <button class=\"video-modal-close\" id=\"videoModalClose\"><i class=\"fas fa-times\"></i></button>\r\n      <div class=\"video-embed-wrap\">\r\n        <iframe id=\"videoIframe\" src=\"\" data-src=\"https://www.youtube.com/embed/dQw4w9WgXcQ?autoplay=1\" title=\"Présentation\" allow=\"autoplay; fullscreen\" allowfullscreen></iframe>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n(function(){\r\n  var modal = document.getElementById(\'videoModal\');\r\n  var playBtn = document.getElementById(\'playBtn\');\r\n  var closeBtn = document.getElementById(\'videoModalClose\');\r\n  var iframe = document.getElementById(\'videoIframe\');\r\n  if(!modal || !playBtn) return;\r\n  function openModal() {\r\n    iframe.src = iframe.dataset.src;\r\n    modal.classList.add(\'open\');\r\n    document.body.style.overflow = \'hidden\';\r\n  }\r\n  function closeModal() {\r\n    iframe.src = \'\';\r\n    modal.classList.remove(\'open\');\r\n    document.body.style.overflow = \'\';\r\n  }\r\n  playBtn.addEventListener(\'click\', openModal);\r\n  closeBtn.addEventListener(\'click\', closeModal);\r\n  modal.addEventListener(\'click\', function(e) { if(e.target === modal) closeModal(); });\r\n  document.addEventListener(\'keydown\', function(e) {\r\n    if(e.key === \'Escape\' && modal.classList.contains(\'open\')) closeModal();\r\n  });\r\n})();\r\n</script>', '.video-section {\r\n  position: relative;\r\n  min-height: 480px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  overflow: hidden;\r\n}\r\n.video-bg {\r\n  position: absolute;\r\n  inset: 0;\r\n}\r\n.video-bg img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n}\r\n.video-overlay {\r\n  position: absolute;\r\n  inset: 0;\r\n  background: rgba(20,12,3,0.72);\r\n}\r\n.video-content {\r\n  position: relative;\r\n  z-index: 2;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n  text-align: center;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n  color: #fff;\r\n}\r\n.section-title em {\r\n  font-style: italic;\r\n  color: #C89B3C;\r\n}\r\n.play-btn {\r\n  width: 90px;\r\n  height: 90px;\r\n  border-radius: 50%;\r\n  background: rgba(200,155,60,0.9);\r\n  color: #fff;\r\n  font-size: 1.6rem;\r\n  display: grid;\r\n  place-items: center;\r\n  box-shadow: 0 0 0 0 rgba(200,155,60,0.4);\r\n  animation: pulseVideo 2.5s infinite;\r\n  transition: all 0.35s ease;\r\n  cursor: pointer;\r\n  border: none;\r\n}\r\n.play-btn:hover {\r\n  background: #C89B3C;\r\n  transform: scale(1.1);\r\n}\r\n@keyframes pulseVideo {\r\n  0% { box-shadow: 0 0 0 0 rgba(200,155,60,0.5); }\r\n  70% { box-shadow: 0 0 0 24px rgba(200,155,60,0); }\r\n  100% { box-shadow: 0 0 0 0 rgba(200,155,60,0); }\r\n}\r\n.video-modal {\r\n  display: none;\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 9998;\r\n  background: rgba(0,0,0,0.93);\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n.video-modal.open {\r\n  display: flex;\r\n}\r\n.video-modal-inner {\r\n  position: relative;\r\n  width: min(860px, 95vw);\r\n}\r\n.video-modal-close {\r\n  position: absolute;\r\n  top: -3rem;\r\n  right: 0;\r\n  color: rgba(255,255,255,0.7);\r\n  font-size: 1.3rem;\r\n  transition: all 0.35s ease;\r\n  cursor: pointer;\r\n  background: none;\r\n  border: none;\r\n}\r\n.video-modal-close:hover {\r\n  color: #fff;\r\n}\r\n.video-embed-wrap {\r\n  position: relative;\r\n  padding-bottom: 56.25%;\r\n  border-radius: 16px;\r\n  overflow: hidden;\r\n}\r\n.video-embed-wrap iframe {\r\n  position: absolute;\r\n  inset: 0;\r\n  width: 100%;\r\n  height: 100%;\r\n  border: none;\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 3, 1, 0, 0, 1, '2026-06-03 10:56:54', '2026-06-03 14:46:49'),
(170, NULL, 'Services', 'services-2', NULL, NULL, 'fa-cube', '<section class=\"services-section\" id=\"services\">\r\n  <div class=\"container\" style=\"max-width:1200px;margin:0 auto;padding:0 24px\">\r\n    <div class=\"section-header text-center\">\r\n      <span class=\"section-tag\">Ce Que Nous Offrons</span>\r\n      <h2 class=\"section-title\">Nos Services</h2>\r\n    </div>\r\n    <div class=\"services-grid\">\r\n      <div class=\"service-card\"><div class=\"service-icon\"><i class=\"fas fa-utensils\"></i></div><h3>Fine Dining</h3><p>Une expérience gastronomique d\'exception dans un cadre élégant et raffiné.</p></div>\r\n      <div class=\"service-card\"><div class=\"service-icon\"><i class=\"fas fa-lock\"></i></div><h3>Événements Privés</h3><p>Salons privatifs pour vos soirées, dîners de gala et occasions spéciales.</p></div>\r\n      <div class=\"service-card\"><div class=\"service-icon\"><i class=\"fas fa-briefcase\"></i></div><h3>Événements Corporate</h3><p>Déjeuners d\'affaires, team buildings gastronomiques et cocktails dinatoires.</p></div>\r\n      <div class=\"service-card\"><div class=\"service-icon\"><i class=\"fas fa-birthday-cake\"></i></div><h3>Anniversaires</h3><p>Célébrez vos moments précieux avec un menu personnalisé et une décoration sur mesure.</p></div>\r\n      <div class=\"service-card\"><div class=\"service-icon\"><i class=\"fas fa-truck\"></i></div><h3>Traiteur & Catering</h3><p>La cuisine Maison Dorée se déplace chez vous pour vos événements privés.</p></div>\r\n      <div class=\"service-card\"><div class=\"service-icon\"><i class=\"fas fa-box\"></i></div><h3>Livraison à Domicile</h3><p>Profitez de notre menu en livraison premium dans tout Paris intramuros.</p></div>\r\n    </div>\r\n  </div>\r\n</section>', '.services-section {\r\n  padding: 6rem 0;\r\n  background: #F8F8F8;\r\n}\r\n.section-header {\r\n  text-align: center;\r\n  margin-bottom: 3.5rem;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.services-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(3, 1fr);\r\n  gap: 1.75rem;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n.service-card {\r\n  background: #fff;\r\n  border: 1px solid #e8e0d0;\r\n  border-radius: 16px;\r\n  padding: 2.5rem 2rem;\r\n  text-align: center;\r\n  transition: all 0.35s ease;\r\n  position: relative;\r\n  overflow: hidden;\r\n}\r\n.service-card:hover {\r\n  transform: translateY(-6px);\r\n  box-shadow: 0 6px 30px rgba(0,0,0,0.10);\r\n  border-color: #C89B3C;\r\n}\r\n.service-icon {\r\n  width: 60px;\r\n  height: 60px;\r\n  background: linear-gradient(135deg, #C89B3C, #a07820);\r\n  color: #fff;\r\n  border-radius: 8px;\r\n  display: grid;\r\n  place-items: center;\r\n  margin: 0 auto 1.5rem;\r\n  font-size: 1.3rem;\r\n  transition: all 0.35s ease;\r\n}\r\n.service-card:hover .service-icon {\r\n  border-radius: 50%;\r\n}\r\n.service-card h3 {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.05rem;\r\n  margin-bottom: 0.75rem;\r\n  color: #1E1E1E;\r\n}\r\n.service-card p {\r\n  font-size: 0.86rem;\r\n  color: #666;\r\n  line-height: 1.7;\r\n}\r\n@media (max-width: 1024px) {\r\n  .services-grid { grid-template-columns: repeat(2, 1fr); }\r\n}\r\n@media (max-width: 768px) {\r\n  .services-grid { grid-template-columns: 1fr; }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 0, 0, 0, 1, '2026-06-03 11:02:06', '2026-06-03 11:59:38'),
(171, NULL, 'INSTAGRAM FEED', 'instagram-feed', NULL, NULL, 'fa-cube', '<section class=\"instagram-section\" id=\"instagram\">\r\n  <div class=\"container\" style=\"max-width:1200px;margin:0 auto;padding:0 24px;text-align:center\">\r\n    <div class=\"section-header\">\r\n      <span class=\"section-tag\">Réseaux Sociaux</span>\r\n      <h2 class=\"section-title\">Suivez-Nous sur <em>Instagram</em></h2>\r\n      <a href=\"#\" class=\"insta-handle\" target=\"_blank\">@maisondoree_paris</a>\r\n    </div>\r\n    <div class=\"insta-grid\">\r\n      <a href=\"#\" class=\"insta-item\" target=\"_blank\"><img src=\"https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=300&q=80\" alt=\"Plat\"><div class=\"insta-hover\"><i class=\"fab fa-instagram\"></i></div></a>\r\n      <a href=\"#\" class=\"insta-item\" target=\"_blank\"><img src=\"https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=300&q=80\" alt=\"Assiette\"><div class=\"insta-hover\"><i class=\"fab fa-instagram\"></i></div></a>\r\n      <a href=\"#\" class=\"insta-item\" target=\"_blank\"><img src=\"https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=300&q=80\" alt=\"Salle\"><div class=\"insta-hover\"><i class=\"fab fa-instagram\"></i></div></a>\r\n      <a href=\"#\" class=\"insta-item\" target=\"_blank\"><img src=\"https://images.unsplash.com/photo-1551024601-bec78aea704b?w=300&q=80\" alt=\"Dessert\"><div class=\"insta-hover\"><i class=\"fab fa-instagram\"></i></div></a>\r\n      <a href=\"#\" class=\"insta-item\" target=\"_blank\"><img src=\"https://images.unsplash.com/photo-1577219491135-ce391730fb2c?w=300&q=80\" alt=\"Chef\"><div class=\"insta-hover\"><i class=\"fab fa-instagram\"></i></div></a>\r\n      <a href=\"#\" class=\"insta-item\" target=\"_blank\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?w=300&q=80\" alt=\"Verres\"><div class=\"insta-hover\"><i class=\"fab fa-instagram\"></i></div></a>\r\n      <a href=\"#\" class=\"insta-item\" target=\"_blank\"><img src=\"https://images.unsplash.com/photo-1488477181946-6428a0291777?w=300&q=80\" alt=\"Chocolat\"><div class=\"insta-hover\"><i class=\"fab fa-instagram\"></i></div></a>\r\n      <a href=\"#\" class=\"insta-item\" target=\"_blank\"><img src=\"https://images.unsplash.com/photo-1544148103-0773bf10d330?w=300&q=80\" alt=\"Table\"><div class=\"insta-hover\"><i class=\"fab fa-instagram\"></i></div></a>\r\n    </div>\r\n  </div>\r\n</section>', '.instagram-section {\r\n  padding: 5rem 0;\r\n  background: #1E1E1E;\r\n}\r\n.section-header {\r\n  text-align: center;\r\n  margin-bottom: 3.5rem;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #fff;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.section-title em {\r\n  font-style: italic;\r\n  color: #C89B3C;\r\n}\r\n.insta-handle {\r\n  display: inline-block;\r\n  color: #d9b560;\r\n  font-size: 0.9rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.08em;\r\n  margin-top: -0.5rem;\r\n  margin-bottom: 2.5rem;\r\n  text-decoration: none;\r\n}\r\n.insta-handle:hover {\r\n  color: #C89B3C;\r\n}\r\n.insta-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(8, 1fr);\r\n  gap: 0.5rem;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n.insta-item {\r\n  position: relative;\r\n  overflow: hidden;\r\n  border-radius: 8px;\r\n  aspect-ratio: 1;\r\n  text-decoration: none;\r\n}\r\n.insta-item img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n  transition: transform 0.5s ease;\r\n}\r\n.insta-item:hover img {\r\n  transform: scale(1.1);\r\n}\r\n.insta-hover {\r\n  position: absolute;\r\n  inset: 0;\r\n  background: rgba(200,155,60,0.75);\r\n  display: grid;\r\n  place-items: center;\r\n  font-size: 1.5rem;\r\n  color: #fff;\r\n  opacity: 0;\r\n  transition: opacity 0.3s;\r\n}\r\n.insta-item:hover .insta-hover {\r\n  opacity: 1;\r\n}\r\n@media (max-width: 1200px) {\r\n  .insta-grid { grid-template-columns: repeat(4, 1fr); }\r\n}\r\n@media (max-width: 768px) {\r\n  .insta-grid { grid-template-columns: repeat(2, 1fr); }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 2, 5, 0, 0, 1, '2026-06-03 12:24:25', '2026-07-25 19:50:34'),
(172, NULL, 'FAQ', 'faq', NULL, NULL, 'fa-cube', '<section class=\"faq-section\" id=\"faq\">\r\n  <div class=\"container\" style=\"max-width:1200px;margin:0 auto;padding:0 24px\">\r\n    <div class=\"section-header text-center\">\r\n      <span class=\"section-tag\">Questions Fréquentes</span>\r\n      <h2 class=\"section-title\">FAQ</h2>\r\n    </div>\r\n    <div class=\"faq-list\">\r\n      <div class=\"faq-item\"><button class=\"faq-question\" aria-expanded=\"false\">La réservation est-elle obligatoire ? <i class=\"fas fa-plus faq-icon\"></i></button><div class=\"faq-answer\"><p>Nous recommandons vivement de réserver, notamment le week-end et lors des périodes de fêtes. Les réservations peuvent être effectuées en ligne, par téléphone ou par email.</p></div></div>\r\n      <div class=\"faq-item\"><button class=\"faq-question\" aria-expanded=\"false\">Proposez-vous des options végétariennes et vegan ? <i class=\"fas fa-plus faq-icon\"></i></button><div class=\"faq-answer\"><p>Absolument. Notre carte propose plusieurs options végétariennes et nous pouvons adapter nos menus aux régimes vegan sur demande préalable.</p></div></div>\r\n      <div class=\"faq-item\"><button class=\"faq-question\" aria-expanded=\"false\">Pouvez-vous organiser des événements privés ? <i class=\"fas fa-plus faq-icon\"></i></button><div class=\"faq-answer\"><p>Oui, Maison Dorée dispose de deux salons privés pouvant accueillir de 8 à 50 personnes. Mariages, anniversaires, dîners d\'affaires — notre équipe événementielle conçoit avec vous une expérience sur mesure.</p></div></div>\r\n      <div class=\"faq-item\"><button class=\"faq-question\" aria-expanded=\"false\">Livrez-vous à domicile ? <i class=\"fas fa-plus faq-icon\"></i></button><div class=\"faq-answer\"><p>Nous proposons un service de livraison premium dans Paris intramuros (75) du mardi au dimanche, de 18h à 22h.</p></div></div>\r\n      <div class=\"faq-item\"><button class=\"faq-question\" aria-expanded=\"false\">Y a-t-il un code vestimentaire ? <i class=\"fas fa-plus faq-icon\"></i></button><div class=\"faq-answer\"><p>Nous encourageons une tenue smart casual ou habillée. La tenue décontractée (sport, short, tongs) n\'est pas acceptée le soir.</p></div></div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n(function(){\r\n  var items = document.querySelectorAll(\'.faq-item\');\r\n  items.forEach(function(item) {\r\n    var btn = item.querySelector(\'.faq-question\');\r\n    var answer = item.querySelector(\'.faq-answer\');\r\n    if(!btn || !answer) return;\r\n    btn.addEventListener(\'click\', function() {\r\n      var isOpen = btn.getAttribute(\'aria-expanded\') === \'true\';\r\n      items.forEach(function(i) {\r\n        var b = i.querySelector(\'.faq-question\');\r\n        var a = i.querySelector(\'.faq-answer\');\r\n        b.setAttribute(\'aria-expanded\', \'false\');\r\n        if(a) a.style.maxHeight = \'\';\r\n      });\r\n      if(!isOpen) {\r\n        btn.setAttribute(\'aria-expanded\', \'true\');\r\n        answer.style.maxHeight = answer.scrollHeight + \'px\';\r\n      }\r\n    });\r\n  });\r\n})();\r\n</script>', '.faq-section {\r\n  padding: 6rem 0;\r\n  background: #fff;\r\n}\r\n.section-header {\r\n  text-align: center;\r\n  margin-bottom: 3.5rem;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.faq-list {\r\n  max-width: 780px;\r\n  margin: 0 auto;\r\n}\r\n.faq-item {\r\n  border-bottom: 1px solid #e8e0d0;\r\n}\r\n.faq-question {\r\n  width: 100%;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  padding: 1.5rem 0;\r\n  font-size: 1rem;\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  text-align: left;\r\n  gap: 1rem;\r\n  transition: color 0.25s;\r\n  background: none;\r\n  border: none;\r\n  cursor: pointer;\r\n}\r\n.faq-question:hover {\r\n  color: #C89B3C;\r\n}\r\n.faq-question[aria-expanded=\"true\"] {\r\n  color: #C89B3C;\r\n}\r\n.faq-icon {\r\n  flex-shrink: 0;\r\n  color: #C89B3C;\r\n  transition: transform 0.3s;\r\n}\r\n.faq-question[aria-expanded=\"true\"] .faq-icon {\r\n  transform: rotate(45deg);\r\n}\r\n.faq-answer {\r\n  overflow: hidden;\r\n  max-height: 0;\r\n  transition: max-height 0.4s cubic-bezier(0.4,0,0.2,1);\r\n}\r\n.faq-answer p {\r\n  padding-bottom: 1.5rem;\r\n  font-size: 0.92rem;\r\n  color: #666;\r\n  line-height: 1.8;\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 2, 0, 0, 0, 1, '2026-06-03 12:25:28', '2026-06-03 12:44:41'),
(173, NULL, 'EVENTS', 'events', NULL, NULL, 'fa-cube', '<section class=\"events-section\" id=\"events\">\r\n  <div class=\"container\" style=\"max-width:1200px;margin:0 auto;padding:0 24px\">\r\n    <div class=\"section-header text-center\">\r\n      <span class=\"section-tag\">Agenda</span>\r\n      <h2 class=\"section-title\">Prochains Événements</h2>\r\n    </div>\r\n    <div class=\"events-grid\">\r\n      <div class=\"event-card\"><div class=\"event-date\"><span class=\"event-day\">15</span><span class=\"event-month\">Juin</span></div><div class=\"event-body\"><span class=\"event-tag\">Live Music</span><h3>Soirée Jazz & Gastronomie</h3><p>Le Quartet Moreno accompagne votre dîner avec des standards jazz et des créations originales.</p><a href=\"#reservation\" class=\"event-link\">Réserver <i class=\"fas fa-arrow-right\"></i></a></div></div>\r\n      <div class=\"event-card\"><div class=\"event-date\"><span class=\"event-day\">22</span><span class=\"event-month\">Juin</span></div><div class=\"event-body\"><span class=\"event-tag\">Dégustation</span><h3>Wine Tasting — Bourgogne</h3><p>Notre sommelier vous guide à travers les grandes appellations de Bourgogne avec 6 vins d\'exception.</p><a href=\"#reservation\" class=\"event-link\">Réserver <i class=\"fas fa-arrow-right\"></i></a></div></div>\r\n      <div class=\"event-card\"><div class=\"event-date\"><span class=\"event-day\">29</span><span class=\"event-month\">Juin</span></div><div class=\"event-body\"><span class=\"event-tag\">Chef\'s Night</span><h3>Dîner Haute Couture</h3><p>Le Chef Moreau présente sa nouvelle collection saisonnière en 9 actes. Une soirée exclusive.</p><a href=\"#reservation\" class=\"event-link\">Réserver <i class=\"fas fa-arrow-right\"></i></a></div></div>\r\n    </div>\r\n  </div>\r\n</section>', '.events-section {\r\n  padding: 6rem 0;\r\n  background: #F8F8F8;\r\n}\r\n.section-header {\r\n  text-align: center;\r\n  margin-bottom: 3.5rem;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.events-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(3, 1fr);\r\n  gap: 1.75rem;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n.event-card {\r\n  background: #fff;\r\n  border: 1px solid #e8e0d0;\r\n  border-radius: 16px;\r\n  padding: 2rem;\r\n  display: flex;\r\n  gap: 1.5rem;\r\n  transition: all 0.35s ease;\r\n}\r\n.event-card:hover {\r\n  transform: translateY(-4px);\r\n  box-shadow: 0 6px 30px rgba(0,0,0,0.10);\r\n}\r\n.event-date {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  justify-content: center;\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  border-radius: 8px;\r\n  padding: 0.75rem 1rem;\r\n  flex-shrink: 0;\r\n  min-width: 60px;\r\n}\r\n.event-day {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.8rem;\r\n  font-weight: 700;\r\n  line-height: 1;\r\n}\r\n.event-month {\r\n  font-size: 0.7rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.1em;\r\n  text-transform: uppercase;\r\n  opacity: 0.85;\r\n}\r\n.event-tag {\r\n  font-size: 0.72rem;\r\n  font-weight: 600;\r\n  color: #C89B3C;\r\n  letter-spacing: 0.1em;\r\n  text-transform: uppercase;\r\n  display: block;\r\n  margin-bottom: 0.4rem;\r\n}\r\n.event-body h3 {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.05rem;\r\n  margin-bottom: 0.5rem;\r\n  color: #1E1E1E;\r\n}\r\n.event-body p {\r\n  font-size: 0.84rem;\r\n  color: #666;\r\n  line-height: 1.65;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.event-link {\r\n  font-size: 0.82rem;\r\n  font-weight: 600;\r\n  color: #C89B3C;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 0.35rem;\r\n  text-decoration: none;\r\n}\r\n.event-link:hover { gap: 0.6rem; }\r\n@media (max-width: 1024px) {\r\n  .events-grid { grid-template-columns: 1fr; }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 0, 0, 0, 1, '2026-06-03 12:26:18', '2026-06-03 12:45:35'),
(174, NULL, 'SPECIAL OFFERS', 'special-offers', NULL, NULL, 'fa-cube', '<section class=\"offers-section\" id=\"offers\">\r\n  <div class=\"container\" style=\"max-width:1200px;margin:0 auto;padding:0 24px\">\r\n    <div class=\"section-header text-center\">\r\n      <span class=\"section-tag\">Promotions</span>\r\n      <h2 class=\"section-title\">Offres Spéciales</h2>\r\n    </div>\r\n    <div class=\"offers-grid\">\r\n      <div class=\"offer-card\"><div class=\"offer-badge\">-20%</div><h3>Weekend Romantique</h3><p>Menu dégustation 5 plats avec accord mets & vins pour 2 personnes le week-end.</p><span class=\"offer-valid\">Valable Sam & Dim</span><a href=\"#reservation\" class=\"btn btn-gold mt-4\">En Profiter</a></div>\r\n      <div class=\"offer-card\"><div class=\"offer-badge\">Pack</div><h3>Menu Famille</h3><p>Entrée + Plat + Dessert pour 4 personnes avec boissons incluses. Enfants bienvenus.</p><span class=\"offer-valid\">Tous les jours</span><a href=\"#reservation\" class=\"btn btn-gold mt-4\">En Profiter</a></div>\r\n      <div class=\"offer-card\"><div class=\"offer-badge\">Happy Hour</div><h3>L\'Heure Apéritive</h3><p>Cocktails signature, planches de charcuterie et amuse-bouches à prix réduits.</p><span class=\"offer-valid\">17h00 – 19h00</span><a href=\"#reservation\" class=\"btn btn-gold mt-4\">En Profiter</a></div>\r\n      <div class=\"offer-card\"><div class=\"offer-badge\">Chef</div><h3>Menu du Chef</h3><p>7 plats surprise composés par le Chef en fonction des produits du marché du jour.</p><span class=\"offer-valid\">Sur réservation</span><a href=\"#reservation\" class=\"btn btn-gold mt-4\">En Profiter</a></div>\r\n    </div>\r\n  </div>\r\n</section>', '.offers-section {\r\n  padding: 6rem 0;\r\n  background: #fff;\r\n}\r\n.section-header {\r\n  text-align: center;\r\n  margin-bottom: 3.5rem;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.offers-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(4, 1fr);\r\n  gap: 1.5rem;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n.offer-card {\r\n  background: #fff;\r\n  border: 1px solid #e8e0d0;\r\n  border-radius: 16px;\r\n  padding: 2rem 1.75rem;\r\n  text-align: center;\r\n  position: relative;\r\n  overflow: hidden;\r\n  transition: all 0.35s ease;\r\n}\r\n.offer-card:hover {\r\n  transform: translateY(-6px);\r\n  box-shadow: 0 16px 60px rgba(0,0,0,0.14);\r\n}\r\n.offer-badge {\r\n  display: inline-flex;\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  font-size: 0.75rem;\r\n  font-weight: 700;\r\n  padding: 0.3rem 0.9rem;\r\n  border-radius: 50px;\r\n  margin-bottom: 1rem;\r\n  letter-spacing: 0.05em;\r\n}\r\n.offer-card h3 {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.1rem;\r\n  margin-bottom: 0.75rem;\r\n  color: #1E1E1E;\r\n}\r\n.offer-card p {\r\n  font-size: 0.85rem;\r\n  color: #666;\r\n  line-height: 1.7;\r\n  margin-bottom: 1rem;\r\n}\r\n.offer-valid {\r\n  font-size: 0.78rem;\r\n  color: #999;\r\n  font-style: italic;\r\n}\r\n.btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n  padding: 0.85rem 2rem;\r\n  border-radius: 50px;\r\n  font-size: 0.9rem;\r\n  font-weight: 600;\r\n  transition: all 0.35s ease;\r\n  text-decoration: none;\r\n}\r\n.btn-gold {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  box-shadow: 0 4px 20px rgba(200,155,60,0.3);\r\n}\r\n.btn-gold:hover {\r\n  background: #a07820;\r\n  transform: translateY(-2px);\r\n}\r\n.mt-4 { margin-top: 1rem; display: inline-block; }\r\n@media (max-width: 1200px) {\r\n  .offers-grid { grid-template-columns: repeat(2, 1fr); }\r\n}\r\n@media (max-width: 768px) {\r\n  .offers-grid { grid-template-columns: 1fr; }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-03 12:27:28', '2026-06-03 14:46:26');
INSERT INTO `blocks` (`id`, `categorie_id`, `name`, `slug`, `description`, `thumbnail`, `icon`, `html_content`, `css_content`, `js_content`, `section_id`, `category`, `website_type`, `tags`, `is_responsive`, `is_free`, `width`, `height`, `usage_count`, `views_count`, `rating`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(175, NULL, 'Back to top', 'back-to-top', NULL, NULL, 'fa-cube', '<button class=\"back-to-top\" id=\"backToTop\" aria-label=\"Retour en haut\"><i class=\"fas fa-chevron-up\"></i></button>\r\n<a href=\"#reservation\" class=\"floating-reservation\" id=\"floatingReservation\"><i class=\"fas fa-calendar-check\"></i><span>Réserver</span></a>\r\n<a href=\"https://wa.me/33123456789\" class=\"floating-whatsapp\" target=\"_blank\" rel=\"noopener\"><i class=\"fab fa-whatsapp\"></i></a>\r\n<a href=\"tel:+33123456789\" class=\"floating-phone\"><i class=\"fas fa-phone\"></i></a>\r\n\r\n<div class=\"popup-overlay\" id=\"newsletterPopup\">\r\n  <div class=\"popup-inner\">\r\n    <button class=\"popup-close\" id=\"popupClose\"><i class=\"fas fa-times\"></i></button>\r\n    <div class=\"popup-content\">\r\n      <span class=\"popup-tag\">Offre Exclusive</span>\r\n      <h3>-15% sur Votre Première Réservation</h3>\r\n      <p>Inscrivez-vous à notre newsletter et recevez votre code promo exclusif.</p>\r\n      <form class=\"popup-form\" id=\"popupForm\">\r\n        <input type=\"email\" placeholder=\"Votre email\" required>\r\n        <button type=\"submit\" class=\"btn btn-gold btn-full\">Obtenir Mon Code</button>\r\n      </form>\r\n      <small>Sans engagement. Désabonnement en un clic.</small>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<script>\r\n(function(){\r\n  // Back to top\r\n  var backBtn = document.getElementById(\'backToTop\');\r\n  var floatingRes = document.getElementById(\'floatingReservation\');\r\n  window.addEventListener(\'scroll\', function() {\r\n    var y = window.scrollY;\r\n    backBtn.classList.toggle(\'visible\', y > 300);\r\n    floatingRes.classList.toggle(\'visible\', y > 600);\r\n  });\r\n  backBtn.addEventListener(\'click\', function() {\r\n    window.scrollTo({ top: 0, behavior: \'smooth\' });\r\n  });\r\n\r\n  // Popup\r\n  var popup = document.getElementById(\'newsletterPopup\');\r\n  var popupClose = document.getElementById(\'popupClose\');\r\n  var popupForm = document.getElementById(\'popupForm\');\r\n  if(popup && !sessionStorage.getItem(\'popupShown\')) {\r\n    setTimeout(function() {\r\n      popup.classList.add(\'open\');\r\n    }, 8000);\r\n  }\r\n  function closePopup() {\r\n    popup.classList.remove(\'open\');\r\n    sessionStorage.setItem(\'popupShown\', \'1\');\r\n  }\r\n  if(popupClose) popupClose.addEventListener(\'click\', closePopup);\r\n  if(popup) popup.addEventListener(\'click\', function(e) { if(e.target === popup) closePopup(); });\r\n  if(popupForm) {\r\n    popupForm.addEventListener(\'submit\', function(e) {\r\n      e.preventDefault();\r\n      closePopup();\r\n    });\r\n  }\r\n})();\r\n</script>', '/* FLOATING ELEMENTS */\r\n.back-to-top {\r\n  position: fixed;\r\n  bottom: 12rem;\r\n  right: 1.5rem;\r\n  z-index: 500;\r\n  width: 46px;\r\n  height: 46px;\r\n  background: #1E1E1E;\r\n  color: #C89B3C;\r\n  border-radius: 50%;\r\n  display: grid;\r\n  place-items: center;\r\n  font-size: 1rem;\r\n  box-shadow: 0 6px 30px rgba(0,0,0,0.10);\r\n  opacity: 0;\r\n  visibility: hidden;\r\n  transition: all 0.35s ease;\r\n  border: 1px solid rgba(200,155,60,0.3);\r\n  cursor: pointer;\r\n}\r\n.back-to-top.visible {\r\n  opacity: 1;\r\n  visibility: visible;\r\n}\r\n.back-to-top:hover {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  transform: translateY(-3px);\r\n}\r\n.floating-reservation {\r\n  position: fixed;\r\n  bottom: 7.5rem;\r\n  right: 1.5rem;\r\n  z-index: 500;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  padding: 0.75rem 1.25rem;\r\n  border-radius: 50px;\r\n  font-size: 0.85rem;\r\n  font-weight: 600;\r\n  box-shadow: 0 6px 24px rgba(200,155,60,0.4);\r\n  opacity: 0;\r\n  visibility: hidden;\r\n  transform: translateX(100%);\r\n  transition: all 0.35s ease;\r\n  text-decoration: none;\r\n}\r\n.floating-reservation.visible {\r\n  opacity: 1;\r\n  visibility: visible;\r\n  transform: none;\r\n}\r\n.floating-reservation:hover {\r\n  background: #a07820;\r\n  transform: translateY(-2px);\r\n}\r\n.floating-whatsapp {\r\n  position: fixed;\r\n  bottom: 5rem;\r\n  right: 1.5rem;\r\n  z-index: 500;\r\n  width: 50px;\r\n  height: 50px;\r\n  background: #25D366;\r\n  color: #fff;\r\n  border-radius: 50%;\r\n  display: grid;\r\n  place-items: center;\r\n  font-size: 1.4rem;\r\n  box-shadow: 0 4px 20px rgba(37,211,102,0.4);\r\n  transition: all 0.35s ease;\r\n  text-decoration: none;\r\n}\r\n.floating-whatsapp:hover {\r\n  transform: scale(1.12);\r\n}\r\n.floating-phone {\r\n  position: fixed;\r\n  bottom: 1.75rem;\r\n  right: 1.5rem;\r\n  z-index: 500;\r\n  width: 50px;\r\n  height: 50px;\r\n  background: #1E1E1E;\r\n  color: #C89B3C;\r\n  border-radius: 50%;\r\n  display: grid;\r\n  place-items: center;\r\n  font-size: 1.1rem;\r\n  box-shadow: 0 6px 30px rgba(0,0,0,0.10);\r\n  border: 1px solid rgba(200,155,60,0.3);\r\n  transition: all 0.35s ease;\r\n  text-decoration: none;\r\n}\r\n.floating-phone:hover {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  transform: scale(1.1);\r\n}\r\n.popup-overlay {\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 9990;\r\n  background: rgba(0,0,0,0.7);\r\n  display: none;\r\n  align-items: center;\r\n  justify-content: center;\r\n  padding: 1rem;\r\n}\r\n.popup-overlay.open {\r\n  display: flex;\r\n}\r\n.popup-inner {\r\n  background: #fff;\r\n  border-radius: 24px;\r\n  padding: 3rem;\r\n  max-width: 460px;\r\n  width: 100%;\r\n  position: relative;\r\n  text-align: center;\r\n  box-shadow: 0 16px 60px rgba(0,0,0,0.14);\r\n}\r\n.popup-close {\r\n  position: absolute;\r\n  top: 1rem;\r\n  right: 1rem;\r\n  color: #999;\r\n  font-size: 1.1rem;\r\n  cursor: pointer;\r\n  background: none;\r\n  border: none;\r\n}\r\n.popup-close:hover {\r\n  color: #1E1E1E;\r\n}\r\n.popup-tag {\r\n  font-size: 0.75rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n}\r\n.popup-content h3 {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.6rem;\r\n  color: #1E1E1E;\r\n  margin: 0.75rem 0 1rem;\r\n}\r\n.popup-content p {\r\n  font-size: 0.9rem;\r\n  color: #666;\r\n  margin-bottom: 1.5rem;\r\n}\r\n.popup-form {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 0.75rem;\r\n}\r\n.popup-form input {\r\n  padding: 0.8rem 1rem;\r\n  border: 1.5px solid #e8e0d0;\r\n  border-radius: 8px;\r\n  font-size: 0.9rem;\r\n  outline: none;\r\n  transition: border-color 0.25s;\r\n}\r\n.popup-form input:focus {\r\n  border-color: #C89B3C;\r\n}\r\n.popup-content small {\r\n  display: block;\r\n  margin-top: 1rem;\r\n  font-size: 0.76rem;\r\n  color: #999;\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 2, 1, 0, 0, 1, '2026-06-03 12:28:55', '2026-06-03 14:46:16'),
(176, NULL, 'Carte des Vins', 'carte-des-vins', NULL, NULL, 'fa-cube', '<section class=\"wine-section\" id=\"wine\">\r\n  <div class=\"container\" style=\"max-width:1200px;margin:0 auto;padding:0 24px\">\r\n    <div class=\"section-header text-center\">\r\n      <span class=\"section-tag\">Notre Cave</span>\r\n      <h2 class=\"section-title\">Carte des <em>Vins</em></h2>\r\n      <p class=\"section-subtitle\">Une sélection prestigieuse de vins français et internationaux, soigneusement choisis par notre sommelier</p>\r\n    </div>\r\n\r\n    <div class=\"wine-categories\">\r\n      <button class=\"wine-cat-btn active\" data-cat=\"rouge\">🍷 Vins Rouges</button>\r\n      <button class=\"wine-cat-btn\" data-cat=\"blanc\">🥂 Vins Blancs</button>\r\n      <button class=\"wine-cat-btn\" data-cat=\"champagne\">🍾 Champagne</button>\r\n      <button class=\"wine-cat-btn\" data-cat=\"international\">🌍 International</button>\r\n    </div>\r\n\r\n    <!-- Panel Vins Rouges -->\r\n    <div class=\"wine-panel active\" id=\"wine-rouge\">\r\n      <div class=\"wine-grid\">\r\n        <div class=\"wine-card\"><div class=\"wine-img\"><img src=\"https://images.unsplash.com/photo-1506377242683-e2cbef21d7a7?w=500&q=80\" alt=\"Bordeaux\"><div class=\"wine-badge gold\">Grand Cru</div></div><div class=\"wine-body\"><div class=\"wine-name\">Château Margaux</div><div class=\"wine-domain\">Bordeaux, France · 2018</div><div class=\"wine-description\">Cuvée d\'exception aux arômes de fruits noirs, d\'épices et de cèdre. Tanins soyeux, finale élégante et longue.</div><div class=\"wine-features\"><span class=\"wine-feature\"><i class=\"fas fa-star\"></i> 95/100 Parker</span><span class=\"wine-feature\"><i class=\"fas fa-clock\"></i> Garde 10-15 ans</span></div><div class=\"wine-footer\"><span class=\"wine-price\">€ 245 <span>/ bouteille</span></span><button class=\"wine-order\" onclick=\"alert(\'Ajouté à votre commande !\')\">Commander</button></div></div></div>\r\n        <div class=\"wine-card\"><div class=\"wine-img\"><img src=\"https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=500&q=80\" alt=\"Bourgogne\"><div class=\"wine-badge gold\">Grand Cru</div></div><div class=\"wine-body\"><div class=\"wine-name\">Romanée-Conti</div><div class=\"wine-domain\">Bourgogne, France · 2019</div><div class=\"wine-description\">Le plus célèbre des vins de Bourgogne. Arômes de violette, de sous-bois et de fruits rouges. Équilibre parfait.</div><div class=\"wine-features\"><span class=\"wine-feature\"><i class=\"fas fa-star\"></i> 98/100 Parker</span><span class=\"wine-feature\"><i class=\"fas fa-clock\"></i> Garde 20 ans</span></div><div class=\"wine-footer\"><span class=\"wine-price\">€ 890 <span>/ bouteille</span></span><button class=\"wine-order\" onclick=\"alert(\'Ajouté à votre commande !\')\">Commander</button></div></div></div>\r\n        <div class=\"wine-card\"><div class=\"wine-img\"><img src=\"https://images.unsplash.com/photo-1506377242683-e2cbef21d7a7?w=500&q=80\" alt=\"Côtes du Rhône\"><div class=\"wine-badge silver\">Premier Cru</div></div><div class=\"wine-body\"><div class=\"wine-name\">Châteauneuf-du-Pape</div><div class=\"wine-domain\">Rhône, France · 2020</div><div class=\"wine-description\">Robe intense, arômes de fruits confits, de garrigue et d\'épices. Corps puissant, tanins fins.</div><div class=\"wine-features\"><span class=\"wine-feature\"><i class=\"fas fa-star\"></i> 92/100 Parker</span><span class=\"wine-feature\"><i class=\"fas fa-clock\"></i> Garde 8-12 ans</span></div><div class=\"wine-footer\"><span class=\"wine-price\">€ 98 <span>/ bouteille</span></span><button class=\"wine-order\" onclick=\"alert(\'Ajouté à votre commande !\')\">Commander</button></div></div></div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Panel Vins Blancs -->\r\n    <div class=\"wine-panel\" id=\"wine-blanc\">\r\n      <div class=\"wine-grid\">\r\n        <div class=\"wine-card\"><div class=\"wine-img\"><img src=\"https://images.unsplash.com/photo-1567529696075-07dfe13ab9a5?w=500&q=80\" alt=\"Sancerre\"><div class=\"wine-badge silver\">Premier Cru</div></div><div class=\"wine-body\"><div class=\"wine-name\">Sancerre Blanc</div><div class=\"wine-domain\">Loire, France · 2022</div><div class=\"wine-description\">Nez d\'agrumes et de fleurs blanches. Bouche fraîche, minérale, avec une belle finale persistante.</div><div class=\"wine-features\"><span class=\"wine-feature\"><i class=\"fas fa-star\"></i> 90/100 Parker</span><span class=\"wine-feature\"><i class=\"fas fa-leaf\"></i> Bio</span></div><div class=\"wine-footer\"><span class=\"wine-price\">€ 45 <span>/ bouteille</span></span><button class=\"wine-order\" onclick=\"alert(\'Ajouté à votre commande !\')\">Commander</button></div></div></div>\r\n        <div class=\"wine-card\"><div class=\"wine-img\"><img src=\"https://images.unsplash.com/photo-1567529696075-07dfe13ab9a5?w=500&q=80\" alt=\"Chablis\"><div class=\"wine-badge gold\">Grand Cru</div></div><div class=\"wine-body\"><div class=\"wine-name\">Chablis Grand Cru</div><div class=\"wine-domain\">Bourgogne, France · 2021</div><div class=\"wine-description\">Minéralité intense, notes de citron vert et de silex. Bouche tendue et saline, grande finesse.</div><div class=\"wine-features\"><span class=\"wine-feature\"><i class=\"fas fa-star\"></i> 94/100 Parker</span><span class=\"wine-feature\"><i class=\"fas fa-clock\"></i> Garde 10 ans</span></div><div class=\"wine-footer\"><span class=\"wine-price\">€ 78 <span>/ bouteille</span></span><button class=\"wine-order\" onclick=\"alert(\'Ajouté à votre commande !\')\">Commander</button></div></div></div>\r\n        <div class=\"wine-card\"><div class=\"wine-img\"><img src=\"https://images.unsplash.com/photo-1567529696075-07dfe13ab9a5?w=500&q=80\" alt=\"Pouilly-Fumé\"><div class=\"wine-badge silver\">Premier Cru</div></div><div class=\"wine-body\"><div class=\"wine-name\">Pouilly-Fumé</div><div class=\"wine-domain\">Loire, France · 2022</div><div class=\"wine-description\">Arômes fumés et d\'agrumes. Attaque vive, rondeur équilibrée, finale sur des notes de pierre à fusil.</div><div class=\"wine-features\"><span class=\"wine-feature\"><i class=\"fas fa-star\"></i> 89/100 Parker</span><span class=\"wine-feature\"><i class=\"fas fa-wine-glass\"></i> Apéritif</span></div><div class=\"wine-footer\"><span class=\"wine-price\">€ 52 <span>/ bouteille</span></span><button class=\"wine-order\" onclick=\"alert(\'Ajouté à votre commande !\')\">Commander</button></div></div></div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Panel Champagne -->\r\n    <div class=\"wine-panel\" id=\"wine-champagne\">\r\n      <div class=\"wine-grid\">\r\n        <div class=\"wine-card\"><div class=\"wine-img\"><img src=\"https://images.unsplash.com/photo-1567170244009-223f0ab2cf7b?w=500&q=80\" alt=\"Champagne Dom Pérignon\"><div class=\"wine-badge gold\">Prestige</div></div><div class=\"wine-body\"><div class=\"wine-name\">Dom Pérignon</div><div class=\"wine-domain\">Champagne, France · 2012</div><div class=\"wine-description\">Le champagne légendaire. Notes de brioche, d\'amande et de fruits secs. Bulles fines et élégantes.</div><div class=\"wine-features\"><span class=\"wine-feature\"><i class=\"fas fa-star\"></i> 96/100 Parker</span><span class=\"wine-feature\"><i class=\"fas fa-gem\"></i> Vintage</span></div><div class=\"wine-footer\"><span class=\"wine-price\">€ 195 <span>/ bouteille</span></span><button class=\"wine-order\" onclick=\"alert(\'Ajouté à votre commande !\')\">Commander</button></div></div></div>\r\n        <div class=\"wine-card\"><div class=\"wine-img\"><img src=\"https://images.unsplash.com/photo-1567170244009-223f0ab2cf7b?w=500&q=80\" alt=\"Champagne Ruinart\"><div class=\"wine-badge silver\">Grand Cru</div></div><div class=\"wine-body\"><div class=\"wine-name\">Ruinart Blanc de Blancs</div><div class=\"wine-domain\">Champagne, France · 2018</div><div class=\"wine-description\">100% Chardonnay. Notes d\'agrumes, de fleurs blanches et de fruits à chair blanche. Finesse exceptionnelle.</div><div class=\"wine-features\"><span class=\"wine-feature\"><i class=\"fas fa-star\"></i> 93/100 Parker</span><span class=\"wine-feature\"><i class=\"fas fa-leaf\"></i> Bio</span></div><div class=\"wine-footer\"><span class=\"wine-price\">€ 89 <span>/ bouteille</span></span><button class=\"wine-order\" onclick=\"alert(\'Ajouté à votre commande !\')\">Commander</button></div></div></div>\r\n        <div class=\"wine-card\"><div class=\"wine-img\"><img src=\"https://images.unsplash.com/photo-1567170244009-223f0ab2cf7b?w=500&q=80\" alt=\"Moët & Chandon\"><div class=\"wine-badge bronze\">Cuvée</div></div><div class=\"wine-body\"><div class=\"wine-name\">Moët & Chandon Impérial</div><div class=\"wine-domain\">Champagne, France · 2020</div><div class=\"wine-description\">Le champagne référence. Fruité, équilibré, frais avec des notes de pomme verte et de brioche légère.</div><div class=\"wine-features\"><span class=\"wine-feature\"><i class=\"fas fa-star\"></i> 88/100 Parker</span><span class=\"wine-feature\"><i class=\"fas fa-heart\"></i> Coup de cœur</span></div><div class=\"wine-footer\"><span class=\"wine-price\">€ 55 <span>/ bouteille</span></span><button class=\"wine-order\" onclick=\"alert(\'Ajouté à votre commande !\')\">Commander</button></div></div></div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Panel International -->\r\n    <div class=\"wine-panel\" id=\"wine-international\">\r\n      <div class=\"wine-grid\">\r\n        <div class=\"wine-card\"><div class=\"wine-img\"><img src=\"https://images.unsplash.com/photo-1584917090143-b7f392a8eb48?w=500&q=80\" alt=\"Barolo\"><div class=\"wine-badge gold\">Grand Cru</div></div><div class=\"wine-body\"><div class=\"wine-name\">Barolo Riserva</div><div class=\"wine-domain\">Piémont, Italie · 2016</div><div class=\"wine-description\">Le roi des vins italiens. Tanins puissants, arômes de rose, de réglisse et de fruits noirs. Structure magistrale.</div><div class=\"wine-features\"><span class=\"wine-feature\"><i class=\"fas fa-star\"></i> 94/100 Parker</span><span class=\"wine-feature\"><i class=\"fas fa-clock\"></i> Garde 15 ans</span></div><div class=\"wine-footer\"><span class=\"wine-price\">€ 120 <span>/ bouteille</span></span><button class=\"wine-order\" onclick=\"alert(\'Ajouté à votre commande !\')\">Commander</button></div></div></div>\r\n        <div class=\"wine-card\"><div class=\"wine-img\"><img src=\"https://images.unsplash.com/photo-1584917090143-b7f392a8eb48?w=500&q=80\" alt=\"Rioja\"><div class=\"wine-badge silver\">Gran Reserva</div></div><div class=\"wine-body\"><div class=\"wine-name\">Rioja Gran Reserva</div><div class=\"wine-domain\">La Rioja, Espagne · 2015</div><div class=\"wine-description\">Élevage long en fût. Arômes de cuir, de tabac, de prune et d\'épices. Bouche ample et soyeuse.</div><div class=\"wine-features\"><span class=\"wine-feature\"><i class=\"fas fa-star\"></i> 91/100 Parker</span><span class=\"wine-feature\"><i class=\"fas fa-wood\"></i> 24 mois fût</span></div><div class=\"wine-footer\"><span class=\"wine-price\">€ 65 <span>/ bouteille</span></span><button class=\"wine-order\" onclick=\"alert(\'Ajouté à votre commande !\')\">Commander</button></div></div></div>\r\n        <div class=\"wine-card\"><div class=\"wine-img\"><img src=\"https://images.unsplash.com/photo-1584917090143-b7f392a8eb48?w=500&q=80\" alt=\"Brunello\"><div class=\"wine-badge silver\">Premier Cru</div></div><div class=\"wine-body\"><div class=\"wine-name\">Brunello di Montalcino</div><div class=\"wine-domain\">Toscane, Italie · 2017</div><div class=\"wine-description\">Cépage Sangiovese. Arômes de fruits rouges, de tabac et d\'herbes séchées. Tanins élégants et persistants.</div><div class=\"wine-features\"><span class=\"wine-feature\"><i class=\"fas fa-star\"></i> 92/100 Parker</span><span class=\"wine-feature\"><i class=\"fas fa-mountain\"></i> Toscane</span></div><div class=\"wine-footer\"><span class=\"wine-price\">€ 85 <span>/ bouteille</span></span><button class=\"wine-order\" onclick=\"alert(\'Ajouté à votre commande !\')\">Commander</button></div></div></div>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"text-center mt-5\">\r\n      <a href=\"#reservation\" class=\"btn btn-gold\" style=\"display:inline-flex;align-items:center;gap:0.5rem;padding:0.85rem 2rem;border-radius:50px;font-size:0.9rem;font-weight:600;background:#C89B3C;color:#fff;text-decoration:none;\">Voir la Cave Complète <i class=\"fas fa-arrow-right\"></i></a>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n(function(){\r\n  var catBtns = document.querySelectorAll(\'.wine-cat-btn\');\r\n  var panels = document.querySelectorAll(\'.wine-panel\');\r\n  catBtns.forEach(function(btn) {\r\n    btn.addEventListener(\'click\', function() {\r\n      catBtns.forEach(function(b) { b.classList.remove(\'active\'); });\r\n      btn.classList.add(\'active\');\r\n      var cat = btn.getAttribute(\'data-cat\');\r\n      panels.forEach(function(panel) { panel.classList.remove(\'active\'); });\r\n      var targetPanel = document.getElementById(\'wine-\' + cat);\r\n      if(targetPanel) targetPanel.classList.add(\'active\');\r\n    });\r\n  });\r\n})();\r\n</script>', 'wine-section {\r\n  padding: 6rem 0;\r\n  background: #fff;\r\n}\r\n.section-header {\r\n  text-align: center;\r\n  margin-bottom: 3.5rem;\r\n}\r\n.section-tag {\r\n  display: inline-block;\r\n  font-size: 0.78rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: #C89B3C;\r\n  margin-bottom: 0.75rem;\r\n}\r\n.section-tag::before { content: \'—  \'; }\r\n.section-tag::after { content: \'  —\'; }\r\n.section-title {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: clamp(1.9rem, 3.5vw, 2.8rem);\r\n  font-weight: 600;\r\n  color: #1E1E1E;\r\n  line-height: 1.25;\r\n  margin-bottom: 1.25rem;\r\n}\r\n.section-title em {\r\n  font-style: italic;\r\n  color: #C89B3C;\r\n}\r\n.section-subtitle {\r\n  font-size: 1.05rem;\r\n  color: #666;\r\n  max-width: 600px;\r\n  margin: 0 auto;\r\n}\r\n.wine-categories {\r\n  display: flex;\r\n  justify-content: center;\r\n  gap: 0.5rem;\r\n  flex-wrap: wrap;\r\n  margin-bottom: 3rem;\r\n}\r\n.wine-cat-btn {\r\n  padding: 0.65rem 1.8rem;\r\n  border-radius: 50px;\r\n  font-size: 0.85rem;\r\n  font-weight: 600;\r\n  color: #666;\r\n  border: 1px solid #e8e0d0;\r\n  background: #fff;\r\n  transition: all 0.35s ease;\r\n  cursor: pointer;\r\n}\r\n.wine-cat-btn:hover {\r\n  color: #C89B3C;\r\n  border-color: #C89B3C;\r\n}\r\n.wine-cat-btn.active {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  border-color: #C89B3C;\r\n}\r\n.wine-panel {\r\n  display: none;\r\n}\r\n.wine-panel.active {\r\n  display: block;\r\n}\r\n.wine-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(3, 1fr);\r\n  gap: 2rem;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n.wine-card {\r\n  background: #fff;\r\n  border: 1px solid #e8e0d0;\r\n  border-radius: 16px;\r\n  overflow: hidden;\r\n  transition: all 0.35s ease;\r\n  position: relative;\r\n}\r\n.wine-card:hover {\r\n  transform: translateY(-6px);\r\n  box-shadow: 0 16px 40px rgba(0,0,0,0.1);\r\n  border-color: #C89B3C;\r\n}\r\n.wine-img {\r\n  position: relative;\r\n  height: 200px;\r\n  overflow: hidden;\r\n}\r\n.wine-img img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n  transition: transform 0.5s ease;\r\n}\r\n.wine-card:hover .wine-img img {\r\n  transform: scale(1.08);\r\n}\r\n.wine-badge {\r\n  position: absolute;\r\n  top: 12px;\r\n  right: 12px;\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  font-size: 0.7rem;\r\n  font-weight: 700;\r\n  letter-spacing: 0.05em;\r\n  padding: 0.25rem 0.8rem;\r\n  border-radius: 50px;\r\n}\r\n.wine-badge.gold {\r\n  background: linear-gradient(135deg, #C89B3C, #a07820);\r\n}\r\n.wine-badge.silver {\r\n  background: linear-gradient(135deg, #8a8a8a, #6a6a6a);\r\n}\r\n.wine-badge.bronze {\r\n  background: linear-gradient(135deg, #cd7f32, #a06020);\r\n}\r\n.wine-body {\r\n  padding: 1.5rem;\r\n}\r\n.wine-name {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.2rem;\r\n  font-weight: 700;\r\n  color: #1E1E1E;\r\n  margin-bottom: 0.25rem;\r\n}\r\n.wine-domain {\r\n  font-size: 0.85rem;\r\n  color: #C89B3C;\r\n  font-weight: 600;\r\n  margin-bottom: 0.75rem;\r\n  letter-spacing: 0.5px;\r\n}\r\n.wine-description {\r\n  font-size: 0.85rem;\r\n  color: #666;\r\n  line-height: 1.6;\r\n  margin-bottom: 1rem;\r\n}\r\n.wine-features {\r\n  display: flex;\r\n  gap: 1rem;\r\n  margin-bottom: 1rem;\r\n  font-size: 0.75rem;\r\n  color: #999;\r\n}\r\n.wine-feature {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.3rem;\r\n}\r\n.wine-feature i {\r\n  color: #C89B3C;\r\n  font-size: 0.7rem;\r\n}\r\n.wine-footer {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  border-top: 1px solid #e8e0d0;\r\n  padding-top: 1rem;\r\n}\r\n.wine-price {\r\n  font-family: \'Playfair Display\', serif;\r\n  font-size: 1.3rem;\r\n  font-weight: 700;\r\n  color: #C89B3C;\r\n}\r\n.wine-price span {\r\n  font-size: 0.8rem;\r\n  font-weight: 400;\r\n  color: #999;\r\n}\r\n.wine-order {\r\n  background: #C89B3C;\r\n  color: #fff;\r\n  border: none;\r\n  padding: 0.5rem 1.2rem;\r\n  border-radius: 50px;\r\n  font-size: 0.75rem;\r\n  font-weight: 600;\r\n  cursor: pointer;\r\n  transition: all 0.35s ease;\r\n}\r\n.wine-order:hover {\r\n  background: #a07820;\r\n  transform: scale(1.02);\r\n}\r\n.wine-note {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 0.3rem;\r\n  background: #F8F8F8;\r\n  padding: 0.25rem 0.6rem;\r\n  border-radius: 50px;\r\n  font-size: 0.7rem;\r\n  color: #C89B3C;\r\n}\r\n@media (max-width: 1024px) {\r\n  .wine-grid { grid-template-columns: repeat(2, 1fr); }\r\n}\r\n@media (max-width: 768px) {\r\n  .wine-grid { grid-template-columns: 1fr; }\r\n  .wine-categories { gap: 0.3rem; }\r\n  .wine-cat-btn { padding: 0.5rem 1.2rem; font-size: 0.75rem; }\r\n}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 2, 0, 0, 1, '2026-06-03 12:39:13', '2026-07-25 19:50:23'),
(177, NULL, 'Top Bar (garage template', 'top-bar-garage-template', NULL, NULL, 'fa-cube', '<div class=\"topbar\">\r\n  <div class=\"topbar-inner\">\r\n    <div class=\"topbar-left\">\r\n      <div class=\"topbar-item\"><svg width=\"14\" height=\"14\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z\"/><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M15 11a3 3 0 11-6 0 3 3 0 016 0z\"/></svg>12 Rue de la Mécanique, 75011 Paris</div>\r\n      <div class=\"topbar-item\"><svg width=\"14\" height=\"14\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>Lun–Ven : 8h–18h &nbsp;|&nbsp; Sam : 8h–13h</div>\r\n      <div class=\"topbar-item\"><svg width=\"14\" height=\"14\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 7V5z\"/></svg><a href=\"tel:+33123456789\">01 23 45 67 89</a></div>\r\n    </div>\r\n    <div class=\"topbar-right\"><div class=\"topbar-social\"><a href=\"#\">f</a><a href=\"#\">in</a><a href=\"#\">ig</a></div><a href=\"#contact\" class=\"topbar-cta\">Urgence 24/7</a></div>\r\n  </div>\r\n</div>', '.topbar{background:#0A0A0A;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06);margin-bottom:0;}\r\n.topbar-inner{max-width:1280px;margin:0 auto;padding:0 40px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;}\r\n.topbar-left{display:flex;gap:28px;align-items:center;flex-wrap:wrap;}\r\n.topbar-item{display:flex;align-items:center;gap:8px;font-size:12px;color:rgba(255,255,255,.55);letter-spacing:.5px;}\r\n.topbar-item svg{flex-shrink:0;color:#D4A537;}\r\n.topbar-item a{color:rgba(255,255,255,.55);transition:color .2s;text-decoration:none;}\r\n.topbar-item a:hover{color:#D4A537;}\r\n.topbar-right{display:flex;align-items:center;gap:16px;}\r\n.topbar-social a{width:30px;height:30px;border-radius:50%;border:1px solid rgba(255,255,255,.12);display:inline-flex;align-items:center;justify-content:center;font-size:12px;color:rgba(255,255,255,.5);transition:all .2s;text-decoration:none;}\r\n.topbar-social a:hover{border-color:#D4A537;color:#D4A537;}\r\n.topbar-cta{background:#D4A537;color:#0A0A0A;font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;padding:7px 18px;text-decoration:none;display:inline-block;}\r\n@media(max-width:768px){.topbar-left .topbar-item:not(:first-child){display:none;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-04 08:26:46', '2026-06-04 08:27:35'),
(178, NULL, 'Navigation bar (garage template)', 'navigation-bar-garage-template', NULL, NULL, 'fa-cube', '<nav class=\"navbar\" id=\"navbar\">\r\n  <div class=\"nav-inner\">\r\n    <a href=\"#\" class=\"nav-logo\"><div class=\"nav-logo-icon\">⚙</div>AUTO<span>ELITE</span></a>\r\n    <ul class=\"nav-links\"><li class=\"active\"><a href=\"#services\">Services</a></li><li><a href=\"#portfolio\">Réalisations</a></li><li><a href=\"#pricing\">Tarifs</a></li><li><a href=\"#team\">Équipe</a></li><li><a href=\"#faq\">FAQ</a></li><li><a href=\"#contact\">Contact</a></li></ul>\r\n    <div class=\"nav-right\"><div class=\"nav-tel\">📞 <span>01 23 45 67 89</span></div><a href=\"#contact\" class=\"btn-prim\">Prendre RDV</a></div>\r\n    <div class=\"burger\" id=\"burger\"><span></span><span></span><span></span></div>\r\n  </div>\r\n</nav>\r\n\r\n<div class=\"mob-overlay\" id=\"mobOverlay\"></div>\r\n<div class=\"mobile-nav\" id=\"mobileNav\">\r\n  <button class=\"mobile-close\">✕</button>\r\n  <a href=\"#services\">Services</a>\r\n  <a href=\"#portfolio\">Réalisations</a>\r\n  <a href=\"#pricing\">Tarifs</a>\r\n  <a href=\"#team\">Équipe</a>\r\n  <a href=\"#faq\">FAQ</a>\r\n  <a href=\"#contact\">Contact</a>\r\n  <a href=\"#contact\" class=\"mob-cta\">📅 Prendre RDV</a>\r\n</div>\r\n\r\n<script>\r\n(function(){\r\n  var navbar = document.getElementById(\'navbar\');\r\n  var burger = document.getElementById(\'burger\');\r\n  var mobileNav = document.getElementById(\'mobileNav\');\r\n  var mobOverlay = document.getElementById(\'mobOverlay\');\r\n  var mobileClose = document.querySelector(\'.mobile-close\');\r\n  function openMob(){mobileNav.classList.add(\'open\');if(mobOverlay)mobOverlay.classList.add(\'open\');document.body.style.overflow=\'hidden\';}\r\n  function closeMob(){mobileNav.classList.remove(\'open\');if(mobOverlay)mobOverlay.classList.remove(\'open\');document.body.style.overflow=\'\';}\r\n  if(burger)burger.addEventListener(\'click\',openMob);\r\n  if(mobileClose)mobileClose.addEventListener(\'click\',closeMob);\r\n  if(mobOverlay)mobOverlay.addEventListener(\'click\',closeMob);\r\n  window.addEventListener(\'scroll\',function(){navbar.classList.toggle(\'scrolled\',window.scrollY>60);});\r\n})();\r\n</script>', '.navbar{position:sticky;top:0;z-index:900;background:#fff;border-bottom:1px solid rgba(0,0,0,.08);transition:box-shadow .3s;}\r\n.navbar.scrolled{box-shadow:0 4px 30px rgba(0,0,0,.1);}\r\n.nav-inner{max-width:1280px;margin:0 auto;padding:0 40px;display:flex;align-items:center;justify-content:space-between;height:72px;}\r\n.nav-logo{font-family:\'Bebas Neue\',sans-serif;font-size:26px;letter-spacing:3px;color:#1A1A1A;display:flex;align-items:center;gap:12px;text-decoration:none;}\r\n.nav-logo-icon{width:40px;height:40px;background:#D4A537;display:flex;align-items:center;justify-content:center;font-size:18px;}\r\n.nav-logo span{color:#D4A537;}\r\n.nav-links{display:flex;gap:0;list-style:none;}\r\n.nav-links>li{position:relative;}\r\n.nav-links>li>a{display:block;padding:0 18px;font-size:13px;font-weight:600;letter-spacing:.5px;color:#1A1A1A;height:72px;line-height:72px;transition:color .2s;white-space:nowrap;text-decoration:none;}\r\n.nav-links>li>a:hover,.nav-links>li.active>a{color:#D4A537;}\r\n.nav-links>li>a::after{content:\'\';position:absolute;bottom:0;left:18px;right:18px;height:2px;background:#D4A537;transform:scaleX(0);transition:transform .25s;}\r\n.nav-links>li>a:hover::after,.nav-links>li.active>a::after{transform:scaleX(1);}\r\n.nav-right{display:flex;align-items:center;gap:16px;}\r\n.nav-tel{font-size:14px;font-weight:700;color:#1A1A1A;}\r\n.nav-tel span{color:#D4A537;}\r\n.btn-prim{display:inline-flex;align-items:center;gap:10px;background:#D4A537;color:#1A1A1A;font-size:13px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;padding:12px 28px;border:2px solid #D4A537;transition:all .25s;text-decoration:none;}\r\n.btn-prim:hover{background:#b8891e;border-color:#b8891e;transform:translateY(-2px);}\r\n.burger{display:none;flex-direction:column;gap:5px;cursor:pointer;padding:6px;}\r\n.burger span{display:block;width:24px;height:2px;background:#1A1A1A;border-radius:2px;transition:all .3s;}\r\n.mobile-nav{position:fixed;inset:0;background:#fff;z-index:9999;display:flex;flex-direction:column;padding:24px 28px;transform:translateX(-100%);transition:transform .35s ease;}\r\n.mobile-nav.open{transform:translateX(0);}\r\n.mobile-close{align-self:flex-end;font-size:26px;cursor:pointer;color:#1A1A1A;background:none;border:none;font-family:inherit;line-height:1;margin-bottom:32px;}\r\n.mobile-nav a{display:block;padding:14px 0;font-size:18px;font-weight:700;color:#1A1A1A;border-bottom:1px solid rgba(0,0,0,.07);letter-spacing:.5px;text-decoration:none;}\r\n.mobile-nav a:hover{color:#D4A537;}\r\n.mobile-nav .mob-cta{margin-top:24px;background:#D4A537;color:#1A1A1A;text-align:center;padding:16px;font-size:14px;font-weight:700;letter-spacing:2px;text-transform:uppercase;border-bottom:none;}\r\n.mob-overlay{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9998;opacity:0;pointer-events:none;transition:opacity .35s;}\r\n.mob-overlay.open{opacity:1;pointer-events:auto;}\r\n@media(max-width:768px){.nav-links,.nav-right{display:none;}.burger{display:flex;}}', NULL, NULL, 'Header', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-04 08:28:31', '2026-06-04 22:08:50'),
(179, NULL, 'Section hero garage theme', 'section-hero-garage-theme', NULL, NULL, 'fa-cube', '<section class=\"hero\">\r\n  <div class=\"hero-left\"><div class=\"hero-bg-pattern\"></div>\r\n    <div class=\"hero-content\">\r\n      <div class=\"hero-eyebrow\"><div class=\"hero-eyebrow-line\"></div><span>Garage Certifié Toutes Marques — Paris</span></div>\r\n      <h1>VOTRE AUTO<br><em>MÉRITE</em><br>LE<br>MEILLEUR.</h1>\r\n      <p class=\"hero-desc\">Expert en mécanique, carrosserie et diagnostic électronique depuis 1998. Confiance, rapidité, excellence.</p>\r\n      <div class=\"hero-actions\"><a href=\"#contact\" class=\"btn-prim\">📅 Prendre Rendez-vous</a><a href=\"#services\" class=\"btn-line\">Voir nos services</a></div>\r\n      <div class=\"hero-trust\"><div class=\"hero-trust-item\"><div class=\"hero-trust-icon\">🏆</div><div class=\"hero-trust-text\"><strong>Certifié</strong>Toutes marques</div></div><div class=\"hero-trust-item\"><div class=\"hero-trust-icon\">✅</div><div class=\"hero-trust-text\"><strong>Garantie</strong>12 mois / 20 000 km</div></div><div class=\"hero-trust-item\"><div class=\"hero-trust-icon\">⚡</div><div class=\"hero-trust-text\"><strong>Urgences</strong>Prise en charge rapide</div></div></div>\r\n    </div>\r\n  </div>\r\n  <div class=\"hero-right\"><div class=\"hero-img\"><img src=\"https://images.unsplash.com/photo-1492144534655-ae79c964c9d7?w=1200&q=85&fit=crop\" alt=\"Garage AutoElite\"></div><div class=\"hero-stats-bar\"><div class=\"hero-stat\"><div class=\"hero-stat-num\">15 000+</div><div class=\"hero-stat-label\">Clients satisfaits</div></div><div class=\"hero-stat\"><div class=\"hero-stat-num\">25+</div><div class=\"hero-stat-label\">Ans d\'expérience</div></div><div class=\"hero-stat\"><div class=\"hero-stat-num\">98%</div><div class=\"hero-stat-label\">Satisfaction</div></div></div></div>\r\n</section>', '.hero{position:relative;min-height:100vh;display:flex;align-items:stretch;overflow:hidden;}\r\n.hero-left{flex:1.1;position:relative;display:flex;flex-direction:column;justify-content:center;padding:80px 60px 80px 80px;background:#111111;}\r\n.hero-left::after{content:\'\';position:absolute;top:0;right:-1px;bottom:0;width:80px;background:#111111;clip-path:polygon(0 0,100% 0,100% 100%,0 100%);z-index:2;}\r\n.hero-bg-pattern{position:absolute;inset:0;opacity:.04;background-image:repeating-linear-gradient(0deg,transparent,transparent 59px,rgba(255,255,255,.4) 59px,rgba(255,255,255,.4) 60px),repeating-linear-gradient(90deg,transparent,transparent 59px,rgba(255,255,255,.4) 59px,rgba(255,255,255,.4) 60px);}\r\n.hero-content{position:relative;z-index:3;max-width:560px;}\r\n.hero-eyebrow{display:flex;align-items:center;gap:12px;margin-bottom:28px;}\r\n.hero-eyebrow-line{width:40px;height:2px;background:#D4A537;}\r\n.hero-eyebrow span{font-size:11px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:#D4A537;}\r\n.hero h1{font-family:\'Bebas Neue\',sans-serif;font-size:clamp(60px,7vw,100px);line-height:.92;color:#fff;margin-bottom:28px;letter-spacing:1px;}\r\n.hero h1 em{color:#D4A537;font-style:normal;}\r\n.hero-desc{font-size:16px;color:rgba(255,255,255,.6);line-height:1.8;margin-bottom:40px;max-width:420px;}\r\n.hero-actions{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:56px;}\r\n.btn-line{display:inline-flex;align-items:center;gap:10px;background:transparent;color:#fff;font-size:13px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;padding:14px 32px;border:2px solid rgba(255,255,255,.4);transition:all .25s;text-decoration:none;}\r\n.btn-line:hover{border-color:#D4A537;color:#D4A537;}\r\n.hero-trust{display:flex;gap:32px;flex-wrap:wrap;}\r\n.hero-trust-item{display:flex;align-items:center;gap:10px;}\r\n.hero-trust-icon{width:36px;height:36px;border:1px solid rgba(212,165,55,.3);display:flex;align-items:center;justify-content:center;font-size:15px;}\r\n.hero-trust-text{font-size:12px;color:rgba(255,255,255,.45);letter-spacing:.5px;}\r\n.hero-trust-text strong{display:block;font-size:13px;color:#fff;letter-spacing:0;font-weight:700;}\r\n.hero-right{flex:1;position:relative;min-height:500px;}\r\n.hero-img{position:absolute;inset:0;}\r\n.hero-img img{width:100%;height:100%;object-fit:cover;}\r\n.hero-img::after{content:\'\';position:absolute;inset:0;background:linear-gradient(to right,rgba(17,17,17,.3) 0%,transparent 40%);}\r\n.hero-stats-bar{position:absolute;bottom:0;left:0;right:0;background:#D4A537;display:flex;z-index:10;}\r\n.hero-stat{flex:1;padding:22px 24px;border-right:1px solid rgba(0,0,0,.12);text-align:center;}\r\n.hero-stat:last-child{border-right:none;}\r\n.hero-stat-num{font-family:\'Bebas Neue\',sans-serif;font-size:36px;color:#0A0A0A;line-height:1;}\r\n.hero-stat-label{font-size:11px;font-weight:600;color:rgba(0,0,0,.6);text-transform:uppercase;letter-spacing:1.5px;margin-top:2px;}\r\n@media(max-width:768px){.hero{flex-direction:column;}.hero-left{padding:80px 24px 40px;}.hero-left::after{display:none;}.hero-right{min-height:320px;}.hero-stats-bar{position:static;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-04 08:31:05', '2026-06-04 08:41:52'),
(180, NULL, 'Services Strip garage theme', 'services-strip-garage-theme', NULL, NULL, 'fa-cube', '<div class=\"services-strip\">\r\n  <div class=\"services-strip-grid\">\r\n    <div class=\"sstrip-item\"><div class=\"sstrip-icon\">🔧</div><div class=\"sstrip-text\"><h4>Mécanique Générale</h4><p>Entretien, révision, freins, distribution</p></div></div>\r\n    <div class=\"sstrip-item\"><div class=\"sstrip-icon\">🔌</div><div class=\"sstrip-text\"><h4>Diagnostic Électronique</h4><p>Lecture codes, reprogrammation ECU</p></div></div>\r\n    <div class=\"sstrip-item\"><div class=\"sstrip-icon\">🚗</div><div class=\"sstrip-text\"><h4>Carrosserie & Peinture</h4><p>Débosselage, retouche, laquage</p></div></div>\r\n    <div class=\"sstrip-item\"><div class=\"sstrip-icon\">⚡</div><div class=\"sstrip-text\"><h4>Véhicules Électriques</h4><p>Batterie, recharge, haute tension</p></div></div>\r\n  </div>\r\n</div>', '.services-strip{background:#1A1A1A;padding:0;margin-bottom:2rem;}\r\n.services-strip-grid{display:grid;grid-template-columns:repeat(4,1fr);max-width:1280px;margin:0 auto;padding:0 40px;}\r\n.sstrip-item{padding:32px 28px;border-right:1px solid rgba(255,255,255,.06);display:flex;gap:18px;align-items:flex-start;transition:background .25s;cursor:default;}\r\n.sstrip-item:last-child{border-right:none;}\r\n.sstrip-item:hover{background:rgba(212,165,55,.08);}\r\n.sstrip-icon{width:48px;height:48px;background:rgba(212,165,55,.12);border:1px solid rgba(212,165,55,.25);flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:20px;}\r\n.sstrip-text h4{font-size:14px;font-weight:700;color:#fff;margin-bottom:5px;}\r\n.sstrip-text p{font-size:12px;color:#8A8A8A;line-height:1.6;}\r\n@media(max-width:768px){.services-strip-grid{grid-template-columns:1fr 1fr;}}\r\n@media(max-width:480px){.services-strip-grid{grid-template-columns:1fr;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-04 08:35:13', '2026-06-04 08:43:06'),
(181, NULL, 'About', 'about-2', NULL, NULL, 'fa-cube', '<section class=\"about\" id=\"about\">\r\n  <div class=\"container\">\r\n    <div class=\"about-grid\">\r\n      <div class=\"about-imgs\"><div class=\"about-img-main\"><img src=\"https://images.unsplash.com/photo-1625047509248-ec889cbff17f?w=900&q=85&fit=crop\" alt=\"Mécanicien professionnel\"></div><div class=\"about-img-sub\"><img src=\"https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=600&q=85&fit=crop\" alt=\"Atelier AutoElite\"></div><div class=\"about-badge\"><div class=\"about-badge-num\">25</div><div class=\"about-badge-txt\">Ans d\'expertise</div></div></div>\r\n      <div class=\"about-content\"><span class=\"sec-tag\">Qui sommes-nous</span><h2 class=\"sec-title\">VOTRE GARAGE DE<br>CONFIANCE À PARIS</h2><p class=\"sec-sub\">Depuis 1998, AutoElite Garage est le partenaire de confiance des automobilistes parisiens. Nos techniciens certifiés prennent soin de votre véhicule avec le même soin qu\'ils apporteraient au leur.</p><div class=\"about-features\"><div class=\"about-feat\"><div class=\"about-feat-icon\">🏆</div><div><h5>Techniciens certifiés</h5><p>Formation continue par les constructeurs</p></div></div><div class=\"about-feat\"><div class=\"about-feat-icon\">💰</div><div><h5>Devis gratuit</h5><p>Transparence totale sans surprise</p></div></div><div class=\"about-feat\"><div class=\"about-feat-icon\">🚘</div><div><h5>Véhicule de prêt</h5><p>Disponible pour toute intervention longue</p></div></div><div class=\"about-feat\"><div class=\"about-feat-icon\">🛡️</div><div><h5>Garantie 12 mois</h5><p>Sur pièces et main d\'œuvre</p></div></div></div><div class=\"about-ctas\"><a href=\"#contact\" class=\"btn-prim\">Prendre RDV</a><a href=\"#portfolio\" class=\"btn-dark-line\">Voir nos travaux</a></div></div>\r\n    </div>\r\n  </div>\r\n</section>', '.about{padding:110px 0;background:#fff;overflow:hidden;}\r\n.container{max-width:1280px;margin:0 auto;padding:0 40px;}\r\n.sec-tag{display:inline-block;font-size:11px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:#D4A537;padding:0;margin-bottom:14px;}\r\n.sec-tag::before{content:\'— \';}\r\n.sec-title{font-family:\'Bebas Neue\',sans-serif;font-size:clamp(38px,5vw,62px);line-height:1.0;letter-spacing:1px;color:#1A1A1A;}\r\n.sec-sub{font-size:16px;color:#8A8A8A;line-height:1.8;margin-top:14px;}\r\n.about-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;}\r\n.about-imgs{position:relative;}\r\n.about-img-main{width:100%;aspect-ratio:4/5;border-radius:0;overflow:hidden;position:relative;}\r\n.about-img-main img{width:100%;height:100%;object-fit:cover;transition:transform .6s ease;}\r\n.about-img-main:hover img{transform:scale(1.03);}\r\n.about-img-sub{position:absolute;bottom:-40px;right:-40px;width:55%;aspect-ratio:1;overflow:hidden;border:6px solid #fff;box-shadow:0 20px 60px rgba(0,0,0,.15);}\r\n.about-img-sub img{width:100%;height:100%;object-fit:cover;}\r\n.about-badge{position:absolute;top:32px;left:-20px;background:#D4A537;padding:24px 22px;text-align:center;z-index:2;}\r\n.about-badge-num{font-family:\'Bebas Neue\',sans-serif;font-size:52px;color:#1A1A1A;line-height:1;}\r\n.about-badge-txt{font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#1A1A1A;margin-top:2px;}\r\n.about-content{padding-right:20px;}\r\n.about-features{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:36px;}\r\n.about-feat{display:flex;gap:14px;align-items:flex-start;}\r\n.about-feat-icon{width:42px;height:42px;background:#F5F3EF;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:18px;}\r\n.about-feat h5{font-size:13px;font-weight:700;color:#1A1A1A;margin-bottom:3px;}\r\n.about-feat p{font-size:12px;color:#8A8A8A;line-height:1.6;}\r\n.about-ctas{display:flex;gap:16px;margin-top:36px;flex-wrap:wrap;align-items:center;}\r\n.btn-dark-line{display:inline-flex;align-items:center;gap:10px;background:transparent;color:#1A1A1A;font-size:13px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;padding:14px 32px;border:2px solid #1A1A1A;transition:all .25s;text-decoration:none;}\r\n.btn-dark-line:hover{background:#1A1A1A;color:#fff;}\r\n@media(max-width:1100px){.about-grid{grid-template-columns:1fr;gap:48px;}.about-img-sub{right:-20px;bottom:-20px;}}\r\n@media(max-width:768px){.about-img-sub{display:none;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-04 08:36:55', '2026-06-04 08:43:08');
INSERT INTO `blocks` (`id`, `categorie_id`, `name`, `slug`, `description`, `thumbnail`, `icon`, `html_content`, `css_content`, `js_content`, `section_id`, `category`, `website_type`, `tags`, `is_responsive`, `is_free`, `width`, `height`, `usage_count`, `views_count`, `rating`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(182, NULL, 'Section service full', 'section-service-full', NULL, NULL, 'fa-cube', '<section class=\"services-full\" id=\"services\">\r\n  <div class=\"services-header\"><div><span class=\"sec-tag\">Nos prestations</span><h2 class=\"sec-title\">TOUS NOS<br>SERVICES</h2></div><p class=\"sec-sub\" style=\"max-width:380px;\">Du diagnostic à la livraison, nous couvrons l\'intégralité des besoins de votre véhicule.</p></div>\r\n  <div class=\"services-grid\">\r\n    <div class=\"srv-card\"><div class=\"srv-img\"><img src=\"https://images.unsplash.com/photo-1486262715619-67b85e0b08d3?w=800&q=80&fit=crop\" alt=\"Mécanique générale\"><div class=\"srv-img-overlay\"></div></div><div class=\"srv-body\"><div class=\"srv-icon\">🔧</div><h3>Mécanique Générale</h3><p>Vidange, freins, embrayage, suspension, distribution. Pièces d\'origine garanties constructeur pour tous les modèles.</p><div class=\"srv-price\">À partir de 49€</div></div><div class=\"srv-hover-line\"></div></div>\r\n    <div class=\"srv-card\"><div class=\"srv-img\"><img src=\"https://images.unsplash.com/photo-1621905251189-08b45d6a269e?w=800&q=80&fit=crop\" alt=\"Diagnostic\"><div class=\"srv-img-overlay\"></div></div><div class=\"srv-body\"><div class=\"srv-icon\">🔌</div><h3>Diagnostic Électronique</h3><p>Lecture et effacement de codes défauts, reprogrammation calculateur, mise à jour logicielle sur toutes les marques.</p><div class=\"srv-price\">À partir de 35€</div></div><div class=\"srv-hover-line\"></div></div>\r\n    <div class=\"srv-card\"><div class=\"srv-img\"><img src=\"https://images.unsplash.com/photo-1503376780353-7e6692767b70?w=800&q=80&fit=crop\" alt=\"Carrosserie\"><div class=\"srv-img-overlay\"></div></div><div class=\"srv-body\"><div class=\"srv-icon\">🎨</div><h3>Carrosserie & Peinture</h3><p>Débosselage sans peinture, retouche teintée, réparation d\'accidents et laquage cabine pressurisée.</p><div class=\"srv-price\">Devis gratuit</div></div><div class=\"srv-hover-line\"></div></div>\r\n    <div class=\"srv-card\"><div class=\"srv-img\"><img src=\"https://images.unsplash.com/photo-1545558014-8692077e9b5c?w=800&q=80&fit=crop\" alt=\"Climatisation\"><div class=\"srv-img-overlay\"></div></div><div class=\"srv-body\"><div class=\"srv-icon\">❄️</div><h3>Climatisation</h3><p>Recharge gaz R134a et R1234yf, diagnostic circuit, remplacement compresseur, condenseur et filtres habitacle.</p><div class=\"srv-price\">À partir de 79€</div></div><div class=\"srv-hover-line\"></div></div>\r\n    <div class=\"srv-card\"><div class=\"srv-img\"><img src=\"https://images.unsplash.com/photo-1558618047-3c8c76ca7d13?w=800&q=80&fit=crop\" alt=\"Pneumatiques\"><div class=\"srv-img-overlay\"></div></div><div class=\"srv-body\"><div class=\"srv-icon\">🛞</div><h3>Pneumatiques & Géométrie</h3><p>Montage équilibrage toutes dimensions, géométrie 3D laser, permutation et gonflage à l\'azote pur.</p><div class=\"srv-price\">À partir de 15€/pneu</div></div><div class=\"srv-hover-line\"></div></div>\r\n    <div class=\"srv-card\"><div class=\"srv-img\"><img src=\"https://images.unsplash.com/photo-1593941707882-a5bba14938c7?w=800&q=80&fit=crop\" alt=\"VE\"><div class=\"srv-img-overlay\"></div></div><div class=\"srv-body\"><div class=\"srv-icon\">⚡</div><h3>Véhicules Électriques</h3><p>Maintenance batterie haute tension, diagnostic onduleurs, réparation bornes de recharge embarquées.</p><div class=\"srv-price\">À partir de 89€</div></div><div class=\"srv-hover-line\"></div></div>\r\n  </div>\r\n</section>', '.services-full{padding:110px 0;background:#F5F3EF;}\r\n.services-header{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:60px;gap:32px;flex-wrap:wrap;max-width:1280px;margin-left:auto;margin-right:auto;padding:0 40px;}\r\n.services-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:2px;max-width:1280px;margin:0 auto;padding:0 40px;}\r\n.srv-card{background:#fff;overflow:hidden;position:relative;}\r\n.srv-img{height:220px;overflow:hidden;position:relative;}\r\n.srv-img img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease;}\r\n.srv-card:hover .srv-img img{transform:scale(1.06);}\r\n.srv-img-overlay{position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.5),transparent);}\r\n.srv-body{padding:28px 26px 26px;}\r\n.srv-icon{width:50px;height:50px;background:#D4A537;display:flex;align-items:center;justify-content:center;font-size:22px;margin-bottom:16px;}\r\n.srv-body h3{font-size:17px;font-weight:800;color:#1A1A1A;margin-bottom:8px;}\r\n.srv-body p{font-size:13px;color:#8A8A8A;line-height:1.7;margin-bottom:16px;}\r\n.srv-price{font-size:13px;font-weight:700;color:#D4A537;display:flex;align-items:center;gap:8px;}\r\n.srv-price::before{content:\'\';display:block;width:16px;height:2px;background:#D4A537;}\r\n.srv-hover-line{position:absolute;bottom:0;left:0;right:0;height:3px;background:#D4A537;transform:scaleX(0);transform-origin:left;transition:transform .35s;}\r\n.srv-card:hover .srv-hover-line{transform:scaleX(1);}\r\n@media(max-width:768px){.services-grid{grid-template-columns:1fr;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 0, 0, 0, 1, '2026-06-04 08:45:31', '2026-06-04 08:48:16'),
(183, NULL, 'WHY CHOOSE US (Garage theme)', 'why-choose-us-garage-theme', NULL, NULL, 'fa-cube', '<section class=\"why\" id=\"why\">\r\n  <div class=\"why-grid\">\r\n    <div class=\"why-img-wrap\"><div class=\"why-main-img\"><img src=\"https://images.unsplash.com/photo-1644952749732-e10d0fef6bcc?w=900&q=85&fit=crop\" alt=\"Technicien expert\"></div><div class=\"why-counter-box\"><div class=\"why-counter\"><div class=\"why-counter-num\">15 000+</div><div class=\"why-counter-lbl\">Clients</div></div><div class=\"why-counter\"><div class=\"why-counter-num\">98%</div><div class=\"why-counter-lbl\">Satisfaits</div></div><div class=\"why-counter\"><div class=\"why-counter-num\">8</div><div class=\"why-counter-lbl\">Experts</div></div><div class=\"why-counter\"><div class=\"why-counter-num\">25+</div><div class=\"why-counter-lbl\">Années</div></div></div></div>\r\n    <div><span class=\"sec-tag\">Pourquoi nous choisir</span><h2 class=\"sec-title\">EXPERTISE,<br>TRANSPARENCE<br>& CONFIANCE</h2><p class=\"sec-sub\">Plus de 25 ans au service de vos véhicules avec une équipe de passionnés certifiés. Votre satisfaction est notre priorité absolue.</p><div class=\"why-list\"><div class=\"why-item\"><div class=\"why-num\">01</div><div><h4>Techniciens certifiés constructeurs</h4><p>Nos équipes sont régulièrement formées et certifiées BMW, Mercedes, Renault, Peugeot, Toyota et plus encore.</p></div></div><div class=\"why-item\"><div class=\"why-num\">02</div><div><h4>Tarifs clairs, devis gratuit</h4><p>Chaque intervention est précédée d\'un devis détaillé et validé par vous. Aucune mauvaise surprise sur la facture finale.</p></div></div><div class=\"why-item\"><div class=\"why-num\">03</div><div><h4>Garantie 12 mois toutes interventions</h4><p>Pièces et main d\'œuvre garanties 12 mois ou 20 000 km. Nous assumons pleinement notre responsabilité.</p></div></div><div class=\"why-item\"><div class=\"why-num\">04</div><div><h4>Véhicule de prêt & dépannage 7j/7</h4><p>Nous mettons à disposition un véhicule de remplacement et intervenons en urgence le week-end.</p></div></div></div></div>\r\n  </div>\r\n</section>', '.why{padding:110px 0;background:#fff;}\r\n.why-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;max-width:1280px;margin:0 auto;padding:0 40px;}\r\n.why-img-wrap{position:relative;}\r\n.why-main-img{width:100%;aspect-ratio:3/4;overflow:hidden;}\r\n.why-main-img img{width:100%;height:100%;object-fit:cover;}\r\n.why-counter-box{position:absolute;bottom:40px;right:-30px;background:#1A1A1A;padding:28px 32px;display:grid;grid-template-columns:1fr 1fr;gap:1px;background-color:rgba(255,255,255,.15);}\r\n.why-counter{background:#1A1A1A;padding:22px 20px;text-align:center;}\r\n.why-counter-num{font-family:\'Bebas Neue\',sans-serif;font-size:42px;color:#D4A537;line-height:1;}\r\n.why-counter-lbl{font-size:10px;color:rgba(255,255,255,.45);text-transform:uppercase;letter-spacing:2px;margin-top:4px;}\r\n.why-list{display:flex;flex-direction:column;gap:24px;margin-top:36px;}\r\n.why-item{display:flex;gap:18px;align-items:flex-start;padding:22px;border:1px solid rgba(0,0,0,.08);transition:all .3s;cursor:default;}\r\n.why-item:hover{border-color:#D4A537;box-shadow:0 8px 32px rgba(0,0,0,.07);}\r\n.why-num{font-family:\'Bebas Neue\',sans-serif;font-size:32px;color:#D4A537;line-height:1;min-width:36px;}\r\n.why-item h4{font-size:15px;font-weight:700;color:#1A1A1A;margin-bottom:5px;}\r\n.why-item p{font-size:13px;color:#8A8A8A;line-height:1.7;}\r\n@media(max-width:1100px){.why-grid{grid-template-columns:1fr;gap:48px;}.why-counter-box{position:static;margin-top:24px;justify-self:center;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-04 08:47:54', '2026-06-04 08:48:21'),
(184, NULL, 'Brand marque garage theme', 'brand-marque-garage-theme', NULL, NULL, 'fa-cube', '<div class=\"brands\">\r\n  <div class=\"brands-label\">Marques que nous traitons</div>\r\n  <div class=\"brands-track-wrap\"><div class=\"brands-track\"><span class=\"brand-logo\">BMW</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">MERCEDES</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">AUDI</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">RENAULT</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">PEUGEOT</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">VOLKSWAGEN</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">TOYOTA</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">FORD</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">TESLA</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">HYUNDAI</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">KIA</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">HONDA</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">BMW</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">MERCEDES</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">AUDI</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">RENAULT</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">PEUGEOT</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">VOLKSWAGEN</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">TOYOTA</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">FORD</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">TESLA</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">HYUNDAI</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">KIA</span><span class=\"brand-sep\"></span><span class=\"brand-logo\">HONDA</span><span class=\"brand-sep\"></span></div></div>\r\n</div>', '.brands{padding:50px 0;border-top:1px solid rgba(0,0,0,.07);border-bottom:1px solid rgba(0,0,0,.07);overflow:hidden;background:#fff;margin-bottom:2rem;}\r\n.brands-label{text-align:center;font-size:11px;letter-spacing:3px;text-transform:uppercase;color:#bbb;margin-bottom:32px;font-weight:600;}\r\n.brands-track-wrap{overflow:hidden;position:relative;max-width:100%;}\r\n.brands-track{display:flex;gap:60px;width:max-content;animation:marquee 22s linear infinite;}\r\n@keyframes marquee{from{transform:translateX(0);}to{transform:translateX(-50%);}}\r\n.brand-logo{display:flex;align-items:center;gap:8px;font-family:\'Bebas Neue\',sans-serif;font-size:22px;letter-spacing:3px;color:#ccc;flex-shrink:0;transition:color .25s;cursor:default;white-space:nowrap;}\r\n.brand-logo:hover{color:#D4A537;}\r\n.brand-sep{width:4px;height:4px;border-radius:50%;background:#ddd;flex-shrink:0;}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 0, 0, 0, 1, '2026-06-04 09:01:11', '2026-06-04 09:11:15'),
(185, NULL, 'Portfolio gallerie', 'portfolio-gallerie', NULL, NULL, 'fa-cube', '<section class=\"portfolio\" id=\"portfolio\">\r\n  <div class=\"portfolio-header\"><div><span class=\"sec-tag\" style=\"color:#D4A537\">Nos réalisations</span><h2 class=\"sec-title white\">GALERIE DE<br>TRAVAUX</h2></div><div class=\"portfolio-filter\"><a href=\"#\" class=\"pf-btn active\" data-filter=\"all\">Tous</a><a href=\"#\" class=\"pf-btn\" data-filter=\"meca\">Mécanique</a><a href=\"#\" class=\"pf-btn\" data-filter=\"carross\">Carrosserie</a><a href=\"#\" class=\"pf-btn\" data-filter=\"elec\">Électrique</a></div></div>\r\n  <div class=\"portfolio-grid\">\r\n    <div class=\"port-item\" data-cat=\"carross\"><div class=\"port-img\"><img src=\"https://images.unsplash.com/photo-1619642751034-765dfdf7c58e?w=1200&q=80&fit=crop\" alt=\"Restauration BMW\"></div><div class=\"port-overlay\"><span class=\"port-tag\">Carrosserie</span><div class=\"port-title\">Restauration complète BMW M3</div></div></div>\r\n    <div class=\"port-item\" data-cat=\"meca\"><div class=\"port-img\"><img src=\"https://images.unsplash.com/photo-1504215680853-026ed2a45def?w=700&q=80&fit=crop\" alt=\"Révision moteur\"></div><div class=\"port-overlay\"><span class=\"port-tag\">Mécanique</span><div class=\"port-title\">Révision moteur Porsche 911</div></div></div>\r\n    <div class=\"port-item\" data-cat=\"elec\"><div class=\"port-img\"><img src=\"https://images.unsplash.com/photo-1593941707882-a5bba14938c7?w=700&q=80&fit=crop\" alt=\"Tesla diagnostic\"></div><div class=\"port-overlay\"><span class=\"port-tag\">Électrique</span><div class=\"port-title\">Diagnostic Tesla Model S</div></div></div>\r\n    <div class=\"port-item\" data-cat=\"carross\"><div class=\"port-img\"><img src=\"https://images.unsplash.com/photo-1449965408869-eaa3f722e40d?w=700&q=80&fit=crop\" alt=\"Peinture\"></div><div class=\"port-overlay\"><span class=\"port-tag\">Carrosserie</span><div class=\"port-title\">Laquage Ferrari 488</div></div></div>\r\n    <div class=\"port-item\" data-cat=\"meca\"><div class=\"port-img\"><img src=\"https://images.unsplash.com/photo-1580274455191-1c62238fa333?w=700&q=80&fit=crop\" alt=\"Atelier\"></div><div class=\"port-overlay\"><span class=\"port-tag\">Mécanique</span><div class=\"port-title\">Révision Audi RS6</div></div></div>\r\n    <div class=\"port-item\" data-cat=\"elec\"><div class=\"port-img\"><img src=\"https://images.unsplash.com/photo-1605559424843-9073c6223bd7?w=700&q=80&fit=crop\" alt=\"VE\"></div><div class=\"port-overlay\"><span class=\"port-tag\">Électrique</span><div class=\"port-title\">Batterie Porsche Taycan</div></div></div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n(function(){\r\n  var filterBtns = document.querySelectorAll(\'.portfolio-filter .pf-btn\');\r\n  var portfolioItems = document.querySelectorAll(\'.port-item\');\r\n  filterBtns.forEach(function(btn){\r\n    btn.addEventListener(\'click\', function(e){\r\n      e.preventDefault();\r\n      filterBtns.forEach(function(b){b.classList.remove(\'active\');});\r\n      btn.classList.add(\'active\');\r\n      var filter = btn.getAttribute(\'data-filter\');\r\n      portfolioItems.forEach(function(item){\r\n        if(filter === \'all\' || item.getAttribute(\'data-cat\') === filter){\r\n          item.style.display = \'block\';\r\n        } else {\r\n          item.style.display = \'none\';\r\n        }\r\n      });\r\n    });\r\n  });\r\n})();\r\n</script>', '.portfolio{padding:110px 0;background:#111111;}\r\n.portfolio .sec-title{color:#fff;}\r\n.portfolio-header{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:50px;flex-wrap:wrap;gap:20px;max-width:1280px;margin-left:auto;margin-right:auto;padding:0 40px;}\r\n.portfolio-filter{display:flex;gap:0;flex-wrap:wrap;}\r\n.pf-btn{padding:10px 22px;font-size:12px;font-weight:700;letter-spacing:1px;text-transform:uppercase;background:transparent;border:1px solid rgba(255,255,255,.12);color:rgba(255,255,255,.5);cursor:pointer;font-family:\'Inter\',sans-serif;transition:all .2s;}\r\n.pf-btn.active,.pf-btn:hover{background:#D4A537;border-color:#D4A537;color:#1A1A1A;}\r\n.portfolio-grid{display:grid;grid-template-columns:repeat(12,1fr);gap:14px;max-width:1280px;margin:0 auto;padding:0 40px;}\r\n.port-item{overflow:hidden;position:relative;cursor:pointer;}\r\n.port-item:nth-child(1){grid-column:span 8;grid-row:span 2;}\r\n.port-item:nth-child(2){grid-column:span 4;}\r\n.port-item:nth-child(3){grid-column:span 4;}\r\n.port-item:nth-child(4){grid-column:span 4;}\r\n.port-item:nth-child(5){grid-column:span 4;}\r\n.port-item:nth-child(6){grid-column:span 4;}\r\n.port-img{width:100%;height:100%;min-height:220px;display:block;overflow:hidden;}\r\n.port-img img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease;}\r\n.port-item:nth-child(1) .port-img{min-height:500px;}\r\n.port-item:hover .port-img img{transform:scale(1.06);}\r\n.port-overlay{position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.85) 0%,rgba(0,0,0,.1) 50%,transparent);opacity:0;transition:opacity .35s;display:flex;flex-direction:column;justify-content:flex-end;padding:24px;}\r\n.port-item:hover .port-overlay{opacity:1;}\r\n.port-tag{display:inline-block;background:#D4A537;color:#1A1A1A;font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;padding:5px 12px;margin-bottom:8px;}\r\n.port-title{font-size:16px;font-weight:700;color:#fff;}\r\n@media(max-width:1100px){.portfolio-grid{grid-template-columns:1fr 1fr;}.port-item:nth-child(1){grid-column:span 2;grid-row:span 1;}.port-item:nth-child(n){grid-column:span 1;}}\r\n@media(max-width:768px){.portfolio-grid{grid-template-columns:1fr;}.port-item:nth-child(n){grid-column:span 1;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-04 09:01:52', '2026-07-25 19:49:44'),
(186, NULL, 'Process garage theme', 'process-garage-theme', NULL, NULL, 'fa-cube', '<section class=\"process\">\r\n  <div style=\"text-align:center;margin-bottom:20px;\"><span class=\"sec-tag\">Comment ça marche</span><h2 class=\"sec-title\">NOTRE PROCESSUS<br>EN 4 ÉTAPES</h2></div>\r\n  <div class=\"process-grid\">\r\n    <div class=\"proc-step\"><div class=\"proc-num\">01</div><h4>Prise de RDV</h4><p>En ligne, par téléphone ou directement au garage. Confirmation sous 1 heure.</p></div>\r\n    <div class=\"proc-step\"><div class=\"proc-num\">02</div><h4>Diagnostic complet</h4><p>Bilan 50 points, rapport détaillé avec photos envoyé par email.</p></div>\r\n    <div class=\"proc-step\"><div class=\"proc-num\">03</div><h4>Validation du devis</h4><p>Devis précis approuvé par vous avant toute intervention. Zéro surprise.</p></div>\r\n    <div class=\"proc-step\"><div class=\"proc-num\">04</div><h4>Livraison & suivi</h4><p>Véhicule livré lavé, contrôlé. Suivi post-intervention assuré.</p></div>\r\n  </div>\r\n</section>', '.process{padding:110px 0;background:#F5F3EF;}\r\n.process-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:0;margin-top:60px;position:relative;max-width:1280px;margin-left:auto;margin-right:auto;padding:0 40px;}\r\n.process-grid::before{content:\'\';position:absolute;top:32px;left:12.5%;right:12.5%;height:1px;background:repeating-linear-gradient(to right,#D4A537 0,#D4A537 14px,transparent 14px,transparent 28px);}\r\n.proc-step{padding:0 24px;text-align:center;position:relative;z-index:1;}\r\n.proc-num{width:64px;height:64px;border-radius:50%;background:#D4A537;color:#1A1A1A;font-family:\'Bebas Neue\',sans-serif;font-size:28px;display:flex;align-items:center;justify-content:center;margin:0 auto 24px;box-shadow:0 4px 20px rgba(212,165,55,.4);}\r\n.proc-step h4{font-size:15px;font-weight:800;color:#1A1A1A;margin-bottom:10px;}\r\n.proc-step p{font-size:13px;color:#8A8A8A;line-height:1.7;}\r\n@media(max-width:768px){.process-grid{grid-template-columns:1fr 1fr;}.process-grid::before{display:none;}}\r\n@media(max-width:480px){.process-grid{grid-template-columns:1fr;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 0, 0, 0, 1, '2026-06-04 09:03:43', '2026-06-04 09:11:27'),
(187, NULL, 'countres garage theme', 'countres-garage-theme', NULL, NULL, 'fa-cube', '<div class=\"counters\">\r\n  <div class=\"counters-inner\">\r\n    <div class=\"cnt-item\"><div class=\"cnt-num\">15 000+</div><div class=\"cnt-label\">Clients satisfaits</div></div>\r\n    <div class=\"cnt-item\"><div class=\"cnt-num\">25+</div><div class=\"cnt-label\">Ans d\'expérience</div></div>\r\n    <div class=\"cnt-item\"><div class=\"cnt-num\">98%</div><div class=\"cnt-label\">% Satisfaction</div></div>\r\n    <div class=\"cnt-item\"><div class=\"cnt-num\">8</div><div class=\"cnt-label\">Techniciens experts</div></div>\r\n    <div class=\"cnt-item\"><div class=\"cnt-num\">50+</div><div class=\"cnt-label\">Points de contrôle</div></div>\r\n  </div>\r\n</div>', '.counters{padding:0;background:#D4A537;overflow:hidden;}\r\n.counters-inner{max-width:1280px;margin:0 auto;display:flex;}\r\n.cnt-item{flex:1;padding:60px 20px;text-align:center;border-right:1px solid rgba(0,0,0,.1);position:relative;}\r\n.cnt-item:last-child{border-right:none;}\r\n.cnt-num{font-family:\'Bebas Neue\',sans-serif;font-size:72px;color:#1A1A1A;line-height:1;}\r\n.cnt-label{font-size:12px;font-weight:700;color:rgba(0,0,0,.55);text-transform:uppercase;letter-spacing:2px;margin-top:4px;}\r\n@media(max-width:768px){.counters-inner{flex-wrap:wrap;}.cnt-item{flex:1;min-width:50%;}}\r\n@media(max-width:480px){.cnt-item{min-width:100%;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-04 09:05:20', '2026-06-04 09:11:31'),
(188, NULL, 'Testimentiels garage theme', 'testimentiels-garage-theme', NULL, NULL, 'fa-cube', '<section class=\"testimonials\" id=\"testimonials\">\r\n  <div style=\"text-align:center;margin-bottom:16px;\"><span class=\"sec-tag\">Avis clients</span><h2 class=\"sec-title white\">ILS NOUS FONT<br>CONFIANCE</h2></div>\r\n  <div class=\"testi-layout\">\r\n    <div class=\"testi-img-col\"><div class=\"testi-main-img\"><img src=\"https://images.unsplash.com/photo-1530046339160-ce3e530c7d2f?w=800&q=80&fit=crop\" alt=\"Client satisfait\"></div><div class=\"testi-floating\"><div class=\"testi-floating-num\">4.9★</div><div class=\"testi-floating-lbl\">Note moyenne<br>+2400 avis Google</div></div></div>\r\n    <div class=\"testi-slider\"><div class=\"testi-slide active\"><div class=\"testi-quote-icon\">\"</div><div class=\"testi-stars\">★★★★★</div><div class=\"testi-text\">Service exceptionnel ! Mon véhicule a été pris en charge le jour même. Diagnostic rapide, devis transparent, et travail impeccable. Je ne vais plus nulle part ailleurs depuis 5 ans !</div><div class=\"testi-author\"><div class=\"testi-avatar\"><img src=\"https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=100&q=80&fit=crop&crop=face\" alt=\"Sophie\"></div><div><div class=\"testi-name\">Sophie Marchand</div><div class=\"testi-role\">Cliente fidèle — BMW Série 5</div></div></div></div><div class=\"testi-slide\"><div class=\"testi-quote-icon\">\"</div><div class=\"testi-stars\">★★★★★</div><div class=\"testi-text\">Équipe très professionnelle et tarifs honnêtes. Ma Tesla a été diagnostiquée et réparée en une seule journée. Ces gars maîtrisent vraiment les véhicules électriques !</div><div class=\"testi-author\"><div class=\"testi-avatar\"><img src=\"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&q=80&fit=crop&crop=face\" alt=\"Karim\"></div><div><div class=\"testi-name\">Karim Bensalem</div><div class=\"testi-role\">Propriétaire Tesla Model 3</div></div></div></div><div class=\"testi-slide\"><div class=\"testi-quote-icon\">\"</div><div class=\"testi-stars\">★★★★★</div><div class=\"testi-text\">Carrosserie après un accrochage. Résultat parfait, impossible de voir qu\'il y avait un dommage. La peinture est parfaitement assortie à la teinte d\'origine. Un grand merci !</div><div class=\"testi-author\"><div class=\"testi-avatar\"><img src=\"https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&q=80&fit=crop&crop=face\" alt=\"Marie-Claire\"></div><div><div class=\"testi-name\">Marie-Claire Petit</div><div class=\"testi-role\">Audi A3 — Cliente 2022</div></div></div></div><div class=\"testi-slide\"><div class=\"testi-quote-icon\">\"</div><div class=\"testi-stars\">★★★★★</div><div class=\"testi-text\">Panne un vendredi soir ! Remorquage organisé, réparation le samedi matin, récupération à midi. Service dépannage bluffant. Le meilleur garage de Paris sans hésitation.</div><div class=\"testi-author\"><div class=\"testi-avatar\"><img src=\"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100&q=80&fit=crop&crop=face\" alt=\"François\"></div><div><div class=\"testi-name\">François Lambert</div><div class=\"testi-role\">Renault Clio — Client 2021</div></div></div></div><div class=\"testi-dots\"><div class=\"testi-dot active\" onclick=\"goTestiSlide(0)\"></div><div class=\"testi-dot\" onclick=\"goTestiSlide(1)\"></div><div class=\"testi-dot\" onclick=\"goTestiSlide(2)\"></div><div class=\"testi-dot\" onclick=\"goTestiSlide(3)\"></div></div></div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\nvar testiSlides = document.querySelectorAll(\'.testi-slide\');\r\nvar testiDots = document.querySelectorAll(\'.testi-dot\');\r\nvar testiCurrent = 0;\r\nfunction goTestiSlide(n){testiSlides[testiCurrent].classList.remove(\'active\');testiDots[testiCurrent].classList.remove(\'active\');testiCurrent=n;testiSlides[testiCurrent].classList.add(\'active\');testiDots[testiCurrent].classList.add(\'active\');}\r\nsetInterval(function(){goTestiSlide((testiCurrent+1)%testiSlides.length);},5000);\r\n</script>', '.testimonials{padding:110px 0;background:#111111;}\r\n.testi-layout{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center;margin-top:60px;max-width:1280px;margin-left:auto;margin-right:auto;padding:0 40px;}\r\n.testi-img-col{position:relative;}\r\n.testi-main-img{width:100%;aspect-ratio:3/4;overflow:hidden;}\r\n.testi-main-img img{width:100%;height:100%;object-fit:cover;}\r\n.testi-floating{position:absolute;bottom:30px;right:-30px;background:#D4A537;padding:24px 28px;max-width:200px;}\r\n.testi-floating-num{font-family:\'Bebas Neue\',sans-serif;font-size:48px;color:#1A1A1A;line-height:1;}\r\n.testi-floating-lbl{font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#1A1A1A;margin-top:4px;}\r\n.testi-slider{position:relative;}\r\n.testi-slide{display:none;}\r\n.testi-slide.active{display:block;}\r\n.testi-quote-icon{font-family:\'Georgia\',serif;font-size:80px;color:rgba(212,165,55,.2);line-height:1;margin-bottom:-10px;}\r\n.testi-stars{color:#D4A537;font-size:18px;letter-spacing:4px;margin-bottom:20px;}\r\n.testi-text{font-size:17px;color:rgba(255,255,255,.75);line-height:1.8;margin-bottom:28px;font-style:italic;}\r\n.testi-author{display:flex;align-items:center;gap:16px;}\r\n.testi-avatar{width:52px;height:52px;border-radius:50%;overflow:hidden;border:2px solid #D4A537;}\r\n.testi-avatar img{width:100%;height:100%;object-fit:cover;}\r\n.testi-name{font-size:15px;font-weight:700;color:#fff;}\r\n.testi-role{font-size:12px;color:#8A8A8A;margin-top:2px;}\r\n.testi-dots{display:flex;gap:8px;margin-top:32px;}\r\n.testi-dot{width:32px;height:3px;background:rgba(255,255,255,.15);cursor:pointer;transition:background .25s;}\r\n.testi-dot.active{background:#D4A537;}\r\n@media(max-width:1100px){.testi-layout{grid-template-columns:1fr;gap:40px;}.testi-img-col{display:none;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-04 09:06:35', '2026-06-04 09:11:36'),
(189, NULL, 'Team garage theme', 'team-garage-theme', NULL, NULL, 'fa-cube', '<section class=\"team\" id=\"team\">\r\n  <div style=\"text-align:center;\"><span class=\"sec-tag\">L\'équipe</span><h2 class=\"sec-title\">DES EXPERTS<br>À VOTRE SERVICE</h2></div>\r\n  <div class=\"team-grid\">\r\n    <div class=\"team-card\"><div class=\"team-img\"><img src=\"https://images.unsplash.com/photo-1621905252507-b35492cc74b4?w=600&q=80&fit=crop&crop=face\" alt=\"Marc Dubois\"></div><div class=\"team-body\"><div class=\"team-name\">Marc Dubois</div><div class=\"team-role\">Chef Mécanicien</div><div class=\"team-exp\">25 ans d\'expérience · Certifié BMW &amp; Mercedes</div><div class=\"team-social-row\"><a href=\"#\" class=\"team-soc\">in</a><a href=\"#\" class=\"team-soc\">f</a></div></div></div>\r\n    <div class=\"team-card\"><div class=\"team-img\"><img src=\"https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=600&q=80&fit=crop&crop=face\" alt=\"Sarah Martin\"></div><div class=\"team-body\"><div class=\"team-name\">Sarah Martin</div><div class=\"team-role\">Expert Diagnostics</div><div class=\"team-exp\">12 ans d\'expérience · Spécialiste VE</div><div class=\"team-social-row\"><a href=\"#\" class=\"team-soc\">in</a><a href=\"#\" class=\"team-soc\">f</a></div></div></div>\r\n    <div class=\"team-card\"><div class=\"team-img\"><img src=\"https://images.unsplash.com/photo-1552664730-d307ca884978?w=600&q=80&fit=crop&crop=face\" alt=\"Thomas Leroy\"></div><div class=\"team-body\"><div class=\"team-name\">Thomas Leroy</div><div class=\"team-role\">Carrossier Peintre</div><div class=\"team-exp\">18 ans d\'expérience · Peinture premium</div><div class=\"team-social-row\"><a href=\"#\" class=\"team-soc\">in</a><a href=\"#\" class=\"team-soc\">f</a></div></div></div>\r\n    <div class=\"team-card\"><div class=\"team-img\"><img src=\"https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=600&q=80&fit=crop&crop=face\" alt=\"Pierre Moreau\"></div><div class=\"team-body\"><div class=\"team-name\">Pierre Moreau</div><div class=\"team-role\">Directeur Technique</div><div class=\"team-exp\">20 ans d\'expérience · Fondateur</div><div class=\"team-social-row\"><a href=\"#\" class=\"team-soc\">in</a><a href=\"#\" class=\"team-soc\">f</a></div></div></div>\r\n  </div>\r\n</section>', '.team{padding:110px 0;background:#F5F3EF;}\r\n.team-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin-top:60px;max-width:1280px;margin-left:auto;margin-right:auto;padding:0 40px;}\r\n.team-card{background:#fff;overflow:hidden;transition:all .3s;}\r\n.team-card:hover{box-shadow:0 20px 60px rgba(0,0,0,.1);transform:translateY(-6px);}\r\n.team-img{height:280px;overflow:hidden;position:relative;}\r\n.team-img img{width:100%;height:100%;object-fit:cover;transition:transform .5s;}\r\n.team-card:hover .team-img img{transform:scale(1.05);}\r\n.team-body{padding:24px 22px;}\r\n.team-name{font-size:17px;font-weight:800;color:#1A1A1A;margin-bottom:4px;}\r\n.team-role{font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#D4A537;margin-bottom:8px;}\r\n.team-exp{font-size:12px;color:#8A8A8A;}\r\n.team-social-row{display:flex;gap:8px;margin-top:14px;padding-top:14px;border-top:1px solid rgba(0,0,0,.07);}\r\n.team-soc{width:30px;height:30px;border:1px solid rgba(0,0,0,.1);display:flex;align-items:center;justify-content:center;font-size:12px;transition:all .2s;text-decoration:none;color:#1A1A1A;}\r\n.team-soc:hover{background:#D4A537;border-color:#D4A537;}\r\n@media(max-width:1100px){.team-grid{grid-template-columns:repeat(2,1fr);}}\r\n@media(max-width:768px){.team-grid{grid-template-columns:1fr;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 0, 0, 0, 1, '2026-06-04 09:07:35', '2026-06-04 09:11:44'),
(190, NULL, 'VIDEO CTA', 'video-cta', NULL, NULL, 'fa-cube', '<section class=\"video-cta\">\r\n  <div class=\"video-bg\"><img src=\"https://images.unsplash.com/photo-1611566026373-c6c8da0ea861?w=1600&q=80&fit=crop\" alt=\"Atelier AutoElite\"></div>\r\n  <div class=\"video-cta-content\"><div class=\"video-play\">▶</div><h2>VOTRE PROCHAIN RDV<br>EN <em>30 SECONDES</em></h2><p>Réservez en ligne, par téléphone ou venez directement nous voir. Nous sommes là pour vous 6 jours sur 7.</p><div style=\"display:flex;gap:14px;justify-content:center;flex-wrap:wrap;\"><a href=\"#contact\" class=\"btn-prim\">📅 Prendre Rendez-vous</a><a href=\"tel:+33123456789\" class=\"btn-line\">📞 01 23 45 67 89</a></div></div>\r\n</section>', '.video-cta{position:relative;height:500px;overflow:hidden;display:flex;align-items:center;justify-content:center;margin-bottom:2rem;}\r\n.video-bg{position:absolute;inset:0;}\r\n.video-bg img{width:100%;height:100%;object-fit:cover;}\r\n.video-bg::after{content:\'\';position:absolute;inset:0;background:rgba(0,0,0,.65);}\r\n.video-cta-content{position:relative;z-index:2;text-align:center;max-width:640px;padding:0 24px;}\r\n.video-cta h2{font-family:\'Bebas Neue\',sans-serif;font-size:clamp(44px,6vw,72px);color:#fff;line-height:1;margin-bottom:20px;}\r\n.video-cta h2 em{color:#D4A537;font-style:normal;}\r\n.video-cta p{font-size:16px;color:rgba(255,255,255,.65);margin-bottom:36px;}\r\n.video-play{width:72px;height:72px;border-radius:50%;background:#D4A537;display:inline-flex;align-items:center;justify-content:center;font-size:24px;margin-bottom:24px;transition:transform .25s;cursor:pointer;}\r\n.video-play:hover{transform:scale(1.1);}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 0, 0, 0, 1, '2026-06-04 09:08:12', '2026-06-04 09:11:51'),
(191, NULL, 'Faqs garage theme', 'faqs-garage-theme', NULL, NULL, 'fa-cube', '<section class=\"faq\" id=\"faq\">\r\n  <div class=\"faq-layout\">\r\n    <div class=\"faq-img\"><img src=\"https://images.unsplash.com/photo-1617469767053-8a78c7cca73a?w=900&q=80&fit=crop\" alt=\"Atelier FAQ\"></div>\r\n    <div><span class=\"sec-tag\">Questions fréquentes</span><h2 class=\"sec-title\">VOUS AVEZ DES<br>QUESTIONS ?</h2>\r\n    <div class=\"faq-list\">\r\n      <div class=\"faq-item open\"><div class=\"faq-q\" onclick=\"toggleFaqItem(this)\">Puis-je obtenir un devis sans engagement ?<span class=\"faq-icon\">+</span></div><div class=\"faq-a\"><div class=\"faq-a-inner\">Oui, nous proposons des devis gratuits et sans engagement. Vous pouvez venir avec votre véhicule ou nous appeler. Aucune intervention ne sera réalisée sans votre validation préalable.</div></div></div>\r\n      <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggleFaqItem(this)\">Combien de temps dure une révision complète ?<span class=\"faq-icon\">+</span></div><div class=\"faq-a\"><div class=\"faq-a-inner\">Une révision standard prend entre 2h et 4h selon l\'état du véhicule. Pour les interventions complexes, nous vous donnons une estimation précise lors de la prise en charge.</div></div></div>\r\n      <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggleFaqItem(this)\">Travaillez-vous avec toutes les marques ?<span class=\"faq-icon\">+</span></div><div class=\"faq-a\"><div class=\"faq-a-inner\">Absolument ! Nous sommes équipés pour toutes les marques, des véhicules classiques aux modèles électriques. Nos techniciens sont formés en continu.</div></div></div>\r\n      <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggleFaqItem(this)\">Proposez-vous un véhicule de remplacement ?<span class=\"faq-icon\">+</span></div><div class=\"faq-a\"><div class=\"faq-a-inner\">Oui, flotte de prêt gratuite pour nos clients Premium et Excellence, et disponible en option pour les autres forfaits.</div></div></div>\r\n      <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggleFaqItem(this)\">Quelle garantie offrez-vous sur vos travaux ?<span class=\"faq-icon\">+</span></div><div class=\"faq-a\"><div class=\"faq-a-inner\">Toutes nos interventions sont garanties 12 mois ou 20 000 km, pièces et main d\'œuvre inclus, sans condition.</div></div></div>\r\n      <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggleFaqItem(this)\">Acceptez-vous le paiement en plusieurs fois ?<span class=\"faq-icon\">+</span></div><div class=\"faq-a\"><div class=\"faq-a-inner\">Oui, pour les factures supérieures à 300€, paiement en 3 ou 4 fois sans frais. CB, virement, chèque et espèces acceptés.</div></div></div>\r\n    </div></div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\nfunction toggleFaqItem(el){var item=el.parentElement;var open=item.classList.contains(\'open\');document.querySelectorAll(\'.faq-item\').forEach(function(i){i.classList.remove(\'open\');});if(!open){item.classList.add(\'open\');}}\r\n</script>', '.faq{padding:110px 0;background:#fff;}\r\n.faq-layout{display:grid;grid-template-columns:1fr 1fr;gap:80px;margin-top:60px;align-items:start;max-width:1280px;margin-left:auto;margin-right:auto;padding:0 40px;}\r\n.faq-img{width:100%;aspect-ratio:4/5;overflow:hidden;}\r\n.faq-img img{width:100%;height:100%;object-fit:cover;}\r\n.faq-list{display:flex;flex-direction:column;gap:0;}\r\n.faq-item{border-bottom:1px solid rgba(0,0,0,.09);}\r\n.faq-q{padding:20px 0;font-size:15px;font-weight:700;color:#1A1A1A;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:16px;user-select:none;transition:color .2s;}\r\n.faq-q:hover,.faq-item.open .faq-q{color:#D4A537;}\r\n.faq-icon{font-size:20px;line-height:1;flex-shrink:0;transition:transform .3s;color:#D4A537;}\r\n.faq-item.open .faq-icon{transform:rotate(45deg);}\r\n.faq-a{max-height:0;overflow:hidden;transition:max-height .35s ease;}\r\n.faq-a-inner{padding:0 0 20px;font-size:14px;color:#8A8A8A;line-height:1.8;}\r\n.faq-item.open .faq-a{max-height:200px;}\r\n@media(max-width:1100px){.faq-layout{grid-template-columns:1fr;gap:48px;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-04 09:09:03', '2026-06-04 09:11:55'),
(192, NULL, 'Footer garage theme', 'footer-garage-theme', NULL, NULL, 'fa-cube', '<footer class=\"footer\">\r\n  <div class=\"footer-grid\">\r\n    <div><div class=\"footer-logo\"><div class=\"footer-logo-icon\">⚙</div>AUTO<span>ELITE</span></div><p class=\"footer-desc\">Votre partenaire de confiance pour l\'entretien et la réparation automobile depuis 1998. Qualité, transparence et passion.</p><div class=\"footer-social\"><a href=\"#\" class=\"fsoc\">f</a><a href=\"#\" class=\"fsoc\">in</a><a href=\"#\" class=\"fsoc\">ig</a><a href=\"#\" class=\"fsoc\">yt</a></div></div>\r\n    <div class=\"footer-col\"><h5>Services</h5><ul><li><a href=\"#services\">Mécanique générale</a></li><li><a href=\"#services\">Carrosserie et Peinture</a></li><li><a href=\"#services\">Diagnostic électronique</a></li><li><a href=\"#services\">Climatisation</a></li><li><a href=\"#services\">Pneumatiques</a></li><li><a href=\"#services\">Véhicules électriques</a></li></ul></div>\r\n    <div class=\"footer-col\"><h5>Informations</h5><ul><li><a href=\"#about\">À propos</a></li><li><a href=\"#team\">Notre équipe</a></li><li><a href=\"#portfolio\">Galerie</a></li><li><a href=\"#testimonials\">Témoignages</a></li><li><a href=\"#pricing\">Tarifs</a></li><li><a href=\"#faq\">FAQ</a></li></ul></div>\r\n    <div class=\"footer-col\"><h5>Contact</h5><ul><li><a href=\"#contact\">Prendre RDV</a></li><li><a href=\"tel:+33123456789\">01 23 45 67 89</a></li><li><a href=\"mailto:contact@autoelite.fr\">contact@autoelite.fr</a></li><li><a href=\"#\">12 Rue de la Mécanique</a></li><li><a href=\"#\">75011 Paris</a></li><li><a href=\"#\">Urgences 7j/7</a></li></ul></div>\r\n  </div>\r\n  <div class=\"footer-bottom\"><div class=\"footer-copy\">© 2025 AutoElite Garage. Tous droits réservés.</div><div class=\"footer-policy\"><a href=\"#\">Mentions légales</a><a href=\"#\">Confidentialité</a><a href=\"#\">CGV</a></div></div>\r\n</footer>', '.footer{background:#0A0A0A;padding:80px 0 0;}\r\n.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:48px;padding-bottom:60px;border-bottom:1px solid rgba(255,255,255,.06);max-width:1280px;margin:0 auto;padding:0 40px 60px;}\r\n.footer-logo{font-family:\'Bebas Neue\',sans-serif;font-size:28px;letter-spacing:3px;color:#fff;margin-bottom:16px;display:flex;align-items:center;gap:10px;}\r\n.footer-logo-icon{width:36px;height:36px;background:#D4A537;display:flex;align-items:center;justify-content:center;font-size:16px;}\r\n.footer-logo span{color:#D4A537;}\r\n.footer-desc{font-size:13px;color:rgba(255,255,255,.38);line-height:1.85;margin-bottom:24px;}\r\n.footer-social{display:flex;gap:8px;}\r\n.fsoc{width:36px;height:36px;border:1px solid rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center;font-size:13px;color:rgba(255,255,255,.45);transition:all .2s;text-decoration:none;}\r\n.fsoc:hover{background:#D4A537;border-color:#D4A537;color:#1A1A1A;}\r\n.footer-col h5{font-size:11px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:#D4A537;margin-bottom:22px;}\r\n.footer-col ul{display:flex;flex-direction:column;gap:10px;list-style:none;padding:0;}\r\n.footer-col ul li a{font-size:13px;color:rgba(255,255,255,.38);transition:color .2s;display:flex;align-items:center;gap:8px;text-decoration:none;}\r\n.footer-col ul li a::before{content:\'→\';color:#D4A537;font-size:11px;opacity:0;transition:opacity .2s;}\r\n.footer-col ul li a:hover{color:#fff;padding-left:4px;}\r\n.footer-col ul li a:hover::before{opacity:1;}\r\n.footer-bottom{display:flex;justify-content:space-between;align-items:center;padding:20px 40px;flex-wrap:wrap;gap:12px;max-width:1280px;margin:0 auto;}\r\n.footer-copy{font-size:12px;color:rgba(255,255,255,.2);}\r\n.footer-policy{display:flex;gap:20px;}\r\n.footer-policy a{font-size:12px;color:rgba(255,255,255,.2);transition:color .2s;text-decoration:none;}\r\n.footer-policy a:hover{color:#D4A537;}\r\n@media(max-width:1100px){.footer-grid{grid-template-columns:1fr 1fr;}}\r\n@media(max-width:768px){.footer-grid{grid-template-columns:1fr;}}', NULL, NULL, 'Footer', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-04 09:10:18', '2026-06-04 22:11:07'),
(193, NULL, 'HERO AVEC VIDEO BACKGROUND', 'hero-avec-video-background', NULL, NULL, 'fa-cube', '<section class=\"hero-prestige\">\r\n  <div class=\"hero-video-bg\">\r\n    <video autoplay muted loop playsinline>\r\n      <source src=\"https://videos.pexels.com/video-files/3129670/3129670-uhd_2560_1440_24fps.mp4\" type=\"video/mp4\">\r\n    </video>\r\n  </div>\r\n  <div class=\"hero-overlay-dark\"></div>\r\n  <div class=\"hero-content-prestige\">\r\n    <div class=\"hero-badge-prestige\">🏆 Garage d\'exception depuis 1995</div>\r\n    <h1>L\'excellence<br>automobile à <span>votre service</span></h1>\r\n    <p>Diagnostic haute précision, réparation sur mesure et entretien premium. Une équipe de techniciens certifiés passionnés.</p>\r\n    <div class=\"hero-btns-prestige\"><a href=\"#\" class=\"btn-gold-prestige\">📅 Prendre rendez-vous</a><a href=\"#\" class=\"btn-outline-prestige\">🔧 Nos services</a></div>\r\n  </div>\r\n  <div class=\"hero-stats-prestige\"><div class=\"hero-stat-prestige\"><div class=\"num\">15 000+</div><div class=\"label\">Clients satisfaits</div></div><div class=\"hero-stat-prestige\"><div class=\"num\">25+</div><div class=\"label\">Années d\'expertise</div></div><div class=\"hero-stat-prestige\"><div class=\"num\">98%</div><div class=\"label\">Satisfaction</div></div></div>\r\n</section>', '.hero-prestige{position:relative;height:100vh;min-height:700px;display:flex;align-items:center;overflow:hidden;}\r\n.hero-video-bg{position:absolute;inset:0;z-index:0;}\r\n.hero-video-bg video{width:100%;height:100%;object-fit:cover;}\r\n.hero-overlay-dark{position:absolute;inset:0;background:linear-gradient(135deg,rgba(0,0,0,.85) 0%,rgba(0,0,0,.4) 100%);z-index:1;}\r\n.hero-content-prestige{position:relative;z-index:2;max-width:1280px;margin:0 auto;padding:0 40px;color:#fff;}\r\n.hero-badge-prestige{display:inline-block;background:rgba(212,165,55,.2);border:1px solid rgba(212,165,55,.6);color:#D4A537;padding:8px 20px;border-radius:50px;font-size:13px;font-weight:600;margin-bottom:24px;backdrop-filter:blur(10px);}\r\n.hero-prestige h1{font-size:clamp(48px,7vw,85px);font-weight:800;line-height:1.1;margin-bottom:20px;}\r\n.hero-prestige h1 span{color:#D4A537;}\r\n.hero-prestige p{font-size:18px;color:rgba(255,255,255,.8);max-width:550px;margin-bottom:32px;line-height:1.7;}\r\n.hero-btns-prestige{display:flex;gap:20px;flex-wrap:wrap;}\r\n.btn-gold-prestige{background:#D4A537;color:#1A1A1A;padding:14px 32px;border-radius:50px;font-weight:700;transition:all .3s;display:inline-flex;align-items:center;gap:10px;}\r\n.btn-gold-prestige:hover{background:#b8891e;transform:translateY(-3px);box-shadow:0 10px 25px rgba(212,165,55,.4);}\r\n.btn-outline-prestige{border:2px solid rgba(255,255,255,.4);color:#fff;padding:14px 32px;border-radius:50px;font-weight:600;transition:all .3s;}\r\n.btn-outline-prestige:hover{border-color:#D4A537;color:#D4A537;}\r\n.hero-stats-prestige{position:absolute;bottom:40px;left:0;right:0;display:flex;justify-content:center;gap:80px;flex-wrap:wrap;z-index:2;}\r\n.hero-stat-prestige{text-align:center;}\r\n.hero-stat-prestige .num{font-size:36px;font-weight:800;color:#D4A537;}\r\n.hero-stat-prestige .label{font-size:12px;color:rgba(255,255,255,.6);margin-top:5px;}\r\n@media(max-width:768px){.hero-stats-prestige{gap:30px;}.hero-stat-prestige .num{font-size:24px;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-04 10:11:57', '2026-07-25 19:49:27'),
(194, NULL, 'SERVICES ICON GRID', 'services-icon-grid', NULL, NULL, 'fa-cube', '<section class=\"services-icon-grid\">\r\n  <div class=\"services-icon-container\"><div class=\"services-icon-header\"><div class=\"services-icon-tag\">Nos prestations</div><h2 class=\"services-icon-title\">Des services complets<br>pour votre véhicule</h2><p class=\"services-icon-sub\">De l\'entretien courant à la réparation complexe</p></div>\r\n  <div class=\"services-icon-grid\"><div class=\"services-icon-item\"><div class=\"icon\"><i class=\"fas fa-oil-can\"></i></div><h3>Entretien & Révision</h3><p>Vidange, filtres, distribution, freins</p></div><div class=\"services-icon-item\"><div class=\"icon\"><i class=\"fas fa-microchip\"></i></div><h3>Diagnostic électronique</h3><p>Analyse calculateur, reprogrammation</p></div><div class=\"services-icon-item\"><div class=\"icon\"><i class=\"fas fa-car-crash\"></i></div><h3>Carrosserie & Peinture</h3><p>Réparation chocs, rayures, peinture sur mesure</p></div><div class=\"services-icon-item\"><div class=\"icon\"><i class=\"fas fa-snowplow\"></i></div><h3>Climatisation</h3><p>Recharge, désinfection, réparation</p></div></div></div>\r\n</section>', '.services-icon-grid{padding:100px 0;background:#fff;}\r\n.services-icon-container{max-width:1280px;margin:0 auto;padding:0 40px;}\r\n.services-icon-header{text-align:center;margin-bottom:50px;}\r\n.services-icon-tag{display:inline-block;font-size:12px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#D4A537;margin-bottom:12px;}\r\n.services-icon-title{font-size:clamp(32px,4vw,48px);font-weight:800;color:#1A1A1A;margin-bottom:16px;}\r\n.services-icon-sub{font-size:16px;color:#666;max-width:600px;margin:0 auto;}\r\n.services-icon-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:30px;}\r\n.services-icon-item{text-align:center;padding:35px 25px;border-radius:20px;background:#F8F9FA;transition:all .3s;}\r\n.services-icon-item:hover{transform:translateY(-8px);box-shadow:0 20px 40px rgba(0,0,0,.08);}\r\n.services-icon-item .icon{width:80px;height:80px;background:linear-gradient(135deg,#D4A537,#b8891e);border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 20px;font-size:32px;color:#fff;}\r\n.services-icon-item h3{font-size:18px;font-weight:700;margin-bottom:10px;}\r\n.services-icon-item p{font-size:13px;color:#666;line-height:1.6;}\r\n@media(max-width:992px){.services-icon-grid{grid-template-columns:repeat(2,1fr);}}\r\n@media(max-width:576px){.services-icon-grid{grid-template-columns:1fr;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 2, 0, 0, 0, 1, '2026-06-04 10:36:33', '2026-06-04 10:53:37');
INSERT INTO `blocks` (`id`, `categorie_id`, `name`, `slug`, `description`, `thumbnail`, `icon`, `html_content`, `css_content`, `js_content`, `section_id`, `category`, `website_type`, `tags`, `is_responsive`, `is_free`, `width`, `height`, `usage_count`, `views_count`, `rating`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(195, NULL, 'ABOUT AVEC IMAGE PRINCIPALE', 'about-avec-image-principale', NULL, NULL, 'fa-cube', '<section class=\"about-showcase\">\r\n  <div class=\"about-showcase-container\">\r\n    <div class=\"about-showcase-image\"><img src=\"https://images.unsplash.com/photo-1621905251189-08b45d6a269e?w=800&q=85\" alt=\"Atelier moderne\"><div class=\"about-showcase-badge\"><div class=\"big\">25+</div><div class=\"small\">Années d\'expertise</div></div></div>\r\n    <div class=\"about-showcase-content\"><div class=\"tag\">Qui sommes-nous</div><h2>Une équipe de passionnés<br>à votre service</h2><p>Depuis 1995, AutoPrestige Garage place l\'excellence et la confiance au cœur de son métier. Nous traitons chaque véhicule comme s\'il était le nôtre, avec rigueur et passion.</p><div class=\"about-feature-list\"><div class=\"about-feature-item\"><i class=\"fas fa-check-circle\"></i><span>Techniciens certifiés</span></div><div class=\"about-feature-item\"><i class=\"fas fa-check-circle\"></i><span>Devis gratuit</span></div><div class=\"about-feature-item\"><i class=\"fas fa-check-circle\"></i><span>Véhicule de prêt</span></div><div class=\"about-feature-item\"><i class=\"fas fa-check-circle\"></i><span>Garantie 12 mois</span></div></div><a href=\"#\" class=\"btn-gold-prestige\" style=\"display:inline-flex;\">Prendre rendez-vous →</a></div>\r\n  </div>\r\n</section>', '.about-showcase{padding:100px 0;background:#F8F9FA;}\r\n.about-showcase-container{max-width:1280px;margin:0 auto;padding:0 40px;display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center;}\r\n.about-showcase-image{position:relative;border-radius:24px;overflow:hidden;box-shadow:0 25px 50px rgba(0,0,0,.15);}\r\n.about-showcase-image img{width:100%;height:100%;object-fit:cover;min-height:450px;}\r\n.about-showcase-badge{position:absolute;bottom:20px;right:20px;background:#D4A537;padding:18px 25px;border-radius:16px;text-align:center;}\r\n.about-showcase-badge .big{font-size:36px;font-weight:800;color:#1A1A1A;line-height:1;}\r\n.about-showcase-badge .small{font-size:12px;font-weight:600;color:#1A1A1A;}\r\n.about-showcase-content .tag{font-size:12px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#D4A537;margin-bottom:12px;display:inline-block;}\r\n.about-showcase-content h2{font-size:clamp(32px,4vw,44px);font-weight:800;color:#1A1A1A;margin-bottom:20px;line-height:1.2;}\r\n.about-showcase-content p{font-size:16px;color:#666;line-height:1.7;margin-bottom:25px;}\r\n.about-feature-list{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:30px 0;}\r\n.about-feature-item{display:flex;align-items:center;gap:10px;}\r\n.about-feature-item i{color:#D4A537;font-size:16px;}\r\n.about-feature-item span{font-size:14px;color:#333;}\r\n@media(max-width:992px){.about-showcase-container{grid-template-columns:1fr;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 2, 0, 0, 0, 1, '2026-06-04 10:38:43', '2026-06-04 10:55:28'),
(196, NULL, 'GALLERY HORIZONTALE (CAROUSEL)', 'gallery-horizontale-carousel', NULL, NULL, 'fa-cube', '<section class=\"gallery-horizontal\">\r\n  <div class=\"gallery-horizontal-container\"><div class=\"gallery-horizontal-header\"><div class=\"services-icon-tag\">Nos réalisations</div><h2 class=\"gallery-horizontal-title\">Galerie de nos travaux</h2><p class=\"gallery-horizontal-sub\">Découvrez nos dernières interventions en images</p></div>\r\n  <div class=\"gallery-horizontal-track\"><div class=\"gallery-horizontal-item\"><img src=\"https://images.unsplash.com/photo-1580274455191-1c62238fa333?w=600&q=85\" alt=\"Révision moteur\"><div class=\"gallery-horizontal-overlay\"><span>🔧 Révision complète</span></div></div>\r\n  <div class=\"gallery-horizontal-item\"><img src=\"https://images.unsplash.com/photo-1619642751034-765dfdf7c58e?w=600&q=85\" alt=\"Carrosserie\"><div class=\"gallery-horizontal-overlay\"><span>🎨 Restauration carrosserie</span></div></div>\r\n  <div class=\"gallery-horizontal-item\"><img src=\"https://images.unsplash.com/photo-1593941707882-a5bba14938c7?w=600&q=85\" alt=\"Diagnostic\"><div class=\"gallery-horizontal-overlay\"><span>📡 Diagnostic électronique</span></div></div>\r\n  <div class=\"gallery-horizontal-item\"><img src=\"https://images.unsplash.com/photo-1486262715619-67b85e0b08d3?w=600&q=85\" alt=\"Atelier\"><div class=\"gallery-horizontal-overlay\"><span>🏭 Atelier professionnel</span></div></div>\r\n  <div class=\"gallery-horizontal-item\"><img src=\"https://images.unsplash.com/photo-1504215680853-026ed2a45def?w=600&q=85\" alt=\"Mécanique\"><div class=\"gallery-horizontal-overlay\"><span>⚙️ Mécanique générale</span></div></div>\r\n  <div class=\"gallery-horizontal-item\"><img src=\"https://images.unsplash.com/photo-1449965408869-eaa3f722e40d?w=600&q=85\" alt=\"Peinture\"><div class=\"gallery-horizontal-overlay\"><span>🎨 Peinture sur mesure</span></div></div></div></div>\r\n</section>', '.gallery-horizontal{padding:100px 0;background:#fff;overflow:hidden;}\r\n.gallery-horizontal-container{max-width:1280px;margin:0 auto;padding:0 40px;}\r\n.gallery-horizontal-header{text-align:center;margin-bottom:50px;}\r\n.gallery-horizontal-title{font-size:clamp(32px,4vw,44px);font-weight:800;color:#1A1A1A;margin-bottom:16px;}\r\n.gallery-horizontal-sub{font-size:16px;color:#666;max-width:600px;margin:0 auto;}\r\n.gallery-horizontal-track{display:flex;gap:20px;overflow-x:auto;scroll-snap-type:x mandatory;padding-bottom:20px;cursor:grab;}\r\n.gallery-horizontal-track::-webkit-scrollbar{height:6px;}\r\n.gallery-horizontal-track::-webkit-scrollbar-track{background:#eee;border-radius:10px;}\r\n.gallery-horizontal-track::-webkit-scrollbar-thumb{background:#D4A537;border-radius:10px;}\r\n.gallery-horizontal-item{flex:0 0 380px;scroll-snap-align:start;border-radius:20px;overflow:hidden;position:relative;transition:transform .3s;}\r\n.gallery-horizontal-item:hover{transform:scale(1.02);}\r\n.gallery-horizontal-item img{width:100%;height:280px;object-fit:cover;}\r\n.gallery-horizontal-overlay{position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.7),transparent);opacity:0;transition:opacity .3s;display:flex;align-items:flex-end;padding:20px;}\r\n.gallery-horizontal-item:hover .gallery-horizontal-overlay{opacity:1;}\r\n.gallery-horizontal-overlay span{color:#fff;font-weight:600;font-size:14px;}\r\n@media(max-width:768px){.gallery-horizontal-item{flex:0 0 300px;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 2, 0, 0, 0, 1, '2026-06-04 10:39:56', '2026-06-04 10:55:31'),
(197, NULL, 'PRICING CARDS AVEC ICONES', 'pricing-cards-avec-icones', NULL, NULL, 'fa-cube', '<section class=\"pricing-cards\">\r\n  <div class=\"pricing-cards-container\"><div class=\"pricing-cards-header\"><div class=\"services-icon-tag\">Nos forfaits</div><h2 class=\"services-icon-title\">Des tarifs transparents</h2><p class=\"services-icon-sub\">Choisissez la formule adaptée à vos besoins</p></div>\r\n  <div class=\"pricing-cards-grid\"><div class=\"pricing-card-item\"><div class=\"price-icon\"><i class=\"fas fa-oil-can\"></i></div><h3>Révision Essentiel</h3><div class=\"price\">49€</div><div class=\"period\">Pour l\'entretien courant</div><ul class=\"pricing-features\"><li><i class=\"fas fa-check-circle\"></i> Vidange moteur</li><li><i class=\"fas fa-check-circle\"></i> Filtre à huile</li><li><i class=\"fas fa-check-circle\"></i> Contrôle niveaux</li><li><i class=\"fas fa-check-circle\"></i> Pression pneus</li></ul><a href=\"#\" class=\"pricing-btn\">Choisir ce forfait</a></div>\r\n  <div class=\"pricing-card-item featured\"><div class=\"pricing-badge\">⭐ Le plus populaire</div><div class=\"price-icon\"><i class=\"fas fa-microchip\"></i></div><h3>Révision Premium</h3><div class=\"price\">149€</div><div class=\"period\">Entretien complet</div><ul class=\"pricing-features\"><li><i class=\"fas fa-check-circle\"></i> Tout Essentiel +</li><li><i class=\"fas fa-check-circle\"></i> Diagnostic électronique</li><li><i class=\"fas fa-check-circle\"></i> Filtre air/habitacle</li><li><i class=\"fas fa-check-circle\"></i> Lavage extérieur offert</li></ul><a href=\"#\" class=\"pricing-btn\">Choisir ce forfait</a></div>\r\n  <div class=\"pricing-card-item\"><div class=\"price-icon\"><i class=\"fas fa-car-crash\"></i></div><h3>Révision Intégrale</h3><div class=\"price\">299€</div><div class=\"period\">Protection totale</div><ul class=\"pricing-features\"><li><i class=\"fas fa-check-circle\"></i> Tout Premium +</li><li><i class=\"fas fa-check-circle\"></i> Géométrie 3D laser</li><li><i class=\"fas fa-check-circle\"></i> Polissage carrosserie</li><li><i class=\"fas fa-check-circle\"></i> Garantie 12 mois</li></ul><a href=\"#\" class=\"pricing-btn\">Choisir ce forfait</a></div></div></div>\r\n</section>', '.pricing-cards{padding:100px 0;background:#F8F9FA;}\r\n.pricing-cards-container{max-width:1280px;margin:0 auto;padding:0 40px;}\r\n.pricing-cards-header{text-align:center;margin-bottom:50px;}\r\n.pricing-cards-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;}\r\n.pricing-card-item{background:#fff;border-radius:24px;padding:40px 30px;text-align:center;transition:all .3s;box-shadow:0 5px 20px rgba(0,0,0,.05);position:relative;}\r\n.pricing-card-item:hover{transform:translateY(-8px);box-shadow:0 20px 40px rgba(0,0,0,.1);}\r\n.pricing-card-item.featured{border:2px solid #D4A537;transform:scale(1.02);}\r\n.pricing-card-item.featured:hover{transform:scale(1.02) translateY(-8px);}\r\n.pricing-badge{position:absolute;top:-12px;left:50%;transform:translateX(-50%);background:#D4A537;color:#1A1A1A;padding:5px 15px;border-radius:50px;font-size:11px;font-weight:700;}\r\n.pricing-card-item .price-icon{font-size:48px;color:#D4A537;margin-bottom:20px;}\r\n.pricing-card-item h3{font-size:20px;font-weight:800;margin-bottom:10px;}\r\n.pricing-card-item .price{font-size:48px;font-weight:800;color:#D4A537;margin:15px 0 5px;}\r\n.pricing-card-item .period{font-size:13px;color:#999;margin-bottom:25px;padding-bottom:25px;border-bottom:1px solid #eee;}\r\n.pricing-features{list-style:none;margin-bottom:30px;text-align:left;}\r\n.pricing-features li{padding:8px 0;font-size:14px;color:#555;display:flex;align-items:center;gap:10px;}\r\n.pricing-features li i{color:#D4A537;}\r\n.pricing-btn{display:block;background:#D4A537;color:#1A1A1A;padding:12px;border-radius:50px;font-weight:700;transition:all .3s;}\r\n.pricing-btn:hover{background:#b8891e;transform:translateY(-2px);}\r\n@media(max-width:992px){.pricing-cards-grid{grid-template-columns:1fr 1fr;}}\r\n@media(max-width:768px){.pricing-cards-grid{grid-template-columns:1fr;}.pricing-card-item.featured{transform:none;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 0, 0, 0, 1, '2026-06-04 10:46:15', '2026-06-04 10:55:33'),
(198, NULL, 'TEAM GRID AVEC IMAGES', 'team-grid-avec-images', NULL, NULL, 'fa-cube', '<section class=\"team-grid-section\">\r\n  <div class=\"team-grid-container\"><div class=\"team-grid-header\"><div class=\"services-icon-tag\">Notre équipe</div><h2 class=\"services-icon-title\">Des experts passionnés</h2><p class=\"services-icon-sub\">Une équipe de techniciens certifiés à votre écoute</p></div>\r\n  <div class=\"team-grid-cards\"><div class=\"team-card-item\"><div class=\"team-card-img\"><img src=\"https://images.unsplash.com/photo-1621905252507-b35492cc74b4?w=400&q=85\" alt=\"Marc Dubois\"></div><div class=\"team-card-info\"><h4>Marc Dubois</h4><div class=\"role\">Chef mécanicien</div><div class=\"exp\">25 ans d\'expérience</div></div></div>\r\n  <div class=\"team-card-item\"><div class=\"team-card-img\"><img src=\"https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=400&q=85\" alt=\"Sophie Martin\"></div><div class=\"team-card-info\"><h4>Sophie Martin</h4><div class=\"role\">Expert diagnostic</div><div class=\"exp\">12 ans d\'expérience</div></div></div>\r\n  <div class=\"team-card-item\"><div class=\"team-card-img\"><img src=\"https://images.unsplash.com/photo-1552664730-d307ca884978?w=400&q=85\" alt=\"Thomas Leroy\"></div><div class=\"team-card-info\"><h4>Thomas Leroy</h4><div class=\"role\">Carrossier peintre</div><div class=\"exp\">18 ans d\'expérience</div></div></div>\r\n  <div class=\"team-card-item\"><div class=\"team-card-img\"><img src=\"https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=400&q=85\" alt=\"Pierre Moreau\"></div><div class=\"team-card-info\"><h4>Pierre Moreau</h4><div class=\"role\">Directeur technique</div><div class=\"exp\">20 ans d\'expérience</div></div></div></div></div>\r\n</section>', '.team-grid-section{padding:100px 0;background:#fff;}\r\n.team-grid-container{max-width:1280px;margin:0 auto;padding:0 40px;}\r\n.team-grid-header{text-align:center;margin-bottom:50px;}\r\n.team-grid-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:25px;}\r\n.team-card-item{background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 5px 20px rgba(0,0,0,.05);transition:all .3s;}\r\n.team-card-item:hover{transform:translateY(-8px);box-shadow:0 20px 40px rgba(0,0,0,.1);}\r\n.team-card-img{height:300px;overflow:hidden;}\r\n.team-card-img img{width:100%;height:100%;object-fit:cover;transition:transform .5s;}\r\n.team-card-item:hover .team-card-img img{transform:scale(1.05);}\r\n.team-card-info{padding:20px;text-align:center;}\r\n.team-card-info h4{font-size:18px;font-weight:800;margin-bottom:4px;}\r\n.team-card-info .role{font-size:12px;color:#D4A537;font-weight:600;margin-bottom:8px;text-transform:uppercase;letter-spacing:1px;}\r\n.team-card-info .exp{font-size:13px;color:#666;}\r\n@media(max-width:992px){.team-grid-cards{grid-template-columns:repeat(2,1fr);}}\r\n@media(max-width:576px){.team-grid-cards{grid-template-columns:1fr;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 0, 0, 0, 1, '2026-06-04 10:46:53', '2026-06-04 10:55:35'),
(199, NULL, 'TESTIMONIALS AVEC AVATARS', 'testimonials-avec-avatars', NULL, NULL, 'fa-cube', '<section class=\"testimonials-grid\">\r\n  <div class=\"testimonials-grid-container\"><div class=\"testimonials-grid-header\"><div class=\"services-icon-tag\">Avis clients</div><h2 class=\"services-icon-title\">Ce qu\'ils disent de nous</h2><p class=\"services-icon-sub\">Plus de 15 000 clients satisfaits</p></div>\r\n  <div class=\"testimonials-grid-cards\"><div class=\"testimonial-card-item\"><div class=\"testimonial-stars\">★★★★★</div><div class=\"testimonial-text\">\"Service impeccable ! Mon véhicule a été réparé rapidement et à un prix très correct. Je recommande vivement ce garage.\"</div><div class=\"testimonial-author\"><img class=\"testimonial-author-img\" src=\"https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=100&q=80\" alt=\"Client\"><div class=\"testimonial-author-info\"><h4>Sophie Martin</h4><p>BMW Série 3</p></div></div></div>\r\n  <div class=\"testimonial-card-item\"><div class=\"testimonial-stars\">★★★★★</div><div class=\"testimonial-text\">\"Des professionnels compétents et à l\'écoute. Le diagnostic a été précis et la réparation rapide. Un grand merci !\"</div><div class=\"testimonial-author\"><img class=\"testimonial-author-img\" src=\"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100&q=80\" alt=\"Client\"><div class=\"testimonial-author-info\"><h4>Thomas Bernard</h4><p>Audi A4</p></div></div></div>\r\n  <div class=\"testimonial-card-item\"><div class=\"testimonial-stars\">★★★★★</div><div class=\"testimonial-text\">\"Meilleur garage de Paris ! Travail soigné, prix transparents et équipe sympathique. Je ne vais plus ailleurs.\"</div><div class=\"testimonial-author\"><img class=\"testimonial-author-img\" src=\"https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&q=80\" alt=\"Client\"><div class=\"testimonial-author-info\"><h4>Marie-Claire D.</h4><p>Peugeot 208</p></div></div></div></div></div>\r\n</section>', '.testimonials-grid{padding:100px 0;background:#F8F9FA;}\r\n.testimonials-grid-container{max-width:1280px;margin:0 auto;padding:0 40px;}\r\n.testimonials-grid-header{text-align:center;margin-bottom:50px;}\r\n.testimonials-grid-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;}\r\n.testimonial-card-item{background:#fff;border-radius:24px;padding:35px;box-shadow:0 5px 20px rgba(0,0,0,.05);transition:all .3s;}\r\n.testimonial-card-item:hover{transform:translateY(-5px);box-shadow:0 20px 40px rgba(0,0,0,.1);}\r\n.testimonial-stars{color:#D4A537;margin-bottom:15px;font-size:14px;letter-spacing:3px;}\r\n.testimonial-text{font-size:15px;color:#555;line-height:1.7;font-style:italic;margin-bottom:25px;}\r\n.testimonial-author{display:flex;align-items:center;gap:15px;}\r\n.testimonial-author-img{width:55px;height:55px;border-radius:50%;object-fit:cover;border:3px solid #D4A537;}\r\n.testimonial-author-info h4{font-size:16px;font-weight:700;margin-bottom:2px;}\r\n.testimonial-author-info p{font-size:12px;color:#999;}\r\n@media(max-width:992px){.testimonials-grid-cards{grid-template-columns:1fr 1fr;}}\r\n@media(max-width:576px){.testimonials-grid-cards{grid-template-columns:1fr;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 0, 0, 0, 1, '2026-06-04 10:47:36', '2026-06-04 10:56:28'),
(200, NULL, 'BRANDS CLIENTS (LOGOS)', 'brands-clients-logos', NULL, NULL, 'fa-cube', '<section class=\"brands-showcase\">\r\n  <div class=\"brands-showcase-container\"><div class=\"brands-showcase-header\"><div class=\"tag\">Ils nous font confiance</div><h3>Nos partenaires et marques traitées</h3></div>\r\n  <div class=\"brands-showcase-track\"><div class=\"brands-showcase-item\"><i class=\"fab fa-bmw\"></i> BMW</div><div class=\"brands-showcase-item\"><i class=\"fab fa-mercedes\"></i> MERCEDES</div><div class=\"brands-showcase-item\"><i class=\"fab fa-audible\"></i> AUDI</div><div class=\"brands-showcase-item\"><i class=\"fab fa-volkswagen\"></i> VOLKSWAGEN</div><div class=\"brands-showcase-item\"><i class=\"fas fa-car\"></i> RENAULT</div><div class=\"brands-showcase-item\"><i class=\"fas fa-car\"></i> PEUGEOT</div><div class=\"brands-showcase-item\"><i class=\"fas fa-car\"></i> TOYOTA</div><div class=\"brands-showcase-item\"><i class=\"fas fa-car\"></i> FORD</div><div class=\"brands-showcase-item\"><i class=\"fas fa-car\"></i> TESLA</div><div class=\"brands-showcase-item\"><i class=\"fab fa-bmw\"></i> BMW</div><div class=\"brands-showcase-item\"><i class=\"fab fa-mercedes\"></i> MERCEDES</div><div class=\"brands-showcase-item\"><i class=\"fab fa-audible\"></i> AUDI</div><div class=\"brands-showcase-item\"><i class=\"fab fa-volkswagen\"></i> VOLKSWAGEN</div><div class=\"brands-showcase-item\"><i class=\"fas fa-car\"></i> RENAULT</div><div class=\"brands-showcase-item\"><i class=\"fas fa-car\"></i> PEUGEOT</div></div></div>\r\n</section>', '.brands-showcase{padding:60px 0;background:#fff;overflow:hidden;}\r\n.brands-showcase-container{max-width:1280px;margin:0 auto;padding:0 40px;}\r\n.brands-showcase-header{text-align:center;margin-bottom:40px;}\r\n.brands-showcase-header .tag{font-size:11px;font-weight:600;letter-spacing:2px;text-transform:uppercase;color:#999;margin-bottom:10px;}\r\n.brands-showcase-header h3{font-size:24px;font-weight:700;color:#1A1A1A;}\r\n.brands-showcase-track{display:flex;gap:50px;animation:scrollBrands 20s linear infinite;width:max-content;}\r\n.brands-showcase-item{display:flex;align-items:center;gap:8px;font-family:\'Bebas Neue\',sans-serif;font-size:28px;letter-spacing:2px;color:#ccc;transition:color .3s;white-space:nowrap;}\r\n.brands-showcase-item:hover{color:#D4A537;}\r\n.brands-showcase-item i{margin-right:8px;font-size:24px;}\r\n@keyframes scrollBrands{0%{transform:translateX(0);}100%{transform:translateX(-50%);}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 2, 0, 0, 0, 1, '2026-06-04 10:48:10', '2026-06-04 10:56:34'),
(201, NULL, 'SNOW CONTAINER', 'snow-container', NULL, NULL, 'fa-cube', '<div class=\"snow-css-only\">\r\n  <div></div><div></div><div></div><div></div><div></div>\r\n  <div></div><div></div><div></div><div></div><div></div>\r\n  <div></div><div></div><div></div><div></div><div></div>\r\n  <div></div><div></div><div></div><div></div><div></div>\r\n</div>', '.snow-css-only {\r\n    position: fixed;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    pointer-events: none;\r\n    z-index: 9999;\r\n    overflow: hidden;\r\n    background: transparent;\r\n  }\r\n  .snow-css-only div {\r\n    position: absolute;\r\n    top: -10px;\r\n    border-radius: 50%;\r\n    background: white;\r\n    opacity: 0.7;\r\n    animation: fall-snow linear infinite;\r\n  }\r\n  .snow-css-only div:nth-child(1) { left: 5%; width: 4px; height: 4px; animation-duration: 8s; animation-delay: 0s; }\r\n  .snow-css-only div:nth-child(2) { left: 15%; width: 6px; height: 6px; animation-duration: 10s; animation-delay: 2s; }\r\n  .snow-css-only div:nth-child(3) { left: 25%; width: 3px; height: 3px; animation-duration: 7s; animation-delay: 1s; }\r\n  .snow-css-only div:nth-child(4) { left: 35%; width: 5px; height: 5px; animation-duration: 12s; animation-delay: 0.5s; }\r\n  .snow-css-only div:nth-child(5) { left: 45%; width: 4px; height: 4px; animation-duration: 9s; animation-delay: 3s; }\r\n  .snow-css-only div:nth-child(6) { left: 55%; width: 7px; height: 7px; animation-duration: 11s; animation-delay: 1.5s; }\r\n  .snow-css-only div:nth-child(7) { left: 65%; width: 3px; height: 3px; animation-duration: 6s; animation-delay: 4s; }\r\n  .snow-css-only div:nth-child(8) { left: 75%; width: 5px; height: 5px; animation-duration: 13s; animation-delay: 0.8s; }\r\n  .snow-css-only div:nth-child(9) { left: 85%; width: 4px; height: 4px; animation-duration: 8.5s; animation-delay: 2.5s; }\r\n  .snow-css-only div:nth-child(10) { left: 95%; width: 6px; height: 6px; animation-duration: 9.5s; animation-delay: 1.2s; }\r\n  .snow-css-only div:nth-child(11) { left: 10%; width: 5px; height: 5px; animation-duration: 14s; animation-delay: 0.3s; }\r\n  .snow-css-only div:nth-child(12) { left: 20%; width: 3px; height: 3px; animation-duration: 7.5s; animation-delay: 3.5s; }\r\n  .snow-css-only div:nth-child(13) { left: 30%; width: 6px; height: 6px; animation-duration: 10.5s; animation-delay: 1.8s; }\r\n  .snow-css-only div:nth-child(14) { left: 40%; width: 4px; height: 4px; animation-duration: 8.2s; animation-delay: 4.2s; }\r\n  .snow-css-only div:nth-child(15) { left: 50%; width: 7px; height: 7px; animation-duration: 11.5s; animation-delay: 0.7s; }\r\n  .snow-css-only div:nth-child(16) { left: 60%; width: 3px; height: 3px; animation-duration: 6.8s; animation-delay: 2.8s; }\r\n  .snow-css-only div:nth-child(17) { left: 70%; width: 5px; height: 5px; animation-duration: 9.2s; animation-delay: 1.1s; }\r\n  .snow-css-only div:nth-child(18) { left: 80%; width: 4px; height: 4px; animation-duration: 12.5s; animation-delay: 3.2s; }\r\n  .snow-css-only div:nth-child(19) { left: 90%; width: 6px; height: 6px; animation-duration: 7.8s; animation-delay: 0.9s; }\r\n  .snow-css-only div:nth-child(20) { left: 100%; width: 3px; height: 3px; animation-duration: 10.8s; animation-delay: 2.2s; }\r\n  @keyframes fall-snow {\r\n    0% {\r\n      transform: translateY(-20px) translateX(0);\r\n      opacity: 0.8;\r\n    }\r\n    100% {\r\n      transform: translateY(100vh) translateX(20px);\r\n      opacity: 0;\r\n    }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 3, 0, 0, 1, '2026-06-05 09:38:04', '2026-06-05 12:49:28'),
(202, NULL, 'Navigation', 'navigation', NULL, NULL, 'fa-cube', '<nav class=\"nav-block\" id=\"navbarBlock\">\r\n  <a href=\"#\" class=\"nav-logo-block\">Chalet<span>Nordique</span></a>\r\n  <ul class=\"nav-links-block\">\r\n    <li><a href=\"#chalets\">Chalets</a></li>\r\n    <li><a href=\"#amenities\">Équipements</a></li>\r\n    <li><a href=\"#experiences\">Expériences</a></li>\r\n    <li><a href=\"#galerie\">Galerie</a></li>\r\n    <li><a href=\"#avis\">Avis</a></li>\r\n    <li><a href=\"#contact\">Contact</a></li>\r\n    <li><a href=\"#reservation\" class=\"nav-cta-block\">Réserver</a></li>\r\n  </ul>\r\n  <div class=\"hamburger-block\" onclick=\"toggleMenuBlock()\">\r\n    <span></span><span></span><span></span>\r\n  </div>\r\n</nav>\r\n\r\n<script>\r\n  window.addEventListener(\'scroll\', function() {\r\n    var nav = document.getElementById(\'navbarBlock\');\r\n    if (nav) {\r\n      if (window.scrollY > 60) {\r\n        nav.classList.add(\'scrolled\');\r\n      } else {\r\n        nav.classList.remove(\'scrolled\');\r\n      }\r\n    }\r\n  });\r\n  function toggleMenuBlock() {\r\n    var links = document.querySelector(\'.nav-links-block\');\r\n    if (links) {\r\n      if (links.style.display === \'flex\') {\r\n        links.style.display = \'\';\r\n      } else {\r\n        links.style.cssText = \'display:flex;flex-direction:column;position:fixed;top:60px;left:0;right:0;background:#0d2137;padding:24px 24px 32px;gap:20px;z-index:800;\';\r\n      }\r\n    }\r\n  }\r\n</script>', '.nav-block {\r\n    position: fixed;\r\n    top: 0;\r\n    left: 0;\r\n    right: 0;\r\n    z-index: 900;\r\n    padding: 20px 60px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    transition: all 0.4s ease;\r\n    background: transparent;\r\n  }\r\n  .nav-block.scrolled {\r\n    background: #0d2137;\r\n    backdrop-filter: blur(12px);\r\n    padding: 14px 60px;\r\n    box-shadow: 0 4px 30px rgba(0,0,0,0.3);\r\n  }\r\n  .nav-logo-block {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 26px;\r\n    font-weight: 700;\r\n    color: #ffffff;\r\n    letter-spacing: 1px;\r\n    text-decoration: none;\r\n  }\r\n  .nav-logo-block span { color: #d4a843; }\r\n  .nav-links-block {\r\n    display: flex;\r\n    gap: 36px;\r\n    list-style: none;\r\n    margin: 0;\r\n    padding: 0;\r\n  }\r\n  .nav-links-block li { margin: 0; }\r\n  .nav-links-block a {\r\n    color: #e8edf2;\r\n    text-decoration: none;\r\n    font-size: 14px;\r\n    font-weight: 500;\r\n    letter-spacing: 1.5px;\r\n    text-transform: uppercase;\r\n    transition: color 0.3s;\r\n  }\r\n  .nav-links-block a:hover { color: #d4a843; }\r\n  .nav-cta-block {\r\n    background: #c8793a;\r\n    color: #ffffff !important;\r\n    padding: 10px 24px;\r\n    border-radius: 2px;\r\n  }\r\n  .nav-cta-block:hover { background: #e8521a !important; color: #ffffff !important; }\r\n  .hamburger-block {\r\n    display: none;\r\n    flex-direction: column;\r\n    gap: 5px;\r\n    cursor: pointer;\r\n  }\r\n  .hamburger-block span {\r\n    width: 25px;\r\n    height: 2px;\r\n    background: #ffffff;\r\n    transition: 0.3s;\r\n  }\r\n  @media (max-width: 992px) {\r\n    .nav-block { padding: 16px 24px; }\r\n    .nav-block.scrolled { padding: 14px 24px; }\r\n    .nav-links-block { display: none; }\r\n    .hamburger-block { display: flex; }\r\n  }', NULL, NULL, 'Header', 'General', '[]', 1, 1, NULL, NULL, 1, 1, 0, 0, 1, '2026-06-05 09:39:39', '2026-07-25 19:49:11'),
(203, NULL, 'Hero snow landing', 'hero-snow-landing', NULL, NULL, 'fa-cube', '<section class=\"hero-block\">\r\n  <video class=\"hero-video-bg-block\" autoplay muted loop playsinline>\r\n    <source src=\"https://www.w3schools.com/html/mov_bbb.mp4\" type=\"video/mp4\">\r\n  </video>\r\n  <div class=\"hero-overlay-block\"></div>\r\n  <div class=\"hero-content-block\">\r\n    <div class=\"hero-badge-block\">✦ Laurentides · Charlevoix · Québec ✦</div>\r\n    <h1>L\'Hiver<br><em>Comme vous</em><br>ne l\'avez jamais vécu</h1>\r\n    <p>Chalets de luxe au cœur des forêts enneigées du Québec</p>\r\n    <div class=\"hero-btns-block\">\r\n      <a href=\"#chalets\" class=\"btn-gold-block\">Voir les chalets</a>\r\n      <a href=\"#reservation\" class=\"btn-outline-block\">Réserver maintenant</a>\r\n    </div>\r\n  </div>\r\n  <div class=\"hero-stats-block\">\r\n    <div class=\"hero-stat-block\"><div class=\"num\">47</div><div class=\"label\">Chalets disponibles</div></div>\r\n    <div class=\"hero-stat-block\"><div class=\"num\">98%</div><div class=\"label\">Satisfaction</div></div>\r\n    <div class=\"hero-stat-block\"><div class=\"num\">12+</div><div class=\"label\">Années d\'expérience</div></div>\r\n    <div class=\"hero-stat-block\"><div class=\"num\">5★</div><div class=\"label\">Note moyenne</div></div>\r\n  </div>\r\n  <div class=\"scroll-hint-block\"><span>Défiler</span><div class=\"scroll-line-block\"></div></div>\r\n</section>', '.hero-block {\r\n    position: relative;\r\n    height: 100vh;\r\n    min-height: 700px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    overflow: hidden;\r\n    background: #0d2137;\r\n    width: 100%;\r\n  }\r\n  .hero-video-bg-block {\r\n    position: absolute;\r\n    top: 0;\r\n    right: 0;\r\n    bottom: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    object-fit: cover;\r\n    filter: brightness(0.5) saturate(0.8);\r\n    z-index: 0;\r\n  }\r\n  .hero-overlay-block {\r\n    position: absolute;\r\n    top: 0;\r\n    right: 0;\r\n    bottom: 0;\r\n    left: 0;\r\n    background: linear-gradient(160deg, rgba(13,33,55,0.6) 0%, rgba(13,33,55,0.2) 50%, rgba(13,33,55,0.8) 100%);\r\n    z-index: 1;\r\n  }\r\n  .hero-content-block {\r\n    position: relative;\r\n    z-index: 2;\r\n    max-width: 1280px;\r\n    margin: 0 auto;\r\n    padding: 0 40px;\r\n    text-align: center;\r\n    color: #ffffff;\r\n  }\r\n  .hero-badge-block {\r\n    display: inline-block;\r\n    border: 1px solid #d4a843;\r\n    color: #d4a843;\r\n    font-size: 11px;\r\n    letter-spacing: 3px;\r\n    text-transform: uppercase;\r\n    padding: 6px 20px;\r\n    margin-bottom: 28px;\r\n    background: transparent;\r\n  }\r\n  .hero-block h1 {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: clamp(48px, 8vw, 110px);\r\n    font-weight: 900;\r\n    line-height: 1.05;\r\n    margin-bottom: 24px;\r\n    color: #ffffff;\r\n  }\r\n  .hero-block h1 em {\r\n    color: #d4a843;\r\n    font-style: italic;\r\n  }\r\n  .hero-block p {\r\n    font-size: clamp(16px, 2vw, 19px);\r\n    font-weight: 300;\r\n    color: #dce8f0;\r\n    max-width: 600px;\r\n    margin: 0 auto 48px;\r\n    line-height: 1.7;\r\n  }\r\n  .hero-btns-block {\r\n    display: flex;\r\n    gap: 16px;\r\n    justify-content: center;\r\n    flex-wrap: wrap;\r\n  }\r\n  .btn-gold-block {\r\n    background: #c8793a;\r\n    color: #ffffff;\r\n    padding: 16px 40px;\r\n    font-family: \'Raleway\', sans-serif;\r\n    font-weight: 600;\r\n    font-size: 14px;\r\n    letter-spacing: 2px;\r\n    text-transform: uppercase;\r\n    text-decoration: none;\r\n    transition: all 0.3s;\r\n    display: inline-block;\r\n    border: none;\r\n    cursor: pointer;\r\n  }\r\n  .btn-gold-block:hover {\r\n    background: #e8521a;\r\n    transform: translateY(-2px);\r\n    box-shadow: 0 8px 25px rgba(200,121,58,0.4);\r\n  }\r\n  .btn-outline-block {\r\n    border: 1px solid rgba(255,255,255,0.6);\r\n    color: #ffffff;\r\n    padding: 16px 40px;\r\n    font-family: \'Raleway\', sans-serif;\r\n    font-weight: 500;\r\n    font-size: 14px;\r\n    letter-spacing: 2px;\r\n    text-transform: uppercase;\r\n    text-decoration: none;\r\n    transition: all 0.3s;\r\n    display: inline-block;\r\n    background: transparent;\r\n    cursor: pointer;\r\n  }\r\n  .btn-outline-block:hover {\r\n    background: rgba(255,255,255,0.1);\r\n    border-color: #ffffff;\r\n  }\r\n  .hero-stats-block {\r\n    position: absolute;\r\n    bottom: 40px;\r\n    left: 0;\r\n    right: 0;\r\n    display: flex;\r\n    justify-content: center;\r\n    gap: 80px;\r\n    flex-wrap: wrap;\r\n    z-index: 2;\r\n  }\r\n  .hero-stat-block {\r\n    text-align: center;\r\n  }\r\n  .hero-stat-block .num {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 36px;\r\n    font-weight: 700;\r\n    color: #d4a843;\r\n  }\r\n  .hero-stat-block .label {\r\n    font-size: 12px;\r\n    letter-spacing: 2px;\r\n    text-transform: uppercase;\r\n    color: #b8d4e8;\r\n    margin-top: 6px;\r\n  }\r\n  .scroll-hint-block {\r\n    position: absolute;\r\n    bottom: 28px;\r\n    left: 50%;\r\n    transform: translateX(-50%);\r\n    z-index: 3;\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    gap: 8px;\r\n  }\r\n  .scroll-hint-block span {\r\n    font-size: 11px;\r\n    letter-spacing: 2px;\r\n    text-transform: uppercase;\r\n    color: #b8d4e8;\r\n  }\r\n  .scroll-line-block {\r\n    width: 1px;\r\n    height: 50px;\r\n    background: linear-gradient(to bottom, #b8d4e8, transparent);\r\n    animation: scrollPulseBlock 2s ease-in-out infinite;\r\n  }\r\n  @keyframes scrollPulseBlock {\r\n    0%, 100% { transform: scaleY(1); opacity: 1; }\r\n    50% { transform: scaleY(0.5); opacity: 0.4; }\r\n  }\r\n  @media (max-width: 768px) {\r\n    .hero-stats-block { gap: 30px; }\r\n    .hero-stat-block .num { font-size: 24px; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 1, 0, 0, 0, 1, '2026-06-05 09:47:33', '2026-06-05 11:49:04'),
(204, NULL, 'stats bar', 'stats-bar', NULL, NULL, 'fa-cube', '<div class=\"stats-block\">\r\n  <div class=\"stat-item-block\"><div class=\"stat-num-block\">47</div><div class=\"stat-label-block\">Chalets disponibles</div></div>\r\n  <div class=\"stat-item-block\"><div class=\"stat-num-block\">98%</div><div class=\"stat-label-block\">Satisfaction clients</div></div>\r\n  <div class=\"stat-item-block\"><div class=\"stat-num-block\">12+</div><div class=\"stat-label-block\">Années d\'expérience</div></div>\r\n  <div class=\"stat-item-block\"><div class=\"stat-num-block\">5★</div><div class=\"stat-label-block\">Note moyenne</div></div>\r\n</div>', '.stats-block {\r\n    background: rgba(255,255,255,0.04);\r\n    backdrop-filter: blur(10px);\r\n    border-top: 1px solid rgba(255,255,255,0.08);\r\n    border-bottom: 1px solid rgba(255,255,255,0.08);\r\n    padding: 28px 60px;\r\n    display: grid;\r\n    grid-template-columns: repeat(4, 1fr);\r\n    text-align: center;\r\n    gap: 20px;\r\n  }\r\n  .stat-item-block { position: relative; }\r\n  .stat-item-block:not(:last-child)::after {\r\n    content: \'\';\r\n    position: absolute;\r\n    right: 0;\r\n    top: 10%;\r\n    bottom: 10%;\r\n    width: 1px;\r\n    background: rgba(255,255,255,0.1);\r\n  }\r\n  .stat-num-block {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 38px;\r\n    font-weight: 700;\r\n    color: #d4a843;\r\n    line-height: 1;\r\n  }\r\n  .stat-label-block {\r\n    font-size: 12px;\r\n    letter-spacing: 2px;\r\n    text-transform: uppercase;\r\n    color: #b8d4e8;\r\n    margin-top: 6px;\r\n  }\r\n  @media (max-width: 992px) {\r\n    .stats-block { grid-template-columns: repeat(2, 1fr); padding: 24px; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-05 09:57:13', '2026-06-05 11:49:42'),
(205, NULL, 'About', 'about-3', NULL, NULL, 'fa-cube', '<section class=\"about-block\" id=\"about\">\r\n  <!-- Colonne image -->\r\n  <div class=\"about-img-wrap-block\">\r\n    <img src=\"https://t3.ftcdn.net/jpg/02/23/55/34/240_F_223553493_L8eOs90xg8fkfkjr2Xzpq3jaJqdclM1w.jpg\" alt=\"Chalet enneigé\" loading=\"lazy\">\r\n    <div class=\"about-img-badge-block\">\r\n      <strong>2024</strong>\r\n      <span>Meilleure location</span>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Colonne texte -->\r\n  <div class=\"about-text-col-block\">\r\n    <span class=\"tag-block\">✦ Notre histoire</span>\r\n    <h2>Des chalets <em>authentiques</em><br>au cœur du Québec</h2>\r\n    <div class=\"divider-block\"></div>\r\n    <p>Depuis 2012, ChaletNordique sélectionne avec soin les plus beaux refuges hivernaux de la province. Chaque propriété est choisie pour son authenticité, son confort et son harmonie avec la nature environnante.</p>\r\n    <br>\r\n    <p>Foyers crépitants, panoramas enneigés, spas extérieurs sous les étoiles — nos chalets transforment chaque séjour en souvenir impérissable.</p>\r\n    <br>\r\n    <a href=\"#chalets\" class=\"btn-about-block\">Découvrir nos propriétés</a>\r\n  </div>\r\n</section>', '/* Conteneur principal avec largeur explicite */\r\n  .about-block {\r\n    background: #162b40;\r\n    display: grid;\r\n    grid-template-columns: 1fr 1fr;\r\n    gap: 80px;\r\n    align-items: center;\r\n    padding: 100px 60px;\r\n    max-width: 100%;\r\n    width: 100%;\r\n    box-sizing: border-box;\r\n  }\r\n\r\n  /* Colonne image */\r\n  .about-img-wrap-block {\r\n    position: relative;\r\n    width: 100%;\r\n    max-width: 100%;\r\n  }\r\n  .about-img-wrap-block img {\r\n    width: 100%;\r\n    height: auto;\r\n    aspect-ratio: 4/5;\r\n    object-fit: cover;\r\n    border-radius: 2px;\r\n    display: block;\r\n  }\r\n\r\n  /* Badge sur l\'image */\r\n  .about-img-badge-block {\r\n    position: absolute;\r\n    bottom: -24px;\r\n    right: -24px;\r\n    background: #c8793a;\r\n    padding: 28px 32px;\r\n    text-align: center;\r\n    min-width: 120px;\r\n  }\r\n  .about-img-badge-block strong {\r\n    display: block;\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 38px;\r\n    font-weight: 900;\r\n    color: #ffffff;\r\n    line-height: 1;\r\n  }\r\n  .about-img-badge-block span {\r\n    font-size: 11px;\r\n    letter-spacing: 2px;\r\n    text-transform: uppercase;\r\n    color: rgba(255,255,255,0.8);\r\n  }\r\n\r\n  /* Colonne texte */\r\n  .about-text-col-block {\r\n    width: 100%;\r\n    max-width: 100%;\r\n    display: flex;\r\n    flex-direction: column;\r\n  }\r\n  .about-block .tag-block {\r\n    font-size: 11px;\r\n    letter-spacing: 3px;\r\n    text-transform: uppercase;\r\n    color: #d4a843;\r\n    margin-bottom: 16px;\r\n    display: block;\r\n  }\r\n  .about-block h2 {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 42px;\r\n    font-weight: 700;\r\n    line-height: 1.15;\r\n    margin-bottom: 20px;\r\n    color: #f0f4f8;\r\n  }\r\n  .about-block h2 em {\r\n    color: #d4a843;\r\n    font-style: italic;\r\n  }\r\n  .about-block p {\r\n    font-size: 16px;\r\n    font-weight: 300;\r\n    line-height: 1.8;\r\n    color: #b8d4e8;\r\n    max-width: 540px;\r\n    margin-bottom: 0;\r\n  }\r\n  .divider-block {\r\n    width: 60px;\r\n    height: 2px;\r\n    background: #c8793a;\r\n    margin: 24px 0;\r\n  }\r\n\r\n  /* Bouton */\r\n  .btn-about-block {\r\n    background: #c8793a;\r\n    color: #ffffff;\r\n    padding: 16px 40px;\r\n    font-family: \'Raleway\', sans-serif;\r\n    font-weight: 600;\r\n    font-size: 14px;\r\n    letter-spacing: 2px;\r\n    text-transform: uppercase;\r\n    text-decoration: none;\r\n    transition: all 0.3s;\r\n    display: inline-block;\r\n    border: none;\r\n    cursor: pointer;\r\n    margin-top: 16px;\r\n    width: fit-content;\r\n  }\r\n  .btn-about-block:hover {\r\n    background: #e8521a;\r\n    transform: translateY(-2px);\r\n  }\r\n\r\n  /* Responsive */\r\n  @media (max-width: 992px) {\r\n    .about-block {\r\n      grid-template-columns: 1fr;\r\n      gap: 60px;\r\n      padding: 70px 24px;\r\n    }\r\n    .about-img-badge-block {\r\n      bottom: -16px;\r\n      right: -8px;\r\n      padding: 18px 20px;\r\n    }\r\n    .about-img-badge-block strong {\r\n      font-size: 28px;\r\n    }\r\n    .about-block h2 {\r\n      font-size: 32px;\r\n    }\r\n    .about-block p {\r\n      max-width: 100%;\r\n    }\r\n  }\r\n\r\n  @media (max-width: 576px) {\r\n    .about-block {\r\n      padding: 50px 16px;\r\n      gap: 40px;\r\n    }\r\n    .about-img-badge-block {\r\n      position: relative;\r\n      bottom: 0;\r\n      right: 0;\r\n      margin-top: -4px;\r\n      width: 100%;\r\n      padding: 16px 20px;\r\n    }\r\n    .btn-about-block {\r\n      width: 100%;\r\n      text-align: center;\r\n    }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 3, 0, 0, 1, '2026-06-05 09:58:53', '2026-06-30 19:15:28');
INSERT INTO `blocks` (`id`, `categorie_id`, `name`, `slug`, `description`, `thumbnail`, `icon`, `html_content`, `css_content`, `js_content`, `section_id`, `category`, `website_type`, `tags`, `is_responsive`, `is_free`, `width`, `height`, `usage_count`, `views_count`, `rating`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(206, NULL, 'Chalets Grid', 'chalets-grid', NULL, NULL, 'fa-cube', '<section class=\"chalets-block\" id=\"chalets\">\r\n  <div class=\"chalets-header-block\">\r\n    <span class=\"section-tag-block\">✦ Nos propriétés</span>\r\n    <h2>Chalets <em>d\'exception</em></h2>\r\n    <p>Chaque chalet est une invitation au bien-être et à la découverte de l\'hiver québécois.</p>\r\n  </div>\r\n\r\n  <div class=\"chalets-grid-block\">\r\n    <!-- Chalet 1 -->\r\n    <div class=\"chalet-card-block\">\r\n      <div class=\"chalet-img-block\">\r\n        <img src=\"https://t3.ftcdn.net/jpg/02/23/55/34/240_F_223553493_L8eOs90xg8fkfkjr2Xzpq3jaJqdclM1w.jpg\" alt=\"Chalet Boréal\" loading=\"lazy\">\r\n        <span class=\"chalet-tag-block\">Populaire</span>\r\n        <button class=\"chalet-fav-block\">♡</button>\r\n      </div>\r\n      <div class=\"chalet-body-block\">\r\n        <div class=\"chalet-stars-block\">★★★★★</div>\r\n        <div class=\"chalet-name-block\">Chalet Boréal</div>\r\n        <div class=\"chalet-location-block\">📍 Mont-Tremblant, Laurentides</div>\r\n        <div class=\"chalet-amenities-block\">\r\n          <span>🛏 4 chambres</span>\r\n          <span>🚿 3 sdb</span>\r\n          <span>🧖 Spa</span>\r\n          <span>🔥 Foyer</span>\r\n        </div>\r\n        <div class=\"chalet-footer-block\">\r\n          <div class=\"chalet-price-block\"><sup>$</sup><strong>349</strong><span>/nuit</span></div>\r\n          <a href=\"#reservation\" class=\"chalet-btn-block\">Réserver</a>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Chalet 2 -->\r\n    <div class=\"chalet-card-block\">\r\n      <div class=\"chalet-img-block\">\r\n        <img src=\"https://t4.ftcdn.net/jpg/06/79/31/43/240_F_679314308_Bh89sE0s4WIeMmyRNXwxP8a7Rw0iayXl.jpg\" alt=\"Refuge du Lac\" loading=\"lazy\">\r\n        <span class=\"chalet-tag-block\" style=\"background:#2d4a2d\">Coup de ❤️</span>\r\n        <button class=\"chalet-fav-block\">♡</button>\r\n      </div>\r\n      <div class=\"chalet-body-block\">\r\n        <div class=\"chalet-stars-block\">★★★★★</div>\r\n        <div class=\"chalet-name-block\">Refuge du Lac</div>\r\n        <div class=\"chalet-location-block\">📍 Charlevoix, Québec</div>\r\n        <div class=\"chalet-amenities-block\">\r\n          <span>🛏 6 chambres</span>\r\n          <span>🚿 4 sdb</span>\r\n          <span>🧖 Spa extérieur</span>\r\n          <span>⛷ Ski</span>\r\n        </div>\r\n        <div class=\"chalet-footer-block\">\r\n          <div class=\"chalet-price-block\"><sup>$</sup><strong>529</strong><span>/nuit</span></div>\r\n          <a href=\"#reservation\" class=\"chalet-btn-block\">Réserver</a>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Chalet 3 -->\r\n    <div class=\"chalet-card-block\">\r\n      <div class=\"chalet-img-block\">\r\n        <img src=\"https://t3.ftcdn.net/jpg/11/75/63/74/240_F_1175637440_GRxjqkU9sSUwGin3o4R2bNYZQBCs8lVB.jpg\" alt=\"L\'Éclaircie\" loading=\"lazy\">\r\n        <span class=\"chalet-tag-block\" style=\"background:#0d2137\">Nouveau</span>\r\n        <button class=\"chalet-fav-block\">♡</button>\r\n      </div>\r\n      <div class=\"chalet-body-block\">\r\n        <div class=\"chalet-stars-block\">★★★★★</div>\r\n        <div class=\"chalet-name-block\">L\'Éclaircie</div>\r\n        <div class=\"chalet-location-block\">📍 Lac-Saint-Jean, Québec</div>\r\n        <div class=\"chalet-amenities-block\">\r\n          <span>🛏 3 chambres</span>\r\n          <span>🚿 2 sdb</span>\r\n          <span>🌲 Forêt privée</span>\r\n          <span>🎿 Raquettes</span>\r\n        </div>\r\n        <div class=\"chalet-footer-block\">\r\n          <div class=\"chalet-price-block\"><sup>$</sup><strong>249</strong><span>/nuit</span></div>\r\n          <a href=\"#reservation\" class=\"chalet-btn-block\">Réserver</a>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Chalet 4 -->\r\n    <div class=\"chalet-card-block\">\r\n      <div class=\"chalet-img-block\">\r\n        <img src=\"https://t3.ftcdn.net/jpg/09/89/24/82/240_F_989248260_60QnHDqcKh0d0y0MbPbyZuqQVR0ENERN.jpg\" alt=\"Villa Rivière\" loading=\"lazy\">\r\n        <span class=\"chalet-tag-block\">Premium</span>\r\n        <button class=\"chalet-fav-block\">♡</button>\r\n      </div>\r\n      <div class=\"chalet-body-block\">\r\n        <div class=\"chalet-stars-block\">★★★★★</div>\r\n        <div class=\"chalet-name-block\">Villa Rivière</div>\r\n        <div class=\"chalet-location-block\">📍 Sainte-Adèle, Laurentides</div>\r\n        <div class=\"chalet-amenities-block\">\r\n          <span>🛏 5 chambres</span>\r\n          <span>🚿 3 sdb</span>\r\n          <span>🏊 Piscine chauffée</span>\r\n          <span>🔥 Foyer</span>\r\n        </div>\r\n        <div class=\"chalet-footer-block\">\r\n          <div class=\"chalet-price-block\"><sup>$</sup><strong>429</strong><span>/nuit</span></div>\r\n          <a href=\"#reservation\" class=\"chalet-btn-block\">Réserver</a>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Chalet 5 -->\r\n    <div class=\"chalet-card-block\">\r\n      <div class=\"chalet-img-block\">\r\n        <img src=\"https://t3.ftcdn.net/jpg/04/58/22/90/240_F_458229054_NQCNTeMPMeKA56uTRgty32OkY7MxWDp4.jpg\" alt=\"Le Sommet\" loading=\"lazy\">\r\n        <span class=\"chalet-tag-block\" style=\"background:#2d4a2d\">Luxe</span>\r\n        <button class=\"chalet-fav-block\">♡</button>\r\n      </div>\r\n      <div class=\"chalet-body-block\">\r\n        <div class=\"chalet-stars-block\">★★★★★</div>\r\n        <div class=\"chalet-name-block\">Le Sommet</div>\r\n        <div class=\"chalet-location-block\">📍 Mont-Sainte-Anne, Québec</div>\r\n        <div class=\"chalet-amenities-block\">\r\n          <span>🛏 8 chambres</span>\r\n          <span>🚿 5 sdb</span>\r\n          <span>🧖 Spa luxe</span>\r\n          <span>⛷ Ski direct</span>\r\n        </div>\r\n        <div class=\"chalet-footer-block\">\r\n          <div class=\"chalet-price-block\"><sup>$</sup><strong>749</strong><span>/nuit</span></div>\r\n          <a href=\"#reservation\" class=\"chalet-btn-block\">Réserver</a>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Chalet 6 -->\r\n    <div class=\"chalet-card-block\">\r\n      <div class=\"chalet-img-block\">\r\n        <img src=\"https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=700&q=80\" alt=\"Cabane Érable\" loading=\"lazy\">\r\n        <span class=\"chalet-tag-block\">Éco</span>\r\n        <button class=\"chalet-fav-block\">♡</button>\r\n      </div>\r\n      <div class=\"chalet-body-block\">\r\n        <div class=\"chalet-stars-block\">★★★★★</div>\r\n        <div class=\"chalet-name-block\">Cabane Érable</div>\r\n        <div class=\"chalet-location-block\">📍 Estrie, Cantons-de-l\'Est</div>\r\n        <div class=\"chalet-amenities-block\">\r\n          <span>🛏 2 chambres</span>\r\n          <span>🚿 1 sdb</span>\r\n          <span>🍁 Érablière</span>\r\n          <span>🌲 Randonnée</span>\r\n        </div>\r\n        <div class=\"chalet-footer-block\">\r\n          <div class=\"chalet-price-block\"><sup>$</sup><strong>189</strong><span>/nuit</span></div>\r\n          <a href=\"#reservation\" class=\"chalet-btn-block\">Réserver</a>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>', '/* Conteneur principal */\r\n  .chalets-block {\r\n    background: #1a1a2e;\r\n    padding: 100px 60px;\r\n    width: 100%;\r\n    max-width: 100%;\r\n    box-sizing: border-box;\r\n  }\r\n\r\n  /* En-tête */\r\n  .chalets-header-block {\r\n    text-align: center;\r\n    margin-bottom: 60px;\r\n    width: 100%;\r\n  }\r\n  .chalets-header-block .section-tag-block {\r\n    font-size: 11px;\r\n    letter-spacing: 3px;\r\n    text-transform: uppercase;\r\n    color: #d4a843;\r\n    margin-bottom: 16px;\r\n    display: inline-block;\r\n  }\r\n  .chalets-header-block h2 {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 42px;\r\n    font-weight: 700;\r\n    line-height: 1.15;\r\n    margin-bottom: 20px;\r\n    color: #f0f4f8;\r\n  }\r\n  .chalets-header-block h2 em {\r\n    color: #d4a843;\r\n    font-style: italic;\r\n  }\r\n  .chalets-header-block p {\r\n    font-size: 16px;\r\n    font-weight: 300;\r\n    line-height: 1.8;\r\n    color: #b8d4e8;\r\n    max-width: 600px;\r\n    margin: 0 auto;\r\n  }\r\n\r\n  /* Grille des chalets */\r\n  .chalets-grid-block {\r\n    display: grid;\r\n    grid-template-columns: repeat(3, 1fr);\r\n    gap: 24px;\r\n    max-width: 1200px;\r\n    margin: 0 auto;\r\n    width: 100%;\r\n  }\r\n\r\n  /* Carte chalet */\r\n  .chalet-card-block {\r\n    background: rgba(255,255,255,0.03);\r\n    border: 1px solid rgba(255,255,255,0.06);\r\n    overflow: hidden;\r\n    transition: transform 0.4s, box-shadow 0.4s;\r\n    width: 100%;\r\n    display: flex;\r\n    flex-direction: column;\r\n  }\r\n  .chalet-card-block:hover {\r\n    transform: translateY(-8px);\r\n    box-shadow: 0 20px 50px rgba(0,0,0,0.4);\r\n  }\r\n\r\n  /* Image */\r\n  .chalet-img-block {\r\n    position: relative;\r\n    overflow: hidden;\r\n    aspect-ratio: 4/3;\r\n    width: 100%;\r\n    background: #0d0d1a;\r\n  }\r\n  .chalet-img-block img {\r\n    width: 100%;\r\n    height: 100%;\r\n    object-fit: cover;\r\n    transition: transform 0.6s;\r\n    display: block;\r\n  }\r\n  .chalet-card-block:hover .chalet-img-block img {\r\n    transform: scale(1.06);\r\n  }\r\n\r\n  /* Tags */\r\n  .chalet-tag-block {\r\n    position: absolute;\r\n    top: 16px;\r\n    left: 16px;\r\n    background: #c8793a;\r\n    color: #ffffff;\r\n    font-size: 11px;\r\n    letter-spacing: 2px;\r\n    text-transform: uppercase;\r\n    padding: 5px 12px;\r\n    z-index: 2;\r\n  }\r\n\r\n  /* Bouton favori */\r\n  .chalet-fav-block {\r\n    position: absolute;\r\n    top: 16px;\r\n    right: 16px;\r\n    width: 36px;\r\n    height: 36px;\r\n    background: rgba(255,255,255,0.15);\r\n    backdrop-filter: blur(6px);\r\n    border-radius: 50%;\r\n    border: none;\r\n    cursor: pointer;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-size: 16px;\r\n    transition: background 0.3s;\r\n    color: #ffffff;\r\n    z-index: 2;\r\n  }\r\n  .chalet-fav-block:hover {\r\n    background: rgba(200,121,58,0.8);\r\n  }\r\n\r\n  /* Corps de la carte */\r\n  .chalet-body-block {\r\n    padding: 24px;\r\n    flex: 1;\r\n    display: flex;\r\n    flex-direction: column;\r\n  }\r\n  .chalet-stars-block {\r\n    color: #d4a843;\r\n    font-size: 12px;\r\n    margin-bottom: 4px;\r\n  }\r\n  .chalet-name-block {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 21px;\r\n    font-weight: 700;\r\n    margin-bottom: 8px;\r\n    color: #f0f4f8;\r\n  }\r\n  .chalet-location-block {\r\n    font-size: 12px;\r\n    color: #d4a843;\r\n    letter-spacing: 1px;\r\n    text-transform: uppercase;\r\n    margin-bottom: 12px;\r\n  }\r\n  .chalet-amenities-block {\r\n    display: flex;\r\n    gap: 16px;\r\n    margin-bottom: 20px;\r\n    flex-wrap: wrap;\r\n  }\r\n  .chalet-amenities-block span {\r\n    font-size: 12px;\r\n    color: #b8d4e8;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 5px;\r\n  }\r\n\r\n  /* Footer de la carte */\r\n  .chalet-footer-block {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    margin-top: auto;\r\n    padding-top: 16px;\r\n    border-top: 1px solid rgba(255,255,255,0.06);\r\n  }\r\n  .chalet-price-block sup {\r\n    font-size: 12px;\r\n    vertical-align: super;\r\n  }\r\n  .chalet-price-block strong {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 28px;\r\n    color: #d4a843;\r\n  }\r\n  .chalet-price-block span {\r\n    font-size: 12px;\r\n    color: #b8d4e8;\r\n  }\r\n\r\n  /* Bouton réserver */\r\n  .chalet-btn-block {\r\n    background: transparent;\r\n    border: 1px solid #c8793a;\r\n    color: #c8793a;\r\n    padding: 9px 20px;\r\n    font-size: 12px;\r\n    letter-spacing: 1.5px;\r\n    text-transform: uppercase;\r\n    cursor: pointer;\r\n    transition: all 0.3s;\r\n    font-family: \'Raleway\', sans-serif;\r\n    text-decoration: none;\r\n    display: inline-block;\r\n  }\r\n  .chalet-btn-block:hover {\r\n    background: #c8793a;\r\n    color: #ffffff;\r\n  }\r\n\r\n  /* Responsive */\r\n  @media (max-width: 992px) {\r\n    .chalets-block {\r\n      padding: 70px 24px;\r\n    }\r\n    .chalets-grid-block {\r\n      grid-template-columns: repeat(2, 1fr);\r\n    }\r\n    .chalets-header-block h2 {\r\n      font-size: 34px;\r\n    }\r\n  }\r\n\r\n  @media (max-width: 768px) {\r\n    .chalets-grid-block {\r\n      grid-template-columns: 1fr;\r\n      gap: 20px;\r\n    }\r\n    .chalets-block {\r\n      padding: 50px 16px;\r\n    }\r\n    .chalets-header-block h2 {\r\n      font-size: 28px;\r\n    }\r\n    .chalets-header-block p {\r\n      font-size: 14px;\r\n    }\r\n    .chalet-body-block {\r\n      padding: 18px;\r\n    }\r\n    .chalet-price-block strong {\r\n      font-size: 24px;\r\n    }\r\n    .chalet-btn-block {\r\n      padding: 7px 14px;\r\n      font-size: 11px;\r\n    }\r\n  }', '// Gestion des favoris (cœur)\r\n  document.querySelectorAll(\'.chalet-fav-block\').forEach(function(btn) {\r\n    btn.addEventListener(\'click\', function(e) {\r\n      e.stopPropagation();\r\n      if (btn.textContent === \'♡\') {\r\n        btn.textContent = \'♥\';\r\n        btn.style.color = \'#e8521a\';\r\n      } else {\r\n        btn.textContent = \'♡\';\r\n        btn.style.color = \'#ffffff\';\r\n      }\r\n    });\r\n  });', NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-05 10:00:10', '2026-06-30 19:38:28'),
(207, NULL, 'Amenities', 'amenities', NULL, NULL, 'fa-cube', '<section class=\"amenities-block\" id=\"amenities\">\r\n  <span class=\"section-tag-block\">✦ Équipements inclus</span>\r\n  <h2>Tout le <em>confort</em> dont vous avez besoin</h2>\r\n  <div class=\"amenities-grid-block\">\r\n    <div class=\"amenity-item-block\"><span class=\"amenity-icon-block\">🛁</span><div class=\"amenity-name-block\">Spa & bain tourbillon</div><div class=\"amenity-desc-block\">Plongez dans un bain extérieur chauffé sous les étoiles et la neige.</div></div>\r\n    <div class=\"amenity-item-block\"><span class=\"amenity-icon-block\">🔥</span><div class=\"amenity-name-block\">Foyer au bois</div><div class=\"amenity-desc-block\">Chaque chalet dispose d\'un foyer traditionnel pour des soirées cocooning.</div></div>\r\n    <div class=\"amenity-item-block\"><span class=\"amenity-icon-block\">🍽️</span><div class=\"amenity-name-block\">Cuisine équipée</div><div class=\"amenity-desc-block\">Cuisines modernes entièrement équipées avec électroménagers haut de gamme.</div></div>\r\n    <div class=\"amenity-item-block\"><span class=\"amenity-icon-block\">📶</span><div class=\"amenity-name-block\">WiFi haute vitesse</div><div class=\"amenity-desc-block\">Connectivité fibre optique pour le télétravail ou le divertissement.</div></div>\r\n    <div class=\"amenity-item-block\"><span class=\"amenity-icon-block\">🎿</span><div class=\"amenity-name-block\">Équipement ski</div><div class=\"amenity-desc-block\">Location de skis, raquettes et motoneiges disponible sur demande.</div></div>\r\n    <div class=\"amenity-item-block\"><span class=\"amenity-icon-block\">🅿️</span><div class=\"amenity-name-block\">Stationnement privé</div><div class=\"amenity-desc-block\">Entrée privée et espace de stationnement inclus pour tous les véhicules.</div></div>\r\n    <div class=\"amenity-item-block\"><span class=\"amenity-icon-block\">🧹</span><div class=\"amenity-name-block\">Ménage inclus</div><div class=\"amenity-desc-block\">Service de nettoyage à l\'arrivée et avant votre départ compris.</div></div>\r\n    <div class=\"amenity-item-block\"><span class=\"amenity-icon-block\">🐕</span><div class=\"amenity-name-block\">Animaux bienvenus</div><div class=\"amenity-desc-block\">Plusieurs de nos chalets acceptent vos compagnons à quatre pattes.</div></div>\r\n  </div>\r\n</section>', '.amenities-block {\r\n    background: linear-gradient(180deg, #0d2137 0%, #162b40 100%);\r\n    text-align: center;\r\n    padding: 100px 60px;\r\n  }\r\n  .amenities-block .section-tag-block {\r\n    font-size: 11px;\r\n    letter-spacing: 3px;\r\n    text-transform: uppercase;\r\n    color: #d4a843;\r\n    margin-bottom: 16px;\r\n    display: inline-block;\r\n  }\r\n  .amenities-block h2 {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 42px;\r\n    font-weight: 700;\r\n    line-height: 1.15;\r\n    margin-bottom: 20px;\r\n    color: #f0f4f8;\r\n  }\r\n  .amenities-block h2 em {\r\n    color: #d4a843;\r\n    font-style: italic;\r\n  }\r\n  .amenities-grid-block {\r\n    display: grid;\r\n    grid-template-columns: repeat(4, 1fr);\r\n    gap: 32px;\r\n    max-width: 1100px;\r\n    margin: 60px auto 0;\r\n  }\r\n  .amenity-item-block {\r\n    padding: 36px 24px;\r\n    border: 1px solid rgba(255,255,255,0.06);\r\n    background: rgba(255,255,255,0.02);\r\n    transition: all 0.3s;\r\n  }\r\n  .amenity-item-block:hover {\r\n    border-color: rgba(212,168,67,0.4);\r\n    background: rgba(212,168,67,0.05);\r\n    transform: translateY(-4px);\r\n  }\r\n  .amenity-icon-block {\r\n    font-size: 38px;\r\n    margin-bottom: 16px;\r\n    display: block;\r\n  }\r\n  .amenity-name-block {\r\n    font-size: 14px;\r\n    letter-spacing: 1.5px;\r\n    text-transform: uppercase;\r\n    font-weight: 600;\r\n    margin-bottom: 8px;\r\n    color: #f0f4f8;\r\n  }\r\n  .amenity-desc-block {\r\n    font-size: 13px;\r\n    color: #b8d4e8;\r\n    line-height: 1.6;\r\n  }\r\n  @media (max-width: 992px) {\r\n    .amenities-block { padding: 70px 24px; }\r\n    .amenities-grid-block { grid-template-columns: repeat(2, 1fr); }\r\n  }\r\n  @media (max-width: 576px) {\r\n    .amenities-grid-block { grid-template-columns: 1fr; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-05 10:01:27', '2026-06-05 11:50:34'),
(208, NULL, 'Gallerie chalets', 'gallerie-chalets', NULL, NULL, 'fa-cube', '<div class=\"lightbox-block\" id=\"lightboxBlock\" onclick=\"closeLightboxBlock(event)\">\r\n  <button class=\"lightbox-close-block\" onclick=\"closeLightboxBlock()\">✕</button>\r\n  <img id=\"lightboxImgBlock\" src=\"\" alt=\"\">\r\n</div>\r\n\r\n<section class=\"gallery-block\" id=\"galerie\">\r\n  <div class=\"gallery-header-block\">\r\n    <span class=\"section-tag-block\">✦ Galerie</span>\r\n    <h2>Un aperçu de <em>l\'expérience</em></h2>\r\n  </div>\r\n  <div class=\"gallery-grid-block\">\r\n    <div class=\"gallery-item-block g1-block\"><img src=\"https://t3.ftcdn.net/jpg/02/23/55/34/240_F_223553493_L8eOs90xg8fkfkjr2Xzpq3jaJqdclM1w.jpg\" alt=\"Chalet hiver\" onclick=\"openLightboxBlock(this.src)\"></div>\r\n    <div class=\"gallery-item-block g2-block\"><img src=\"https://t4.ftcdn.net/jpg/06/79/31/43/240_F_679314308_Bh89sE0s4WIeMmyRNXwxP8a7Rw0iayXl.jpg\" alt=\"Nuit étoilée\" onclick=\"openLightboxBlock(this.src)\"></div>\r\n    <div class=\"gallery-item-block g3-block\"><img src=\"https://t3.ftcdn.net/jpg/11/75/63/74/240_F_1175637440_GRxjqkU9sSUwGin3o4R2bNYZQBCs8lVB.jpg\" alt=\"Forêt enneigée\" onclick=\"openLightboxBlock(this.src)\"></div>\r\n    <div class=\"gallery-item-block g4-block\"><img src=\"https://t3.ftcdn.net/jpg/09/89/24/82/240_F_989248260_60QnHDqcKh0d0y0MbPbyZuqQVR0ENERN.jpg\" alt=\"Spa extérieur\" onclick=\"openLightboxBlock(this.src)\"></div>\r\n    <div class=\"gallery-item-block g5-block\"><img src=\"https://t3.ftcdn.net/jpg/04/58/22/90/240_F_458229054_NQCNTeMPMeKA56uTRgty32OkY7MxWDp4.jpg\" alt=\"Intérieur chalet\" onclick=\"openLightboxBlock(this.src)\"></div>\r\n    <div class=\"gallery-item-block g6-block\"><img src=\"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?w=700&q=80\" alt=\"Ski alpin\" onclick=\"openLightboxBlock(this.src)\"></div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n  function openLightboxBlock(src) {\r\n    document.getElementById(\'lightboxImgBlock\').src = src;\r\n    document.getElementById(\'lightboxBlock\').classList.add(\'active\');\r\n  }\r\n  function closeLightboxBlock(event) {\r\n    if (event && event.target !== event.currentTarget && event.target.className !== \'lightbox-close-block\') return;\r\n    document.getElementById(\'lightboxBlock\').classList.remove(\'active\');\r\n  }\r\n  document.addEventListener(\'keydown\', function(e) {\r\n    if (e.key === \'Escape\') closeLightboxBlock();\r\n  });\r\n</script>', '.gallery-block {\r\n    background: #1a1a2e;\r\n    padding: 100px 60px 60px;\r\n  }\r\n  .gallery-header-block {\r\n    text-align: center;\r\n    margin-bottom: 48px;\r\n  }\r\n  .gallery-header-block .section-tag-block {\r\n    font-size: 11px;\r\n    letter-spacing: 3px;\r\n    text-transform: uppercase;\r\n    color: #d4a843;\r\n    margin-bottom: 16px;\r\n    display: inline-block;\r\n  }\r\n  .gallery-header-block h2 {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 42px;\r\n    font-weight: 700;\r\n    line-height: 1.15;\r\n    margin-bottom: 20px;\r\n    color: #f0f4f8;\r\n  }\r\n  .gallery-header-block h2 em {\r\n    color: #d4a843;\r\n    font-style: italic;\r\n  }\r\n  .gallery-grid-block {\r\n    display: grid;\r\n    grid-template-columns: repeat(12, 1fr);\r\n    gap: 12px;\r\n    max-width: 1300px;\r\n    margin: 0 auto;\r\n  }\r\n  .gallery-item-block {\r\n    overflow: hidden;\r\n    cursor: pointer;\r\n    position: relative;\r\n  }\r\n  .gallery-item-block img {\r\n    width: 100%;\r\n    height: 100%;\r\n    object-fit: cover;\r\n    transition: transform 0.5s;\r\n    display: block;\r\n  }\r\n  .gallery-item-block:hover img {\r\n    transform: scale(1.05);\r\n  }\r\n  .gallery-item-block::after {\r\n    content: \'\';\r\n    position: absolute;\r\n    inset: 0;\r\n    background: rgba(13,33,55,0.3);\r\n    opacity: 0;\r\n    transition: opacity 0.3s;\r\n  }\r\n  .gallery-item-block:hover::after {\r\n    opacity: 1;\r\n  }\r\n  .g1-block { grid-column: span 5; min-height: 320px; }\r\n  .g2-block { grid-column: span 4; min-height: 320px; }\r\n  .g3-block { grid-column: span 3; min-height: 320px; }\r\n  .g4-block { grid-column: span 3; min-height: 260px; }\r\n  .g5-block { grid-column: span 5; min-height: 260px; }\r\n  .g6-block { grid-column: span 4; min-height: 260px; }\r\n  .lightbox-block {\r\n    display: none;\r\n    position: fixed;\r\n    inset: 0;\r\n    z-index: 9999;\r\n    background: rgba(0,0,0,0.95);\r\n    align-items: center;\r\n    justify-content: center;\r\n  }\r\n  .lightbox-block.active {\r\n    display: flex;\r\n  }\r\n  .lightbox-block img {\r\n    max-width: 90vw;\r\n    max-height: 90vh;\r\n    object-fit: contain;\r\n  }\r\n  .lightbox-close-block {\r\n    position: absolute;\r\n    top: 24px;\r\n    right: 32px;\r\n    font-size: 32px;\r\n    color: #ffffff;\r\n    cursor: pointer;\r\n    background: none;\r\n    border: none;\r\n  }\r\n  @media (max-width: 992px) {\r\n    .gallery-block { padding: 70px 24px 40px; }\r\n    .gallery-grid-block { grid-template-columns: 1fr 1fr; }\r\n    .g1-block, .g2-block, .g3-block, .g4-block, .g5-block, .g6-block { grid-column: span 1; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-05 10:02:08', '2026-07-25 19:49:01'),
(209, NULL, 'Experience', 'experience', NULL, NULL, 'fa-cube', '<section class=\"experiences-block\" id=\"experiences\">\r\n  <div class=\"exp-grid-block\">\r\n    <div>\r\n      <span class=\"section-tag-block\">✦ Activités & découvertes</span>\r\n      <h2>Vivez l\'hiver<br><em>pleinement</em></h2>\r\n      <div class=\"divider-block\"></div>\r\n      <div class=\"exp-list-block\">\r\n        <div class=\"exp-item-block\"><span class=\"exp-icon-block\">⛷️</span><div><div class=\"exp-name-block\">Ski alpin & planche à neige</div><div class=\"exp-desc-block\">Accès direct aux pentes de Mont-Tremblant, Mont-Sainte-Anne et Stoneham — parmi les meilleures stations du Canada.</div></div></div>\r\n        <div class=\"exp-item-block\"><span class=\"exp-icon-block\">🏂</span><div><div class=\"exp-name-block\">Motoneige</div><div class=\"exp-desc-block\">Explorez des centaines de kilomètres de sentiers balisés à travers les forêts boréales québécoises.</div></div></div>\r\n        <div class=\"exp-item-block\"><span class=\"exp-icon-block\">🎣</span><div><div class=\"exp-name-block\">Pêche sur glace</div><div class=\"exp-desc-block\">Une tradition québécoise unique — installez-vous sur un lac gelé avec votre cabane et vos lignes.</div></div></div>\r\n        <div class=\"exp-item-block\"><span class=\"exp-icon-block\">🌌</span><div><div class=\"exp-name-block\">Aurores boréales</div><div class=\"exp-desc-block\">La région de Charlevoix offre certains des plus beaux ciels nocturnes pour observer les aurores.</div></div></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"exp-img-block\"><img src=\"https://images.unsplash.com/photo-1551524559-8af4e6624178?w=800&q=80\" alt=\"Ski québec\"><div class=\"exp-img-label-block\"><p>L\'hiver québécois, une aventure sans égale</p></div></div>\r\n  </div>\r\n</section>', '.experiences-block {\r\n    background: linear-gradient(135deg, #162b40 0%, #0d2137 100%);\r\n    padding: 100px 60px;\r\n  }\r\n  .exp-grid-block {\r\n    display: grid;\r\n    grid-template-columns: 1fr 1fr;\r\n    gap: 80px;\r\n    align-items: center;\r\n    max-width: 1280px;\r\n    margin: 0 auto;\r\n  }\r\n  .experiences-block .section-tag-block {\r\n    font-size: 11px;\r\n    letter-spacing: 3px;\r\n    text-transform: uppercase;\r\n    color: #d4a843;\r\n    margin-bottom: 16px;\r\n    display: inline-block;\r\n  }\r\n  .experiences-block h2 {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 42px;\r\n    font-weight: 700;\r\n    line-height: 1.15;\r\n    margin-bottom: 20px;\r\n    color: #f0f4f8;\r\n  }\r\n  .experiences-block h2 em {\r\n    color: #d4a843;\r\n    font-style: italic;\r\n  }\r\n  .divider-block {\r\n    width: 60px;\r\n    height: 2px;\r\n    background: #c8793a;\r\n    margin: 24px 0;\r\n  }\r\n  .exp-list-block {\r\n    margin-top: 40px;\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 24px;\r\n  }\r\n  .exp-item-block {\r\n    display: flex;\r\n    gap: 20px;\r\n    align-items: flex-start;\r\n    padding: 24px;\r\n    border-left: 2px solid transparent;\r\n    transition: all 0.3s;\r\n  }\r\n  .exp-item-block:hover {\r\n    border-left-color: #c8793a;\r\n    background: rgba(255,255,255,0.02);\r\n  }\r\n  .exp-icon-block {\r\n    font-size: 28px;\r\n    flex-shrink: 0;\r\n  }\r\n  .exp-name-block {\r\n    font-weight: 600;\r\n    font-size: 16px;\r\n    margin-bottom: 6px;\r\n    color: #f0f4f8;\r\n  }\r\n  .exp-desc-block {\r\n    font-size: 14px;\r\n    color: #b8d4e8;\r\n    line-height: 1.7;\r\n  }\r\n  .exp-img-block {\r\n    position: relative;\r\n  }\r\n  .exp-img-block img {\r\n    width: 100%;\r\n    aspect-ratio: 3/4;\r\n    object-fit: cover;\r\n  }\r\n  .exp-img-label-block {\r\n    position: absolute;\r\n    bottom: 0;\r\n    left: 0;\r\n    right: 0;\r\n    background: linear-gradient(transparent, rgba(13,33,55,0.9));\r\n    padding: 40px 28px 28px;\r\n  }\r\n  .exp-img-label-block p {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 22px;\r\n    font-style: italic;\r\n    color: #ffffff;\r\n  }\r\n  @media (max-width: 992px) {\r\n    .experiences-block { padding: 70px 24px; }\r\n    .exp-grid-block { grid-template-columns: 1fr; gap: 40px; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-05 10:06:30', '2026-06-05 12:03:31'),
(210, NULL, 'Testimentiels', 'testimentiels', NULL, NULL, 'fa-cube', '<section class=\"testimonials-block\" id=\"avis\">\r\n  <div class=\"testimonials-header-block\">\r\n    <span class=\"section-tag-block\">✦ Ce qu\'ils en disent</span>\r\n    <h2>Nos clients <em>adorent</em> leurs séjours</h2>\r\n  </div>\r\n  <div class=\"testimonials-track-block\">\r\n    <div class=\"testimonial-card-block\"><div class=\"testimonial-stars-block\">★★★★★</div><p class=\"testimonial-text-block\">Un séjour absolument magique au Chalet Boréal. Le spa extérieur sous la neige était une expérience inoubliable. On reviendra certainement l\'an prochain!</p><div class=\"testimonial-author-block\"><img class=\"testimonial-avatar-block\" src=\"https://randomuser.me/api/portraits/women/44.jpg\" alt=\"\"><div><div class=\"testimonial-name-block\">Marie-Claude Tremblay</div><div class=\"testimonial-origin-block\">Montréal, QC · Janvier 2024</div></div></div></div>\r\n    <div class=\"testimonial-card-block\"><div class=\"testimonial-stars-block\">★★★★★</div><p class=\"testimonial-text-block\">Notre groupe de 8 personnes a adoré le Refuge du Lac à Charlevoix. Vue imprenable, cuisine top, et le service de l\'équipe ChaletNordique est irréprochable.</p><div class=\"testimonial-author-block\"><img class=\"testimonial-avatar-block\" src=\"https://randomuser.me/api/portraits/men/32.jpg\" alt=\"\"><div><div class=\"testimonial-name-block\">Jean-Philippe Gagnon</div><div class=\"testimonial-origin-block\">Québec, QC · Février 2024</div></div></div></div>\r\n    <div class=\"testimonial-card-block\"><div class=\"testimonial-stars-block\">★★★★★</div><p class=\"testimonial-text-block\">La Cabane Érable était exactement ce qu\'on cherchait pour notre week-end romantique. Endroit parfait, ambiance cosy, et le foyer était allumé à notre arrivée!</p><div class=\"testimonial-author-block\"><img class=\"testimonial-avatar-block\" src=\"https://randomuser.me/api/portraits/women/67.jpg\" alt=\"\"><div><div class=\"testimonial-name-block\">Sophie Beaumont</div><div class=\"testimonial-origin-block\">Ottawa, ON · Décembre 2023</div></div></div></div>\r\n  </div>\r\n</section>', '.testimonials-block {\r\n    background: #0d2137;\r\n    padding: 100px 60px;\r\n  }\r\n  .testimonials-header-block {\r\n    text-align: center;\r\n    margin-bottom: 60px;\r\n  }\r\n  .testimonials-block .section-tag-block {\r\n    font-size: 11px;\r\n    letter-spacing: 3px;\r\n    text-transform: uppercase;\r\n    color: #d4a843;\r\n    margin-bottom: 16px;\r\n    display: inline-block;\r\n  }\r\n  .testimonials-block h2 {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 42px;\r\n    font-weight: 700;\r\n    line-height: 1.15;\r\n    margin-bottom: 20px;\r\n    color: #f0f4f8;\r\n  }\r\n  .testimonials-block h2 em {\r\n    color: #d4a843;\r\n    font-style: italic;\r\n  }\r\n  .testimonials-track-block {\r\n    display: grid;\r\n    grid-template-columns: repeat(3, 1fr);\r\n    gap: 28px;\r\n    max-width: 1200px;\r\n    margin: 0 auto;\r\n  }\r\n  .testimonial-card-block {\r\n    background: rgba(255,255,255,0.03);\r\n    border: 1px solid rgba(255,255,255,0.07);\r\n    padding: 36px 32px;\r\n    position: relative;\r\n    transition: transform 0.3s;\r\n  }\r\n  .testimonial-card-block:hover {\r\n    transform: translateY(-4px);\r\n  }\r\n  .testimonial-card-block::before {\r\n    content: \'\"\';\r\n    position: absolute;\r\n    top: 20px;\r\n    right: 28px;\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 96px;\r\n    color: rgba(212,168,67,0.12);\r\n    line-height: 1;\r\n  }\r\n  .testimonial-stars-block {\r\n    color: #d4a843;\r\n    margin-bottom: 16px;\r\n  }\r\n  .testimonial-text-block {\r\n    font-size: 14px;\r\n    line-height: 1.8;\r\n    color: #b8d4e8;\r\n    margin-bottom: 24px;\r\n    font-style: italic;\r\n  }\r\n  .testimonial-author-block {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 14px;\r\n  }\r\n  .testimonial-avatar-block {\r\n    width: 44px;\r\n    height: 44px;\r\n    border-radius: 50%;\r\n    object-fit: cover;\r\n    border: 2px solid #c8793a;\r\n  }\r\n  .testimonial-name-block {\r\n    font-weight: 600;\r\n    font-size: 14px;\r\n    color: #ffffff;\r\n  }\r\n  .testimonial-origin-block {\r\n    font-size: 12px;\r\n    color: #b8d4e8;\r\n  }\r\n  @media (max-width: 992px) {\r\n    .testimonials-block { padding: 70px 24px; }\r\n    .testimonials-track-block { grid-template-columns: 1fr; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-05 10:07:38', '2026-06-05 12:04:29'),
(211, NULL, 'Région', 'region', NULL, NULL, 'fa-cube', '<section class=\"region-block\" id=\"region\">\r\n  <div>\r\n    <span class=\"section-tag-block\">✦ La région</span>\r\n    <h2>Au cœur des <em>plus belles</em><br>régions du Québec</h2>\r\n    <div class=\"divider-block\"></div>\r\n    <p class=\"section-body-block\">Nos chalets sont stratégiquement situés pour vous donner accès aux meilleures expériences hivernales de la province.</p>\r\n    <div class=\"region-points-block\">\r\n      <div class=\"region-point-block\"><div class=\"region-point-dot-block\"></div><span>Laurentides — stations de ski de classe mondiale</span></div>\r\n      <div class=\"region-point-block\"><div class=\"region-point-dot-block\"></div><span>Charlevoix — paysages et gastronomie exceptionnels</span></div>\r\n      <div class=\"region-point-block\"><div class=\"region-point-dot-block\"></div><span>Estrie — tranquillité et forêts d\'érables</span></div>\r\n      <div class=\"region-point-block\"><div class=\"region-point-dot-block\"></div><span>Lac-Saint-Jean — vastes espaces et pêche sur glace</span></div>\r\n    </div>\r\n  </div>\r\n  <div><img class=\"region-map-img-block\" src=\"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&q=80\" alt=\"Paysage québécois\"></div>\r\n</section>', '.region-block {\r\n    background: linear-gradient(135deg, #1a1a2e 0%, #162b40 100%);\r\n    display: grid;\r\n    grid-template-columns: 1fr 1fr;\r\n    gap: 80px;\r\n    align-items: center;\r\n    padding: 100px 60px;\r\n  }\r\n  .region-block .section-tag-block {\r\n    font-size: 11px;\r\n    letter-spacing: 3px;\r\n    text-transform: uppercase;\r\n    color: #d4a843;\r\n    margin-bottom: 16px;\r\n    display: inline-block;\r\n  }\r\n  .region-block h2 {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 42px;\r\n    font-weight: 700;\r\n    line-height: 1.15;\r\n    margin-bottom: 20px;\r\n    color: #f0f4f8;\r\n  }\r\n  .region-block h2 em {\r\n    color: #d4a843;\r\n    font-style: italic;\r\n  }\r\n  .divider-block {\r\n    width: 60px;\r\n    height: 2px;\r\n    background: #c8793a;\r\n    margin: 24px 0;\r\n  }\r\n  .section-body-block {\r\n    font-size: 16px;\r\n    font-weight: 300;\r\n    line-height: 1.8;\r\n    color: #b8d4e8;\r\n    max-width: 540px;\r\n  }\r\n  .region-points-block {\r\n    margin-top: 36px;\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 16px;\r\n  }\r\n  .region-point-block {\r\n    display: flex;\r\n    gap: 16px;\r\n    align-items: center;\r\n    font-size: 14px;\r\n    color: #b8d4e8;\r\n  }\r\n  .region-point-dot-block {\r\n    width: 8px;\r\n    height: 8px;\r\n    border-radius: 50%;\r\n    background: #c8793a;\r\n    flex-shrink: 0;\r\n  }\r\n  .region-map-img-block {\r\n    width: 100%;\r\n    border-radius: 2px;\r\n    aspect-ratio: 1;\r\n    object-fit: cover;\r\n    filter: saturate(0.6) brightness(0.9);\r\n  }\r\n  @media (max-width: 992px) {\r\n    .region-block { grid-template-columns: 1fr; gap: 40px; padding: 70px 24px; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-05 10:08:29', '2026-06-05 12:05:05'),
(212, NULL, 'Footer chalet', 'footer-chalet', NULL, NULL, 'fa-cube', '<footer class=\"footer-block\">\r\n  <div class=\"footer-container-block\">\r\n    <div class=\"footer-top-block\">\r\n      <div class=\"footer-brand-block\">\r\n        <a href=\"#\" class=\"nav-logo-block\">Chalet<span>Nordique</span></a>\r\n        <p>Votre référence pour la location de chalets de luxe au Québec depuis 2012. Nous créons des souvenirs inoubliables au cœur de la nature hivernale québécoise.</p>\r\n        <div class=\"footer-socials-block\">\r\n          <a href=\"#\" class=\"social-btn-block\">f</a>\r\n          <a href=\"#\" class=\"social-btn-block\">in</a>\r\n          <a href=\"#\" class=\"social-btn-block\">📸</a>\r\n          <a href=\"#\" class=\"social-btn-block\">▶</a>\r\n        </div>\r\n      </div>\r\n      <div class=\"footer-col-block\"><h4>Chalets</h4><ul><li><a href=\"#\">Laurentides</a></li><li><a href=\"#\">Charlevoix</a></li><li><a href=\"#\">Estrie</a></li><li><a href=\"#\">Lac-Saint-Jean</a></li><li><a href=\"#\">Toutes les régions</a></li></ul></div>\r\n      <div class=\"footer-col-block\"><h4>Services</h4><ul><li><a href=\"#\">Réservation</a></li><li><a href=\"#\">Location de matériel</a></li><li><a href=\"#\">Chef à domicile</a></li><li><a href=\"#\">Transport VIP</a></li><li><a href=\"#\">Concierge 24/7</a></li></ul></div>\r\n      <div class=\"footer-col-block\"><h4>Informations</h4><ul><li><a href=\"#\">À propos</a></li><li><a href=\"#\">FAQ</a></li><li><a href=\"#\">Conditions</a></li><li><a href=\"#\">Confidentialité</a></li><li><a href=\"#\">Contact</a></li></ul></div>\r\n    </div>\r\n    <div class=\"footer-bottom-block\">\r\n      <span>© 2024 ChaletNordique — Tous droits réservés</span>\r\n      <span>Fait avec ❤️ au Québec 🍁</span>\r\n      <span>\r\n        <img src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Visa_Inc._logo.svg/100px-Visa_Inc._logo.svg.png\" alt=\"Visa\" style=\"height:16px;opacity:0.4;filter:invert(1);margin-right:8px\">\r\n        <img src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Mastercard-logo.svg/100px-Mastercard-logo.svg.png\" alt=\"Mastercard\" style=\"height:16px;opacity:0.4;filter:invert(1)\">\r\n      </span>\r\n    </div>\r\n  </div>\r\n</footer>', '.footer-block {\r\n    background: rgba(0,0,0,0.4);\r\n    border-top: 1px solid rgba(255,255,255,0.06);\r\n    padding: 60px 60px 30px;\r\n  }\r\n  .footer-container-block {\r\n    max-width: 1280px;\r\n    margin: 0 auto;\r\n  }\r\n  .footer-top-block {\r\n    display: grid;\r\n    grid-template-columns: 2fr 1fr 1fr 1fr;\r\n    gap: 60px;\r\n    margin-bottom: 48px;\r\n  }\r\n  .footer-brand-block .nav-logo-block {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 26px;\r\n    font-weight: 700;\r\n    color: #ffffff;\r\n    letter-spacing: 1px;\r\n    text-decoration: none;\r\n    display: inline-block;\r\n    margin-bottom: 16px;\r\n  }\r\n  .footer-brand-block .nav-logo-block span { color: #d4a843; }\r\n  .footer-brand-block p {\r\n    font-size: 14px;\r\n    color: #b8d4e8;\r\n    line-height: 1.7;\r\n  }\r\n  .footer-socials-block {\r\n    display: flex;\r\n    gap: 12px;\r\n    margin-top: 20px;\r\n  }\r\n  .social-btn-block {\r\n    width: 38px;\r\n    height: 38px;\r\n    border: 1px solid rgba(255,255,255,0.15);\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-size: 16px;\r\n    text-decoration: none;\r\n    color: #b8d4e8;\r\n    transition: all 0.3s;\r\n    border-radius: 50%;\r\n  }\r\n  .social-btn-block:hover {\r\n    background: #c8793a;\r\n    border-color: #c8793a;\r\n    color: #ffffff;\r\n  }\r\n  .footer-col-block h4 {\r\n    font-size: 11px;\r\n    letter-spacing: 2.5px;\r\n    text-transform: uppercase;\r\n    color: #d4a843;\r\n    margin-bottom: 20px;\r\n  }\r\n  .footer-col-block ul {\r\n    list-style: none;\r\n    margin: 0;\r\n    padding: 0;\r\n  }\r\n  .footer-col-block ul li {\r\n    margin-bottom: 10px;\r\n  }\r\n  .footer-col-block ul li a {\r\n    font-size: 14px;\r\n    color: #b8d4e8;\r\n    text-decoration: none;\r\n    transition: color 0.3s;\r\n  }\r\n  .footer-col-block ul li a:hover {\r\n    color: #ffffff;\r\n  }\r\n  .footer-bottom-block {\r\n    border-top: 1px solid rgba(255,255,255,0.06);\r\n    padding-top: 24px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    font-size: 12px;\r\n    color: rgba(255,255,255,0.3);\r\n  }\r\n  @media (max-width: 992px) {\r\n    .footer-block { padding: 40px 24px 30px; }\r\n    .footer-top-block { grid-template-columns: 1fr 1fr; gap: 40px; }\r\n    .footer-bottom-block { flex-direction: column; gap: 12px; text-align: center; }\r\n  }\r\n  @media (max-width: 576px) {\r\n    .footer-top-block { grid-template-columns: 1fr; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-05 10:09:13', '2026-06-05 12:06:03'),
(213, NULL, 'FONTS & LIBRAIRIES GLOBALES', 'fonts-librairies-globales', NULL, NULL, 'fa-cube', '<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,600;0,700;1,300;1,400;1,600&family=Outfit:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\r\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.css\">\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css\">', NULL, NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 09:00:35', '2026-06-06 09:00:35'),
(214, NULL, 'DESIGN TOKENS & RESET GLOBAL', 'design-tokens-reset-global', NULL, NULL, 'fa-cube', '<style>\r\n  :root {\r\n    --gold: #C9A84C;\r\n    --gold-light: #E8C97A;\r\n    --gold-pale: rgba(201,168,76,0.12);\r\n    --dark: #080808;\r\n    --dark-2: #0F0F0F;\r\n    --dark-3: #161616;\r\n    --dark-4: #1E1E1E;\r\n    --dark-5: #252525;\r\n    --light: #F8F4EE;\r\n    --light-2: #EDE5D5;\r\n    --text-dark: #0D0D0D;\r\n    --text-light: #F5F0E8;\r\n    --text-muted: #7A7470;\r\n    --wood: #7A4F2B;\r\n    --wood-light: #9E6B40;\r\n    --green: #2C4234;\r\n    --radius: 2px;\r\n    --ease: cubic-bezier(0.25,0.46,0.45,0.94);\r\n    --transition: 0.4s var(--ease);\r\n    --font-serif: \'Cormorant Garamond\', Georgia, serif;\r\n    --font-sans: \'Outfit\', sans-serif;\r\n  }\r\n  [data-theme=\"dark\"] {\r\n    --bg: var(--dark);\r\n    --bg-2: var(--dark-2);\r\n    --bg-3: var(--dark-3);\r\n    --text: var(--text-light);\r\n    --card-bg: var(--dark-4);\r\n    --border: rgba(255,255,255,0.06);\r\n    --nav-bg: rgba(8,8,8,0.94);\r\n  }\r\n  [data-theme=\"light\"] {\r\n    --bg: var(--light);\r\n    --bg-2: var(--light-2);\r\n    --bg-3: #fff;\r\n    --text: var(--text-dark);\r\n    --card-bg: #fff;\r\n    --border: rgba(0,0,0,0.07);\r\n    --nav-bg: rgba(248,244,238,0.96);\r\n  }\r\n  *,*::before,*::after{margin:0;padding:0;box-sizing:border-box;}\r\n  html{scroll-behavior:smooth;font-size:16px;}\r\n  body{font-family:\'Outfit\',sans-serif;background:var(--bg);color:var(--text);transition:background .5s,color .5s;overflow-x:hidden;}\r\n  h1,h2,h3,h4{font-family:\'Cormorant Garamond\',Georgia,serif;}\r\n  a{text-decoration:none;color:inherit;}\r\n  img{max-width:100%;display:block;}\r\n  ::-webkit-scrollbar{width:5px;}\r\n  ::-webkit-scrollbar-track{background:#0F0F0F;}\r\n  ::-webkit-scrollbar-thumb{background:#C9A84C;border-radius:3px;}\r\n  .reveal-pbr {\r\n    opacity: 0;\r\n    transform: translateY(36px);\r\n    transition: opacity .75s ease, transform .75s ease;\r\n  }\r\n  .reveal-pbr.visible {\r\n    opacity: 1;\r\n    transform: translateY(0);\r\n  }\r\n  .delay-1 { transition-delay: .1s; }\r\n  .delay-2 { transition-delay: .2s; }\r\n  .delay-3 { transition-delay: .3s; }\r\n  .delay-4 { transition-delay: .4s; }\r\n  .container-pbr {\r\n    max-width: 1340px;\r\n    margin: 0 auto;\r\n  }\r\n  .sec-eyebrow-pbr {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 12px;\r\n    font-size: .65rem;\r\n    letter-spacing: 4px;\r\n    text-transform: uppercase;\r\n    color: #C9A84C;\r\n    margin-bottom: 1rem;\r\n  }\r\n  .sec-eyebrow-pbr::before {\r\n    content: \'\';\r\n    width: 28px;\r\n    height: 1px;\r\n    background: #C9A84C;\r\n  }\r\n  .sec-title-pbr {\r\n    font-size: clamp(2rem, 4vw, 3.4rem);\r\n    line-height: 1.08;\r\n    margin-bottom: 1.2rem;\r\n    color: var(--text, #F5F0E8);\r\n  }\r\n  .btn-primary-pbr {\r\n    background: #C9A84C;\r\n    color: #fff;\r\n    padding: .85rem 2.2rem;\r\n    font-size: .78rem;\r\n    font-weight: 600;\r\n    letter-spacing: 1.2px;\r\n    text-transform: uppercase;\r\n    border: 1px solid #C9A84C;\r\n    display: inline-block;\r\n    transition: var(--transition, 0.4s);\r\n    cursor: pointer;\r\n    text-decoration: none;\r\n  }\r\n  .btn-primary-pbr:hover {\r\n    background: transparent;\r\n    color: #C9A84C;\r\n  }\r\n  .btn-outline-pbr {\r\n    background: transparent;\r\n    color: #C9A84C;\r\n    padding: .85rem 2.2rem;\r\n    font-size: .78rem;\r\n    font-weight: 500;\r\n    letter-spacing: 1.2px;\r\n    text-transform: uppercase;\r\n    border: 1px solid #C9A84C;\r\n    display: inline-block;\r\n    transition: var(--transition, 0.4s);\r\n    cursor: pointer;\r\n    text-decoration: none;\r\n  }\r\n  .btn-outline-pbr:hover {\r\n    background: #C9A84C;\r\n    color: #fff;\r\n  }\r\n</style>', NULL, NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-06 09:01:30', '2026-07-25 19:48:50');
INSERT INTO `blocks` (`id`, `categorie_id`, `name`, `slug`, `description`, `thumbnail`, `icon`, `html_content`, `css_content`, `js_content`, `section_id`, `category`, `website_type`, `tags`, `is_responsive`, `is_free`, `width`, `height`, `usage_count`, `views_count`, `rating`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(215, NULL, 'NAVIGATION', 'navigation-2', NULL, NULL, 'fa-cube', '<nav class=\"nav-block-pbr\" id=\"navbarPBR\">\r\n  <div class=\"nav-inner-pbr\">\r\n    <div class=\"logo-pbr\"><div class=\"logo-mark-pbr\"><i class=\"fa fa-tree\"></i></div><div class=\"logo-text-pbr\">Prestige Bois Rond <span>Maisons & Chalets • Québec</span></div></div>\r\n    <ul class=\"nav-links-pbr\">\r\n      <li><a href=\"#products\">Maisons & Chalets ▾</a><ul class=\"dropdown-pbr\"><li><a href=\"#products\">Tous nos modèles</a></li><li><a href=\"#products\">Série Prestige</a></li><li><a href=\"#products\">Série Scandinave</a></li><li><a href=\"#products\">Série Contemporaine</a></li><li><a href=\"#products\">Maison en bois rond</a></li><li><a href=\"#products\">Chalet en bois rond</a></li></ul></li>\r\n      <li><a href=\"#services\">Services ▾</a><ul class=\"dropdown-pbr\"><li><a href=\"#services\">Plans</a></li><li><a href=\"#services\">Soutien technique</a></li><li><a href=\"#services\">Auto-construction</a></li><li><a href=\"#services\">Surveillance de chantier</a></li><li><a href=\"#services\">Ajouts et rénovations</a></li><li><a href=\"#services\">Transport</a></li></ul></li>\r\n      <li><a href=\"#gallery\">Réalisations</a></li><li><a href=\"#about\">À propos</a></li><li><a href=\"#blog\">Blogue</a></li><li><a href=\"#contact\">Contact</a></li>\r\n    </ul>\r\n    <div class=\"nav-actions-pbr\"><button class=\"theme-btn-pbr\" id=\"themeTogglePBR\"><i class=\"fa fa-sun\"></i></button><a href=\"#contact\" class=\"btn-nav-cta-pbr\">Soumission gratuite</a><div class=\"hamburger-pbr\" id=\"hamburgerPBR\"><span></span><span></span><span></span></div></div>\r\n  </div>\r\n</nav>\r\n<div class=\"mobile-nav-pbr\" id=\"mobileNavPBR\"><ul class=\"mobile-nav-links-pbr\"><li><a href=\"#products\" onclick=\"closeMobileNavPBR()\">Maisons & Chalets</a></li><li><a href=\"#services\" onclick=\"closeMobileNavPBR()\">Services</a></li><li><a href=\"#gallery\" onclick=\"closeMobileNavPBR()\">Réalisations</a></li><li><a href=\"#about\" onclick=\"closeMobileNavPBR()\">À propos</a></li><li><a href=\"#blog\" onclick=\"closeMobileNavPBR()\">Blogue</a></li><li><a href=\"#contact\" onclick=\"closeMobileNavPBR()\">Contact</a></li><li><a href=\"#contact\" onclick=\"closeMobileNavPBR()\" style=\"color:#C9A84C;font-weight:600\">Soumission gratuite</a></li></ul></div>\r\n<script>\r\n  (function(){\r\n    var themeToggle=document.getElementById(\'themeTogglePBR\'),isDark=true;\r\n    if(themeToggle){themeToggle.addEventListener(\'click\',function(){isDark=!isDark;document.documentElement.setAttribute(\'data-theme\',isDark?\'dark\':\'light\');var icon=themeToggle.querySelector(\'i\');if(icon)icon.className=isDark?\'fa fa-sun\':\'fa fa-moon\';});}\r\n    window.addEventListener(\'scroll\',function(){var nav=document.getElementById(\'navbarPBR\');if(nav)nav.style.boxShadow=window.scrollY>50?\'0 5px 30px rgba(0,0,0,.35)\':\'none\';});\r\n    var hamburger=document.getElementById(\'hamburgerPBR\'),mobileNav=document.getElementById(\'mobileNavPBR\'),mobileOpen=false;\r\n    if(hamburger&&mobileNav){hamburger.addEventListener(\'click\',function(){mobileOpen=!mobileOpen;mobileNav.classList.toggle(\'open\',mobileOpen);document.body.style.overflow=mobileOpen?\'hidden\':\'\';});}\r\n    window.closeMobileNavPBR=function(){if(mobileNav)mobileNav.classList.remove(\'open\');document.body.style.overflow=\'\';mobileOpen=false;};\r\n  })();\r\n</script>', '.nav-block-pbr {\r\n    position: fixed;\r\n    top: 0;\r\n    left: 0;\r\n    right: 0;\r\n    z-index: 1000;\r\n    background: var(--nav-bg, rgba(8,8,8,0.94));\r\n    backdrop-filter: blur(24px);\r\n    border-bottom: 1px solid var(--border, rgba(255,255,255,0.06));\r\n    transition: var(--transition, 0.4s);\r\n  }\r\n  .nav-inner-pbr {\r\n    max-width: 1440px;\r\n    margin: 0 auto;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    padding: 0 2.5rem;\r\n    height: 78px;\r\n  }\r\n  .logo-pbr{display:flex;align-items:center;gap:14px;}\r\n  .logo-mark-pbr{width:42px;height:42px;background:#C9A84C;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:18px;color:#fff;flex-shrink:0;}\r\n  .logo-text-pbr{font-family:\'Cormorant Garamond\',Georgia,serif;font-size:1.15rem;font-weight:600;line-height:1.15;color:var(--text,#F5F0E8);}\r\n  .logo-text-pbr span{display:block;font-size:0.6rem;font-family:\'Outfit\',sans-serif;font-weight:500;letter-spacing:3.5px;text-transform:uppercase;color:#C9A84C;margin-top:1px;}\r\n  .nav-links-pbr{display:flex;list-style:none;align-items:center;}\r\n  .nav-links-pbr>li{position:relative;}\r\n  .nav-links-pbr>li>a{padding:.5rem 1rem;display:block;font-size:.78rem;font-weight:500;letter-spacing:.8px;text-transform:uppercase;opacity:.75;transition:opacity .2s,color .2s;color:var(--text,#F5F0E8);}\r\n  .nav-links-pbr>li>a:hover,.nav-links-pbr>li>a.active{opacity:1;color:#C9A84C;}\r\n  .dropdown-pbr{position:absolute;top:calc(100% + 8px);left:0;min-width:230px;background:var(--card-bg,#1E1E1E);border:1px solid var(--border,rgba(255,255,255,0.06));border-top:2px solid #C9A84C;box-shadow:0 24px 60px rgba(0,0,0,.4);padding:.5rem 0;opacity:0;visibility:hidden;transform:translateY(12px);transition:var(--transition,0.4s);list-style:none;z-index:100;}\r\n  .nav-links-pbr>li:hover .dropdown-pbr{opacity:1;visibility:visible;transform:translateY(0);}\r\n  .dropdown-pbr li a{display:block;padding:.55rem 1.3rem;font-size:.8rem;opacity:.75;border-left:2px solid transparent;transition:.2s;color:var(--text,#F5F0E8);}\r\n  .dropdown-pbr li a:hover{opacity:1;border-left-color:#C9A84C;color:#C9A84C;padding-left:1.6rem;}\r\n  .nav-actions-pbr{display:flex;align-items:center;gap:1rem;}\r\n  .btn-nav-cta-pbr{background:#C9A84C;color:#fff;padding:.5rem 1.4rem;font-size:.75rem;font-weight:600;letter-spacing:1.2px;text-transform:uppercase;border:1px solid #C9A84C;transition:var(--transition,0.4s);text-decoration:none;display:inline-block;}\r\n  .btn-nav-cta-pbr:hover{background:transparent;color:#C9A84C;}\r\n  .theme-btn-pbr{width:34px;height:34px;border-radius:50%;border:1px solid var(--border,rgba(255,255,255,0.06));background:transparent;color:var(--text,#F5F0E8);cursor:pointer;font-size:13px;display:flex;align-items:center;justify-content:center;transition:var(--transition,0.4s);}\r\n  .theme-btn-pbr:hover{border-color:#C9A84C;color:#C9A84C;}\r\n  .hamburger-pbr{display:none;flex-direction:column;gap:5px;cursor:pointer;padding:5px;}\r\n  .hamburger-pbr span{width:22px;height:2px;background:var(--text,#F5F0E8);transition:.3s;display:block;}\r\n  .mobile-nav-pbr{display:none;position:fixed;inset:0;z-index:999;background:#0F0F0F;padding:6rem 2rem 2rem;overflow-y:auto;}\r\n  .mobile-nav-pbr.open{display:block;}\r\n  .mobile-nav-links-pbr{list-style:none;}\r\n  .mobile-nav-links-pbr>li{border-bottom:1px solid rgba(255,255,255,0.06);}\r\n  .mobile-nav-links-pbr>li>a{display:block;padding:1rem 0;font-size:.95rem;font-weight:500;color:#F5F0E8;text-decoration:none;}\r\n  @media(max-width:768px){.nav-links-pbr,.btn-nav-cta-pbr{display:none;}.hamburger-pbr{display:flex;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 09:03:02', '2026-06-06 09:03:02'),
(216, NULL, 'HERO avec SWIPER et SELECTEUR', 'hero-avec-swiper-et-selecteur', NULL, NULL, 'fa-cube', '<div class=\"hero-block-pbr\"><div class=\"swiper hero-swiper-pbr\" id=\"heroSwiperPBR\"><div class=\"swiper-wrapper\">\r\n  <div class=\"swiper-slide hero-slide-pbr\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/DSC06735-HDR.jpg\" alt=\"\"><div class=\"hero-content-pbr\"><div class=\"hero-eyebrow-pbr\">Artisans du bois rond depuis 1998</div><h1>Maisons & Chalets<br>en <em>Bois Rond</em></h1><p>Chaque réalisation est l\'expression d\'une passion pour le bois massif et d\'un engagement constant envers l\'excellence artisanale.</p><div class=\"hero-btns-pbr\"><a href=\"#products\" class=\"btn-primary-pbr\">Découvrir nos modèles</a><a href=\"#gallery\" class=\"btn-ghost-pbr\">Voir nos réalisations</a></div></div></div>\r\n  <div class=\"swiper-slide hero-slide-pbr\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/DJI_0237.jpg\" alt=\"\"><div class=\"hero-content-pbr\"><div class=\"hero-eyebrow-pbr\">Série Contemporaine Hybride</div><h1>Design Moderne,<br>Âme <em>Naturelle</em></h1><p>La série Contemporaine allie lignes épurées et chaleur intemporelle du bois massif. L\'élégance à l\'état pur.</p><div class=\"hero-btns-pbr\"><a href=\"#products\" class=\"btn-primary-pbr\">Explorer la série</a><a href=\"#video-section\" class=\"btn-ghost-pbr\"><i class=\"fa fa-play\"></i>&nbsp; Voir la vidéo</a></div></div></div>\r\n  <div class=\"swiper-slide hero-slide-pbr\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/SaveInsta.App_327015499_693241832530188_5777615420000727358_n.jpg\" alt=\"\"><div class=\"hero-content-pbr\"><div class=\"hero-eyebrow-pbr\">Série Scandinave</div><h1>Charme Rustique,<br><em>Design Épuré</em></h1><p>Nos chalets scandinaves fusionnent l\'authenticité du bois rond avec l\'esthétique nordique pure. Fabriqués avec passion au Québec.</p><div class=\"hero-btns-pbr\"><a href=\"#products\" class=\"btn-primary-pbr\">Série Scandinave</a><a href=\"#gallery\" class=\"btn-ghost-pbr\">Galerie photos</a></div></div></div>\r\n</div><div class=\"swiper-pagination swiper-pagination-pbr\"></div><div class=\"hero-stats-pbr\"><div class=\"hero-stat-pbr\"><span class=\"num\">100+</span><span class=\"lbl\">Réalisations</span></div><div class=\"hero-stat-pbr\"><span class=\"num\">25+</span><span class=\"lbl\">Années</span></div><div class=\"hero-stat-pbr\"><span class=\"num\">100%</span><span class=\"lbl\">Satisfaction</span></div></div><div class=\"hero-scroll-pbr\"><i class=\"fa fa-chevron-down\"></i><span>Défiler</span></div>\r\n<div class=\"hero-selector-pbr\" id=\"heroSelectorPBR\">\r\n  <div class=\"hsel-card-pbr active\" data-slide=\"0\" onclick=\"heroSelectCardPBR(this,0)\"><div class=\"hsel-thumb-pbr\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/DSC06735-HDR.jpg\"><span class=\"hsel-num-pbr\">01</span><div class=\"hsel-progress-pbr\"></div></div><div class=\"hsel-body-pbr\"><div class=\"hsel-icon-pbr\"><i class=\"fa fa-crown\"></i></div><div class=\"hsel-info-pbr\"><span class=\"hsel-tag-pbr\">Prestige</span><h4>Série Prestige</h4><p>Luxe & artisanat exceptionnel</p></div><i class=\"fa fa-arrow-right hsel-arrow-pbr\"></i></div></div>\r\n  <div class=\"hsel-card-pbr\" data-slide=\"1\" onclick=\"heroSelectCardPBR(this,1)\"><div class=\"hsel-thumb-pbr\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/DJI_0237.jpg\"><span class=\"hsel-num-pbr\">02</span><div class=\"hsel-progress-pbr\"></div></div><div class=\"hsel-body-pbr\"><div class=\"hsel-icon-pbr\"><i class=\"fa fa-layer-group\"></i></div><div class=\"hsel-info-pbr\"><span class=\"hsel-tag-pbr\">Contemporain</span><h4>Série Hybride</h4><p>Modernité & charme naturel</p></div><i class=\"fa fa-arrow-right hsel-arrow-pbr\"></i></div></div>\r\n  <div class=\"hsel-card-pbr\" data-slide=\"2\" onclick=\"heroSelectCardPBR(this,2)\"><div class=\"hsel-thumb-pbr\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/SaveInsta.App_327015499_693241832530188_5777615420000727358_n.jpg\"><span class=\"hsel-num-pbr\">03</span><div class=\"hsel-progress-pbr\"></div></div><div class=\"hsel-body-pbr\"><div class=\"hsel-icon-pbr\"><i class=\"fa fa-snowflake\"></i></div><div class=\"hsel-info-pbr\"><span class=\"hsel-tag-pbr\">Scandinave</span><h4>Série Scandinave</h4><p>Design nordique & bois massif</p></div><i class=\"fa fa-arrow-right hsel-arrow-pbr\"></i></div></div>\r\n</div></div></div>\r\n<script src=\"https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js\"></script>\r\n<script>\r\n  (function(){\r\n    window.heroSwiperPBR=new Swiper(\'#heroSwiperPBR\',{loop:true,speed:1200,autoplay:{delay:6000,disableOnInteraction:false},effect:\'fade\',fadeEffect:{crossFade:true},pagination:{el:\'.hero-swiper-pbr .swiper-pagination-pbr\',clickable:true},on:{slideChange:function(){syncHeroSelectorPBR(this.realIndex);}}});\r\n    window.heroSelectCardPBR=function(card,slideIdx){document.querySelectorAll(\'.hsel-card-pbr\').forEach(function(c){c.classList.remove(\'active\');});card.classList.add(\'active\');if(window.heroSwiperPBR)window.heroSwiperPBR.slideToLoop(slideIdx,800);};\r\n    function syncHeroSelectorPBR(realIdx){document.querySelectorAll(\'.hsel-card-pbr\').forEach(function(c){var si=parseInt(c.dataset.slide);if(si===realIdx)c.classList.add(\'active\');else c.classList.remove(\'active\');});}\r\n  })();\r\n</script>', '.hero-block-pbr{height:100vh;position:relative;overflow:hidden;}\r\n  .hero-swiper-pbr{width:100%;height:100%;}\r\n  .hero-slide-pbr{position:relative;display:flex;align-items:center;}\r\n  .hero-slide-pbr::before{content:\'\';position:absolute;inset:0;background:linear-gradient(120deg,rgba(0,0,0,.72)0%,rgba(0,0,0,.18)55%,rgba(0,0,0,.38)100%);z-index:1;}\r\n  .hero-slide-pbr img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transform:scale(1.07);animation:heroZoomPBR 9s ease-out forwards;}\r\n  @keyframes heroZoomPBR{to{transform:scale(1);}}\r\n  .hero-content-pbr{position:relative;z-index:2;max-width:680px;padding:0 2.5rem;margin-left:9%;}\r\n  .hero-eyebrow-pbr{display:inline-flex;align-items:center;gap:12px;font-size:.65rem;letter-spacing:4px;text-transform:uppercase;color:#C9A84C;margin-bottom:1.8rem;opacity:0;animation:fadeUpPBR .8s .3s forwards;}\r\n  .hero-eyebrow-pbr::before{content:\'\';width:28px;height:1px;background:#C9A84C;}\r\n  .hero-content-pbr h1{font-size:clamp(2.8rem,5.5vw,5.2rem);color:#fff;line-height:1.04;margin-bottom:1.6rem;opacity:0;animation:fadeUpPBR .8s .5s forwards;font-family:\'Cormorant Garamond\',Georgia,serif;}\r\n  .hero-content-pbr h1 em{color:#C9A84C;font-style:italic;}\r\n  .hero-content-pbr p{font-size:1.05rem;color:rgba(255,255,255,.78);line-height:1.75;margin-bottom:2.8rem;opacity:0;animation:fadeUpPBR .8s .7s forwards;}\r\n  .hero-btns-pbr{display:flex;gap:1rem;flex-wrap:wrap;opacity:0;animation:fadeUpPBR .8s .9s forwards;}\r\n  @keyframes fadeUpPBR{from{opacity:0;transform:translateY(28px)}to{opacity:1;transform:translateY(0)}}\r\n  .btn-ghost-pbr{background:transparent;color:#fff;padding:.85rem 2.2rem;font-size:.78rem;font-weight:500;letter-spacing:1px;text-transform:uppercase;border:1px solid rgba(255,255,255,.35);display:inline-block;transition:var(--transition,0.4s);cursor:pointer;text-decoration:none;}\r\n  .btn-ghost-pbr:hover{border-color:#C9A84C;color:#C9A84C;}\r\n  .hero-stats-pbr{position:absolute;bottom:2.5rem;right:7%;z-index:3;display:flex;gap:3rem;}\r\n  .hero-stat-pbr .num{font-family:\'Cormorant Garamond\',Georgia,serif;font-size:2.4rem;color:#C9A84C;line-height:1;display:block;}\r\n  .hero-stat-pbr .lbl{font-size:.6rem;letter-spacing:2px;text-transform:uppercase;color:rgba(255,255,255,.55);margin-top:4px;display:block;}\r\n  .hero-scroll-pbr{position:absolute;bottom:2rem;left:50%;transform:translateX(-50%);z-index:3;display:flex;flex-direction:column;align-items:center;gap:6px;color:rgba(255,255,255,.45);font-size:.6rem;letter-spacing:2px;text-transform:uppercase;animation:bouncePBR 2s infinite;}\r\n  .hero-scroll-pbr i{font-size:16px;color:#C9A84C;}\r\n  @keyframes bouncePBR{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(8px)}}\r\n  .swiper-pagination-pbr{bottom:1.5rem!important;left:5%!important;width:auto!important;text-align:left!important;z-index:4!important;}\r\n  .swiper-pagination-pbr .swiper-pagination-bullet{background:rgba(255,255,255,.35)!important;opacity:1!important;width:6px!important;height:6px!important;}\r\n  .swiper-pagination-pbr .swiper-pagination-bullet-active{background:#C9A84C!important;width:22px!important;border-radius:3px!important;}\r\n  .hero-selector-pbr{position:absolute;right:0;top:50%;transform:translateY(-50%);z-index:10;display:flex;flex-direction:column;gap:0;width:260px;}\r\n  .hsel-card-pbr{position:relative;cursor:pointer;overflow:hidden;transition:var(--transition,0.4s);border-left:3px solid transparent;background:rgba(8,8,8,.72);backdrop-filter:blur(20px);display:flex;flex-direction:column;border-bottom:1px solid rgba(255,255,255,.05);}\r\n  .hsel-card-pbr:last-child{border-bottom:none;}\r\n  .hsel-card-pbr.active{border-left-color:#C9A84C;background:rgba(8,8,8,.88);}\r\n  .hsel-card-pbr:hover{background:rgba(20,16,10,.9);}\r\n  .hsel-thumb-pbr{width:100%;height:90px;overflow:hidden;position:relative;flex-shrink:0;}\r\n  .hsel-thumb-pbr img{width:100%;height:100%;object-fit:cover;transition:transform .7s var(--ease);filter:brightness(.55) saturate(.8);}\r\n  .hsel-card-pbr.active .hsel-thumb-pbr img{filter:brightness(.75) saturate(1);}\r\n  .hsel-card-pbr:hover .hsel-thumb-pbr img{transform:scale(1.08);filter:brightness(.7) saturate(1);}\r\n  .hsel-thumb-pbr::after{content:\'\';position:absolute;inset:0;background:linear-gradient(180deg,transparent 40%,rgba(201,168,76,.18)100%);opacity:0;transition:.4s;}\r\n  .hsel-card-pbr.active .hsel-thumb-pbr::after,.hsel-card-pbr:hover .hsel-thumb-pbr::after{opacity:1;}\r\n  .hsel-num-pbr{position:absolute;top:8px;left:10px;font-size:.58rem;letter-spacing:2px;text-transform:uppercase;color:#C9A84C;font-family:\'Outfit\',sans-serif;font-weight:700;background:rgba(0,0,0,.5);padding:2px 7px;border-radius:1px;z-index:1;}\r\n  .hsel-progress-pbr{position:absolute;bottom:0;left:0;height:2px;background:#C9A84C;width:0%;transition:none;z-index:2;}\r\n  .hsel-card-pbr.active .hsel-progress-pbr{animation:hselProgressPBR 6s linear forwards;}\r\n  @keyframes hselProgressPBR{from{width:0%}to{width:100%}}\r\n  .hsel-body-pbr{padding:.85rem 1.1rem .9rem;display:flex;align-items:center;gap:10px;}\r\n  .hsel-icon-pbr{width:30px;height:30px;border-radius:50%;border:1px solid rgba(201,168,76,.4);display:flex;align-items:center;justify-content:center;color:#C9A84C;font-size:.78rem;flex-shrink:0;transition:.3s;}\r\n  .hsel-card-pbr.active .hsel-icon-pbr,.hsel-card-pbr:hover .hsel-icon-pbr{background:#C9A84C;border-color:#C9A84C;color:#fff;}\r\n  .hsel-info-pbr{flex:1;min-width:0;}\r\n  .hsel-tag-pbr{font-size:.55rem;letter-spacing:2px;text-transform:uppercase;color:#C9A84C;display:block;margin-bottom:2px;font-weight:600;}\r\n  .hsel-info-pbr h4{font-family:\'Outfit\',sans-serif;font-size:.8rem;font-weight:600;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\r\n  .hsel-info-pbr p{font-size:.65rem;color:rgba(255,255,255,.45);}\r\n  .hsel-arrow-pbr{color:#C9A84C;font-size:.65rem;flex-shrink:0;opacity:0;transition:.3s;transform:translateX(-4px);}\r\n  .hsel-card-pbr:hover .hsel-arrow-pbr,.hsel-card-pbr.active .hsel-arrow-pbr{opacity:1;transform:translateX(0);}\r\n  @media(max-width:1200px){.hero-selector-pbr{width:220px;}.hsel-thumb-pbr{height:72px;}}\r\n  @media(max-width:900px){.hero-selector-pbr{width:100%;right:auto;top:auto;bottom:0;transform:none;flex-direction:row;}.hsel-card-pbr{flex:1;}.hsel-thumb-pbr{height:58px;}.hsel-info-pbr p{display:none;}.hsel-arrow-pbr{display:none;}.hero-stats-pbr{display:none;}}\r\n  @media(max-width:580px){.hsel-num-pbr{display:none;}.hsel-thumb-pbr{height:44px;}.hsel-body-pbr{padding:.55rem .7rem;}.hsel-info-pbr h4{font-size:.7rem;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-06 09:04:57', '2026-07-25 19:48:35'),
(217, NULL, 'Stats', 'stats', NULL, NULL, 'fa-cube', '<section id=\"stats\"><div class=\"stats-grid\"><div class=\"stat-item reveal\"><span class=\"num\">100+</span><span class=\"lbl\">Réalisations complétées</span></div><div class=\"stat-item reveal delay-1\"><span class=\"num\">25+</span><span class=\"lbl\">Années d\'expertise</span></div><div class=\"stat-item reveal delay-2\"><span class=\"num\">3</span><span class=\"lbl\">Séries exclusives</span></div><div class=\"stat-item reveal delay-3\"><span class=\"num\">∞</span><span class=\"lbl\">Possibilités sur mesure</span></div></div></section>\r\n<script>\r\n  function animCounter(el,target){var c=0,step=target/60,timer=setInterval(function(){c+=step;if(c>=target){el.textContent=target+\'+\';clearInterval(timer);}else{el.textContent=Math.floor(c)+\'+\';}},30);}\r\n  var statsObs=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.querySelectorAll(\'.num\').forEach(function(num){var txt=num.textContent;if(txt.indexOf(\'100\')!==-1)animCounter(num,100);else if(txt.indexOf(\'25\')!==-1)animCounter(num,25);});statsObs.unobserve(entry.target);}});},{threshold:.5});\r\n  var statsSection=document.getElementById(\'stats\');if(statsSection)statsObs.observe(statsSection);\r\n</script>', '#stats{background:#C9A84C;padding:3.5rem 2.5rem;}\r\n  .stats-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:2rem;max-width:1100px;margin:0 auto;text-align:center;}\r\n  .stat-item .num{font-family:\'Cormorant Garamond\',Georgia,serif;font-size:3.2rem;color:#fff;line-height:1;display:block;}\r\n  .stat-item .lbl{color:rgba(255,255,255,.8);font-size:.65rem;letter-spacing:2.5px;text-transform:uppercase;margin-top:6px;display:block;}\r\n  @media(max-width:768px){.stats-grid{grid-template-columns:1fr 1fr;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 09:05:33', '2026-06-06 11:42:32'),
(218, NULL, 'About', 'about-4', NULL, NULL, 'fa-cube', '<section id=\"about\"><div class=\"container\"><div class=\"about-grid\"><div class=\"about-img-wrap reveal\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/DSC06735-HDR.jpg\" class=\"about-img-main\"><div class=\"about-badge\"><span class=\"big\">25+</span><span class=\"small\">Années d\'excellence</span></div></div><div class=\"reveal delay-1\"><div class=\"sec-eyebrow\">Notre histoire</div><h2 class=\"sec-title\">Une <em style=\"font-style:italic;color:#C9A84C\">passion</em> pour le bois massif</h2><p style=\"color:#7A7470;line-height:1.85;margin-bottom:1.5rem\">Chez Prestige Bois Rond, chaque maison et chalet que nous concevons est l\'expression d\'une passion profonde pour le bois massif et d\'un engagement constant envers l\'excellence artisanale.</p><p style=\"color:#7A7470;line-height:1.85;margin-bottom:2rem\">Fondée au Québec, notre entreprise accompagne ses clients de la conception jusqu\'à la livraison, en offrant un service personnalisé et un savoir-faire exceptionnel reconnu à travers la province.</p><div class=\"about-feats\"><div class=\"feat-item\"><i class=\"fa fa-leaf\"></i><div><h4>Matériaux durables</h4><p>Bois massif sélectionné pour sa qualité et sa durabilité.</p></div></div><div class=\"feat-item\"><i class=\"fa fa-tools\"></i><div><h4>Artisanat expert</h4><p>Chaque pièce usinée avec précision par nos artisans.</p></div></div><div class=\"feat-item\"><i class=\"fa fa-snowflake\"></i><div><h4>Normes énergétiques</h4><p>Conformes aux plus hautes normes d\'efficacité.</p></div></div><div class=\"feat-item\"><i class=\"fa fa-handshake\"></i><div><h4>Accompagnement complet</h4><p>De la conception jusqu\'à la livraison, avec vous.</p></div></div></div><div style=\"margin-top:2.5rem\"><a href=\"#contact\" class=\"btn-primary\">Parlez-nous de votre projet</a></div></div></div></div></section>', '#about{background:#0F0F0F;padding:6rem 2.5rem;}\r\n  .about-grid{display:grid;grid-template-columns:1fr 1fr;gap:6rem;align-items:center;}\r\n  .about-img-wrap{position:relative;}\r\n  .about-img-main{width:100%;height:560px;object-fit:cover;}\r\n  .about-badge{position:absolute;bottom:-2rem;right:-2rem;background:#C9A84C;padding:2.2rem;text-align:center;min-width:160px;}\r\n  .about-badge .big{font-family:\'Cormorant Garamond\',Georgia,serif;font-size:3rem;color:#1A1109;display:block;line-height:1;}\r\n  .about-badge .small{font-size:.65rem;letter-spacing:2px;text-transform:uppercase;color:rgba(0,0,0,0.7);}\r\n  .about-feats{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:2.5rem;}\r\n  .feat-item{display:flex;align-items:flex-start;gap:12px;padding:1.2rem;background:#161616;border:1px solid rgba(255,255,255,0.06);border-left:3px solid #C9A84C;}\r\n  .feat-item i{color:#C9A84C;font-size:1.1rem;margin-top:2px;flex-shrink:0;}\r\n  .feat-item h4{font-family:\'Outfit\',sans-serif;font-size:.82rem;font-weight:600;margin-bottom:3px;color:#F5F0E8;}\r\n  .feat-item p{font-size:.76rem;color:#7A7470;line-height:1.5;}\r\n  @media(max-width:1100px){.about-grid{grid-template-columns:1fr;gap:3rem;}}\r\n  @media(max-width:768px){#about{padding:4rem 1.5rem;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 09:12:07', '2026-06-06 11:43:18'),
(219, NULL, 'Vidéo Section', 'video-section-2', NULL, NULL, 'fa-cube', '<div class=\"video-modal-pbr\" id=\"videoModalPBR\"><button class=\"video-close-pbr\" onclick=\"closeVideoPBR()\"><i class=\"fa fa-times\"></i></button><iframe id=\"videoFramePBR\" class=\"video-frame-pbr\" width=\"900\" height=\"506\" src=\"\" frameborder=\"0\" allow=\"autoplay;encrypted-media\" allowfullscreen></iframe></div>\r\n<section id=\"video-section-pbr\" class=\"video-block-pbr\"><div class=\"container-pbr\"><div class=\"sec-eyebrow-pbr\" style=\"justify-content:center\">Notre univers</div><h2 class=\"sec-title-pbr\" style=\"text-align:center;margin-bottom:.5rem\">Visitez nos <span style=\"color:#C9A84C\">réalisations</span></h2><p style=\"text-align:center;color:var(--text-muted,#7A7470);margin-bottom:0\">Découvrez l\'artisanat et la passion derrière chaque projet Prestige Bois Rond.</p><div class=\"video-wrap-pbr reveal-pbr\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/07/bg-dji.jpg\" alt=\"Vidéo\" class=\"video-thumb-pbr\"><button class=\"video-play-pbr\" onclick=\"openVideoPBR()\"><i class=\"fa fa-play\"></i></button></div></div></section>\r\n<script>\r\n  (function(){\r\n    window.openVideoPBR=function(){document.getElementById(\'videoFramePBR\').src=\'https://www.youtube.com/embed/2AOSbHozuzY?autoplay=1\';document.getElementById(\'videoModalPBR\').classList.add(\'open\');document.body.style.overflow=\'hidden\';};\r\n    window.closeVideoPBR=function(){document.getElementById(\'videoFramePBR\').src=\'\';document.getElementById(\'videoModalPBR\').classList.remove(\'open\');document.body.style.overflow=\'\';};\r\n    var revealObs=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting)e.target.classList.add(\'visible\');});},{threshold:.1});\r\n    document.querySelectorAll(\'#video-section-pbr .reveal-pbr\').forEach(function(el){revealObs.observe(el);});\r\n  })();\r\n</script>', '.video-block-pbr{background:#080808;padding:5rem 2.5rem;text-align:center;}\r\n  .video-wrap-pbr{position:relative;max-width:920px;margin:2.5rem auto 0;overflow:hidden;}\r\n  .video-thumb-pbr{width:100%;display:block;filter:brightness(.55);}\r\n  .video-play-pbr{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:82px;height:82px;border-radius:50%;background:#C9A84C;border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:1.6rem;color:#fff;transition:var(--transition,0.4s);box-shadow:0 0 0 16px rgba(201,168,76,.18);}\r\n  .video-play-pbr:hover{transform:translate(-50%,-50%) scale(1.1);box-shadow:0 0 0 22px rgba(201,168,76,.26);}\r\n  .video-modal-pbr{display:none;position:fixed;inset:0;z-index:9000;background:rgba(0,0,0,.96);align-items:center;justify-content:center;}\r\n  .video-modal-pbr.open{display:flex;}\r\n  .video-close-pbr{position:absolute;top:1.5rem;right:1.5rem;background:#C9A84C;border:none;color:#fff;width:44px;height:44px;border-radius:50%;font-size:1.1rem;cursor:pointer;display:flex;align-items:center;justify-content:center;}\r\n  .video-frame-pbr{max-width:95vw;max-height:85vh;border:1px solid var(--border,rgba(255,255,255,0.06));}\r\n  @media(max-width:768px){.video-block-pbr{padding:4rem 1.5rem;}.video-play-pbr{width:60px;height:60px;font-size:1.2rem;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-06 09:25:22', '2026-07-25 19:48:22'),
(220, NULL, 'Gallerie', 'gallerie-2', NULL, NULL, 'fa-cube', '<section id=\"gallery\"><div class=\"container\"><div class=\"sec-eyebrow reveal\">Galerie photos</div><h2 class=\"sec-title reveal\">Nos <span class=\"text-gold\">Réalisations</span></h2><p class=\"sec-sub reveal\" style=\"margin-bottom:2rem;color:#7A7470\">Parcourez notre galerie et laissez-vous inspirer par l\'authenticité et la beauté de nos constructions en bois rond.</p><div class=\"gallery-filter reveal\"><button class=\"filter-btn active\" data-filter=\"all\">Tout</button><button class=\"filter-btn\" data-filter=\"prestige\">Série Prestige</button><button class=\"filter-btn\" data-filter=\"scandinave\">Série Scandinave</button><button class=\"filter-btn\" data-filter=\"contemporain\">Contemporain</button></div><div class=\"gallery-grid\" id=\"galleryGrid\"><div class=\"gallery-item\" data-cat=\"prestige\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/DSC06735-HDR.jpg\"><div class=\"gitem-ov\"><i class=\"fa fa-expand\"></i></div></div><div class=\"gallery-item\" data-cat=\"scandinave\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/SaveInsta.App_327015499_693241832530188_5777615420000727358_n.jpg\"><div class=\"gitem-ov\"><i class=\"fa fa-expand\"></i></div></div><div class=\"gallery-item\" data-cat=\"contemporain\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/DJI_0237.jpg\"><div class=\"gitem-ov\"><i class=\"fa fa-expand\"></i></div></div><div class=\"gallery-item\" data-cat=\"prestige\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/IMG-20250628-WA0010.jpg\"><div class=\"gitem-ov\"><i class=\"fa fa-expand\"></i></div></div><div class=\"gallery-item\" data-cat=\"prestige\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/Gestion-complete-par-nos-experts-image-.jpg\"><div class=\"gitem-ov\"><i class=\"fa fa-expand\"></i></div></div><div class=\"gallery-item\" data-cat=\"scandinave\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/09/Client-auto-constructeur-image.jpg\"><div class=\"gitem-ov\"><i class=\"fa fa-expand\"></i></div></div><div class=\"gallery-item\" data-cat=\"contemporain\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/07/real-hero.jpg\"><div class=\"gitem-ov\"><i class=\"fa fa-expand\"></i></div></div><div class=\"gallery-item\" data-cat=\"prestige\"><img src=\"https://prestigeboisrond.ca/wp-content/uploads/2025/07/bg-dji.jpg\"><div class=\"gitem-ov\"><i class=\"fa fa-expand\"></i></div></div></div><div style=\"text-align:center;margin-top:2.5rem\"><a href=\"#\" class=\"btn-primary\">Voir toutes nos réalisations</a></div></div></section>\r\n<script>\r\n  (function(){\r\n    var galleryImgs=Array.from(document.querySelectorAll(\'#galleryGrid .gallery-item img\')).map(function(i){return i.src;});\r\n    var lbIdx=0;\r\n    document.querySelectorAll(\'#galleryGrid .gallery-item\').forEach(function(item,idx){item.addEventListener(\'click\',function(){lbIdx=idx;document.getElementById(\'lb-img\').src=galleryImgs[idx];document.getElementById(\'lightbox\').classList.add(\'open\');document.body.style.overflow=\'hidden\';});});\r\n    document.getElementById(\'lb-close\').onclick=function(){document.getElementById(\'lightbox\').classList.remove(\'open\');document.body.style.overflow=\'\';};\r\n    document.getElementById(\'lb-prev\').onclick=function(){lbIdx=(lbIdx-1+galleryImgs.length)%galleryImgs.length;document.getElementById(\'lb-img\').src=galleryImgs[lbIdx];};\r\n    document.getElementById(\'lb-next\').onclick=function(){lbIdx=(lbIdx+1)%galleryImgs.length;document.getElementById(\'lb-img\').src=galleryImgs[lbIdx];};\r\n    document.getElementById(\'lightbox\').addEventListener(\'click\',function(e){if(e.target===document.getElementById(\'lightbox\')){document.getElementById(\'lightbox\').classList.remove(\'open\');document.body.style.overflow=\'\';}});\r\n    var filterBtns=document.querySelectorAll(\'.filter-btn\');\r\n    filterBtns.forEach(function(btn){btn.addEventListener(\'click\',function(){filterBtns.forEach(function(b){b.classList.remove(\'active\');});btn.classList.add(\'active\');var filter=btn.dataset.filter;document.querySelectorAll(\'#galleryGrid .gallery-item\').forEach(function(item){var show=(filter===\'all\'||item.dataset.cat===filter);item.style.opacity=show?\'1\':\'0\';item.style.display=show?\'block\':\'none\';});});});\r\n  })();\r\n</script>', '#gallery{background:#0F0F0F;padding:6rem 2.5rem 3rem;}\r\n  .gallery-filter{display:flex;gap:.5rem;margin-bottom:2.5rem;flex-wrap:wrap;}\r\n  .filter-btn{padding:.45rem 1.2rem;font-size:.73rem;letter-spacing:1px;text-transform:uppercase;font-family:\'Outfit\',sans-serif;border:1px solid rgba(255,255,255,0.1);background:transparent;color:#F5F0E8;cursor:pointer;transition:all 0.4s;}\r\n  .filter-btn.active,.filter-btn:hover{background:#C9A84C;border-color:#C9A84C;color:#1A1109;}\r\n  .gallery-grid{columns:4;gap:4px;}\r\n  .gallery-item{break-inside:avoid;margin-bottom:4px;overflow:hidden;position:relative;cursor:pointer;}\r\n  .gallery-item img{width:100%;display:block;transition:transform .5s;filter:brightness(.88);}\r\n  .gallery-item:hover img{transform:scale(1.05);filter:brightness(1);}\r\n  .gitem-ov{position:absolute;inset:0;background:rgba(201,168,76,0);display:flex;align-items:center;justify-content:center;transition:.4s;}\r\n  .gallery-item:hover .gitem-ov{background:rgba(201,168,76,.22);}\r\n  .gitem-ov i{font-size:1.8rem;color:#fff;opacity:0;transform:scale(0);transition:.3s;}\r\n  .gallery-item:hover .gitem-ov i{opacity:1;transform:scale(1);}\r\n  @media(max-width:768px){#gallery{padding:4rem 1.5rem 2rem;}.gallery-grid{columns:2;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 09:26:30', '2026-06-06 11:44:22'),
(221, NULL, 'Services', 'services-3', NULL, NULL, 'fa-cube', '<section id=\"services\"><div class=\"container\"><div class=\"sec-eyebrow reveal\">Ce que nous offrons</div><h2 class=\"sec-title reveal\">Nos <span class=\"text-gold\">Services</span></h2><p class=\"sec-sub reveal\" style=\"color:#7A7470\">Un accompagnement complet du début à la fin de votre projet.</p><div class=\"services-grid\"><div class=\"svc-card reveal\"><div class=\"svc-icon\"><i class=\"fa fa-drafting-compass\"></i></div><h3>Plans & Conception</h3><p>Nos architectes et techniciens créent des plans sur mesure adaptés à votre terrain, votre style et votre budget.</p><a href=\"#\" class=\"svc-link\">En savoir plus <i class=\"fa fa-arrow-right\"></i></a></div><div class=\"svc-card reveal delay-1\"><div class=\"svc-icon\"><i class=\"fa fa-hard-hat\"></i></div><h3>Surveillance de chantier</h3><p>Notre équipe supervise chaque étape de votre construction pour garantir qualité et conformité aux normes.</p><a href=\"#\" class=\"svc-link\">En savoir plus <i class=\"fa fa-arrow-right\"></i></a></div><div class=\"svc-card reveal delay-2\"><div class=\"svc-icon\"><i class=\"fa fa-hammer\"></i></div><h3>Auto-construction</h3><p>Envie de participer à la construction de votre rêve ? Nous vous fournissons les kits, documents et l\'assistance nécessaires.</p><a href=\"#\" class=\"svc-link\">En savoir plus <i class=\"fa fa-arrow-right\"></i></a></div><div class=\"svc-card reveal\"><div class=\"svc-icon\"><i class=\"fa fa-home\"></i></div><h3>Ajouts & Rénovations</h3><p>Peu importe l\'ampleur de vos rénovations en bois massif, nous avons la solution adaptée à vos besoins.</p><a href=\"#\" class=\"svc-link\">En savoir plus <i class=\"fa fa-arrow-right\"></i></a></div><div class=\"svc-card reveal delay-1\"><div class=\"svc-icon\"><i class=\"fa fa-truck\"></i></div><h3>Transport</h3><p>Ne vous cassez pas la tête — nous nous occupons de la livraison de votre structure partout au Québec.</p><a href=\"#\" class=\"svc-link\">En savoir plus <i class=\"fa fa-arrow-right\"></i></a></div><div class=\"svc-card reveal delay-2\"><div class=\"svc-icon\"><i class=\"fa fa-headset\"></i></div><h3>Soutien technique</h3><p>Notre équipe d\'experts est disponible pour répondre à toutes vos questions techniques tout au long du projet.</p><a href=\"#\" class=\"svc-link\">En savoir plus <i class=\"fa fa-arrow-right\"></i></a></div></div></div></section>', '#services{background:#080808;padding:6rem 2.5rem;}\r\n  .services-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.5px;margin-top:3rem;}\r\n  .svc-card{background:#1E1E1E;border:1px solid rgba(255,255,255,0.06);padding:2.5rem 2rem;position:relative;overflow:hidden;transition:all 0.4s;}\r\n  .svc-card::after{content:\'\';position:absolute;bottom:0;left:0;width:0;height:2px;background:#C9A84C;transition:width .4s;}\r\n  .svc-card:hover{transform:translateY(-4px);box-shadow:0 22px 55px rgba(0,0,0,.3);}\r\n  .svc-card:hover::after{width:100%;}\r\n  .svc-icon{width:54px;height:54px;border-radius:50%;border:1px solid #C9A84C;display:flex;align-items:center;justify-content:center;margin-bottom:1.5rem;color:#C9A84C;font-size:1.3rem;transition:all 0.4s;}\r\n  .svc-card:hover .svc-icon{background:#C9A84C;color:#fff;}\r\n  .svc-card h3{font-size:1.08rem;margin-bottom:.7rem;color:#F5F0E8;}\r\n  .svc-card p{font-size:.83rem;color:#7A7470;line-height:1.7;margin-bottom:1.2rem;}\r\n  .svc-link{font-size:.72rem;letter-spacing:1px;text-transform:uppercase;color:#C9A84C;font-weight:600;display:inline-flex;align-items:center;gap:6px;text-decoration:none;}\r\n  .svc-link i{transition:transform .3s;}\r\n  .svc-link:hover i{transform:translateX(5px);}\r\n  @media(max-width:1100px){.services-grid{grid-template-columns:1fr 1fr;}}\r\n  @media(max-width:768px){#services{padding:4rem 1.5rem;}.services-grid{grid-template-columns:1fr;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 09:38:08', '2026-06-06 11:44:56'),
(222, NULL, 'Process', 'process', NULL, NULL, 'fa-cube', '<section id=\"process\"><div class=\"container\"><div class=\"sec-eyebrow reveal\" style=\"justify-content:center\">Étapes du projet</div><h2 class=\"sec-title reveal\" style=\"text-align:center\">Comment ça <span class=\"text-gold\">fonctionne</span></h2><div class=\"process-steps\"><div class=\"proc-step reveal\"><div class=\"proc-num\">1</div><h3>Consultation</h3><p>Discussion de vos besoins, budget et style de vie pour définir votre projet idéal.</p></div><div class=\"proc-step reveal delay-1\"><div class=\"proc-num\">2</div><h3>Conception</h3><p>Élaboration des plans et soumission personnalisée selon vos spécifications.</p></div><div class=\"proc-step reveal delay-2\"><div class=\"proc-num\">3</div><h3>Fabrication</h3><p>Usinage précis de votre structure en bois rond dans nos installations au Québec.</p></div><div class=\"proc-step reveal delay-3\"><div class=\"proc-num\">4</div><h3>Livraison</h3><p>Transport et livraison de votre kit directement sur votre terrain.</p></div><div class=\"proc-step reveal delay-4\"><div class=\"proc-num\">5</div><h3>Emménagement</h3><p>Votre maison de rêve est prête. Bienvenue dans votre nouveau chez-vous!</p></div></div></div></section>', '#process{background:#0F0F0F;padding:6rem 2.5rem;}\r\n  .process-steps{display:grid;grid-template-columns:repeat(5,1fr);margin-top:3rem;position:relative;}\r\n  .process-steps::before{content:\'\';position:absolute;top:43px;left:10%;right:10%;height:1px;background:linear-gradient(90deg,transparent,#C9A84C,transparent);z-index:0;}\r\n  .proc-step{text-align:center;padding:2rem 1rem;position:relative;z-index:1;}\r\n  .proc-num{width:54px;height:54px;border-radius:50%;background:#C9A84C;color:#fff;display:flex;align-items:center;justify-content:center;font-family:\'Cormorant Garamond\',Georgia,serif;font-size:1.2rem;font-weight:700;margin:0 auto 1.2rem;box-shadow:0 0 0 8px #0F0F0F;}\r\n  .proc-step h3{font-family:\'Outfit\',sans-serif;font-size:.88rem;font-weight:600;margin-bottom:.5rem;color:#F5F0E8;}\r\n  .proc-step p{font-size:.76rem;color:#7A7470;line-height:1.5;}\r\n  @media(max-width:768px){#process{padding:4rem 1.5rem;}.process-steps{grid-template-columns:1fr;}.process-steps::before{display:none;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 09:39:04', '2026-06-06 11:45:33'),
(223, NULL, 'Avis Clients', 'avis-clients', NULL, NULL, 'fa-cube', '<section id=\"testimonials\"><div class=\"container\"><div class=\"sec-eyebrow reveal\" style=\"justify-content:center\">Avis clients</div><h2 class=\"sec-title reveal\" style=\"text-align:center\">Ce que nos clients <span class=\"text-gold\">disent</span></h2><div class=\"swiper testimonials-swiper\" style=\"margin-top:3rem;padding:1rem 0 3rem\"><div class=\"swiper-wrapper\"><div class=\"swiper-slide testi-slide\"><div class=\"testi-card\"><div class=\"testi-stars\">★★★★★</div><p>\"Prestige Bois Rond a réalisé le chalet de nos rêves. Du premier contact jusqu\'à la livraison, l\'équipe a été professionnelle, à l\'écoute et d\'une précision remarquable. Le résultat dépasse toutes nos attentes.\"</p><div class=\"testi-author\"><div class=\"testi-avatar\">ML</div><div><h4>Marie-Lise Tremblay</h4><span>Laurentides, Québec • Série Prestige</span></div></div></div></div><div class=\"swiper-slide testi-slide\"><div class=\"testi-card\"><div class=\"testi-stars\">★★★★★</div><p>\"Nous avons opté pour l\'auto-construction avec le soutien de Prestige Bois Rond. L\'accompagnement était exceptionnel! Ils ont répondu à chacune de nos questions avec patience et expertise. Notre maison est magnifique!\"</p><div class=\"testi-author\"><div class=\"testi-avatar\">PL</div><div><h4>Pierre & Lucie Bergeron</h4><span>Lanaudière, Québec • Auto-construction</span></div></div></div></div><div class=\"swiper-slide testi-slide\"><div class=\"testi-card\"><div class=\"testi-stars\">★★★★★</div><p>\"La qualité du bois et le soin apporté à chaque détail est impressionnant. Notre chalet scandinave est une pure merveille — chaleureux l\'hiver, frais l\'été. On recommande Prestige Bois Rond à 100%!\"</p><div class=\"testi-author\"><div class=\"testi-avatar\">JF</div><div><h4>Jean-François Côté</h4><span>Estrie, Québec • Série Scandinave</span></div></div></div></div><div class=\"swiper-slide testi-slide\"><div class=\"testi-card\"><div class=\"testi-stars\">★★★★★</div><p>\"Notre maison contemporaine hybride est à la fois moderne et chaleureuse. Le service après-vente est également irréprochable. Une équipe passionnée et compétente de bout en bout.\"</p><div class=\"testi-author\"><div class=\"testi-avatar\">SB</div><div><h4>Sophie Beaumont</h4><span>Charlevoix, Québec • Série Contemporaine</span></div></div></div></div></div><div class=\"swiper-pagination\"></div></div></div></section>\r\n<script>\r\n  new Swiper(\'.testimonials-swiper\',{loop:true,speed:800,autoplay:{delay:5000},slidesPerView:1,spaceBetween:24,breakpoints:{768:{slidesPerView:2},1200:{slidesPerView:3}},pagination:{el:\'.testimonials-swiper .swiper-pagination\',clickable:true}});\r\n</script>', '#testimonials{background:#080808;position:relative;overflow:hidden;padding:6rem 2.5rem;}\r\n  #testimonials::before{content:\'\"\';position:absolute;top:-2rem;left:4%;z-index:0;font-family:\'Cormorant Garamond\',Georgia,serif;font-size:18rem;color:#C9A84C;opacity:.04;line-height:1;}\r\n  .testimonials-swiper{position:relative;z-index:1;}\r\n  .testi-slide{padding:1rem 2.5rem;}\r\n  .testi-card{background:#1E1E1E;border:1px solid rgba(255,255,255,0.06);padding:2.5rem;}\r\n  .testi-stars{color:#C9A84C;font-size:.85rem;margin-bottom:1.2rem;letter-spacing:2px;}\r\n  .testi-card p{font-size:.95rem;line-height:1.8;color:#7A7470;font-style:italic;margin-bottom:1.5rem;}\r\n  .testi-author{display:flex;align-items:center;gap:12px;}\r\n  .testi-avatar{width:46px;height:46px;border-radius:50%;background:#C9A84C;display:flex;align-items:center;justify-content:center;font-family:\'Cormorant Garamond\',Georgia,serif;color:#fff;font-size:1.05rem;}\r\n  .testi-author h4{font-family:\'Outfit\',sans-serif;font-size:.88rem;font-weight:600;color:#F5F0E8;}\r\n  .testi-author span{font-size:.72rem;color:#7A7470;}\r\n  @media(max-width:768px){#testimonials{padding:4rem 1.5rem;}.testi-slide{padding:1rem;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 09:39:49', '2026-06-06 11:46:02'),
(224, NULL, 'SOCIAL FEED', 'social-feed', NULL, NULL, 'fa-cube', '<section id=\"social-feed\"><div class=\"container\"><div class=\"sec-eyebrow reveal\">Suivez-nous</div><h2 class=\"sec-title reveal\">Nos <span class=\"text-gold\">Médias Sociaux</span></h2><div class=\"social-tabs reveal\" style=\"margin-top:1.5rem\"><button class=\"social-tab active\" data-social=\"instagram\"><i class=\"fab fa-instagram\"></i> Instagram</button><button class=\"social-tab\" data-social=\"facebook\"><i class=\"fab fa-facebook\"></i> Facebook</button><button class=\"social-tab\" data-social=\"pinterest\"><i class=\"fab fa-pinterest\"></i> Pinterest</button></div><div class=\"swiper social-swiper\" style=\"margin-top:1.5rem;padding-bottom:3rem\"><div class=\"swiper-wrapper\" id=\"socialFeed\"></div><div class=\"swiper-pagination\"></div></div><div style=\"text-align:center;margin-top:1rem\"><a href=\"https://www.instagram.com/prestigeboisrond/\" target=\"_blank\" class=\"btn-primary\" style=\"margin-right:1rem\"><i class=\"fab fa-instagram\"></i> Instagram</a><a href=\"https://www.facebook.com/prestigeboisrond\" target=\"_blank\" class=\"btn-outline\"><i class=\"fab fa-facebook\"></i> Facebook</a></div></div></section>\r\n<script>\r\n  (function(){\r\n    var socialImages=[\'https://prestigeboisrond.ca/wp-content/uploads/2025/09/DSC06735-HDR.jpg\',\'https://prestigeboisrond.ca/wp-content/uploads/2025/09/SaveInsta.App_327015499_693241832530188_5777615420000727358_n.jpg\',\'https://prestigeboisrond.ca/wp-content/uploads/2025/09/DJI_0237.jpg\',\'https://prestigeboisrond.ca/wp-content/uploads/2025/09/IMG-20250628-WA0010.jpg\',\'https://prestigeboisrond.ca/wp-content/uploads/2025/09/Gestion-complete-par-nos-experts-image-.jpg\',\'https://prestigeboisrond.ca/wp-content/uploads/2025/09/Client-auto-constructeur-image.jpg\'];\r\n    var socialCaptions=[\'Notre dernière réalisation en Série Prestige — l\\\'art du bois rond au sommet 🏡 #PrestigeBoisRond\',\'Chalet scandinave livré cette semaine! Merci à nos clients pour leur confiance ❤️ #BoisRond\',\'Vue de drone sur notre plus récente construction contemporaine #Québec #Chalet\',\'Avant/Après: transformation magnifique avec nos services d\\\'ajout et rénovation 🔨\',\'Notre équipe d\\\'experts sur le chantier — la qualité avant tout! #Artisanat\',\'Auto-construction réussie! Nos clients ont bâti leur rêve avec notre soutien 💪\'];\r\n    var socialPlat={instagram:{label:\'Instagram\',icon:\'fab fa-instagram\'},facebook:{label:\'Facebook\',icon:\'fab fa-facebook\'},pinterest:{label:\'Pinterest\',icon:\'fab fa-pinterest\'}};\r\n    var socialSwiperInst=null;\r\n    function renderSocialFeed(platform){var feed=document.getElementById(\'socialFeed\');if(!feed)return;feed.innerHTML=socialImages.map(function(img,i){return \'<div class=\"swiper-slide\"><div class=\"social-post\"><div class=\"social-post-img\"><img src=\"\'+img+\'\" loading=\"lazy\"></div><div class=\"social-post-info\"><div class=\"platform\"><i class=\"\'+socialPlat[platform].icon+\'\"></i> \'+socialPlat[platform].label+\'</div><p>\'+socialCaptions[i%socialCaptions.length]+\'</p></div></div></div>\';}).join(\'\');if(socialSwiperInst)socialSwiperInst.destroy(true,true);socialSwiperInst=new Swiper(\'.social-swiper\',{loop:false,speed:700,slidesPerView:2,spaceBetween:16,autoplay:{delay:4000},breakpoints:{768:{slidesPerView:3},1024:{slidesPerView:4}},pagination:{el:\'.social-swiper .swiper-pagination\',clickable:true}});}\r\n    renderSocialFeed(\'instagram\');\r\n    document.querySelectorAll(\'.social-tab\').forEach(function(tab){tab.addEventListener(\'click\',function(){document.querySelectorAll(\'.social-tab\').forEach(function(t){t.classList.remove(\'active\');});tab.classList.add(\'active\');renderSocialFeed(tab.dataset.social);});});\r\n  })();\r\n</script>', '#social-feed{background:#0F0F0F;padding:4rem 2.5rem;}\r\n  .social-tabs{display:flex;gap:1rem;margin-bottom:2rem;}\r\n  .social-tab{padding:.45rem 1.4rem;border-radius:50px;border:1px solid rgba(255,255,255,0.1);background:transparent;color:#F5F0E8;cursor:pointer;font-family:\'Outfit\',sans-serif;font-size:.8rem;font-weight:500;transition:all 0.4s;display:flex;align-items:center;gap:8px;}\r\n  .social-tab.active{background:#C9A84C;border-color:#C9A84C;color:#1A1109;}\r\n  .social-post{background:#1E1E1E;border:1px solid rgba(255,255,255,0.06);overflow:hidden;cursor:pointer;}\r\n  .social-post-img{aspect-ratio:1;overflow:hidden;}\r\n  .social-post-img img{width:100%;height:100%;object-fit:cover;transition:transform .5s;}\r\n  .social-post:hover .social-post-img img{transform:scale(1.06);}\r\n  .social-post-info{padding:1rem;}\r\n  .social-post-info .platform{font-size:.68rem;color:#C9A84C;font-weight:600;letter-spacing:1px;margin-bottom:.4rem;}\r\n  .social-post-info p{font-size:.8rem;color:#7A7470;line-height:1.5;}\r\n  @media(max-width:768px){#social-feed{padding:3rem 1.5rem;}}', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 09:40:28', '2026-06-06 11:47:11');
INSERT INTO `blocks` (`id`, `categorie_id`, `name`, `slug`, `description`, `thumbnail`, `icon`, `html_content`, `css_content`, `js_content`, `section_id`, `category`, `website_type`, `tags`, `is_responsive`, `is_free`, `width`, `height`, `usage_count`, `views_count`, `rating`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(225, NULL, 'CTA BANNER', 'cta-banner', NULL, NULL, 'fa-cube', '#cta-banner{position:relative;overflow:hidden;background:#080808;padding:5.5rem 2.5rem;}\r\n  .cta-bg{position:absolute;inset:0;z-index:0;background-image:url(\'https://prestigeboisrond.ca/wp-content/uploads/2025/07/bg-dji.jpg\');background-size:cover;background-position:center;opacity:.2;}\r\n  .cta-inner{position:relative;z-index:1;text-align:center;max-width:720px;margin:0 auto;}\r\n  .cta-inner h2{font-size:clamp(2rem,4vw,3.6rem);color:#fff;margin-bottom:1rem;}\r\n  .cta-inner p{color:rgba(255,255,255,.68);font-size:.98rem;margin-bottom:2.5rem;}\r\n  .cta-btns{display:flex;gap:1rem;justify-content:center;flex-wrap:wrap;}\r\n  @media(max-width:768px){#cta-banner{padding:4rem 1.5rem;}}', '<section id=\"cta-banner\"><div class=\"cta-bg\"></div><div class=\"cta-inner reveal\"><div class=\"sec-eyebrow\" style=\"justify-content:center;color:#fff;opacity:.7\">Passez à l\'action</div><h2>Bâtissez votre projet<br>de <em style=\"color:#C9A84C;font-style:italic\">rêve</em> avec nous</h2><p>Des projets pour tous les budgets. Accompagnement sur-mesure du début à la fin. Contactez-nous dès aujourd\'hui.</p><div class=\"cta-btns\"><a href=\"#contact\" class=\"btn-primary\">Obtenir une soumission gratuite</a><a href=\"tel:4385252063\" class=\"btn-ghost\">(438) 525-2063</a></div></div></section>', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 09:41:10', '2026-06-06 11:47:50'),
(226, NULL, 'Footer', 'footer', NULL, NULL, 'fa-cube', '<footer><div class=\"footer-grid\"><div class=\"footer-brand\"><div class=\"logo\" style=\"margin-bottom:1rem\"><div class=\"logo-mark\"><i class=\"fa fa-tree\"></i></div><div class=\"logo-text\" style=\"color:#fff\">Prestige Bois Rond <span>Québec, Canada</span></div></div><p>Chaque maison et chalet que nous concevons est l\'expression d\'une passion pour le bois massif et d\'un engagement constant envers l\'excellence artisanale.</p><div class=\"social-links\"><a href=\"https://www.facebook.com/prestigeboisrond\" target=\"_blank\" class=\"social-link\"><i class=\"fab fa-facebook-f\"></i></a><a href=\"https://www.instagram.com/prestigeboisrond/\" target=\"_blank\" class=\"social-link\"><i class=\"fab fa-instagram\"></i></a><a href=\"https://www.pinterest.com/prestigeboisrond/\" target=\"_blank\" class=\"social-link\"><i class=\"fab fa-pinterest-p\"></i></a><a href=\"https://www.youtube.com/@prestigeboisrond\" target=\"_blank\" class=\"social-link\"><i class=\"fab fa-youtube\"></i></a></div></div><div class=\"footer-col\"><h4>Maisons & Chalets</h4><ul><li><a href=\"#\">Tous nos modèles</a></li><li><a href=\"#\">Série Prestige</a></li><li><a href=\"#\">Série Scandinave</a></li><li><a href=\"#\">Série Contemporaine</a></li><li><a href=\"#\">Maison en bois rond</a></li><li><a href=\"#\">Chalet en bois rond</a></li></ul></div><div class=\"footer-col\"><h4>Services</h4><ul><li><a href=\"#\">Plans</a></li><li><a href=\"#\">Soutien technique</a></li><li><a href=\"#\">Auto-construction</a></li><li><a href=\"#\">Surveillance chantier</a></li><li><a href=\"#\">Ajouts & rénovations</a></li><li><a href=\"#\">Transport</a></li></ul></div><div class=\"footer-col\"><h4>À propos</h4><ul><li><a href=\"#\">Notre histoire</a></li><li><a href=\"#\">Avantages</a></li><li><a href=\"#\">Normes énergétiques</a></li><li><a href=\"#\">Réalisations</a></li><li><a href=\"#\">Blogue</a></li><li><a href=\"#\">FAQ</a></li><li><a href=\"#\">Contact</a></li></ul></div></div><div class=\"footer-bottom\"><p>© 2025 Prestige Bois Rond. Tous droits réservés.</p><div class=\"footer-bottom-links\"><a href=\"#\">Confidentialité</a><a href=\"#\">Conditions</a><a href=\"#\">Plan du site</a></div></div></footer>', 'footer{background:#050505;color:rgba(255,255,255,.55);padding:4.5rem 2.5rem 2rem;}\r\n  .footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:3rem;max-width:1340px;margin:0 auto;}\r\n  .footer-brand .logo-text{color:#fff;margin-bottom:1rem;}\r\n  .footer-brand p{font-size:.83rem;line-height:1.75;margin-bottom:1.5rem;color:rgba(255,255,255,.55);}\r\n  .footer-col h4{color:#fff;font-family:\'Outfit\',sans-serif;font-size:.78rem;font-weight:700;letter-spacing:2.5px;text-transform:uppercase;margin-bottom:1.2rem;}\r\n  .footer-col ul{list-style:none;}\r\n  .footer-col ul li{margin-bottom:.6rem;}\r\n  .footer-col ul li a{font-size:.8rem;transition:color .2s;color:rgba(255,255,255,.55);text-decoration:none;}\r\n  .footer-col ul li a:hover{color:#C9A84C;}\r\n  .footer-bottom{border-top:1px solid rgba(255,255,255,.04);margin-top:3rem;padding-top:1.5rem;max-width:1340px;margin-left:auto;margin-right:auto;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:1rem;}\r\n  .footer-bottom p{font-size:.75rem;}\r\n  .footer-bottom-links{display:flex;gap:1.5rem;}\r\n  .footer-bottom-links a{font-size:.75rem;transition:color .2s;color:rgba(255,255,255,.55);text-decoration:none;}\r\n  .footer-bottom-links a:hover{color:#C9A84C;}\r\n  @media(max-width:1100px){.footer-grid{grid-template-columns:1fr 1fr;}}\r\n  @media(max-width:768px){footer{padding:3rem 1.5rem 2rem;}.footer-grid{grid-template-columns:1fr;}.footer-bottom{flex-direction:column;text-align:center;}}', NULL, NULL, 'Footer', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 09:42:28', '2026-06-06 11:48:18'),
(227, NULL, 'Navigation', 'navigation-3', NULL, NULL, 'fa-cube', '<nav class=\"nav-sylva\" id=\"navbarSylva\">\r\n  <a href=\"#\" class=\"nav-logo-sylva\"><div class=\"logo-icon-sylva\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z\"/><polyline points=\"9,22 9,12 15,12 15,22\"/></svg></div>SYLVA<span>.</span></a>\r\n  <ul class=\"nav-links-sylva\"><li><a href=\"#services\">Services</a></li><li><a href=\"#projets\">Réalisations</a></li><li><a href=\"#materiaux\">Matériaux</a></li><li><a href=\"#equipe\">Équipe</a></li><li><a href=\"#blog\">Actualités</a></li><li><a href=\"#contact\">Contact</a></li></ul>\r\n  <a href=\"#contact\" class=\"nav-cta-sylva\">Devis Gratuit</a>\r\n  <button class=\"nav-hamburger-sylva\" id=\"hamburgerSylva\"><span class=\"ham-line-sylva\"></span><span class=\"ham-line-sylva\"></span><span class=\"ham-line-sylva\"></span></button>\r\n</nav>\r\n<div class=\"mobile-nav-sylva\" id=\"mobileNavSylva\"><ul class=\"mobile-nav-links-sylva\"><li><a href=\"#services\" onclick=\"closeMobileSylva()\">Services</a></li><li><a href=\"#projets\" onclick=\"closeMobileSylva()\">Réalisations</a></li><li><a href=\"#materiaux\" onclick=\"closeMobileSylva()\">Matériaux</a></li><li><a href=\"#equipe\" onclick=\"closeMobileSylva()\">Équipe</a></li><li><a href=\"#blog\" onclick=\"closeMobileSylva()\">Actualités</a></li><li><a href=\"#contact\" onclick=\"closeMobileSylva()\">Contact</a></li><li><a href=\"#contact\" onclick=\"closeMobileSylva()\" style=\"color:#D4A853\">Devis Gratuit</a></li></ul></div>\r\n<script>\r\n  var nav = document.getElementById(\'navbarSylva\');\r\n  window.addEventListener(\'scroll\', function() { if (nav) nav.classList.toggle(\'scrolled\', window.scrollY > 60); });\r\n  var hamburger = document.getElementById(\'hamburgerSylva\');\r\n  var mobileNav = document.getElementById(\'mobileNavSylva\');\r\n  if (hamburger && mobileNav) { hamburger.addEventListener(\'click\', function() { mobileNav.classList.toggle(\'open\'); document.body.style.overflow = mobileNav.classList.contains(\'open\') ? \'hidden\' : \'\'; }); }\r\n  window.closeMobileSylva = function() { if (mobileNav) mobileNav.classList.remove(\'open\'); document.body.style.overflow = \'\'; };\r\n</script>', '.nav-sylva {\r\n    position: fixed; top: 0; left: 0; right: 0; z-index: 1000;\r\n    padding: 24px 60px;\r\n    display: flex; align-items: center; justify-content: space-between;\r\n    transition: background 0.4s, padding 0.4s;\r\n  }\r\n  .nav-sylva.scrolled { background: rgba(26,17,9,0.92); backdrop-filter: blur(18px); padding: 16px 60px; border-bottom: 1px solid rgba(139,94,60,0.3); }\r\n  .nav-logo-sylva {\r\n    font-family: \'Playfair Display\', serif; font-size: 28px; font-weight: 900; letter-spacing: 4px;\r\n    color: #FDFAF6; text-decoration: none; display: flex; align-items: center; gap: 12px;\r\n  }\r\n  .nav-logo-sylva span { color: #D4A853; }\r\n  .logo-icon-sylva { width: 36px; height: 36px; border: 2px solid #D4A853; display: flex; align-items: center; justify-content: center; }\r\n  .logo-icon-sylva svg { width: 20px; height: 20px; fill: #D4A853; }\r\n  .nav-links-sylva { display: flex; gap: 36px; list-style: none; }\r\n  .nav-links-sylva a { font-family: \'Barlow Condensed\', sans-serif; font-size: 13px; font-weight: 500; letter-spacing: 2px; text-transform: uppercase; color: rgba(255,255,255,0.75); text-decoration: none; transition: color 0.2s; position: relative; }\r\n  .nav-links-sylva a::after { content: \'\'; position: absolute; bottom: -4px; left: 0; width: 0; height: 1px; background: #D4A853; transition: width 0.3s; }\r\n  .nav-links-sylva a:hover { color: #D4A853; }\r\n  .nav-links-sylva a:hover::after { width: 100%; }\r\n  .nav-cta-sylva { font-family: \'Barlow Condensed\', sans-serif; font-size: 13px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: #1A1109; background: #D4A853; padding: 10px 24px; text-decoration: none; transition: background 0.2s; }\r\n  .nav-cta-sylva:hover { background: #C4956A; }\r\n  .nav-hamburger-sylva { display: none; background: none; border: none; flex-direction: column; gap: 5px; padding: 4px; }\r\n  .ham-line-sylva { width: 24px; height: 2px; background: #FDFAF6; }\r\n  .mobile-nav-sylva { display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: #1A1109; z-index: 999; padding: 100px 30px 40px; overflow-y: auto; }\r\n  .mobile-nav-sylva.open { display: block; }\r\n  .mobile-nav-links-sylva { list-style: none; }\r\n  .mobile-nav-links-sylva li { border-bottom: 1px solid rgba(255,255,255,0.1); }\r\n  .mobile-nav-links-sylva a { display: block; padding: 18px 0; font-family: \'Barlow Condensed\', sans-serif; font-size: 16px; letter-spacing: 2px; text-transform: uppercase; color: #FDFAF6; text-decoration: none; }\r\n  @media (max-width: 900px) { .nav-sylva { padding: 20px 30px; } .nav-links-sylva, .nav-cta-sylva { display: none; } .nav-hamburger-sylva { display: flex; } }', NULL, NULL, 'Header', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 10:43:12', '2026-06-06 10:45:52'),
(228, NULL, 'Hero', 'hero', NULL, NULL, 'fa-cube', '<section class=\"hero-sylva\" id=\"hero\">\r\n  <div class=\"hero-bg-sylva\" id=\"heroBgSylva\"></div>\r\n  <div class=\"hero-overlay-sylva\"></div>\r\n  <div class=\"hero-content-sylva\">\r\n    <div class=\"hero-tag-sylva\">Construction Bois d\'Exception</div>\r\n    <h1>L\'Art du <em>Bois</em><br>À l\'État Pur</h1>\r\n    <p class=\"hero-desc-sylva\">Maisons en ossature bois, chalets alpins et structures bois sur mesure. Nous bâtissons vos rêves avec le respect du vivant et l\'exigence de l\'excellence.</p>\r\n    <div class=\"hero-btns-sylva\"><a href=\"#projets\" class=\"btn-primary-sylva\">Voir nos Réalisations <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/><polyline points=\"12,5 19,12 12,19\"/></svg></a><a href=\"#contact\" class=\"btn-secondary-sylva\">Demander un Devis</a></div>\r\n  </div>\r\n  <div class=\"hero-stats-sylva\"><div class=\"hero-stat-sylva\"><div class=\"num\">380+</div><div class=\"lbl\">Projets Livrés</div></div><div class=\"hero-stat-sylva\"><div class=\"num\">22</div><div class=\"lbl\">Ans d\'Expertise</div></div><div class=\"hero-stat-sylva\"><div class=\"num\">98%</div><div class=\"lbl\">Clients Satisfaits</div></div></div>\r\n  <div class=\"hero-scroll-sylva\">Défiler</div>\r\n</section>\r\n<script>window.addEventListener(\'scroll\', function() { var y = window.scrollY; var heroBg = document.getElementById(\'heroBgSylva\'); if (heroBg) heroBg.style.transform = \'scale(1) translateY(\' + (y * 0.35) + \'px)\'; });</script>', '.hero-sylva { position: relative; height: 100vh; min-height: 700px; display: flex; align-items: flex-end; overflow: hidden; }\r\n  .hero-bg-sylva { position: absolute; inset: 0; background-image: url(\'https://images.unsplash.com/photo-1589129140837-67287c22521b?w=1800&q=90\'); background-size: cover; background-position: center; transform: scale(1.08); animation: heroZoomSylva 12s ease-out forwards; }\r\n  @keyframes heroZoomSylva { from { transform: scale(1.08); } to { transform: scale(1); } }\r\n  .hero-overlay-sylva { position: absolute; inset: 0; background: linear-gradient(to bottom, rgba(26,17,9,0.15) 0%, rgba(26,17,9,0.05) 30%, rgba(26,17,9,0.6) 70%, rgba(26,17,9,0.92) 100%); }\r\n  .hero-content-sylva { position: relative; z-index: 2; padding: 0 60px 80px; max-width: 900px; }\r\n  .hero-tag-sylva { font-family: \'Barlow Condensed\', sans-serif; font-size: 12px; font-weight: 500; letter-spacing: 4px; text-transform: uppercase; color: #D4A853; margin-bottom: 20px; display: flex; align-items: center; gap: 14px; opacity: 0; animation: fadeUpSylva 0.8s 0.3s forwards; }\r\n  .hero-tag-sylva::before { content: \'\'; width: 40px; height: 1px; background: #D4A853; }\r\n  .hero-sylva h1 { font-family: \'Playfair Display\', serif; font-size: clamp(52px, 7vw, 90px); font-weight: 900; line-height: 1.0; color: #FDFAF6; margin-bottom: 28px; opacity: 0; animation: fadeUpSylva 0.8s 0.5s forwards; }\r\n  .hero-sylva h1 em { font-style: italic; color: #D4A853; }\r\n  .hero-desc-sylva { font-size: 17px; font-weight: 300; line-height: 1.7; color: rgba(255,255,255,0.75); max-width: 520px; margin-bottom: 44px; opacity: 0; animation: fadeUpSylva 0.8s 0.7s forwards; }\r\n  .hero-btns-sylva { display: flex; gap: 16px; flex-wrap: wrap; opacity: 0; animation: fadeUpSylva 0.8s 0.9s forwards; }\r\n  .btn-primary-sylva { font-family: \'Barlow Condensed\', sans-serif; font-size: 13px; font-weight: 600; letter-spacing: 2.5px; text-transform: uppercase; color: #1A1109; background: #D4A853; padding: 16px 36px; text-decoration: none; transition: background 0.25s; display: inline-flex; align-items: center; gap: 10px; }\r\n  .btn-primary-sylva:hover { background: #e5b96a; }\r\n  .btn-secondary-sylva { font-family: \'Barlow Condensed\', sans-serif; font-size: 13px; font-weight: 500; letter-spacing: 2.5px; text-transform: uppercase; color: #FDFAF6; border: 1px solid rgba(255,255,255,0.4); padding: 16px 36px; text-decoration: none; transition: border-color 0.25s; }\r\n  .btn-secondary-sylva:hover { border-color: #D4A853; background: rgba(212,168,83,0.1); }\r\n  .hero-stats-sylva { position: absolute; right: 60px; bottom: 80px; z-index: 2; display: flex; flex-direction: column; gap: 30px; opacity: 0; animation: fadeLeftSylva 0.8s 1.1s forwards; }\r\n  .hero-stat-sylva { text-align: right; }\r\n  .hero-stat-sylva .num { font-family: \'Playfair Display\', serif; font-size: 42px; font-weight: 700; color: #D4A853; line-height: 1; }\r\n  .hero-stat-sylva .lbl { font-family: \'Barlow Condensed\', sans-serif; font-size: 11px; font-weight: 400; letter-spacing: 2px; text-transform: uppercase; color: rgba(255,255,255,0.55); }\r\n  .hero-scroll-sylva { position: absolute; left: 60px; bottom: 40px; z-index: 2; display: flex; align-items: center; gap: 12px; font-family: \'Barlow Condensed\', sans-serif; font-size: 11px; letter-spacing: 3px; text-transform: uppercase; color: rgba(255,255,255,0.45); writing-mode: vertical-rl; animation: fadeInSylva 1s 1.5s both; }\r\n  .hero-scroll-sylva::before { content: \'\'; width: 1px; height: 50px; background: rgba(255,255,255,0.25); animation: scrollLineSylva 2s 2s infinite; }\r\n  @keyframes scrollLineSylva { 0% { transform: scaleY(0); transform-origin: top; } 50% { transform: scaleY(1); transform-origin: top; } 51% { transform: scaleY(1); transform-origin: bottom; } 100% { transform: scaleY(0); transform-origin: bottom; } }\r\n  @keyframes fadeUpSylva { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }\r\n  @keyframes fadeLeftSylva { from { opacity: 0; transform: translateX(30px); } to { opacity: 1; transform: translateX(0); } }\r\n  @keyframes fadeInSylva { from { opacity: 0; } to { opacity: 1; } }\r\n  @media (max-width: 900px) { .hero-content-sylva { padding: 0 30px 70px; } .hero-stats-sylva { right: 30px; bottom: 70px; } }\r\n  @media (max-width: 600px) { .hero-sylva h1 { font-size: 40px; } .hero-stats-sylva { display: none; } }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-06 10:44:15', '2026-07-25 19:48:00'),
(229, NULL, 'Service', 'service', NULL, NULL, 'fa-cube', '<section class=\"services-sylva\" id=\"services\">\r\n  <div class=\"services-intro-sylva\"><div class=\"section-label-sylva\">Nos Expertises</div><h2 class=\"section-title-sylva\">Des Constructions <em>Pensées</em> pour Durer</h2><p>De la maison contemporaine en ossature bois au chalet de montagne traditionnel, chaque projet est une œuvre unique façonnée avec passion et savoir-faire.</p></div>\r\n  <div class=\"services-grid-sylva\">\r\n    <div class=\"service-card-sylva\"><div class=\"service-img-sylva\" style=\"background-image:url(\'https://plus.unsplash.com/premium_photo-1684348962314-64fa628992f0?w=800&q=80\')\"></div><div class=\"service-overlay-sylva\"><div class=\"service-num-sylva\">01</div><h3 class=\"service-name-sylva\">Maisons en Ossature Bois</h3><p class=\"service-desc-sylva\">Construction complète de maisons individuelles avec ossature bois CLT ou Douglas. Performances thermiques exceptionnelles, délais réduits.</p></div><div class=\"service-arrow-sylva\">→</div></div>\r\n    <div class=\"service-card-sylva\"><div class=\"service-img-sylva\" style=\"background-image:url(\'https://plus.unsplash.com/premium_photo-1687710306899-10a3bfcacf9b?w=700&q=80\')\"></div><div class=\"service-overlay-sylva\"><div class=\"service-num-sylva\">02</div><h3 class=\"service-name-sylva\">Chalets Alpins</h3><p class=\"service-desc-sylva\">Chalets traditionnels et contemporains en vieux bois et épicéa massif. L\'authenticité montagnarde réinterprétée.</p></div><div class=\"service-arrow-sylva\">→</div></div>\r\n    <div class=\"service-card-sylva\"><div class=\"service-img-sylva\" style=\"background-image:url(\'https://images.unsplash.com/photo-1575403071235-5dcd06cbf169?w=700&q=80\')\"></div><div class=\"service-overlay-sylva\"><div class=\"service-num-sylva\">03</div><h3 class=\"service-name-sylva\">Extensions & Surélévations</h3><p class=\"service-desc-sylva\">Agrandissement de votre espace de vie avec des structures bois légères et durables, s\'intégrant parfaitement à l\'existant.</p></div><div class=\"service-arrow-sylva\">→</div></div>\r\n    <div class=\"service-card-sylva\"><div class=\"service-img-sylva\" style=\"background-image:url(\'https://images.unsplash.com/photo-1704902949428-65e05241291a?w=700&q=80\')\"></div><div class=\"service-overlay-sylva\"><div class=\"service-num-sylva\">04</div><h3 class=\"service-name-sylva\">Terrasses & Aménagements</h3><p class=\"service-desc-sylva\">Terrasses en bois exotique ou naturel, pergolas, carports et mobilier extérieur sur mesure.</p></div><div class=\"service-arrow-sylva\">→</div></div>\r\n    <div class=\"service-card-sylva\"><div class=\"service-img-sylva\" style=\"background-image:url(\'https://plus.unsplash.com/premium_photo-1687996106455-b391358404bf?w=700&q=80\')\"></div><div class=\"service-overlay-sylva\"><div class=\"service-num-sylva\">05</div><h3 class=\"service-name-sylva\">Aménagement Intérieur</h3><p class=\"service-desc-sylva\">Menuiserie sur mesure, escaliers bois, parquets massifs et bibliothèques intégrées pour sublimer chaque pièce.</p></div><div class=\"service-arrow-sylva\">→</div></div>\r\n  </div>\r\n</section>', '.services-sylva { background: #FDFAF6; padding: 110px 60px; }\r\n  .services-intro-sylva { max-width: 580px; margin-bottom: 70px; }\r\n  .services-intro-sylva p { font-size: 17px; font-weight: 300; color: #7A7269; line-height: 1.8; margin-top: 20px; }\r\n  .services-grid-sylva { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2px; }\r\n  .service-card-sylva { position: relative; overflow: hidden; aspect-ratio: 3/4; cursor: pointer; }\r\n  .service-card-sylva:first-child { aspect-ratio: auto; grid-row: span 2; }\r\n  .service-img-sylva { width: 100%; height: 100%; background-size: cover; background-position: center; transition: transform 0.7s; }\r\n  .service-card-sylva:hover .service-img-sylva { transform: scale(1.07); }\r\n  .service-overlay-sylva { position: absolute; inset: 0; background: linear-gradient(to top, rgba(26,17,9,0.85) 0%, rgba(26,17,9,0) 60%); display: flex; flex-direction: column; justify-content: flex-end; padding: 32px; }\r\n  .service-num-sylva { font-family: \'Barlow Condensed\', sans-serif; font-size: 11px; letter-spacing: 3px; color: #D4A853; margin-bottom: 10px; }\r\n  .service-name-sylva { font-family: \'Playfair Display\', serif; font-size: 22px; font-weight: 700; color: #FDFAF6; margin-bottom: 8px; }\r\n  .service-card-sylva:first-child .service-name-sylva { font-size: 32px; }\r\n  .service-desc-sylva { font-size: 13px; font-weight: 300; color: rgba(255,255,255,0.65); line-height: 1.6; max-height: 0; overflow: hidden; transition: max-height 0.4s, opacity 0.4s; opacity: 0; }\r\n  .service-card-sylva:hover .service-desc-sylva { max-height: 80px; opacity: 1; }\r\n  .service-arrow-sylva { position: absolute; top: 24px; right: 24px; width: 40px; height: 40px; border: 1px solid rgba(255,255,255,0.3); display: flex; align-items: center; justify-content: center; color: #FDFAF6; font-size: 18px; transition: background 0.3s; }\r\n  .service-card-sylva:hover .service-arrow-sylva { background: #D4A853; border-color: #D4A853; }\r\n  @media (max-width: 1100px) { .services-grid-sylva { grid-template-columns: 1fr 1fr; } .service-card-sylva:first-child { grid-column: span 2; aspect-ratio: 16/7; } }\r\n  @media (max-width: 900px) { .services-sylva { padding: 80px 30px; } }\r\n  @media (max-width: 600px) { .services-grid-sylva { grid-template-columns: 1fr; } .service-card-sylva:first-child { grid-column: span 1; } }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 10:45:02', '2026-06-06 10:45:02'),
(230, NULL, 'About', 'about-5', NULL, NULL, 'fa-cube', '<section class=\"about-sylva\" id=\"about\">\r\n  <div class=\"about-inner-sylva\">\r\n    <div class=\"about-images-sylva\"><div class=\"about-img-main-sylva\"></div><div class=\"about-img-badge-sylva\"><div class=\"big\">22</div><div class=\"small\">Années<br>d\'Excellence</div></div></div>\r\n    <div class=\"about-content-sylva reveal-sylva\"><div class=\"section-label-sylva\">Notre Histoire</div><h2 class=\"section-title-sylva\">L\'Âme du Bois dans <em>Chaque</em> Construction</h2><p class=\"about-text-sylva\">Fondée en 2003 au cœur des Alpes, SYLVA s\'est imposée comme la référence en construction bois haut de gamme. Nous sélectionnons méticuleusement chaque essence, travaillons avec des artisans passionnés et respectons scrupuleusement l\'environnement dans lequel nos projets s\'inscrivent.<br><br>Notre philosophie : conjuguer tradition charpentière et innovation architecturale pour créer des espaces de vie d\'exception, durables et vivants.</p><div class=\"about-values-sylva\"><div class=\"about-value-sylva\"><h4>Bois Certifié</h4><p>100% de nos bois proviennent de forêts gérées durablement, certifiées PEFC et FSC.</p></div><div class=\"about-value-sylva\"><h4>Sur Mesure</h4><p>Chaque projet est unique. Aucun plan standardisé, chaque détail est pensé pour vous.</p></div><div class=\"about-value-sylva\"><h4>Garantie Décennale</h4><p>Toutes nos constructions sont couvertes par notre assurance décennale complète.</p></div><div class=\"about-value-sylva\"><h4>Basse Consommation</h4><p>Nos maisons respectent les normes BBC et RT2020, pour votre confort et l\'environnement.</p></div></div></div>\r\n  </div>\r\n</section>', '.about-sylva { background: #1A1109; padding: 120px 0; }\r\n  .about-inner-sylva { display: grid; grid-template-columns: 1fr 1fr; min-height: 600px; }\r\n  .about-images-sylva { position: relative; overflow: hidden; }\r\n  .about-img-main-sylva { width: 100%; height: 100%; background-image: url(\'https://plus.unsplash.com/premium_photo-1687710306899-10a3bfcacf9b?w=900&q=80\'); background-size: cover; background-position: center; }\r\n  .about-img-badge-sylva { position: absolute; bottom: 50px; right: -30px; width: 190px; height: 190px; background: #D4A853; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 20px; z-index: 2; }\r\n  .about-img-badge-sylva .big { font-family: \'Playfair Display\', serif; font-size: 54px; font-weight: 900; color: #1A1109; line-height: 1; }\r\n  .about-img-badge-sylva .small { font-family: \'Barlow Condensed\', sans-serif; font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: #1A1109; margin-top: 6px; line-height: 1.4; }\r\n  .about-content-sylva { padding: 80px 80px 80px 70px; display: flex; flex-direction: column; justify-content: center; }\r\n  .about-content-sylva .section-label-sylva { color: #D4A853; }\r\n  .about-content-sylva .section-label-sylva::before { background: #D4A853; }\r\n  .about-content-sylva .section-title-sylva { color: #FDFAF6; }\r\n  .about-text-sylva { font-size: 16px; font-weight: 300; color: rgba(255,255,255,0.6); line-height: 1.9; margin: 24px 0 40px; }\r\n  .about-values-sylva { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }\r\n  .about-value-sylva { border-left: 2px solid #8B5E3C; padding-left: 16px; }\r\n  .about-value-sylva h4 { font-family: \'Barlow Condensed\', sans-serif; font-size: 13px; font-weight: 600; letter-spacing: 1.5px; text-transform: uppercase; color: #D4A853; margin-bottom: 6px; }\r\n  .about-value-sylva p { font-size: 13px; font-weight: 300; color: rgba(255,255,255,0.5); line-height: 1.6; }\r\n  @media (max-width: 900px) { .about-inner-sylva { grid-template-columns: 1fr; } .about-img-badge-sylva { right: 20px; } .about-content-sylva { padding: 60px 30px; } }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-06 10:45:42', '2026-07-25 19:47:51'),
(231, NULL, 'Process', 'process-2', NULL, NULL, 'fa-cube', '<section class=\"process-block-sylva\" id=\"process\">\r\n  <div class=\"process-header-block-sylva\">\r\n    <div class=\"process-label-block-sylva\">Comment ça marche</div>\r\n    <h2 class=\"process-title-block-sylva\">De l\'Idée à la <em>Réalité</em></h2>\r\n  </div>\r\n  <div class=\"steps-grid-block-sylva\">\r\n    <div class=\"step-card-block-sylva\"><div class=\"step-number-block-sylva\">01</div><div class=\"step-title-block-sylva\">Consultation</div><div class=\"step-desc-block-sylva\">Réunion initiale pour comprendre vos besoins, votre style de vie et votre budget.</div></div>\r\n    <div class=\"step-card-block-sylva\"><div class=\"step-number-block-sylva\">02</div><div class=\"step-title-block-sylva\">Conception</div><div class=\"step-desc-block-sylva\">Nos architectes créent les plans et modélisations 3D de votre futur chez-vous.</div></div>\r\n    <div class=\"step-card-block-sylva\"><div class=\"step-number-block-sylva\">03</div><div class=\"step-title-block-sylva\">Validation & Devis</div><div class=\"step-desc-block-sylva\">Devis détaillé et transparent, ajustements selon vos retours.</div></div>\r\n    <div class=\"step-card-block-sylva\"><div class=\"step-number-block-sylva\">04</div><div class=\"step-title-block-sylva\">Construction</div><div class=\"step-desc-block-sylva\">Fabrication en atelier et assemblage sur site par nos maîtres charpentiers.</div></div>\r\n    <div class=\"step-card-block-sylva\"><div class=\"step-number-block-sylva\">05</div><div class=\"step-title-block-sylva\">Livraison</div><div class=\"step-desc-block-sylva\">Remise des clés avec visite complète et suivi post-livraison garanti.</div></div>\r\n  </div>\r\n</section>', '.process-block-sylva {\r\n    background: #F0E8DC;\r\n    padding: 110px 60px;\r\n  }\r\n  .process-header-block-sylva {\r\n    text-align: center;\r\n    margin-bottom: 80px;\r\n  }\r\n  .process-label-block-sylva {\r\n    font-family: \'Barlow Condensed\', sans-serif;\r\n    font-size: 11px;\r\n    font-weight: 500;\r\n    letter-spacing: 4px;\r\n    text-transform: uppercase;\r\n    color: #8B5E3C;\r\n    margin-bottom: 16px;\r\n    display: inline-block;\r\n  }\r\n  .process-title-block-sylva {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: clamp(36px, 4.5vw, 58px);\r\n    font-weight: 700;\r\n    line-height: 1.15;\r\n    color: #1A1109;\r\n  }\r\n  .process-title-block-sylva em {\r\n    font-style: italic;\r\n    color: #8B5E3C;\r\n  }\r\n  .steps-grid-block-sylva {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    gap: 20px;\r\n    flex-wrap: wrap;\r\n    margin-top: 60px;\r\n  }\r\n  .step-card-block-sylva {\r\n    flex: 1;\r\n    min-width: 180px;\r\n    text-align: center;\r\n    padding: 0 15px;\r\n  }\r\n  .step-number-block-sylva {\r\n    width: 60px;\r\n    height: 60px;\r\n    background: #FDFAF6;\r\n    border: 2px solid #8B5E3C;\r\n    border-radius: 50%;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 22px;\r\n    font-weight: 700;\r\n    color: #8B5E3C;\r\n    margin: 0 auto 20px;\r\n  }\r\n  .step-title-block-sylva {\r\n    font-family: \'Barlow Condensed\', sans-serif;\r\n    font-size: 18px;\r\n    font-weight: 600;\r\n    letter-spacing: 1px;\r\n    text-transform: uppercase;\r\n    color: #1A1109;\r\n    margin-bottom: 10px;\r\n  }\r\n  .step-desc-block-sylva {\r\n    font-size: 14px;\r\n    color: #7A7269;\r\n    line-height: 1.6;\r\n  }\r\n  @media (max-width: 900px) {\r\n    .process-block-sylva { padding: 80px 30px; }\r\n    .steps-grid-block-sylva { flex-direction: column; align-items: center; }\r\n    .step-card-block-sylva { max-width: 300px; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-06 10:47:10', '2026-06-06 11:12:26'),
(232, NULL, 'PROJETS (GALERIE)', 'projets-galerie', NULL, NULL, 'fa-cube', '<section class=\"projets-sylva\" id=\"projets\"><div class=\"projets-header-sylva reveal-sylva\"><div><div class=\"section-label-sylva\">Portfolio</div><h2 class=\"section-title-sylva\">Nos <em>Réalisations</em></h2></div><a href=\"#\" class=\"projets-link-sylva\">Voir tout le portfolio →</a></div><div class=\"filter-btns-sylva\"><button class=\"filter-btn-sylva active\" data-filter=\"all\">Tous</button><button class=\"filter-btn-sylva\" data-filter=\"chalet\">Chalets</button><button class=\"filter-btn-sylva\" data-filter=\"maison\">Maisons</button><button class=\"filter-btn-sylva\" data-filter=\"extension\">Extensions</button><button class=\"filter-btn-sylva\" data-filter=\"amenagement\">Aménagements</button></div><div class=\"projets-masonry-sylva\"><div class=\"projet-card-sylva\" data-cat=\"chalet\"><img class=\"projet-img-sylva\" src=\"https://plus.unsplash.com/premium_photo-1684348962314-64fa628992f0?w=900&q=80\"><div class=\"projet-info-sylva\"><div class=\"projet-cat-sylva\">Chalet</div><div class=\"projet-name-sylva\">Chalet La Cime</div><div class=\"projet-loc-sylva\">📍 Megève, Haute-Savoie</div></div></div><div class=\"projet-card-sylva\" data-cat=\"maison\"><img class=\"projet-img-sylva\" src=\"https://images.unsplash.com/photo-1704902949428-65e05241291a?w=600&q=80\"><div class=\"projet-info-sylva\"><div class=\"projet-cat-sylva\">Maison</div><div class=\"projet-name-sylva\">Villa Forêt Noire</div><div class=\"projet-loc-sylva\">📍 Annecy, Haute-Savoie</div></div></div><div class=\"projet-card-sylva\" data-cat=\"extension\"><img class=\"projet-img-sylva\" src=\"https://plus.unsplash.com/premium_photo-1682148150953-95f64cbe92ae?w=600&q=80\"><div class=\"projet-info-sylva\"><div class=\"projet-cat-sylva\">Extension</div><div class=\"projet-name-sylva\">Extension Les Pins</div><div class=\"projet-loc-sylva\">📍 Grenoble, Isère</div></div></div><div class=\"projet-card-sylva\" data-cat=\"amenagement\"><img class=\"projet-img-sylva\" src=\"https://images.unsplash.com/photo-1575403071235-5dcd06cbf169?w=600&q=80\"><div class=\"projet-info-sylva\"><div class=\"projet-cat-sylva\">Aménagement</div><div class=\"projet-name-sylva\">Terrasse Panoramique</div><div class=\"projet-loc-sylva\">📍 Chamonix</div></div></div><div class=\"projet-card-sylva\" data-cat=\"chalet\"><img class=\"projet-img-sylva\" src=\"https://images.unsplash.com/photo-1587913560680-7f8187bf9634?w=600&q=80\"><div class=\"projet-info-sylva\"><div class=\"projet-cat-sylva\">Chalet</div><div class=\"projet-name-sylva\">Chalet Sapin Blanc</div><div class=\"projet-loc-sylva\">📍 Val d\'Isère</div></div></div><div class=\"projet-card-sylva\" data-cat=\"maison\"><img class=\"projet-img-sylva\" src=\"https://plus.unsplash.com/premium_photo-1687996106455-b391358404bf?w=600&q=80\"><div class=\"projet-info-sylva\"><div class=\"projet-cat-sylva\">Maison</div><div class=\"projet-name-sylva\">Maison Hêtre</div><div class=\"projet-loc-sylva\">📍 Lyon, Rhône</div></div></div></div></section>\r\n<script>\r\n  var filterBtns = document.querySelectorAll(\'.filter-btn-sylva\');\r\n  filterBtns.forEach(function(btn) { btn.addEventListener(\'click\', function() { filterBtns.forEach(function(b) { b.classList.remove(\'active\'); }); btn.classList.add(\'active\'); var filter = btn.dataset.filter; document.querySelectorAll(\'.projet-card-sylva\').forEach(function(card) { card.classList.toggle(\'hide\', filter !== \'all\' && card.dataset.cat !== filter); }); }); });\r\n</script>', '.projets-sylva { background: #FDFAF6; padding: 110px 60px; }\r\n  .projets-header-sylva { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 50px; }\r\n  .projets-link-sylva { font-family: \'Barlow Condensed\', sans-serif; font-size: 13px; font-weight: 500; letter-spacing: 2px; text-transform: uppercase; color: #8B5E3C; text-decoration: none; display: flex; align-items: center; gap: 10px; border-bottom: 1px solid #C4956A; padding-bottom: 4px; }\r\n  .filter-btns-sylva { display: flex; gap: 8px; margin-bottom: 40px; }\r\n  .filter-btn-sylva { font-family: \'Barlow Condensed\', sans-serif; font-size: 12px; font-weight: 500; letter-spacing: 2px; text-transform: uppercase; padding: 8px 20px; border: 1px solid #C4956A; background: transparent; color: #7A7269; transition: all 0.25s; cursor: pointer; }\r\n  .filter-btn-sylva.active, .filter-btn-sylva:hover { background: #8B5E3C; color: #FDFAF6; border-color: #8B5E3C; }\r\n  .projets-masonry-sylva { display: grid; grid-template-columns: repeat(12, 1fr); gap: 16px; }\r\n  .projet-card-sylva { position: relative; overflow: hidden; transition: opacity 0.4s; }\r\n  .projet-card-sylva:nth-child(1) { grid-column: span 7; grid-row: span 2; aspect-ratio: 16/11; }\r\n  .projet-card-sylva:nth-child(2) { grid-column: span 5; aspect-ratio: 4/3; }\r\n  .projet-card-sylva:nth-child(3) { grid-column: span 5; aspect-ratio: 4/3; }\r\n  .projet-card-sylva:nth-child(4) { grid-column: span 4; aspect-ratio: 1/1; }\r\n  .projet-card-sylva:nth-child(5) { grid-column: span 4; aspect-ratio: 1/1; }\r\n  .projet-card-sylva:nth-child(6) { grid-column: span 4; aspect-ratio: 1/1; }\r\n  .projet-card-sylva.hide { opacity: 0; pointer-events: none; }\r\n  .projet-img-sylva { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform 0.7s; }\r\n  .projet-card-sylva:hover .projet-img-sylva { transform: scale(1.06); }\r\n  .projet-info-sylva { position: absolute; inset: 0; background: linear-gradient(to top, rgba(26,17,9,0.9) 0%, transparent 50%); display: flex; flex-direction: column; justify-content: flex-end; padding: 28px; opacity: 0; transition: opacity 0.4s; }\r\n  .projet-card-sylva:hover .projet-info-sylva { opacity: 1; }\r\n  .projet-cat-sylva { font-family: \'Barlow Condensed\', sans-serif; font-size: 11px; letter-spacing: 3px; text-transform: uppercase; color: #D4A853; margin-bottom: 6px; }\r\n  .projet-name-sylva { font-family: \'Playfair Display\', serif; font-size: 22px; font-weight: 700; color: #FDFAF6; }\r\n  .projet-loc-sylva { font-size: 13px; color: rgba(255,255,255,0.6); margin-top: 4px; }\r\n  @media (max-width: 900px) { .projets-sylva { padding: 80px 30px; } .projets-masonry-sylva { grid-template-columns: repeat(6, 1fr); } .projet-card-sylva:nth-child(1) { grid-column: span 6; aspect-ratio: 16/9; grid-row: auto; } .projet-card-sylva:nth-child(n+2) { grid-column: span 3; aspect-ratio: 4/3; } }\r\n  @media (max-width: 600px) { .projet-card-sylva:nth-child(n+2) { grid-column: span 6; } }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 10:49:57', '2026-06-06 10:49:57'),
(233, NULL, 'Matériaux', 'materiaux', NULL, NULL, 'fa-cube', '<section class=\"materiaux-block-sylva\" id=\"materiaux\">\r\n  <div class=\"materiaux-header-block-sylva\">\r\n    <div class=\"materiaux-label-block-sylva\">Nos Matériaux</div>\r\n    <h2 class=\"materiaux-title-block-sylva\">Le Bois dans <em>Toute</em> sa Noblesse</h2>\r\n  </div>\r\n  <div class=\"mat-grid-block-sylva\">\r\n    <div class=\"mat-card-block-sylva\"><div class=\"mat-icon-block-sylva\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"/><path d=\"M2 17l10 5 10-5\"/><path d=\"M2 12l10 5 10-5\"/></svg></div><h3>Douglas</h3><p>Bois structurel par excellence, le Douglas offre une résistance mécanique exceptionnelle et une belle teinte rougeâtre.</p><div class=\"mat-tags-block-sylva\"><span class=\"mat-tag-block-sylva\">Ossature</span><span class=\"mat-tag-block-sylva\">Bardage</span><span class=\"mat-tag-block-sylva\">Charpente</span></div></div>\r\n    <div class=\"mat-card-block-sylva\"><div class=\"mat-icon-block-sylva\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 8v8M8 12h8\"/></svg></div><h3>CLT / Bois Lamellé</h3><p>Le Cross Laminated Timber révolutionne la construction moderne. Résistance sismique et isolation phonique supérieure.</p><div class=\"mat-tags-block-sylva\"><span class=\"mat-tag-block-sylva\">Planchers</span><span class=\"mat-tag-block-sylva\">Murs</span><span class=\"mat-tag-block-sylva\">Toiture</span></div></div>\r\n    <div class=\"mat-card-block-sylva\"><div class=\"mat-icon-block-sylva\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 3h18v18H3z\"/><path d=\"M3 9h18M3 15h18M9 3v18M15 3v18\"/></svg></div><h3>Épicéa Massif</h3><p>L\'essence traditionnelle des chalets alpins. Léger, résistant et doté d\'une excellente isolation thermique naturelle.</p><div class=\"mat-tags-block-sylva\"><span class=\"mat-tag-block-sylva\">Chalets</span><span class=\"mat-tag-block-sylva\">Parquet</span><span class=\"mat-tag-block-sylva\">Lambris</span></div></div>\r\n    <div class=\"mat-card-block-sylva\"><div class=\"mat-icon-block-sylva\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></div><h3>Chêne & Châtaignier</h3><p>Essences nobles pour les finitions intérieures et extérieures haut de gamme. Durabilité naturelle exceptionnelle.</p><div class=\"mat-tags-block-sylva\"><span class=\"mat-tag-block-sylva\">Menuiserie</span><span class=\"mat-tag-block-sylva\">Escaliers</span><span class=\"mat-tag-block-sylva\">Terrasses</span></div></div>\r\n  </div>\r\n</section>', '.materiaux-block-sylva {\r\n    background: #F0E8DC;\r\n    padding: 110px 60px;\r\n  }\r\n  .materiaux-header-block-sylva {\r\n    margin-bottom: 60px;\r\n  }\r\n  .materiaux-label-block-sylva {\r\n    font-family: \'Barlow Condensed\', sans-serif;\r\n    font-size: 11px;\r\n    font-weight: 500;\r\n    letter-spacing: 4px;\r\n    text-transform: uppercase;\r\n    color: #8B5E3C;\r\n    margin-bottom: 16px;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 14px;\r\n  }\r\n  .materiaux-label-block-sylva::before {\r\n    content: \'\';\r\n    width: 30px;\r\n    height: 1px;\r\n    background: #8B5E3C;\r\n  }\r\n  .materiaux-title-block-sylva {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: clamp(36px, 4.5vw, 58px);\r\n    font-weight: 700;\r\n    line-height: 1.15;\r\n    color: #1A1109;\r\n  }\r\n  .materiaux-title-block-sylva em {\r\n    font-style: italic;\r\n    color: #8B5E3C;\r\n  }\r\n  .mat-grid-block-sylva {\r\n    display: grid;\r\n    grid-template-columns: repeat(4, 1fr);\r\n    gap: 24px;\r\n    margin-top: 40px;\r\n  }\r\n  .mat-card-block-sylva {\r\n    background: #FDFAF6;\r\n    padding: 40px 30px;\r\n    border-top: 3px solid transparent;\r\n    transition: all 0.3s;\r\n  }\r\n  .mat-card-block-sylva:hover {\r\n    border-top-color: #8B5E3C;\r\n    transform: translateY(-6px);\r\n    box-shadow: 0 20px 60px rgba(0,0,0,0.1);\r\n  }\r\n  .mat-icon-block-sylva {\r\n    width: 56px;\r\n    height: 56px;\r\n    background: #F0E8DC;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    margin-bottom: 24px;\r\n  }\r\n  .mat-icon-block-sylva svg {\r\n    width: 28px;\r\n    height: 28px;\r\n    stroke: #8B5E3C;\r\n    fill: none;\r\n    stroke-width: 1.5;\r\n  }\r\n  .mat-card-block-sylva h3 {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 20px;\r\n    font-weight: 700;\r\n    color: #1A1109;\r\n    margin-bottom: 12px;\r\n  }\r\n  .mat-card-block-sylva p {\r\n    font-size: 14px;\r\n    font-weight: 300;\r\n    color: #7A7269;\r\n    line-height: 1.7;\r\n  }\r\n  .mat-tags-block-sylva {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    gap: 8px;\r\n    margin-top: 16px;\r\n  }\r\n  .mat-tag-block-sylva {\r\n    font-family: \'Barlow Condensed\', sans-serif;\r\n    font-size: 10px;\r\n    letter-spacing: 1.5px;\r\n    text-transform: uppercase;\r\n    padding: 4px 10px;\r\n    background: #F0E8DC;\r\n    color: #8B5E3C;\r\n  }\r\n  @media (max-width: 1100px) {\r\n    .mat-grid-block-sylva { grid-template-columns: repeat(2, 1fr); }\r\n  }\r\n  @media (max-width: 900px) {\r\n    .materiaux-block-sylva { padding: 80px 30px; }\r\n  }\r\n  @media (max-width: 600px) {\r\n    .mat-grid-block-sylva { grid-template-columns: 1fr; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-06 10:52:17', '2026-06-06 11:13:54'),
(234, NULL, 'chiffres', 'chiffres', NULL, NULL, 'fa-cube', '<section class=\"chiffres-sylva\"><div class=\"chiffres-grid-sylva\"><div class=\"chiffre-item-sylva\"><div class=\"chiffre-num-sylva counter-sylva\" data-target=\"380\">0</div><div class=\"chiffre-lbl-sylva\">Projets Réalisés</div></div><div class=\"chiffre-item-sylva\"><div class=\"chiffre-num-sylva counter-sylva\" data-target=\"22\">0</div><div class=\"chiffre-lbl-sylva\">Années d\'Expérience</div></div><div class=\"chiffre-item-sylva\"><div class=\"chiffre-num-sylva counter-sylva\" data-target=\"48\">0</div><div class=\"chiffre-lbl-sylva\">Artisans Experts</div></div><div class=\"chiffre-item-sylva\"><div class=\"chiffre-num-sylva counter-sylva\" data-target=\"98\">0<span class=\"chiffre-unit-sylva\">%</span></div><div class=\"chiffre-lbl-sylva\">Satisfaction Clients</div></div></div></section>\r\n<script>\r\n  var counterObserver = new IntersectionObserver(function(entries) { entries.forEach(function(entry) { if (!entry.isIntersecting) return; var el = entry.target; var target = parseInt(el.dataset.target); var suffix = el.querySelector(\'.chiffre-unit-sylva\') ? el.querySelector(\'.chiffre-unit-sylva\').outerHTML : \'\'; var start = 0; var step = target / 60; var timer = setInterval(function() { start = Math.min(start + step, target); el.innerHTML = Math.floor(start) + suffix; if (start >= target) clearInterval(timer); }, 20); counterObserver.unobserve(el); }); }, { threshold: 0.5 });\r\n  document.querySelectorAll(\'.counter-sylva\').forEach(function(el) { counterObserver.observe(el); });\r\n</script>', '.chiffres-sylva { background: #D4A853; padding: 90px 60px; }\r\n  .chiffres-grid-sylva { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; background: rgba(0,0,0,0.1); }\r\n  .chiffre-item-sylva { background: #D4A853; padding: 50px 40px; text-align: center; transition: background 0.3s; }\r\n  .chiffre-item-sylva:hover { background: #c9a048; }\r\n  .chiffre-num-sylva { font-family: \'Playfair Display\', serif; font-size: 64px; font-weight: 900; color: #1A1109; line-height: 1; }\r\n  .chiffre-unit-sylva { font-size: 32px; }\r\n  .chiffre-lbl-sylva { font-family: \'Barlow Condensed\', sans-serif; font-size: 13px; font-weight: 500; letter-spacing: 2px; text-transform: uppercase; color: rgba(26,17,9,0.65); margin-top: 10px; }\r\n  @media (max-width: 900px) { .chiffres-sylva { padding: 60px 30px; } .chiffres-grid-sylva { grid-template-columns: repeat(2, 1fr); } }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 10:52:57', '2026-06-06 10:52:57'),
(235, NULL, 'TÉMOIGNAGES', 'temoignages', NULL, NULL, 'fa-cube', '<section class=\"temoignages-sylva\"><div class=\"temoignages-inner-sylva\"><div class=\"section-label-sylva\">Témoignages</div><h2 class=\"section-title-sylva\">Ce que Disent <em>Nos Clients</em></h2><div class=\"temo-card-sylva\"><div class=\"temo-stars-sylva\">★★★★★</div><p class=\"temo-text-sylva\">\"SYLVA a transformé notre rêve de chalet en une réalité qui dépasse toutes nos espérances. Chaque détail a été soigné avec une précision et une passion rares. Nous recommandons sans la moindre réserve.\"</p><div class=\"temo-author-sylva\"><div class=\"temo-avatar-sylva\" style=\"background-image:url(\'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&q=80\')\"></div><div><div class=\"temo-name-sylva\">Marc & Sophie Durand</div><div class=\"temo-role-sylva\">Chalet La Cime — Megève</div></div></div></div><div style=\"margin-top:30px\"><div class=\"temo-card-sylva\"><div class=\"temo-stars-sylva\">★★★★★</div><p class=\"temo-text-sylva\">\"Professionnalisme exemplaire du premier contact jusqu\'à la livraison. Notre maison ossature bois est non seulement magnifique mais aussi incroyablement performante énergétiquement.\"</p><div class=\"temo-author-sylva\"><div class=\"temo-avatar-sylva\" style=\"background-image:url(\'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=100&q=80\')\"></div><div><div class=\"temo-name-sylva\">Isabelle Morel</div><div class=\"temo-role-sylva\">Maison Forêt Noire — Annecy</div></div></div></div></div></div></section>', '.temoignages-sylva { background: #5C3A1E; padding: 120px 0; overflow: hidden; }\r\n  .temoignages-inner-sylva { padding: 0 60px; }\r\n  .temoignages-sylva .section-label-sylva { color: #D4A853; }\r\n  .temoignages-sylva .section-label-sylva::before { background: #D4A853; }\r\n  .temoignages-sylva .section-title-sylva { color: #FDFAF6; margin-bottom: 60px; }\r\n  .temo-card-sylva { background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.1); padding: 50px 44px; transition: background 0.3s; }\r\n  .temo-card-sylva:hover { background: rgba(255,255,255,0.1); }\r\n  .temo-stars-sylva { color: #D4A853; font-size: 16px; margin-bottom: 24px; }\r\n  .temo-text-sylva { font-family: \'Playfair Display\', serif; font-style: italic; font-size: 18px; font-weight: 400; line-height: 1.75; color: rgba(255,255,255,0.85); margin-bottom: 36px; }\r\n  .temo-author-sylva { display: flex; align-items: center; gap: 16px; }\r\n  .temo-avatar-sylva { width: 52px; height: 52px; border-radius: 50%; background-size: cover; background-position: center; border: 2px solid #D4A853; }\r\n  .temo-name-sylva { font-family: \'Barlow Condensed\', sans-serif; font-size: 15px; font-weight: 600; letter-spacing: 1px; color: #FDFAF6; }\r\n  .temo-role-sylva { font-size: 12px; color: rgba(255,255,255,0.45); margin-top: 3px; }\r\n  @media (max-width: 900px) { .temoignages-sylva { padding: 80px 0; } .temoignages-inner-sylva { padding: 0 30px; } }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 10:53:34', '2026-06-06 10:53:34');
INSERT INTO `blocks` (`id`, `categorie_id`, `name`, `slug`, `description`, `thumbnail`, `icon`, `html_content`, `css_content`, `js_content`, `section_id`, `category`, `website_type`, `tags`, `is_responsive`, `is_free`, `width`, `height`, `usage_count`, `views_count`, `rating`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(236, NULL, 'ÉQUIPE', 'equipe', NULL, NULL, 'fa-cube', '<section class=\"equipe-block-sylva\" id=\"equipe\">\r\n  <div class=\"equipe-header-block-sylva\">\r\n    <div class=\"equipe-label-block-sylva\">Notre Équipe</div>\r\n    <h2 class=\"equipe-title-block-sylva\">Des <em>Artisans</em> de Passion</h2>\r\n  </div>\r\n  <div class=\"equipe-grid-block-sylva\">\r\n    <div class=\"membre-card-block-sylva\"><div class=\"membre-photo-block-sylva\"><img src=\"https://plus.unsplash.com/premium_photo-1682148150953-95f64cbe92ae?w=400&q=80\" alt=\"Pierre Martin\"></div><div class=\"membre-name-block-sylva\">Pierre Martin</div><div class=\"membre-role-block-sylva\">Fondateur & Architecte</div></div>\r\n    <div class=\"membre-card-block-sylva\"><div class=\"membre-photo-block-sylva\"><img src=\"https://images.unsplash.com/photo-1587913560680-7f8187bf9634?w=400&q=80\" alt=\"Claire Dubois\"></div><div class=\"membre-name-block-sylva\">Claire Dubois</div><div class=\"membre-role-block-sylva\">Architecte d\'Intérieur</div></div>\r\n    <div class=\"membre-card-block-sylva\"><div class=\"membre-photo-block-sylva\"><img src=\"https://images.unsplash.com/photo-1575403071235-5dcd06cbf169?w=400&q=80\" alt=\"Antoine Bernard\"></div><div class=\"membre-name-block-sylva\">Antoine Bernard</div><div class=\"membre-role-block-sylva\">Maître Charpentier</div></div>\r\n    <div class=\"membre-card-block-sylva\"><div class=\"membre-photo-block-sylva\"><img src=\"https://images.unsplash.com/photo-1589129140837-67287c22521b?w=400&q=80\" alt=\"Lucie Rousseau\"></div><div class=\"membre-name-block-sylva\">Lucie Rousseau</div><div class=\"membre-role-block-sylva\">Responsable Projets</div></div>\r\n  </div>\r\n</section>', '.equipe-block-sylva {\r\n    background: #FDFAF6;\r\n    padding: 110px 60px;\r\n  }\r\n  .equipe-header-block-sylva {\r\n    text-align: center;\r\n    margin-bottom: 70px;\r\n  }\r\n  .equipe-label-block-sylva {\r\n    font-family: \'Barlow Condensed\', sans-serif;\r\n    font-size: 11px;\r\n    font-weight: 500;\r\n    letter-spacing: 4px;\r\n    text-transform: uppercase;\r\n    color: #8B5E3C;\r\n    margin-bottom: 16px;\r\n    display: inline-block;\r\n  }\r\n  .equipe-title-block-sylva {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: clamp(36px, 4.5vw, 58px);\r\n    font-weight: 700;\r\n    line-height: 1.15;\r\n    color: #1A1109;\r\n  }\r\n  .equipe-title-block-sylva em {\r\n    font-style: italic;\r\n    color: #8B5E3C;\r\n  }\r\n  .equipe-grid-block-sylva {\r\n    display: grid;\r\n    grid-template-columns: repeat(4, 1fr);\r\n    gap: 30px;\r\n  }\r\n  .membre-card-block-sylva {\r\n    text-align: center;\r\n  }\r\n  .membre-photo-block-sylva {\r\n    width: 100%;\r\n    aspect-ratio: 1/1;\r\n    overflow: hidden;\r\n    margin-bottom: 20px;\r\n  }\r\n  .membre-photo-block-sylva img {\r\n    width: 100%;\r\n    height: 100%;\r\n    object-fit: cover;\r\n    transition: transform 0.5s;\r\n  }\r\n  .membre-card-block-sylva:hover .membre-photo-block-sylva img {\r\n    transform: scale(1.05);\r\n  }\r\n  .membre-name-block-sylva {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 22px;\r\n    font-weight: 700;\r\n    color: #1A1109;\r\n    margin-bottom: 5px;\r\n  }\r\n  .membre-role-block-sylva {\r\n    font-family: \'Barlow Condensed\', sans-serif;\r\n    font-size: 13px;\r\n    letter-spacing: 2px;\r\n    text-transform: uppercase;\r\n    color: #8B5E3C;\r\n  }\r\n  @media (max-width: 900px) {\r\n    .equipe-block-sylva { padding: 80px 30px; }\r\n    .equipe-grid-block-sylva { grid-template-columns: repeat(2, 1fr); }\r\n  }\r\n  @media (max-width: 600px) {\r\n    .equipe-grid-block-sylva { grid-template-columns: 1fr; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-06 10:56:36', '2026-06-06 11:14:32'),
(237, NULL, 'FAQ', 'faq-2', NULL, NULL, 'fa-cube', '<section class=\"faq-block-sylva\" id=\"faq\">\r\n  <div class=\"faq-container-block-sylva\">\r\n    <div class=\"faq-header-block-sylva\">\r\n      <div class=\"faq-label-block-sylva\">Questions Fréquentes</div>\r\n      <h2 class=\"faq-title-block-sylva\">Tout ce que Vous <em>Voulez Savoir</em></h2>\r\n    </div>\r\n    <div class=\"faq-list-block-sylva\">\r\n      <div class=\"faq-item-block-sylva\"><button class=\"faq-question-block-sylva\" onclick=\"toggleFaqSylva(this)\">Combien de temps dure la construction d\'une maison ossature bois ?<span class=\"faq-icon-block-sylva\">+</span></button><div class=\"faq-answer-block-sylva\"><p>La durée varie selon la complexité du projet. En général, comptez 3 à 4 mois pour la phase de conception et permis de construire, puis 4 à 6 mois pour la construction elle-même. Une maison en ossature bois se construit 30 à 40% plus rapidement qu\'une construction traditionnelle.</p></div></div>\r\n      <div class=\"faq-item-block-sylva\"><button class=\"faq-question-block-sylva\" onclick=\"toggleFaqSylva(this)\">Quelles sont les performances thermiques d\'une maison en bois ?<span class=\"faq-icon-block-sylva\">+</span></button><div class=\"faq-answer-block-sylva\"><p>Le bois est naturellement un excellent isolant thermique, jusqu\'à 400 fois plus efficace que l\'acier et 15 fois plus que le béton. Nos constructions dépassent systématiquement les normes BBC.</p></div></div>\r\n      <div class=\"faq-item-block-sylva\"><button class=\"faq-question-block-sylva\" onclick=\"toggleFaqSylva(this)\">Comment garantissez-vous la durabilité de vos constructions ?<span class=\"faq-icon-block-sylva\">+</span></button><div class=\"faq-answer-block-sylva\"><p>Nous utilisons exclusivement des essences durables pour toutes les parties exposées. Nos constructions sont couvertes par la garantie décennale obligatoire.</p></div></div>\r\n      <div class=\"faq-item-block-sylva\"><button class=\"faq-question-block-sylva\" onclick=\"toggleFaqSylva(this)\">Puis-je personnaliser entièrement le design de mon chalet ?<span class=\"faq-icon-block-sylva\">+</span></button><div class=\"faq-answer-block-sylva\"><p>Absolument. Chaque projet SYLVA est unique et entièrement sur mesure. De l\'implantation au choix des essences, chaque aspect est co-construit avec vous.</p></div></div>\r\n      <div class=\"faq-item-block-sylva\"><button class=\"faq-question-block-sylva\" onclick=\"toggleFaqSylva(this)\">Intervenez-vous dans toute la France ?<span class=\"faq-icon-block-sylva\">+</span></button><div class=\"faq-answer-block-sylva\"><p>Notre zone principale d\'intervention couvre les régions Auvergne-Rhône-Alpes, PACA et Bourgogne-Franche-Comté. Pour des projets de grande envergure, nous intervenons sur l\'ensemble du territoire français.</p></div></div>\r\n    </div>\r\n  </div>\r\n</section>\r\n<script>\r\n  function toggleFaqSylva(btn) {\r\n    var isActive = btn.classList.contains(\'active\');\r\n    document.querySelectorAll(\'.faq-question-block-sylva\').forEach(function(b) {\r\n      b.classList.remove(\'active\');\r\n      b.nextElementSibling.classList.remove(\'open\');\r\n    });\r\n    if (!isActive) {\r\n      btn.classList.add(\'active\');\r\n      btn.nextElementSibling.classList.add(\'open\');\r\n    }\r\n  }\r\n</script>', '.faq-block-sylva {\r\n    background: #F0E8DC;\r\n    padding: 110px 60px;\r\n  }\r\n  .faq-container-block-sylva {\r\n    max-width: 800px;\r\n    margin: 0 auto;\r\n  }\r\n  .faq-header-block-sylva {\r\n    text-align: center;\r\n    margin-bottom: 60px;\r\n  }\r\n  .faq-label-block-sylva {\r\n    font-family: \'Barlow Condensed\', sans-serif;\r\n    font-size: 11px;\r\n    font-weight: 500;\r\n    letter-spacing: 4px;\r\n    text-transform: uppercase;\r\n    color: #8B5E3C;\r\n    margin-bottom: 16px;\r\n    display: inline-block;\r\n  }\r\n  .faq-title-block-sylva {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: clamp(36px, 4.5vw, 58px);\r\n    font-weight: 700;\r\n    line-height: 1.15;\r\n    color: #1A1109;\r\n  }\r\n  .faq-title-block-sylva em {\r\n    font-style: italic;\r\n    color: #8B5E3C;\r\n  }\r\n  .faq-item-block-sylva {\r\n    border-bottom: 1px solid rgba(139,94,60,0.2);\r\n    margin-bottom: 5px;\r\n  }\r\n  .faq-question-block-sylva {\r\n    width: 100%;\r\n    background: none;\r\n    border: none;\r\n    text-align: left;\r\n    padding: 25px 0;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 18px;\r\n    font-weight: 600;\r\n    color: #1A1109;\r\n    cursor: pointer;\r\n    transition: color 0.3s;\r\n  }\r\n  .faq-question-block-sylva:hover {\r\n    color: #8B5E3C;\r\n  }\r\n  .faq-icon-block-sylva {\r\n    width: 36px;\r\n    height: 36px;\r\n    border: 1px solid #C4956A;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-size: 20px;\r\n    color: #8B5E3C;\r\n    transition: all 0.3s;\r\n    flex-shrink: 0;\r\n  }\r\n  .faq-question-block-sylva.active .faq-icon-block-sylva {\r\n    background: #8B5E3C;\r\n    color: #FDFAF6;\r\n    transform: rotate(45deg);\r\n  }\r\n  .faq-answer-block-sylva {\r\n    max-height: 0;\r\n    overflow: hidden;\r\n    transition: max-height 0.4s ease;\r\n    padding-right: 20px;\r\n  }\r\n  .faq-answer-block-sylva.open {\r\n    max-height: 200px;\r\n    padding-bottom: 25px;\r\n  }\r\n  .faq-answer-block-sylva p {\r\n    font-size: 15px;\r\n    font-weight: 300;\r\n    color: #7A7269;\r\n    line-height: 1.8;\r\n  }\r\n  @media (max-width: 900px) {\r\n    .faq-block-sylva { padding: 80px 30px; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 11:03:47', '2026-06-06 11:15:17'),
(238, NULL, 'Footer', 'footer-3', NULL, NULL, 'fa-cube', '<footer class=\"footer-sylva\"><div class=\"footer-top-sylva\"><div class=\"footer-brand-sylva\"><a href=\"#\" class=\"nav-logo-sylva\"><div class=\"logo-icon-sylva\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z\"/><polyline points=\"9,22 9,12 15,12 15,22\"/></svg></div>SYLVA<span>.</span></a><p>Construction bois d\'exception depuis 2003. Maisons, chalets et aménagements taillés sur mesure avec passion et savoir-faire artisanal.</p><div class=\"footer-socials-sylva\"><a href=\"#\" class=\"footer-social-sylva\">f</a><a href=\"#\" class=\"footer-social-sylva\">in</a><a href=\"#\" class=\"footer-social-sylva\">ig</a><a href=\"#\" class=\"footer-social-sylva\">yt</a></div></div><div class=\"footer-col-sylva\"><h4>Services</h4><ul><li><a href=\"#\">Maisons Ossature Bois</a></li><li><a href=\"#\">Chalets Alpins</a></li><li><a href=\"#\">Extensions</a></li><li><a href=\"#\">Terrasses</a></li></ul></div><div class=\"footer-col-sylva\"><h4>Entreprise</h4><ul><li><a href=\"#\">À Propos</a></li><li><a href=\"#\">Notre Équipe</a></li><li><a href=\"#\">Nos Certifications</a></li><li><a href=\"#\">Carrières</a></li></ul></div><div class=\"footer-col-sylva\"><h4>Informations</h4><ul><li><a href=\"#\">FAQ</a></li><li><a href=\"#\">Devis Gratuit</a></li><li><a href=\"#\">Mentions Légales</a></li><li><a href=\"#\">Plan du Site</a></li></ul></div></div><div class=\"footer-bottom-sylva\"><span>© 2025 SYLVA Construction Bois. Tous droits réservés.</span><span>Réalisé avec ♥ en Haute-Savoie</span></div></footer>', '.footer-sylva { background: #1A1109; padding: 80px 60px 40px; }\r\n  .footer-top-sylva { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 60px; padding-bottom: 60px; border-bottom: 1px solid rgba(255,255,255,0.08); margin-bottom: 40px; }\r\n  .footer-brand-sylva .nav-logo-sylva { margin-bottom: 20px; display: inline-block; color: #FDFAF6; text-decoration: none; }\r\n  .footer-brand-sylva p { font-size: 14px; font-weight: 300; color: rgba(255,255,255,0.45); line-height: 1.8; }\r\n  .footer-socials-sylva { display: flex; gap: 10px; margin-top: 24px; }\r\n  .footer-social-sylva { width: 38px; height: 38px; border: 1px solid rgba(255,255,255,0.15); display: flex; align-items: center; justify-content: center; color: rgba(255,255,255,0.5); text-decoration: none; font-size: 15px; transition: all 0.25s; }\r\n  .footer-social-sylva:hover { background: #D4A853; border-color: #D4A853; color: #1A1109; }\r\n  .footer-col-sylva h4 { font-family: \'Barlow Condensed\', sans-serif; font-size: 12px; font-weight: 600; letter-spacing: 3px; text-transform: uppercase; color: rgba(255,255,255,0.4); margin-bottom: 24px; }\r\n  .footer-col-sylva ul { list-style: none; display: flex; flex-direction: column; gap: 12px; }\r\n  .footer-col-sylva ul a { font-size: 14px; color: rgba(255,255,255,0.55); text-decoration: none; transition: color 0.2s; display: flex; align-items: center; gap: 8px; }\r\n  .footer-col-sylva ul a::before { content: \'\'; width: 16px; height: 1px; background: #C4956A; transition: width 0.2s; }\r\n  .footer-col-sylva ul a:hover { color: #D4A853; }\r\n  .footer-col-sylva ul a:hover::before { width: 24px; background: #D4A853; }\r\n  .footer-bottom-sylva { display: flex; align-items: center; justify-content: space-between; font-size: 12px; color: rgba(255,255,255,0.25); }\r\n  @media (max-width: 900px) { .footer-sylva { padding: 60px 30px 40px; } .footer-top-sylva { grid-template-columns: 1fr 1fr; gap: 40px; } .footer-bottom-sylva { flex-direction: column; gap: 16px; text-align: center; } }\r\n  @media (max-width: 600px) { .footer-top-sylva { grid-template-columns: 1fr; } }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 0, 0, 0, 1, '2026-06-06 11:04:21', '2026-06-06 11:04:21'),
(239, NULL, 'Vidéo iframe', 'video-iframe', NULL, NULL, 'fa-cube', '<section class=\"video-iframe-section\">\r\n  <div class=\"video-iframe-container\">\r\n    <div class=\"video-iframe-header\">\r\n      <h2 class=\"video-iframe-title\">Découvrez <em>nos réalisations</em></h2>\r\n      <p class=\"video-iframe-sub\">Plongez au cœur de notre artisanat et laissez-vous inspirer</p>\r\n    </div>\r\n    <div class=\"video-iframe-wrapper\">\r\n      <iframe \r\n        src=\"https://www.youtube.com/embed/2AOSbHozuzY?autoplay=0&rel=0&modestbranding=1\" \r\n        title=\"Vidéo Prestige Bois Rond\"\r\n        allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\"\r\n        allowfullscreen>\r\n      </iframe>\r\n    </div>\r\n  </div>\r\n</section>', '.video-iframe-section {\r\n    background: #080808;\r\n    padding: 80px 60px;\r\n    text-align: center;\r\n  }\r\n  .video-iframe-container {\r\n    max-width: 1100px;\r\n    margin: 0 auto;\r\n  }\r\n  .video-iframe-header {\r\n    margin-bottom: 40px;\r\n  }\r\n  .video-iframe-title {\r\n    font-family: \'Cormorant Garamond\', Georgia, serif;\r\n    font-size: 38px;\r\n    font-weight: 700;\r\n    color: #F5F0E8;\r\n    margin-bottom: 16px;\r\n  }\r\n  .video-iframe-title em {\r\n    color: #C9A84C;\r\n    font-style: italic;\r\n  }\r\n  .video-iframe-sub {\r\n    font-size: 16px;\r\n    color: #7A7470;\r\n    max-width: 550px;\r\n    margin: 0 auto;\r\n  }\r\n  .video-iframe-wrapper {\r\n    position: relative;\r\n    width: 100%;\r\n    aspect-ratio: 16/9;\r\n    background: #000;\r\n    border-radius: 16px;\r\n    overflow: hidden;\r\n    box-shadow: 0 20px 40px rgba(0,0,0,0.4);\r\n  }\r\n  .video-iframe-wrapper iframe {\r\n    width: 100%;\r\n    height: 100%;\r\n    border: none;\r\n  }\r\n  @media (max-width: 768px) {\r\n    .video-iframe-section { padding: 60px 20px; }\r\n    .video-iframe-title { font-size: 32px; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 1, 0, 0, 1, '2026-06-07 20:07:19', '2026-06-08 09:22:33'),
(240, NULL, '3 Vidéos Iframe', '3-videos-iframe', NULL, NULL, 'fa-cube', '<section class=\"video-gallery-section\">\r\n  <div class=\"video-gallery-container\">\r\n    <div class=\"video-gallery-header\">\r\n      <h2>Nos <em>réalisations</em> en vidéo</h2>\r\n      <p>Découvrez la qualité et le savoir-faire Prestige Bois Rond</p>\r\n    </div>\r\n    <div class=\"video-gallery-grid\">\r\n      <div class=\"video-gallery-card\">\r\n        <iframe src=\"https://www.youtube.com/embed/2AOSbHozuzY?rel=0\" allowfullscreen></iframe>\r\n        <div class=\"video-gallery-card-info\">\r\n          <h3>Présentation Prestige Bois Rond</h3>\r\n          <p>Découvrez notre univers et notre passion pour le bois rond</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"video-gallery-card\">\r\n        <iframe src=\"https://www.youtube.com/embed/dQw4w9WgXcQ?rel=0\" allowfullscreen></iframe>\r\n        <div class=\"video-gallery-card-info\">\r\n          <h3>Chalet Scandinave</h3>\r\n          <p>Visite complète d\'un chalet scandinave livré en 2024</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"video-gallery-card\">\r\n        <iframe src=\"https://www.youtube.com/embed/8hJhyZrZMIA?rel=0\" allowfullscreen></iframe>\r\n        <div class=\"video-gallery-card-info\">\r\n          <h3>Série Prestige</h3>\r\n          <p>Les finitions haut de gamme de notre collection Prestige</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>', '.video-gallery-section {\r\n    background: #080808;\r\n    padding: 80px 60px;\r\n  }\r\n  .video-gallery-container {\r\n    max-width: 1280px;\r\n    margin: 0 auto;\r\n  }\r\n  .video-gallery-header {\r\n    text-align: center;\r\n    margin-bottom: 50px;\r\n  }\r\n  .video-gallery-header h2 {\r\n    font-family: \'Cormorant Garamond\', Georgia, serif;\r\n    font-size: 42px;\r\n    font-weight: 700;\r\n    color: #F5F0E8;\r\n    margin-bottom: 16px;\r\n  }\r\n  .video-gallery-header h2 em {\r\n    color: #C9A84C;\r\n    font-style: italic;\r\n  }\r\n  .video-gallery-header p {\r\n    font-size: 16px;\r\n    color: #7A7470;\r\n    max-width: 550px;\r\n    margin: 0 auto;\r\n  }\r\n  .video-gallery-grid {\r\n    display: grid;\r\n    grid-template-columns: repeat(3, 1fr);\r\n    gap: 24px;\r\n  }\r\n  .video-gallery-card {\r\n    background: rgba(255,255,255,0.03);\r\n    border-radius: 16px;\r\n    overflow: hidden;\r\n    transition: transform 0.3s;\r\n  }\r\n  .video-gallery-card:hover {\r\n    transform: translateY(-5px);\r\n  }\r\n  .video-gallery-card iframe {\r\n    width: 100%;\r\n    aspect-ratio: 16/9;\r\n    border: none;\r\n  }\r\n  .video-gallery-card-info {\r\n    padding: 16px;\r\n  }\r\n  .video-gallery-card-info h3 {\r\n    font-family: \'Outfit\', sans-serif;\r\n    font-size: 16px;\r\n    font-weight: 600;\r\n    color: #F5F0E8;\r\n    margin-bottom: 6px;\r\n  }\r\n  .video-gallery-card-info p {\r\n    font-size: 12px;\r\n    color: #7A7470;\r\n  }\r\n  @media (max-width: 900px) {\r\n    .video-gallery-section { padding: 60px 20px; }\r\n    .video-gallery-grid { grid-template-columns: 1fr; }\r\n  }', NULL, NULL, 'Basic', 'General', '[]', 1, 1, NULL, NULL, 0, 4, 0, 0, 1, '2026-06-08 09:32:34', '2026-07-25 19:47:11'),
(242, NULL, 'Vidéo Player Iframe', 'video-player-iframe', NULL, NULL, 'fa-cube', '<section class=\"video-library-section\">\r\n  <div class=\"video-library-container\">\r\n    <div class=\"video-library-header\">\r\n      <div class=\"video-library-badge\">✦ Notre videothèque</div>\r\n      <h2 class=\"video-library-title\">Découvrez <em>nos réalisations</em></h2>\r\n      <p class=\"video-library-sub\">Cliquez sur une vidéo ci-dessous pour la découvrir en grand format</p>\r\n    </div>\r\n\r\n    <div class=\"video-library-layout\">\r\n      <!-- Lecteur principal (GAUCHE) -->\r\n      <div class=\"video-library-player\">\r\n        <iframe class=\"video-library-main-frame\" id=\"mainVideoLibrary\"\r\n          src=\"https://www.youtube.com/embed/2AOSbHozuzY?autoplay=0&rel=0&modestbranding=1\"\r\n          title=\"Lecteur vidéo principal\"\r\n          allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\"\r\n          allowfullscreen>\r\n        </iframe>\r\n        <div class=\"video-library-main-info\" id=\"mainVideoInfo\">\r\n          <div class=\"video-library-main-title\">Présentation Prestige Bois Rond</div>\r\n          <div class=\"video-library-main-desc\">Découvrez notre savoir-faire artisanal et la passion du bois rond.</div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Liste des vidéos (DROITE) - IFRAME DIRECT PREMIER ÉLÉMENT -->\r\n      <div class=\"video-library-list\" id=\"videoLibraryList\">\r\n        \r\n        <!-- Vidéo 1 -->\r\n        <div class=\"video-library-card\" \r\n             data-video-id=\"2AOSbHozuzY\"\r\n             data-video-url=\"https://www.youtube.com/embed/2AOSbHozuzY?autoplay=1&rel=0&modestbranding=1\"\r\n             data-title=\"Présentation Prestige Bois Rond\" \r\n             data-desc=\"Découvrez notre savoir-faire artisanal et la passion du bois rond.\">\r\n          <iframe src=\"https://www.youtube.com/embed/2AOSbHozuzY?autoplay=0&rel=0&modestbranding=1&controls=0\"\r\n            title=\"Miniature vidéo 1\"\r\n            allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\">\r\n          </iframe>\r\n          <div class=\"video-library-card-play\"><i class=\"fa fa-play\"></i></div>\r\n          <div class=\"video-library-card-info\">\r\n            <div class=\"video-library-card-title\">Présentation Prestige Bois Rond</div>\r\n            <div class=\"video-library-card-desc\">Découvrez notre savoir-faire artisanal...</div>\r\n            <div class=\"video-library-card-meta\">\r\n              <span class=\"video-library-card-duration\"><i class=\"fa fa-clock-o\"></i> 2:34 min</span>\r\n              <span class=\"video-library-card-cat\"><i class=\"fa fa-tag\"></i> Présentation</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Vidéo 2 -->\r\n        <div class=\"video-library-card\" \r\n             data-video-id=\"dQw4w9WgXcQ\"\r\n             data-video-url=\"https://www.youtube.com/embed/dQw4w9WgXcQ?autoplay=1&rel=0&modestbranding=1\"\r\n             data-title=\"Chalet Scandinave - Visite complète\" \r\n             data-desc=\"Visitez ce magnifique chalet scandinave livré en 2024 en Estrie.\">\r\n          <iframe src=\"https://www.youtube.com/embed/dQw4w9WgXcQ?autoplay=0&rel=0&modestbranding=1&controls=0\"\r\n            title=\"Miniature vidéo 2\"\r\n            allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\">\r\n          </iframe>\r\n          <div class=\"video-library-card-play\"><i class=\"fa fa-play\"></i></div>\r\n          <div class=\"video-library-card-info\">\r\n            <div class=\"video-library-card-title\">Chalet Scandinave - Visite complète</div>\r\n            <div class=\"video-library-card-desc\">Visitez ce magnifique chalet scandinave...</div>\r\n            <div class=\"video-library-card-meta\">\r\n              <span class=\"video-library-card-duration