INSERT INTO `destinations` (`id`, `name`, `image`, `description`, `is_active`, `slug`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Toronto', 'toronto.jpg', 'La plus grande ville du Canada, centre économique et culturel.', 1, 'toronto', '2026-01-10 10:01:03', '2026-01-10 10:03:59', '2026-01-10 10:03:59'),
(2, 'Canada', 'destinations/c7M1isDfA1rHOIxBslGORE1MDc13uut495LyqHaR.jpg', 'Le Canada est un pays immense et diversifié, reconnu pour ses paysages spectaculaires, sa nature préservée et sa qualité de vie. Entre montagnes, forêts, lacs et villes modernes, il offre une richesse culturelle et naturelle exceptionnelle.', 1, 'canada', '2026-01-10 10:01:03', '2026-01-10 12:25:37', NULL),
(3, 'Vancouver', 'vancouver.jpg', 'Cité côtière entourée de montagnes, idéale pour les amoureux de la nature.', 1, 'vancouver', '2026-01-10 10:01:03', '2026-01-10 10:12:50', '2026-01-10 10:12:50'),
(4, 'Québec', 'quebec.jpg', 'Ville historique fortifiée, berceau de la civilisation française en Amérique.', 1, 'quebec', '2026-01-10 10:01:03', '2026-01-10 10:12:28', '2026-01-10 10:12:28'),
(5, 'Calgary', 'calgary.jpg', 'Porte d\'entrée des Rocheuses canadiennes et célèbre pour son Stampede.', 0, 'calgary', '2026-01-10 10:01:03', '2026-01-10 10:13:30', '2026-01-10 10:13:30'),
(6, 'Ottawa', 'ottawa.jpg', 'Capitale du Canada, riche en musées et institutions nationales.', 1, 'ottawa', '2026-01-10 10:01:03', '2026-01-10 10:12:33', '2026-01-10 10:12:33'),
(7, 'Banff', 'banff.jpg', 'Station de montagne renommée dans le parc national de Banff.', 1, 'banff', '2026-01-10 10:01:03', '2026-01-10 10:12:38', '2026-01-10 10:12:38'),
(8, 'Niagara Falls', 'niagara.jpg', 'Célèbres chutes d\'eau à la frontière Canada-États-Unis.', 1, 'niagara-falls', '2026-01-10 10:01:03', '2026-01-10 10:12:44', '2026-01-10 10:12:44'),
(9, 'Winnipeg', 'winnipeg.jpg', 'Ville des prairies canadiennes.', 0, 'winnipeg', '2026-01-10 10:01:03', '2026-01-10 10:12:16', '2026-01-10 10:12:16'),
(10, 'Halifax', 'halifax.jpg', 'Port historique sur la côte atlantique.', 1, 'halifax', '2026-01-10 10:01:03', '2026-01-10 10:04:31', '2026-01-10 10:04:31'),
(11, 'Province de Québec', 'destinations/MuygjcNCNqO03ZxjbTWLId9Q7jmSueLQX4E6jipp.jpg', 'Le Québec est une province francophone unique en Amérique du Nord. Elle allie culture, histoire, gastronomie et grands espaces naturels, avec un fort accent sur l’identité et le tourisme durable.', 1, 'province-de-quebec', '2026-01-10 12:27:27', '2026-01-10 12:31:09', NULL),
(12, 'Abitibi-Témiscamingue', 'destinations/qQ3zzd9a4c9bKWmxulFHbBoFTszB8ldFWyRPpXvk.jpg', 'Région de forêts et de lacs, l’Abitibi-Témiscamingue est un paradis pour les amateurs de plein air, de pêche et de tourisme nature. Elle se distingue aussi par son héritage minier et culturel.', 1, 'abitibi-temiscamingue', '2026-01-10 12:31:49', '2026-01-10 12:31:49', NULL),
(13, 'Bas-Saint-Laurent', 'destinations/IBXysIQ5NYpy35f42PHnf6Nzk1JxV1aStqVMqnG6.jpg', 'Située le long du fleuve Saint-Laurent, cette région séduit par ses paysages maritimes, ses villages côtiers et son ambiance paisible, idéale pour l’écotourisme et la détente.', 1, 'bas-saint-laurent', '2026-01-10 12:34:02', '2026-01-10 12:34:02', NULL),
(14, 'Cantons-de-l’Est', 'destinations/MmHkhCvpJOIw3yRVq54ULYRu4NYsdR9jBsPdo6sE.jpg', 'Connue pour ses collines, vignobles et lacs, la région des Cantons-de-l’Est est prisée pour le tourisme gourmand, les activités quatre saisons et son charme européen.', 1, 'cantons-de-lest', '2026-01-10 12:40:08', '2026-01-10 12:40:08', NULL),
(15, 'Centre-du-Québec', 'destinations/j0uBTGv3YZoeUg4YJ0NuR1ACByIBpBSqDGBCJXt7.jpg', 'Le Centre-du-Québec est une région agricole dynamique, située au cœur de la province. Elle combine traditions rurales, innovation et proximité avec les grands centres urbains.', 1, 'centre-du-quebec', '2026-01-10 12:45:18', '2026-01-10 12:45:18', NULL),
(16, 'Charlevoix', 'destinations/aXuiB0sF8GgrKjPmqwaAckWWCnoXtr6buUnJ3j84.jpg', 'Charlevoix est célèbre pour ses montagnes, ses panoramas spectaculaires et sa gastronomie locale. Une destination prisée pour l’art, la nature et le tourisme haut de gamme.', 1, 'charlevoix', '2026-01-10 12:52:38', '2026-01-10 12:53:08', NULL),
(17, 'Chaudière-Appalaches', 'destinations/ORsJ66LJVzwmBZEb0h7wjDIYG0s1AClpC58I6sge.jpg', 'Cette région est reconnue pour ses rivières, ses chutes impressionnantes et son esprit entrepreneurial, notamment dans la région de la Beauce.', 1, 'chaudiere-appalaches', '2026-01-10 12:55:27', '2026-01-10 12:55:27', NULL),
(18, 'Côte-Nord', 'destinations/G21VnUQb2Z77C1c0zUnQN8rHR0dAaI7MKNqvJ42b.jpg', 'La Côte-Nord offre des paysages sauvages, une faune exceptionnelle et des expériences uniques comme l’observation des baleines et les grands espaces nordiques.', 1, 'cote-nord', '2026-01-10 12:56:14', '2026-01-10 12:56:14', NULL),
(19, 'Eeyou Istchee Baie-James', 'destinations/wA1zNpBhiSRDzbd0vHwpHP1l63wLMnBuf7UFmyBT.jpg', 'Territoire nordique immense, Eeyou Istchee Baie-James est marqué par la culture crie, les projets hydroélectriques majeurs et une nature brute et préservée.', 1, 'eeyou-istchee-baie-james', '2026-01-10 12:57:13', '2026-01-10 12:57:13', NULL),
(20, 'Gaspésie', 'destinations/OIKNPDXiRt7EFS4e7CZPGTDRblpwphK6ZVLZDGEl.jpg', 'La Gaspésie est réputée pour ses falaises, ses montagnes et son célèbre Rocher Percé. Elle incarne l’aventure, la mer et les grands paysages canadiens.', 1, 'gaspesie', '2026-01-10 12:59:49', '2026-01-10 14:16:53', NULL),
(21, 'Îles-de-la-Madeleine', 'destinations/mdLFEGrroN3KXEQnB84gJcFl36k2s9xS26XSPNHa.jpg', 'Archipel au charme unique, les Îles-de-la-Madeleine séduisent par leurs plages de sable, falaises rouges, culture maritime et ambiance chaleureuse.', 1, 'iles-de-la-madeleine', '2026-01-10 13:22:01', '2026-01-10 13:22:01', NULL);
