INSERT INTO `menus` (`id`, `title`, `slug`, `type`, `parent_id`, `reference_id`, `menu_type`, `order`, `route`, `url`, `icon`, `is_active`, `has_page`, `page_id`, `page_content`, `page_styles`, `page_meta`, `page_status`, `page_slug`, `created_at`, `updated_at`) VALUES
(2, '🏢 Info Business', 'info-business-go-exploria', 'custom', NULL, NULL, 'Accueil', 3, NULL, '#info-business-go-exploria', NULL, 1, 1, NULL, '<body><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\"/><div id=\"consulting-section\" class=\"consulting-section\"><!-- En-tête de la section --><div class=\"section-header\"><h1>Agence de Conseil pour Votre Entreprise</h1><p>Développez votre entreprise avec notre expertise stratégique et nos solutions sur mesure. Demandez votre consultation personnalisée.</p></div><div class=\"section-content\"><!-- Partie gauche : Présentation de l\'entreprise avec image de clientèle --><div class=\"company-presentation\"><!-- En-tête avec logo et image de clientèle --><div class=\"company-header\"><div class=\"company-logo\"><div class=\"logo-icon\"><i class=\"fas fa-chart-line\"></i></div><div class=\"logo-text\"><h2>Stratégis Conseil</h2><p>Votre succès, notre expertise</p></div></div><!-- Image de clientèle à droite --><div class=\"clientele-image\"><!-- SVG illustrant une équipe de clients satisfaits --><img src=\"data:image/jpeg;base64,\" alt=\"Clientèle satisfaite\" id=\"igikc\" class=\"clientele-svg\"/></div></div><!-- Description de l\'entreprise --><div class=\"company-description\"><h3>Notre Agence de Conseil</h3><p>Nous sommes une agence de conseil spécialisée dans l\'accompagnement des entreprises vers l\'excellence opérationnelle et la croissance durable.</p><p>Notre équipe d\'experts vous aide à identifier les opportunités, optimiser vos processus et mettre en place des stratégies efficaces pour atteindre vos objectifs.</p><ul class=\"features-list\"><li><i class=\"fas fa-check-circle\"></i> Conseil stratégique sur mesure\n                        </li><li><i class=\"fas fa-check-circle\"></i> Analyse approfondie de votre marché\n                        </li><li><i class=\"fas fa-check-circle\"></i> Solutions digitales innovantes\n                        </li><li><i class=\"fas fa-check-circle\"></i> Accompagnement pas à pas\n                        </li></ul></div></div><!-- Partie droite : Formulaire, image et plans --><div class=\"request-section\"><h3 class=\"section-title\">Demandez Votre Consultation</h3><!-- Conteneur formulaire + image --><div class=\"form-image-container\"><!-- Formulaire --><div class=\"form-container\"><form method=\"get\" class=\"request-form\"><div class=\"form-group\"><label for=\"company-name\">Nom de votre société</label><input type=\"text\" id=\"company-name\" placeholder=\"Ex: Ma Société SARL\" class=\"form-control\"/></div><div class=\"form-group\"><label for=\"contact-name\">Votre nom</label><input type=\"text\" id=\"contact-name\" placeholder=\"Ex: Jean Dupont\" class=\"form-control\"/></div><div class=\"form-group\"><label for=\"email\">Adresse email</label><input type=\"email\" id=\"email\" placeholder=\"exemple@societe.com\" class=\"form-control\"/></div><div class=\"form-group\"><label for=\"service\">Service souhaité</label><select id=\"service\" class=\"form-control\"><option value=\"\">Sélectionnez un service</option><option value=\"strategy\">Conseil stratégique</option><option value=\"digital\">Transformation digitale</option><option value=\"management\">Management opérationnel</option><option value=\"marketing\">Stratégie marketing</option></select></div><button type=\"submit\" class=\"submit-btn\">Envoyer</button></form></div><!-- Image de graphique à droite --><div class=\"image-container\"><div><!-- Image SVG de graphique de croissance --><svg viewBox=\"0 0 400 300\" xmlns=\"http://www.w3.org/2000/svg\" class=\"growth-chart\"><defs><linearGradient id=\"chartBg\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\"><stop offset=\"0%\" id=\"ishls\"></stop><stop offset=\"100%\" id=\"iwvi1\"></stop></linearGradient><linearGradient id=\"barGradient1\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\"><stop offset=\"0%\" id=\"iblfm\"></stop><stop offset=\"100%\" id=\"i5peu\"></stop></linearGradient><lin