ormal;transition-duration:0.25s;transition-timing-function:ease;transition-delay:0s;transition-property:all;border-top-width:1px;border-right-width:1px;border-bottom-width:1px;border-left-width:1px;border-top-style:solid;border-right-style:solid;border-bottom-style:solid;border-left-style:solid;border-top-color:rgb(226, 238, 245);border-right-color:rgb(226, 238, 245);border-bottom-color:rgb(226, 238, 245);border-left-color:rgb(226, 238, 245);border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;display:flex;flex-direction:column;}.property-card:hover{transform:translateY(-8px);box-shadow:rgb(26, 64, 85) 0px 30px 45px -15px;}.card-image{position:relative;height:240px;overflow-x:hidden;overflow-y:hidden;}.card-image img{width:100%;height:100%;object-fit:cover;transition-behavior:normal;transition-duration:0.6s;transition-timing-function:ease;transition-delay:0s;transition-property:transform;}.property-card:hover .card-image img{transform:scale(1.05);}.image-badge{position:absolute;top:16px;left:16px;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgba(255, 255, 255, 0.9);backdrop-filter:blur(4px);padding-top:6px;padding-right:16px;padding-bottom:6px;padding-left:16px;border-top-left-radius:40px;border-top-right-radius:40px;border-bottom-right-radius:40px;border-bottom-left-radius:40px;font-weight:600;font-size:0.85rem;color:rgb(15, 59, 79);box-shadow:rgba(0, 0, 0, 0.05) 0px 5px 12px;border-top-width:1px;border-right-width:1px;border-bottom-width:1px;border-left-width:1px;border-top-style:solid;border-right-style:solid;border-bottom-style:solid;border-left-style:solid;border-top-color:rgba(255, 255, 255, 0.5);border-right-color:rgba(255, 255, 255, 0.5);border-bottom-color:rgba(255, 255, 255, 0.5);border-left-color:rgba(255, 255, 255, 0.5);border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;}.card-content{padding-top:28px;padding-right:22px;padding-bottom:26px;padding-left:22px;flex-grow:1;flex-shrink:1;flex-basis:0%;}.property-title{font-family:\"Playfair Display\", serif;font-size:1.9rem;font-weight:700;margin-bottom:8px;color:rgb(23, 56, 71);}.property-location{display:flex;align-items:center;row-gap:8px;column-gap:8px;color:rgb(89, 126, 148);font-weight:500;margin-top:8px;margin-right:0px;margin-bottom:16px;margin-left:0px;font-size:1rem;}.property-features{display:flex;flex-wrap:wrap;row-gap:18px;column-gap:18px;margin-top:20px;margin-right:0px;margin-bottom:20px;margin-left:0px;padding-top:16px;padding-right:0px;padding-bottom:16px;padding-left:0px;border-top-width:1px;border-top-style:dashed;border-top-color:rgb(198, 218, 232);border-bottom-width:1px;border-bottom-style:dashed;border-bottom-color:rgb(198, 218, 232);}.feature{display:flex;align-items:center;row-gap:8px;column-gap:8px;font-weight:500;color:rgb(43, 87, 112);}.feature i{font-size:1.3rem;color:rgb(44, 127, 160);}.property-price{font-size:2.2rem;font-weight:800;color:rgb(27, 94, 122);margin-top:18px;margin-right:0px;margin-bottom:12px;margin-left:0px;line-height:1;}.price-suffix{font-size:1rem;font-weight:400;color:rgb(111, 143, 161);margin-left:5px;}.btn-property{display:inline-block;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:transparent;border-top-width:2px;border-right-width:2px;border-bottom-width:2px;border-left-width:2px;border-top-style:solid;border-right-style:solid;border-bottom-style:solid;border-left-style:solid;border-top-color:rgb(44, 127, 160);border-right-color:rgb(44, 127, 160);border-bottom-color:rgb(44, 127, 160);border-left-color:rgb(44, 127, 160);border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;color:rgb(44, 127, 160);padding-top:12px;padding-right:32px;padding-bottom:12px;padding-left:32px;border-top-left-radius:60px;border-top-right-radius:60px;border-bottom-right-radius:60px;border-bottom-left-radius:60px;font-weight:700;text-decoration-line:none;text-decoration-thickness:initial;text-decoration-style:initial;text-decoration-color:initial;transition-behavior:normal;transition-duration:0.2s;transition-timing-function:ease;transition-delay:0s;transition-property:all;width:100%;text-align:center;font-size:1rem;}.btn-property:hover{background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(44, 127, 160);color:white;}.agent-cta{margin-top:60px;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(233, 242, 249);border-top-left-radius:60px;border-top-right-radius:60px;border-bottom-right-radius:60px;border-bottom-left-radius:60px;padding-top:40px;padding-right:50px;padding-bottom:40px;padding-left:50px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;row-gap:30px;column-gap:30px;}.agent-info{display:flex;align-items:center;row-gap:25px;column-gap:25px;flex-wrap:wrap;}.agent-avatar{width:90px;height:90px;border-top-left-radius:50%;border-top-right-radius:50%;border-bottom-right-radius:50%;border-bottom-left-radius:50%;object-fit:cover;border-top-width:4px;border-right-width:4px;border-bottom-width:4px;border-left-width:4px;border-top-style:solid;border-right-style:solid;border-bottom-style:solid;border-left-style:solid;border-top-color:white;border-right-color:white;border-bottom-color:white;border-left-color:white;border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;box-shadow:rgba(0, 60, 80, 0.1) 0px 10px 20px;}.agent-details h4{font-family:\"Playfair Display\", serif;font-size:2rem;margin-bottom:5px;color:rgb(9, 48, 63);}.btn-contact{background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(9, 48, 63);color:white;padding-top:16px;padding-right:42px;padding-bottom:16px;padding-left:42px;border-top-left-radius:50px;border-top-right-radius:50px;border-bottom-right-radius:50px;border-bottom-left-radius:50px;text-decoration-line:none;text-decoration-thickness:initial;text-decoration-style:initial;text-decoration-color:initial;font-weight:700;font-size:1.1rem;transition-behavior:normal;transition-duration:0.2s;transition-timing-function:ease;transition-delay:0s;transition-property:all;border-top-width:1px;border-right-width:1px;border-bottom-width:1px;border-left-width:1px;border-top-style:solid;border-right-style:solid;border-bottom-style:solid;border-left-style:solid;border-top-color:rgba(255, 255, 255, 0.19);border-right-color:rgba(255, 255, 255, 0.19);border-bottom-color:rgba(255, 255, 255, 0.19);border-left-color:rgba(255, 255, 255, 0.19);border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;box-shadow:rgba(7, 33, 46, 0.25) 0px 10px 20px;}.btn-contact:hover{background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(18, 76, 99);transform:scale(1.02);}[data-gjs-type=\"property-card\"], [data-gjs-type=\"badge\"], [data-gjs-type=\"agent\"]{transition-behavior:normal;transition-duration:0.1s;transition-timing-function:ease;transition-delay:0s;transition-property:outline;}#ikqpjb{font-weight:600;}#i8dgpb{border:0px solid #fffdfd;}#imcypd{border:0 solid white;}@media (max-width: 768px){.consulting-section{flex-direction:column;}.request-section{border-left-width:initial;border-left-style:none;border-left-color:initial;border-top-width:1px;border-top-style:solid;border-top-color:rgb(238, 238, 238);}.section-header h1{font-size:2rem;}.form-image-container{flex-direction:column;}.image-container{order:-1;margin-bottom:20px;}.company-header{flex-direction:column;}.clientele-image{margin-top:20px;max-width:100%;}}@media (max-width: 700px){.agent-cta{flex-direction:column;text-align:center;}.agent-info{flex-direction:column;}}', NULL, 'draft', NULL, '2026-02-02 10:45:44', '2026-02-16 13:30:24');
INSERT INTO `menus` (`id`, `title`, `slug`, `type`, `parent_id`, `reference_id`, `menu_type`, `order`, `route`, `url`, `icon`, `is_active`, `has_page`, `page_id`, `page_content`, `page_styles`, `page_meta`, `page_status`, `page_slug`, `created_at`, `updated_at`) VALUES
(3, '🏛️ MOSTS AU QUÉBEC', 'mosts-au-quebec', 'custom', NULL, NULL, 'Accueil', 5, NULL, '#mosts-au-quebec', NULL, 1, 1, NULL, '<body>\n  <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\" />\n  <link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&amp;family=Montserrat:wght@400;500;700&amp;display=swap\" rel=\"stylesheet\" />\n  <div class=\"container\">\n    <!-- En-tête de la page -->\n    <header class=\"section-header\">\n      <h2 class=\"section-subtitle grapejs-editable\">Découvrez les meilleurs du Québec</h2>\n      <h1 class=\"section-title grapejs-editable\">LES MOSTS AU QUÉBEC</h1>\n      <p class=\"section-description grapejs-editable\"> Explorez les entreprises, régions, activités, vidéos et événements les plus remarquables du Québec. Notre sélection exclusive vous guide vers les meilleures expériences. </p>\n    </header>\n    <!-- Carrousel 1: Entreprises -->\n    <section class=\"carousel-container\">\n      <div class=\"carousel-header\">\n        <h3 class=\"carousel-title grapejs-editable\">Entreprises vedettes</h3>\n        <div class=\"carousel-controls\">\n          <a href=\"#\" aria-label=\"Précédent\" id=\"iavfm\" class=\"carousel-btn prev-btn\">\n            <i class=\"fas fa-chevron-left\"></i>\n          </a>\n          <a href=\"#\" aria-label=\"Suivant\" id=\"i7sxt\" class=\"carousel-btn next-btn\">\n            <i class=\"fas fa-chevron-right\"></i>\n          </a>\n        </div>\n      </div>\n      <div id=\"entreprises-carousel\" class=\"carousel-items\">\n        <!-- Entreprise 1 -->\n        <div src=\"data:image/svg+xml;base64,\" class=\"carousel-item grapejs-editable\">\n          <img src=\"https://images.unsplash.com/photo-1497366754035-f200968a6e72?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=500&amp;q=80\" alt=\"Entreprise québécoise\" class=\"carousel-item-img\" />\n          <div class=\"carousel-item-content\">\n            <h4 class=\"carousel-item-title grapejs-editable\">Sirop d\'érable Tradition</h4>\n            <p class=\"carousel-item-description grapejs-editable\">Producteur artisanal de sirop d\'érable depuis 3 générations dans les Cantons-de-l\'Est.</p>\n            <div class=\"carousel-item-meta\">\n              <span class=\"grapejs-editable\">Cantons-de-l\'Est</span>\n              <span class=\"carousel-item-rating grapejs-editable\">★★★★★</span>\n            </div>\n          </div>\n        </div>\n        <!-- Entreprise 2 -->\n        <div class=\"carousel-item\">\n          <img src=\"https://images.unsplash.com/photo-1516321318423-f06f85e504b3?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=500&amp;q=80\" alt=\"Entreprise technologique\" class=\"carousel-item-img\" />\n          <div class=\"carousel-item-content\">\n            <h4 class=\"carousel-item-title grapejs-editable\">TechQuébec Solutions</h4>\n            <p class=\"carousel-item-description grapejs-editable\">Innovateur en intelligence artificielle basé à Montréal, leader dans son domaine.</p>\n            <div class=\"carousel-item-meta\">\n              <span class=\"grapejs-editable\">Montréal</span>\n              <span class=\"carousel-item-rating\">★★★★☆</span>\n            </div>\n          </div>\n        </div>\n        <!-- Entreprise 3 -->\n        <div class=\"carousel-item\">\n          <img src=\"https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=500&amp;q=80\" alt=\"Fromagerie artisanale\" class=\"carousel-item-img\" />\n          <div class=\"carousel-item-content\">\n            <h4 class=\"carousel-item-title grapejs-editable\">Fromagerie du Vieux-Québec</h4>\n            <p class=\"carousel-item-description grapejs-editable\">Fromagerie artisanale produisant des fromages fins primés internationalement.</p>\n            <div class=\"carousel-item-meta\">\n              <span class=\"grapejs-editable\">Québec</span>\n              <span class=\"carousel-item-rating\">★★★★★</span>\n            </div>\n          </div>\n        </div>\n        <!-- Entreprise 4 -->\n        <div class=\"carousel-item\">\n          <img src=\"https://images.unsplash.com/photo-1530122037265-a5f1f91d3b99?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=500&amp;q=80\" alt=\"Entreprise de plein air\" class=\"carousel-item-img\" />\n          <div class=\"carousel-item-content\">\n            <h4 class=\"carousel-item-title grapejs-editable\">Aventures Boréales</h4>\n            <p class=\"carousel-item-description grapejs-editable\">Organisateur d\'expéditions de plein air et d\'écotourisme dans le nord du Québec.</p>\n            <div class=\"carousel-item-meta\">\n              <span class=\"grapejs-editable\">Saguenay-Lac-St-Jean</span>\n              <span class=\"carousel-item-rating\">★★★★☆</span>\n            </div>\n          </div>\n        </div>\n        <!-- Entreprise 5 -->\n        <div class=\"carousel-item\">\n          <img src=\"https://images.unsplash.com/photo-1556228453-efd6c1ff04f6?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=500&amp;q=80\" alt=\"Brasserie artisanale\" class=\"carousel-item-img\" />\n          <div class=\"carousel-item-content\">\n            <h4 class=\"carousel-item-title grapejs-editable\">Microbrasserie Boréale</h4>\n            <p class=\"carousel-item-description grapejs-editable\">Brasserie artisanale renommée pour ses bières inspirées des saveurs québécoises.</p>\n            <div class=\"carousel-item-meta\">\n              <span class=\"grapejs-editable\">Gaspésie</span>\n              <span class=\"carousel-item-rating\">★★★★★</span>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n    <!-- Carrousel 2: Régions -->\n    <section class=\"carousel-container\">\n      <div class=\"carousel-header\">\n        <h3 class=\"carousel-title grapejs-editable\">Régions à découvrir</h3>\n        <div class=\"carousel-controls\">\n          <a href=\"#\" aria-label=\"Précédent\" id=\"iuhnm\" class=\"carousel-btn prev-btn\">\n            <i class=\"fas fa-chevron-left\"></i>\n          </a>\n          <a href=\"#\" aria-label=\"Suivant\" id=\"in7pv\" class=\"carousel-btn next-btn\">\n            <i class=\"fas fa-chevron-right\"></i>\n          </a>\n        </div>\n      </div>\n      <div id=\"regions-carousel\" class=\"carousel-items\">\n        <!-- Région 1 -->\n        <div class=\"carousel-item\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Vieux-Québec\" class=\"carousel-item-img\" />\n          <div class=\"carousel-item-content\">\n            <h4 class=\"carousel-item-title grapejs-editable\">Vieux-Québec</h4>\n            <p class=\"carousel-item-description grapejs-editable\">Seule ville fortifiée en Amérique du Nord, patrimoine mondial de l\'UNESCO.</p>\n            <div class=\"carousel-item-meta\">\n              <span class=\"grapejs-editable\">Québec</span>\n              <span class=\"carousel-item-rating\">★★★★★</span>\n            </div>\n          </div>\n        </div>\n        <!-- Région 2 -->\n        <div class=\"carousel-item\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Montréal\" class=\"carousel-item-img\" />\n          <div class=\"carousel-item-content\">\n            <h4 class=\"carousel-item-title grapejs-editable\">Montréal métropolitain</h4>\n            <p class=\"carousel-item-description grapejs-editable\">Ville vibrante alliant histoire, culture, gastronomie et vie nocturne animée.</p>\n            <div class=\"carousel-item-meta\">\n              <span class=\"grapejs-editable\">Montréal</span>\n              <span class=\"carousel-item-rating\">★★★★★</span>\n            </div>\n          </div>\n        </div>\n        <!-- Région 3 -->\n        <div class=\"carousel-item\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Charlevoix\" class=\"carousel-item-img\" />\n          <div class=\"carousel-item-content\">\n            <h4 class=\"carousel-item-title grapejs-editable\">Charlevoix</h4>\n            <p class=\"carousel-item-description grapejs-editable\">Région reconnue pour ses paysages magnifiques, sa gastronomie et ses artistes.</p>\n            <div class=\"carousel-item-meta\">\n              <span class=\"grapejs-editable\">Charlevoix</span>\n              <span class=\"carousel-item-rating\">★★★★★</span>\n            </div>\n          </div>\n        </div>\n        <!-- Région 4 -->\n        <div class=\"carousel-item\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Gaspésie\" class=\"carousel-item-img\" />\n          <div class=\"carousel-item-content\">\n            <h4 class=\"carousel-item-title grapejs-editable\">Gaspésie</h4>\n            <p class=\"carousel-item-description grapejs-editable\">Péninsule sauvage offrant des paysages côtiers spectaculaires et une faune riche.</p>\n            <div class=\"carousel-item-meta\">\n              <span class=\"grapejs-editable\">Gaspésie</span>\n              <span class=\"carousel-item-rating\">★★★★☆</span>\n            </div>\n          </div>\n        </div>\n        <!-- Région 5 -->\n        <div class=\"carousel-item\">\n          <img src=\"https://images.unsplash.com/photo-1544551763-46a013bb70d5?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=500&amp;q=80\" alt=\"Cantons-de-l\'Est\" class=\"carousel-item-img\" />\n          <div class=\"carousel-item-content\">\n            <h4 class=\"carousel-item-title grapejs-editable\">Cantons-de-l\'Est</h4>\n            <p class=\"carousel-item-description grapejs-editable\">Région de collines verdoyantes, vignobles, érablières et villages pittoresques.</p>\n            <div class=\"carousel-item-meta\">\n              <span class=\"grapejs-editable\">Cantons-de-l\'Est</span>\n              <span class=\"carousel-item-rating\">★★★★☆</span>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n    <!-- Section Liens rapides -->\n    <sectio