-top-right-radius:16px;border-bottom-right-radius:16px;border-bottom-left-radius:16px;}#ifxbem{background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(26, 188, 156);}#iyl5hi{background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(230, 126, 34);}#ilq55l{background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(139, 69, 19);}#iptoqm-2{outline-color:rgba(67, 97, 238, 0.5);color:rgb(33, 37, 41);background-color:rgb(255, 255, 255);}#i5eqa-2{outline-color:rgba(67, 97, 238, 0.5);color:rgb(33, 37, 41);}#i24ujs-2{outline-color:rgba(67, 97, 238, 0.5);color:rgb(33, 37, 41);}#i24ujs-3{outline-color:rgba(67, 97, 238, 0.5);color:rgb(33, 37, 41);}#i24ujs-4{outline-color:rgba(67, 97, 238, 0.5);color:rgb(33, 37, 41);}#i24ujs-5{outline-color:rgba(67, 97, 238, 0.5);color:rgb(33, 37, 41);}#i0mzbs{background-color:rgb(255, 255, 255);font-size:1.8rem;}#ifbnk8{font-size:1.8rem;background-color:initial;}#isqu1h{font-size:1.8rem;background-color:initial;}#ietkw6{font-size:1.8rem;background-color:initial;}#ifqnic{background-color:rgb(255, 255, 255);font-size:1.8rem;}#iaxadi{font-size:1.8rem;background-color:initial;}#i029u5{font-size:1.8rem;background-color:initial;}#ig8tat{font-size:1.8rem;background-color:initial;}#i6czur-2{font-weight:500;}#i57n0q-2{color:rgb(26, 188, 156);font-size:1.8rem;}#i6czur-2-2{font-weight:500;}#ih6x52-3{background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial