ign:start;background-color:rgb(255, 255, 255);}#iteun2-2{color:rgb(51, 51, 51);font-family:Lato, Arial, Helvetica, sans-serif;font-size:18.6667px;text-align:-webkit-left;}#is9b7z-2{font-size:14pt;}#i7a539-2{font-variant-numeric:normal;font-variant-east-asian:normal;font-variant-alternates:normal;font-variant-position:normal;font-variant-emoji:normal;}#i01vro-2{line-height:110%;margin-top:0.42cm;margin-bottom:0.21cm;}#iteun2-2-2{color:rgb(51, 51, 51);font-family:Lato, Arial, Helvetica, sans-serif;font-size:18.6667px;text-align:-webkit-left;}#ioteka-2{text-align:center;background-color:rgb(245, 247, 255);}#ilpj0l{font-size:14pt;}#iuqhco{line-height:110%;margin-top:0.42cm;margin-bottom:0.21cm;}#i4c29o{line-height:110%;margin-top:0.42cm;margin-bottom:0.21cm;}#ipwpgy{font-size:26.6667px;}@keyframes snowfall{0%{transform:translateY(-10px) rotate(0deg);}100%{transform:translateY(100vh) rotate(360deg);}}@media (max-width: 1200px){.language-grid{grid-template-columns:repeat(2, 1fr);}}@media (max-width: 992px){.plans-container{grid-template-columns:repeat(auto-fit, minmax(280px, 1fr));}}@media (max-width: 768px){.section-title{font-size:2.2rem;}.plan-card{max-width:400px;margin-top:0px;margin-right:auto;margin-bottom:0px;margin-left:auto;}.showcase-header h2{font-size:2.2rem;}.language-header h2{font-size:2.2rem;}.language-grid{grid-template-columns:1fr;}.language-section{padding-top:40px;padding-right:25px;padding-bottom:40px;padding-left:25px;}}@media (max-width: 576px){.section-header{margin-bottom:40px;}.section-title{font-size:1.9rem;}.plan-price{font-size:2.5rem;}}', '{\"title\": \"🎢Plans Web et Affichage Prime Time\", \"keywords\": \"🎢Plans Web et Affichage Prime Time, tourisme, voyage\", \"description\": \"Page de 🎢Plans Web et Affichage Prime Time\"}', 'draft', 'plans-web-affichage-prime-time-Sp1L8x', '2026-02-02 12:19:05', '2026-02-19 22:18:23');
INSERT INTO `menus` (`id`, `title`, `slug`, `type`, `parent_id`, `reference_id`, `menu_type`, `order`, `route`, `url`, `icon`, `is_active`, `has_page`, `page_id`, `page_content`, `page_styles`, `page_meta`, `page_status`, `page_slug`, `created_at`, `updated_at`) VALUES
(9, '🎥 Mes chaînes vidéos-photos', 'mes-chaines-videos-photos-go-exploria', 'custom', NULL, NULL, 'Accueil', 7, NULL, '#mes-chaines-videos-photos-go-exploria', NULL, 1, 1, NULL, '    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n<body>\n    <div class=\"container\">\n        <div class=\"section-title\">\n            <h1>Lecteur Media Slideshow</h1>\n            <p>Découvrez notre collection multimédia avec ce lecteur moderne et interactif. Naviguez entre les différents médias avec des animations fluides.</p>\n        </div>\n        \n        <div class=\"slideshow-player\">\n            <div class=\"player-header\">\n                <div class=\"player-title\">\n                    <i class=\"fas fa-play-circle\"></i>\n                    <span>Galerie Multimédia Premium</span>\n                </div>\n                \n                <div class=\"player-controls\">\n                    <a href=\"#\" class=\"control-btn active\" id=\"btn-all\" title=\"Tous les médias\">\n                        <i class=\"fas fa-th-large\"></i>\n                    </a>\n                    <a href=\"#\" class=\"control-btn\" id=\"btn-photos\" title=\"Photos seulement\">\n                        <i class=\"fas fa-image\"></i>\n                    </a>\n                    <a href=\"#\" class=\"control-btn\" id=\"btn-videos\" title=\"Vidéos seulement\">\n                        <i class=\"fas fa-video\"></i>\n                    </a>\n                </div>\n            </div>\n            \n            <div class=\"player-body\">\n                <div class=\"media-display\">\n                    <div class=\"media-container\">\n                        <!-- Les médias sont insérés dynamiquement par JavaScript -->\n                    </div>\n                    \n                    <div class=\"media-info\">\n                        <h2 class=\"media-title\">Titre du média</h2>\n                        <p class=\"media-description\">Description du média actuellement affiché</p>\n                    </div>\n                </div>\n                \n                <div class=\"media-sidebar\">\n                    <div class=\"media-thumbnails\">\n                        <!-- Les vignettes sont insérées dynamiquement par JavaScript -->\n                    </div>\n                </div>\n            </div>\n            \n            <div class=\"player-footer\">\n                <div class=\"progress-container\">\n                    <div class=\"progress-bar\" id=\"progress-bar\">\n                        <div class=\"progress-fill\" id=\"progress-fill\"></div>\n                    </div>\n                    <div class=\"time-info\">\n                        <span id=\"current-time\">0:00</span>\n                        <span id=\"total-time\">0:00</span>\n                    </div>\n                </div>\n                \n                <div class=\"media-counter\">\n                    <span class=\"counter-current\" id=\"current-slide\">1</span>\n                    <span class=\"counter-separator\">/</span>\n                    <span class=\"counter-total\" id=\"total-slides\">5</span>\n                </div>\n                \n                <div class=\"player-actions\">\n                    <a href=\"#\" class=\"action-btn\" id=\"btn-prev\" title=\"Précédent\">\n                        <i class=\"fas fa-step-backward\"></i>\n                    </a>\n                    <a href=\"#\" class=\"action-btn play-pause pulse-effect\" id=\"btn-play-pause\" title=\"Lecture/Pause\">\n                        <i class=\"fas fa-play\" id=\"play-icon\"></i>\n                    </a>\n                    <a href=\"#\" class=\"action-btn\" id=\"btn-next\" title=\"Suivant\">\n                        <i class=\"fas fa-step-forward\"></i>\n                    </a>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        // Données des médias\n        const mediaData = [\n            {\n                id: 1,\n                type: \"image\",\n                title: \"Paysage Montagneux\",\n                description: \"Un magnifique panorama de montagnes enneigées au coucher du soleil.\",\n                src: \"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1350&q=80\",\n                thumbnail: \"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=300&q=80\",\n                duration: null\n            },\n            {\n                id: 2,\n                type: \"video\",\n                title: \"Forêt Tropicale\",\n                description: \"Explorez la beauté d\'une forêt tropicale luxuriante avec ses cascades.\",\n                src: \"https://assets.mixkit.co/videos/preview/mixkit-waterfall-in-forest-2213-large.mp4\",\n                thumbnail: \"https://images.unsplash.com/photo-1441974231531-c6227db76b6e?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=300&q=80\",\n                duration: \"0:15\"\n            },\n            {\n                id: 3,\n                type: \"image\",\n                title: \"Ville Nocturne\",\n                description: \"Lumières étincelantes d\'une métropole moderne la nuit.\",\n                src: \"https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1350&q=80\",\n                thumbnail: \"https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=300&q=80\",\n                duration: null\n            },\n            {\n                id: 4,\n                type: \"video\",\n                title: \"Océan et Vagues\",\n                description: \"Les vagues puissantes de l\'océan s\'écrasant sur les rochers.\",\n                src: \"https://assets.mixkit.co/videos/preview/mixkit-sea-waves-crashing-on-rocks-2222-large.mp4\",\n                thumbnail: \"https://images.unsplash.com/photo-1505142468610-359e7d316be0?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=300&q=80\",\n                duration: \"0:12\"\n            },\n            {\n                id: 5,\n                type: \"image\",\n                title: \"Désert et Ciel Étoilé\",\n                description: \"Une nuit étoilée au-dessus des dunes de sable du désert.\",\n                src: \"https://images.unsplash.com/photo-1519681393784-d120267933ba?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1350&q=80\",\n                thumbnail: \"https://images.unsplash.com/photo-1519681393784-d120267933ba?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=300&q=80\",\n                duration: null\n            }\n        ];\n\n        // Variables globales\n        let currentSlide = 0;\n        let totalSlides = mediaData.length;\n        let isPlaying = false;\n        let playInterval;\n        let currentMediaType = \'all\';\n        let filteredMedia = [...mediaData];\n\n        // Initialisation\n        document.addEventListener(\'DOMContentLoaded\', function() {\n            initSlideshow();\n            setupEventListeners();\n            updateSlideshow();\n            updateProgressBar();\n        });\n\n        // Initialisation du slideshow\n        function initSlideshow() {\n            const mediaContainer = document.querySelector(\'.media-container\');\n            const thumbnailsContainer = document.querySelector(\'.media-thumbnails\');\n            \n            // Afficher le total des slides\n            document.getElementById(\'total-slides\').textContent = totalSlides;\n            \n            // Créer les éléments médias\n            mediaData.forEach((media, index) => {\n                // Créer l\'élément média principal\n                let mediaElement;\n                if (media.type === \'image\') {\n                    mediaElement = document.createElement(\'img\');\n                    mediaElement.src = media.src;\n                    mediaElement.alt = media.title;\n                    mediaElement.classList.add(\'media-item\');\n                } else if (media.type === \'video\') {\n                    mediaElement = document.createElement(\'video\');\n                    mediaElement.src = media.src;\n                    mediaElement.controls = true;\n                    mediaElement.classList.add(\'media-item\');\n                    \n                    // Mettre à jour la durée de la vidéo lorsqu\'elle est chargée\n                    mediaElement.addEventListener(\'loadedmetadata\', function() {\n                        updateVideoDuration(index, mediaElement.duration);\n                    });\n                }\n                \n                if (index === 0) mediaElement.classList.add(\'active\');\n                mediaContainer.appendChild(mediaElement);\n                \n                // Créer la vignette\n                const thumbnailItem = document.createElement(\'div\');\n                thumbnailItem.classList.add(\'thumbnail-item\');\n                if (index === 0) thumbnailItem.classList.add(\'active\');\n                thumbnailItem.dataset.index = index;\n                \n                thumbnailItem.innerHTML = `\n                    <div class=\"thumbnail-img\">\n                        <img src=\"${media.thumbnail}\" alt=\"${media.title}\">\n                    </div>\n                    <div class=\"thumbnail-info\">\n                        <h4>${media.title}</h4>\n                        <p>${media.type === \'image\' ? \'Image\' : \'Vidéo\'} ${media.duration ? \' • \' + media.duration : \'\'}</p>\n                    </div>\n                `;\n                \n                thumbnailsContainer.appendChild(thumbnailItem);\n                \n                // Ajouter l\'événement de clic sur la vignette\n                thumbnailItem.addEventListener(\'click\', function() {\n                    const index = parseInt(this.dataset.index);\n                    goToSlide(index);\n                });\n            });\n            \n            // Mettre à jour les informations du premier média\n            updateMediaInfo(0);\n        }\n\n        // Configuration des événements\n        function setupEventListeners() {\n            // Boutons de contrôle\n            document.getElementById(\'btn-all\').addEventListener(\'click\', function() {\n                setMediaFilter(\'all\');\n                updateActiveFilterButton(this);\n            });\n            \n            document.getElementById(\'btn-photos\').addEventListener(\'click\', function() {\n                setMediaFilter(\'image\');\n                updateActiveFilterButton(this);\n            });\n            \n            document.getElementById(\'btn-videos\').addEventListener(\'click\', function() {\n                setMediaFilter(\'video\');\n                updateActiveFilterButton(this);\n            });\n            \n            // Boutons de navigation\n            document.getElementById(\'btn-prev\').addEventListener(\'click\', prevSlide);\n            document.getElementById(\'btn-next\').addEventListener(\'click\', nextSlide);\n            document.getElementById(\'btn-play-pause\').addEventListener(\'click\', togglePlayPause);\n            \n            // Barre de progression\n            const progressBar = document.getElementById(\'progress-bar\');\n            progressBar.addEventListener(\'click\', function(e) {\n                const rect = this.getBoundingClientRect();\n                const pos = (e.clientX - rect.left) / this.offsetWidth;\n                const slideIndex = Math.floor(pos * filteredMedia.length);\n                goToSlide(slideIndex);\n            });\n            \n            // Touches du clavier\n            document.addEventListener(\'keydown\', function(e) {\n                switch(e.key) {\n                    case \'ArrowLeft\':\n                        prevSlide();\n                        break;\n                    case \'ArrowRight\':\n                        nextSlide();\n                        break;\n                    case \' \':\n                        e.preventDefault();\n                        togglePlayPause();\n                        break;\n                }\n            });\n        }\n\n        // Navigation entre les slides\n        function goToSlide(index) {\n            // S\'assurer que l\'index est dans les limites\n            if (index < 0) index = filteredMedia.length - 1;\n            if (index >= filteredMedia.length) index = 0;\n            \n            // Obtenir l\'index réel dans les données médias complètes\n            const realIndex = mediaData.findIndex(media => media.id === filteredMedia[index].id);\n            \n            // Mettre à jour le slide courant\n            currentSlide = realIndex;\n            \n            // Mettre à jour l\'affichage\n            updateSlideshow();\n            \n            // Réinitialiser l\'intervalle de lecture si en mode lecture\n            if (isPlaying) {\n                clearInterval(playInterval);\n                startAutoPlay();\n            }\n        }\n\n        function nextSlide() {\n            let nextIndex = filteredMedia.findIndex(media => media.id === mediaData[currentSlide].id) + 1;\n            if (nextIndex >= filteredMedia.length) nextIndex = 0;\n            \n            const realIndex = mediaData.findIndex(media => media.id === filteredMedia[nextIndex].id);\n            goToSlide(realIndex);\n        }\n\n        function prevSlide() {\n            let prevIndex = filteredMedia.findIndex(media => media.id === mediaData[currentSlide].id) - 1;\n            if (prevIndex < 0) prevIndex = filteredMedia.length - 1;\n            \n            const realIndex = mediaData.findIndex(media => media.id === filteredMedia[prevIndex].id);\n            goToSlide(realIndex);\n        }\n\n        // Lecture automatique\n        function startAutoPlay() {\n            clearInterval(playInterval);\n            playInterval = setInterval(nextSlide, 5000); // Change de slide toutes les 5 secondes\n        }\n\n        function togglePlayPause() {\n            const playPauseBtn = document.getElementById(\'btn-play-pause\');\n            const playIcon = document.getElementById(\'play-icon\');\n            \n            if (isPlaying) {\n                // Mettre en pause\n                clearInterval(playInterval);\n                playIcon.classList.remove(\'fa-pause\');\n                playIcon.classList.add(\'fa-play\');\n                playPauseBtn.classList.add(\'pulse-effect\');\n                isPlaying = false;\n                \n                // Mettre en pause la vidéo si c\'est une vidéo\n                const currentMedia = document.querySelector(\'.media-item.active\');\n                if (currentMedia.tagName === \'VIDEO\') {\n                    currentMedia.pause();\n                }\n            } else {\n                // Lancer la lecture\n                startAutoPlay();\n                playIcon.classList.remove(\'fa-play\');\n                playIcon.classList.add(\'fa-pause\');\n                playPauseBtn.classList.remove(\'pulse-effect\');\n                isPlaying = true;\n                \n                // Lancer la vidéo si c\'est une vidéo\n                const currentMedia = document.querySelector(\'.media-item.active\');\n                if (currentMedia.tagName === \'VIDEO\') {\n                    currentMedia.play();\n                }\n            }\n        }\n\n        // Filtrage des médias\n        function setMediaFilter(type) {\n            currentMediaType = type;\n            \n            if (type === \'all\') {\n                filteredMedia = [...mediaData];\n            } else {\n                filteredMedia = mediaData.filter(media => media.type === type);\n            }\n            \n            // Réinitialiser au premier slide après filtrage\n            currentSlide = mediaData.findIndex(media => media.id === filteredMedia[0].id);\n            \n            // Mettre à jour l\'affichage\n            updateSlideshow();\n            updateThumbnails();\n            \n            // Mettre à jour le compteur\n            document.getElementById(\'total-slides\').textContent = filteredMedia.length;\n            \n            // Réinitialiser la lecture si active\n            if (isPlaying) {\n                clearInterval(playInterval);\n                startAutoPlay();\n            }\n        }\n\n        function updateActiveFilterButton(activeButton) {\n            // Retirer la classe active de tous les boutons de filtre\n            document.querySelectorAll(\'.control-btn\').forEach(btn => {\n                btn.classList.remove(\'active\');\n            });\n            \n            // Ajouter la classe active au bouton cliqué\n            activeButton.classList.add(\'active\');\n        }\n\n        // Mise à jour de l\'affichage\n        function updateSlideshow() {\n            // Mettre à jour le média affiché\n            const mediaItems = document.querySelectorAll(\'.media-item\');\n            mediaItems.forEach((item, index) => {\n                item.classList.remove(\'active\');\n                if (index === currentSlide) {\n                    item.classList.add(\'active\');\n                    \n                    // Si c\'est une vidéo et que le mode lecture est activé, la lancer\n                    if (isPlaying && item.tagName === \'VIDEO\') {\n                        item.play();\n                    }\n                }\n            });\n            \n            // Mettre à jour les informations du média\n            updateMediaInfo(currentSlide);\n            \n            // Mettre à jour le compteur de slide\n            const slideIndexInFiltered = filteredMedia.findIndex(media => media.id === mediaData[currentSlide].id);\n            document.getElementById(\'current-slide\').textContent = slideIndexInFiltered + 1;\n            \n            // Mettre à jour les vignettes actives\n            updateActiveThumbnail();\n            \n            // Mettre à jour la barre de progression\n            updateProgressBar();\n        }\n\n        function updateMediaInfo(index) {\n            const media = mediaData[index];\n            document.querySelector(\'.media-title\').textContent = media.title;\n            document.querySelector(\'.media-description\').textContent = media.description;\n        }\n\n        function updateThumbnails() {\n            const thumbnailItems = document.querySelectorAll(\'.thumbnail-item\');\n            thumbnailItems.forEach(item => {\n                const index = parseInt(item.dataset.index);\n                const media = mediaData[index];\n                \n                // Afficher ou masquer selon le filtre\n                if (currentMediaType === \'all\' || media.type === currentMediaType) {\n                    item.style.display = \'flex\';\n                } else {\n                    item.style.display = \'none\';\n                }\n            });\n        }\n\n        function updateActiveThumbnail() {\n            const thumbnailItems = document.querySelectorAll(\'.thumbnail-item\');\n            thumbnailItems.forEach(item => {\n                const index = parseInt(item.dataset.index);\n                item.classList.remove(\'active\');\n                if (index === currentSlide) {\n                    item.classList.add(\'active\');\n                    \n                    // Faire défiler jusqu\'à la vignette active\n                    item.scrollIntoView({ behavior: \'smooth\', block: \'nearest\', inline: \'center\' });\n                }\n            });\n        }\n\n        function updateProgressBar() {\n            const slideIndexInFiltered = filteredMedia.findIndex(media => media.id === mediaData[currentSlide].id);\n            const progressPercent = ((slideIndexInFiltered + 1) / filteredMedia.length) * 100;\n            document.getElementById(\'progress-fill\').style.width = `${progressPercent}%`;\n            \n            // Mettre à jour le temps actuel et total\n            document.getElementById(\'current-time\').textContent = formatTime(slideIndexInFiltered + 1);\n            document.getElementById(\'total-time\').textContent = formatTime(filteredMedia.length);\n        }\n\n        function updateVideoDuration(index, duration) {\n            // Formater la durée de la vidéo\n            const minutes = Math.floor(duration / 60);\n            const seconds = Math.floor(duration % 60);\n            const formattedDuration = `${minutes}:${seconds < 10 ? \'0\' : \'\'}${seconds}`;\n            \n            // Mettre à jour les données\n            mediaData[index].duration = formattedDuration;\n            \n            // Mettre à jour l\'affichage de la vignette si c\'est le média actuel\n            if (index === currentSlide) {\n                const thumbnailItems = document.querySelectorAll(\'.thumbnail-item\');\n                thumbnailItems[index].querySelector(\'.thumbnail-info p\').textContent = \n                    `Vidéo • ${formattedDuration}`;\n            }\n        }\n\n        function formatTime(value) {\n            // Simuler un format de temps basé sur l\'index\n            const minutes = Math.floor(value / 2);\n            const seconds = (value % 2) * 30;\n            return `${minutes}:${seconds < 10 ? \'0\' : \'\'}${seconds}`;\n        }\n    </script>\n</body>', '* {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n            font-family: \'Segoe UI\', system-ui, -apple-system, sans-serif;\n        }\n        \n        body {\n            background: linear-gradient(135deg, #0f2027 0%, #203a43 50%, #2c5364 100%);\n            color: #fff;\n            min-height: 100vh;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            padding: 20px;\n        }\n        \n        .container {\n            max-width: 1200px;\n            width: 100%;\n            margin: 0 auto;\n        }\n        \n        .section-title {\n            text-align: center;\n            margin-bottom: 40px;\n            position: relative;\n        }\n        \n        .section-title h1 {\n            font-size: 2.8rem;\n            font-weight: 700;\n            background: linear-gradient(90deg, #00dbde, #fc00ff);\n            -webkit-background-clip: text;\n            background-clip: text;\n            color: transparent;\n            margin-bottom: 15px;\n            letter-spacing: 1px;\n        }\n        \n        .section-title p {\n            font-size: 1.2rem;\n            color: #b0c4de;\n            max-width: 600px;\n            margin: 0 auto;\n            line-height: 1.6;\n        }\n        \n        .slideshow-player {\n            background: rgba(15, 25, 35, 0.85);\n            border-radius: 20px;\n            overflow: hidden;\n            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.5);\n            backdrop-filter: blur(10px);\n            border: 1px solid rgba(255, 255, 255, 0.1);\n        }\n        \n        .player-header {\n            padding: 25px 30px;\n            border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            background: rgba(0, 0, 0, 0.2);\n        }\n        \n        .player-title {\n            font-size: 1.8rem;\n            font-weight: 600;\n            display: flex;\n            align-items: center;\n            gap: 12px;\n        }\n        \n        .player-title i {\n            color: #00dbde;\n            font-size: 2rem;\n        }\n        \n        .player-controls {\n            display: flex;\n            gap: 15px;\n        }\n        \n        .control-btn {\n            background: rgba(255, 255, 255, 0.1);\n            border: none;\n            color: white;\n            width: 45px;\n            height: 45px;\n            border-radius: 50%;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            cursor: pointer;\n            font-size: 1.2rem;\n            transition: all 0.3s ease;\n            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);\n        }\n        \n        .control-btn:hover {\n            background: rgba(255, 255, 255, 0.2);\n            transform: translateY(-3px);\n        }\n        \n        .control-btn.active {\n            background: linear-gradient(135deg, #00dbde, #fc00ff);\n            color: white;\n        }\n        \n        .player-body {\n            display: flex;\n            min-height: 500px;\n        }\n        \n        .media-display {\n            flex: 1;\n            padding: 30px;\n            display: flex;\n            flex-direction: column;\n            justify-content: center;\n            align-items: center;\n            background: rgba(0, 0, 0, 0.3);\n            position: relative;\n            overflow: hidden;\n        }\n        \n        .media-container {\n            width: 100%;\n            max-width: 800px;\n            border-radius: 15px;\n            overflow: hidden;\n            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);\n            position: relative;\n            animation: fadeIn 0.8s ease-out;\n        }\n        \n        @keyframes fadeIn {\n            from { opacity: 0; transform: scale(0.95); }\n            to { opacity: 1; transform: scale(1); }\n        }\n        \n        .media-item {\n            display: none;\n            width: 100%;\n            height: auto;\n        }\n        \n        .media-item.active {\n            display: block;\n            animation: slideIn 0.8s ease-out;\n        }\n        \n        @keyframes slideIn {\n            from { opacity: 0; transform: translateX(30px); }\n            to { opacity: 1; transform: translateX(0); }\n        }\n        \n        .media-item img, .media-item video {\n            width: 100%;\n            height: auto;\n            display: block;\n        }\n        \n        .media-info {\n            padding: 20px 0;\n            text-align: center;\n            width: 100%;\n            max-width: 800px;\n        }\n        \n        .media-title {\n            font-size: 1.8rem;\n            font-weight: 600;\n            margin-bottom: 10px;\n            color: #fff;\n        }\n        \n        .media-description {\n            color: #b0c4de;\n            font-size: 1.1rem;\n            line-height: 1.6;\n        }\n        \n        .media-sidebar {\n            width: 300px;\n            padding: 25px;\n            border-left: 1px solid rgba(255, 255, 255, 0.1);\n            background: rgba(0, 0, 0, 0.2);\n            overflow-y: auto;\n            max-height: 500px;\n        }\n        \n        .media-thumbnails {\n            display: flex;\n            flex-direction: column;\n            gap: 15px;\n        }\n        \n        .thumbnail-item {\n            display: flex;\n            align-items: center;\n            gap: 15px;\n            padding: 12px;\n            border-radius: 10px;\n            cursor: pointer;\n            transition: all 0.3s ease;\n            background: rgba(255, 255, 255, 0.05);\n            border: 1px solid transparent;\n        }\n        \n        .thumbnail-item:hover {\n            background: rgba(255, 255, 255, 0.1);\n            transform: translateX(5px);\n        }\n        \n        .thumbnail-item.active {\n            background: rgba(0, 219, 222, 0.15);\n            border-color: #00dbde;\n        }\n        \n        .thumbnail-img {\n            width: 80px;\n            height: 60px;\n            border-radius: 8px;\n            overflow: hidden;\n            flex-shrink: 0;\n        }\n        \n        .thumbnail-img img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n        }\n        \n        .thumbnail-info h4 {\n            font-size: 1rem;\n            font-weight: 600;\n            margin-bottom: 5px;\n        }\n        \n        .thumbnail-info p {\n            font-size: 0.85rem;\n            color: #a0b3d0;\n        }\n        \n        .player-footer {\n            padding: 20px 30px;\n            border-top: 1px solid rgba(255, 255, 255, 0.1);\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            background: rgba(0, 0, 0, 0.2);\n        }\n        \n        .progress-container {\n            flex: 1;\n            margin-right: 30px;\n        }\n        \n        .progress-bar {\n            height: 8px;\n            background: rgba(255, 255, 255, 0.1);\n            border-radius: 4px;\n            overflow: hidden;\n            margin-bottom: 8px;\n            cursor: pointer;\n        }\n        \n        .progress-fill {\n            height: 100%;\n            background: linear-gradient(90deg, #00dbde, #fc00ff);\n            border-radius: 4px;\n            width: 30%;\n            transition: width 0.3s ease;\n            position: relative;\n        }\n        \n        .progress-fill::after {\n            content: \'\';\n            position: absolute;\n            right: 0;\n            top: 50%;\n            transform: translateY(-50%);\n            width: 16px;\n            height: 16px;\n            background: white;\n            border-radius: 50%;\n            box-shadow: 0 0 10px rgba(0, 219, 222, 0.8);\n        }\n        \n        .time-info {\n            display: flex;\n            justify-content: space-between;\n            font-size: 0.9rem;\n            color: #b0c4de;\n        }\n        \n        .player-actions {\n            display: flex;\n            gap: 10px;\n        }\n        \n        .action-btn {\n            background: rgba(255, 255, 255, 0.1);\n            border: none;\n            color: white;\n            width: 50px;\n            height: 50px;\n            border-radius: 50%;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            cursor: pointer;\n            font-size: 1.3rem;\n            transition: all 0.3s ease;\n        }\n        \n        .action-btn:hover {\n            background: linear-gradient(135deg, #00dbde, #fc00ff);\n            transform: scale(1.1);\n        }\n        \n        .action-btn.play-pause {\n            width: 60px;\n            height: 60px;\n            font-size: 1.6rem;\n            background: linear-gradient(135deg, #00dbde, #fc00ff);\n        }\n        \n        .media-counter {\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-size: 1.1rem;\n            color: #b0c4de;\n            gap: 10px;\n        }\n        \n        .counter-current {\n            font-size: 1.8rem;\n            font-weight: 700;\n            color: white;\n        }\n        \n        .counter-total {\n            font-size: 1.3rem;\n        }\n        \n        /* Animation pour le changement de slide */\n        @keyframes pulse {\n            0% { box-shadow: 0 0 0 0 rgba(0, 219, 222, 0.7); }\n            70% { box-shadow: 0 0 0 10px rgba(0, 219, 222, 0); }\n            100% { box-shadow: 0 0 0 0 rgba(0, 219, 222, 0); }\n        }\n        \n        .pulse-effect {\n            animation: pulse 1.5s infinite;\n        }\n        \n        /* Responsive */\n        @media (max-width: 992px) {\n            .player-body {\n                flex-direction: column;\n            }\n            \n            .media-sidebar {\n                width: 100%;\n                border-left: none;\n                border-top: 1px solid rgba(255, 255, 255, 0.1);\n                max-height: 300px;\n            }\n            \n            .media-thumbnails {\n                flex-direction: row;\n                overflow-x: auto;\n                padding-bottom: 10px;\n            }\n            \n            .thumbnail-item {\n                flex-direction: column;\n                min-width: 150px;\n            }\n            \n            .thumbnail-img {\n                width: 100%;\n                height: 100px;\n            }\n            a { \n                text-decoration: none;\n            }\n        }\n        \n        @media (max-width: 768px) {\n            .section-title h1 {\n                font-size: 2.2rem;\n            }\n            \n            .player-header {\n                flex-direction: column;\n                gap: 20px;\n                text-align: center;\n            }\n            \n            .player-footer {\n                flex-direction: column;\n                gap: 20px;\n            }\n            \n            .progress-container {\n                margin-right: 0;\n                width: 100%;\n            }\n            \n            .media-display {\n                padding: 15px;\n            }\n        }', NULL, 'draft', NULL, '2026-02-02 12:20:08', '2026-02-11 13:45:09');
INSERT INTO `menus` (`id`, `title`, `slug`, `type`, `parent_id`, `reference_id`, `menu_type`, `order`, `route`, `url`, `icon`, `is_active`, `has_page`, `page_id`, `page_content`, `page_styles`, `page_meta`, `page_status`, `page_slug`, `created_at`, `updated_at`) VALUES
(10, 'Partenaires Affiliés', 'partenaires-affilies', 'custom', NULL, NULL, 'Accueil', 3, NULL, '#partenaires-affilies', NULL, 1, 1, NULL, '<body><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\"/><div id=\"partners-section\" class=\"partners-section\"><!-- Background décoratif --><div class=\"section-background\"></div><!-- En-tête de la section --><div class=\"section-header\"><h1>Partenaires Master User Go Exploria</h1><p class=\"section-subtitle\">La plateforme ultime pour les professionnels du tourisme et de l\'événementiel</p><div class=\"highlight-slogan\"><h2>ACTIVEZ ET GÉREZ VOS DESTINATIONS ET VOS MARCHÉS</h2><p>Optimisez votre présence, développez vos activités et maximisez vos revenus avec nos outils professionnels.</p></div></div><!-- Contenu principal --><div class=\"section-content\"><!-- Colonne gauche : Avantages et fonctionnalités --><div class=\"features-column\"><h3>Fonctionnalités Principales</h3><div class=\"feature-card\"><div class=\"feature-icon\"><i class=\"fas fa-map-marked-alt\"></i></div><h4>Gestion Multi-Destinations</h4><p>Centralisez et gérez toutes vos destinations depuis une interface unique. Suivez les performances, ajustez vos stratégies et optimisez vos offres en temps réel.</p></div><div class=\"feature-card\"><div class=\"feature-icon\"><i class=\"fas fa-chart-network\"></i><i class=\"fas fa-tachometer-alt\"></i></div><h4>Analyse de Marché Avancée</h4><p>Accédez à des données market en temps réel, identifiez les tendances émergentes et prenez des décisions éclairées pour développer vos activités.</p></div><div class=\"feature-card\"><div class=\"feature-icon\"><i class=\"fas fa-users-cog\"></i></div><h4>Gestion des Partenaires</h4><p>Collaborez efficacement avec votre réseau de partenaires. Partagez des ressources, synchronisez les calendriers et travaillez en harmonie.</p></div><div class=\"feature-card\"><div class=\"feature-icon\"><i class=\"fas fa-file-invoice-dollar\"></i></div><h4>Facturation et Suivi Financier</h4><p>Générez des factures automatiques, suivez les paiements et analysez vos performances financières avec des rapports détaillés.</p></div></div><!-- Colonne droite : Dashboard et avantages --><div class=\"dashboard-column\"><!-- Dashboard preview --><div class=\"dashboard-preview\"><div class=\"dashboard-header\"><div class=\"dashboard-icon\"><i class=\"fas fa-tachometer-alt\"></i></div><h3>Tableau de Bord Master</h3></div><div class=\"dashboard-stats\"><div class=\"stat-item\"><div class=\"stat-value\">+87%</div><div class=\"stat-label\">Croissance du réseau</div></div><div class=\"stat-item\"><div class=\"stat-value\">156</div><div class=\"stat-label\">Destinations actives</div></div><div class=\"stat-item\"><div class=\"stat-value\">2.4M€</div><div class=\"stat-label\">Chiffre d\'affaires</div></div><div class=\"stat-item\"><div class=\"stat-value\">94%</div><div class=\"stat-label\">Satisfaction clients</div></div></div><div class=\"dashboard-cta\"></div></div><!-- Avantages --><h3>Avantages Exclusifs</h3><ul class=\"advantages-list\"><li><i class=\"fas fa-check-circle\"></i> <strong>Accès prioritaire</strong> aux nouvelles fonctionnalités et mises à jour\n                    </li><li><i class=\"fas fa-check-circle\"></i> <strong>Support dédié</strong> avec un conseiller personnel disponible 7j/7\n                    </li><li><i class=\"fas fa-check-circle\"></i> <strong>Formation complète</strong> et accompagnement pour maximiser votre ROI\n                    </li><li><i class=\"fas fa-check-circle\"></i> <strong>Réseau exclusif</strong> de partenaires et opportunités business\n                    </li><li><i class=\"fas fa-check-circle\"></i> <strong>Tarifs préférentiels</strong> sur les services premium et extensions\n                    </li></ul></div></div><!-- Section des partenaires --><div class=\"partners-showcase\"><h3>Ils nous font confiance</h3><div class=\"partners-grid\"><div class=\"partner-logo\"><i class=\"fas fa-hotel\"></i><span class=\"partner-name\">Hotel Group Pro</span></div><div class=\"partner-logo\"><i class=\"fas fa-plane\"></i><span class=\"partner-name\">Voyage Elite</span></div><div class=\"partner-logo\"><i class=\"fas fa-umbrella-beach\"></i><span class=\"partner-name\">Resort Luxury</span></div><div class=\"partner-logo\"><i class=\"fas fa-concierge-bell\"></i><span class=\"partner-name\">Event Masters</span></div><div class=\"partner-logo\"><i class=\"fas fa-map-signs\"></i><span class=\"partner-name\">Tourism Experts</span></div><div class=\"partner-logo\"><i class=\"fas fa-briefcase\"></i><span class=\"partner-name\">Business Travel</span></div></div></div><!-- Footer de la section --><div class=\"section-footer\"><div class=\"footer-content\"><div class=\"footer-logo\"><i class=\"fas fa-globe\"></i> Partenaires Master User Go Exploria\n                </div><div class=\"footer-cta\"></div></div></div></div><!-- Note pour GrapeJS --></body>', '* { box-sizing: border-box; } body {margin: 0;}*{margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;box-sizing:border-box;font-family:\"Segoe UI\", Tahoma, Geneva, Verdana, sans-serif;}body{background-color:rgb(248, 249, 250);color:rgb(51, 51, 51);line-height:1.6;padding-top:20px;padding-right:20px;padding-bottom:20px;padding-left:20px;max-width:1200px;margin-top:0px;margin-right:auto;margin-bottom:0px;margin-left:auto;}.partners-section{background-color:white;border-top-left-radius:16px;border-top-right-radius:16px;border-bottom-right-radius:16px;border-bottom-left-radius:16px;box-shadow:rgba(0, 0, 0, 0.1) 0px 15px 40px;overflow-x:hidden;overflow-y:hidden;margin-top:20px;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:all;position:relative;}.section-background{position:absolute;top:0px;left:0px;width:100%;height:100%;z-index:0;opacity:0.