olor:initial;padding-top:20px;padding-right:40px;padding-bottom:20px;padding-left:40px;border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-right-radius:12px;border-bottom-left-radius:12px;display:inline-block;border-left-width:5px;border-left-style:solid;border-left-color:rgb(45, 92, 194);margin-top:10px;}.highlight-slogan h2{font-size:1.8rem;color:rgb(26, 58, 143);font-weight:700;margin-bottom:5px;}.highlight-slogan p{font-size:1.1rem;color:rgb(85, 85, 85);}.section-content{display:flex;flex-wrap:wrap;padding-top:40px;padding-right:40px;padding-bottom:40px;padding-left:40px;position:relative;z-index:1;row-gap:40px;column-gap:40px;}.features-column{flex-grow:1;flex-shrink:1;flex-basis:0%;min-width:300px;}.features-column h3{font-size:1.8rem;color:rgb(26, 58, 143);margin-bottom:25px;padding-bottom:15px;border-bottom-width:2px;border-bottom-style:solid;border-bottom-color:rgb(238, 238, 238);}.feature-card{background-color:rgb(248, 250, 252);border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-right-radius:12px;border-bottom-left-radius:12px;padding-top:25px;padding-right:25px;padding-bottom:25px;padding-left:25px;margin-bottom:20px;border-top-width:1px;border-right-width:1px;border-bottom-width:1px;border-left-width:1px;border-top-style:solid;border-right-style:solid;border-bottom-style:solid;border-left-style:solid;border-top-color:rgb(238, 238, 238);border-right-color:rgb(238, 238, 238);border-bottom-color:rgb(238, 238, 238);border-left-color:rgb(238, 238, 238);border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:all;position:relative;overflow-x:hidden;overflow-y:hidden;}.feature-card:hover{transform:translateY(-5px);box-shadow:rgba(0, 0, 0, 0.08) 0px 10px 25px;border-top-color:rgb(45, 92, 194);border-right-color:rgb(45, 92, 194);border-bottom-color:rgb(45, 92, 194);border-left-color:rgb(45, 92, 194);}.feature-card::before{content:\"\";position:absolute;top:0px;left:0px;width:5px;height:100%;background-image:linear-gradient(rgb(26, 58, 143), rgb(45, 92, 194));background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;}.feature-icon{width:60px;height:60px;background-image:linear-gradient(135deg, rgba(26, 58, 143, 0.1) 0%, rgba(45, 92, 194, 0.1) 100%);background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-right-radius:12px;border-bottom-left-radius:12px;display:flex;align-items:center;justify-content:center;margin-bottom:15px;}.feature-icon i{font-size:1.8rem;color:rgb(45, 92, 194);}.feature-card h4{font-size:1.3rem;color:rgb(26, 58, 143);margin-bottom:10px;}.feature-card p{color:rgb(102, 102, 102);font-size:1rem;line-height:1.6;}.dashboard-column{flex-grow:1;flex-shrink:1;flex-basis:0%;min-width:300px;}.dashboard-preview{background-image:linear-gradient(135deg, rgb(26, 58, 143) 0%, rgb(45, 92, 194) 100%);background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;border-top-left-radius:16px;border-top-right-radius:16px;border-bottom-right-radius:16px;border-bottom-left-radius:16px;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px;color:white;margin-bottom:30px;box-shadow:rgba(26, 58, 143, 0.3) 0px 10px 30px;position:relative;overflow-x:hidden;overflow-y:hidden;}.dashboard-preview::before{content:\"\";position:absolute;top:-50%;righ