anslateY(0px);}}@keyframes title-appear{100%{opacity:1;transform:translateY(0px);}}@keyframes fade-up{100%{opacity:1;transform:translateY(0px);}}@media (max-width: 1200px){.products-grid{grid-template-columns:repeat(3, 1fr);}.showcase-grid{grid-template-columns:repeat(2, 1fr);}}@media (max-width: 992px){.main-title{font-size:2.8rem;}.products-grid{grid-template-columns:repeat(2, 1fr);}}@media (max-width: 768px){.main-title{font-size:2.2rem;}.products-grid{grid-template-columns:1fr;}.header-subtitle{font-size:1.1rem;}.showcase-grid{grid-template-columns:1fr;}.showcase-header h2{font-size:2.2rem;}}@media (max-width: 480px){.main-title{font-size:2.2rem;}.header-subtitle{font-size:1.1rem;}.products-grid{grid-template-columns:1fr;}.fashion-header{padding-top:60px;padding-right:0px;padding-bottom:40px;padding-left:0px;}}', NULL, 'draft', NULL, '2026-02-02 12:22:13', '2026-02-12 15:34:51');
INSERT INTO `menus` (`id`, `title`, `slug`, `type`, `parent_id`, `reference_id`, `menu_type`, `order`, `route`, `url`, `icon`, `is_active`, `has_page`, `page_id`, `page_content`, `page_styles`, `page_meta`, `page_status`, `page_slug`, `created_at`, `updated_at`) VALUES
(12, '🏨Vos Nouvelles', 'go-exploria-vos-nouvelles', 'custom', NULL, NULL, 'Accueil', 6, NULL, '#go-exploria-vos-nouvelles', NULL, 1, 1, NULL, '<body><!-- Navigation --><link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css\" rel=\"stylesheet\"/><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\"/><link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700;800&amp;family=Inter:wght@300;400;500;600&amp;display=swap\" rel=\"stylesheet\"/><!-- Hero Section --><!-- Featured News --><section id=\"news\" class=\"gn-section\"><div class=\"gn-container\"><div class=\"gn-section-header gn-mb-50\"><h2 class=\"gn-section-title gn-font-primary\">À La Une</h2><p class=\"gn-section-subtitle\">Les actualités les plus importantes du moment</p></div><div class=\"gn-featured-article gn-fade-in gn-delay-1\"><img src=\"https://images.unsplash.com/photo-1588681664899-f142ff2dc9b1?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=2070&amp;q=80\" alt=\"Sommet International\" class=\"gn-featured-img\"/><div class=\"gn-featured-overlay\"><span class=\"gn-badge gn-badge-accent gn-mb-20\">Politique Internationale</span><h3 class=\"h2 gn-font-primary\">Sommet mondial sur le climat: Les engagements des grandes puissances</h3><div class=\"d-flex align-items-center gn-mt-20\"><i class=\"fas fa-user me-2\"></i><span class=\"me-4\">Marie Dubois</span><i class=\"fas fa-clock me-2\"></i><span class=\"me-4\">Il y a 2 heures</span><i class=\"fas fa-eye me-2\"></i><span>12K vues</span></div></div></div></div></section><!-- Latest News --><section class=\"gn-section gn-section-light\"><div class=\"gn-container\"><div class=\"gn-section-header gn-mb-50\"><h2 class=\"gn-section-title gn-font-primary\">Dernières Nouvelles</h2><p class=\"gn-section-subtitle\">Les articles les plus récents par région</p></div><div class=\"row g-4\"><div class=\"col-lg-4 col-md-6\"><div class=\"gn-card gn-fade-in gn-delay-1\"><img src=\"data:image/jpeg;base64,\" alt=\"Marché Africain\" class=\"gn-card-img\"/><div class=\"gn-card-body\"><span class=\"gn-badge gn-badge-primary gn-mb-10\">Économie • Afrique</span><h3 class=\"gn-card-title gn-font-primary\">\n                                Croissance record des économies d\'Afrique de l\'Ouest\n                            </h3><p class=\"gn-card-text\">\n                                La CEDEAO annonce une croissance économique de 6.2% pour le dernier trimestre, \n                                dépassant toutes les prévisions.\n                            </p><div class=\"d-flex justify-content-between align-items-center\"><small class=\"text-muted\">Il y a 3 heures</small><a href=\"#\" class=\"gn-btn gn-btn-primary btn-sm\">Lire</a></div></div></div></div><div class=\"col-lg-4 col-md-6\"><div class=\"gn-card gn-fade-in gn-delay-2\"><img src=\"https://images.unsplash.com/photo-1511895426328-dc8714191300?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=2070&amp;q=80\" alt=\"Union Européenne\" class=\"gn-card-img\"/><div class=\"gn-card-body\"><span class=\"gn-badge gn-badge-secondary gn-mb-10\">Politique • Europe</span><h3 class=\"gn-card-title gn-font-primary\">\n                                Nouvelle politique migratoire de l\'Union Européenne\n                            </h3><p class=\"gn-card-text\">\n                                Les membres de l\'UE trouvent un accord sur une approche commune pour la \n                                gestion des frontières et l\'accueil des réfugiés.\n                            </p><div class=\"d-flex justify-content-between align-items-center\"><small class=\"text-muted\">Il y a 6 heures</small><a href=\"#\" class=\"gn-btn gn-btn-primary btn-sm\">Lire</a></div></div></div></div><div class=\"col-lg-4 col-md-6\"><div class=\"gn-card gn-fade-in gn-delay-3\"><img src=\"https://images.unsplash.com/photo-1528164344705-47542687000d?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=2092&amp;q=80\" alt=\"Asie Technologie\" class=\"gn-card-img\"/><div class=\"gn-card-body\"><span class=\"gn-badge gn-badge-accent gn-mb-10\">Innovation • Asie</span><h3 class=\"gn-card-title gn-font-primary\">\n                                Le Japon lance son plus grand satellite d\'observation\n                            </h3><p class=\"gn-card-text\">\n                                Une avancée majeure pour la surveillance climatique et la prévention \n                                des catastrophes naturelles en Asie-Pacifique.\n                            </p><div class=\"d-flex justify-content-between align-items-center\"><small class=\"text-muted\">Il y a 8 heures</small><a href=\"#\" class=\"gn-btn gn-btn-primary btn-sm\">Lire</a></div></div></div></div></div></div></section><!-- Regions Section --><section id=\"regions\" class=\"gn-section\"><div class=\"gn-container\"><div class=\"gn-section-header gn-mb-50\"><h2 class=\"gn-section-title gn-font-primary\">Nouvelles Par Région</h2><p class=\"gn-section-subtitle\">Explorez les actualités spécifiques à chaque région du monde</p></div><div class=\"row g-4\"><div class=\"col-lg-3 col-md-6\"><div class=\"gn-region-card gn-fade-in gn-delay-1\"><img src=\"https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=2068&amp;q=80\" alt=\"Afrique\" class=\"gn-region-img\"/><div class=\"gn-region-overlay\"><h4 class=\"h3 gn-font-primary\">Afrique</h4><p class=\"gn-mb-20\">245 nouvelles aujourd\'hui</p><a href=\"#\" class=\"gn-btn gn-btn-accent\">Explorer</a></div></div></div><div class=\"col-lg-3 col-md-6\"><div class=\"gn-region-card gn-fade-in gn-delay-2\"><img src=\"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=2020&amp;q=80\" alt=\"Europe\" class=\"gn-region-img\"/><div class=\"gn-region-overlay\"><h4 class=\"h3 gn-font-primary\">Europe</h4><p class=\"gn-mb-20\">189 nouvelles aujourd\'hui</p><a href=\"#\" class=\"gn-btn gn-btn-accent\">Explorer</a></div></div></div><div class=\"col-lg-3 col-md-6\"><div class=\"gn-region-card gn-fade-in gn-delay-3\"><img src=\"https://images.unsplash.com/photo-1535139262971-c51845709a48?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=2070&amp;q=80\" alt=\"Asie\" class=\"gn-region-img\"/><div class=\"gn-region-overlay\"><h4 class=\"h3 gn-font-primary\">Asie</h4><p class=\"gn-mb-20\">312 nouvelles aujourd\'hui</p><a href=\"#\" class=\"gn-btn gn-btn-accent\">Explorer</a></div></div></div><div class=\"col-lg-3 col-md-6\"><div class=\"gn-region-card gn-fade-in gn-delay-4\"><img src=\"https://images.unsplash.com/photo-1501594907352-04cda38ebc29?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=2032&amp;q=80\" alt=\"Amériques\" class=\"gn-region-img\"/><div class=\"gn-region-overlay\"><h4 class=\"h3 gn-font-primary\">Amériques</h4><p class=\"gn-mb-20\">278 nouvelles aujourd\'hui</p><a href=\"#\" class=\"gn-btn gn-btn-accent\">Explorer</a></div></div></div></div></div></section><!-- Newsletter --><!-- Footer --></body>', '* { box-sizing: border-box; } body {margin: 0;}*{box-sizing:border-box;}body{margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;}:root{--gn-primary:#1a237e;--gn-secondary:#0d6efd;--gn-accent:#ff6b35;--gn-dark:#1a1a2e;--gn-light:#f8f9ff;--gn-success:#28a745;--gn-warning:#ffc107;--gn-danger:#dc3545;--gn-border-radius:12px;--gn-box-shadow:0 8px 30px rgba(0,0,0,0.08);--gn-transition:all 0.3s cubic-bezier(0.4, 0, 0.2, 1);}.gn-font-primary{font-family:Poppins, sans-serif !important;}.gn-section{padding-top:80px;padding-right:0px;padding-bottom:80px;padding-left:0px;position:relative;}.gn-section-light{background-color:var(--gn-light) !important;}.gn-container{max-width:1200px;margin-top:0px;margin-right:auto;margin-bottom:0px;margin-left:auto;padding-top:0px;padding-right:20px;padding-bottom:0px;padding-left:20px;}.gn-btn{padding-top:12px !important;padding-right:32px !important;padding-bottom:12px !important;padding-left:32px !important;border-top-left-radius:50px !important;border-top-right-radius:50px !important;border-bottom-right-radius:50px !important;border-bottom-left-radius:50px !important;font-weight:600 !important;border-top-width:initial !important;border-right-width:initial !important;border-bottom-width:initial !important;border-left-width:initial !important;border-top-style:none !important;border-right-style:none !important;border-bottom-style:none !important;border-left-style:none !important;border-top-color:initial !important;border-right-color:initial !important;border-bottom-color:initial !important;border-left-color:initial !important;border-image-source:initial !important;border-image-slice:initial !important;border-image-width:initial !important;border-image-outset:initial !important;border-image-repeat:initial !important;display:inline-flex !important;align-items:center !important;justify-content:center !important;row-gap:10px !important;column-gap:10px !important;}.gn-btn-primary{color:white !important;}.gn-btn-primary:hover{background-image:initial !important;background-position-x:initial !important;background-position-y:initial !important;background-size:initial !important;background-repeat:initial !important;background-attachment:initial !important;background-origin:initial !important;background-clip:initial !important;background-color:rgb(21, 28, 106) !important;transform:translateY(-3px) !important;box-shadow:rgba(26, 35, 126, 0.3) 0px 10px 20px !important;}.gn-btn-accent{color:white !important;}.gn-btn-accent:hover{background-image:initial !important;background-position-x:initial !important;background-position-y:initial !important;background-size:initial !important;background-repeat:initial !important;background-attachment:initial !important;background-origin:initial !important;background-clip:initial !important;background-color:rgb(229, 90, 43) !important;transform:translateY(-3px) !important;box-shadow:rgba(255, 107, 53, 0.3) 0px 10px 20px !important;}.gn-card{background-image:initial !important;background-position-x:initial !important;background-position-y:initial !important;background-size:initial !important;background-repeat:initial !important;background-attachment:initial !important;background-origin:initial !important;background-clip:initial !important;background-color:white !important;border-top-width:initial !important;border-right-width:initial !important;border-bottom-width:initial !important;border-left-width:initial !important;border-top-style:none !important;border-right-style:none !important;border-bottom-style:none !important;border-left-style:none !important;border-top-color:initial !important;border-right-color:initial !important;border-bottom-color:initial !important;border-left-color:initial !important;border-image-source:initial !important;border-image-slice:initial !important;border-image-width:initial !important;border-image-outset:initial !important;border-image-repeat:initial !important;box-shadow:var(--gn-box-shadow) !important;overflow-x:hidden !important;overflow-y:hidden !important;height:100% !important;}.gn-card:hover{transform:translateY(-10px) !important;box-shadow:rgba(0, 0, 0, 0.15) 0px 20px 40px !important;}.gn-card-img{width:100% !important;height:220px !important;object-fit:cover !important;}.gn-card:hover .gn-card-img{transform:scale(1.05) !important;}.gn-card-body{padding-top:25px !important;padding-right:25px !important;padding-bottom:25px !important;padding-left:25px !important;}.gn-card-title{font-size:1.3rem !important;font-weight:700 !important;margin-bottom:15px !important;line-height:1.4 !important;}.gn-card-text{color:rgb(102, 102, 102) !important;margin-bottom:20px !important;font-size:0.95rem !important;}.gn-badge{display:inline-block !important;padding-top:6px !important;padding-right:15px !important;padding-bottom:6px !important;padding-left:15px !important;border-top-left-radius:50px !important;border-top-right-radius:50px !important;border-bottom-right-radius:50px !important;border-bottom-left-radius:50px !important;font-size:0.8rem !important;font-weight:600 !important;text-transform:uppercase !important;letter-spacing:0.5px !important;}.gn-badge-primary{background-image:initial !important;background-position-x:initial !important;background-position-y:initial !important;background-size:initial !important;background-repeat:initial !important;background-attachment:initial !important;background-origin:initial !important;background-clip:initial !important;background-color:rgba(26, 35, 126, 0.1) !important;color:var(--gn-primary) !important;}.gn-badge-secondary{background-image:initial !important;background-position-x:initial !important;background-position-y:initial !important;background-size:initial !important;background-repeat:initial !important;background-attachment:initial !important;background-origin:initial !important;background-clip:initial !important;background-color:rgba(13, 110, 253, 0.1) !important;color:var(--gn-secondary) !important;}.gn-badge-accent{background-image:initial !important;background-position-x:initial !important;background-position-y:initial !important;background-size:initial !important;background-repeat:initial !important;background-attachment:initial !important;background-origin:initial !important;background-clip:initial !important;background-color:rgba(255, 107, 53, 0.1) !important;color:var(--gn-accent) !important;}.gn-section-header{text-align:center;margin-bottom:60px;}.gn-section-title{position:relative;display:inline-block;font-size:2.5rem !important;font-weight:800 !important;margin-bottom:15px !important;}.gn-section-title::after{content:\"\";position:absolute;bottom:-10px;left:50%;transform:translateX(-50%);width:60px;height:4px;border-top-left-radius:2px;border-top-right-radius:2px;border-bottom-right-radius:2px;border-bottom-left-radius:2px;}.gn-section-subtitle{color:rgb(102, 102, 102);font-size:1.1rem;max-width:700px;margin-top:0px;margin-right:auto;margin-bottom:0px;margin-left:auto;}.gn-featured-article{position:relative;overflow-x:hidden;overflow-y:hidden;box-shadow:var(--gn-box-shadow);}.gn-featured-article:hover{transform:translateY(-10px);box-shadow:rgba(0, 0, 0, 0.15) 0px 25px 50px;}.gn-featured-img{width:100%;height:450px;object-fit:cover;}.gn-featured-article:hover .gn-featured-img{transform:scale(1.05);}.gn-featured-overlay{position:absolute;bottom:0px;left:0px;right:0px;background-image:linear-gradient(transparent, rgba(0, 0, 0, 0.9));background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;color:white;padding-top:40px;padding-right:40px;padding-bottom:40px;padding-left:40px;}.gn-region-card{position:relative;overflow-x:hidden;overflow-y:hidden;height:300px;box-shadow:var(--gn-box-shadow);}.gn-region-card:hover{transform:translateY(-10px);box-shadow:rgba(0, 0, 0, 0.2) 0px 20px 40px;}.gn-region-img{width:100%;height:100%;object-fit:cover;}.gn-region-card:hover .gn-region-img{transform:scale(1.1);}.gn-region-overlay{position:absolute;top:0px;left:0px;right:0px;bottom:0px;background-image:linear-gradient(transparent, rgba(0, 0, 0, 0.8));background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;display:flex;flex-direction:column;justify-content:flex-end;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px;color:white;}.gn-fade-in{opacity:0;transform:translateY(30px);animation-duration:0.8s;animation-timing-function:ease-out;animation-delay:0s;animation-iteration-count:1;animation-direction:normal;animation-fill-mode:forwards;animation-play-state:running;animation-name:gnFadeIn;animation-timeline:auto;animation-range-start:normal;animation-range-end:normal;}.gn-delay-1{animation-delay:0.1s !important;}.gn-delay-2{animation-delay:0.2s !important;}.gn-delay-3{animation-delay:0.3s !important;}.gn-delay-4{animation-delay:0.4s !important;}.gn-mb-10{margin-bottom:10px !important;}.gn-mb-20{margin-bottom:20px !important;}.gn-mb-50{margin-bottom:50px !important;}.gn-mt-20{margin-top:20px !important;}@keyframes gnFadeIn{100%{opacity:1;transform:translateY(0px);}}@media (max-width: 768px){.gn-section-title{font-size:2rem !important;}}', NULL, 'draft', NULL, '2026-02-02 12:22:43', '2026-02-11 13:27:10');
INSERT INTO `menus` (`id`, `title`, `slug`, `type`, `parent_id`, `reference_id`, `menu_type`, `order`, `route`, `url`, `icon`, `is_active`, `has_page`, `page_id`, `page_content`, `page_styles`, `page_meta`, `page_status`, `page_slug`, `created_at`, `updated_at`) VALUES
(18, 'AFFICHEZ VOTRE ENTREPRISE', 'affichez-vos-entreprises', 'custom', 2, NULL, 'Accueil', 1, NULL, '#info-business-go-exploria', NULL, 1, 1, NULL, '<body><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\"/><div id=\"consulting-section\" class=\"consulting-section\"><!-- En-tête de la section --><div class=\"section-header\"><h1>Agence de Conseil pour Votre Entreprise</h1><p>Développez votre entreprise avec notre expertise stratégique et nos solutions sur mesure. Demandez votre consultation personnalisée.</p></div><div class=\"section-content\"><!-- Partie gauche : Présentation de l\'entreprise avec image de clientèle --><div class=\"company-presentation\"><!-- En-tête avec logo et image de clientèle --><div class=\"company-header\"><div class=\"company-logo\"><div class=\"logo-icon\"><i class=\"fas fa-chart-line\"></i></div><div class=\"logo-text\"><h2>Stratégis Conseil</h2><p>Votre succès, notre expertise</p></div></div><!-- Image de clientèle à droite --><div class=\"clientele-image\"><!-- SVG illustrant une équipe de clients satisfaits --><img src=\"data:image/jpeg;base64,\" alt=\"Clientèle satisfaite\" id=\"iht6d\" class=\"clientele-svg\"/></div></div><!-- Description de l\'entreprise --><div class=\"company-description\"><h3>Notre Agence de Conseil</h3><p>Nous sommes une agence de conseil spécialisée dans l\'accompagnement des entreprises vers l\'excellence opérationnelle et la croissance durable.</p><p>Notre équipe d\'experts vous aide à identifier les opportunités, optimiser vos processus et mettre en place des stratégies efficaces pour atteindre vos objectifs.</p><ul class=\"features-list\"><li><i class=\"fas fa-check-circle\"></i> Conseil stratégique sur mesure\n                        </li><li><i class=\"fas fa-check-circle\"></i> Analyse approfondie de votre marché\n                        </li><li><i class=\"fas fa-check-circle\"></i> Solutions digitales innovantes\n                        </li><li><i class=\"fas fa-check-circle\"></i> Accompagnement pas à pas\n                        </li></ul></div></div><!-- Partie droite : Formulaire, image et plans --><div class=\"request-section\"><h3 class=\"section-title\">Demandez Votre Consultation</h3><!-- Conteneur formulaire + image --><div class=\"form-image-container\"><!-- Formulaire --><div class=\"form-container\"><form method=\"get\" class=\"request-form\"><div class=\"form-group\"><label for=\"company-name\">Nom de votre société</label><input type=\"text\" id=\"company-name\" placeholder=\"Ex: Ma Société SARL\" class=\"form-control\"/></div><div class=\"form-group\"><label for=\"contact-name\">Votre nom</label><input type=\"text\" id=\"contact-name\" placeholder=\"Ex: Jean Bourget\" class=\"form-control\"/></div><div class=\"form-group\"><label for=\"email\">Adresse email</label><input type=\"email\" id=\"email\" placeholder=\"exemple@societe.com\" class=\"form-control\"/></div><div class=\"form-group\"><label for=\"service\">Service souhaité</label><select id=\"service\" class=\"form-control\"><option value=\"\">Sélectionnez un service</option><option value=\"strategy\">Conseil stratégique</option><option value=\"digital\">Transformation digitale</option><option value=\"management\">Management opérationnel</option><option value=\"marketing\">Stratégie marketing</option></select></div><button type=\"submit\" class=\"submit-btn\">Demander</button></form></div><!-- Image de graphique à droite --><div class=\"image-container\"><div><!-- Image SVG de graphique de croissance --><svg viewBox=\"0 0 400 300\" xmlns=\"http://www.w3.org/2000/svg\" class=\"growth-chart\"><defs><linearGradient id=\"chartBg\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\"><stop offset=\"0%\" id=\"ig4l4\"></stop><stop offset=\"100%\" id=\"ienoi\"></stop></linearGradient><linearGradient id=\"barGradient1\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\"><stop offset=\"0%\" id=\"i91gg\"></stop><stop offset=\"100%\" id=\"io15h\"></stop></linearGradient><linearGradient id=\"barGradient2\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\"><stop offset=\"0%\" id=\"inxrb\"></stop><stop offset=\"100%\" id=\"i6fhmu\"></stop></linearGradient><linearGradient id=\"lineGradient\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\"><stop offset=\"0%\" id=\"iq37bq\"></stop><stop offset=\"100%\" id=\"i12ylk\"></stop></linearGradient></defs><rect width=\"100%\" height=\"100%\" fill=\"url(#chartBg)\" rx=\"8\"></rect><g opacity=\"0.2\"><line x1=\"50\" y1=\"50\" x2=\"50\" y2=\"250\" stroke=\"#333\" stroke-width=\"1\"></line><line x1=\"50\" y1=\"250\" x2=\"350\" y2=\"250\" stroke=\"#333\" stroke-width=\"1\"></line><line x1=\"50\" y1=\"200\" x2=\"350\" y2=\"200\" stroke=\"#333\" stroke-width=\"1\" stroke-dasharray=\"5,5\"></line><line x1=\"50\" y1=\"150\" x2=\"350\" y2=\"150\" stroke=\"#333\" stroke-width=\"1\" stroke-dasharray=\"5,5\"></line><line x1=\"50\" y1=\"100\" x2=\"350\" y2=\"100\" stroke=\"#333\" stroke-width=\"1\" stroke-dasharray=\"5,5\"></line><line x1=\"50\" y1=\"50\" x2=\"350\" y2=\"50\" stroke=\"#333\" stroke-width=\"1\" stroke-dasharray=\"5,5\"></line></g><text x=\"25\" y=\"260\" font-family=\"Arial\" font-size=\"12\" fill=\"#666\">0%</text><text x=\"25\" y=\"210\" font-family=\"Arial\" font-size=\"12\" fill=\"#666\">25%</text><text x=\"25\" y=\"160\" font-family=\"Arial\" font-size=\"12\" fill=\"#666\">50%</text><text x=\"25\" y=\"110\" font-family=\"Arial\" font-size=\"12\" fill=\"#666\">75%</text><text x=\"25\" y=\"60\" font-family=\"Arial\" font-size=\"12\" fill=\"#666\">100%</text><rect x=\"80\" y=\"150\" width=\"40\" height=\"100\" fill=\"url(#barGradient1)\" rx=\"3\"></rect><rect x=\"140\" y=\"120\" width=\"40\" height=\"130\" fill=\"url(#barGradient1)\" rx=\"3\"></rect><rect x=\"200\" y=\"90\" width=\"40\" height=\"160\" fill=\"url(#barGradient2)\" rx=\"3\"></rect><rect x=\"260\" y=\"60\" width=\"40\" height=\"190\" fill=\"url(#barGradient2)\" rx=\"3\"></rect><rect x=\"320\" y=\"30\" width=\"40\" height=\"220\" fill=\"url(#barGradient1)\" rx=\"3\"></rect><path d=\"M100,150 Q170,120 220,90 T340,30\" stroke=\"url(#lineGradient)\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"></path><circle cx=\"100\" cy=\"150\" r=\"4\" fill=\"#1a3a8f\"></circle><circle cx=\"160\" cy=\"120\" r=\"4\" fill=\"#1a3a8f\"></circle><circle cx=\"220\" cy=\"90\" r=\"4\" fill=\"#2d5cc2\"></circle><circle cx=\"280\" cy=\"60\" r=\"4\" fill=\"#2d5cc2\"></circle><circle cx=\"340\" cy=\"30\" r=\"6\" fill=\"#1a3a8f\"></circle><text x=\"100\" y=\"270\" font-family=\"Arial\" font-size=\"12\" fill=\"#666\" text-anchor=\"middle\">M1</text><text x=\"160\" y=\"270\" font-family=\"Arial\" font-size=\"12\" fill=\"#666\" text-anchor=\"middle\">M2</text><text x=\"220\" y=\"270\" font-family=\"Arial\" font-size=\"12\" fill=\"#666\" text-anchor=\"middle\">M3</text><text x=\"280\" y=\"270\" font-family=\"Arial\" font-size=\"12\" fill=\"#666\" text-anchor=\"middle\">M4</text><text x=\"340\" y=\"270\" font-family=\"Arial\" font-size=\"12\" fill=\"#666\" text-anchor=\"middle\">M5</text><text x=\"200\" y=\"20\" font-family=\"Arial\" font-size=\"16\" font-weight=\"bold\" fill=\"#1a3a8f\" text-anchor=\"middle\">Croissance des entreprises</text><text x=\"200\" y=\"40\" font-family=\"Arial\" font-size=\"12\" fill=\"#666\" text-anchor=\"middle\">après notre accompagnement</text><rect x=\"280\" y=\"280\" width=\"12\" height=\"12\" fill=\"url(#barGradient1)\" rx=\"2\"></rect><text x=\"300\" y=\"290\" font-family=\"Arial\" font-size=\"10\" fill=\"#666\">Clients</text><rect x=\"340\" y=\"280\" width=\"12\" height=\"12\" fill=\"url(#barGradient2)\" rx=\"2\"></rect><text x=\"360\" y=\"290\" font-family=\"Arial\" font-size=\"10\" fill=\"#666\">Moyenne</text></svg><!-- Statistiques sous le graphique --><div class=\"chart-stats\"><div class=\"stat-item\"><div class=\"stat-number\">+42%</div><div class=\"stat-label\">Croissance moyenne</div></div><div class=\"stat-item\"><div class=\"stat-number\">94%</div><div class=\"stat-label\">Satisfaction</div></div></div></div></div></div><!-- Plans d\'affichage --><div class=\"plans-section\"><h3 class=\"section-title\">Nos Plans d\'Affichage</h3><div class=\"plans-grid\"><div class=\"plan-card\"><div class=\"plan-icon\"><i class=\"fas fa-star\"></i></div><h4>Essentiel</h4><p>Analyse initiale et recommandations de base</p></div><div class=\"plan-card\"><div class=\"plan-icon\"><i class=\"fas fa-gem\"></i></div><h4>Professionnel</h4><p>Accompagnement stratégique complet</p></div><div class=\"plan-card\"><div class=\"plan-icon\"><i class=\"fas fa-crown\"></i></div><h4>Enterprise</h4><p>Solution sur mesure pour grandes entreprises</p></div></div></div></div></div><!-- Footer de la section --></div><!-- Note pour GrapeJS --></body>', '* { box-sizing: border-box; } body {margin: 0;}*{margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;box-sizing:border-box;font-family:\"Segoe UI\", Tahoma, Geneva, Verdana, sans-serif;}body{background-color:rgb(248, 249, 250);color:rgb(51, 51, 51);line-height:1.6;padding-top:20px;padding-right:20px;padding-bottom:20px;padding-left:20px;max-width:1200px;margin-top:0px;margin-right:auto;margin-bottom:0px;margin-left:auto;}.consulting-section{display:flex;flex-wrap:wrap;background-color:white;border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-right-radius:12px;border-bottom-left-radius:12px;box-shadow:rgba(0, 0, 0, 0.08) 0px 10px 30px;overflow-x:hidden;overflow-y:hidden;margin-top:20px;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:all;}.section-header{width:100%;background-image:linear-gradient(135deg, rgb(26, 58, 143) 0%, rgb(45, 92, 194) 100%);background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:init