6px;}@media (max-width: 768px){.consulting-section{flex-direction:column;}.request-section{border-left-width:initial;border-left-style:none;border-left-color:initial;border-top-width:1px;border-top-style:solid;border-top-color:rgb(238, 238, 238);}.section-header h1{font-size:2rem;}.form-image-container{flex-direction:column;}.image-container{order:-1;margin-bottom:20px;}.company-header{flex-direction:column;}.clientele-image{margin-top:20px;max-width:100%;}}', '{\"title\": \"Digital Marketing\", \"keywords\": \"Digital Marketing, tourisme, voyage\", \"description\": \"Page de Digital Marketing\"}', 'draft', 'digital-marketing-CKVk80', '2026-02-04 10:40:55', '2026-02-12 15:20:25');
INSERT INTO `menus` (`id`, `title`, `slug`, `type`, `parent_id`, `reference_id`, `menu_type`, `order`, `route`, `url`, `icon`, `is_active`, `has_page`, `page_id`, `page_content`, `page_styles`, `page_meta`, `page_status`, `page_slug`, `created_at`, `updated_at`) VALUES
(19, 'Chaines & Média', 'chaines-media', 'custom', 9, NULL, 'Accueil', 0, NULL, '#mes-chaines-videos-photos-go-exploria', NULL, 1, 1, NULL, '    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n<body>\n    <div class=\"container\">\n        <div class=\"section-title\">\n            <h1>Lecteur Media Slideshow</h1>\n            <p>Découvrez notre collection multimédia avec ce lecteur moderne et interactif. Naviguez entre les différents médias avec des animations fluides.</p>\n        </div>\n        \n        <div class=\"slideshow-player\">\n            <div class=\"player-header\">\n                <div class=\"player-title\">\n                    <i class=\"fas fa-play-circle\"></i>\n                    <span>Galerie Multimédia Premium</span>\n                </div>\n                \n                <div class=\"player-controls\">\n                    <a href=\"#\" class=\"control-btn active\" id=\"btn-all\" title=\"Tous les médias\">\n                        <i class=\"fas fa-th-large\"></i>\n                    </a>\n                    <a href=\"#\" class=\"control-btn\" id=\"btn-photos\" title=\"Photos seulement\">\n                        <i class=\"fas fa-image\"></i>\n                    </a>\n                    <a href=\"#\" class=\"control-btn\" id=\"btn-videos\" title=\"Vidéos seulement\">\n                        <i class=\"fas fa-video\"></i>\n                    </a>\n                </div>\n            </div>\n            \n            <div class=\"player-body\">\n                <div class=\"media-display\">\n                    <div class=\"media-container\">\n                        <!-- Les médias sont insérés dynamiquement par JavaScript -->\n                    </div>\n                    \n                    <div class=\"media-info\">\n                        <h2 class=\"media-title\">Titre du média</h2>\n                        <p class=\"media-description\">Description du média actuellement affiché</p>\n                    </div>\n                </div>\n                \n                <div class=\"media-sidebar\">\n                    <div class=\"media-thumbnails\">\n                        <!-- Les vignettes sont insérées dynamiquement par JavaScript -->\n                    </div>\n                </div>\n            </div>\n            \n            <div class=\"player-footer\">\n                <div class=\"progress-container\">\n                    <div class=\"progress-bar\" id=\"progress-bar\">\n                        <div class=\"progress-fill\" id=\"progress-fill\"></div>\n                    </div>\n                    <div class=\"time-info\">\n                        <span id=\"current-time\">0:00</span>\n                        <span id=\"total-time\">0:00</span>\n                    </div>\n                </div>\n                \n                <div class=\"media-counter\">\n                    <span class=\"counter-current\" id=\"current-slide\">1</span>\n                    <span class=\"counter-separator\">/</span>\n                    <span class=\"counter-total\" id=\"total-slides\">5</span>\n                </div>\n                \n                <div class=\"player-actions\">\n                    <a href=\"#\" class=\"action-btn\" id=\"btn-prev\" title=\"Précédent\">\n                        <i class=\"fas fa-step-backward\"></i>\n                    </a>\n                    <a href=\"#\" class=\"action-btn play-pause pulse-effect\" id=\"btn-play-pause\" title=\"Lecture/Pause\">\n                        <i class=\"fas fa-play\" id=\"play-icon\"></i>\n                    </a>\n                    <a href=\"#\" class=\"action-btn\" id=\"btn-next\" title=\"Suivant\">\n                        <i class=\"fas fa-step-forward\"></i>\n                    </a>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        // Données des médias\n        const mediaData = [\n            {\n                id: 1,\n                type: \"image\",\n                title: \"Paysage Montagneux\",\n                description: \"Un magnifique panorama de montagnes enneigées au coucher du soleil.\",\n                src: \"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1350&q=80\",\n                thumbnail: \"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=300&q=80\",\n                duration: null\n            },\n            {\n                id: 2,\n                type: \"video\",\n                title: \"Forêt Tropicale\",\n                description: \"Explorez la beauté d\'une forêt tropicale luxuriante avec ses cascades.\",\n                src: \"https://assets.mixkit.co/videos/preview/mixkit-waterfall-in-forest-2213-large.mp4\",\n                thumbnail: \"https://images.unsplash.com/photo-1441974231531-c6227db76b6e?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=300&q=80\",\n                duration: \"0:15\"\n            },\n            {\n                id: 3,\n                type: \"image\",\n                title: \"Ville Nocturne\",\n                description: \"Lumières étincelantes d\'une métropole moderne la nuit.\",\n                src: \"https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1350&q=80\",\n                thumbnail: \"https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=300&q=80\",\n                duration: null\n            },\n            {\n                id: 4,\n                type: \"video\",\n                title: \"Océan et Vagues\",\n                description: \"Les vagues puissantes de l\'océan s\'écrasant sur les rochers.\",\n                src: \"https://assets.mixkit.co/videos/preview/mixkit-sea-waves-crashing-on-rocks-2222-large.mp4\",\n                thumbnail: \"https://images.unsplash.com/photo-1505142468610-359e7d316be0?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=300&q=80\",\n                duration: \"0:12\"\n            },\n            {\n                id: 5,\n                type: \"image\",\n                title: \"Désert et Ciel Étoilé\",\n                description: \"Une nuit étoilée au-dessus des dunes de sable du désert.\",\n                src: \"https://images.unsplash.com/photo-1519681393784-d120267933ba?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1350&q=80\",\n                thumbnail: \"https://images.unsplash.com/photo-1519681393784-d120267933ba?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=300&q=80\",\n                duration: null\n            }\n        ];\n\n        // Variables globales\n        let currentSlide = 0;\n        let totalSlides = mediaData.length;\n        let isPlaying = false;\n        let playInterval;\n        let currentMediaType = \'all\';\n        let filteredMedia = [...mediaData];\n\n        // Initialisation\n        document.addEventListener(\'DOMContentLoaded\', function() {\n            initSlideshow();\n            setupEventListeners();\n            updateSlideshow();\n            updateProgressBar();\n        });\n\n        // Initialisation du slideshow\n        function initSlideshow() {\n            const mediaContainer = document.querySelector(\'.media-container\');\n            const thumbnailsContainer = document.querySelector(\'.media-thumbnails\');\n            \n            // Afficher le total des slides\n            document.getElementById(\'total-slides\').textContent = totalSlides;\n            \n            // Créer les éléments médias\n            mediaData.forEach((media, index) => {\n                // Créer l\'élément média principal\n                let mediaElement;\n                if (media.type === \'image\') {\n                    mediaElement = document.createElement(\'img\');\n                    mediaElement.src = media.src;\n                    mediaElement.alt = media.title;\n                    mediaElement.classList.add(\'media-item\');\n                } else if (media.type === \'video\') {\n                    mediaElement = document.createElement(\'video\');\n                    mediaElement.src = media.src;\n                    mediaElement.controls = true;\n                    mediaElement.classList.add(\'media-item\');\n                    \n                    // Mettre à jour la durée de la vidéo lorsqu\'elle est chargée\n                    mediaElement.addEventListener(\'loadedmetadata\', function() {\n                        updateVideoDuration(index, mediaElement.duration);\n                    });\n                }\n                \n                if (index === 0) mediaElement.classList.add(\'active\');\n                mediaContainer.appendChild(mediaElement);\n                \n                // Créer la vignette\n                const thumbnailItem = document.createElement(\'div\');\n                thumbnailItem.classList.add(\'thumbnail-item\');\n                if (index === 0) thumbnailItem.classList.add(\'active\');\n                thumbnailItem.dataset.index = index;\n                \n                thumbnailItem.innerHTML = `\n                    <div class=\"thumbnail-img\">\n                        <img src=\"${media.thumbnail}\" alt=\"${media.title}\">\n                    </div>\n                    <div class=\"thumbnail-info\">\n                        <h4>${media.title}</h4>\n                        <p>${media.type === \'image\' ? \'Image\' : \'Vidéo\'} ${media.duration ? \' • \' + media.duration : \'\'}</p>\n                    </div>\n                `;\n                \n                thumbnailsContainer.appendChild(thumbnailItem);\n                \n                // Ajouter l\'événement de clic sur la vignette\n                thumbnailItem.addEventListener(\'click\', function() {\n                    const index = parseInt(this.dataset.index);\n                    goToSlide(index);\n                });\n            });\n            \n            // Mettre à jour les informations du premier média\n            updateMediaInfo(0);\n        }\n\n        // Configuration des événements\n        function setupEventListeners() {\n            // Boutons de contrôle\n            document.getElementById(\'btn-all\').addEventListener(\'click\', function() {\n                setMediaFilter(\'all\');\n                updateActiveFilterButton(this);\n            });\n            \n            document.getElementById(\'btn-photos\').addEventListener(\'click\', function() {\n                setMediaFilter(\'image\');\n                updateActiveFilterButton(this);\n            });\n            \n            document.getElementById(\'btn-videos\').addEventListener(\'click\', function() {\n                setMediaFilter(\'video\');\n                updateActiveFilterButton(this);\n            });\n            \n            // Boutons de navigation\n            document.getElementById(\'btn-prev\').addEventListener(\'click\', prevSlide);\n            document.getElementById(\'btn-next\').addEventListener(\'click\', nextSlide);\n            document.getElementById(\'btn-play-pause\').addEventListener(\'click\', togglePlayPause);\n            \n            // Barre de progression\n            const progressBar = document.getElementById(\'progress-bar\');\n            progressBar.addEventListener(\'click\', function(e) {\n                const rect = this.getBoundingClientRect();\n                const pos = (e.clientX - rect.left) / this.offsetWidth;\n                const slideIndex = Math.floor(pos * filteredMedia.length);\n                goToSlide(slideIndex);\n            });\n            \n            // Touches du clavier\n            document.addEventListener(\'keydown\', function(e) {\n                switch(e.key) {\n                    case \'ArrowLeft\':\n                        prevSlide();\n                        break;\n                    case \'ArrowRight\':\n                        nextSlide();\n                        break;\n                    case \' \':\n                        e.preventDefault();\n                        togglePlayPause();\n                        break;\n                }\n            });\n        }\n\n        // Navigation entre les slides\n        function goToSlide(index) {\n            // S\'assurer que l\'index est dans les limites\n            if (index < 0) index = filteredMedia.length - 1;\n            if (index >= filteredMedia.length) index = 0;\n            \n            // Obtenir l\'index réel dans les données médias complètes\n            const realIndex = mediaData.findIndex(media => media.id === filteredMedia[index].id);\n            \n            // Mettre à jour le slide courant\n            currentSlide = realIndex;\n            \n            // Mettre à jour l\'affichage\n            updateSlideshow();\n            \n            // Réinitialiser l\'intervalle de lecture si en mode lecture\n            if (isPlaying) {\n                clearInterval(playInterval);\n                startAutoPlay();\n            }\n        }\n\n        function nextSlide() {\n            let nextIndex = filteredMedia.findIndex(media => media.id === mediaData[currentSlide].id) + 1;\n            if (nextIndex >= filteredMedia.length) nextIndex = 0;\n            \n            const realIndex = mediaData.findIndex(media => media.id === filteredMedia[nextIndex].id);\n            goToSlide(realIndex);\n        }\n\n        function prevSlide() {\n            let prevIndex = filteredMedia.findIndex(media => media.id === mediaData[currentSlide].id) - 1;\n            if (prevIndex < 0) prevIndex = filteredMedia.length - 1;\n            \n            const realIndex = mediaData.findIndex(media => media.id === filteredMedia[prevIndex].id);\n            goToSlide(realIndex);\n        }\n\n        // Lecture automatique\n        function startAutoPlay() {\n            clearInterval(playInterval);\n            playInterval = setInterval(nextSlide, 5000); // Change de slide toutes les 5 secondes\n        }\n\n        function togglePlayPause() {\n            const playPauseBtn = document.getElementById(\'btn-play-pause\');\n            const playIcon = document.getElementById(\'play-icon\');\n            \n            if (isPlaying) {\n                // Mettre en pause\n                clearInterval(playInterval);\n                playIcon.classList.remove(\'fa-pause\');\n                playIcon.classList.add(\'fa-play\');\n                playPauseBtn.classList.add(\'pulse-effect\');\n                isPlaying = false;\n                \n                // Mettre en pause la vidéo si c\'est une vidéo\n                const currentMedia = document.querySelector(\'.media-item.active\');\n                if (currentMedia.tagName === \'VIDEO\') {\n                    currentMedia.pause();\n                }\n            } else {\n                // Lancer la lecture\n                startAutoPlay();\n                playIcon.classList.remove(\'fa-play\');\n                playIcon.classList.add(\'fa-pause\');\n                playPauseBtn.classList.remove(\'pulse-effect\');\n                isPlaying = true;\n                \n                // Lancer la vidéo si c\'est une vidéo\n                const currentMedia = document.querySelector(\'.media-item.active\');\n                if (currentMedia.tagName === \'VIDEO\') {\n                    currentMedia.play();\n                }\n            }\n        }\n\n        // Filtrage des médias\n        function setMediaFilter(type) {\n            currentMediaType = type;\n            \n            if (type === \'all\') {\n                filteredMedia = [...mediaData];\n            } else {\n                filteredMedia = mediaData.filter(media => media.type === type);\n            }\n            \n            // Réinitialiser au premier slide après filtrage\n            currentSlide = mediaData.findIndex(media => media.id === filteredMedia[0].id);\n            \n            // Mettre à jour l\'affichage\n            updateSlideshow();\n            updateThumbnails();\n            \n            // Mettre à jour le compteur\n            document.getElementById(\'total-slides\').textContent = filteredMedia.length;\n            \n            // Réinitialiser la lecture si active\n            if (isPlaying) {\n                clearInterval(playInterval);\n                startAutoPlay();\n            }\n        }\n\n        function updateActiveFilterButton(activeButton) {\n            // Retirer la classe active de tous les boutons de filtre\n            document.querySelectorAll(\'.control-btn\').forEach(btn => {\n                btn.classList.remove(\'active\');\n            });\n            \n            // Ajouter la classe active au bouton cliqué\n            activeButton.classList.add(\'active\');\n        }\n\n        // Mise à jour de l\'affichage\n        function updateSlideshow() {\n            // Mettre à jour le média affiché\n            const mediaItems = document.querySelectorAll(\'.media-item\');\n            mediaItems.forEach((item, index) => {\n                item.classList.remove(\'active\');\n                if (index === currentSlide) {\n                    item.classList.add(\'active\');\n                    \n                    // Si c\'est une vidéo et que le mode lecture est activé, la lancer\n                    if (isPlaying && item.tagName === \'VIDEO\') {\n                        item.play();\n                    }\n                }\n            });\n            \n            // Mettre à jour les informations du média\n            updateMediaInfo(currentSlide);\n            \n            // Mettre à jour le compteur de slide\n            const slideIndexInFiltered = filteredMedia.findIndex(media => media.id === mediaData[currentSlide].id);\n            document.getElementById(\'current-slide\').textContent = slideIndexInFiltered + 1;\n            \n            // Mettre à jour les vignettes actives\n            updateActiveThumbnail();\n            \n            // Mettre à jour la barre de progression\n            updateProgressBar();\n        }\n\n        function updateMediaInfo(index) {\n            const media = mediaData[index];\n            document.querySelector(\'.media-title\').textContent = media.title;\n            document.querySelector(\'.media-description\').textContent = media.description;\n        }\n\n        function updateThumbnails() {\n            const thumbnailItems = document.querySelectorAll(\'.thumbnail-item\');\n            thumbnailItems.forEach(item => {\n                const index = parseInt(item.dataset.index);\n                const media = mediaData[index];\n                \n                // Afficher ou masquer selon le filtre\n                if (currentMediaType === \'all\' || media.type === currentMediaType) {\n                    item.style.display = \'flex\';\n                } else {\n                    item.style.display = \'none\';\n                }\n            });\n        }\n\n        function updateActiveThumbnail() {\n            const thumbnailItems = document.querySelectorAll(\'.thumbnail-item\');\n            thumbnailItems.forEach(item => {\n                const index = parseInt(item.dataset.index);\n                item.classList.remove(\'active\');\n                if (index === currentSlide) {\n                    item.classList.add(\'active\');\n                    \n                    // Faire défiler jusqu\'à la vignette active\n                    item.scrollIntoView({ behavior: \'smooth\', block: \'nearest\', inline: \'center\' });\n                }\n            });\n        }\n\n        function updateProgressBar() {\n            const slideIndexInFiltered = filteredMedia.findIndex(media => media.id === mediaData[currentSlide].id);\n            const progressPercent = ((slideIndexInFiltered + 1) / filteredMedia.length) * 100;\n            document.getElementById(\'progress-fill\').style.width = `${progressPercent}%`;\n            \n            // Mettre à jour le temps actuel et total\n            document.getElementById(\'current-time\').textContent = formatTime(slideIndexInFiltered + 1);\n            document.getElementById(\'total-time\').textContent = formatTime(filteredMedia.length);\n        }\n\n        function updateVideoDuration(index, duration) {\n            // Formater la durée de la vidéo\n            const minutes = Math.floor(duration / 60);\n            const seconds = Math.floor(duration % 60);\n            const formattedDuration = `${minutes}:${seconds < 10 ? \'0\' : \'\'}${seconds}`;\n            \n            // Mettre à jour les données\n            mediaData[index].duration = formattedDuration;\n            \n            // Mettre à jour l\'affichage de la vignette si c\'est le média actuel\n            if (index === currentSlide) {\n                const thumbnailItems = document.querySelectorAll(\'.thumbnail-item\');\n                thumbnailItems[index].querySelector(\'.thumbnail-info p\').textContent = \n                    `Vidéo • ${formattedDuration}`;\n            }\n        }\n\n        function formatTime(value) {\n            // Simuler un format de temps basé sur l\'index\n            const minutes = Math.floor(value / 2);\n            const seconds = (value % 2) * 30;\n            return `${minutes}:${seconds < 10 ? \'0\' : \'\'}${seconds}`;\n        }\n    </script>\n</body>', '* {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n            font-family: \'Segoe UI\', system-ui, -apple-system, sans-serif;\n        }\n        \n        body {\n            background: linear-gradient(135deg, #0f2027 0%, #203a43 50%, #2c5364 100%);\n            color: #fff;\n            min-height: 100vh;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            padding: 20px;\n        }\n        \n        .container {\n            max-width: 1200px;\n            width: 100%;\n            margin: 0 auto;\n        }\n        \n        .section-title {\n            text-align: center;\n            margin-bottom: 40px;\n            position: relative;\n        }\n        \n        .section-title h1 {\n            font-size: 2.8rem;\n            font-weight: 700;\n            background: linear-gradient(90deg, #00dbde, #fc00ff);\n            -webkit-background-clip: text;\n            background-clip: text;\n            color: transparent;\n            margin-bottom: 15px;\n            letter-spacing: 1px;\n        }\n        \n        .section-title p {\n            font-size: 1.2rem;\n            color: #b0c4de;\n            max-width: 600px;\n            margin: 0 auto;\n            line-height: 1.6;\n        }\n        \n        .slideshow-player {\n            background: rgba(15, 25, 35, 0.85);\n            border-radius: 20px;\n            overflow: hidden;\n            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.5);\n            backdrop-filter: blur(10px);\n            border: 1px solid rgba(255, 255, 255, 0.1);\n        }\n        \n        .player-header {\n            padding: 25px 30px;\n            border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            background: rgba(0, 0, 0, 0.2);\n        }\n        \n        .player-title {\n            font-size: 1.8rem;\n            font-weight: 600;\n            display: flex;\n            align-items: center;\n            gap: 12px;\n        }\n        \n        .player-title i {\n            color: #00dbde;\n            font-size: 2rem;\n        }\n        \n        .player-controls {\n            display: flex;\n            gap: 15px;\n        }\n        \n        .control-btn {\n            background: rgba(255, 255, 255, 0.1);\n            border: none;\n            color: white;\n            width: 45px;\n            height: 45px;\n            border-radius: 50%;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            cursor: pointer;\n            font-size: 1.2rem;\n            transition: all 0.3s ease;\n            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);\n        }\n        \n        .control-btn:hover {\n            background: rgba(255, 255, 255, 0.2);\n            transform: translateY(-3px);\n        }\n        \n        .control-btn.active {\n            background: linear-gradient(135deg, #00dbde, #fc00ff);\n            color: white;\n        }\n        \n        .player-body {\n            display: flex;\n            min-height: 500px;\n        }\n        \n        .media-display {\n            flex: 1;\n            padding: 30px;\n            display: flex;\n            flex-direction: column;\n            justify-content: center;\n            align-items: center;\n            background: rgba(0, 0, 0, 0.3);\n            position: relative;\n            overflow: hidden;\n        }\n        \n        .media-container {\n            width: 100%;\n            max-width: 800px;\n            border-radius: 15px;\n            overflow: hidden;\n            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);\n            position: relative;\n            animation: fadeIn 0.8s ease-out;\n        }\n        \n        @keyframes fadeIn {\n            from { opacity: 0; transform: scale(0.95); }\n            to { opacity: 1; transform: scale(1); }\n        }\n        \n        .media-item {\n            display: none;\n            width: 100%;\n            height: auto;\n        }\n        \n        .media-item.active {\n            display: block;\n            animation: slideIn 0.8s ease-out;\n        }\n        \n        @keyframes slideIn {\n            from { opacity: 0; transform: translateX(30px); }\n            to { opacity: 1; transform: translateX(0); }\n        }\n        \n        .media-item img, .media-item video {\n            width: 100%;\n            height: auto;\n            display: block;\n        }\n        \n        .media-info {\n            padding: 20px 0;\n            text-align: center;\n            width: 100%;\n            max-width: 800px;\n        }\n        \n        .media-title {\n            font-size: 1.8rem;\n            font-weight: 600;\n            margin-bottom: 10px;\n            color: #fff;\n        }\n        \n        .media-description {\n            color: #b0c4de;\n            font-size: 1.1rem;\n            line-height: 1.6;\n        }\n        \n        .media-sidebar {\n            width: 300px;\n            padding: 25px;\n            border-left: 1px solid rgba(255, 255, 255, 0.1);\n            background: rgba(0, 0, 0, 0.2);\n            overflow-y: auto;\n            max-height: 500px;\n        }\n        \n        .media-thumbnails {\n            display: flex;\n            flex-direction: column;\n            gap: 15px;\n        }\n        \n        .thumbnail-item {\n            display: flex;\n            align-items: center;\n            gap: 15px;\n            padding: 12px;\n            border-radius: 10px;\n            cursor: pointer;\n            transition: all 0.3s ease;\n            background: rgba(255, 255, 255, 0.05);\n            border: 1px solid transparent;\n        }\n        \n        .thumbnail-item:hover {\n            background: rgba(255, 255, 255, 0.1);\n            transform: translateX(5px);\n        }\n        \n        .thumbnail-item.active {\n            background: rgba(0, 219, 222, 0.15);\n            border-color: #00dbde;\n        }\n        \n        .thumbnail-img {\n            width: 80px;\n            height: 60px;\n            border-radius: 8px;\n            overflow: hidden;\n            flex-shrink: 0;\n        }\n        \n        .thumbnail-img img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n        }\n        \n        .thumbnail-info h4 {\n            font-size: 1rem;\n            font-weight: 600;\n            margin-bottom: 5px;\n        }\n        \n        .thumbnail-info p {\n            font-size: 0.85rem;\n            color: #a0b3d0;\n        }\n        \n        .player-footer {\n            padding: 20px 30px;\n            border-top: 1px solid rgba(255, 255, 255, 0.1);\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            background: rgba(0, 0, 0, 0.2);\n        }\n        \n        .progress-container {\n            flex: 1;\n            margin-right: 30px;\n        }\n        \n        .progress-bar {\n            height: 8px;\n            background: rgba(255, 255, 255, 0.1);\n            border-radius: 4px;\n            overflow: hidden;\n            margin-bottom: 8px;\n            cursor: pointer;\n        }\n        \n        .progress-fill {\n            height: 100%;\n            background: linear-gradient(90deg, #00dbde, #fc00ff);\n            border-radius: 4px;\n            width: 30%;\n            transition: width 0.3s ease;\n            position: relative;\n        }\n        \n        .progress-fill::after {\n            content: \'\';\n            position: absolute;\n            right: 0;\n            top: 50%;\n            transform: translateY(-50%);\n            width: 16px;\n            height: 16px;\n            background: white;\n            border-radius: 50%;\n            box-shadow: 0 0 10px rgba(0, 219, 222, 0.8);\n        }\n        \n        .time-info {\n            display: flex;\n            justify-content: space-between;\n            font-size: 0.9rem;\n            color: #b0c4de;\n        }\n        \n        .player-actions {\n            display: flex;\n            gap: 10px;\n        }\n        \n        .action-btn {\n            background: rgba(255, 255, 255, 0.1);\n            border: none;\n            color: white;\n            width: 50px;\n            height: 50px;\n            border-radius: 50%;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            cursor: pointer;\n            font-size: 1.3rem;\n            transition: all 0.3s ease;\n        }\n        \n        .action-btn:hover {\n            background: linear-gradient(135deg, #00dbde, #fc00ff);\n            transform: scale(1.1);\n        }\n        \n        .action-btn.play-pause {\n            width: 60px;\n            height: 60px;\n            font-size: 1.6rem;\n            background: linear-gradient(135deg, #00dbde, #fc00ff);\n        }\n        \n        .media-counter {\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-size: 1.1rem;\n            color: #b0c4de;\n            gap: 10px;\n        }\n        \n        .counter-current {\n            font-size: 1.8rem;\n            font-weight: 700;\n            color: white;\n        }\n        \n        .counter-total {\n            font-size: 1.3rem;\n        }\n        \n        /* Animation pour le changement de slide */\n        @keyframes pulse {\n            0% { box-shadow: 0 0 0 0 rgba(0, 219, 222, 0.7); }\n            70% { box-shadow: 0 0 0 10px rgba(0, 219, 222, 0); }\n            100% { box-shadow: 0 0 0 0 rgba(0, 219, 222, 0); }\n        }\n        \n        .pulse-effect {\n            animation: pulse 1.5s infinite;\n        }\n        \n        /* Responsive */\n        @media (max-width: 992px) {\n            .player-body {\n                flex-direction: column;\n            }\n            \n            .media-sidebar {\n                width: 100%;\n                border-left: none;\n                border-top: 1px solid rgba(255, 255, 255, 0.1);\n                max-height: 300px;\n            }\n            \n            .media-thumbnails {\n                flex-direction: row;\n                overflow-x: auto;\n                padding-bottom: 10px;\n            }\n            \n            .thumbnail-item {\n                flex-direction: column;\n                min-width: 150px;\n            }\n            \n            .thumbnail-img {\n                width: 100%;\n                height: 100px;\n            }\n            a { \n                text-decoration: none;\n            }\n        }\n        \n        @media (max-width: 768px) {\n            .section-title h1 {\n                font-size: 2.2rem;\n            }\n            \n            .player-header {\n                flex-direction: column;\n                gap: 20px;\n                text-align: center;\n            }\n            \n            .player-footer {\n                flex-direction: column;\n                gap: 20px;\n            }\n            \n            .progress-container {\n                margin-right: 0;\n                width: 100%;\n            }\n            \n            .media-display {\n                padding: 15px;\n            }\n        }', '{\"title\": \"Chaines & Média\", \"keywords\": \"Chaines & Média, tourisme, voyage\", \"description\": \"Page de Chaines & Média\"}', 'draft', 'chaines-mdia-8AoUaU', '2026-02-04 11:25:51', '2026-02-12 15:23:47');
INSERT INTO `menus` (`id`, `title`, `slug`, `type`, `parent_id`, `reference_id`, `menu_type`, `order`, `route`, `url`, `icon`, `is_active`, `has_page`, `page_id`, `page_content`, `page_styles`, `page_meta`, `page_status`, `page_slug`, `created_at`, `updated_at`) VALUES
(20, 'Partenaires Master User', 'partenaires-master-user-go-exploria', 'custom', 10, NULL, 'Accueil', 0, NULL, '#partenaires-affilies', NULL, 1, 1, NULL, '<body><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\"/><div id=\"partners-section\" class=\"partners-section\"><!-- Background décoratif --><div class=\"section-background\"></div><!-- En-tête de la section --><div class=\"section-header\"><h1>Partenaires Master User Go Exploria</h1><p class=\"section-subtitle\">La plateforme ultime pour les professionnels du tourisme et de l\'événementiel</p><div class=\"highlight-slogan\"><h2>ACTIVEZ ET GÉREZ VOS DESTINATIONS ET VOS MARCHÉS</h2><p>Optimisez votre présence, développez vos activités et maximisez vos revenus avec nos outils professionnels.</p></div></div><!-- Contenu principal --><div class=\"section-content\"><!-- Colonne gauche : Avantages et fonctionnalités --><div class=\"features-column\"><h3>Fonctionnalités Principales</h3><div class=\"feature-card\"><div class=\"feature-icon\"><i class=\"fas fa-map-marked-alt\"></i></div><h4>Gestion Multi-Destinations</h4><p>Centralisez et gérez toutes vos destinations depuis une interface unique. Suivez les performances, ajustez vos stratégies et optimisez vos offres en temps réel.</p></div><div class=\"feature-card\"><div class=\"feature-icon\"><i class=\"fas fa-chart-network\"></i><i class=\"fas fa-tachometer-alt\"></i></div><h4>Analyse de Marché Avancée</h4><p>Accédez à des données market en temps réel, identifiez les tendances émergentes et prenez des décisions éclairées pour développer vos activités.</p></div><div class=\"feature-card\"><div class=\"feature-icon\"><i class=\"fas fa-users-cog\"></i></div><h4>Gestion des Partenaires</h4><p>Collaborez efficacement avec votre réseau de partenaires. Partagez des ressources, synchronisez les calendriers et travaillez en harmonie.</p></div><div class=\"feature-card\"><div class=\"feature-icon\"><i class=\"fas fa-file-invoice-dollar\"></i></div><h4>Facturation et Suivi Financier</h4><p>Générez des factures automatiques, suivez les paiements et analysez vos performances financières avec des rapports détaillés.</p></div></div><!-- Colonne droite : Dashboard et avantages --><div class=\"dashboard-column\"><!-- Dashboard preview --><div class=\"dashboard-preview\"><div class=\"dashboard-header\"><div class=\"dashboard-icon\"><i class=\"fas fa-tachometer-alt\"></i></div><h3>Tableau de Bord Master</h3></div><div class=\"dashboard-stats\"><div class=\"stat-item\"><div class=\"stat-value\">+87%</div><div class=\"stat-label\">Croissance du réseau</div></div><div class=\"stat-item\"><div class=\"stat-value\">156</div><div class=\"stat-label\">Destinations actives</div></div><div class=\"stat-item\"><div class=\"stat-value\">2.4M€</div><div class=\"stat-label\">Chiffre d\'affaires</div></div><div class=\"stat-item\"><div class=\"stat-value\">94%</div><div class=\"stat-label\">Satisfaction clients</div></div></div><div class=\"dashboard-cta\"></div></div><!-- Avantages --><h3>Avantages Exclusifs</h3><ul class=\"advantages-list\"><li><i class=\"fas fa-check-circle\"></i> <strong>Accès prioritaire</strong> aux nouvelles fonctionnalités et mises à jour\n                    </li><li><i class=\"fas fa-check-circle\"></i> <strong>Support dédié</strong> avec un conseiller personnel disponible 7j/7\n                    </li><li><i class=\"fas fa-check-circle\"></i> <strong>Formation complète</strong> et accompagnement pour maximiser votre ROI\n                    </li><li><i class=\"fas fa-check-circle\"></i> <strong>Réseau exclusif</strong> de partenaires et opportunités business\n                    </li><li><i class=\"fas fa-check-circle\"></i> <strong>Tarifs préférentiels</strong> sur les services premium et extensions\n                    </li></ul></div></div><!-- Section des partenaires --><div class=\"partners-showcase\"><h3>Ils nous font confiance</h3><div class=\"partners-grid\"><div class=\"partner-logo\"><i class=\"fas fa-hotel\"></i><span class=\"partner-name\">Hotel Group Pro</span></div><div class=\"partner-logo\"><i class=\"fas fa-plane\"></i><span class=\"partner-name\">Voyage Elite</span></div><div class=\"partner-logo\"><i class=\"fas fa-umbrella-beach\"></i><span class=\"partner-name\">Resort Luxury</span></div><div class=\"partner-logo\"><i class=\"fas fa-concierge-bell\"></i><span class=\"partner-name\">Event Masters</span></div><div class=\"partner-logo\"><i class=\"fas fa-map-signs\"></i><span class=\"partner-name\">Tourism Experts</span></div><div class=\"partner-logo\"><i class=\"fas fa-briefcase\"></i><span class=\"partner-name\">Business Travel</span></div></div></div><!-- Footer de la section --><div class=\"section-footer\"><div class=\"footer-content\"><div class=\"footer-logo\"><i class=\"fas fa-globe\"></i> Partenaires Master User Go Exploria\n                </div><div class=\"footer-cta\"></div></div></div></div><!-- Note pour GrapeJS --></body>', '* { box-sizing: border-box; } body {margin: 0;}*{margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;box-sizing:border-box;font-family:\"Segoe UI\", Tahoma, Geneva, Verdana, sans-serif;}body{background-color:rgb(248, 249, 250);color:rgb(51, 51, 51);line-height:1.6;padding-top:20px;padding-right:20px;padding-bottom:20px;padding-left:20px;max-width:1200px;margin-top:0px;margin-right:auto;margin-bottom:0px;margin-left:auto;}.partners-section{background-color:white;border-top-left-radius:16px;border-top-right-radius:16px;border-bottom-right-radius:16px;border-bottom-left-radius:16px;box-shadow:rgba(0, 0, 0, 0.1) 0px 15px 40px;overflow-x:hidden;overflow-y:hidden;margin-top:20px;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:all;position:relative;}.section-background{position:absolute;top:0px;left:0px;width:100%;height:100%;z-index:0;opacity:0.05;background-image:radial-gradient(circle at 20% 80%, rgb(74, 111, 165) 0%, transparent 50%), radial-gradient(circle at 80% 20%, rgb(45, 92, 194) 0%, transparent 50%), radial-gradient(circle at 40% 40%, rgb(26, 58, 143) 0%, transparent 50%);background-position-x:initial, initial, initial;background-position-y:initial, initial, initial;background-size:initial, initial, initial;background-repeat:initial, initial, initial;background-attachment:initial, initial, initial;background-origin:initial, initial, initial;background-clip:initial, initial, initial;background-color:initial;}.section-header{width:100%;padding-top:50px;padding-right:40px;padding-bottom:30px;padding-left:40px;text-align:center;position:relative;z-index:1;background-image:linear-gradient(135deg, rgba(26, 58, 143, 0.05) 0%, rgba(45, 92, 194, 0.05) 100%);background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;}.logo-badge i{margin-right:10px;font-size:1.3rem;}.section-header h1{font-size:2.8rem;margin-bottom:15px;font-weight:800;background-image:linear-gradient(135deg, rgb(26, 58, 143) 0%, rgb(45, 92, 194) 100%);background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-color:initial;background-clip:text;color:transparent;letter-spacing:-0.5px;line-height:1.2;}.section-subtitle{font-size:1.3rem;color:rgb(102, 102, 102);max-width:700px;margin-top:0px;margin-right:auto;margin-bottom:25px;margin-left:auto;font-weight:500;}.highlight-slogan{background-image:linear-gradient(135deg, rgba(26, 58, 143, 0.1) 0%, rgba(45, 92, 194, 0.1) 100%);background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;padding-top:20px;padding-right:40px;padding-bottom:20px;padding-left:40px;border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-right-radius:12px;border-bottom-left-radius:12px;display:inline-block;border-left-width:5px;border-left-style:solid;border-left-color:rgb(45, 92, 194);margin-top:10px;}.highlight-slogan h2{font-size:1.8rem;color:rgb(26, 58, 143);font-weight:700;margin-bottom:5px;}.highlight-slogan p{font-size:1.1rem;color:rgb(85, 85, 85);}.section-content{display:flex;flex-wrap:wrap;padding-top:40px;padding-right:40px;padding-bottom:40px;padding-left:40px;position:relative;z-index:1;row-gap:40px;column-gap:40px;}.features-column{flex-grow:1;flex-shrink:1;flex-basis:0%;min-width:300px;}.features-column h3{font-size:1.8rem;color:rgb(26, 58, 143);margin-bottom:25px;padding-bottom:15px;border-bottom-width:2px;border-bottom-style:solid;border-bottom-color:rgb(238, 238, 238);}.feature-card{background-color:rgb(248, 250, 252);border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-right-radius:12px;border-bottom-left-radius:12px;padding-top:25px;padding-right:25px;padding-bottom:25px;padding-left:25px;margin-bottom:20px;border-top-width:1px;border-right-width:1px;border-bottom-width:1px;border-left-width:1px;border-top-style:solid;border-right-style:solid;border-bottom-style:solid;border-left-style:solid;border-top-color:rgb(238, 238, 238);border-right-color:rgb(238, 238, 238);border-bottom-color:rgb(238, 238, 238);border-left-color:rgb(238, 238, 238);border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:all;position:relative;overflow-x:hidden;overflow-y:hidden;}.feature-card:hover{transform:translateY(-5px);box-shadow:rgba(0, 0, 0, 0.08) 0px 10px 25px;border-top-color:rgb(45, 92, 194);border-right-color:rgb(45, 92, 194);border-bottom-color:rgb(45, 92, 194);border-left-color:rgb(45, 92, 194);}.feature-card::before{content:\"\";position:absolute;top:0px;left:0px;width:5px;height:100%;background-image:linear-gradient(rgb(26, 58, 143), rgb(45, 92, 194));background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;}.feature-icon{width:60px;height:60px;background-image:linear-gradient(135deg, rgba(26, 58, 143, 0.1) 0%, rgba(45, 92, 194, 0.1) 100%);background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-right-radius:12px;border-bottom-left-radius:12px;display:flex;align-items:center;justify-content:center;margin-bottom:15px;}.feature-icon i{font-size:1.8rem;color:rgb(45, 92, 194);}.feature-card h4{font-size:1.3rem;color:rgb(26, 58, 143);margin-bottom:10px;}.feature-card p{color:rgb(102, 102, 102);font-size:1rem;line-height:1.6;}.dashboard-column{flex-grow:1;flex-shrink:1;flex-basis:0%;min-width:300px;}.dashboard-preview{background-image:linear-gradient(135deg, rgb(26, 58, 143) 0%, rgb(45, 92, 194) 100%);background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;border-top-left-radius:16px;border-top-right-radius:16px;border-bottom-right-radius:16px;border-bottom-left-radius:16px;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px;color:white;margin-bottom:30px;box-shadow:rgba(26, 58, 143, 0.3) 0px 10px 30px;position:relative;overflow-x:hidden;overflow-y:hidden;}.dashboard-preview::before{content:\"\";position:absolute;top:-50%;right:-50%;width:200px;height:200px;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgba(255, 255, 255, 0.1);border-top-left-radius:50%;border-top-right-radius:50%;border-bottom-right-radius:50%;border-bottom-left-radius:50%;}.dashboard-preview::after{content:\"\";position:absolute;bottom:-30%;left:-30%;width:150px;height:150px;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgba(255, 255, 255, 0.05);border-top-left-radius:50%;border-top-right-radius:50%;border-bottom-right-radius:50%;border-bottom-left-radius:50%;}.dashboard-header{display:flex;align-items:center;margin-bottom:20px;position:relative;z-index:2;}.dashboard-icon{width:50px;height:50px;background-color:rgba(255, 255, 255, 0.2);border-top-left-radius:10px;border-top-right-radius:10px;border-bottom-right-radius:10px;border-bottom-left-radius:10px;display:flex;align-items:center;justify-content:center;margin-right:15px;}.dashboard-icon i{font-size:1.5rem;}.dashboard-header h3{font-size:1.6rem;font-weight:700;}.dashboard-stats{display:grid;grid-template-columns:repeat(2, 1fr);row-gap:20px;column-gap:20px;margin-bottom:25px;position:relative;z-index:2;}.stat-item{background-color:rgba(255, 255, 255, 0.15);padding-top:15px;padding-right:15px;padding-bottom:15px;padding-left:15px;border-top-left-radius:10px;border-top-right-radius:10px;border-bottom-right-radius:10px;border-bottom-left-radius:10px;text-align:center;backdrop-filter:blur(5px);}.stat-value{font-size:1.8rem;font-weight:800;margin-bottom:5px;}.stat-label{font-size:0.9rem;opacity:0.9;}.dashboard-cta{position:relative;z-index:2;text-align:center;}.cta-button i{margin-right:10px;font-size:1.2rem;}.advantages-list{list-style-position:initial;list-style-image:initial;list-style-type:none;}.advantages-list li{padding-top:15px;padding-right:0px;padding-bottom:15px;padding-left:0px;display:flex;align-items:center;border-bottom-width:1px;border-bottom-style:dashed;border-bottom-color:rgb(238, 238, 238);}.advantages-list li:last-child{border-bottom-width:initial;border-bottom-style:none;border-bottom-color:initial;}.advantages-list i{color:rgb(45, 92, 194);margin-right:15px;font-size:1.2rem;min-width:25px;}.partners-showcase{width:100%;padding-top:40px;padding-right:40px;padding-bottom:40px;padding-left:40px;background-color:rgb(248, 250, 252);border-top-width:1px;border-top-style:solid;border-top-color:rgb(238, 238, 238);position:relative;z-index:1;}.partners-showcase h3{text-align:center;font-size:1.8rem;color:rgb(26, 58, 143);margin-bottom:30px;}.partners-grid{display:grid;grid-template-columns:repeat(auto-fit, minmax(150px, 1fr));row-gap:25px;column-gap:25px;max-width:1000px;margin-top:0px;margin-right:auto;margin-bottom:0px;margin-left:auto;}.partner-logo{background-color:white;border-top-left-radius:10px;border-top-right-radius:10px;border-bottom-right-radius:10px;border-bottom-left-radius:10px;padding-top:20px;padding-right:20px;padding-bottom:20px;padding-left:20px;display:flex;align-items:center;justify-content:center;height:100px;box-shadow:rgba(0, 0, 0, 0.05) 0px 5px 15px;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:all;border-top-width:1px;border-right-width:1px;border-bottom-width:1px;border-left-width:1px;border-top-style:solid;border-right-style:solid;border-bottom-style:solid;border-left-style:solid;border-top-color:rgb(238, 238, 238);border-right-color:rgb(238, 238, 238);border-bottom-color:rgb(238, 238, 238);border-left-color:rgb(238, 238, 238);border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;}.partner-logo:hover{transform:translateY(-5px);box-shadow:rgba(0, 0, 0, 0.1) 0px 10px 20px;border-top-color:rgb(45, 92, 194);border-right-color:rgb(45, 92, 194);border-bottom-color:rgb(45, 92, 194);border-left-color:rgb(45, 92, 194);}.partner-logo i{font-size:2.5rem;color:rgb(45, 92, 194);}.partner-name{font-weight:600;color:rgb(51, 51, 51);margin-left:10px;font-size:1.1rem;}.section-footer{width:100%;padding-top:30px;padding-right:40px;padding-bottom:30px;padding-left:40px;background-image:linear-gradient(135deg, rgb(26, 58, 143) 0%, rgb(45, 92, 194) 100%);background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;color:white;text-align:center;position:relative;z-index:1;}.footer-content{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;max-width:1000px;margin-top:0px;margin-right:auto;margin-bottom:0px;margin-left:auto;}.footer-logo{font-size:1.3rem;font-weight:700;display:flex;align-items:center;}.footer-logo i{margin-right:10px;font-size:1.5rem;}.footer-cta{display:flex;row-gap:15px;column-gap:15px;}.footer-button i{margin-right:8px;}.grapejs-note h4{color:rgb(26, 58, 143);margin-bottom:8px;display:flex;align-items:center;}.grapejs-note h4 i{margin-right:10px;}@media (max-width: 768px){.section-header{padding-top:30px;padding-right:20px;padding-bottom:30px;padding-left:20px;}.section-header h1{font-size:2rem;}.section-subtitle{font-size:1.1rem;}.highlight-slogan{padding-top:15px;padding-right:20px;padding-bottom:15px;padding-left:20px;}.highlight-slogan h2{font-size:1.4rem;}.section-content{padding-top:20px;padding-right:20px;padding-bottom:20px;padding-left:20px;flex-direction:column;}.partners-showcase{padding-top:30px;padding-right:20px;padding-bottom:30px;padding-left:20px;}.section-footer{padding-top:30px;padding-right:20px;padding-bottom:30px;padding-left:20px;}.footer-content{flex-direction:column;row-gap:20px;column-gap:20px;}}', '{\"title\": \"Tourisme Hébergement\", \"keywords\": \"Tourisme Hébergement, tourisme, voyage\", \"description\": \"Page de Tourisme Hébergement\"}', 'draft', 'tourisme-hebergement-oVQtCn', '2026-02-04 16:36:25', '2026-02-12 15:20:50'),
(21, 'Partenaires Régionaux', 'partenaires-rgionaux', 'custom', 10, NULL, 'Accueil', 1, NULL, '#partenaires-affilies', NULL, 1, 1, NULL, '<body><section id=\"video-slider\" class=\"slider-pizzafusion\"><div class=\"container\"><div class=\"section-title\"><h2 id=\"ivlj\">L\'EXPÉRIENCE PIZZAFUSION</h2><p>Découvrez notre processus de création unique</p></div><div id=\"pizzaSwiper\" class=\"swiper-container\"><div class=\"swiper-wrapper\"><div class=\"swiper-slide\"><img src=\"https://images.unsplash.com/photo-1595708684082-a173bb3a06c5?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=2070&amp;q=80\" alt=\"Pizza au four à bois\" loading=\"lazy\" class=\"slide-image\"/><div class=\"slide-content\"><h3>Fromage Fondant</h3><p>Notre mozzarella di bufala fond parfaitement pour créer une texture inégalée.</p></div></div><div class=\"swiper-slide\"><img src=\"https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=1981&amp;q=80\" alt=\"Pizza Margherita\" loading=\"lazy\" class=\"slide-image\"/><div class=\"slide-content\"><h3>Four à Bois Traditionnel</h3><p>Cuisson à 400°C pour une croûte parfaite et des saveurs authentiques.</p></div></div><div class=\"swiper-slide\"><img src=\"https://images.unsplash.com/photo-1513104890138-7c749659a591?ixlib=rb-4.0.3&amp;auto=format&amp;fit=crop&amp;w=2070&amp;q=80\" alt=\"Pizza aux champignons\" loading=\"lazy\" class=\"slide-image\"/><div class=\"slide-content\"><h3>Maîtrise Artisanale</h3><p>Nos pizzaiolos préparent chaque pizza avec une précision millimétrique.</p></div></div></div><button type=\"button\" class=\"swiper-button swiper-button-prev\">Send</button><button type=\"button\" class=\"swiper-button swiper-button-next\">Send</button><div class=\"swiper-pagination\"></div></div></div></section></body>', '* { box-sizing: border-box; } body {margin: 0;}.slider-pizzafusion{background-color:rgb(15, 15, 15);position:relative;padding-top:120px;padding-right:0px;padding-bottom:120px;padding-left:0px;}.slider-pizzafusion .container{width:90%;max-width:1400px;margin-top:0px;margin-right:auto;margin-bottom:0px;margin-left:auto;padding-top:0px;padding-right:20px;padding-bottom:0px;padding-left:20px;}.slider-pizzafusion .section-title{text-align:center;margin-bottom:5rem;}.slider-pizzafusion .section-title h2{font-size:3.5rem;margin-bottom:2rem;display:inline-block;font-family:\"Playfair Display\", serif;font-weight:800;background-image:linear-gradient(135deg, rgb(255, 59, 48) 0%, rgb(255, 149, 0) 100%);background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-color:initial;-webkit-text-fill-color:transparent;background-clip:text;line-height:1.2;}.slider-pizzafusion .section-title p{font-size:1.1rem;color:rgba(255, 255, 255, 0.8);font-family:Montserrat, sans-serif;max-width:600px;margin-top:0px;margin-right:auto;margin-bottom:0px;margin-left:auto;}.slider-pizzafusion .swiper-container{width:100%;height:600px;border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-right-radius:20px;border-bottom-left-radius:20px;overflow-x:hidden;overflow-y:hidden;box-shadow:rgba(0, 0, 0, 0.15) 0px 20px 40px;position:relative;}.slider-pizzafusion .swiper-slide{position:relative;width:100%;height:100%;}.slider-pizzafusion .slide-image{width:100%;height:100%;object-fit:cover;display:block;}.slider-pizzafusion .slide-content{position:absolute;bottom:0px;left:0px;right:0px;background-image:linear-gradient(transparent, rgba(0, 0, 0, 0.9));background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;padding-top:40px;padding-right:40px;padding-bottom:40px;padding-left:40px;color:white;}.slider-pizzafusion .slide-content h3{font-size:2.8rem;margin-bottom:10px;font-family:\"Playfair Display\", serif;font-weight:800;background-image:linear-gradient(135deg, rgb(255, 59, 48) 0%, rgb(255, 149, 0) 100%);background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-color:initial;-webkit-text-fill-color:transparent;background-clip:text;}.slider-pizzafusion .slide-content p{color:rgba(255, 255, 255, 0.8);font-size:1.1rem;font-family:Montserrat, sans-serif;max-width:600px;}.slider-pizzafusion .swiper-button{position:absolute;top:50%;transform:translateY(-50%);width:50px;height:50px;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgba(255, 255, 255, 0.2);border-top-left-radius:50%;border-top-right-radius:50%;border-bottom-right-radius:50%;border-bottom-left-radius:50%;color:white;display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:10;backdrop-filter:blur(10px);border-top-width:initial;border-right-width:initial;border-bottom-width:initial;border-left-width:initial;border-top-style:none;border-right-style:none;border-bottom-style:none;border-left-style:none;border-top-color:initial;border-right-color:initial;border-bottom-color:initial;border-left-color:initial;border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:all;}.slider-pizzafusion .swiper-button:hover{background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgba(255, 255, 255, 0.3);transform:translateY(-50%) scale(1.1);}.slider-pizzafusion .swiper-button-prev{left:20px;}.slider-pizzafusion .swiper-button-next{right:20px;}.slider-pizzafusion .swiper-pagination{position:absolute;bottom:20px;left:0px;right:0px;text-align:center;z-index:10;}.slider-pizzafusion .swiper-pagination-bullet{width:10px;height:10px;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:white;opacity:0.5;display:inline-block;margin-top:0px;margin-right:5px;margin-bottom:0px;margin-left:5px;border-top-left-radius:50%;border-top-right-radius:50%;border-bottom-right-radius:50%;border-bottom-left-radius:50%;cursor:pointer;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:all;}.slider-pizzafusion .swiper-pagination-bullet-active{background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(255, 59, 48);opacity:1;transform:scale(1.2);}@media (max-width: 1200px){.slider-pizzafusion .swiper-container{height:500px;}.slider-pizzafusion .section-title h2{font-size:3rem;}}@media (max-width: 992px){.slider-pizzafusion{padding-top:80px;padding-right:0px;padding-bottom:80px;padding-left:0px;}.slider-pizzafusion .swiper-container{height:400px;}.slider-pizzafusion .slide-content{padding-top:20px;padding-right:20px;padding-bottom:20px;padding-left:20px;}.slider-pizzafusion .slide-content h3{font-size:2rem;}}@media (max-width: 768px){.slider-pizzafusion .section-title h2{font-size:2.5rem;}.slider-pizzafusion .swiper-container{height:350px;}.slider-pizzafusion .slide-content h3{font-size:1.8rem;}.slider-pizzafusion .slide-content p{font-size:1rem;}.slider-pizzafusion .swiper-button{width:40px;height:40px;font-size:0.8rem;}}@media (max-width: 576px){.slider-pizzafusion .swiper-container{height:300px;border-top-left-radius:10px;border-top-right-radius:10px;border-bottom-right-radius:10px;border-bottom-left-radius:10px;}.slider-pizzafusion .section-title h2{font-size:2rem;}.slider-pizzafusion .slide-content{padding-top:15px;padding-right:15px;padding-bottom:15px;padding-left:15px;}.slider-pizzafusion .slide-content h3{font-size:1.5rem;}.slider-pizzafusion .swiper-button{width:35px;height:35px;display:none;}.slider-pizzafusion .swiper-pagination{bottom:10px;}}', '{\"title\": \"Partenaires Régionaux\", \"keywords\": \"Partenaires Régionaux, tourisme, voyage\", \"description\": \"Page de Partenaires Régionaux\"}', 'draft', 'partenaires-rgionaux-dcf8h1', '2026-02-04 17:06:27', '2026-02-12 15:21:00');
INSERT INTO `menus` (`id`, `title`, `slug`, `type`, `parent_id`, `reference_id`, `menu_type`, `order`, `route`, `url`, `icon`, `is_active`, `has_page`, `page_id`, `page_content`, `page_styles`, `page_meta`, `page_status`, `page_slug`, `created_at`, `updated_at`) VALUES
(22, 'Forfaits Touristiques', 'forfaits-touristiques-go-exploria', 'custom', NULL, NULL, 'Accueil', 8, NULL, '#forfaits-touristiques-go-exploria', NULL, 1, 1, NULL, '<body><!-- Background Animation --><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\"/><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"/><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin=\"\"/><link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&amp;family=Poppins:wght@400;500;600;700;800&amp;display=swap\" rel=\"stylesheet\"/><div class=\"bg-animation\"><div class=\"bg-circle\"></div><div class=\"bg-circle\"></div><div class=\"bg-circle\"></div></div><!-- Header --><!-- Hero Section --><section class=\"hero\"><div class=\"container\"><h1>Forfaits Voyage sur Mesure</h1><p>Découvrez nos forfaits exclusifs pour le Québec et l\'Europe avec des images réelles et authentiques.</p></div></section><!-- Vente Forfaits Québec - STATIC HTML --><section id=\"quebec\" class=\"packages-section\"><div id=\"vente-de-forfaits-quebec\" class=\"container\"><div class=\"category-title\"><i class=\"fas fa-maple-leaf\"></i><h2>Forfaits Québec</h2></div><div class=\"packages-grid\"><!-- Forfait Québec 1 --><div class=\"package-card\"><div class=\"package-image\"><img src=\"https://images.pexels.com/photos/208745/pexels-photo-208745.jpeg?auto=compress&amp;cs=tinysrgb&amp;w=1260&amp;h=750&amp;dpr=2\" alt=\"Vieux-Québec\" loading=\"lazy\"/><div class=\"package-badge\">POPULAIRE</div></div><div id=\"ibs16\" class=\"package-content\"><div class=\"package-header\"><h3>Escapade Montréal &amp; Québec</h3><div class=\"package-price\">$1899<span>/pers.</span></div></div><div class=\"package-location\"><i class=\"fas fa-map-marker-alt\"></i><span>Montréal, Québec</span></div><p class=\"package-description\">Séjour de 5 jours dans les plus belles villes du Québec. Visites guidées, gastronomie locale et hébergement 4 étoiles inclus.</p><div class=\"package-features\"><div class=\"feature\"><i class=\"fas fa-check\"></i> Culture</div><div class=\"feature\"><i class=\"fas fa-check\"></i> Gastronomie</div><div class=\"feature\"><i class=\"fas fa-check\"></i> Histoire</div></div><button type=\"button\" class=\"btn-primary\">Send</button></div></div><!-- Forfait Québec 2 --><div class=\"package-card\"><div class=\"package-image\"><img src=\"https://images.pexels.com/photos/4275885/pexels-photo-4275885.jpeg?auto=compress&amp;cs=tinysrgb&amp;w=1260&amp;h=750&amp;dpr=2\" alt=\"Gaspésie\" loading=\"lazy\"/><div class=\"package-badge\">NOUVEAU</div></div><div class=\"package-content\"><div class=\"package-header\"><h3>Aventure Gaspésie</h3><div class=\"package-price\">$2199<span>/pers.</span></div></div><div class=\"package-location\"><i class=\"fas fa-map-marker-alt\"></i><span>Gaspé, Québec</span></div><p class=\"package-description\">Parc national Forillon, observation des baleines, randonnée et découverte du Rocher Percé.</p><div class=\"package-features\"><div class=\"feature\"><i class=\"fas fa-check\"></i> Nature</div><div class=\"feature\"><i class=\"fas fa-check\"></i> Aventure</div><div class=\"feature\"><i class=\"fas fa-check\"></i> Faune</div></div><button type=\"button\" class=\"btn-primary\">Send</button></div></div><!-- Forfait Québec 3 --><div class=\"package-card\"><div class=\"package-image\"><img src=\"https://images.pexels.com/photos/361104/pexels-photo-361104.jpeg?auto=compress&amp;cs=tinysrgb&amp;w=1260&amp;h=750&amp;dpr=2\" alt=\"Charlevoix\" loading=\"lazy\"/><div class=\"package-badge\">LUXE</div></div><div class=\"package-content\"><div class=\"package-header\"><h3>Ski &amp; Spa Charlevoix</h3><div class=\"package-price\">$2499<span>/pers.</span></div></div><div class=\"package-location\"><i class=\"fas fa-map-marker-alt\"></i><span>Charlevoix, Québec</span></div><p class=\"package-description\">Forfait ski dans les Laurentides avec hébergement luxueux et accès au spa nordique.</p><div class=\"package-features\"><div class=\"feature\"><i class=\"fas fa-check\"></i> Sport</div><div class=\"feature\"><i class=\"fas fa-check\"></i> Bien-être</div><div class=\"feature\"><i class=\"fas fa-check\"></i> Luxe</div></div><button type=\"button\" class=\"btn-primary\">Send</button></div></div></div></div></section><!-- Vente Forfaits Europe - STATIC HTML --><section id=\"europe\" class=\"packages-section\"><div class=\"container\"><div class=\"category-title\"><i class=\"fas fa-globe-europe\"></i><h2>Forfaits Europe</h2></div><div class=\"packages-grid\"><!-- Forfait Europe 1 --><div class=\"package-card\"><div class=\"package-image\"><img src=\"data:image/jpeg;base64,\" alt=\"Paris\" loading=\"lazy\" id=\"if6g81\"/><div class=\"package-badge\">COUPLE</div></div><div class=\"package-content\"><div class=\"package-header\"><h3>Romantique Paris</h3><div class=\"package-price\">$2899<span>/pers.</span></div></div><div class=\"package-location\"><i class=\"fas fa-map-marker-alt\"></i><span>Paris, France</span></div><p class=\"package-description\">Week-end romantique à Paris avec croisière sur la Seine, dîner gastronomique et visite des monuments emblématiques.</p><div class=\"package-features\"><div class=\"feature\"><i class=\"fas fa-check\"></i> Romantique</div><div class=\"feature\"><i class=\"fas fa-check\"></i> Culture</div><div class=\"feature\"><i class=\"fas fa-check\"></i> Gastronomie</div></div><button type=\"button\" class=\"btn-primary\">Send</button></div></div><!-- Forfait Europe 2 --><div class=\"package-card\"><div class=\"package-image\"><img src=\"data:image/jpeg;base64,\" alt=\"Toscane\" loading=\"lazy\" id=\"ild4b8\"/><div class=\"package-badge\">EXCLUSIF</div></div><div class=\"package-content\"><div class=\"package-header\"><h3>Route des Vins Toscane</h3><div class=\"package-price\">$3299<span>/pers.</span></div></div><div class=\"package-location\"><i class=\"fas fa-map-marker-alt\"></i><span>Toscane, Italie</span></div><p class=\"package-description\">Circuit œnologique dans les plus beaux domaines viticoles toscans. Dégustations, ateliers et hébergement dans un agriturismo.</p><div class=\"package-features\"><div class=\"feature\"><i class=\"fas fa-check\"></i> Vin</div><div class=\"feature\"><i class=\"fas fa-check\"></i> Gastronomie</div><div class=\"feature\"><i class=\"fas fa-check\"></i> Détente</div></div><button type=\"button\" class=\"btn-primary\">Send</button></div></div><!-- Forfait Europe 3 --><div class=\"package-card\"><div class=\"package-image\"><img src=\"https://images.pexels.com/photos/189349/pexels-photo-189349.jpeg?auto=compress&amp;cs=tinysrgb&amp;w=1260&amp;h=750&amp;dpr=2\" alt=\"Islande\" loading=\"lazy\"/><div class=\"package-badge\">INCONTOURNABLE</div></div><div class=\"package-content\"><div class=\"package-header\"><h3>Aurores Boréales Islande</h3><div class=\"package-price\">$3999<span>/pers.</span></div></div><div class=\"package-location\"><i class=\"fas fa-map-marker-alt\"></i><span>Reykjavik, Islande</span></div><p class=\"package-description\">Chasse aux aurores boréales, bains géothermiques et découverte des paysages lunaires islandais.</p><div class=\"package-features\"><div class=\"feature\"><i class=\"fas fa-check\"></i> Aventure</div><div class=\"feature\"><i class=\"fas fa-check\"></i> Nordique</div><div class=\"feature\"><i class=\"fas fa-check\"></i> Photographie</div></div><button type=\"button\" class=\"btn-primary\">Send</button></div></div></div></div></section><!-- Section Afficher vos forfaits ici - STATIC HTML --><section id=\"showcase\" class=\"showcase-packages\"><div class=\"container\"><div class=\"showcase-header\"><h2>Afficher vos forfaits ici</h2><p>Découvrez tous nos forfaits exclusifs en un coup d\'œil</p></div><div class=\"showcase-grid\"><div class=\"showcase-item\"><span class=\"showcase-badge quebec\">Québec</span><h4><i class=\"fas fa-maple-leaf\"></i> Escapade Montréal</h4><p>Séjour de 5 jours dans les plus belles villes du Québec.</p><div class=\"showcase-price\">$1899<span>/pers.</span></div></div><div class=\"showcase-item\"><span class=\"showcase-badge quebec\">Québec</span><h4><i class=\"fas fa-maple-leaf\"></i> Aventure Gaspésie</h4><p>Parc national Forillon, observation des baleines.</p><div class=\"showcase-price\">$2199<span>/pers.</span></div></div><div class=\"showcase-item\"><span class=\"showcase-badge quebec\">Québec</span><h4><i class=\"fas fa-maple-leaf\"></i> Ski &amp; Spa Charlevoix</h4><p>Forfait ski avec hébergement luxueux et spa nordique.</p><div class=\"showcase-price\">$2499<span>/pers.</span></div></div><div class=\"showcase-item\"><span class=\"showcase-badge europe\">Europe</span><h4><i class=\"fas fa-globe-europe\"></i> Romantique Paris</h4><p>Week-end romantique avec croisière sur la Seine.</p><div class=\"showcase-price\">$2899<span>/pers.</span></div></div><div class=\"showcase-item\"><span class=\"showcase-badge europe\">Europe</span><h4><i class=\"fas fa-globe-europe\"></i> Route des Vins Toscane</h4><p>Circuit œnologique dans les domaines viticoles.</p><div class=\"showcase-price\">$3299<span>/pers.</span></div></div><div class=\"showcase-item\"><span class=\"showcase-badge europe\">Europe</span><h4><i class=\"fas fa-globe-europe\"></i> Aurores Boréales Islande</h4><p>Chasse aux aurores boréales et bains géothermiques.</p><div class=\"showcase-price\">$3999<span>/pers.</span></div></div></div></div></section><!-- Section Création de forfaits - STATIC HTML --><section id=\"creation\" class=\"creation-section\"><div class=\"container\"><div class=\"creation-card\"><div class=\"creation-info\"><h3>Créez votre forfait personnalisé</h3><p>Composez le voyage de vos rêves en quelques clics. Sélectionnez vos destinations, activités et hébergements préférés.</p><ul class=\"features-list\"><li><i class=\"fas fa-check-circle\"></i> Choix illimité de destinations</li><li><i class=\"fas fa-check-circle\"></i> Activités sur mesure</li><li><i class=\"fas fa-check-circle\"></i> Hébergements premium</li><li><i class=\"fas fa-check-circle\"></i> Devis instantané</li><li><i class=\"fas fa-check-circle\"></i> Support personnalisé 24/7</li></ul></div><div class=\"creation-form\"><h3>Nouveau forfait</h3><form method=\"get\" id=\"package-creation-form\"><div class=\"form-group\"><label for=\"package-title\">Titre du forfait</label><input type=\"text\" id=\"package-title\" placeholder=\"Ex: Escapade à Montréal\" value=\"Nouveau forfait Québec\"/></div><div class=\"form-group\"><label for=\"package-category\">Catégorie</label><select id=\"package-category\"><option value=\"\">Sélectionnez une catégorie</option><option value=\"quebec\" selected>Québec</option><option value=\"europe\">Europe</option></select></div><div class=\"form-group\"><label for=\"package-destination\">Destination</label><input type=\"text\" id=\"package-destination\" placeholder=\"Ville, Pays\" value=\"Ville de Québec\"/></div><div class=\"form-group\"><label for=\"package-price\">Prix (par personne)</label><input type=\"number\" id=\"package-price\" placeholder=\"1899\" value=\"1999\"/></div><div class=\"form-group\"><label for=\"package-description\">Description</label><textarea id=\"package-description\" placeholder=\"Décrivez votre forfait...\">Découvrez les charmes de la ville de Québec avec ce forfait exclusif.</textarea></div><div class=\"form-group\"><label for=\"package-image\">URL de l\'image</label><input type=\"url\" id=\"package-image\" placeholder=\"https://example.com/image.jpg\" value=\"https://images.pexels.com/photos/208745/pexels-photo-208745.jpeg\"/></div><button type=\"submit\" class=\"btn-create\">Send</button></form></div></div></div></section><!-- Footer --></body>', '* { box-sizing: border-box; } body {margin: 0;}*{margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;box-sizing:border-box;}body{font-family:Inter, sans-serif;backgroun