und-clip:initial;background-color:rgba(255, 255, 255, 0.05);border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-right-radius:20px;border-bottom-left-radius:20px;padding-top:40px;padding-right:40px;padding-bottom:40px;padding-left:40px;}.creation-form h3{color:rgb(248, 250, 255);margin-bottom:25px;}.form-group{margin-bottom:20px;}.form-group label{display:block;margin-bottom:8px;font-weight:600;color:rgba(255, 255, 255, 0.9);}.form-group input, .form-group select, .form-group textarea{width:100%;padding-top:15px;padding-right:20px;padding-bottom:15px;padding-left:20px;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgba(255, 255, 255, 0.08);border-top-width:1px;border-right-width:1px;border-bottom-width:1px;border-left-width:1px;border-top-style:solid;border-right-style:solid;border-bottom-style:solid;border-left-style:solid;border-top-color:rgba(255, 255, 255, 0.1);border-right-color:rgba(255, 255, 255, 0.1);border-bottom-color:rgba(255, 255, 255, 0.1);border-left-color:rgba(255, 255, 255, 0.1);border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-right-radius:12px;border-bottom-left-radius:12px;color:white;font-family:Inter, sans-serif;font-size:1rem;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:all;}.form-group input:focus, .form-group select:focus, .form-group textarea:focus{outline-color:initial;outline-style:none;outline-width:initial;border-top-color:rgb(0, 102, 204);border-right-color:rgb(0, 102, 204);border-bottom-color:rgb(0, 102, 204);border-left-color:rgb(0, 102, 204);background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgba(255, 255, 255, 0.12);}.form-group textarea{height:100px;resize:vertical;}.btn-create{background-image:linear-gradient(135deg, rgb(0, 102, 204), rgb(0, 204, 153));background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;color:white;border-top-width:initial;border-right-width:initial;border-bottom-width:initial;border-left-width:initial;border-top-style:none;border-right-style:none;border-bottom-style:none;border-left-style:none;border-top-color:initial;border-right-color:initial;border-bottom-color:initial;border-left-color:initial;border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;padding-top:18px;padding-right:18px;padding-bottom:18px;padding-left:18px;border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-right-radius:12px;border-bottom-left-radius:12px;font-weight:700;cursor:pointer;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:all;width:100%;font-size:1.1rem;display:flex;align-items:center;justify-content:center;row-gap:10px;column-gap:10px;margin-top:10px;}.btn-create:hover{transform:translateY(-3px);box-shadow:rgba(0, 102, 204, 0.5) 0px 10px 30px;}footer{background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(26, 43, 60);padding-top:80px;padding-right:0px;padding-bottom:40px;padding-left:0px;margin-top:100px;position:relative;overflow-x:hidden;overflow-y:hidden;}.footer-section h3{font-size:1.5rem;margin-bottom:25px;position:relative;display:inline-block;color:rgb(248, 250, 255);}.footer-section h3::after{content:\"\";position:absolute;width:40px;height:4px;background-image:linear-gradient(135deg, rgb(0, 102, 204), rgb(0, 204, 153));background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;bottom:-8px;left:0px;border-top-left-radius:2px;border-top-right-radius:2px;border-bottom-right-radius:2px;border-bottom-left-radius:2px;}.footer-links li{margin-bottom:12px;}.footer-links a{color:rgba(255, 255, 255, 0.7);text-decoration-line:none;text-decoration-thickness:initial;text-decoration-style:initial;text-decoration-color:initial;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:all;display:flex;align-items:center;row-gap:10px;column-gap:10px;}.footer-links a:hover{color:rgb(51, 153, 255);transform:translateX(5px);}.copyright a{color:rgb(0, 204, 153);text-decoration-line:none;text-decoration-thickness:initial;text-decoration-style:initial;text-decoration-color:initial;}.gjs-dashed .package-card, .gjs-dashed .showcase-item, .gjs-dashed .creation-card{pointer-events:all;cursor:pointer;}[data-gjs-type=\"wrapper\"]{min-height:100vh;}.package-card{display:block;}.showcase-item{display:block;}@keyframes float{0%, 100%{transform:translateY(0px) translateX(0px);}33%{transform:translateY(-30px) translateX(20px);}66%{transform:translateY(20px) translateX(-20px);}}@keyframes textShine{0%{background-position-x:0%;background-position-y:50%;}100%{background-position-x:100%;background-position-y:50%;}}@media (max-width: 1200px){.hero h1{font-size:3.2rem;}.creation-card{grid-template-columns:1fr;}}@media (max-width: 992px){.hero h1{font-size:2.8rem;}.packages-grid{grid-template-columns:repeat(auto-fill, minmax(300px, 1fr));}}@media (max-width: 768px){.container{padding-top:0px;padding-right:20px;padding-bottom:0px;padding-left:20px;}.hero h1{font-size:2.2rem;}.hero p{font-size:1.1rem;}.category-title{font-size:2rem;}.showcase-header h2{font-size:2.2rem;}.creation-card{padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px;}.creation-form{padding-top:25px;padding-right:25px;padding-bottom:25px;padding-left:25px;}.packages-grid{grid-template-columns:1fr;}.showcase-grid{grid-template-columns:1fr;}}', '{\"title\": \"Info forfaits\", \"keywords\": \"Info forfaits, tourisme, voyage\", \"description\": \"Page de Info forfaits\"}', 'draft', 'info-forfaits-go-exploria-aWACnz', '2026-02-04 18:04:02', '2026-02-12 12:23:42');
INSERT INTO `menus` (`id`, `title`, `slug`, `type`, `parent_id`, `reference_id`, `menu_type`, `order`, `route`, `url`, `icon`, `is_active`, `has_page`, `page_id`, `page_content`, `page_styles`, `page_meta`, `page_status`, `page_slug`, `created_at`, `updated_at`) VALUES
(23, 'Info voyages', 'info-voyages-go-exploria', 'custom', NULL, NULL, 'Accueil', 9, NULL, '#info-voyages-go-exploria', NULL, 1, 1, NULL, '\n<body>\n  <!-- Section Voyage - Compatible GrapesJS -->\n  <section class=\"travel-section\">\n    <div class=\"travel-container\">\n      \n      <!-- COLONNE GAUCHE : ALERTS VOYAGE -->\n      <div class=\"travel-alerts\">\n        <div class=\"section-header\">\n          <div class=\"section-icon\">\n            ⚠️\n          </div>\n          <div>\n            <h2 class=\"section-title\">Alertes voyage</h2>\n            <p class=\"section-sub\">Informations en temps réel • 3 alertes</p>\n          </div>\n        </div>\n\n        <!-- Alerte 1 - Orange (Météo) -->\n        <div class=\"alert-card\">\n          <div class=\"alert-icon alert-orange\">🌪️</div>\n          <div class=\"alert-content\">\n            <h3 class=\"alert-title\">Fortes turbulences - Atlantique Nord</h3>\n            <p class=\"alert-desc\">Des turbulences sévères sont signalées sur les vols entre New York et Londres. Prévoyez des retards possibles.</p>\n            <div class=\"alert-meta\">\n              <span class=\"meta-item\">🕒 Il y a 25 min</span>\n              <span class=\"meta-item\">📍 Zone A4</span>\n              <span class=\"meta-item\">🔔 8 vols concernés</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- Alerte 2 - Bleue (Grève) -->\n        <div class=\"alert-card\">\n          <div class=\"alert-icon alert-blue\">✊</div>\n          <div class=\"alert-content\">\n            <h3 class=\"alert-title\">Mouvement social - Aéroport de Paris</h3>\n            <p class=\"alert-desc\">Préavis de grève des contrôleurs aériens ce vendredi. Jusqu\'à 40% des vols pourraient être annulés.</p>\n            <div class=\"alert-meta\">\n              <span class=\"meta-item\">🕒 Il y a 2h</span>\n              <span class=\"meta-item\">📍 CDG, ORY</span>\n              <span class=\"meta-item\">📅 15-16 Mars</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- Alerte 3 - Rouge (Sécurité) -->\n        <div class=\"alert-card\">\n          <div class=\"alert-icon alert-red\">🛡️</div>\n          <div class=\"alert-content\">\n            <h3 class=\"alert-title\">Niveau de sécurité renforcé - Tel Aviv</h3>\n            <p class=\"alert-desc\">Mesures de contrôle supplémentaires. Prévoyez 3h d\'avance pour votre départ.</p>\n            <div class=\"alert-meta\">\n              <span class=\"meta-item\">🕒 Il y a 45 min</span>\n              <span class=\"meta-item\">📍 TLV</span>\n              <span class=\"meta-item\">⚠️ Vigilance</span>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- COLONNE DROITE : BULLETS D\'AVIONS -->\n      <div class=\"travel-bullets\">\n        <div class=\"section-header\">\n          <div class=\"section-icon\">\n            ✈\n          </div>\n          <div>\n            <h2 class=\"section-title\">Vols en direct</h2>\n            <p class=\"section-sub\">Suivi des départs • 4 vols</p>\n          </div>\n        </div>\n\n        <div class=\"bullets-grid\">\n          <!-- Bullet 1 - AF 164 -->\n          <div class=\"bullet-item\">\n            <div class=\"plane-icon\">\n              ✈\n            </div>\n            <div class=\"plane-details\">\n              <h4 class=\"plane-route\">\n                <span>AF 164</span>\n                <span style=\"font-size: 14px; color: #62748b;\">✈</span>\n              </h4>\n              <p class=\"plane-status\">\n                Paris → New York\n                <span class=\"status-badge\">À l\'heure</span>\n              </p>\n              <div class=\"flight-time\">\n                <span>🕒 14:45 • Terminal 2E</span>\n              </div>\n              <div class=\"weather-badge\">\n                <span>☁️ 7°C • Visibilité bonne</span>\n              </div>\n            </div>\n          </div>\n\n          <!-- Bullet 2 - LH 456 -->\n          <div class=\"bullet-item\">\n            <div class=\"plane-icon\">\n              ✈\n            </div>\n            <div class=\"plane-details\">\n              <h4 class=\"plane-route\">\n                <span>LH 456</span>\n              </h4>\n              <p class=\"plane-status\">\n                Francfort → Tokyo\n                <span class=\"status-badge status-warning\">Retard 25min</span>\n              </p>\n              <div class=\"flight-time\">\n                <span>🕒 22:10 • Porte B43</span>\n              </div>\n              <div class=\"weather-badge\">\n                <span>🌧 13°C • Pluie légère</span>\n              </div>\n            </div>\n          </div>\n\n          <!-- Bullet 3 - BA 278 -->\n          <div class=\"bullet-item\">\n            <div class=\"plane-icon\">\n              ✈\n            </div>\n            <div class=\"plane-details\">\n              <h4 class=\"plane-route\">\n                <span>BA 278</span>\n              </h4>\n              <p class=\"plane-status\">\n                Londres → Dubai\n                <span class=\"status-badge\">À l\'heure</span>\n              </p>\n              <div class=\"flight-time\">\n                <span>🕒 09:20 • Gate 12</span>\n              </div>\n              <div class=\"weather-badge\">\n                <span>☀️ 28°C • Ciel dégagé</span>\n              </div>\n            </div>\n          </div>\n\n          <!-- Bullet 4 - EK 202 -->\n          <div class=\"bullet-item\">\n            <div class=\"plane-icon\">\n              ✈\n            </div>\n            <div class=\"plane-details\">\n              <h4 class=\"plane-route\">\n                <span>EK 202</span>\n              </h4>\n              <p class=\"plane-status\">\n                Milan → Dubaï\n                <span class=\"status-badge\">Embarquement</span>\n              </p>\n              <div class=\"flight-time\">\n                <span>🕒 16:30 • Porte D7</span>\n              </div>\n              <div class=\"weather-badge\">\n                <span>☀️ 22°C • Vent faible</span>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Lien voir tous les vols -->\n        <div style=\"margin-top: 28px; text-align: right;\">\n          <span style=\"display: inline-flex; align-items: center; gap: 8px; background: white; padding: 12px 24px; border-radius: 40px; font-weight: 600; color: #2563eb; box-shadow: 0 6px 12px -6px rgba(0,0,0,0.1); border: 1px solid #e2e8f0; font-size: 15px;\">\n            Voir tous les vols → \n          </span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Note pour GrapesJS: structure facile à éditer -->\n</body>', '\n        /* Styles très basiques pour GrapeJS */\n        body {\n            font-family: Arial, sans-serif;\n            margin: 0;\n            padding: 0;\n            background-color: #f5f5f5;\n            color: #333;\n        }\n        \n        .simple-section {\n            padding: 60px 20px;\n        }\n        \n        .section-container {\n            max-width: 1200px;\n            margin: 0 auto;\n        }\n        \n        #section-1 {\n            background: linear-gradient(to right, #4facfe 0%, #00f2fe 100%);\n            color: white;\n            text-align: center;\n        }\n        \n        #section-1 h1 {\n            font-size: 2.5em;\n            margin-bottom: 20px;\n        }\n        \n        #section-1 p {\n            font-size: 1.2em;\n            max-width: 600px;\n            margin: 0 auto;\n        }\n        \n        #section-2 {\n            background: white;\n        }\n        \n        .content-block {\n            background: #fff;\n            padding: 40px;\n            border-radius: 10px;\n            box-shadow: 0 5px 15px rgba(0,0,0,0.1);\n        }\n        \n        #section-2 h2 {\n            color: #2c3e50;\n            margin-bottom: 20px;\n            font-size: 2em;\n        }\n        \n        #section-2 p {\n            line-height: 1.6;\n            margin-bottom: 15px;\n            color: #555;\n        }\n        \n        /* Responsive */\n        @media (max-width: 768px) {\n            .simple-section {\n                padding: 40px 15px;\n            }\n            \n            #section-1 h1 {\n                font-size: 2em;\n            }\n            \n            .content-block {\n                padding: 25px;\n            }\n        }\n        \n        /* GrapeJS compatibility */\n        [data-gjs-type=\"section\"] {\n            min-height: 100px;\n        }\n        \n        [data-gjs-type=\"text\"] {\n            min-height: 20px;\n        }\n     .travel-section {\n      font-family: \'Inter\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, sans-serif;\n      max-width: 1280px;\n      margin: 0 auto;\n      padding: 60px 24px;\n      background: linear-gradient(145deg, #f8fafc 0%, #f1f5f9 100%);\n      border-radius: 48px 48px 48px 48px;\n      position: relative;\n      overflow: hidden;\n    }\n\n    /* Éléments décoratifs */\n    .travel-section::before {\n      content: \"✈\";\n      position: absolute;\n      top: -30px;\n      right: -30px;\n      font-size: 200px;\n      opacity: 0.03;\n      transform: rotate(15deg);\n      color: #0f172a;\n    }\n\n    .travel-container {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 32px;\n      position: relative;\n      z-index: 2;\n    }\n\n    /* Colonne gauche - Alerts */\n    .travel-alerts {\n      flex: 1 1 55%;\n      min-width: 300px;\n    }\n\n    /* Colonne droite - Bullets d\'avions */\n    .travel-bullets {\n      flex: 1 1 35%;\n      min-width: 250px;\n    }\n\n    /* En-têtes */\n    .section-header {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      margin-bottom: 28px;\n    }\n\n    .section-icon {\n      width: 48px;\n      height: 48px;\n      background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);\n      border-radius: 20px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: white;\n      font-size: 24px;\n      box-shadow: 0 10px 20px -8px rgba(37, 99, 235, 0.3);\n    }\n\n    .section-title {\n      font-size: 28px;\n      font-weight: 700;\n      color: #0f172a;\n      margin: 0;\n      letter-spacing: -0.5px;\n    }\n\n    .section-sub {\n      font-size: 14px;\n      color: #475569;\n      margin: 4px 0 0 0;\n      font-weight: 400;\n    }\n\n    /* Cartes d\'alertes */\n    .alert-card {\n      background: white;\n      border-radius: 28px;\n      padding: 24px;\n      margin-bottom: 20px;\n      box-shadow: 0 15px 30px -12px rgba(0, 0, 0, 0.1);\n      border: 1px solid rgba(255, 255, 255, 0.5);\n      backdrop-filter: blur(10px);\n      transition: all 0.2s ease;\n      display: flex;\n      align-items: flex-start;\n      gap: 16px;\n    }\n\n    .alert-card:hover {\n      transform: translateY(-3px);\n      box-shadow: 0 25px 40px -15px rgba(0, 0, 0, 0.15);\n    }\n\n    .alert-icon {\n      width: 44px;\n      height: 44px;\n      border-radius: 16px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 22px;\n      flex-shrink: 0;\n    }\n\n    .alert-orange {\n      background: linear-gradient(145deg, #fff7ed, #ffedd5);\n      color: #9a3412;\n    }\n\n    .alert-blue {\n      background: linear-gradient(145deg, #eff6ff, #dbeafe);\n      color: #1e40af;\n    }\n\n    .alert-red {\n      background: linear-gradient(145deg, #fef2f2, #fee2e2);\n      color: #b91c1c;\n    }\n\n    .alert-green {\n      background: linear-gradient(145deg, #f0fdf4, #dcfce7);\n      color: #166534;\n    }\n\n    .alert-content {\n      flex: 1;\n    }\n\n    .alert-title {\n      font-weight: 700;\n      font-size: 18px;\n      margin: 0 0 6px 0;\n      color: #0f172a;\n    }\n\n    .alert-desc {\n      font-size: 15px;\n      color: #334155;\n      margin: 0 0 12px 0;\n      line-height: 1.5;\n    }\n\n    .alert-meta {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      font-size: 13px;\n      color: #64748b;\n    }\n\n    .meta-item {\n      display: flex;\n      align-items: center;\n      gap: 4px;\n    }\n\n    /* Bullets d\'avions */\n    .bullets-grid {\n      display: grid;\n      grid-template-columns: 1fr;\n      gap: 18px;\n    }\n\n    .bullet-item {\n      background: white;\n      border-radius: 22px;\n      padding: 20px;\n      display: flex;\n      align-items: center;\n      gap: 18px;\n      box-shadow: 0 10px 20px -8px rgba(0, 0, 0, 0.05);\n      border: 1px solid rgba(226, 232, 240, 0.6);\n      transition: all 0.2s ease;\n    }\n\n    .bullet-item:hover {\n      border-color: #94a3b8;\n      background: white;\n    }\n\n    .plane-icon {\n      width: 54px;\n      height: 54px;\n      background: linear-gradient(145deg, #f1f5f9, #e2e8f0);\n      border-radius: 18px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 28px;\n      color: #2563eb;\n      flex-shrink: 0;\n    }\n\n    .plane-details {\n      flex: 1;\n    }\n\n    .plane-route {\n      font-weight: 700;\n      font-size: 18px;\n      color: #0f172a;\n      margin: 0 0 4px 0;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n    }\n\n    .plane-status {\n      font-size: 14px;\n      color: #475569;\n      margin: 0;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .status-badge {\n      background: #e6f7e6;\n      color: #0a5c0a;\n      padding: 4px 10px;\n      border-radius: 30px;\n      font-size: 12px;\n      font-weight: 600;\n    }\n\n    .status-warning {\n      background: #fff3cd;\n      color: #856404;\n    }\n\n    .flight-time {\n      font-size: 13px;\n      color: #62748b;\n      display: flex;\n      align-items: center;\n      gap: 4px;\n      margin-top: 6px;\n    }\n\n    /* Badges météo / infos */\n    .weather-badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      background: rgba(203, 213, 225, 0.3);\n      padding: 6px 14px;\n      border-radius: 40px;\n      font-size: 13px;\n      color: #1e293b;\n      margin-top: 8px;\n    }\n\n    /* Responsive */\n    @media (max-width: 768px) {\n      .travel-container {\n        flex-direction: column;\n      }\n      \n      .travel-section {\n        padding: 40px 20px;\n        border-radius: 32px;\n      }\n      \n      .section-title {\n        font-size: 24px;\n      }\n    }\n\n    /* GrapesJS: classes draggables facilement identifiables */\n    .gjs-draggable {\n      cursor: move;\n    }\n\n    /* Animation subtle */\n    @keyframes float {\n      0% { transform: translateY(0px); }\n      50% { transform: translateY(-5px); }\n      100% { transform: translateY(0px); }\n    }\n\n    .animate-float {\n      animation: float 6s ease-in-out infinite;\n    }', '{\"title\": \"Info voyages\", \"keywords\": \"Info voyages, tourisme, voyage\", \"description\": \"Page de Info voyages\"}', 'draft', 'info-voyages-go-exploria-FwV3hB', '2026-02-04 18:06:50', '2026-02-12 15:25:05'),
