                  images: [\n                        \"https://images.unsplash.com/photo-1552374196-1ab2a1c593e8?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1200&q=80\",\n                        \"https://images.unsplash.com/photo-1594633312681-425c7b97ccd1?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1200&q=80\"\n                    ],\n                    colors: [\n                        {name: \"Noir\", hex: \"#000000\"},\n                        {name: \"Blanc\", hex: \"#FFFFFF\"},\n                        {name: \"Gris\", hex: \"#808080\"},\n                        {name: \"Bleu Marine\", hex: \"#000080\"}\n                    ],\n                    sizes: [\"XS\", \"S\", \"M\", \"L\", \"XL\"],\n                    badge: \"new\",\n                    material: \"Mérinos 85%, Élasthanne 15%\",\n                    features: [\"Respirant\", \"Ajusté\", \"Anti-odeur\", \"Évacuation humidité\"]\n                },\n                {\n                    id: 12,\n                    name: \"Collant Thermique\",\n                    category: \"baselayers\",\n                    price: \"24,99 €\",\n                    originalPrice: \"34,99 €\",\n                    description: \"Collant thermique ultra-fin pour rester au chaud sous les vêtements. Transparent et invisible sous les vêtements.\",\n                    images: [\n                        \"https://images.unsplash.com/photo-1594633312681-425c7b97ccd1?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1200&q=80\",\n                        \"https://images.unsplash.com/photo-1576871337632-b9aef4c17ab9?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1200&q=80\"\n                    ],\n                    colors: [\n                        {name: \"Naturel\", hex: \"#F5DEB3\"},\n                        {name: \"Noir\", hex: \"#000000\"},\n                        {name: \"Brun\", hex: \"#8B4513\"}\n                    ],\n                    sizes: [\"S\", \"M\", \"L\", \"XL\"],\n                    badge: \"sale\",\n                    material: \"Nylon 92%, Élasthanne 8%\",\n                    features: [\"Ultra-fin\", \"Invisible\", \"Chaleur thermique\", \"Confortable\"]\n                }\n            ]\n        };\n\n        // Initialisation\n        $(document).ready(function() {\n            // Générer l\'effet de neige\n            createSnowflakes();\n            \n            // Générer tous les produits initialement\n            generateAllProducts();\n            \n            // Gestion des filtres de catégorie\n            $(\'.category-btn\').on(\'click\', function() {\n                $(\'.category-btn\').removeClass(\'active\');\n                $(this).addClass(\'active\');\n                \n                const category = $(this).data(\'category\');\n                filterProductsByCategory(category);\n                \n                // Animation du bouton\n                $(this).css(\'transform\', \'scale(0.95)\');\n                setTimeout(() => {\n                    $(this).css(\'transform\', \'\');\n                }, 200);\n            });\n            \n            // Gestion de la fermeture de la modal\n            $(\'#modal-close\').on(\'click\', closeModal);\n            $(\'#product-modal-overlay\').on(\'click\', function(e) {\n                if (e.target === this) {\n                    closeModal();\n                }\n            });\n            \n            // Fermer la modal avec la touche Échap\n            $(document).on(\'keydown\', function(e) {\n                if (e.key === \'Escape\') {\n                    closeModal();\n                }\n            });\n        });\n\n        // Fonction pour créer l\'effet de neige\n        function createSnowflakes() {\n            const snowContainer = $(\'#snow-container\');\n            const snowflakeCount = 50;\n            \n            for (let i = 0; i < snowflakeCount; i++) {\n                const snowflake = $(\'<div class=\"snowflake\"></div>\');\n                const size = Math.random() * 5 + 3;\n                const posX = Math.random() * 100;\n                const duration = Math.random() * 10 + 10;\n                const delay = Math.random() * 10;\n                \n                snowflake.css({\n                    width: `${size}px`,\n                    height: `${size}px`,\n                    left: `${posX}%`,\n                    opacity: Math.random() * 0.7 + 0.3,\n                    animationDuration: `${duration}s`,\n                    animationDelay: `${delay}s`\n                });\n                \n                snowContainer.append(snowflake);\n            }\n        }\n\n        // Fonction pour générer tous les produits\n        function generateAllProducts() {\n            const container = $(\'#products-container\');\n            // Ne pas vider le contenu s\'il y a déjà des éléments (pour préserver l\'éditeur)\n            if (container.children().length <= 1) {\n                container.empty();\n                \n                let allProducts = [];\n                \n                // Combiner tous les produits de toutes les catégories\n                for (const category in winterProducts) {\n                    allProducts = allProducts.concat(winterProducts[category]);\n                }\n                \n                // Trier par ID pour un affichage cohérent\n                allProducts.sort((a, b) => a.id - b.id);\n                \n                // Générer les cartes de produits\n                allProducts.forEach((product, index) => {\n                    const productCard = createProductCard(product, index);\n                    container.append(productCard);\n                });\n                \n                // Ajouter les événements aux cartes\n                attachProductCardEvents();\n            }\n        }\n\n        // Fonction pour créer une carte produit\n        function createProductCard(product, index) {\n            const colorDots = product.colors.map(color => \n                `<div class=\"color-dot\" style=\"background-color: ${color.hex};\" data-gjs-type=\"color-dot\"></div>`\n            ).join(\'\');\n            \n            const sizeChips = product.sizes.map(size => \n                `<span class=\"size-chip\" data-gjs-type=\"size-chip\" data-gjs-editable=\"true\">${size}</span>`\n            ).join(\'\');\n            \n            const badgeClass = `product-card-badge ${product.badge}`;\n            const badgeText = product.badge === \'new\' ? \'Nouveau\' : \n                             product.badge === \'sale\' ? \'Promo\' : \n                             product.badge === \'limited\' ? \'Limitée\' : \'\';\n            \n            const priceHtml = product.originalPrice ? \n                `<div class=\"product-card-price\" data-gjs-type=\"product-price\">\n                    <span class=\"current-price\" data-gjs-type=\"current-price\" data-gjs-editable=\"true\">${product.price}</span>\n                    <span class=\"original-price\" data-gjs-type=\"original-price\" data-gjs-editable=\"true\">${product.originalPrice}</span>\n                </div>` :\n                `<div class=\"product-card-price\" data-gjs-type=\"product-price\">\n                    <span class=\"current-price\" data-gjs-type=\"current-price\" data-gjs-editable=\"true\">${product.price}</span>\n                </div>`;\n            \n            return `\n                <div class=\"product-card\" data-id=\"${product.id}\" data-category=\"${product.category}\" data-gjs-type=\"product-card\">\n                    ${badgeText ? `<div class=\"${badgeClass}\" data-gjs-type=\"product-badge\" data-gjs-editable=\"true\">${badgeText}</div>` : \'\'}\n                    <div class=\"product-card-image\" data-gjs-type=\"product-image\">\n                        <img src=\"${product.images[0]}\" alt=\"${product.name}\" data-gjs-type=\"image\" data-gjs-editable=\"true\">\n                        <button class=\"quick-view-btn\" data-id=\"${product.id}\" data-gjs-type=\"quick-view-button\" data-gjs-editable=\"true\">\n                            <i class=\"fas fa-eye\"></i> Voir le produit\n                        </button>\n                    </div>\n                    <div class=\"product-card-content\" data-gjs-type=\"product-content\">\n                        <h3 class=\"product-card-title\" data-gjs-type=\"product-title\" data-gjs-editable=\"true\">${product.name}</h3>\n                        ${priceHtml}\n                        <div class=\"product-card-colors\" data-gjs-type=\"product-colors\">\n                            ${colorDots}\n                        </div>\n                        <div class=\"product-card-sizes\" data-gjs-type=\"product-sizes\">\n                            ${sizeChips}\n                        </div>\n                    </div>\n                </div>\n            `;\n        }\n\n        // Fonction pour attacher les événements aux cartes\n        function attachProductCardEvents() {\n            $(\'.quick-view-btn\').on(\'click\', function(e) {\n                e.stopPropagation();\n                const productId = parseInt($(this).data(\'id\'));\n                openProductModal(productId);\n            });\n            \n            $(\'.product-card\').on(\'click\', function(e) {\n                if (!$(e.target).closest(\'.quick-view-btn\').length) {\n                    const productId = parseInt($(this).data(\'id\'));\n                    openProductModal(productId);\n                }\n            });\n        }\n\n        // Fonction pour filtrer les produits par catégorie\n        function filterProductsByCategory(category) {\n            const container = $(\'#products-container\');\n            // Sauvegarder le premier élément (exemple pour l\'éditeur)\n            const firstElement = container.children().first();\n            container.empty();\n            container.append(firstElement);\n            \n            let productsToShow;\n            \n            if (category === \'all\') {\n                // Combiner tous les produits\n                productsToShow = [];\n                for (const cat in winterProducts) {\n                    productsToShow = productsToShow.concat(winterProducts[cat]);\n                }\n                productsToShow.sort((a, b) => a.id - b.id);\n            } else {\n                productsToShow = winterProducts[category] || [];\n            }\n            \n            // Animation de sortie des anciens produits\n            container.css(\'opacity\', \'0\');\n            \n            setTimeout(() => {\n                // Générer les nouveaux produits\n                productsToShow.forEach((product, index) => {\n                    const productCard = createProductCard(product, index);\n                    container.append(productCard);\n                });\n                \n                // Réattacher les événements\n                attachProductCardEvents();\n                \n                // Animation d\'entrée des nouveaux produits\n                container.css(\'opacity\', \'1\');\n            }, 300);\n        }\n\n        // Fonction pour ouvrir la modal d\'un produit\n        function openProductModal(productId) {\n            // Trouver le produit\n            let product = null;\n            for (const category in winterProducts) {\n                const foundProduct = winterProducts[category].find(p => p.id === productId);\n                if (foundProduct) {\n                    product = foundProduct;\n                    break;\n                }\n            }\n            \n            if (!product) return;\n            \n            // Remplir la modal avec les données du produit\n            fillProductModal(product);\n            \n            // Afficher la modal avec animation\n            $(\'#product-modal-overlay\').addClass(\'active\');\n            setTimeout(() => {\n                $(\'#product-modal\').addClass(\'active\');\n            }, 50);\n            \n            // Empêcher le défilement du body\n            $(\'body\').css(\'overflow\', \'hidden\');\n        }\n\n        // Fonction pour remplir la modal avec les données du produit\n        function fillProductModal(product) {\n            const modalContent = $(\'#modal-content\');\n            \n            // Sauvegarder le contenu existant (pour l\'éditeur)\n            const existingContent = modalContent.html();\n            \n            // Créer la galerie d\'images\n            const thumbnails = product.images.map((image, index) => `\n                <div class=\"modal-thumbnail ${index === 0 ? \'active\' : \'\'}\" data-index=\"${index}\" data-gjs-type=\"modal-thumbnail\">\n                    <img src=\"${image}\" alt=\"${product.name} vue ${index + 1}\" data-gjs-type=\"image\" data-gjs-editable=\"true\">\n                </div>\n            `).join(\'\');\n            \n            // Créer les options de couleur\n            const colorOptions = product.colors.map((color, index) => `\n                <div class=\"modal-color-option ${index === 0 ? \'selected\' : \'\'}\" \n                     style=\"background-color: ${color.hex};\"\n                     data-color=\"${color.name}\"\n                     data-hex=\"${color.hex}\"\n                     data-gjs-type=\"modal-color-option\"></div>\n            `).join(\'\');\n            \n            // Créer les options de taille\n            const sizeOptions = product.sizes.map((size, index) => `\n                <div class=\"modal-variant-option ${index === 0 ? \'selected\' : \'\'}\" data-value=\"${size}\" data-gjs-type=\"modal-variant-option\" data-gjs-editable=\"true\">${size}</div>\n            `).join(\'\');\n            \n            // Créer la liste des caractéristiques\n            const featuresList = product.features.map(feature => `\n                <li><i class=\"fas fa-check\"></i> ${feature}</li>\n            `).join(\'\');\n            \n            // Prix avec promotion si applicable\n            const priceHtml = product.originalPrice ? \n                `<div class=\"modal-price\" data-gjs-type=\"modal-price\">\n                    <span class=\"modal-current-price\" data-gjs-type=\"modal-current-price\" data-gjs-editable=\"true\">${product.price}</span>\n                    <span class=\"modal-original-price\" data-gjs-type=\"modal-original-price\" data-gjs-editable=\"true\">${product.originalPrice}</span>\n                </div>` :\n                `<div class=\"modal-price\" data-gjs-type=\"modal-price\">\n                    <span class=\"modal-current-price\" data-gjs-type=\"modal-current-price\" data-gjs-editable=\"true\">${product.price}</span>\n                </div>`;\n            \n            // HTML complet de la modal\n            modalContent.html(`\n                <div class=\"modal-gallery\" data-gjs-type=\"modal-gallery\">\n                    <div class=\"modal-main-image\" data-gjs-type=\"modal-main-image\">\n                        <img src=\"${product.images[0]}\" alt=\"${product.name}\" id=\"modal-main-image\" data-gjs-type=\"image\" data-gjs-editable=\"true\">\n                    </div>\n                    <div class=\"modal-thumbnails\" data-gjs-type=\"modal-thumbnails\">\n                        ${thumbnails}\n                    </div>\n                </div>\n                <div class=\"modal-details\" data-gjs-type=\"modal-details\">\n                    <span class=\"modal-category\" data-gjs-type=\"modal-category\" data-gjs-editable=\"true\">${getCategoryName(product.category)}</span>\n                    <h2 class=\"modal-title\" data-gjs-type=\"modal-title\" data-gjs-editable=\"true\">${product.name}</h2>\n                    ${priceHtml}\n                    <p class=\"modal-description\" data-gjs-type=\"modal-description\" data-gjs-editable=\"true\">${product.description}</p>\n                    \n                    <div class=\"modal-variant-section\" data-gjs-type=\"modal-variant-section\">\n                        <h3 class=\"modal-variant-title\" data-gjs-type=\"modal-variant-title\" data-gjs-editable=\"true\">Couleur</h3>\n                        <div class=\"modal-variant-options\" id=\"modal-color-options\" data-gjs-type=\"modal-variant-options\">\n                            ${colorOptions}\n                        </div>\n                    </div>\n                    \n                    <div class=\"modal-variant-section\" data-gjs-type=\"modal-variant-section\">\n                        <h3 class=\"modal-variant-title\" data-gjs-type=\"modal-variant-title\" data-gjs-editable=\"true\">Taille</h3>\n                        <div class=\"modal-variant-options\" id=\"modal-size-options\" data-gjs-type=\"modal-variant-options\">\n                            ${sizeOptions}\n                        </div>\n                    </div>\n                    \n                    <div class=\"modal-variant-section\" data-gjs-type=\"modal-variant-section\">\n                        <h3 class=\"modal-variant-title\" data-gjs-type=\"modal-variant-title\" data-gjs-editable=\"true\">Caractéristiques</h3>\n                        <ul style=\"color: var(--warm-gray); padding-left: 20px; margin-top: 10px;\">\n                            ${featuresList}\n                        </ul>\n                        <p style=\"margin-top: 15px; font-size: 0.9rem;\"><strong>Matériau:</strong> ${product.material}</p>\n                    </div>\n                    \n                    <div class=\"modal-actions\" data-gjs-type=\"modal-actions\">\n                        <div class=\"modal-quantity\" data-gjs-type=\"modal-quantity\">\n                            <button class=\"modal-quantity-btn minus\" data-gjs-type=\"modal-quantity-btn\">-</button>\n                            <input type=\"text\" class=\"modal-quantity-input\" value=\"1\" readonly id=\"modal-quantity\" data-gjs-type=\"modal-quantity-input\">\n                            <button class=\"modal-quantity-btn plus\" data-gjs-type=\"modal-quantity-btn\">+</button>\n                        </div>\n                        <button class=\"modal-add-to-cart\" id=\"modal-add-to-cart\" data-gjs-type=\"modal-add-to-cart\" data-gjs-editable=\"true\">\n                            <i class=\"fas fa-shopping-bag\"></i>\n                            Ajouter au panier\n                        </button>\n                        <button class=\"modal-wishlist-btn\" id=\"modal-wishlist\" data-gjs-type=\"modal-wishlist-btn\">\n                            <i class=\"far fa-heart\"></i>\n                        </button>\n                    </div>\n                </div>\n            `);\n            \n            // Attacher les événements de la modal\n            attachModalEvents(product);\n        }\n\n        // Fonction pour obtenir le nom d\'une catégorie\n        function getCategoryName(categoryKey) {\n            const categoryNames = {\n                \'outerwear\': \'Vêtements chauds\',\n                \'knitwear\': \'Pulls & Gilets\',\n                \'accessories\': \'Accessoires\',\n                \'footwear\': \'Chaussures\',\n                \'baselayers\': \'Sous-vêtements\'\n            };\n            return categoryNames[categoryKey] || categoryKey;\n        }\n\n        // Fonction pour attacher les événements dans la modal\n        function attachModalEvents(product) {\n            // Gestion des thumbnails\n            $(\'.modal-thumbnail\').on(\'click\', function() {\n                const index = $(this).data(\'index\');\n                $(\'.modal-thumbnail\').removeClass(\'active\');\n                $(this).addClass(\'active\');\n                \n                const mainImage = $(\'#modal-main-image\');\n                const newImage = product.images[index];\n                \n                // Animation de transition\n                mainImage.css(\'opacity\', \'0\');\n                setTimeout(() => {\n                    mainImage.attr(\'src\', newImage);\n                    mainImage.css(\'opacity\', \'1\');\n                }, 300);\n            });\n            \n            // Gestion des sélections de couleur\n            $(\'#modal-color-options .modal-color-option\').on(\'click\', function() {\n                $(\'#modal-color-options .modal-color-option\').removeClass(\'selected\');\n                $(this).addClass(\'selected\');\n                \n                // Animation\n                $(this).css(\'transform\', \'scale(1.3)\');\n                setTimeout(() => {\n                    $(this).css(\'transform\', \'scale(1.15)\');\n                }, 300);\n            });\n            \n            // Gestion des sélections de taille\n            $(\'#modal-size-options .modal-variant-option\').on(\'click\', function() {\n                $(\'#modal-size-options .modal-variant-option\').removeClass(\'selected\');\n                $(this).addClass(\'selected\');\n                \n                // Animation\n                $(this).css(\'transform\', \'scale(0.9)\');\n                setTimeout(() => {\n                    $(this).css(\'transform\', \'scale(1)\');\n                }, 200);\n            });\n            \n            // Gestion de la quantité\n            $(\'.modal-quantity-btn.plus\').on(\'click\', function() {\n                const input = $(\'#modal-quantity\');\n                let value = parseInt(input.val());\n                if (value < 10) {\n                    input.val(value + 1);\n                    animateQuantityChange(input);\n                }\n            });\n            \n            $(\'.modal-quantity-btn.minus\').on(\'click\', function() {\n                const input = $(\'#modal-quantity\');\n                let value = parseInt(input.val());\n                if (value > 1) {\n                    input.val(value - 1);\n                    animateQuantityChange(input);\n                }\n            });\n            \n            // Gestion du bouton wishlist\n            $(\'#modal-wishlist\').on(\'click\', function() {\n                $(this).toggleClass(\'active\');\n                const icon = $(this).find(\'i\');\n                \n                if ($(this).hasClass(\'active\')) {\n                    icon.removeClass(\'far fa-heart\').addClass(\'fas fa-heart\');\n                    \n                    // Animation\n                    $(this).css(\'transform\', \'scale(1.3)\');\n                    setTimeout(() => {\n                        $(this).css(\'transform\', \'scale(1.1)\');\n                    }, 300);\n                    \n                    showNotification(\'Produit ajouté à votre wishlist!\');\n                } else {\n                    icon.removeClass(\'fas fa-heart\').addClass(\'far fa-heart\');\n                    \n                    // Animation\n                    $(this).css(\'transform\', \'scale(0.9)\');\n                    setTimeout(() => {\n                        $(this).css(\'transform\', \'scale(1)\');\n                    }, 300);\n                }\n            });\n            \n            // Gestion du bouton \"Ajouter au panier\"\n            $(\'#modal-add-to-cart\').on(\'click\', function() {\n                const size = $(\'#modal-size-options .selected\').data(\'value\');\n                const color = $(\'#modal-color-options .selected\').data(\'color\');\n                const quantity = $(\'#modal-quantity\').val();\n                \n                // Animation du bouton\n                $(this).css(\'transform\', \'scale(0.95)\');\n                setTimeout(() => {\n                    $(this).css(\'transform\', \'scale(1)\');\n                }, 200);\n                \n                // Afficher le récapitulatif\n                showCartSummary(product, size, color, quantity);\n            });\n        }\n\n        // Fonction pour animer le changement de quantité\n        function animateQuantityChange(input) {\n            input.css(\'transform\', \'scale(1.1)\');\n            setTimeout(() => {\n                input.css(\'transform\', \'scale(1)\');\n            }, 200);\n        }\n\n        // Fonction pour fermer la modal\n        function closeModal() {\n            $(\'#product-modal\').removeClass(\'active\');\n            setTimeout(() => {\n                $(\'#product-modal-overlay\').removeClass(\'active\');\n                $(\'body\').css(\'overflow\', \'auto\');\n            }, 300);\n        }\n\n        // Fonction pour afficher un récapitulatif d\'ajout au panier\n        function showCartSummary(product, size, color, quantity) {\n            const summary = `\n                <div class=\"cart-summary-overlay\">\n                    <div class=\"cart-summary-modal\">\n                        <div class=\"modal-header\">\n                            <h3>Produit ajouté au panier</h3>\n                            <button class=\"close-summary\"><i class=\"fas fa-times\"></i></button>\n                        </div>\n                        <div class=\"modal-content\">\n                            <div class=\"summary-item\">\n                                <img src=\"${product.images[0]}\" alt=\"${product.name}\" class=\"summary-image\">\n                                <div class=\"summary-details\">\n                                    <h4>${product.name}</h4>\n                                    <p>Taille: ${size}</p>\n                                    <p>Couleur: ${color}</p>\n                                    <p>Quantité: ${quantity}</p>\n                                    <p class=\"summary-price\">Total: ${calculateTotal(product.price, quantity)} €</p>\n                                </div>\n                            </div>\n                            <div class=\"summary-actions\">\n                                <button class=\"summary-btn continue\">Continuer mes achats</button>\n                                <button class=\"summary-btn checkout\">Voir le panier</button>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            `;\n            \n            // Styles pour le récapitulatif\n            const summaryStyles = `\n                <style>\n                    .cart-summary-overlay {\n                        position: fixed;\n                        top: 0;\n                        left: 0;\n                        width: 100%;\n                        height: 100%;\n                        background: rgba(44, 62, 80, 0.9);\n                        display: flex;\n                        align-items: center;\n                        justify-content: center;\n                        z-index: 2000;\n                        animation: fade-in 0.4s;\n                    }\n                    \n                    @keyframes fade-in {\n                        from { opacity: 0; }\n                        to { opacity: 1; }\n                    }\n                    \n                    .cart-summary-modal {\n                        background: white;\n                        border-radius: 20px;\n                        width: 90%;\n                        max-width: 500px;\n                        overflow: hidden;\n                        animation: slide-up 0.5s;\n                        box-shadow: 0 25px 50px rgba(0,0,0,0.3);\n                    }\n                    \n                    @keyframes slide-up {\n                        from { transform: translateY(50px); opacity: 0; }\n                        to { transform: translateY(0); opacity: 1; }\n                    }\n                    \n                    .modal-header {\n                        display: flex;\n                        justify-content: space-between;\n                        align-items: center;\n                        padding: 25px;\n                        background: linear-gradient(135deg, #2C3E50, #4A6572);\n                        color: white;\n                    }\n                    \n                    .modal-header h3 {\n                        margin: 0;\n                        font-family: \'Montserrat\', sans-serif;\n                    }\n                    \n                    .close-summary {\n                        background: none;\n                        border: none;\n                        color: white;\n                        font-size: 1.5rem;\n                        cursor: pointer;\n                    }\n                    \n                    .modal-content {\n                        padding: 30px;\n                    }\n                    \n                    .summary-item {\n                        display: flex;\n                        gap: 20px;\n                        margin-bottom: 30px;\n                    }\n                    \n                    .summary-image {\n                        width: 120px;\n                        height: 120px;\n                        object-fit: cover;\n                        border-radius: 12px;\n                    }\n                    \n                    .summary-details h4 {\n                        margin: 0 0 10px 0;\n                        font-family: \'Montserrat\', sans-serif;\n                        color: #2C3E50;\n                    }\n                    \n                    .summary-details p {\n                        margin: 5px 0;\n                        color: #7F8C8D;\n                    }\n                    \n                    .summary-price {\n                        font-weight: 700;\n                        color: #1ABC9C !important;\n                        font-size: 1.2rem;\n                        margin-top: 10px !important;\n                    }\n                    \n                    .summary-actions {\n                        display: flex;\n                        gap: 15px;\n                    }\n                    \n                    .summary-btn {\n                        flex: 1;\n                        padding: 15px;\n                        border: none;\n                        border-radius: 12px;\n                        font-family: \'Montserrat\', sans-serif;\n                        font-weight: 600;\n                        cursor: pointer;\n                        transition: all 0.3s;\n                    }\n                    \n                    .summary-btn.continue {\n                        background: #ECF0F1;\n                        color: #2C3E50;\n                    }\n                    \n                    .summary-btn.checkout {\n                        background: linear-gradient(135deg, #1ABC9C, #16A085);\n                        color: white;\n                    }\n                    \n                    .summary-btn:hover {\n                        transform: translateY(-3px);\n                        box-shadow: 0 10px 20px rgba(0,0,0,0.1);\n                    }\n                </style>\n            `;\n            \n            // Ajouter au DOM\n            $(\'head\').append(summaryStyles);\n            $(\'body\').append(summary);\n            \n            // Gestion de la fermeture\n            $(\'.close-summary, .summary-btn.continue\').on(\'click\', function() {\n                $(\'.cart-summary-overlay\').fadeOut(300, function() {\n                    $(this).remove();\n                    $(summaryStyles).remove();\n                });\n            });\n            \n            $(\'.summary-btn.checkout\').on(\'click\', function() {\n                alert(\'Redirection vers le panier...\');\n                $(\'.cart-summary-overlay\').remove();\n                $(summaryStyles).remove();\n                closeModal();\n            });\n        }\n\n        // Fonction pour calculer le total\n        function calculateTotal(priceStr, quantity) {\n            const price = parseFloat(priceStr.replace(\' €\', \'\').replace(\',\', \'.\'));\n            return (price * parseInt(quantity)).toFixed(2);\n        }\n\n        // Fonction pour afficher une notification\n        function showNotification(message) {\n            const notification = $(`\n                <div class=\"notification\">\n                    <i class=\"fas fa-check-circle\"></i>\n                    <span>${message}</span>\n                </div>\n            `);\n            \n            // Styles pour la notification\n            const notificationStyles = `\n                <style>\n                    .notification {\n                        position: fixed;\n                        bottom: 30px;\n                        right: 30px;\n                        background: white;\n                        padding: 20px 25px;\n                        border-radius: 12px;\n                        box-shadow: 0 15px 35px rgba(0,0,0,0.15);\n                        display: flex;\n                        align-items: center;\n                        gap: 15px;\n                        z-index: 1000;\n                        transform: translateX(100%);\n                        opacity: 0;\n                        animation: slide-in-notification 0.5s forwards, slide-out-notification 0.5s 2.5s forwards;\n                    }\n                    \n                    @keyframes slide-in-notification {\n                        to { transform: translateX(0); opacity: 1; }\n                    }\n                    \n                    @keyframes slide-out-notification {\n                        to { transform: translateX(100%); opacity: 0; }\n                    }\n                    \n                    .notification i {\n                        color: #1ABC9C;\n                        font-size: 1.5rem;\n                    }\n                    \n                    .notification span {\n                        font-weight: 600;\n                        color: #2C3E50;\n                    }\n                </style>\n            `;\n            \n            $(\'head\').append(notificationStyles);\n            $(\'body\').append(notification);\n            \n            // Supprimer après l\'animation\n            setTimeout(() => {\n                notification.remove();\n                $(notificationStyles).remove();\n            }, 3000);\n        }\n    </script>\n</body>', ' /* Variables CSS - Thème Mode Hiver */\n        :root {\n            --winter-blue: #2C3E50;\n            --ice-blue: #ECF0F1;\n            --frost-white: #F8F9FA;\n            --silver: #BDC3C7;\n            --icy-teal: #1ABC9C;\n            --cold-purple: #9B59B6;\n            --warm-gray: #7F8C8D;\n            --burgundy: #8B0000;\n            --navy: #000080;\n            --snow-shadow: 0 15px 35px rgba(44, 62, 80, 0.1);\n            --frost-shadow: 0 8px 25px rgba(189, 195, 199, 0.2);\n            --glow-shadow: 0 0 20px rgba(26, 188, 156, 0.15);\n            --radius-lg: 20px;\n            --radius-md: 12px;\n            --radius-sm: 8px;\n            --transition-smooth: 0.5s cubic-bezier(0.23, 1, 0.32, 1);\n            --transition-bounce: 0.6s cubic-bezier(0.68, -0.55, 0.265, 1.55);\n        }\n\n        /* Reset et styles globaux */\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-family: \'Raleway\', sans-serif;\n            background: linear-gradient(135deg, var(--frost-white) 0%, #E8F4F8 100%);\n            color: var(--winter-blue);\n            line-height: 1.6;\n            min-height: 100vh;\n            padding: 20px;\n            overflow-x: hidden;\n        }\n\n        .container {\n            max-width: 1400px;\n            margin: 0 auto;\n            padding: 0 20px;\n        }\n\n        /* En-tête avec effet de neige */\n        .fashion-header {\n            text-align: center;\n            padding: 80px 0 60px;\n            position: relative;\n            overflow: hidden;\n        }\n\n        .snow-effect {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            pointer-events: none;\n            z-index: -1;\n        }\n\n        .snowflake {\n            position: absolute;\n            background: white;\n            border-radius: 50%;\n            opacity: 0.8;\n            animation: snowfall linear infinite;\n        }\n\n        @keyframes snowfall {\n            0% { transform: translateY(-10px) rotate(0deg); }\n            100% { transform: translateY(100vh) rotate(360deg); }\n        }\n\n        .header-content {\n            position: relative;\n            z-index: 2;\n        }\n\n        .season-badge {\n            display: inline-block;\n            background: linear-gradient(135deg, var(--icy-teal), var(--cold-purple));\n            color: white;\n            padding: 12px 28px;\n            border-radius: 50px;\n            font-weight: 600;\n            letter-spacing: 2px;\n            margin-bottom: 25px;\n            text-transform: uppercase;\n            font-size: 0.9rem;\n            box-shadow: var(--glow-shadow);\n            transform: translateY(-20px);\n            opacity: 0;\n            animation: badge-float 1s 0.3s forwards;\n        }\n\n        @keyframes badge-float {\n            to {\n                opacity: 1;\n                transform: translateY(0);\n            }\n        }\n\n        .main-title {\n            font-family: \'Montserrat\', sans-serif;\n            font-size: 3.8rem;\n            font-weight: 700;\n            background: linear-gradient(135deg, var(--winter-blue), #4A6572);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            margin-bottom: 20px;\n            opacity: 0;\n            transform: translateY(30px);\n            animation: title-appear 1s 0.5s forwards;\n        }\n\n        @keyframes title-appear {\n            to {\n                opacity: 1;\n                transform: translateY(0);\n            }\n        }\n\n        .header-subtitle {\n            font-size: 1.3rem;\n            color: var(--warm-gray);\n            max-width: 700px;\n            margin: 0 auto 40px;\n            opacity: 0;\n            animation: fade-up 1s 0.7s forwards;\n        }\n\n        @keyframes fade-up {\n            to {\n                opacity: 1;\n                transform: translateY(0);\n            }\n        }\n\n        /* Navigation des catégories */\n        .category-nav {\n            display: flex;\n            justify-content: center;\n            flex-wrap: wrap;\n            gap: 15px;\n            margin-bottom: 60px;\n            opacity: 0;\n            animation: fade-up 1s 0.9s forwards;\n        }\n\n        .category-btn {\n            padding: 16px 32px;\n            background: white;\n            border: 2px solid transparent;\n            border-radius: var(--radius-md);\n            font-family: \'Montserrat\', sans-serif;\n            font-weight: 600;\n            color: var(--winter-blue);\n            cursor: pointer;\n            transition: var(--transition-bounce);\n            position: relative;\n            overflow: hidden;\n            box-shadow: var(--frost-shadow);\n        }\n\n        .category-btn::before {\n            content: \'\';\n            position: absolute;\n            top: 50%;\n            left: 50%;\n            width: 0;\n            height: 0;\n            background: rgba(26, 188, 156, 0.1);\n            border-radius: 50%;\n            transform: translate(-50%, -50%);\n            transition: width 0.6s, height 0.6s;\n        }\n\n        .category-btn:hover::before {\n            width: 300px;\n            height: 300px;\n        }\n\n        .category-btn:hover {\n            transform: translateY(-8px);\n            border-color: var(--icy-teal);\n            box-shadow: var(--snow-shadow);\n        }\n\n        .category-btn.active {\n            background: var(--winter-blue);\n            color: white;\n            border-color: var(--winter-blue);\n        }\n\n        .category-btn i {\n            margin-right: 10px;\n            font-size: 1.1rem;\n        }\n\n        /* Grille de produits */\n        .products-section {\n            margin-bottom: 80px;\n            opacity: 0;\n            animation: fade-up 1s 1.1s forwards;\n        }\n\n        .section-title {\n            font-family: \'Montserrat\', sans-serif;\n            font-size: 2.2rem;\n            font-weight: 700;\n            color: var(--winter-blue);\n            margin-bottom: 40px;\n            text-align: center;\n            position: relative;\n        }\n\n        .section-title::after {\n            content: \'\';\n            position: absolute;\n            bottom: -15px;\n            left: 50%;\n            transform: translateX(-50%);\n            width: 100px;\n            height: 4px;\n            background: linear-gradient(90deg, var(--icy-teal), var(--cold-purple));\n            border-radius: 2px;\n        }\n\n        .products-grid {\n            display: grid;\n            grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));\n            gap: 30px;\n        }\n\n        .product-card {\n            background: white;\n            border-radius: var(--radius-lg);\n            overflow: hidden;\n            box-shadow: var(--frost-shadow);\n            transition: var(--transition-bounce);\n            position: relative;\n            cursor: pointer;\n        }\n\n        .product-card:hover {\n            transform: translateY(-15px);\n            box-shadow: var(--snow-shadow);\n        }\n\n        .product-card-badge {\n            position: absolute;\n            top: 15px;\n            left: 15px;\n            padding: 6px 14px;\n            border-radius: 50px;\n            font-size: 0.8rem;\n            font-weight: 600;\n            z-index: 2;\n            color: white;\n        }\n\n        .product-card-badge.new {\n            background: var(--icy-teal);\n        }\n\n        .product-card-badge.sale {\n            background: var(--burgundy);\n        }\n\n        .product-card-badge.limited {\n            background: var(--cold-purple);\n        }\n\n        .product-card-image {\n            height: 250px;\n            overflow: hidden;\n            position: relative;\n        }\n\n        .product-card-image img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n            transition: transform 6s ease;\n        }\n\n        .product-card:hover .product-card-image img {\n            transform: scale(1.1);\n        }\n\n        .quick-view-btn {\n            position: absolute;\n            bottom: -50px;\n            left: 50%;\n            transform: translateX(-50%);\n            background: white;\n            border: none;\n            padding: 12px 24px;\n            border-radius: 50px;\n            font-weight: 600;\n            color: var(--winter-blue);\n            cursor: pointer;\n            transition: var(--transition-smooth);\n            box-shadow: var(--frost-shadow);\n            z-index: 2;\n            opacity: 0;\n        }\n\n        .product-card:hover .quick-view-btn {\n            bottom: 20px;\n            opacity: 1;\n        }\n\n        .quick-view-btn:hover {\n            background: var(--winter-blue);\n            color: white;\n            transform: translateX(-50%) scale(1.05);\n        }\n\n        .product-card-content {\n            padding: 25px;\n        }\n\n        .product-card-title {\n            font-family: \'Montserrat\', sans-serif;\n            font-weight: 600;\n            font-size: 1.2rem;\n            margin-bottom: 10px;\n            color: var(--winter-blue);\n        }\n\n        .product-card-price {\n            display: flex;\n            align-items: center;\n            gap: 10px;\n            margin-bottom: 15px;\n        }\n\n        .current-price {\n            font-weight: 700;\n            font-size: 1.5rem;\n            color: var(--icy-teal);\n        }\n\n        .original-price {\n            font-size: 1.1rem;\n            color: var(--silver);\n            text-decoration: line-through;\n        }\n\n        .product-card-colors {\n            display: flex;\n            gap: 8px;\n            margin-bottom: 15px;\n        }\n\n        .color-dot {\n            width: 20px;\n            height: 20px;\n            border-radius: 50%;\n            border: 2px solid white;\n            box-shadow: 0 2px 5px rgba(0,0,0,0.1);\n            cursor: pointer;\n            transition: transform 0.3s;\n        }\n\n        .color-dot:hover {\n            transform: scale(1.2);\n        }\n\n        .product-card-sizes {\n            display: flex;\n            gap: 5px;\n            flex-wrap: wrap;\n        }\n\n        .size-chip {\n            padding: 5px 10px;\n            background: var(--ice-blue);\n            border-radius: 4px;\n            font-size: 0.8rem;\n            color: var(--winter-blue);\n        }\n\n        /* Footer */\n        .fashion-footer {\n            text-align: center;\n            padding: 40px 0;\n            color: var(--warm-gray);\n            border-top: 1px solid var(--ice-blue);\n            opacity: 0;\n            animation: fade-up 1s 1.5s forwards;\n        }\n\n        .footer-links {\n            display: flex;\n            justify-content: center;\n            gap: 30px;\n            margin-bottom: 20px;\n            flex-wrap: wrap;\n        }\n\n        .footer-link {\n            color: var(--winter-blue);\n            text-decoration: none;\n            font-weight: 500;\n            transition: var(--transition-smooth);\n            position: relative;\n        }\n\n        .footer-link::after {\n            content: \'\';\n            position: absolute;\n            bottom: -5px;\n            left: 0;\n            width: 0;\n            height: 2px;\n            background: var(--icy-teal);\n            transition: width 0.3s;\n        }\n\n        .footer-link:hover::after {\n            width: 100%;\n        }\n\n        /* Modal de produit */\n        .product-modal-overlay {\n            position: fixed;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background: rgba(44, 62, 80, 0.95);\n            display: none;\n            justify-content: center;\n            align-items: center;\n            z-index: 1000;\n            padding: 20px;\n            opacity: 0;\n            transition: opacity 0.4s;\n        }\n\n        .product-modal-overlay.active {\n            display: flex;\n            opacity: 1;\n        }\n\n        .product-modal {\n            background: white;\n            border-radius: var(--radius-lg);\n            width: 100%;\n            max-width: 1100px;\n            max-height: 90vh;\n            overflow-y: auto;\n            display: none;\n            transform: translateY(50px);\n            opacity: 0;\n            transition: transform 0.5s, opacity 0.5s;\n            box-shadow: 0 30px 80px rgba(0, 0, 0, 0.4);\n        }\n\n        .product-modal.active {\n            display: block;\n            transform: translateY(0);\n            opacity: 1;\n        }\n\n        .modal-close {\n            position: absolute;\n            top: 25px;\n            right: 25px;\n            background: white;\n            border: none;\n            width: 40px;\n            height: 40px;\n            border-radius: 50%;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-size: 1.3rem;\n            color: var(--winter-blue);\n            cursor: pointer;\n            z-index: 10;\n            transition: var(--transition-smooth);\n            box-shadow: var(--frost-shadow);\n        }\n\n        .modal-close:hover {\n            background: var(--winter-blue);\n            color: white;\n            transform: rotate(90deg);\n        }\n\n        .modal-content {\n            display: grid;\n            grid-template-columns: 1fr 1fr;\n            gap: 50px;\n            padding: 40px;\n        }\n\n        @media (max-width: 992px) {\n            .modal-content {\n                grid-template-columns: 1fr;\n                gap: 30px;\n            }\n        }\n\n        /* Galerie dans la modal */\n        .modal-gallery {\n            position: relative;\n        }\n\n        .modal-main-image {\n            height: 450px;\n            border-radius: var(--radius-md);\n            overflow: hidden;\n            margin-bottom: 20px;\n        }\n\n        .modal-main-image img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n            transition: transform 8s ease;\n        }\n\n        .modal-main-image:hover img {\n            transform: scale(1.05);\n        }\n\n        .modal-thumbnails {\n            display: flex;\n            gap: 12px;\n            flex-wrap: wrap;\n        }\n\n        .modal-thumbnail {\n            width: 70px;\n            height: 70px;\n            border-radius: var(--radius-sm);\n            overflow: hidden;\n            cursor: pointer;\n            border: 3px solid transparent;\n            transition: var(--transition-smooth);\n            opacity: 0.7;\n        }\n\n        .modal-thumbnail:hover {\n            opacity: 1;\n            transform: translateY(-3px);\n        }\n\n        .modal-thumbnail.active {\n            border-color: var(--icy-teal);\n            opacity: 1;\n        }\n\n        .modal-thumbnail img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n        }\n\n        /* Détails dans la modal */\n        .modal-details {\n            padding: 20px 0;\n        }\n\n        .modal-title {\n            font-family: \'Montserrat\', sans-serif;\n            font-size: 2.2rem;\n            font-weight: 700;\n            color: var(--winter-blue);\n            margin-bottom: 15px;\n        }\n\n        .modal-category {\n            display: inline-block;\n            background: var(--ice-blue);\n            color: var(--winter-blue);\n            padding: 6px 15px;\n            border-radius: 50px;\n            font-size: 0.9rem;\n            margin-bottom: 20px;\n            font-weight: 600;\n        }\n\n        .modal-price {\n            display: flex;\n            align-items: center;\n            gap: 20px;\n            margin-bottom: 25px;\n        }\n\n        .modal-current-price {\n            font-size: 2.5rem;\n            font-weight: 700;\n            color: var(--icy-teal);\n        }\n\n        .modal-original-price {\n            font-size: 1.8rem;\n            color: var(--silver);\n            text-decoration: line-through;\n        }\n\n        .modal-description {\n            color: var(--warm-gray);\n            margin-bottom: 30px;\n            line-height: 1.8;\n            font-size: 1.1rem;\n        }\n\n        /* Variantes dans la modal */\n        .modal-variant-section {\n            margin-bottom: 25px;\n        }\n\n        .modal-variant-title {\n            font-family: \'Montserrat\', sans-serif;\n            font-weight: 600;\n            margin-bottom: 15px;\n            color: var(--winter-blue);\n            font-size: 1.1rem;\n        }\n\n        .modal-variant-options {\n            display: flex;\n            flex-wrap: wrap;\n            gap: 10px;\n        }\n\n        .modal-variant-option {\n            padding: 12px 20px;\n            border: 2px solid var(--ice-blue);\n            border-radius: var(--radius-md);\n            background: white;\n            cursor: pointer;\n            transition: var(--transition-smooth);\n            font-weight: 500;\n        }\n\n        .modal-variant-option:hover {\n            border-color: var(--icy-teal);\n            transform: translateY(-3px);\n        }\n\n        .modal-variant-option.selected {\n            background: var(--winter-blue);\n            color: white;\n            border-color: var(--winter-blue);\n        }\n\n        .modal-color-option {\n            width: 40px;\n            height: 40px;\n            border-radius: 50%;\n            border: 3px solid transparent;\n            cursor: pointer;\n            transition: var(--transition-smooth);\n        }\n\n        .modal-color-option:hover {\n            transform: scale(1.15);\n        }\n\n        .modal-color-option.selected {\n            border-color: var(--winter-blue);\n            transform: scale(1.15);\n            box-shadow: 0 5px 15px rgba(0,0,0,0.1);\n        }\n\n        /* Actions dans la modal */\n        .modal-actions {\n            display: flex;\n            gap: 15px;\n            margin-top: 40px;\n        }\n\n        .modal-quantity {\n            display: flex;\n            align-items: center;\n            border: 2px solid var(--ice-blue);\n            border-radius: var(--radius-md);\n            overflow: hidden;\n        }\n\n        .modal-quantity-btn {\n            width: 50px;\n            height: 50px;\n            background: white;\n            border: none;\n            font-size: 1.3rem;\n            color: var(--winter-blue);\n            cursor: pointer;\n            transition: var(--transition-smooth);\n        }\n\n        .modal-quantity-btn:hover {\n            background: var(--ice-blue);\n        }\n\n        .modal-quantity-input {\n            width: 60px;\n            height: 50px;\n            border: none;\n            text-align: center;\n            font-size: 1.2rem;\n            font-weight: 600;\n            color: var(--winter-blue);\n        }\n\n        .modal-add-to-cart {\n            flex: 1;\n            padding: 0 30px;\n            background: linear-gradient(135deg, var(--icy-teal), #16A085);\n            color: white;\n            border: none;\n            border-radius: var(--radius-md);\n            font-family: \'Montserrat\', sans-serif;\n            font-weight: 600;\n            font-size: 1rem;\n            cursor: pointer;\n            transition: var(--transition-bounce);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            gap: 12px;\n        }\n\n        .modal-add-to-cart:hover {\n            transform: translateY(-5px);\n            box-shadow: 0 15px 30px rgba(26, 188, 156, 0.3);\n        }\n\n        .modal-wishlist-btn {\n            width: 50px;\n            height: 50px;\n            background: white;\n            border: 2px solid var(--ice-blue);\n            border-radius: var(--radius-md);\n            color: var(--winter-blue);\n            cursor: pointer;\n            transition: var(--transition-bounce);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-size: 1.3rem;\n        }\n\n        .modal-wishlist-btn:hover {\n            background: #FF6B6B;\n            border-color: #FF6B6B;\n            color: white;\n            transform: scale(1.1);\n        }\n\n        .modal-wishlist-btn.active {\n            background: #FF6B6B;\n            border-color: #FF6B6B;\n            color: white;\n        }\n\n        /* Responsive */\n        @media (max-width: 768px) {\n            .main-title {\n                font-size: 2.8rem;\n            }\n            \n            .products-grid {\n                grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));\n            }\n            \n            .modal-content {\n                padding: 25px;\n            }\n            \n            .modal-main-image {\n                height: 350px;\n            }\n            \n            .modal-title {\n                font-size: 1.8rem;\n            }\n            \n            .modal-current-price {\n                font-size: 2rem;\n            }\n            \n            .category-nav {\n                gap: 10px;\n            }\n            \n            .category-btn {\n                padding: 12px 20px;\n                font-size: 0.9rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .main-title {\n                font-size: 2.2rem;\n            }\n            \n            .header-subtitle {\n                font-size: 1.1rem;\n            }\n            \n            .products-grid {\n                grid-template-columns: 1fr;\n            }\n            \n            .modal-actions {\n                flex-direction: column;\n            }\n            \n            .modal-add-to-cart {\n                padding: 15px;\n            }\n            \n            .fashion-header {\n                padding: 60px 0 40px;\n            }\n        }', NULL, 'draft', NULL, '2026-02-06 17:51:56', '2026-02-07 15:49:26');
