INSERT INTO `mode_emploi_guides` (`id`, `module_id`, `section`, `title`, `excerpt`, `content`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 3, 'dashboard', '1 · Tableau de bord (vue d\'ensemble)', 'Comprendre la page d\'accueil de votre espace et la navigation par onglets.', '<h2>1 · Tableau de bord</h2><p>Le tableau de bord est la page d\'accueil de votre espace entreprise. Il donne une vue d\'ensemble de votre site et permet de naviguer vers toutes les fonctionnalités.</p><figure class=\"image\"><img src=\"/storage/mode-emploi-guides/qxNufdOm6Im9QfJ9GO21X5xwbN7c2OmoB8CxGpsS.png\" alt=\"Vue générale du tableau de bord de l&#039;espace entreprise\"><figcaption>Vue générale du tableau de bord de l&#039;espace entreprise</figcaption></figure><h3>Étapes</h3><ol><li>Ouvrez votre espace depuis <a href=\"/admin/cms/9659/atelier-ar-tremblay/dashboard?section=dashboard\" target=\"_blank\" rel=\"noopener\">le Tableau de bord</a>.</li><li>À gauche, le <strong>menu vertical</strong> liste toutes les sections (Configuration, Horaire de travail, Médiathèque, Templates, etc.).</li><li>Utilisez le champ <strong>« Rechercher un menu… »</strong> en haut du menu pour filtrer rapidement une section.</li><li>Le bouton <strong>globe</strong> (en haut du profil) ouvre votre site public dans un nouvel onglet.</li><li>Cliquez sur une section pour afficher son contenu à droite.</li></ol>', 'fas fa-chart-line', 1, 1, '2026-07-15 13:22:47', '2026-07-16 08:42:19'),
(2, 3, 'config', '2 · Configuration générale', 'Logo, favicon, localisation (pays/province/région/ville), position sur la carte et téléphone.', '<h2>2 · Configuration générale</h2><p>La section <a href=\"/admin/cms/9659/atelier-ar-tremblay/dashboard?section=config\" target=\"_blank\" rel=\"noopener\">Configuration</a> regroupe les paramètres généraux de votre établissement.</p><figure class=\"image\"><img src=\"/storage/mode-emploi-guides/oSnxRpNrcaXAjZVkjIl6mgE6NuaDPvUyFQyDRETX.png\" alt=\"Section Configuration : informations, identité visuelle, localisation\"><figcaption>Section Configuration : informations, identité visuelle, localisation</figcaption></figure><h3>Étapes</h3><ol><li><strong>Logo &amp; Favicon</strong> : glissez-déposez ou cliquez sur les zones d\'upload pour importer votre logo (PNG/JPG/SVG, max 2 Mo) et votre favicon (ICO/PNG/SVG, max 1 Mo).</li><li><strong>Localisation</strong> : sélectionnez dans l\'ordre le <em>Pays</em>, la <em>Province</em>, la <em>Région</em> puis la <em>Ville</em>. Chaque liste se remplit en fonction du choix précédent.</li><li><strong>Position sur la carte</strong> : cliquez sur « Rechercher » pour géolocaliser l\'adresse, ou déplacez directement le marqueur sur la carte.</li><li><strong>Téléphone</strong> : renseignez le numéro affiché sur votre site.</li><li>Cliquez sur <strong>« Sauvegarder la configuration »</strong> en bas pour enregistrer.</li></ol><blockquote>La section « Jours fériés et fêtes » se trouve aussi ici : ajoutez-y vos fermetures exceptionnelles.</blockquote>', 'fas fa-sliders-h', 2, 1, '2026-07-15 13:22:47', '2026-07-16 08:42:19'),
(3, 3, 'work-hours', '3 · Horaire de travail', 'Définir les horaires d\'ouverture jour par jour et marquer les jours fermés.', '<h2>3 · Horaire de travail</h2><p>La section <a href=\"/admin/cms/9659/atelier-ar-tremblay/dashboard?section=work-hours\" target=\"_blank\" rel=\"noopener\">Horaire de travail</a> permet de définir les horaires d\'ouverture affichés sur votre site.</p><figure class=\"image\"><img src=\"/storage/mode-emploi-guides/qCcUqUaO9PtAHurkmTUAe5FsIMtsp9Vol9mHuooZ.png\" alt=\"Section Horaire de travail : horaires par jour et jours fermés\"><figcaption>Section Horaire de travail : horaires par jour et jours fermés</figcaption></figure><h3>Étapes</h3><ol><li>Pour chaque jour de la semaine, définissez l\'heure d\'<strong>Ouverture</strong> et de <strong>Fermeture</strong>.</li><li>Cochez <strong>« Fermé »</strong> pour un jour non travaillé : les champs horaires sont alors désactivés.</li><li>Cliquez sur <strong>« Sauvegarder les horaires »</strong> pour enregistrer.</li></ol>', 'fas fa-clock', 3, 1, '2026-07-15 13:22:47', '2026-07-16 08:42:19'),
(4, 3, 'media', '4 · Médiathèque (images & fichiers)', 'Importer, organiser et réutiliser vos images et fichiers.', '<h2>4 · Médiathèque</h2><p>La <a href=\"/admin/cms/9659/atelier-ar-tremblay/dashboard?section=media\" target=\"_blank\" rel=\"noopener\">Médiathèque</a> centralise toutes les images et fichiers réutilisables sur votre site.</p><figure class=\"image\"><img src=\"/storage/mode-emploi-guides/bm0IO5Bkp4bW7HOUEadFmMTbRms1wmFTBvdHbTLz.png\" alt=\"Médiathèque : grille des images et fichiers importés\"><figcaption>Médiathèque : grille des images et fichiers importés</figcaption></figure><h3>Étapes</h3><ol><li>Cliquez sur <strong>« Importer »</strong> (ou glissez-déposez) pour ajouter une ou plusieurs images.</li><li>Cliquez sur un média pour voir ses détails et copier son URL.</li><li>Réutilisez ensuite ces médias dans l\'éditeur de templates, les sliders, etc.</li></ol>', 'fas fa-images', 4, 1, '2026-07-15 13:22:47', '2026-07-16 08:42:19'),
(5, 3, 'themes', '5 · Templates & Éditeur de contenu', 'Modifier une image, une vidéo, un texte, un bouton ou un lien dans l\'éditeur.', '<h2>5 · Templates &amp; Éditeur de contenu</h2><p>Depuis la section <a href=\"/admin/cms/9659/atelier-ar-tremblay/dashboard?section=themes\" target=\"_blank\" rel=\"noopener\">Templates</a>, ouvrez un template pour l\'éditer. L\'éditeur permet de modifier chaque élément de la page.</p><figure class=\"image\"><img src=\"/storage/mode-emploi-guides/qLRDyPIipE44h1gYgufForygU7kRfL2PIcahpdlf.png\" alt=\"Section Templates : accès aux templates et à l&#039;éditeur de contenu\"><figcaption>Section Templates : accès aux templates et à l&#039;éditeur de contenu</figcaption></figure><h3>Modifier un <u>texte</u></h3><ol><li>Double-cliquez sur le texte à modifier.</li><li>Saisissez le nouveau contenu ; utilisez la barre d\'outils pour le gras, la couleur, la taille.</li><li>Cliquez en dehors pour valider.</li></ol><h3>Changer une <u>image</u></h3><ol><li>Cliquez sur l\'image, puis sur l\'icône de remplacement.</li><li>Choisissez une image depuis la Médiathèque ou importez-en une nouvelle.</li><li>Ajustez si besoin le texte alternatif (SEO/accessibilité).</li></ol><h3>Changer une <u>vidéo</u></h3><ol><li>Sélectionnez le bloc vidéo.</li><li>Collez l\'URL (YouTube) ou choisissez un fichier vidéo.</li><li>Validez pour mettre à jour l\'aperçu.</li></ol><h3>Modifier un <u>bouton</u> et son <u>lien</u></h3><ol><li>Cliquez sur le bouton pour le sélectionner.</li><li>Modifiez son <strong>libellé</strong> (texte affiché).</li><li>Dans les réglages du lien, renseignez l\'<strong>URL de destination</strong> et choisissez si le lien s\'ouvre dans un nouvel onglet.</li><li>Enregistrez le template pour publier les changements.</li></ol><blockquote>Pensez à <strong>enregistrer</strong> régulièrement pendant l\'édition pour ne rien perdre.</blockquote>', 'fas fa-palette', 5, 1, '2026-07-15 13:22:47', '2026-07-16 08:42:19'),
(6, 3, 'slider', '6 · Slider Vidéos', 'Gérer les slides vidéo affichés en page d\'accueil.', '<h2>6 · Slider Vidéos</h2><p>La section <a href=\"/admin/cms/9659/atelier-ar-tremblay/dashboard?section=slider\" target=\"_blank\" rel=\"noopener\">Slider Vidéos</a> gère les slides vidéo mis en avant sur votre site.</p><figure class=\"image\"><img src=\"/storage/mode-emploi-guides/uCehPKsiv7jwpV6tWYhW9gHeAv3QHRTBNeZVtwVT.png\" alt=\"Section Slider Vidéos : gestion des slides\"><figcaption>Section Slider Vidéos : gestion des slides</figcaption></figure><h3>Étapes</h3><ol><li>Cliquez sur <strong>« Ajouter »</strong> pour créer un slide.</li><li>Renseignez le titre, la vidéo (URL ou fichier) et le texte d\'accroche.</li><li>Réordonnez les slides par glisser-déposer et enregistrez.</li></ol>', 'fas fa-film', 6, 1, '2026-07-15 13:22:47', '2026-07-16 08:42:19'),
(7, 3, 'map-videos', '7 · Vidéos maps', 'Ajouter des points vidéo géolocalisés sur la carte.', '<h2>7 · Vidéos maps</h2><p>La section <a href=\"/admin/cms/9659/atelier-ar-tremblay/dashboard?section=map-videos\" target=\"_blank\" rel=\"noopener\">Vidéos maps</a> permet d\'associer des vidéos à des points géolocalisés.</p><figure class=\"image\"><img src=\"/storage/mode-emploi-guides/ZefkYU3VhHdu33atDPmFoqdBm4H22KdO83ZejJMc.png\" alt=\"Section Vidéos maps : points vidéo géolocalisés\"><figcaption>Section Vidéos maps : points vidéo géolocalisés</figcaption></figure><h3>Étapes</h3><ol><li>Ajoutez un point sur la carte à l\'emplacement souhaité.</li><li>Associez-lui une vidéo et un titre.</li><li>Enregistrez : le point vidéo apparaît sur la carte publique.</li></ol>', 'fas fa-map-marked-alt', 7, 1, '2026-07-15 13:22:47', '2026-07-16 08:42:19'),
(8, 3, 'contact-messages', '8 · Messages de contact', 'Consulter et traiter les demandes envoyées par les visiteurs.', '<h2>8 · Messages de contact</h2><p>La section <a href=\"/admin/cms/9659/atelier-ar-tremblay/dashboard?section=contact-messages\" target=\"_blank\" rel=\"noopener\">Messages contact</a> rassemble les demandes reçues via le formulaire de contact.</p><figure class=\"image\"><img src=\"/storage/mode-emploi-guides/jWOU22V84vSWOxKwnlrpC3cvoyq9ilBgu8OUgKeM.png\" alt=\"Section Messages contact : boîte de réception des demandes\"><figcaption>Section Messages contact : boîte de réception des demandes</figcaption></figure><h3>Étapes</h3><ol><li>Cliquez sur un message pour lire son contenu complet.</li><li>Le compteur du menu indique le nombre de nouveaux messages.</li><li>Traitez, marquez comme lu ou supprimez selon vos besoins.</li></ol>', 'fas fa-inbox', 8, 1, '2026-07-15 13:22:47', '2026-07-16 08:42:19');
