INSERT INTO `pages` (`id`, `name`, `slug`, `html_content`, `css_content`, `is_active`, `pageable_id`, `pageable_type`, `created_at`, `updated_at`) VALUES
(2, 'Accueil', 'accueil', '<body><section class=\"gallery-section\"><div class=\"container\"><h2 class=\"gallery-title\">Our Creative Portfolio</h2><p class=\"gallery-subtitle\">Explore our collection of stunning visual work</p><div class=\"gallery-filters\"><button type=\"button\" data-filter=\"all\" class=\"gallery-filter active\">All</button><button type=\"button\" data-filter=\"nature\" class=\"gallery-filter\">Nature</button><button type=\"button\" data-filter=\"urban\" class=\"gallery-filter\">Urban</button><button type=\"button\" data-filter=\"portrait\" class=\"gallery-filter\">Portrait</button><button type=\"button\" data-filter=\"abstract\" class=\"gallery-filter\">Abstract</button></div><div class=\"masonry-gallery\"><div data-index=\"1\" class=\"gallery-item nature\"><img src=\"https://images.unsplash.com/photo-1501854140801-50d01698950b\" alt=\"Mountain Landscape\"/><div class=\"gallery-overlay\"><h4>Mountain Majesty</h4><p>Nature • Landscape</p></div></div><div data-index=\"2\" class=\"gallery-item urban portrait\"><img src=\"https://images.unsplash.com/photo-1544005313-94ddf0286df2\" alt=\"Urban Portrait\"/><div class=\"gallery-overlay\"><h4>City Stories</h4><p>Urban • Portrait</p></div></div><div data-index=\"3\" class=\"gallery-item abstract\"><img src=\"https://images.unsplash.com/photo-1543857778-c4a1a569e388\" alt=\"Abstract Art\"/><div class=\"gallery-overlay\"><h4>Color Symphony</h4><p>Abstract • Art</p></div></div><div data-index=\"4\" class=\"gallery-item nature\"><img src=\"https://images.unsplash.com/photo-1441974231531-c6227db76b6e\" alt=\"Forest Path\"/><div class=\"gallery-overlay\"><h4>Forest Path</h4><p>Nature • Adventure</p></div></div><div data-index=\"5\" class=\"gallery-item urban\"><img src=\"https://images.unsplash.com/photo-1477959858617-67f85cf4f1df\" alt=\"City Skyline\"/><div class=\"gallery-overlay\"><h4>Metropolis</h4><p>Urban • Architecture</p></div></div><div data-index=\"6\" class=\"gallery-item portrait\"><img src=\"https://images.unsplash.com/photo-1534528741775-53994a69daeb\" alt=\"Portrait\"/><div class=\"gallery-overlay\"><h4>Human Essence</h4><p>Portrait • Emotion</p></div></div></div></div><!-- Lightbox Modal --><div class=\"lightbox\"><div class=\"lightbox-content\"><button type=\"button\" class=\"lightbox-close\">×</button><button type=\"button\" class=\"lightbox-nav prev\">❮</button><button type=\"button\" class=\"lightbox-nav next\">❯</button><img src=\"data:image/svg+xml;base64,\" alt=\"\" class=\"lightbox-image\"/><div class=\"lightbox-caption\"><h3></h3><p></p></div></div></div></section></body>', '* { box-sizing: border-box; } body {margin: 0;}.gallery-section{padding-top:80px;padding-right:20px;padding-bottom:80px;padding-left:20px;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(15, 23, 42);color:white;}.container{max-width:1400px;margin-top:0px;margin-right:auto;margin-bottom:0px;margin-left:auto;}.gallery-title{font-size:3rem;text-align:center;margin-bottom:15px;background-image:linear-gradient(45deg, rgb(139, 92, 246), rgb(59, 130, 246));background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-color:initial;-webkit-text-fill-color:transparent;background-clip:text;}.gallery-subtitle{text-align:center;color:rgb(148, 163, 184);font-size:1.2rem;margin-bottom:50px;}.gallery-filters{display:flex;justify-content:center;row-gap:15px;column-gap:15px;margin-bottom:40px;flex-wrap:wrap;}.gallery-filter{padding-top:12px;padding-right:30px;padding-bottom:12px;padding-left:30px;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgba(255, 255, 255, 0.1);border-top-width:initial;border-right-width:initial;border-bottom-width:initial;border-left-width:initial;border-top-style:none;border-right-style:none;border-bottom-style:none;border-left-style:none;border-top-color:initial;border-right-color:initial;border-bottom-color:initial;border-left-color:initial;border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;color:rgb(203, 213, 225);border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-right-radius:25px;border-bottom-left-radius:25px;cursor:pointer;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:all;font-weight:500;backdrop-filter:blur(10px);}.gallery-filter:hover{background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgba(255, 255, 255, 0.2);transform:translateY(-2px);}.gallery-filter.active{background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(59, 130, 246);color:white;box-shadow:rgba(59, 130, 246, 0.4) 0px 5px 20px;}.masonry-gallery{column-width:300px;column-count:4;column-gap:20px;}.gallery-item{break-inside:avoid;margin-bottom:20px;position:relative;border-top-left-radius:15px;border-top-right-radius:15px;border-bottom-right-radius:15px;border-bottom-left-radius:15px;overflow-x:hidden;overflow-y:hidden;cursor:pointer;transition-behavior:normal, normal;transition-duration:0.3s, 0.3s;transition-timing-function:ease, ease;transition-delay:0s, 0s;transition-property:transform, box-shadow;}.gallery-item:hover{transform:translateY(-10px)