(89, 6, 'Agence Voyage · Forfaits & Réservations', NULL, NULL, '<body>\r\n  <!-- AGENCE DE VOYAGE - FORFAITS & RÉSERVATIONS -->\r\n  <section class=\"travel-agency-section\">\r\n\r\n    <!-- HEADER VOYAGE -->\r\n    <header class=\"ta-header\">\r\n      <div class=\"ta-logo\">\r\n        <span class=\"ta-logo-icon\">✈</span>\r\n        <span class=\"ta-logo-text\">Ailleurs<span>&Co</span></span>\r\n      </div>\r\n      <nav class=\"ta-nav\">\r\n        <a href=\"#\">Destinations</a>\r\n        <a href=\"#\">Forfaits</a>\r\n        <a href=\"#\">Circuits</a>\r\n        <a href=\"#\">Contact</a>\r\n      </nav>\r\n      <div class=\"ta-actions\">\r\n        <span class=\"ta-contact\">\r\n          <span>📞</span> 01 23 45 67 89\r\n        </span>\r\n      </div>\r\n    </header>\r\n\r\n    <!-- HERO AVEC MOTEUR DE RECHERCHE -->\r\n    <div class=\"ta-hero\">\r\n      <span class=\"ta-hero-bg-icon\">✈</span>\r\n      <div class=\"ta-hero-content\">\r\n        <span class=\"ta-hero-tag\">\r\n          <span>🌍</span> Voyagez mieux, dépensez moins\r\n        </span>\r\n        <h1 class=\"ta-hero-title\">\r\n          Des <span class=\"ta-hero-highlight\">voyages sur mesure</span><br>aux prix justes\r\n        </h1>\r\n        <p class=\"ta-hero-desc\">\r\n          Forfaits tout inclus, circuits authentiques et vols secs. \r\n          Réservez en confiance parmi 500+ destinations.\r\n        </p>\r\n        \r\n        <!-- MOTEUR DE RECHERCHE / RÉSERVATION RAPIDE -->\r\n        <div class=\"ta-search-box\">\r\n          <div class=\"ta-search-item\">\r\n            <span class=\"ta-search-icon\">📍</span>\r\n            <div class=\"ta-search-content\">\r\n              <span class=\"ta-search-label\">Destination</span>\r\n              <span class=\"ta-search-value\">Où allez-vous ?</span>\r\n            </div>\r\n          </div>\r\n          <div class=\"ta-search-item\">\r\n            <span class=\"ta-search-icon\">📅</span>\r\n            <div class=\"ta-search-content\">\r\n              <span class=\"ta-search-label\">Départ</span>\r\n              <span class=\"ta-search-value\">15 juin 2026</span>\r\n            </div>\r\n          </div>\r\n          <div class=\"ta-search-item\">\r\n            <span class=\"ta-search-icon\">👥</span>\r\n            <div class=\"ta-search-content\">\r\n              <span class=\"ta-search-label\">Voyageurs</span>\r\n              <span class=\"ta-search-value\">2 adultes</span>\r\n            </div>\r\n          </div>\r\n          <button class=\"ta-search-btn\">\r\n            <span>🔍</span> Rechercher\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- DESTINATIONS POPULAIRES -->\r\n    <div class=\"ta-destinations\">\r\n      <div class=\"section-header\">\r\n        <div>\r\n          <h2 class=\"section-title\">Destinations populaires</h2>\r\n          <p class=\"section-sub\">Les voyages les plus réservés du moment</p>\r\n        </div>\r\n        <span style=\"color: #3a8891; font-weight: 600; border-bottom: 2px solid #3a8891; padding-bottom: 4px;\">\r\n          Toutes nos destinations →\r\n        </span>\r\n      </div>\r\n\r\n      <div class=\"destinations-grid\">\r\n        <!-- Grèce -->\r\n        <div class=\"destination-card\">\r\n          <div class=\"destination-image\">\r\n            <span>🇬🇷</span>\r\n            <span class=\"destination-price-tag\">dès 599€</span>\r\n          </div>\r\n          <div class=\"destination-info\">\r\n            <h3 class=\"destination-name\">Santorin</h3>\r\n            <div class=\"destination-meta\">\r\n              <span class=\"destination-rating\">★ 4.8 (234 avis)</span>\r\n              <span class=\"destination-days\">📅 7 jours</span>\r\n            </div>\r\n            <div style=\"display: flex; gap: 8px; flex-wrap: wrap;\">\r\n              <span style=\"background: #ecf5f6; padding: 6px 16px; border-radius: 30px; font-size: 13px;\">Vol inclus</span>\r\n              <span style=\"background: #ecf5f6; padding: 6px 16px; border-radius: 30px; font-size: 13px;\">Demi-pension</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <!-- Islande -->\r\n        <div class=\"destination-card\">\r\n          <div class=\"destination-image\">\r\n            <span>🇮🇸</span>\r\n            <span class=\"destination-price-tag\">dès 899€</span>\r\n          </div>\r\n          <div class=\"destination-info\">\r\n            <h3 class=\"destination-name\">Reykjavik</h3>\r\n            <div class=\"destination-meta\">\r\n              <span class=\"destination-rating\">★ 4.9 (187 avis)</span>\r\n              <span class=\"destination-days\">📅 6 jours</span>\r\n            </div>\r\n            <div style=\"display: flex; gap: 8px;\">\r\n              <span style=\"background: #ecf5f6; padding: 6px 16px; border-radius: 30px; font-size: 13px;\">Aurores</span>\r\n              <span style=\"background: #ecf5f6; padding: 6px 16px; border-radius: 30px; font-size: 13px;\">Lagon Bleu</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <!-- Thaïlande -->\r\n        <div class=\"destination-card\">\r\n          <div class=\"destination-image\">\r\n            <span>🇹🇭</span>\r\n            <span class=\"destination-price-tag\">dès 1299€</span>\r\n          </div>\r\n          <div class=\"destination-info\">\r\n            <h3 class=\"destination-name\">Phuket</h3>\r\n            <div class=\"destination-meta\">\r\n              <span class=\"destination-rating\">★ 4.7 (312 avis)</span>\r\n              <span class=\"destination-days\">📅 10 jours</span>\r\n            </div>\r\n            <div style=\"display: flex; gap: 8px;\">\r\n              <span style=\"background: #ecf5f6; padding: 6px 16px; border-radius: 30px; font-size: 13px;\">Tout inclus</span>\r\n              <span style=\"background: #ecf5f6; padding: 6px 16px; border-radius: 30px; font-size: 13px;\">Plages</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <!-- Maroc -->\r\n        <div class=\"destination-card\">\r\n          <div class=\"destination-image\">\r\n            <span>🇲🇦</span>\r\n            <span class=\"destination-price-tag\">dès 449€</span>\r\n          </div>\r\n          <div class=\"destination-info\">\r\n            <h3 class=\"destination-name\">Marrakech</h3>\r\n            <div class=\"destination-meta\">\r\n              <span class=\"destination-rating\">★ 4.8 (156 avis)</span>\r\n              <span class=\"destination-days\">📅 5 jours</span>\r\n            </div>\r\n            <div style=\"display: flex; gap: 8px;\">\r\n              <span style=\"background: #ecf5f6; padding: 6px 16px; border-radius: 30px; font-size: 13px;\">Riad inclus</span>\r\n              <span style=\"background: #ecf5f6; padding: 6px 16px; border-radius: 30px; font-size: 13px;\">Dépaysement</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- FORFAITS VOYAGE (PACKAGES) -->\r\n    <div class=\"ta-packages\">\r\n      <div class=\"section-header\">\r\n        <div>\r\n          <h2 class=\"section-title\">Nos forfaits voyage</h2>\r\n          <p class=\"section-sub\">Tout inclus, sans mauvaise surprise</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"packages-grid\">\r\n        <!-- FORFAIT AVENTURE -->\r\n        <div class=\"package-card\">\r\n          <div class=\"package-emoji\">🏔️</div>\r\n          <h3 class=\"package-name\">Évasion nature</h3>\r\n          <p class=\"package-desc\">Randonnées, parcs nationaux, hébergements authentiques.</p>\r\n          <div class=\"package-features\">\r\n            <span class=\"package-feature\">✓ Vol A/R inclus</span>\r\n            <span class=\"package-feature\">✓ 7 nuits en hôtel 3*</span>\r\n            <span class=\"package-feature\">✓ 3 activités guidées</span>\r\n            <span class=\"package-feature\">✓ Petit-déjeuner inclus</span>\r\n          </div>\r\n          <div class=\"package-price\">799€ <small>/ personne</small></div>\r\n          <span class=\"package-btn\">Réserver</span>\r\n        </div>\r\n        <!-- FORFAIT DÉTENTE -->\r\n        <div class=\"package-card\">\r\n          <div class=\"package-emoji\">🏖️</div>\r\n          <h3 class=\"package-name\">Escapade balnéaire</h3>\r\n          <p class=\"package-desc\">Plages de rêve, farniente, spa et cocktails au bord de l\'eau.</p>\r\n          <div class=\"package-features\">\r\n            <span class=\"package-feature\">✓ Vol A/R</span>\r\n            <span class=\"package-feature\">✓ 9 nuits resort 4*</span>\r\n            <span class=\"package-feature\">✓ All inclusive</span>\r\n            <span class=\"package-feature\">✓ Transferts VIP</span>\r\n          </div>\r\n          <div class=\"package-price\">1299€ <small>/ personne</small></div>\r\n          <span class=\"package-btn\">Réserver</span>\r\n        </div>\r\n        <!-- FORFAIT CULTURE -->\r\n        <div class=\"package-card\">\r\n          <div class=\"package-emoji\">🏛️</div>\r\n          <h3 class=\"package-name\">Circuit culturel</h3>\r\n          <p class=\"package-desc\">Visites guidées, musées, patrimoine mondial et gastronomie.</p>\r\n          <div class=\"package-features\">\r\n            <span class=\"package-feature\">✓ Vol A/R</span>\r\n            <span class=\"package-feature\">✓ 12 nuits en hôtels</span>\r\n            <span class=\"package-feature\">✓ Guide francophone</span>\r\n            <span class=\"package-feature\">✓ 8 visites incluses</span>\r\n          </div>\r\n          <div class=\"package-price\">1690€ <small>/ personne</small></div>\r\n          <span class=\"package-btn outline\">Réserver</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- AVIS CLIENTS -->\r\n    <div class=\"ta-testimonials\">\r\n      <div class=\"section-header\">\r\n        <div>\r\n          <h2 class=\"section-title\">Ils nous ont fait confiance</h2>\r\n          <p class=\"section-sub\">+12 000 voyageurs satisfaits</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"testimonials-grid\">\r\n        <div class=\"testimonial-card\">\r\n          <div class=\"testimonial-header\">\r\n            <div class=\"testimonial-avatar\">👩</div>\r\n            <div class=\"testimonial-name\">\r\n              <h4>Claire M.</h4>\r\n              <span class=\"testimonial-location\">📍 Voyage à Santorin</span>\r\n            </div>\r\n          </div>\r\n          <p class=\"testimonial-text\">\r\n            \"Organisation parfaite, hôtel avec vue imprenable sur la caldera. Le forfait tout inclus valait vraiment le coup !\"\r\n          </p>\r\n          <div class=\"testimonial-rating\">★★★★★</div>\r\n        </div>\r\n        <div class=\"testimonial-card\">\r\n          <div class=\"testimonial-header\">\r\n            <div class=\"testimonial-avatar\">👨</div>\r\n            <div class=\"testimonial-name\">\r\n              <h4>Thomas R.</h4>\r\n              <span class=\"testimonial-location\">📍 Circuit Islande</span>\r\n            </div>\r\n          </div>\r\n          <p class=\"testimonial-text\">\r\n            \"Guide exceptionnel, logistique impeccable. Nous avons vu des aurores boréales, un rêve !\"\r\n          </p>\r\n          <div class=\"testimonial-rating\">★★★★★</div>\r\n        </div>\r\n        <div class=\"testimonial-card\">\r\n          <div class=\"testimonial-header\">\r\n            <div class=\"testimonial-avatar\">👩‍🦱</div>\r\n            <div class=\"testimonial-name\">\r\n              <h4>Sophie L.</h4>\r\n              <span class=\"testimonial-location\">📍 Phuket</span>\r\n            </div>\r\n          </div>\r\n          <p class=\"testimonial-text\">\r\n            \"Rapport qualité/prix incroyable. Le resort était magnifique et les excursions bien organisées.\"\r\n          </p>\r\n          <div class=\"testimonial-rating\">★★★★☆</div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- BANDEAU RÉSERVATION RAPIDE -->\r\n    <div class=\"ta-cta\">\r\n      <div class=\"cta-content\">\r\n        <h3>Prêt à partir ?</h3>\r\n        <p>Réservez votre voyage en quelques clics. Paiement sécurisé, confirmation instantanée.</p>\r\n      </div>\r\n      <span class=\"cta-btn\">Réserver maintenant →</span>\r\n    </div>\r\n\r\n    <!-- FOOTER AGENCE VOYAGE -->\r\n    <footer class=\"ta-footer\">\r\n      <div class=\"footer-main\">\r\n        <div class=\"footer-about\">\r\n          <div class=\"ta-logo\">\r\n            <span class=\"ta-logo-icon\">✈</span>\r\n            <span class=\"ta-logo-text\">Ailleurs<span>&Co</span></span>\r\n          </div>\r\n          <p>Voyagez sur mesure avec des experts. Plus de 15 ans d\'expertise et un réseau de partenaires locaux.</p>\r\n          <div style=\"display: flex; gap: 24px; font-size: 24px;\">\r\n            <span>📘</span>\r\n            <span>📷</span>\r\n            <span>🐦</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Destinations</span>\r\n          <a href=\"#\">Europe</a>\r\n          <a href=\"#\">Asie</a>\r\n          <a href=\"#\">Amériques</a>\r\n          <a href=\"#\">Afrique</a>\r\n          <a href=\"#\">Océanie</a>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Services</span>\r\n          <a href=\"#\">Forfaits tout inclus</a>\r\n          <a href=\"#\">Circuits accompagnés</a>\r\n          <a href=\"#\">Vols secs</a>\r\n          <a href=\"#\">Assurance voyage</a>\r\n          <a href=\"#\">Location voiture</a>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Contact</span>\r\n          <a href=\"#\">Service client</a>\r\n          <a href=\"#\">Devis personnalisé</a>\r\n          <a href=\"#\">FAQ</a>\r\n          <a href=\"#\">CGV</a>\r\n          <a href=\"#\">Mentions légales</a>\r\n        </div>\r\n      </div>\r\n      <div class=\"footer-bottom\">\r\n        <span>© 2026 Ailleurs & Co - Agence de voyage</span>\r\n        <span style=\"display: flex; gap: 28px;\">\r\n          <span>Confidentialité</span>\r\n          <span>Cookies</span>\r\n        </span>\r\n      </div>\r\n    </footer>\r\n  </section>\r\n</body>', '/* ===== STYLE AGENCE DE VOYAGE ===== */\r\n    /* Design évasion, confiance, destinations de rêve */\r\n    .travel-agency-section {\r\n      font-family: \'Inter\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, sans-serif;\r\n      max-width: 1440px;\r\n      margin: 0 auto;\r\n      background: #ffffff;\r\n      color: #1e2a2f;\r\n      position: relative;\r\n    }\r\n\r\n    /* HEADER VOYAGE */\r\n    .ta-header {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      padding: 24px 48px;\r\n      background: white;\r\n      border-bottom: 1px solid rgba(70, 130, 180, 0.1);\r\n      flex-wrap: wrap;\r\n    }\r\n\r\n    .ta-logo {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 12px;\r\n    }\r\n\r\n    .ta-logo-icon {\r\n      font-size: 36px;\r\n      background: linear-gradient(145deg, #2b7a78, #3a8891);\r\n      color: white;\r\n      padding: 10px;\r\n      border-radius: 18px;\r\n      transform: rotate(-5deg);\r\n    }\r\n\r\n    .ta-logo-text {\r\n      font-size: 28px;\r\n      font-weight: 800;\r\n      letter-spacing: -1px;\r\n      color: #17252e;\r\n    }\r\n\r\n    .ta-logo-text span {\r\n      color: #3a8891;\r\n    }\r\n\r\n    .ta-nav {\r\n      display: flex;\r\n      gap: 42px;\r\n      font-weight: 500;\r\n    }\r\n\r\n    .ta-nav a {\r\n      text-decoration: none;\r\n      color: #2b3e4b;\r\n      font-size: 16px;\r\n    }\r\n\r\n    .ta-actions {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 24px;\r\n    }\r\n\r\n    .ta-contact {\r\n      background: #feffff;\r\n      border: 1.5px solid #3a8891;\r\n      padding: 12px 28px;\r\n      border-radius: 40px;\r\n      color: #1e4a5a;\r\n      font-weight: 600;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 8px;\r\n    }\r\n\r\n    /* HERO VOYAGE - RECHERCHE FORFAITS */\r\n    .ta-hero {\r\n      position: relative;\r\n      padding: 60px 48px 80px;\r\n      background: linear-gradient(145deg, #eef7fb, #e3f0f5);\r\n      border-radius: 0 0 48px 48px;\r\n      overflow: hidden;\r\n    }\r\n\r\n    .ta-hero-bg-icon {\r\n      position: absolute;\r\n      right: 40px;\r\n      bottom: 20px;\r\n      font-size: 160px;\r\n      opacity: 0.1;\r\n      transform: rotate(10deg);\r\n      color: #2b7a78;\r\n    }\r\n\r\n    .ta-hero-content {\r\n      max-width: 700px;\r\n      position: relative;\r\n      z-index: 5;\r\n    }\r\n\r\n    .ta-hero-tag {\r\n      background: rgba(58, 136, 145, 0.12);\r\n      color: #1e5a63;\r\n      padding: 10px 22px;\r\n      border-radius: 40px;\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 10px;\r\n      font-weight: 600;\r\n      font-size: 15px;\r\n      margin-bottom: 28px;\r\n      backdrop-filter: blur(4px);\r\n    }\r\n\r\n    .ta-hero-title {\r\n      font-size: 58px;\r\n      font-weight: 800;\r\n      line-height: 1.1;\r\n      margin: 0 0 24px 0;\r\n      color: #0a2a33;\r\n      letter-spacing: -2px;\r\n    }\r\n\r\n    .ta-hero-highlight {\r\n      color: #3a8891;\r\n      position: relative;\r\n      display: inline-block;\r\n    }\r\n\r\n    .ta-hero-desc {\r\n      font-size: 18px;\r\n      line-height: 1.6;\r\n      color: #2e4a54;\r\n      margin-bottom: 40px;\r\n      max-width: 600px;\r\n    }\r\n\r\n    /* FORMULAIRE RECHERCHE RAPIDE */\r\n    .ta-search-box {\r\n      background: white;\r\n      border-radius: 70px;\r\n      padding: 8px;\r\n      display: flex;\r\n      align-items: center;\r\n      max-width: 700px;\r\n      box-shadow: 0 25px 45px -20px rgba(0,80,100,0.2);\r\n      border: 1px solid rgba(255,255,255,0.5);\r\n      flex-wrap: wrap;\r\n    }\r\n\r\n    .ta-search-item {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 12px;\r\n      padding: 8px 24px;\r\n      border-right: 1px solid #e5edf0;\r\n      flex: 1 1 160px;\r\n    }\r\n\r\n    .ta-search-item:last-child {\r\n      border-right: none;\r\n    }\r\n\r\n    .ta-search-icon {\r\n      font-size: 22px;\r\n      color: #3a8891;\r\n    }\r\n\r\n    .ta-search-content {\r\n      display: flex;\r\n      flex-direction: column;\r\n    }\r\n\r\n    .ta-search-label {\r\n      font-size: 12px;\r\n      color: #7f979b;\r\n      font-weight: 500;\r\n    }\r\n\r\n    .ta-search-value {\r\n      font-weight: 700;\r\n      color: #1e3f4a;\r\n      font-size: 16px;\r\n    }\r\n\r\n    .ta-search-btn {\r\n      background: #3a8891;\r\n      border: none;\r\n      border-radius: 60px;\r\n      padding: 18px 44px;\r\n      color: white;\r\n      font-weight: 700;\r\n      font-size: 17px;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 12px;\r\n      cursor: default;\r\n      box-shadow: 0 12px 22px -8px rgba(58,136,145,0.4);\r\n    }\r\n\r\n    /* DESTINATIONS POPULAIRES */\r\n    .ta-destinations {\r\n      padding: 70px 48px;\r\n    }\r\n\r\n    .section-header {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      align-items: flex-end;\r\n      margin-bottom: 48px;\r\n      flex-wrap: wrap;\r\n    }\r\n\r\n    .section-title {\r\n      font-size: 38px;\r\n      font-weight: 700;\r\n      margin: 0;\r\n      letter-spacing: -1px;\r\n      color: #17252e;\r\n    }\r\n\r\n    .section-sub {\r\n      font-size: 17px;\r\n      color: #5f7d84;\r\n      margin: 8px 0 0 0;\r\n    }\r\n\r\n    .destinations-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 28px;\r\n    }\r\n\r\n    .destination-card {\r\n      background: white;\r\n      border-radius: 32px;\r\n      overflow: hidden;\r\n      box-shadow: 0 20px 35px -15px rgba(0,0,0,0.05);\r\n      border: 1px solid #edf3f5;\r\n      transition: 0.3s ease;\r\n    }\r\n\r\n    .destination-card:hover {\r\n      transform: translateY(-8px);\r\n      box-shadow: 0 30px 45px -18px rgba(58,136,145,0.2);\r\n      border-color: #bfd8dd;\r\n    }\r\n\r\n    .destination-image {\r\n      background: linear-gradient(145deg, #cbdade, #b3ccd0);\r\n      height: 200px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      position: relative;\r\n      font-size: 70px;\r\n    }\r\n\r\n    .destination-price-tag {\r\n      position: absolute;\r\n      top: 18px;\r\n      right: 18px;\r\n      background: white;\r\n      padding: 8px 20px;\r\n      border-radius: 40px;\r\n      font-weight: 700;\r\n      color: #1e5a63;\r\n      box-shadow: 0 6px 14px rgba(0,0,0,0.05);\r\n      font-size: 16px;\r\n    }\r\n\r\n    .destination-info {\r\n      padding: 24px;\r\n    }\r\n\r\n    .destination-name {\r\n      font-size: 24px;\r\n      font-weight: 700;\r\n      margin: 0 0 8px 0;\r\n      color: #17252e;\r\n    }\r\n\r\n    .destination-meta {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 20px;\r\n      color: #5a7980;\r\n      font-size: 15px;\r\n      margin-bottom: 16px;\r\n    }\r\n\r\n    .destination-rating {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 6px;\r\n      color: #f5b342;\r\n      font-weight: 600;\r\n    }\r\n\r\n    .destination-days {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 6px;\r\n    }\r\n\r\n    /* SECTION FORFAITS / PACKAGES */\r\n    .ta-packages {\r\n      padding: 50px 48px 80px;\r\n      background: #f6fbfc;\r\n    }\r\n\r\n    .packages-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 32px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .package-card {\r\n      background: white;\r\n      border-radius: 36px;\r\n      padding: 32px;\r\n      box-shadow: 0 20px 35px -12px rgba(0,60,80,0.05);\r\n      border: 1px solid #e6f0f2;\r\n      transition: 0.25s;\r\n      display: flex;\r\n      flex-direction: column;\r\n    }\r\n\r\n    .package-card:hover {\r\n      border-color: #98c0c5;\r\n      box-shadow: 0 30px 50px -20px rgba(58,136,145,0.2);\r\n    }\r\n\r\n    .package-emoji {\r\n      font-size: 58px;\r\n      margin-bottom: 20px;\r\n    }\r\n\r\n    .package-name {\r\n      font-size: 26px;\r\n      font-weight: 700;\r\n      margin: 0 0 12px 0;\r\n      color: #17252e;\r\n    }\r\n\r\n    .package-desc {\r\n      font-size: 16px;\r\n      line-height: 1.6;\r\n      color: #43636b;\r\n      margin-bottom: 24px;\r\n      flex: 1;\r\n    }\r\n\r\n    .package-features {\r\n      display: flex;\r\n      flex-direction: column;\r\n      gap: 14px;\r\n      margin-bottom: 28px;\r\n    }\r\n\r\n    .package-feature {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 12px;\r\n      font-size: 15px;\r\n      color: #2d515a;\r\n    }\r\n\r\n    .package-price {\r\n      font-size: 32px;\r\n      font-weight: 800;\r\n      color: #1a4a53;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .package-price small {\r\n      font-size: 16px;\r\n      font-weight: 400;\r\n      color: #78959b;\r\n    }\r\n\r\n    .package-btn {\r\n      background: #3a8891;\r\n      color: white;\r\n      padding: 16px 28px;\r\n      border-radius: 50px;\r\n      font-weight: 700;\r\n      text-align: center;\r\n      display: inline-block;\r\n      margin-top: 16px;\r\n      border: none;\r\n      cursor: default;\r\n    }\r\n\r\n    .package-btn.outline {\r\n      background: transparent;\r\n      border: 2px solid #3a8891;\r\n      color: #1e5a63;\r\n    }\r\n\r\n    /* SECTION AVIS VOYAGEURS */\r\n    .ta-testimonials {\r\n      padding: 70px 48px;\r\n    }\r\n\r\n    .testimonials-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 30px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .testimonial-card {\r\n      background: white;\r\n      border-radius: 32px;\r\n      padding: 32px;\r\n      border: 1px solid #eef3f5;\r\n      box-shadow: 0 12px 28px -8px rgba(0,0,0,0.02);\r\n    }\r\n\r\n    .testimonial-header {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 18px;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .testimonial-avatar {\r\n      width: 60px;\r\n      height: 60px;\r\n      background: linear-gradient(145deg, #d2e7ec, #bdd9df);\r\n      border-radius: 22px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      font-size: 28px;\r\n    }\r\n\r\n    .testimonial-name h4 {\r\n      font-size: 18px;\r\n      font-weight: 700;\r\n      margin: 0 0 6px 0;\r\n      color: #17252e;\r\n    }\r\n\r\n    .testimonial-location {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 6px;\r\n      color: #59848b;\r\n      font-size: 14px;\r\n    }\r\n\r\n    .testimonial-text {\r\n      font-size: 16px;\r\n      line-height: 1.7;\r\n      color: #3f5d64;\r\n      margin-bottom: 20px;\r\n      font-style: italic;\r\n    }\r\n\r\n    .testimonial-rating {\r\n      color: #f5b342;\r\n      font-size: 18px;\r\n    }\r\n\r\n    /* BANDEAU RÉSERVATION */\r\n    .ta-cta {\r\n      background: linear-gradient(145deg, #1e5a63, #1a4a53);\r\n      border-radius: 48px;\r\n      margin: 20px 48px 60px;\r\n      padding: 56px 64px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      flex-wrap: wrap;\r\n      color: white;\r\n    }\r\n\r\n    .cta-content h3 {\r\n      font-size: 38px;\r\n      font-weight: 700;\r\n      margin: 0 0 16px 0;\r\n      color: white;\r\n      letter-spacing: -1px;\r\n    }\r\n\r\n    .cta-content p {\r\n      font-size: 18px;\r\n      color: rgba(255,255,255,0.85);\r\n      margin: 0;\r\n      max-width: 600px;\r\n    }\r\n\r\n    .cta-btn {\r\n      background: white;\r\n      color: #1a4a53;\r\n      padding: 20px 52px;\r\n      border-radius: 60px;\r\n      font-weight: 700;\r\n      font-size: 18px;\r\n      border: none;\r\n      box-shadow: 0 20px 35px -12px rgba(0,0,0,0.2);\r\n    }\r\n\r\n    /* FOOTER VOYAGE */\r\n    .ta-footer {\r\n      background: #f0f6f8;\r\n      padding: 60px 48px 30px;\r\n      border-top: 1px solid #d7e3e6;\r\n    }\r\n\r\n    .footer-main {\r\n      display: grid;\r\n      grid-template-columns: 2fr 1fr 1fr 1.5fr;\r\n      gap: 50px;\r\n      margin-bottom: 50px;\r\n    }\r\n\r\n    .footer-about p {\r\n      color: #4d6f76;\r\n      line-height: 1.7;\r\n      margin: 24px 0;\r\n    }\r\n\r\n    .footer-links {\r\n      display: flex;\r\n      flex-direction: column;\r\n      gap: 16px;\r\n    }\r\n\r\n    .footer-links a {\r\n      text-decoration: none;\r\n      color: #43636b;\r\n      font-size: 15px;\r\n    }\r\n\r\n    .footer-title {\r\n      font-weight: 700;\r\n      color: #1e4a5a;\r\n      margin-bottom: 12px;\r\n      font-size: 18px;\r\n    }\r\n\r\n    .footer-bottom {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      align-items: center;\r\n      padding-top: 30px;\r\n      border-top: 1px solid #cbdce0;\r\n      color: #5e8087;\r\n    }\r\n\r\n    /* RESPONSIVE */\r\n    @media (max-width: 1100px) {\r\n      .destinations-grid,\r\n      .packages-grid,\r\n      .testimonials-grid,\r\n      .footer-main {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n    }\r\n\r\n    @media (max-width: 800px) {\r\n      .destinations-grid,\r\n      .packages-grid,\r\n      .testimonials-grid,\r\n      .footer-main {\r\n        grid-template-columns: 1fr;\r\n      }\r\n      .ta-hero-title {\r\n        font-size: 44px;\r\n      }\r\n      .ta-search-box {\r\n        border-radius: 30px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 600px) {\r\n      .ta-header {\r\n        flex-direction: column;\r\n        gap: 20px;\r\n      }\r\n      .ta-hero, .ta-destinations, .ta-packages {\r\n        padding: 40px 24px;\r\n      }\r\n    }\r\n\r\n    .gjs-draggable { cursor: move; }', NULL, NULL, NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL);
INSERT INTO `templates` (`id`, `categorie_id`, `name`, `url`, `description`, `html_content`, `css_content`, `js_content`, `assets_folder`, `assets_data`, `thumbnail`, `metadata`, `user_id`, `website_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(90, 3, 'Site Corporate · Présence Institutionnelle', NULL, NULL, '<body>\r\n  <!-- SITE CORPORATE - PRÉSENCE INSTITUTIONNELLE PREMIUM -->\r\n  <section class=\"corporate-section\">\r\n\r\n    <!-- HEADER INSTITUTIONNEL -->\r\n    <header class=\"corp-header\">\r\n      <div class=\"corp-logo\">\r\n        <span class=\"corp-logo-icon\">G</span>\r\n        <span class=\"corp-logo-text\">Groupe<span>Altus</span></span>\r\n      </div>\r\n      <nav class=\"corp-nav\">\r\n        <a href=\"#\">Groupe</a>\r\n        <a href=\"#\">Expertises</a>\r\n        <a href=\"#\">Engagements</a>\r\n        <a href=\"#\">Médias</a>\r\n        <a href=\"#\">Carrières</a>\r\n      </nav>\r\n      <div class=\"corp-actions\">\r\n        <span class=\"corp-lang\">🌐 FR</span>\r\n        <span class=\"corp-contact-btn\">Contact</span>\r\n      </div>\r\n    </header>\r\n\r\n    <!-- HERO INSTITUTIONNEL - MESSAGE FORT -->\r\n    <div class=\"corp-hero\">\r\n      <div class=\"corp-hero-left\">\r\n        <span class=\"corp-hero-tag\">\r\n          <span>🏛️</span> Groupe international\r\n        </span>\r\n        <h1 class=\"corp-hero-title\">\r\n          Construisons ensemble <span>l\'avenir</span> avec responsabilité\r\n        </h1>\r\n        <p class=\"corp-hero-desc\">\r\n          Depuis 1985, Groupe Altus accompagne les transformations stratégiques \r\n          des grandes institutions et entreprises. Présents dans 25 pays.\r\n        </p>\r\n        <div class=\"corp-hero-stats\">\r\n          <div class=\"corp-stat-item\">\r\n            <span class=\"corp-stat-number\">25</span>\r\n            <span class=\"corp-stat-label\">Pays d\'implantation</span>\r\n          </div>\r\n          <div class=\"corp-stat-item\">\r\n            <span class=\"corp-stat-number\">1 200</span>\r\n            <span class=\"corp-stat-label\">Collaborateurs</span>\r\n          </div>\r\n          <div class=\"corp-stat-item\">\r\n            <span class=\"corp-stat-number\">450M€</span>\r\n            <span class=\"corp-stat-label\">Chiffre d\'affaires</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div class=\"corp-hero-right\">\r\n        <div class=\"corp-quote\">\r\n          “Notre raison d\'être : innover avec intégrité pour construire un monde plus durable et inclusif.”\r\n        </div>\r\n        <div class=\"corp-author\">\r\n          <div class=\"corp-avatar\">👤</div>\r\n          <div>\r\n            <div style=\"font-weight: 700; color: #0a2a36;\">Marie-Noëlle Delacroix</div>\r\n            <div style=\"font-size: 14px; color: #4e6b76;\">Présidente-directrice générale</div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- VALEURS & MISSION -->\r\n    <div class=\"corp-values\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-surtitle\">NOS VALEURS</div>\r\n        <h2 class=\"section-title\">Une éthique au cœur de nos actions</h2>\r\n        <p class=\"section-desc\">\r\n          L\'exigence, la confiance et l\'engagement guident chacune de nos décisions depuis 40 ans.\r\n        </p>\r\n      </div>\r\n      <div class=\"values-grid\">\r\n        <div class=\"value-card\">\r\n          <div class=\"value-icon\">⚖️</div>\r\n          <h3 class=\"value-title\">Intégrité</h3>\r\n          <p class=\"value-text\">Transparence totale dans nos relations avec nos parties prenantes.</p>\r\n        </div>\r\n        <div class=\"value-card\">\r\n          <div class=\"value-icon\">🚀</div>\r\n          <h3 class=\"value-title\">Excellence</h3>\r\n          <p class=\"value-text\">La recherche permanente de la qualité et de la performance.</p>\r\n        </div>\r\n        <div class=\"value-card\">\r\n          <div class=\"value-icon\">🤝</div>\r\n          <h3 class=\"value-title\">Respect</h3>\r\n          <p class=\"value-text\">Considération de nos collaborateurs, clients et de l\'environnement.</p>\r\n        </div>\r\n        <div class=\"value-card\">\r\n          <div class=\"value-icon\">🌍</div>\r\n          <h3 class=\"value-title\">Responsabilité</h3>\r\n          <p class=\"value-text\">Agir pour un impact positif sur la société et les territoires.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- EXPERTISES / PÔLES D\'ACTIVITÉ -->\r\n    <div class=\"corp-expertise\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-surtitle\">NOS EXPERTISES</div>\r\n        <h2 class=\"section-title\">Quatre pôles complémentaires</h2>\r\n        <p class=\"section-desc\">\r\n          Une offre intégrée au service des grandes transformations.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"expertise-grid\">\r\n        <div class=\"expertise-card\">\r\n          <div class=\"expertise-number\">01</div>\r\n          <h3 class=\"expertise-name\">Conseil stratégique</h3>\r\n          <p class=\"expertise-desc\">\r\n            Accompagnement des directions générales dans leurs décisions majeures : fusions, transformations, internationalisation.\r\n          </p>\r\n          <span class=\"expertise-link\">Découvrir →</span>\r\n        </div>\r\n        <div class=\"expertise-card\">\r\n          <div class=\"expertise-number\">02</div>\r\n          <h3 class=\"expertise-name\">Ingénierie financière</h3>\r\n          <p class=\"expertise-desc\">\r\n            Optimisation de la structure financière, levées de fonds, due diligence et accompagnement M&A.\r\n          </p>\r\n          <span class=\"expertise-link\">Découvrir →</span>\r\n        </div>\r\n        <div class=\"expertise-card\">\r\n          <div class=\"expertise-number\">03</div>\r\n          <h3 class=\"expertise-name\">Transition numérique</h3>\r\n          <p class=\"expertise-desc\">\r\n            Accélération digitale des organisations, cybersécurité, data intelligence et expérience client.\r\n          </p>\r\n          <span class=\"expertise-link\">Découvrir →</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- CHIFFRES CLÉS -->\r\n    <div class=\"corp-figures\">\r\n      <div class=\"figures-container\">\r\n        <div class=\"figure-block\">\r\n          <div class=\"figure-big\">40</div>\r\n          <div class=\"figure-label\">ans d\'expertise</div>\r\n        </div>\r\n        <div class=\"figure-block\">\r\n          <div class=\"figure-big\">25</div>\r\n          <div class=\"figure-label\">implantations</div>\r\n        </div>\r\n        <div class=\"figure-block\">\r\n          <div class=\"figure-big\">1 200</div>\r\n          <div class=\"figure-label\">talents</div>\r\n        </div>\r\n        <div class=\"figure-block\">\r\n          <div class=\"figure-big\">+800</div>\r\n          <div class=\"figure-label\">clients grands comptes</div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- COMITÉ DE DIRECTION -->\r\n    <div class=\"corp-leadership\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-surtitle\">GOUVERNANCE</div>\r\n        <h2 class=\"section-title\">Notre comité exécutif</h2>\r\n        <p class=\"section-desc\">\r\n          Une équipe dirigeante pluridisciplinaire, engagée au service de notre mission.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"leadership-grid\">\r\n        <div class=\"leader-card\">\r\n          <div class=\"leader-avatar\">👩</div>\r\n          <h3 class=\"leader-name\">Marie-Noëlle Delacroix</h3>\r\n          <div class=\"leader-position\">Présidente</div>\r\n          <p class=\"leader-bio\">40 ans d\'expérience dans le conseil aux directions générales.</p>\r\n        </div>\r\n        <div class=\"leader-card\">\r\n          <div class=\"leader-avatar\">👨</div>\r\n          <h3 class=\"leader-name\">Thomas Beauchamp</h3>\r\n          <div class=\"leader-position\">Directeur Général</div>\r\n          <p class=\"leader-bio\">Ancien associé chez McKinsey, expert en transformation.</p>\r\n        </div>\r\n        <div class=\"leader-card\">\r\n          <div class=\"leader-avatar\">👩‍⚖️</div>\r\n          <h3 class=\"leader-name\">Catherine Fontaine</h3>\r\n          <div class=\"leader-position\">Directrice Juridique & RSE</div>\r\n          <p class=\"leader-bio\">Pilote la stratégie RSE et conformité groupe.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- ENGAGEMENTS RSE -->\r\n    <div class=\"corp-commitments\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-surtitle\">RESPONSABILITÉ SOCIÉTALE</div>\r\n        <h2 class=\"section-title\">Nos engagements concrets</h2>\r\n        <p class=\"section-desc\">\r\n          Parce que la performance durable est notre seul horizon.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"commitments-grid\">\r\n        <div class=\"commitment-item\">\r\n          <span class=\"commitment-icon\">🌱</span>\r\n          <div class=\"commitment-text\">\r\n            <h4>Neutralité carbone</h4>\r\n            <p>Objectif 2035 : réduction de 50% de nos émissions et compensation intégrale.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"commitment-item\">\r\n          <span class=\"commitment-icon\">🤲</span>\r\n          <div class=\"commitment-text\">\r\n            <h4>Fondation d\'entreprise</h4>\r\n            <p>Soutien à l\'éducation et l\'insertion professionnelle des jeunes.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"commitment-item\">\r\n          <span class=\"commitment-icon\">⚖️</span>\r\n          <div class=\"commitment-text\">\r\n            <h4>Parité & inclusion</h4>\r\n            <p>45% de femmes au comex, 35 nationalités représentées.</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- BANDEAU CONTACT / PRISE DE CONTACT -->\r\n    <div class=\"corp-cta\">\r\n      <div class=\"cta-left\">\r\n        <h3>Une ambition ? Un projet ?</h3>\r\n        <p>Nos équipes sont à votre écoute pour échanger sur vos enjeux stratégiques.</p>\r\n      </div>\r\n      <span class=\"cta-btn\">Nous contacter →</span>\r\n    </div>\r\n\r\n    <!-- FOOTER CORPORATE -->\r\n    <footer class=\"corp-footer\">\r\n      <div class=\"footer-main\">\r\n        <div class=\"footer-about\">\r\n          <div class=\"footer-logo\">\r\n            <span>Groupe Altus</span>\r\n          </div>\r\n          <p>Société de conseil et d\'ingénierie financière, certifiée B Corp et signataire du Global Compact.</p>\r\n          <div class=\"footer-social\">\r\n            <span>📘</span>\r\n            <span>📷</span>\r\n            <span>🐦</span>\r\n            <span>🔗</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Groupe</span>\r\n          <a href=\"#\">Qui sommes-nous</a>\r\n          <a href=\"#\">Gouvernance</a>\r\n          <a href=\"#\">Rapport annuel</a>\r\n          <a href=\"#\">Presse</a>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Expertises</span>\r\n          <a href=\"#\">Stratégie</a>\r\n          <a href=\"#\">Finance</a>\r\n          <a href=\"#\">Digital</a>\r\n          <a href=\"#\">RSE</a>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Carrières</span>\r\n          <a href=\"#\">Offres d\'emploi</a>\r\n          <a href=\"#\">Candidature spontanée</a>\r\n          <a href=\"#\">Talents</a>\r\n          <a href=\"#\">FAQ recrutement</a>\r\n        </div>\r\n      </div>\r\n      <div class=\"footer-bottom\">\r\n        <span>© 2026 Groupe Altus. Tous droits réservés.</span>\r\n        <span style=\"display: flex; gap: 28px;\">\r\n          <span>Mentions légales</span>\r\n          <span>Confidentialité</span>\r\n          <span>Cookies</span>\r\n        </span>\r\n      </div>\r\n    </footer>\r\n  </section>\r\n</body>', ' /* ===== STYLE CORPORATE - ÉLÉGANCE & CONFIANCE ===== */\r\n    /* Design institutionnel, premium, sobre */\r\n    .corporate-section {\r\n      font-family: \'Inter\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, sans-serif;\r\n      max-width: 1440px;\r\n      margin: 0 auto;\r\n      background: #ffffff;\r\n      color: #1e2b3c;\r\n      position: relative;\r\n    }\r\n\r\n    /* HEADER CORPORATE - SOBRE & PROFESSIONNEL */\r\n    .corp-header {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      padding: 20px 60px;\r\n      background: white;\r\n      border-bottom: 1px solid #f0f2f5;\r\n      flex-wrap: wrap;\r\n    }\r\n\r\n    .corp-logo {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 12px;\r\n    }\r\n\r\n    .corp-logo-icon {\r\n      font-size: 32px;\r\n      background: linear-gradient(145deg, #0a3143, #0b3b4f);\r\n      color: white;\r\n      padding: 10px;\r\n      border-radius: 12px;\r\n      font-weight: 600;\r\n    }\r\n\r\n    .corp-logo-text {\r\n      font-size: 26px;\r\n      font-weight: 700;\r\n      letter-spacing: -0.5px;\r\n      color: #0c2a36;\r\n    }\r\n\r\n    .corp-logo-text span {\r\n      font-weight: 300;\r\n      color: #4f7a8c;\r\n    }\r\n\r\n    .corp-nav {\r\n      display: flex;\r\n      gap: 44px;\r\n      font-weight: 500;\r\n    }\r\n\r\n    .corp-nav a {\r\n      text-decoration: none;\r\n      color: #2c404c;\r\n      font-size: 16px;\r\n      transition: 0.2s;\r\n    }\r\n\r\n    .corp-nav a:hover {\r\n      color: #0066a1;\r\n    }\r\n\r\n    .corp-actions {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 20px;\r\n    }\r\n\r\n    .corp-lang {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 8px;\r\n      color: #3a5a6a;\r\n      font-weight: 500;\r\n    }\r\n\r\n    .corp-contact-btn {\r\n      background: transparent;\r\n      border: 1.5px solid #0a3143;\r\n      padding: 12px 28px;\r\n      border-radius: 40px;\r\n      font-weight: 600;\r\n      color: #0a3143;\r\n      transition: 0.2s;\r\n    }\r\n\r\n    /* HERO CORPORATE - IMPACT VISUEL */\r\n    .corp-hero {\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 40px;\r\n      padding: 60px 60px 80px;\r\n      background: linear-gradient(145deg, #f9fcff, #f4f8fd);\r\n      position: relative;\r\n      overflow: hidden;\r\n    }\r\n\r\n    .corp-hero::before {\r\n      content: \"● ● ●\";\r\n      position: absolute;\r\n      top: 30px;\r\n      right: 60px;\r\n      font-size: 140px;\r\n      color: rgba(10, 49, 67, 0.02);\r\n      letter-spacing: 20px;\r\n    }\r\n\r\n    .corp-hero-left {\r\n      display: flex;\r\n      flex-direction: column;\r\n      justify-content: center;\r\n    }\r\n\r\n    .corp-hero-tag {\r\n      background: rgba(10, 49, 67, 0.06);\r\n      color: #0a3143;\r\n      padding: 8px 22px;\r\n      border-radius: 40px;\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 10px;\r\n      font-weight: 600;\r\n      font-size: 15px;\r\n      margin-bottom: 28px;\r\n      width: fit-content;\r\n    }\r\n\r\n    .corp-hero-title {\r\n      font-size: 56px;\r\n      font-weight: 700;\r\n      line-height: 1.1;\r\n      margin: 0 0 24px 0;\r\n      color: #0a1e26;\r\n      letter-spacing: -1.5px;\r\n    }\r\n\r\n    .corp-hero-title span {\r\n      color: #0066a1;\r\n      position: relative;\r\n    }\r\n\r\n    .corp-hero-desc {\r\n      font-size: 18px;\r\n      line-height: 1.7;\r\n      color: #3a5563;\r\n      margin-bottom: 40px;\r\n      max-width: 90%;\r\n    }\r\n\r\n    .corp-hero-stats {\r\n      display: flex;\r\n      gap: 48px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .corp-stat-item {\r\n      display: flex;\r\n      flex-direction: column;\r\n    }\r\n\r\n    .corp-stat-number {\r\n      font-size: 36px;\r\n      font-weight: 700;\r\n      color: #0a3143;\r\n    }\r\n\r\n    .corp-stat-label {\r\n      font-size: 15px;\r\n      color: #597888;\r\n    }\r\n\r\n    .corp-hero-right {\r\n      background: white;\r\n      border-radius: 40px;\r\n      padding: 40px;\r\n      box-shadow: 0 30px 50px -25px rgba(0,60,90,0.08);\r\n      border: 1px solid rgba(10,49,67,0.05);\r\n      display: flex;\r\n      flex-direction: column;\r\n      justify-content: center;\r\n    }\r\n\r\n    .corp-quote {\r\n      font-size: 22px;\r\n      line-height: 1.5;\r\n      color: #1a3c4c;\r\n      font-weight: 500;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .corp-author {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .corp-avatar {\r\n      width: 56px;\r\n      height: 56px;\r\n      background: linear-gradient(145deg, #d9e6f0, #c5d8e5);\r\n      border-radius: 18px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      font-size: 24px;\r\n      color: #0a3143;\r\n    }\r\n\r\n    /* SECTION VALEURS / MÉTIER */\r\n    .corp-values {\r\n      padding: 80px 60px;\r\n      background: white;\r\n    }\r\n\r\n    .section-header {\r\n      text-align: center;\r\n      max-width: 700px;\r\n      margin: 0 auto 60px;\r\n    }\r\n\r\n    .section-surtitle {\r\n      font-size: 15px;\r\n      text-transform: uppercase;\r\n      letter-spacing: 3px;\r\n      color: #0066a1;\r\n      font-weight: 600;\r\n      margin-bottom: 16px;\r\n    }\r\n\r\n    .section-title {\r\n      font-size: 42px;\r\n      font-weight: 700;\r\n      margin: 0 0 20px 0;\r\n      color: #0a1e26;\r\n      letter-spacing: -1px;\r\n    }\r\n\r\n    .section-desc {\r\n      font-size: 18px;\r\n      color: #4d6773;\r\n      line-height: 1.6;\r\n    }\r\n\r\n    .values-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 30px;\r\n      margin-top: 20px;\r\n    }\r\n\r\n    .value-card {\r\n      background: #fafcfe;\r\n      border-radius: 32px;\r\n      padding: 36px 28px;\r\n      border: 1px solid #eaf0f4;\r\n      transition: 0.25s ease;\r\n    }\r\n\r\n    .value-card:hover {\r\n      border-color: #b0cddb;\r\n      box-shadow: 0 20px 35px -18px rgba(0,80,110,0.08);\r\n      transform: translateY(-5px);\r\n    }\r\n\r\n    .value-icon {\r\n      font-size: 48px;\r\n      margin-bottom: 28px;\r\n    }\r\n\r\n    .value-title {\r\n      font-size: 22px;\r\n      font-weight: 700;\r\n      margin: 0 0 16px 0;\r\n      color: #0a2a36;\r\n    }\r\n\r\n    .value-text {\r\n      font-size: 16px;\r\n      line-height: 1.7;\r\n      color: #45606b;\r\n      margin: 0;\r\n    }\r\n\r\n    /* SECTION EXPERTISE / SERVICES */\r\n    .corp-expertise {\r\n      background: #f5f9fc;\r\n      padding: 80px 60px;\r\n    }\r\n\r\n    .expertise-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 32px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .expertise-card {\r\n      background: white;\r\n      border-radius: 32px;\r\n      padding: 36px;\r\n      box-shadow: 0 15px 30px -12px rgba(0,0,0,0.02);\r\n      border: 1px solid #eef3f7;\r\n    }\r\n\r\n    .expertise-number {\r\n      font-size: 42px;\r\n      font-weight: 800;\r\n      color: rgba(0,102,161,0.1);\r\n      margin-bottom: 20px;\r\n      line-height: 1;\r\n    }\r\n\r\n    .expertise-name {\r\n      font-size: 24px;\r\n      font-weight: 700;\r\n      margin: 0 0 18px 0;\r\n      color: #0a2a36;\r\n    }\r\n\r\n    .expertise-desc {\r\n      font-size: 16px;\r\n      line-height: 1.7;\r\n      color: #47636e;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .expertise-link {\r\n      color: #0066a1;\r\n      font-weight: 600;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 8px;\r\n    }\r\n\r\n    /* SECTION CHIFFRES CLÉS */\r\n    .corp-figures {\r\n      padding: 70px 60px;\r\n      background: white;\r\n    }\r\n\r\n    .figures-container {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 40px;\r\n      background: linear-gradient(145deg, #f0f7fa, #eaf2f6);\r\n      border-radius: 60px;\r\n      padding: 60px 50px;\r\n    }\r\n\r\n    .figure-block {\r\n      text-align: center;\r\n    }\r\n\r\n    .figure-big {\r\n      font-size: 52px;\r\n      font-weight: 800;\r\n      color: #0a3143;\r\n      margin-bottom: 12px;\r\n    }\r\n\r\n    .figure-label {\r\n      font-size: 17px;\r\n      color: #2d5563;\r\n      font-weight: 500;\r\n    }\r\n\r\n    /* SECTION ÉQUIPE DIRIGEANTE */\r\n    .corp-leadership {\r\n      padding: 80px 60px;\r\n      background: #f5f9fc;\r\n    }\r\n\r\n    .leadership-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 32px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .leader-card {\r\n      background: white;\r\n      border-radius: 32px;\r\n      padding: 32px;\r\n      border: 1px solid #e9f0f3;\r\n      display: flex;\r\n      flex-direction: column;\r\n      align-items: center;\r\n      text-align: center;\r\n    }\r\n\r\n    .leader-avatar {\r\n      width: 120px;\r\n      height: 120px;\r\n      background: linear-gradient(145deg, #d0e1e8, #c0d5df);\r\n      border-radius: 32px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      font-size: 52px;\r\n      margin-bottom: 24px;\r\n      color: #0a3143;\r\n    }\r\n\r\n    .leader-name {\r\n      font-size: 24px;\r\n      font-weight: 700;\r\n      margin: 0 0 6px 0;\r\n      color: #0a2a36;\r\n    }\r\n\r\n    .leader-position {\r\n      font-size: 16px;\r\n      color: #0066a1;\r\n      font-weight: 600;\r\n      margin-bottom: 18px;\r\n    }\r\n\r\n    .leader-bio {\r\n      font-size: 15px;\r\n      color: #4b6873;\r\n      line-height: 1.6;\r\n    }\r\n\r\n    /* SECTION ENGAGEMENTS RSE */\r\n    .corp-commitments {\r\n      padding: 70px 60px;\r\n      background: white;\r\n    }\r\n\r\n    .commitments-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 30px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .commitment-item {\r\n      display: flex;\r\n      gap: 22px;\r\n      align-items: flex-start;\r\n    }\r\n\r\n    .commitment-icon {\r\n      font-size: 36px;\r\n      background: #f0f7fa;\r\n      padding: 16px;\r\n      border-radius: 22px;\r\n      color: #0066a1;\r\n    }\r\n\r\n    .commitment-text h4 {\r\n      font-size: 20px;\r\n      font-weight: 700;\r\n      margin: 0 0 12px 0;\r\n      color: #0a2a36;\r\n    }\r\n\r\n    .commitment-text p {\r\n      font-size: 16px;\r\n      color: #4e6b76;\r\n      line-height: 1.6;\r\n      margin: 0;\r\n    }\r\n\r\n    /* BANDEAU CONTACT / ACCOMPAGNEMENT */\r\n    .corp-cta {\r\n      background: linear-gradient(145deg, #0a3143, #0b3b4f);\r\n      border-radius: 48px;\r\n      margin: 40px 60px 60px;\r\n      padding: 60px 70px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      flex-wrap: wrap;\r\n      color: white;\r\n    }\r\n\r\n    .cta-left h3 {\r\n      font-size: 36px;\r\n      font-weight: 700;\r\n      margin: 0 0 16px 0;\r\n      color: white;\r\n      letter-spacing: -1px;\r\n    }\r\n\r\n    .cta-left p {\r\n      font-size: 18px;\r\n      color: rgba(255,255,255,0.8);\r\n      margin: 0;\r\n      max-width: 600px;\r\n    }\r\n\r\n    .cta-btn {\r\n      background: white;\r\n      color: #0a3143;\r\n      padding: 18px 52px;\r\n      border-radius: 60px;\r\n      font-weight: 700;\r\n      font-size: 18px;\r\n      border: none;\r\n      box-shadow: 0 20px 35px -12px rgba(0,0,0,0.2);\r\n      transition: 0.2s;\r\n    }\r\n\r\n    /* FOOTER CORPORATE */\r\n    .corp-footer {\r\n      background: #0f2835;\r\n      color: white;\r\n      padding: 60px 60px 30px;\r\n    }\r\n\r\n    .footer-main {\r\n      display: grid;\r\n      grid-template-columns: 2fr 1fr 1fr 1.5fr;\r\n      gap: 50px;\r\n      margin-bottom: 50px;\r\n    }\r\n\r\n    .footer-logo {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 12px;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .footer-logo span {\r\n      font-size: 28px;\r\n      font-weight: 700;\r\n      color: white;\r\n    }\r\n\r\n    .footer-about p {\r\n      color: rgba(255,255,255,0.6);\r\n      line-height: 1.7;\r\n      margin: 0 0 24px 0;\r\n    }\r\n\r\n    .footer-links {\r\n      display: flex;\r\n      flex-direction: column;\r\n      gap: 14px;\r\n    }\r\n\r\n    .footer-links a {\r\n      text-decoration: none;\r\n      color: rgba(255,255,255,0.6);\r\n      font-size: 15px;\r\n      transition: 0.2s;\r\n    }\r\n\r\n    .footer-links a:hover {\r\n      color: white;\r\n    }\r\n\r\n    .footer-title {\r\n      font-weight: 700;\r\n      color: white;\r\n      margin-bottom: 16px;\r\n      font-size: 18px;\r\n    }\r\n\r\n    .footer-bottom {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      align-items: center;\r\n      padding-top: 30px;\r\n      border-top: 1px solid rgba(255,255,255,0.1);\r\n      color: rgba(255,255,255,0.5);\r\n      font-size: 14px;\r\n    }\r\n\r\n    .footer-social {\r\n      display: flex;\r\n      gap: 28px;\r\n      font-size: 22px;\r\n    }\r\n\r\n    /* RESPONSIVE */\r\n    @media (max-width: 1100px) {\r\n      .values-grid,\r\n      .figures-container,\r\n      .leadership-grid,\r\n      .commitments-grid,\r\n      .footer-main {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n      .expertise-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n    }\r\n\r\n    @media (max-width: 900px) {\r\n      .corp-hero {\r\n        grid-template-columns: 1fr;\r\n      }\r\n      .corp-header {\r\n        flex-direction: column;\r\n        gap: 20px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 700px) {\r\n      .values-grid,\r\n      .expertise-grid,\r\n      .figures-container,\r\n      .leadership-grid,\r\n      .commitments-grid,\r\n      .footer-main {\r\n        grid-template-columns: 1fr;\r\n      }\r\n      .corp-hero,\r\n      .corp-values,\r\n      .corp-expertise,\r\n      .corp-leadership {\r\n        padding: 40px 24px;\r\n      }\r\n    }\r\n\r\n    .gjs-draggable { cursor: move; }', NULL, NULL, NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL);
INSERT INTO `templates` (`id`, `categorie_id`, `name`, `url`, `description`, `html_content`, `css_content`, `js_content`, `assets_folder`, `assets_data`, `thumbnail`, `metadata`, `user_id`, `website_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(91, 3, 'Cabinet de conseil', NULL, NULL, '<body>\r\n  <!-- CABINET DE CONSEIL - SITE VITRINE PROFESSIONNEL -->\r\n  <section class=\"consulting-section\">\r\n\r\n    <!-- HEADER ÉLÉGANT -->\r\n    <header class=\"cons-header\">\r\n      <div class=\"cons-logo\">\r\n        <span class=\"cons-logo-symbol\">⟁</span>\r\n        <span class=\"cons-logo-text\">Axis<span style=\"color: #b45a3b;\">.</span>Conseil</span>\r\n      </div>\r\n      <nav class=\"cons-nav\">\r\n        <a href=\"#\">Expertises</a>\r\n        <a href=\"#\">Méthode</a>\r\n        <a href=\"#\">Équipe</a>\r\n        <a href=\"#\">Réalisations</a>\r\n        <a href=\"#\">Perspectives</a>\r\n      </nav>\r\n      <button class=\"cons-cta\">Échanger</button>\r\n    </header>\r\n\r\n    <!-- HERO - MESSAGE CONSEIL -->\r\n    <div class=\"cons-hero\">\r\n      <div class=\"cons-hero-left\">\r\n        <span class=\"cons-hero-tag\">\r\n          <span>📊</span> Cabinet indépendant depuis 2008\r\n        </span>\r\n        <h1 class=\"cons-hero-title\">\r\n          Stratégie, management, <span class=\"cons-hero-accent\">performance durable</span>\r\n        </h1>\r\n        <p class=\"cons-hero-desc\">\r\n          Nous accompagnons les directions générales dans leurs transformations critiques. \r\n          Une approche sur-mesure, des résultats mesurables.\r\n        </p>\r\n        <div class=\"cons-hero-btns\">\r\n          <button class=\"btn-primary\">Nos expertises →</button>\r\n          <button class=\"btn-outline\">Nous rencontrer</button>\r\n        </div>\r\n      </div>\r\n      <div class=\"cons-hero-right\">\r\n        <div class=\"cons-testimonial\">\r\n          “Axis.Conseil a structuré notre plan stratégique et nous a aidés à pivoter face aux défis du marché. Un partenaire de confiance.”\r\n        </div>\r\n        <div class=\"cons-client\">\r\n          <div class=\"cons-client-avatar\">JD</div>\r\n          <div>\r\n            <div style=\"font-weight: 700; color: #173e4a;\">Jean Delamare</div>\r\n            <div style=\"font-size: 14px; color: #547a85;\">DG, Groupe Delamare Industries</div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- EXPERTISES - CŒUR DE MÉTIER -->\r\n    <div class=\"cons-expertises\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-surtitle\">NOTRE SAVOIR-FAIRE</div>\r\n        <h2 class=\"section-title\">Expertises à haute valeur ajoutée</h2>\r\n        <p class=\"section-desc\">\r\n          Des compétences pointues au service de vos enjeux stratégiques et opérationnels.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"expertises-grid\">\r\n        <div class=\"expertise-card\">\r\n          <div class=\"expertise-icon\">📐</div>\r\n          <h3 class=\"expertise-name\">Stratégie d\'entreprise</h3>\r\n          <p class=\"expertise-desc\">\r\n            Diagnostic stratégique, feuille de route croissance, diversification, internationalisation.\r\n          </p>\r\n          <span class=\"expertise-link\">Découvrir →</span>\r\n        </div>\r\n        <div class=\"expertise-card\">\r\n          <div class=\"expertise-icon\">⚙️</div>\r\n          <h3 class=\"expertise-name\">Performance opérationnelle</h3>\r\n          <p class=\"expertise-desc\">\r\n            Optimisation des processus, supply chain, excellence industrielle, transformation lean.\r\n          </p>\r\n          <span class=\"expertise-link\">Découvrir →</span>\r\n        </div>\r\n        <div class=\"expertise-card\">\r\n          <div class=\"expertise-icon\">👥</div>\r\n          <h3 class=\"expertise-name\">Management & RH</h3>\r\n          <p class=\"expertise-desc\">\r\n            Conduite du changement, marque employeur, organisation du travail, développement des talents.\r\n          </p>\r\n          <span class=\"expertise-link\">Découvrir →</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- MÉTHODOLOGIE EN 4 ÉTAPES -->\r\n    <div class=\"cons-methodology\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-surtitle\">NOTRE MÉTHODE</div>\r\n        <h2 class=\"section-title\">Un processus éprouvé</h2>\r\n        <p class=\"section-desc\">\r\n          De l\'audit à la mise en œuvre, nous vous accompagnons à chaque étape.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"methodology-grid\">\r\n        <div class=\"methodology-step\">\r\n          <div class=\"step-number\">01</div>\r\n          <h4 class=\"step-title\">Diagnostic</h4>\r\n          <p class=\"step-desc\">Analyse terrain, entretiens, data review. Nous identifions vos leviers.</p>\r\n        </div>\r\n        <div class=\"methodology-step\">\r\n          <div class=\"step-number\">02</div>\r\n          <h4 class=\"step-title\">Stratégie</h4>\r\n          <p class=\"step-desc\">Co-construction du plan d\'action avec vos équipes de direction.</p>\r\n        </div>\r\n        <div class=\"methodology-step\">\r\n          <div class=\"step-number\">03</div>\r\n          <h4 class=\"step-title\">Déploiement</h4>\r\n          <p class=\"step-desc\">Accompagnement opérationnel, agile et pragmatique.</p>\r\n        </div>\r\n        <div class=\"methodology-step\">\r\n          <div class=\"step-number\">04</div>\r\n          <h4 class=\"step-title\">Pérennisation</h4>\r\n          <p class=\"step-desc\">Transfert de compétences et pilotage des résultats.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- ÉQUIPE DIRIGEANTE / ASSOCIÉS -->\r\n    <div class=\"cons-team\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-surtitle\">NOTRE ÉQUIPE</div>\r\n        <h2 class=\"section-title\">Des associés impliqués</h2>\r\n        <p class=\"section-desc\">\r\n          Des profils complémentaires, une culture commune de l\'impact.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"team-grid\">\r\n        <div class=\"team-card\">\r\n          <div class=\"team-avatar\">👨</div>\r\n          <h3 class=\"team-name\">François Vernier</h3>\r\n          <div class=\"team-role\">Associé fondateur</div>\r\n          <p class=\"team-bio\">Ancien BCG, 20 ans d\'expérience en stratégie corporate.</p>\r\n        </div>\r\n        <div class=\"team-card\">\r\n          <div class=\"team-avatar\">👩</div>\r\n          <h3 class=\"team-name\">Céline Arnaud</h3>\r\n          <div class=\"team-role\">Associée - Performance</div>\r\n          <p class=\"team-bio\">Experte en transformation opérationnelle et supply chain.</p>\r\n        </div>\r\n        <div class=\"team-card\">\r\n          <div class=\"team-avatar\">👨‍💼</div>\r\n          <h3 class=\"team-name\">Marc Delcourt</h3>\r\n          <div class=\"team-role\">Associé - RH & Conduite du changement</div>\r\n          <p class=\"team-bio\">DRH de grands groupes, spécialiste des transformations humaines.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- ÉTUDES DE CAS CLIENTS -->\r\n    <div class=\"cons-cases\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-surtitle\">RÉALISATIONS</div>\r\n        <h2 class=\"section-title\">Ils nous ont fait confiance</h2>\r\n        <p class=\"section-desc\">\r\n          Quelques exemples de missions à fort impact.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"cases-grid\">\r\n        <div class=\"case-card\">\r\n          <span class=\"case-tag\">Industrie</span>\r\n          <h3 class=\"case-title\">Redressement opérationnel</h3>\r\n          <p class=\"case-desc\">\r\n            Retour à la rentabilité en 18 mois pour un équipementier automobile de 800 salariés. Plan de performance et recentrage stratégique.\r\n          </p>\r\n          <span class=\"case-link\">Lire l\'étude →</span>\r\n        </div>\r\n        <div class=\"case-card\">\r\n          <span class=\"case-tag\">Services</span>\r\n          <h3 class=\"case-title\">Transformation digitale</h3>\r\n          <p class=\"case-desc\">\r\n            Accompagnement d\'un groupe de conseil dans sa digitalisation interne et l\'optimisation de son modèle de delivery.\r\n          </p>\r\n          <span class=\"case-link\">Lire l\'étude →</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- CHIFFRES CLÉS -->\r\n    <div class=\"cons-figures\">\r\n      <div class=\"figures-wrapper\">\r\n        <div class=\"figure-block\">\r\n          <div class=\"figure-number\">+150</div>\r\n          <div class=\"figure-label\">missions réalisées</div>\r\n        </div>\r\n        <div class=\"figure-block\">\r\n          <div class=\"figure-number\">85%</div>\r\n          <div class=\"figure-label\">clients récurrents</div>\r\n        </div>\r\n        <div class=\"figure-block\">\r\n          <div class=\"figure-number\">16</div>\r\n          <div class=\"figure-label\">consultants seniors</div>\r\n        </div>\r\n        <div class=\"figure-block\">\r\n          <div class=\"figure-number\">4,8/5</div>\r\n          <div class=\"figure-label\">satisfaction client</div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- BANDEAU PRISE DE CONTACT -->\r\n    <div class=\"cons-contact-cta\">\r\n      <div class=\"contact-left\">\r\n        <h3>Un défi stratégique ?</h3>\r\n        <p>Parlons de vos enjeux. Première rencontre sans engagement.</p>\r\n      </div>\r\n      <button class=\"contact-btn\">Nous contacter →</button>\r\n    </div>\r\n\r\n    <!-- FOOTER CABINET CONSEIL -->\r\n    <footer class=\"cons-footer\">\r\n      <div class=\"footer-main\">\r\n        <div class=\"footer-about\">\r\n          <div class=\"footer-logo\">Axis.Conseil</div>\r\n          <p>Cabinet de conseil en stratégie et management, indépendant et engagé auprès de ses clients depuis 2008.</p>\r\n          <div class=\"social-links\">\r\n            <span>📘</span>\r\n            <span>📷</span>\r\n            <span>🐦</span>\r\n            <span>🔗</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Expertises</span>\r\n          <a href=\"#\">Stratégie</a>\r\n          <a href=\"#\">Performance</a>\r\n          <a href=\"#\">Management</a>\r\n          <a href=\"#\">Digital</a>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Ressources</span>\r\n          <a href=\"#\">Publications</a>\r\n          <a href=\"#\">Études de cas</a>\r\n          <a href=\"#\">Newsletter</a>\r\n          <a href=\"#\">Carrières</a>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Contact</span>\r\n          <a href=\"#\">Paris</a>\r\n          <a href=\"#\">Lyon</a>\r\n          <a href=\"#\">contact@axis-conseil.fr</a>\r\n          <a href=\"#\">01 42 68 12 34</a>\r\n        </div>\r\n      </div>\r\n      <div class=\"footer-bottom\">\r\n        <span>© 2026 Axis.Conseil. Tous droits réservés.</span>\r\n        <span style=\"display: flex; gap: 28px;\">\r\n          <span>Mentions légales</span>\r\n          <span>Confidentialité</span>\r\n        </span>\r\n      </div>\r\n    </footer>\r\n  </section>\r\n</body>', '/* ===== STYLE CABINET DE CONSEIL - EXPERTISE & CONFIANCE ===== */\r\n    /* Design premium, épuré, typographie élégante */\r\n    .consulting-section {\r\n      font-family: \'Inter\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, \'Helvetica Neue\', sans-serif;\r\n      max-width: 1440px;\r\n      margin: 0 auto;\r\n      background: #ffffff;\r\n      color: #1a2e3b;\r\n      position: relative;\r\n    }\r\n\r\n    /* HEADER - SIGNATURE VISUELLE */\r\n    .cons-header {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      padding: 20px 60px;\r\n      background: white;\r\n      border-bottom: 1px solid #f0f3f7;\r\n      flex-wrap: wrap;\r\n    }\r\n\r\n    .cons-logo {\r\n      display: flex;\r\n      align-items: baseline;\r\n      gap: 6px;\r\n    }\r\n\r\n    .cons-logo-symbol {\r\n      font-size: 32px;\r\n      font-weight: 700;\r\n      color: #0f4c5c;\r\n      background: #eaf2f4;\r\n      padding: 8px 14px;\r\n      border-radius: 12px;\r\n      letter-spacing: -1px;\r\n    }\r\n\r\n    .cons-logo-text {\r\n      font-size: 26px;\r\n      font-weight: 600;\r\n      color: #173e4a;\r\n      margin-left: 8px;\r\n    }\r\n\r\n    .cons-logo-dot {\r\n      color: #c17b4b;\r\n      font-size: 32px;\r\n    }\r\n\r\n    .cons-nav {\r\n      display: flex;\r\n      gap: 42px;\r\n      font-weight: 500;\r\n    }\r\n\r\n    .cons-nav a {\r\n      text-decoration: none;\r\n      color: #2b4853;\r\n      font-size: 16px;\r\n      transition: 0.2s;\r\n    }\r\n\r\n    .cons-nav a:hover {\r\n      color: #b45a3b;\r\n    }\r\n\r\n    .cons-cta {\r\n      background: #0f4c5c;\r\n      color: white;\r\n      padding: 12px 32px;\r\n      border-radius: 40px;\r\n      font-weight: 600;\r\n      font-size: 15px;\r\n      border: none;\r\n      box-shadow: 0 8px 18px -8px rgba(15, 76, 92, 0.3);\r\n      transition: 0.2s;\r\n    }\r\n\r\n    /* HERO - IMPACT CONSEIL */\r\n    .cons-hero {\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 40px;\r\n      padding: 60px 60px 80px;\r\n      background: linear-gradient(145deg, #fbfdfe, #f6fafc);\r\n      position: relative;\r\n    }\r\n\r\n    .cons-hero-left {\r\n      display: flex;\r\n      flex-direction: column;\r\n      justify-content: center;\r\n    }\r\n\r\n    .cons-hero-tag {\r\n      background: rgba(15, 76, 92, 0.08);\r\n      color: #0f4c5c;\r\n      padding: 8px 24px;\r\n      border-radius: 40px;\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 10px;\r\n      font-weight: 600;\r\n      font-size: 14px;\r\n      margin-bottom: 24px;\r\n      width: fit-content;\r\n      border: 1px solid rgba(15, 76, 92, 0.1);\r\n    }\r\n\r\n    .cons-hero-title {\r\n      font-size: 54px;\r\n      font-weight: 700;\r\n      line-height: 1.1;\r\n      margin: 0 0 24px 0;\r\n      color: #0d2f38;\r\n      letter-spacing: -1.5px;\r\n    }\r\n\r\n    .cons-hero-accent {\r\n      color: #b45a3b;\r\n      border-bottom: 3px solid rgba(180, 90, 59, 0.15);\r\n    }\r\n\r\n    .cons-hero-desc {\r\n      font-size: 18px;\r\n      line-height: 1.7;\r\n      color: #3a5f6b;\r\n      margin-bottom: 36px;\r\n      max-width: 90%;\r\n    }\r\n\r\n    .cons-hero-btns {\r\n      display: flex;\r\n      gap: 20px;\r\n    }\r\n\r\n    .btn-primary {\r\n      background: #0f4c5c;\r\n      color: white;\r\n      padding: 16px 38px;\r\n      border-radius: 50px;\r\n      font-weight: 600;\r\n      font-size: 17px;\r\n      border: none;\r\n      box-shadow: 0 12px 22px -12px rgba(15, 76, 92, 0.35);\r\n    }\r\n\r\n    .btn-outline {\r\n      background: transparent;\r\n      border: 1.5px solid #0f4c5c;\r\n      color: #0f4c5c;\r\n      padding: 16px 38px;\r\n      border-radius: 50px;\r\n      font-weight: 600;\r\n      font-size: 17px;\r\n    }\r\n\r\n    .cons-hero-right {\r\n      background: white;\r\n      border-radius: 40px;\r\n      padding: 40px 38px;\r\n      box-shadow: 0 30px 50px -30px rgba(0,60,70,0.06);\r\n      border: 1px solid #ecf3f5;\r\n      display: flex;\r\n      flex-direction: column;\r\n      justify-content: center;\r\n    }\r\n\r\n    .cons-testimonial {\r\n      font-size: 20px;\r\n      line-height: 1.6;\r\n      color: #1c424e;\r\n      font-weight: 500;\r\n      margin-bottom: 32px;\r\n      font-style: italic;\r\n    }\r\n\r\n    .cons-client {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .cons-client-avatar {\r\n      width: 60px;\r\n      height: 60px;\r\n      background: #eef2f4;\r\n      border-radius: 18px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      font-size: 26px;\r\n      color: #0f4c5c;\r\n    }\r\n\r\n    /* SECTION EXPERTISES */\r\n    .cons-expertises {\r\n      padding: 80px 60px;\r\n      background: white;\r\n    }\r\n\r\n    .section-header {\r\n      display: flex;\r\n      flex-direction: column;\r\n      align-items: center;\r\n      text-align: center;\r\n      max-width: 700px;\r\n      margin: 0 auto 60px;\r\n    }\r\n\r\n    .section-surtitle {\r\n      font-size: 14px;\r\n      text-transform: uppercase;\r\n      letter-spacing: 4px;\r\n      color: #b45a3b;\r\n      font-weight: 600;\r\n      margin-bottom: 18px;\r\n    }\r\n\r\n    .section-title {\r\n      font-size: 42px;\r\n      font-weight: 700;\r\n      margin: 0 0 22px 0;\r\n      color: #0d2f38;\r\n      letter-spacing: -1px;\r\n    }\r\n\r\n    .section-desc {\r\n      font-size: 18px;\r\n      color: #4c6d78;\r\n      line-height: 1.6;\r\n    }\r\n\r\n    .expertises-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 32px;\r\n      margin-top: 20px;\r\n    }\r\n\r\n    .expertise-card {\r\n      background: #ffffff;\r\n      border-radius: 32px;\r\n      padding: 38px 32px;\r\n      border: 1px solid #ecf3f6;\r\n      transition: all 0.25s ease;\r\n    }\r\n\r\n    .expertise-card:hover {\r\n      border-color: #c9a287;\r\n      box-shadow: 0 25px 40px -22px rgba(15, 76, 92, 0.08);\r\n      transform: translateY(-6px);\r\n    }\r\n\r\n    .expertise-icon {\r\n      font-size: 48px;\r\n      margin-bottom: 28px;\r\n      background: #f5fafb;\r\n      width: 80px;\r\n      height: 80px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      border-radius: 24px;\r\n      color: #0f4c5c;\r\n    }\r\n\r\n    .expertise-name {\r\n      font-size: 24px;\r\n      font-weight: 700;\r\n      margin: 0 0 16px 0;\r\n      color: #173e4a;\r\n    }\r\n\r\n    .expertise-desc {\r\n      font-size: 16px;\r\n      line-height: 1.7;\r\n      color: #4a6e7a;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .expertise-link {\r\n      color: #b45a3b;\r\n      font-weight: 600;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 8px;\r\n    }\r\n\r\n    /* SECTION MÉTHODOLOGIE */\r\n    .cons-methodology {\r\n      background: #f8fbfc;\r\n      padding: 80px 60px;\r\n    }\r\n\r\n    .methodology-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 30px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .methodology-step {\r\n      text-align: center;\r\n      padding: 32px 24px;\r\n      background: white;\r\n      border-radius: 32px;\r\n      border: 1px solid #e8f0f2;\r\n    }\r\n\r\n    .step-number {\r\n      font-size: 42px;\r\n      font-weight: 800;\r\n      color: rgba(180, 90, 59, 0.2);\r\n      line-height: 1;\r\n      margin-bottom: 18px;\r\n    }\r\n\r\n    .step-title {\r\n      font-size: 22px;\r\n      font-weight: 700;\r\n      margin: 0 0 16px 0;\r\n      color: #0f4c5c;\r\n    }\r\n\r\n    .step-desc {\r\n      font-size: 15px;\r\n      color: #4b6e79;\r\n      line-height: 1.6;\r\n    }\r\n\r\n    /* SECTION ÉQUIPE - ASSOCIÉS */\r\n    .cons-team {\r\n      padding: 80px 60px;\r\n      background: white;\r\n    }\r\n\r\n    .team-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 36px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .team-card {\r\n      background: white;\r\n      border-radius: 32px;\r\n      padding: 36px 32px;\r\n      border: 1px solid #ecf3f6;\r\n      transition: 0.2s;\r\n      text-align: center;\r\n    }\r\n\r\n    .team-card:hover {\r\n      border-color: #bfaa9a;\r\n      box-shadow: 0 30px 45px -28px rgba(15,76,92,0.08);\r\n    }\r\n\r\n    .team-avatar {\r\n      width: 120px;\r\n      height: 120px;\r\n      background: linear-gradient(145deg, #e4edf0, #d3e1e6);\r\n      border-radius: 32px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      font-size: 52px;\r\n      margin: 0 auto 26px;\r\n      color: #0f4c5c;\r\n    }\r\n\r\n    .team-name {\r\n      font-size: 24px;\r\n      font-weight: 700;\r\n      margin: 0 0 8px 0;\r\n      color: #173e4a;\r\n    }\r\n\r\n    .team-role {\r\n      font-size: 16px;\r\n      color: #b45a3b;\r\n      font-weight: 600;\r\n      margin-bottom: 20px;\r\n    }\r\n\r\n    .team-bio {\r\n      font-size: 15px;\r\n      color: #4a6e7a;\r\n      line-height: 1.7;\r\n    }\r\n\r\n    /* SECTION ÉTUDES DE CAS */\r\n    .cons-cases {\r\n      background: #f8fbfc;\r\n      padding: 80px 60px;\r\n    }\r\n\r\n    .cases-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(2, 1fr);\r\n      gap: 32px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .case-card {\r\n      background: white;\r\n      border-radius: 32px;\r\n      padding: 36px;\r\n      border: 1px solid #e6eff2;\r\n      display: flex;\r\n      flex-direction: column;\r\n    }\r\n\r\n    .case-tag {\r\n      background: rgba(15, 76, 92, 0.08);\r\n      color: #0f4c5c;\r\n      padding: 6px 20px;\r\n      border-radius: 40px;\r\n      font-size: 13px;\r\n      font-weight: 600;\r\n      align-self: flex-start;\r\n      margin-bottom: 20px;\r\n    }\r\n\r\n    .case-title {\r\n      font-size: 26px;\r\n      font-weight: 700;\r\n      margin: 0 0 18px 0;\r\n      color: #0d2f38;\r\n    }\r\n\r\n    .case-desc {\r\n      font-size: 16px;\r\n      color: #4b6e79;\r\n      line-height: 1.7;\r\n      margin-bottom: 24px;\r\n      flex: 1;\r\n    }\r\n\r\n    .case-link {\r\n      color: #b45a3b;\r\n      font-weight: 700;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 10px;\r\n    }\r\n\r\n    /* SECTION CHIFFRES */\r\n    .cons-figures {\r\n      padding: 60px 60px 70px;\r\n      background: white;\r\n    }\r\n\r\n    .figures-wrapper {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 30px;\r\n      background: linear-gradient(145deg, #f1f8fa, #e9f2f5);\r\n      border-radius: 60px;\r\n      padding: 60px 40px;\r\n    }\r\n\r\n    .figure-block {\r\n      text-align: center;\r\n    }\r\n\r\n    .figure-number {\r\n      font-size: 52px;\r\n      font-weight: 800;\r\n      color: #0f4c5c;\r\n      margin-bottom: 12px;\r\n    }\r\n\r\n    .figure-label {\r\n      font-size: 17px;\r\n      color: #2e5a66;\r\n      font-weight: 500;\r\n    }\r\n\r\n    /* BANDEAU CONTACT */\r\n    .cons-contact-cta {\r\n      background: linear-gradient(145deg, #0f4c5c, #0a3a46);\r\n      border-radius: 48px;\r\n      margin: 40px 60px 60px;\r\n      padding: 56px 70px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      flex-wrap: wrap;\r\n      color: white;\r\n    }\r\n\r\n    .contact-left h3 {\r\n      font-size: 36px;\r\n      font-weight: 700;\r\n      margin: 0 0 16px 0;\r\n      color: white;\r\n      letter-spacing: -1px;\r\n    }\r\n\r\n    .contact-left p {\r\n      font-size: 18px;\r\n      color: rgba(255,255,255,0.85);\r\n      margin: 0;\r\n    }\r\n\r\n    .contact-btn {\r\n      background: white;\r\n      color: #0f4c5c;\r\n      padding: 18px 52px;\r\n      border-radius: 60px;\r\n      font-weight: 700;\r\n      font-size: 18px;\r\n      border: none;\r\n      box-shadow: 0 18px 32px -12px rgba(0,0,0,0.18);\r\n    }\r\n\r\n    /* FOOTER CABINET */\r\n    .cons-footer {\r\n      background: #0d2f38;\r\n      color: white;\r\n      padding: 60px 60px 30px;\r\n    }\r\n\r\n    .footer-main {\r\n      display: grid;\r\n      grid-template-columns: 2fr 1fr 1fr 1fr;\r\n      gap: 50px;\r\n      margin-bottom: 50px;\r\n    }\r\n\r\n    .footer-logo {\r\n      font-size: 28px;\r\n      font-weight: 700;\r\n      color: white;\r\n      margin-bottom: 20px;\r\n    }\r\n\r\n    .footer-about p {\r\n      color: rgba(255,255,255,0.6);\r\n      line-height: 1.7;\r\n    }\r\n\r\n    .footer-links {\r\n      display: flex;\r\n      flex-direction: column;\r\n      gap: 16px;\r\n    }\r\n\r\n    .footer-links a {\r\n      text-decoration: none;\r\n      color: rgba(255,255,255,0.6);\r\n      font-size: 15px;\r\n    }\r\n\r\n    .footer-title {\r\n      font-weight: 700;\r\n      color: white;\r\n      margin-bottom: 12px;\r\n      font-size: 18px;\r\n    }\r\n\r\n    .footer-bottom {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      padding-top: 30px;\r\n      border-top: 1px solid rgba(255,255,255,0.1);\r\n      color: rgba(255,255,255,0.5);\r\n    }\r\n\r\n    .social-links {\r\n      display: flex;\r\n      gap: 28px;\r\n      font-size: 22px;\r\n    }\r\n\r\n    /* RESPONSIVE */\r\n    @media (max-width: 1100px) {\r\n      .expertises-grid,\r\n      .team-grid,\r\n      .figures-wrapper {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n      .methodology-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n    }\r\n\r\n    @media (max-width: 900px) {\r\n      .cons-hero {\r\n        grid-template-columns: 1fr;\r\n      }\r\n      .cases-grid {\r\n        grid-template-columns: 1fr;\r\n      }\r\n      .cons-header {\r\n        flex-direction: column;\r\n        gap: 20px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 700px) {\r\n      .expertises-grid,\r\n      .team-grid,\r\n      .methodology-grid,\r\n      .figures-wrapper,\r\n      .footer-main {\r\n        grid-template-columns: 1fr;\r\n      }\r\n      .cons-hero,\r\n      .cons-expertises,\r\n      .cons-methodology,\r\n      .cons-team,\r\n      .cons-cases {\r\n        padding: 40px 24px;\r\n      }\r\n    }\r\n\r\n    .gjs-draggable { cursor: move; }', NULL, NULL, NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL);
INSERT INTO `templates` (`id`, `categorie_id`, `name`, `url`, `description`, `html_content`, `css_content`, `js_content`, `assets_folder`, `assets_data`, `thumbnail`, `metadata`, `user_id`, `website_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(92, 3, 'Services Médicaux', NULL, NULL, '<body>\r\n  <!-- SERVICES MÉDICAUX - CABINET & SOINS -->\r\n  <section class=\"medical-section\">\r\n\r\n    <!-- HEADER MÉDICAL -->\r\n    <header class=\"med-header\">\r\n      <div class=\"med-logo\">\r\n        <span class=\"med-logo-icon\">⚕️</span>\r\n        <span class=\"med-logo-text\">Centre<span>Médical</span></span>\r\n      </div>\r\n      <nav class=\"med-nav\">\r\n        <a href=\"#\">Spécialités</a>\r\n        <a href=\"#\">Équipe</a>\r\n        <a href=\"#\">Services</a>\r\n        <a href=\"#\">RDV</a>\r\n        <a href=\"#\">Contact</a>\r\n      </nav>\r\n      <div class=\"med-actions\">\r\n        <span class=\"med-urgent\">\r\n          <span>🚨</span> Urgences 24/7\r\n        </span>\r\n        <button class=\"med-rdv-btn\">Prendre RDV</button>\r\n      </div>\r\n    </header>\r\n\r\n    <!-- HERO MÉDICAL -->\r\n    <div class=\"med-hero\">\r\n      <div class=\"med-hero-left\">\r\n        <span class=\"med-hero-tag\">\r\n          <span>🩺</span> Centre de santé pluridisciplinaire\r\n        </span>\r\n        <h1 class=\"med-hero-title\">\r\n          Votre santé, <span class=\"med-hero-accent\">notre engagement</span>\r\n        </h1>\r\n        <p class=\"med-hero-desc\">\r\n          Médecine générale, spécialistes, examens et suivi personnalisé. \r\n          Un accompagnement bienveillant pour toute la famille.\r\n        </p>\r\n        <div class=\"med-hero-btns\">\r\n          <button class=\"btn-primary\">Prendre rendez-vous →</button>\r\n          <button class=\"btn-outline\">Nos spécialistes</button>\r\n        </div>\r\n      </div>\r\n      <div class=\"med-hero-right\">\r\n        <div class=\"med-opening\">\r\n          <div class=\"med-opening-item\">\r\n            <span class=\"med-opening-icon\">🕒</span>\r\n            <div>\r\n              <div style=\"font-weight: 700; color: #1a4c4f;\">Horaires d\'ouverture</div>\r\n              <div style=\"color: #4b7276;\">Lun-Ven: 8h-20h • Sam: 9h-17h</div>\r\n            </div>\r\n          </div>\r\n          <div class=\"med-opening-item\">\r\n            <span class=\"med-opening-icon\">📍</span>\r\n            <div>\r\n              <div style=\"font-weight: 700; color: #1a4c4f;\">Notre adresse</div>\r\n              <div style=\"color: #4b7276;\">12 rue de la Santé, 75010 Paris</div>\r\n            </div>\r\n          </div>\r\n          <div class=\"med-opening-item\">\r\n            <span class=\"med-opening-icon\">📞</span>\r\n            <div>\r\n              <div style=\"font-weight: 700; color: #1a4c4f;\">Prise de RDV</div>\r\n              <div style=\"color: #4b7276;\">01 42 68 12 34</div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- SPÉCIALITÉS MÉDICALES -->\r\n    <div class=\"med-specialties\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-surtitle\">NOS SPÉCIALITÉS</div>\r\n        <h2 class=\"section-title\">Une prise en charge complète</h2>\r\n        <p class=\"section-desc\">\r\n          Plus de 15 spécialités médicales pour répondre à tous vos besoins de santé.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"specialties-grid\">\r\n        <div class=\"specialty-card\">\r\n          <div class=\"specialty-icon\">🫀</div>\r\n          <h3 class=\"specialty-name\">Cardiologie</h3>\r\n          <p class=\"specialty-desc\">Consultations, échographies, épreuves d\'effort et suivi cardiologique.</p>\r\n          <span class=\"specialty-link\">En savoir +</span>\r\n        </div>\r\n        <div class=\"specialty-card\">\r\n          <div class=\"specialty-icon\">🦷</div>\r\n          <h3 class=\"specialty-name\">Dentaire</h3>\r\n          <p class=\"specialty-desc\">Soins, prothèses, implantologie et orthodontie pour tous les âges.</p>\r\n          <span class=\"specialty-link\">En savoir +</span>\r\n        </div>\r\n        <div class=\"specialty-card\">\r\n          <div class=\"specialty-icon\">👁️</div>\r\n          <h3 class=\"specialty-name\">Ophtalmologie</h3>\r\n          <p class=\"specialty-desc\">Consultations, dépistage, pathologies oculaires et chirurgie.</p>\r\n          <span class=\"specialty-link\">En savoir +</span>\r\n        </div>\r\n        <div class=\"specialty-card\">\r\n          <div class=\"specialty-icon\">🤰</div>\r\n          <h3 class=\"specialty-name\">Gynécologie</h3>\r\n          <p class=\"specialty-desc\">Suivi gynécologique, grossesse, contraception et ménopause.</p>\r\n          <span class=\"specialty-link\">En savoir +</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- ÉQUIPE MÉDICALE -->\r\n    <div class=\"med-team\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-surtitle\">NOTRE ÉQUIPE</div>\r\n        <h2 class=\"section-title\">Des professionnels à votre écoute</h2>\r\n        <p class=\"section-desc\">\r\n          Médecins, chirurgiens et paramédicaux engagés pour votre bien-être.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"team-grid\">\r\n        <div class=\"team-card\">\r\n          <div class=\"team-avatar\">👩‍⚕️</div>\r\n          <h3 class=\"team-name\">Dr. Sophie Martin</h3>\r\n          <div class=\"team-specialty\">Médecine générale</div>\r\n          <p class=\"team-bio\">15 ans d\'expérience, approche holistique et prévention.</p>\r\n        </div>\r\n        <div class=\"team-card\">\r\n          <div class=\"team-avatar\">👨‍⚕️</div>\r\n          <h3 class=\"team-name\">Dr. Thomas Bernard</h3>\r\n          <div class=\"team-specialty\">Cardiologue</div>\r\n          <p class=\"team-bio\">Ancien chef de clinique, spécialiste des pathologies cardiaques.</p>\r\n        </div>\r\n        <div class=\"team-card\">\r\n          <div class=\"team-avatar\">👩‍⚕️</div>\r\n          <h3 class=\"team-name\">Dr. Amélie Petit</h3>\r\n          <div class=\"team-specialty\">Gynécologue</div>\r\n          <p class=\"team-bio\">Suivi personnalisé, chirurgie gynécologique et obstétrique.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- SERVICES & SOINS -->\r\n    <div class=\"med-services\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-surtitle\">NOS SERVICES</div>\r\n        <h2 class=\"section-title\">Des soins accessibles</h2>\r\n        <p class=\"section-desc\">\r\n          Consultations, examens et soins sans dépassement d\'honoraires.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"services-grid\">\r\n        <div class=\"service-card\">\r\n          <span class=\"service-icon\">🩺</span>\r\n          <h3 class=\"service-title\">Consultation générale</h3>\r\n          <div class=\"service-features\">\r\n            <span class=\"service-feature\">✓ Médecine générale</span>\r\n            <span class=\"service-feature\">✓ Suivi chronique</span>\r\n            <span class=\"service-feature\">✓ Prévention</span>\r\n          </div>\r\n          <div class=\"service-price\">25€ (Sécurité sociale + mutuelle)</div>\r\n        </div>\r\n        <div class=\"service-card\">\r\n          <span class=\"service-icon\">🩻</span>\r\n          <h3 class=\"service-title\">Imagerie médicale</h3>\r\n          <div class=\"service-features\">\r\n            <span class=\"service-feature\">✓ Radiologie</span>\r\n            <span class=\"service-feature\">✓ Échographie</span>\r\n            <span class=\"service-feature\">✓ Mammographie</span>\r\n          </div>\r\n          <div class=\"service-price\">Sur rendez-vous</div>\r\n        </div>\r\n        <div class=\"service-card\">\r\n          <span class=\"service-icon\">💉</span>\r\n          <h3 class=\"service-title\">Analyses & dépistages</h3>\r\n          <div class=\"service-features\">\r\n            <span class=\"service-feature\">✓ Prise de sang</span>\r\n            <span class=\"service-feature\">✓ Dépistages</span>\r\n            <span class=\"service-feature\">✓ Vaccinations</span>\r\n          </div>\r\n          <div class=\"service-price\">Sans RDV</div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- TÉMOIGNAGES PATIENTS -->\r\n    <div class=\"med-testimonials\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-surtitle\">AVIS PATIENTS</div>\r\n        <h2 class=\"section-title\">Ils nous ont fait confiance</h2>\r\n        <p class=\"section-desc\">\r\n          Votre satisfaction est notre priorité.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"testimonials-grid\">\r\n        <div class=\"testimonial-card\">\r\n          <div class=\"testimonial-rating\">★★★★★</div>\r\n          <p class=\"testimonial-text\">\"Accueil chaleureux, délais de rendez-vous très raisonnables. Le Dr. Martin est à l\'écoute et prend le temps d\'expliquer.\"</p>\r\n          <div class=\"testimonial-author\">\r\n            <div class=\"testimonial-avatar\">M</div>\r\n            <div>\r\n              <div style=\"font-weight: 700; color: #1a4c4f;\">Marie L.</div>\r\n              <div style=\"font-size: 13px; color: #4b7276;\">Patiente depuis 5 ans</div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"testimonial-card\">\r\n          <div class=\"testimonial-rating\">★★★★★</div>\r\n          <p class=\"testimonial-text\">\"Service de cardiologie très professionnel. Examen complet et suivi personnalisé. Je recommande vivement.\"</p>\r\n          <div class=\"testimonial-author\">\r\n            <div class=\"testimonial-avatar\">P</div>\r\n            <div>\r\n              <div style=\"font-weight: 700; color: #1a4c4f;\">Philippe D.</div>\r\n              <div style=\"font-size: 13px; color: #4b7276;\">Patient</div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"testimonial-card\">\r\n          <div class=\"testimonial-rating\">★★★★☆</div>\r\n          <p class=\"testimonial-text\">\"Prise de RDV en ligne très pratique. Équipe dentaire compétente et douce avec les enfants.\"</p>\r\n          <div class=\"testimonial-author\">\r\n            <div class=\"testimonial-avatar\">S</div>\r\n            <div>\r\n              <div style=\"font-weight: 700; color: #1a4c4f;\">Sophie R.</div>\r\n              <div style=\"font-size: 13px; color: #4b7276;\">Maman de 2 enfants</div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- CHIFFRES CLÉS -->\r\n    <div class=\"med-figures\">\r\n      <div class=\"figures-container\">\r\n        <div class=\"figure-item\">\r\n          <div class=\"figure-number\">+25k</div>\r\n          <div class=\"figure-label\">patients par an</div>\r\n        </div>\r\n        <div class=\"figure-item\">\r\n          <div class=\"figure-number\">15</div>\r\n          <div class=\"figure-label\">spécialités</div>\r\n        </div>\r\n        <div class=\"figure-item\">\r\n          <div class=\"figure-number\">8</div>\r\n          <div class=\"figure-label\">médecins</div>\r\n        </div>\r\n        <div class=\"figure-item\">\r\n          <div class=\"figure-number\">4.8</div>\r\n          <div class=\"figure-label\">note moyenne</div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- BANDEAU URGENCE -->\r\n    <div class=\"med-emergency\">\r\n      <div class=\"emergency-left\">\r\n        <span class=\"emergency-icon\">🚨</span>\r\n        <div class=\"emergency-text\">\r\n          <h4>Urgence médicale ?</h4>\r\n          <p>Notre ligne d\'urgence est joignable 24h/24 et 7j/7</p>\r\n        </div>\r\n      </div>\r\n      <span class=\"emergency-phone\">\r\n        <span>📞</span> 01 42 68 12 34\r\n      </span>\r\n    </div>\r\n\r\n    <!-- PRISE DE RENDEZ-VOUS -->\r\n    <div class=\"med-appointment\">\r\n      <div class=\"appointment-container\">\r\n        <div class=\"appointment-left\">\r\n          <h3>Prenez rendez-vous en ligne</h3>\r\n          <p>Consultations disponibles sous 48h en moyenne. Annulation possible sans frais jusqu\'à 24h avant.</p>\r\n          <div class=\"appointment-methods\">\r\n            <div class=\"method-item\">\r\n              <span class=\"method-icon\">📅</span>\r\n              <div>\r\n                <div style=\"font-weight: 700; color: #1a4c4f;\">RDV en ligne</div>\r\n                <div style=\"color: #4b7276;\">7j/7, 24h/24</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"method-item\">\r\n              <span class=\"method-icon\">📞</span>\r\n              <div>\r\n                <div style=\"font-weight: 700; color: #1a4c4f;\">Par téléphone</div>\r\n                <div style=\"color: #4b7276;\">Lun-Ven: 8h-20h</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"method-item\">\r\n              <span class=\"method-icon\">🏥</span>\r\n              <div>\r\n                <div style=\"font-weight: 700; color: #1a4c4f;\">Sur place</div>\r\n                <div style=\"color: #4b7276;\">Accueil sans RDV selon disponibilités</div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"appointment-right\">\r\n          <div class=\"appointment-form\">\r\n            <div class=\"form-group\">\r\n              <span class=\"form-label\">Spécialité</span>\r\n              <select class=\"form-input\">\r\n                <option>Médecine générale</option>\r\n                <option>Cardiologie</option>\r\n                <option>Dentaire</option>\r\n                <option>Ophtalmologie</option>\r\n                <option>Gynécologie</option>\r\n              </select>\r\n            </div>\r\n            <div class=\"form-group\">\r\n              <span class=\"form-label\">Date souhaitée</span>\r\n              <input type=\"text\" class=\"form-input\" placeholder=\"JJ/MM/AAAA\" value=\"15/03/2026\">\r\n            </div>\r\n            <div class=\"form-group\">\r\n              <span class=\"form-label\">Nom et prénom</span>\r\n              <input type=\"text\" class=\"form-input\" placeholder=\"Votre nom\">\r\n            </div>\r\n            <button class=\"form-submit\">Rechercher un créneau</button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- FOOTER MÉDICAL -->\r\n    <footer class=\"med-footer\">\r\n      <div class=\"footer-main\">\r\n        <div class=\"footer-about\">\r\n          <div class=\"footer-logo\">CentreMédical</div>\r\n          <p>Établissement de santé conventionné, accessible et engagé pour une médecine de qualité pour tous.</p>\r\n          <div style=\"display: flex; gap: 24px; font-size: 24px; margin-top: 24px;\">\r\n            <span style=\"color: rgba(255,255,255,0.6);\">📘</span>\r\n            <span style=\"color: rgba(255,255,255,0.6);\">📷</span>\r\n            <span style=\"color: rgba(255,255,255,0.6);\">🐦</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Spécialités</span>\r\n          <a href=\"#\">Cardiologie</a>\r\n          <a href=\"#\">Dentaire</a>\r\n          <a href=\"#\">Ophtalmologie</a>\r\n          <a href=\"#\">Gynécologie</a>\r\n          <a href=\"#\">Pédiatrie</a>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Infos pratiques</span>\r\n          <a href=\"#\">Horaires</a>\r\n          <a href=\"#\">Accès</a>\r\n          <a href=\"#\">Prise de RDV</a>\r\n          <a href=\"#\">Téléconsultation</a>\r\n          <a href=\"#\">Tarifs</a>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Contact</span>\r\n          <a href=\"#\">12 rue de la Santé, 75010 Paris</a>\r\n          <a href=\"#\">01 42 68 12 34</a>\r\n          <a href=\"#\">contact@centremedical.fr</a>\r\n          <a href=\"#\">Urgences: 01 42 68 12 34</a>\r\n        </div>\r\n      </div>\r\n      <div class=\"footer-bottom\">\r\n        <span>© 2026 CentreMédical - Tous droits réservés</span>\r\n        <span style=\"display: flex; gap: 28px;\">\r\n          <span>Mentions légales</span>\r\n          <span>Confidentialité</span>\r\n          <span>CGU</span>\r\n        </span>\r\n      </div>\r\n    </footer>\r\n  </section>\r\n</body>', ' /* ===== STYLE SERVICES MÉDICAUX - CONFIANCE & BIEN-ÊTRE ===== */\r\n    /* Design apaisant, professionnel, rassurant */\r\n    .medical-section {\r\n      font-family: \'Inter\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, \'Helvetica Neue\', sans-serif;\r\n      max-width: 1440px;\r\n      margin: 0 auto;\r\n      background: #ffffff;\r\n      color: #1e3a3f;\r\n      position: relative;\r\n    }\r\n\r\n    /* HEADER MÉDICAL - SOBRE & RASSURANT */\r\n    .med-header {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      padding: 20px 60px;\r\n      background: white;\r\n      border-bottom: 1px solid #eef5f6;\r\n      flex-wrap: wrap;\r\n    }\r\n\r\n    .med-logo {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 14px;\r\n    }\r\n\r\n    .med-logo-icon {\r\n      font-size: 32px;\r\n      background: linear-gradient(145deg, #2c7a7b, #1e5f60);\r\n      color: white;\r\n      padding: 10px;\r\n      border-radius: 16px;\r\n    }\r\n\r\n    .med-logo-text {\r\n      font-size: 26px;\r\n      font-weight: 700;\r\n      color: #1e4a4d;\r\n      letter-spacing: -0.5px;\r\n    }\r\n\r\n    .med-logo-text span {\r\n      color: #2c7a7b;\r\n      font-weight: 300;\r\n    }\r\n\r\n    .med-nav {\r\n      display: flex;\r\n      gap: 42px;\r\n      font-weight: 500;\r\n    }\r\n\r\n    .med-nav a {\r\n      text-decoration: none;\r\n      color: #2c4e52;\r\n      font-size: 16px;\r\n      transition: 0.2s;\r\n    }\r\n\r\n    .med-nav a:hover {\r\n      color: #1e5f60;\r\n    }\r\n\r\n    .med-actions {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 24px;\r\n    }\r\n\r\n    .med-urgent {\r\n      background: #fff1e0;\r\n      color: #b34141;\r\n      padding: 10px 24px;\r\n      border-radius: 40px;\r\n      font-weight: 600;\r\n      font-size: 15px;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 10px;\r\n      border: 1px solid rgba(179, 65, 65, 0.1);\r\n    }\r\n\r\n    .med-rdv-btn {\r\n      background: #2c7a7b;\r\n      color: white;\r\n      padding: 12px 32px;\r\n      border-radius: 40px;\r\n      font-weight: 600;\r\n      font-size: 15px;\r\n      border: none;\r\n      box-shadow: 0 8px 18px -8px rgba(44, 122, 123, 0.4);\r\n    }\r\n\r\n    /* HERO MÉDICAL - APAI SANT */\r\n    .med-hero {\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 40px;\r\n      padding: 60px 60px 80px;\r\n      background: linear-gradient(145deg, #f6fbfc, #edf5f7);\r\n      position: relative;\r\n      overflow: hidden;\r\n    }\r\n\r\n    .med-hero::before {\r\n      content: \"⚕️\";\r\n      position: absolute;\r\n      bottom: -20px;\r\n      right: 40px;\r\n      font-size: 180px;\r\n      opacity: 0.03;\r\n      transform: rotate(10deg);\r\n    }\r\n\r\n    .med-hero-left {\r\n      display: flex;\r\n      flex-direction: column;\r\n      justify-content: center;\r\n    }\r\n\r\n    .med-hero-tag {\r\n      background: rgba(44, 122, 123, 0.1);\r\n      color: #1e5f60;\r\n      padding: 8px 24px;\r\n      border-radius: 40px;\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 10px;\r\n      font-weight: 600;\r\n      font-size: 15px;\r\n      margin-bottom: 28px;\r\n      width: fit-content;\r\n    }\r\n\r\n    .med-hero-title {\r\n      font-size: 54px;\r\n      font-weight: 700;\r\n      line-height: 1.1;\r\n      margin: 0 0 24px 0;\r\n      color: #0f3b3d;\r\n      letter-spacing: -1.5px;\r\n    }\r\n\r\n    .med-hero-accent {\r\n      color: #1e5f60;\r\n      position: relative;\r\n      border-bottom: 4px solid rgba(44, 122, 123, 0.2);\r\n    }\r\n\r\n    .med-hero-desc {\r\n      font-size: 18px;\r\n      line-height: 1.7;\r\n      color: #3b676b;\r\n      margin-bottom: 36px;\r\n      max-width: 90%;\r\n    }\r\n\r\n    .med-hero-btns {\r\n      display: flex;\r\n      gap: 20px;\r\n      flex-wrap: wrap;\r\n    }\r\n\r\n    .btn-primary {\r\n      background: #2c7a7b;\r\n      color: white;\r\n      padding: 16px 38px;\r\n      border-radius: 50px;\r\n      font-weight: 600;\r\n      font-size: 17px;\r\n      border: none;\r\n      box-shadow: 0 12px 22px -12px rgba(44, 122, 123, 0.4);\r\n    }\r\n\r\n    .btn-outline {\r\n      background: transparent;\r\n      border: 1.5px solid #2c7a7b;\r\n      color: #1e5f60;\r\n      padding: 16px 38px;\r\n      border-radius: 50px;\r\n      font-weight: 600;\r\n      font-size: 17px;\r\n    }\r\n\r\n    .med-hero-right {\r\n      background: white;\r\n      border-radius: 40px;\r\n      padding: 36px;\r\n      box-shadow: 0 30px 50px -25px rgba(0,80,90,0.08);\r\n      border: 1px solid #e2f0f0;\r\n      display: flex;\r\n      flex-direction: column;\r\n      justify-content: center;\r\n    }\r\n\r\n    .med-opening {\r\n      display: flex;\r\n      flex-direction: column;\r\n      gap: 24px;\r\n    }\r\n\r\n    .med-opening-item {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 16px;\r\n      padding-bottom: 20px;\r\n      border-bottom: 1px dashed #d0e4e5;\r\n    }\r\n\r\n    .med-opening-item:last-child {\r\n      border-bottom: none;\r\n    }\r\n\r\n    .med-opening-icon {\r\n      width: 54px;\r\n      height: 54px;\r\n      background: #ebf6f6;\r\n      border-radius: 18px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      font-size: 26px;\r\n      color: #2c7a7b;\r\n    }\r\n\r\n    /* SECTION SPÉCIALITÉS MÉDICALES */\r\n    .med-specialties {\r\n      padding: 80px 60px;\r\n      background: white;\r\n    }\r\n\r\n    .section-header {\r\n      display: flex;\r\n      flex-direction: column;\r\n      align-items: center;\r\n      text-align: center;\r\n      max-width: 700px;\r\n      margin: 0 auto 60px;\r\n    }\r\n\r\n    .section-surtitle {\r\n      font-size: 14px;\r\n      text-transform: uppercase;\r\n      letter-spacing: 4px;\r\n      color: #2c7a7b;\r\n      font-weight: 600;\r\n      margin-bottom: 18px;\r\n    }\r\n\r\n    .section-title {\r\n      font-size: 42px;\r\n      font-weight: 700;\r\n      margin: 0 0 22px 0;\r\n      color: #0f3b3d;\r\n      letter-spacing: -1px;\r\n    }\r\n\r\n    .section-desc {\r\n      font-size: 18px;\r\n      color: #4c7376;\r\n      line-height: 1.6;\r\n    }\r\n\r\n    .specialties-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 28px;\r\n      margin-top: 20px;\r\n    }\r\n\r\n    .specialty-card {\r\n      background: #ffffff;\r\n      border-radius: 32px;\r\n      padding: 36px 28px;\r\n      border: 1px solid #eaf2f3;\r\n      transition: all 0.25s ease;\r\n      text-align: center;\r\n    }\r\n\r\n    .specialty-card:hover {\r\n      border-color: #8fc1c2;\r\n      box-shadow: 0 25px 40px -22px rgba(44, 122, 123, 0.1);\r\n      transform: translateY(-6px);\r\n    }\r\n\r\n    .specialty-icon {\r\n      font-size: 52px;\r\n      margin-bottom: 24px;\r\n      background: #f2f9fa;\r\n      width: 90px;\r\n      height: 90px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      border-radius: 26px;\r\n      margin: 0 auto 26px;\r\n      color: #2c7a7b;\r\n    }\r\n\r\n    .specialty-name {\r\n      font-size: 22px;\r\n      font-weight: 700;\r\n      margin: 0 0 14px 0;\r\n      color: #1a4c4f;\r\n    }\r\n\r\n    .specialty-desc {\r\n      font-size: 15px;\r\n      line-height: 1.6;\r\n      color: #4a7175;\r\n      margin-bottom: 20px;\r\n    }\r\n\r\n    .specialty-link {\r\n      color: #2c7a7b;\r\n      font-weight: 600;\r\n      font-size: 15px;\r\n    }\r\n\r\n    /* SECTION ÉQUIPE MÉDICALE */\r\n    .med-team {\r\n      background: #f5fbfc;\r\n      padding: 80px 60px;\r\n    }\r\n\r\n    .team-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 32px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .team-card {\r\n      background: white;\r\n      border-radius: 32px;\r\n      padding: 32px;\r\n      border: 1px solid #e0f0f0;\r\n      display: flex;\r\n      flex-direction: column;\r\n      align-items: center;\r\n      text-align: center;\r\n      transition: 0.2s;\r\n    }\r\n\r\n    .team-card:hover {\r\n      border-color: #9fc9ca;\r\n      box-shadow: 0 20px 35px -18px rgba(44,122,123,0.1);\r\n    }\r\n\r\n    .team-avatar {\r\n      width: 120px;\r\n      height: 120px;\r\n      background: linear-gradient(145deg, #d8ecec, #c4dfdf);\r\n      border-radius: 32px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      font-size: 52px;\r\n      margin-bottom: 24px;\r\n      color: #1e5f60;\r\n    }\r\n\r\n    .team-name {\r\n      font-size: 24px;\r\n      font-weight: 700;\r\n      margin: 0 0 6px 0;\r\n      color: #1a4c4f;\r\n    }\r\n\r\n    .team-specialty {\r\n      font-size: 16px;\r\n      color: #2c7a7b;\r\n      font-weight: 600;\r\n      margin-bottom: 16px;\r\n    }\r\n\r\n    .team-bio {\r\n      font-size: 15px;\r\n      color: #4b7276;\r\n      line-height: 1.6;\r\n    }\r\n\r\n    /* SECTION SERVICES & SOINS */\r\n    .med-services {\r\n      padding: 80px 60px;\r\n      background: white;\r\n    }\r\n\r\n    .services-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 32px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .service-card {\r\n      background: #f9fdfe;\r\n      border-radius: 32px;\r\n      padding: 36px;\r\n      border: 1px solid #e6f1f2;\r\n      display: flex;\r\n      flex-direction: column;\r\n    }\r\n\r\n    .service-icon {\r\n      font-size: 44px;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .service-title {\r\n      font-size: 24px;\r\n      font-weight: 700;\r\n      margin: 0 0 18px 0;\r\n      color: #1a4c4f;\r\n    }\r\n\r\n    .service-features {\r\n      display: flex;\r\n      flex-direction: column;\r\n      gap: 14px;\r\n      margin-bottom: 28px;\r\n    }\r\n\r\n    .service-feature {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 12px;\r\n      color: #3c6a6e;\r\n      font-size: 16px;\r\n    }\r\n\r\n    .service-price {\r\n      font-size: 20px;\r\n      font-weight: 700;\r\n      color: #1e5f60;\r\n      margin-top: auto;\r\n    }\r\n\r\n    /* SECTION TÉMOIGNAGES PATIENTS */\r\n    .med-testimonials {\r\n      background: #f5fbfc;\r\n      padding: 80px 60px;\r\n    }\r\n\r\n    .testimonials-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 30px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .testimonial-card {\r\n      background: white;\r\n      border-radius: 32px;\r\n      padding: 36px;\r\n      border: 1px solid #e2eff0;\r\n    }\r\n\r\n    .testimonial-rating {\r\n      color: #ffb347;\r\n      font-size: 20px;\r\n      margin-bottom: 22px;\r\n    }\r\n\r\n    .testimonial-text {\r\n      font-size: 17px;\r\n      line-height: 1.7;\r\n      color: #3b6468;\r\n      margin-bottom: 24px;\r\n      font-style: italic;\r\n    }\r\n\r\n    .testimonial-author {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .testimonial-avatar {\r\n      width: 56px;\r\n      height: 56px;\r\n      background: #e0eff0;\r\n      border-radius: 18px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      font-size: 24px;\r\n      color: #2c7a7b;\r\n    }\r\n\r\n    /* SECTION CHIFFRES CLÉS */\r\n    .med-figures {\r\n      padding: 60px 60px 70px;\r\n      background: white;\r\n    }\r\n\r\n    .figures-container {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 30px;\r\n      background: linear-gradient(145deg, #eef7f8, #e3f0f2);\r\n      border-radius: 60px;\r\n      padding: 60px 40px;\r\n    }\r\n\r\n    .figure-item {\r\n      text-align: center;\r\n    }\r\n\r\n    .figure-number {\r\n      font-size: 52px;\r\n      font-weight: 800;\r\n      color: #1e5f60;\r\n      margin-bottom: 12px;\r\n    }\r\n\r\n    .figure-label {\r\n      font-size: 17px;\r\n      color: #346b6f;\r\n      font-weight: 500;\r\n    }\r\n\r\n    /* SECTION PRISE DE RENDEZ-VOUS */\r\n    .med-appointment {\r\n      padding: 60px 60px 80px;\r\n      background: white;\r\n    }\r\n\r\n    .appointment-container {\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 50px;\r\n      background: linear-gradient(145deg, #f6fbfc, #ecf5f6);\r\n      border-radius: 48px;\r\n      padding: 56px 60px;\r\n    }\r\n\r\n    .appointment-left h3 {\r\n      font-size: 36px;\r\n      font-weight: 700;\r\n      margin: 0 0 20px 0;\r\n      color: #0f3b3d;\r\n      letter-spacing: -1px;\r\n    }\r\n\r\n    .appointment-left p {\r\n      font-size: 18px;\r\n      color: #3b676b;\r\n      line-height: 1.7;\r\n      margin-bottom: 32px;\r\n    }\r\n\r\n    .appointment-methods {\r\n      display: flex;\r\n      flex-direction: column;\r\n      gap: 20px;\r\n    }\r\n\r\n    .method-item {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .method-icon {\r\n      width: 48px;\r\n      height: 48px;\r\n      background: white;\r\n      border-radius: 16px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      font-size: 24px;\r\n      color: #2c7a7b;\r\n    }\r\n\r\n    .appointment-right {\r\n      background: white;\r\n      border-radius: 36px;\r\n      padding: 40px;\r\n      box-shadow: 0 20px 35px -15px rgba(0,0,0,0.02);\r\n    }\r\n\r\n    .appointment-form {\r\n      display: flex;\r\n      flex-direction: column;\r\n      gap: 20px;\r\n    }\r\n\r\n    .form-group {\r\n      display: flex;\r\n      flex-direction: column;\r\n      gap: 8px;\r\n    }\r\n\r\n    .form-label {\r\n      font-size: 15px;\r\n      font-weight: 600;\r\n      color: #1e5f60;\r\n    }\r\n\r\n    .form-input {\r\n      padding: 16px 22px;\r\n      border-radius: 30px;\r\n      border: 1px solid #d0e4e5;\r\n      font-size: 16px;\r\n      background: white;\r\n    }\r\n\r\n    .form-submit {\r\n      background: #2c7a7b;\r\n      color: white;\r\n      padding: 18px 32px;\r\n      border-radius: 50px;\r\n      font-weight: 700;\r\n      font-size: 17px;\r\n      border: none;\r\n      margin-top: 12px;\r\n    }\r\n\r\n    /* BANDEAU URGENCE */\r\n    .med-emergency {\r\n      background: #fff6f0;\r\n      border-radius: 32px;\r\n      margin: 20px 60px 40px;\r\n      padding: 32px 48px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      flex-wrap: wrap;\r\n      border: 1px solid #ffdbcc;\r\n    }\r\n\r\n    .emergency-left {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 20px;\r\n    }\r\n\r\n    .emergency-icon {\r\n      font-size: 48px;\r\n    }\r\n\r\n    .emergency-text h4 {\r\n      font-size: 24px;\r\n      font-weight: 700;\r\n      margin: 0 0 6px 0;\r\n      color: #b34141;\r\n    }\r\n\r\n    .emergency-text p {\r\n      font-size: 16px;\r\n      color: #6e4a3a;\r\n      margin: 0;\r\n    }\r\n\r\n    .emergency-phone {\r\n      background: #b34141;\r\n      color: white;\r\n      padding: 16px 42px;\r\n      border-radius: 50px;\r\n      font-weight: 700;\r\n      font-size: 20px;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 12px;\r\n    }\r\n\r\n    /* FOOTER MÉDICAL */\r\n    .med-footer {\r\n      background: #0f3b3d;\r\n      color: white;\r\n      padding: 60px 60px 30px;\r\n    }\r\n\r\n    .footer-main {\r\n      display: grid;\r\n      grid-template-columns: 2fr 1fr 1fr 1.5fr;\r\n      gap: 50px;\r\n      margin-bottom: 50px;\r\n    }\r\n\r\n    .footer-logo {\r\n      font-size: 28px;\r\n      font-weight: 700;\r\n      color: white;\r\n      margin-bottom: 20px;\r\n    }\r\n\r\n    .footer-about p {\r\n      color: rgba(255,255,255,0.6);\r\n      line-height: 1.7;\r\n    }\r\n\r\n    .footer-links {\r\n      display: flex;\r\n      flex-direction: column;\r\n      gap: 16px;\r\n    }\r\n\r\n    .footer-links a {\r\n      text-decoration: none;\r\n      color: rgba(255,255,255,0.6);\r\n      font-size: 15px;\r\n      transition: 0.2s;\r\n    }\r\n\r\n    .footer-links a:hover {\r\n      color: white;\r\n    }\r\n\r\n    .footer-title {\r\n      font-weight: 700;\r\n      color: white;\r\n      margin-bottom: 12px;\r\n      font-size: 18px;\r\n    }\r\n\r\n    .footer-bottom {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      padding-top: 30px;\r\n      border-top: 1px solid rgba(255,255,255,0.1);\r\n      color: rgba(255,255,255,0.5);\r\n    }\r\n\r\n    /* RESPONSIVE */\r\n    @media (max-width: 1100px) {\r\n      .specialties-grid,\r\n      .team-grid,\r\n      .services-grid,\r\n      .testimonials-grid,\r\n      .figures-container,\r\n      .footer-main {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n    }\r\n\r\n    @media (max-width: 900px) {\r\n      .med-hero {\r\n        grid-template-columns: 1fr;\r\n      }\r\n      .appointment-container {\r\n        grid-template-columns: 1fr;\r\n      }\r\n      .med-header {\r\n        flex-direction: column;\r\n        gap: 20px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 700px) {\r\n      .specialties-grid,\r\n      .team-grid,\r\n      .services-grid,\r\n      .testimonials-grid,\r\n      .figures-container,\r\n      .footer-main {\r\n        grid-template-columns: 1fr;\r\n      }\r\n      .med-hero,\r\n      .med-specialties,\r\n      .med-team,\r\n      .med-services,\r\n      .med-testimonials {\r\n        padding: 40px 24px;\r\n      }\r\n    }\r\n\r\n    .gjs-draggable { cursor: move; }', NULL, NULL, NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL);
INSERT INTO `templates` (`id`, `categorie_id`, `name`, `url`, `description`, `html_content`, `css_content`, `js_content`, `assets_folder`, `assets_data`, `thumbnail`, `metadata`, `user_id`, `website_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(93, 11, 'Hôtellerie', NULL, NULL, '<body>\r\n  <!-- HÔTEL - RÉSERVATION EN LIGNE -->\r\n  <section class=\"hotel-section\">\r\n\r\n    <!-- HEADER HÔTEL -->\r\n    <header class=\"hotel-header\">\r\n      <div class=\"hotel-logo\">\r\n        <span class=\"hotel-logo-icon\">🏨</span>\r\n        <span class=\"hotel-logo-text\">Palace<span>Hotel</span></span>\r\n      </div>\r\n      <nav class=\"hotel-nav\">\r\n        <a href=\"#\">Chambres</a>\r\n        <a href=\"#\">Services</a>\r\n        <a href=\"#\">Galerie</a>\r\n        <a href=\"#\">Offres</a>\r\n        <a href=\"#\">Contact</a>\r\n      </nav>\r\n      <div class=\"hotel-actions\">\r\n        <span class=\"hotel-lang\">🌐 FR</span>\r\n        <button class=\"hotel-reservation-btn\">Réserver</button>\r\n      </div>\r\n    </header>\r\n\r\n    <!-- HERO AVEC MOTEUR DE RÉSERVATION -->\r\n    <div class=\"hotel-hero\">\r\n      <span class=\"hotel-hero-bg\">🏨</span>\r\n      <div class=\"hotel-hero-content\">\r\n        <span class=\"hotel-hero-tag\">\r\n          <span>✨</span> Hôtel 5 étoiles - Paris Centre\r\n        </span>\r\n        <h1 class=\"hotel-hero-title\">\r\n          Séjournez dans <span class=\"hotel-hero-accent\">l\'élégance</span> parisienne\r\n        </h1>\r\n        <p class=\"hotel-hero-desc\">\r\n          Chambres luxueuses, spa primé, restaurant gastronomique. \r\n          Une expérience unique au cœur de la ville lumière.\r\n        </p>\r\n        \r\n        <!-- MOTEUR DE RÉSERVATION -->\r\n        <div class=\"hotel-booking-engine\">\r\n          <div class=\"booking-field\">\r\n            <span class=\"booking-icon\">📅</span>\r\n            <div class=\"booking-content\">\r\n              <span class=\"booking-label\">Arrivée</span>\r\n              <span class=\"booking-value\">15 mars 2026</span>\r\n            </div>\r\n          </div>\r\n          <div class=\"booking-field\">\r\n            <span class=\"booking-icon\">📅</span>\r\n            <div class=\"booking-content\">\r\n              <span class=\"booking-label\">Départ</span>\r\n              <span class=\"booking-value\">18 mars 2026</span>\r\n            </div>\r\n          </div>\r\n          <div class=\"booking-field\">\r\n            <span class=\"booking-icon\">👥</span>\r\n            <div class=\"booking-content\">\r\n              <span class=\"booking-label\">Voyageurs</span>\r\n              <span class=\"booking-value\">2 adultes</span>\r\n            </div>\r\n          </div>\r\n          <button class=\"booking-btn\">\r\n            <span>🔍</span> Vérifier disponibilités\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- CHAMBRES & SUITES -->\r\n    <div class=\"hotel-rooms\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-title-left\">\r\n          <h2>Chambres & Suites</h2>\r\n          <p>Un confort absolu dans chaque espace</p>\r\n        </div>\r\n        <span class=\"section-link\">Voir toutes nos chambres →</span>\r\n      </div>\r\n\r\n      <div class=\"rooms-grid\">\r\n        <!-- CHAMBRE CLASSIQUE -->\r\n        <div class=\"room-card\">\r\n          <div class=\"room-image\">\r\n            <span>🛏️</span>\r\n            <span class=\"room-badge\">À partir de 199€</span>\r\n          </div>\r\n          <div class=\"room-info\">\r\n            <div class=\"room-category\">CHAMBRE</div>\r\n            <h3 class=\"room-name\">Classique</h3>\r\n            <div class=\"room-features\">\r\n              <span>🛏️ 1 lit double</span>\r\n              <span>🚿 Douche</span>\r\n            </div>\r\n            <div class=\"room-price\">\r\n              <span class=\"price-amount\">199€</span>\r\n              <span class=\"price-period\">/ nuit</span>\r\n            </div>\r\n            <button class=\"room-btn\">Réserver</button>\r\n          </div>\r\n        </div>\r\n        <!-- CHAMBRE SUPÉRIEURE -->\r\n        <div class=\"room-card\">\r\n          <div class=\"room-image\">\r\n            <span>🛋️</span>\r\n            <span class=\"room-badge\">À partir de 299€</span>\r\n          </div>\r\n          <div class=\"room-info\">\r\n            <div class=\"room-category\">SUPÉRIEURE</div>\r\n            <h3 class=\"room-name\">Supérieure</h3>\r\n            <div class=\"room-features\">\r\n              <span>🛏️ 1 lit king</span>\r\n              <span>🛁 Baignoire</span>\r\n              <span>🌆 Vue cour</span>\r\n            </div>\r\n            <div class=\"room-price\">\r\n              <span class=\"price-amount\">299€</span>\r\n              <span class=\"price-period\">/ nuit</span>\r\n            </div>\r\n            <button class=\"room-btn\">Réserver</button>\r\n          </div>\r\n        </div>\r\n        <!-- SUITE DELUXE -->\r\n        <div class=\"room-card\">\r\n          <div class=\"room-image\">\r\n            <span>✨</span>\r\n            <span class=\"room-badge\">À partir de 499€</span>\r\n          </div>\r\n          <div class=\"room-info\">\r\n            <div class=\"room-category\">SUITE</div>\r\n            <h3 class=\"room-name\">Deluxe</h3>\r\n            <div class=\"room-features\">\r\n              <span>🛏️ 2 lits queen</span>\r\n              <span>🛁 Jacuzzi</span>\r\n              <span>🏙️ Vue Paris</span>\r\n            </div>\r\n            <div class=\"room-price\">\r\n              <span class=\"price-amount\">499€</span>\r\n              <span class=\"price-period\">/ nuit</span>\r\n            </div>\r\n            <button class=\"room-btn\">Réserver</button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- ÉQUIPEMENTS & SERVICES -->\r\n    <div class=\"hotel-amenities\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-title-left\">\r\n          <h2>Services & équipements</h2>\r\n          <p>L\'excellence à chaque instant</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"amenities-grid\">\r\n        <div class=\"amenity-item\">\r\n          <div class=\"amenity-icon\">🍽️</div>\r\n          <h4 class=\"amenity-title\">Restaurant étoilé</h4>\r\n          <p class=\"amenity-desc\">Cuisine gastronomique française, chef primé</p>\r\n        </div>\r\n        <div class=\"amenity-item\">\r\n          <div class=\"amenity-icon\">💆</div>\r\n          <h4 class=\"amenity-title\">Spa & bien-être</h4>\r\n          <p class=\"amenity-desc\">Piscine, sauna, hammam, soins sur mesure</p>\r\n        </div>\r\n        <div class=\"amenity-item\">\r\n          <div class=\"amenity-icon\">🏋️</div>\r\n          <h4 class=\"amenity-title\">Fitness</h4>\r\n          <p class=\"amenity-desc\">Équipements haut de gamme, coach disponible</p>\r\n        </div>\r\n        <div class=\"amenity-item\">\r\n          <div class=\"amenity-icon\">🚗</div>\r\n          <h4 class=\"amenity-title\">Parking privé</h4>\r\n          <p class=\"amenity-desc\">Sécurisé, accès direct à l\'hôtel</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- GALERIE PHOTOS -->\r\n    <div class=\"hotel-gallery\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-title-left\">\r\n          <h2>Galerie</h2>\r\n          <p>Découvrez l\'atmosphère unique du Palace</p>\r\n        </div>\r\n        <span class=\"section-link\">Voir plus →</span>\r\n      </div>\r\n\r\n      <div class=\"gallery-grid\">\r\n        <div class=\"gallery-item\">🏊</div>\r\n        <div class=\"gallery-item\">🍷</div>\r\n        <div class=\"gallery-item\">🛋️</div>\r\n        <div class=\"gallery-item\">🌇</div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- OFFRES SPÉCIALES -->\r\n    <div class=\"hotel-offers\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-title-left\">\r\n          <h2>Offres spéciales</h2>\r\n          <p>Des séjours d\'exception à tarifs privilégiés</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"offers-grid\">\r\n        <div class=\"offer-card\">\r\n          <span class=\"offer-tag\">⭐ COUP DE CŒUR</span>\r\n          <h3 class=\"offer-name\">Escapade romantique</h3>\r\n          <p class=\"offer-desc\">\r\n            Champagne offert, dîner aux chandelles, accès spa en illimité et départ tardif.\r\n          </p>\r\n          <div class=\"offer-price\">\r\n            349€ <small>/ nuit</small>\r\n          </div>\r\n          <button class=\"offer-btn\">Réserver cette offre</button>\r\n        </div>\r\n        <div class=\"offer-card\">\r\n          <span class=\"offer-tag\">🏆 FAMILLE</span>\r\n          <h3 class=\"offer-name\">Séjour en famille</h3>\r\n          <p class=\"offer-desc\">\r\n            Petit-déjeuner inclus pour 4 personnes, lit bébé offert, accès au club enfants.\r\n          </p>\r\n          <div class=\"offer-price\">\r\n            449€ <small>/ nuit</small>\r\n          </div>\r\n          <button class=\"offer-btn\">Réserver cette offre</button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- TÉMOIGNAGES CLIENTS -->\r\n    <div class=\"hotel-testimonials\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-title-left\">\r\n          <h2>Ils ont séjourné chez nous</h2>\r\n          <p>Votre satisfaction, notre fierté</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"testimonials-grid\">\r\n        <div class=\"testimonial-card\">\r\n          <div class=\"testimonial-rating\">★★★★★</div>\r\n          <p class=\"testimonial-text\">\"Un séjour parfait ! Le personnel est aux petits soins, la chambre spacieuse et le spa magnifique. Nous reviendrons.\"</p>\r\n          <div class=\"testimonial-author\">\r\n            <div class=\"testimonial-avatar\">C</div>\r\n            <div>\r\n              <div style=\"font-weight: 700; color: #2e2a27;\">Claire M.</div>\r\n              <div style=\"font-size: 13px; color: #6f6258;\">Séjour romantique</div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"testimonial-card\">\r\n          <div class=\"testimonial-rating\">★★★★★</div>\r\n          <p class=\"testimonial-text\">\"Le restaurant est une vraie découverte gastronomique. Chambre luxueuse, literie exceptionnelle. Merci pour l\'accueil.\"</p>\r\n          <div class=\"testimonial-author\">\r\n            <div class=\"testimonial-avatar\">T</div>\r\n            <div>\r\n              <div style=\"font-weight: 700; color: #2e2a27;\">Thomas R.</div>\r\n              <div style=\"font-size: 13px; color: #6f6258;\">Séjour affaires</div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"testimonial-card\">\r\n          <div class=\"testimonial-rating\">★★★★☆</div>\r\n          <p class=\"testimonial-text\">\"Très bel hôtel, bien situé. Le petit-déjeuner buffet est copieux et varié. Je recommande la suite avec vue.\"</p>\r\n          <div class=\"testimonial-author\">\r\n            <div class=\"testimonial-avatar\">S</div>\r\n            <div>\r\n              <div style=\"font-weight: 700; color: #2e2a27;\">Sophie L.</div>\r\n              <div style=\"font-size: 13px; color: #6f6258;\">Séjour en famille</div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- NEWSLETTER -->\r\n    <div class=\"hotel-newsletter\">\r\n      <div class=\"newsletter-left\">\r\n        <h3>Offres exclusives</h3>\r\n        <p>Inscrivez-vous pour recevoir nos promotions et nouveautés</p>\r\n      </div>\r\n      <div class=\"newsletter-form\">\r\n        <input type=\"email\" class=\"newsletter-input\" placeholder=\"Votre adresse email\" value=\"\">\r\n        <button class=\"newsletter-btn\">S\'inscrire</button>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- FOOTER HÔTEL -->\r\n    <footer class=\"hotel-footer\">\r\n      <div class=\"footer-main\">\r\n        <div class=\"footer-about\">\r\n          <div class=\"footer-logo\">PalaceHotel</div>\r\n          <p>Hôtel 5 étoiles au cœur de Paris. Alliant tradition et modernité pour une expérience unique depuis 1925.</p>\r\n          <div class=\"footer-social\">\r\n            <span>📘</span>\r\n            <span>📷</span>\r\n            <span>🐦</span>\r\n            <span>🎵</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Hébergement</span>\r\n          <a href=\"#\">Chambres classiques</a>\r\n          <a href=\"#\">Chambres supérieures</a>\r\n          <a href=\"#\">Suites</a>\r\n          <a href=\"#\">Offres spéciales</a>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Services</span>\r\n          <a href=\"#\">Restauration</a>\r\n          <a href=\"#\">Spa & bien-être</a>\r\n          <a href=\"#\">Événements</a>\r\n          <a href=\"#\">Séminaires</a>\r\n        </div>\r\n        <div class=\"footer-links\">\r\n          <span class=\"footer-title\">Contact</span>\r\n          <a href=\"#\">15 avenue Montaigne, 75008 Paris</a>\r\n          <a href=\"#\">01 53 67 89 01</a>\r\n          <a href=\"#\">reservation@palacehotel.fr</a>\r\n          <a href=\"#\">Accès & plan</a>\r\n        </div>\r\n      </div>\r\n      <div class=\"footer-bottom\">\r\n        <span>© 2026 PalaceHotel - Tous droits réservés</span>\r\n        <span style=\"display: flex; gap: 28px;\">\r\n          <span>Mentions légales</span>\r\n          <span>Confidentialité</span>\r\n          <span>CGV</span>\r\n        </span>\r\n      </div>\r\n    </footer>\r\n  </section>\r\n</body>', ' /* ===== STYLE HÔTELLERIE - LUXE, CONFORT, ÉVASION ===== */\r\n    /* Design premium, chaleureux, expérience client */\r\n    .hotel-section {\r\n      font-family: \'Inter\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, \'Helvetica Neue\', sans-serif;\r\n      max-width: 1440px;\r\n      margin: 0 auto;\r\n      background: #ffffff;\r\n      color: #2c2c2c;\r\n      position: relative;\r\n    }\r\n\r\n    /* HEADER HÔTEL - ÉLÉGANCE */\r\n    .hotel-header {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      padding: 24px 60px;\r\n      background: white;\r\n      border-bottom: 1px solid #f5efe9;\r\n      flex-wrap: wrap;\r\n    }\r\n\r\n    .hotel-logo {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 12px;\r\n    }\r\n\r\n    .hotel-logo-icon {\r\n      font-size: 34px;\r\n      background: linear-gradient(145deg, #c69c6d, #b2845a);\r\n      color: white;\r\n      padding: 10px;\r\n      border-radius: 14px;\r\n      transform: rotate(-2deg);\r\n    }\r\n\r\n    .hotel-logo-text {\r\n      font-size: 28px;\r\n      font-weight: 700;\r\n      color: #4a3729;\r\n      letter-spacing: -0.5px;\r\n    }\r\n\r\n    .hotel-logo-text span {\r\n      color: #b2845a;\r\n      font-weight: 300;\r\n    }\r\n\r\n    .hotel-nav {\r\n      display: flex;\r\n      gap: 42px;\r\n      font-weight: 500;\r\n    }\r\n\r\n    .hotel-nav a {\r\n      text-decoration: none;\r\n      color: #4e3e35;\r\n      font-size: 16px;\r\n      transition: 0.2s;\r\n    }\r\n\r\n    .hotel-nav a:hover {\r\n      color: #b2845a;\r\n    }\r\n\r\n    .hotel-actions {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 20px;\r\n    }\r\n\r\n    .hotel-lang {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 8px;\r\n      color: #6b5a4e;\r\n      font-weight: 500;\r\n    }\r\n\r\n    .hotel-reservation-btn {\r\n      background: #b2845a;\r\n      color: white;\r\n      padding: 14px 32px;\r\n      border-radius: 40px;\r\n      font-weight: 600;\r\n      font-size: 15px;\r\n      border: none;\r\n      box-shadow: 0 10px 20px -10px rgba(178, 132, 90, 0.4);\r\n    }\r\n\r\n    /* HERO HÔTEL - ÉVASION */\r\n    .hotel-hero {\r\n      position: relative;\r\n      padding: 80px 60px;\r\n      background: linear-gradient(145deg, #fcf8f4, #f8f1ea);\r\n      border-radius: 0 0 48px 48px;\r\n      overflow: hidden;\r\n    }\r\n\r\n    .hotel-hero-bg {\r\n      position: absolute;\r\n      top: 20px;\r\n      right: 60px;\r\n      font-size: 200px;\r\n      opacity: 0.05;\r\n      color: #b2845a;\r\n    }\r\n\r\n    .hotel-hero-content {\r\n      max-width: 700px;\r\n      position: relative;\r\n      z-index: 5;\r\n    }\r\n\r\n    .hotel-hero-tag {\r\n      background: rgba(178, 132, 90, 0.12);\r\n      color: #8b6b4c;\r\n      padding: 10px 26px;\r\n      border-radius: 40px;\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 10px;\r\n      font-weight: 600;\r\n      font-size: 15px;\r\n      margin-bottom: 28px;\r\n      backdrop-filter: blur(4px);\r\n    }\r\n\r\n    .hotel-hero-title {\r\n      font-size: 58px;\r\n      font-weight: 800;\r\n      line-height: 1.05;\r\n      margin: 0 0 24px 0;\r\n      color: #2e2a27;\r\n      letter-spacing: -2px;\r\n    }\r\n\r\n    .hotel-hero-accent {\r\n      color: #b2845a;\r\n      font-style: italic;\r\n    }\r\n\r\n    .hotel-hero-desc {\r\n      font-size: 18px;\r\n      line-height: 1.7;\r\n      color: #5f5248;\r\n      margin-bottom: 40px;\r\n      max-width: 600px;\r\n    }\r\n\r\n    /* MOTEUR DE RÉSERVATION */\r\n    .hotel-booking-engine {\r\n      background: white;\r\n      border-radius: 80px;\r\n      padding: 12px;\r\n      display: flex;\r\n      align-items: center;\r\n      max-width: 900px;\r\n      box-shadow: 0 30px 50px -25px rgba(0,0,0,0.1);\r\n      border: 1px solid rgba(255,255,255,0.6);\r\n      flex-wrap: wrap;\r\n    }\r\n\r\n    .booking-field {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 14px;\r\n      padding: 8px 28px;\r\n      border-right: 1px solid #efe5dd;\r\n      flex: 1 1 180px;\r\n    }\r\n\r\n    .booking-field:last-child {\r\n      border-right: none;\r\n    }\r\n\r\n    .booking-icon {\r\n      font-size: 24px;\r\n      color: #b2845a;\r\n    }\r\n\r\n    .booking-content {\r\n      display: flex;\r\n      flex-direction: column;\r\n    }\r\n\r\n    .booking-label {\r\n      font-size: 12px;\r\n      color: #8f7e73;\r\n      font-weight: 500;\r\n    }\r\n\r\n    .booking-value {\r\n      font-weight: 700;\r\n      color: #3a342f;\r\n      font-size: 16px;\r\n    }\r\n\r\n    .booking-btn {\r\n      background: #b2845a;\r\n      border: none;\r\n      border-radius: 60px;\r\n      padding: 18px 44px;\r\n      color: white;\r\n      font-weight: 700;\r\n      font-size: 17px;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 12px;\r\n      cursor: default;\r\n      box-shadow: 0 12px 22px -8px rgba(178,132,90,0.5);\r\n    }\r\n\r\n    /* SECTION CHAMBRES & SUITES */\r\n    .hotel-rooms {\r\n      padding: 90px 60px;\r\n      background: white;\r\n    }\r\n\r\n    .section-header {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      align-items: flex-end;\r\n      margin-bottom: 48px;\r\n      flex-wrap: wrap;\r\n    }\r\n\r\n    .section-title-left h2 {\r\n      font-size: 42px;\r\n      font-weight: 700;\r\n      margin: 0 0 12px 0;\r\n      color: #2e2a27;\r\n      letter-spacing: -1px;\r\n    }\r\n\r\n    .section-title-left p {\r\n      font-size: 18px;\r\n      color: #6f6258;\r\n      margin: 0;\r\n    }\r\n\r\n    .section-link {\r\n      color: #b2845a;\r\n      font-weight: 600;\r\n      border-bottom: 2px solid #b2845a;\r\n      padding-bottom: 4px;\r\n    }\r\n\r\n    .rooms-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 32px;\r\n      margin-top: 20px;\r\n    }\r\n\r\n    .room-card {\r\n      background: white;\r\n      border-radius: 36px;\r\n      overflow: hidden;\r\n      box-shadow: 0 25px 40px -25px rgba(0,0,0,0.05);\r\n      border: 1px solid #f5ede7;\r\n      transition: 0.3s ease;\r\n    }\r\n\r\n    .room-card:hover {\r\n      transform: translateY(-8px);\r\n      box-shadow: 0 35px 60px -30px rgba(178,132,90,0.2);\r\n      border-color: #e3d2c5;\r\n    }\r\n\r\n    .room-image {\r\n      background: linear-gradient(145deg, #e8ddd2, #dfd1c4);\r\n      height: 260px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      position: relative;\r\n      font-size: 80px;\r\n    }\r\n\r\n    .room-badge {\r\n      position: absolute;\r\n      top: 24px;\r\n      right: 24px;\r\n      background: white;\r\n      padding: 8px 22px;\r\n      border-radius: 40px;\r\n      font-weight: 700;\r\n      color: #b2845a;\r\n      box-shadow: 0 6px 16px rgba(0,0,0,0.03);\r\n      font-size: 15px;\r\n    }\r\n\r\n    .room-info {\r\n      padding: 32px;\r\n    }\r\n\r\n    .room-category {\r\n      font-size: 13px;\r\n      text-transform: uppercase;\r\n      letter-spacing: 2px;\r\n      color: #b2845a;\r\n      margin-bottom: 10px;\r\n    }\r\n\r\n    .room-name {\r\n      font-size: 26px;\r\n      font-weight: 700;\r\n      margin: 0 0 16px 0;\r\n      color: #2e2a27;\r\n    }\r\n\r\n    .room-features {\r\n      display: flex;\r\n      gap: 24px;\r\n      margin-bottom: 24px;\r\n      color: #6f6258;\r\n      font-size: 15px;\r\n    }\r\n\r\n    .room-price {\r\n      display: flex;\r\n      align-items: baseline;\r\n      gap: 8px;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .price-amount {\r\n      font-size: 32px;\r\n      font-weight: 800;\r\n      color: #2e2a27;\r\n    }\r\n\r\n    .price-period {\r\n      font-size: 16px;\r\n      color: #8f7e73;\r\n    }\r\n\r\n    .room-btn {\r\n      background: transparent;\r\n      border: 1.5px solid #b2845a;\r\n      color: #8b6b4c;\r\n      padding: 14px 28px;\r\n      border-radius: 40px;\r\n      font-weight: 600;\r\n      width: 100%;\r\n      font-size: 16px;\r\n      transition: 0.2s;\r\n    }\r\n\r\n    .room-btn:hover {\r\n      background: #b2845a;\r\n      color: white;\r\n    }\r\n\r\n    /* SECTION ÉQUIPEMENTS & SERVICES */\r\n    .hotel-amenities {\r\n      background: #fcf9f6;\r\n      padding: 80px 60px;\r\n    }\r\n\r\n    .amenities-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 30px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .amenity-item {\r\n      text-align: center;\r\n      padding: 36px 24px;\r\n      background: white;\r\n      border-radius: 32px;\r\n      border: 1px solid #f5eae3;\r\n      transition: 0.2s;\r\n    }\r\n\r\n    .amenity-item:hover {\r\n      border-color: #dcc9bb;\r\n      transform: translateY(-5px);\r\n    }\r\n\r\n    .amenity-icon {\r\n      font-size: 48px;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .amenity-title {\r\n      font-size: 20px;\r\n      font-weight: 700;\r\n      margin: 0 0 12px 0;\r\n      color: #4a3f38;\r\n    }\r\n\r\n    .amenity-desc {\r\n      font-size: 15px;\r\n      color: #73645b;\r\n      line-height: 1.6;\r\n    }\r\n\r\n    /* SECTION GALERIE PHOTOS */\r\n    .hotel-gallery {\r\n      padding: 80px 60px;\r\n      background: white;\r\n    }\r\n\r\n    .gallery-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 24px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .gallery-item {\r\n      background: linear-gradient(145deg, #f0e7e0, #e5d9d1);\r\n      border-radius: 28px;\r\n      height: 200px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      font-size: 48px;\r\n      border: 1px solid #f5ede7;\r\n      transition: 0.2s;\r\n    }\r\n\r\n    .gallery-item:hover {\r\n      transform: scale(1.02);\r\n      box-shadow: 0 20px 35px -18px rgba(0,0,0,0.1);\r\n    }\r\n\r\n    /* SECTION TARIFS & OFFRES */\r\n    .hotel-offers {\r\n      background: #fcf9f6;\r\n      padding: 80px 60px;\r\n    }\r\n\r\n    .offers-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(2, 1fr);\r\n      gap: 32px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .offer-card {\r\n      background: white;\r\n      border-radius: 36px;\r\n      padding: 40px;\r\n      display: flex;\r\n      flex-direction: column;\r\n      border: 1px solid #f5eae3;\r\n    }\r\n\r\n    .offer-tag {\r\n      background: #b2845a;\r\n      color: white;\r\n      padding: 6px 20px;\r\n      border-radius: 40px;\r\n      font-size: 14px;\r\n      font-weight: 600;\r\n      align-self: flex-start;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .offer-name {\r\n      font-size: 28px;\r\n      font-weight: 700;\r\n      margin: 0 0 16px 0;\r\n      color: #2e2a27;\r\n    }\r\n\r\n    .offer-desc {\r\n      font-size: 16px;\r\n      line-height: 1.7;\r\n      color: #6f6258;\r\n      margin-bottom: 28px;\r\n    }\r\n\r\n    .offer-price {\r\n      font-size: 36px;\r\n      font-weight: 800;\r\n      color: #b2845a;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .offer-price small {\r\n      font-size: 16px;\r\n      font-weight: 400;\r\n      color: #8f7e73;\r\n    }\r\n\r\n    .offer-btn {\r\n      background: #b2845a;\r\n      color: white;\r\n      padding: 16px 32px;\r\n      border-radius: 50px;\r\n      font-weight: 700;\r\n      text-align: center;\r\n      border: none;\r\n    }\r\n\r\n    /* SECTION TÉMOIGNAGES CLIENTS */\r\n    .hotel-testimonials {\r\n      padding: 80px 60px;\r\n      background: white;\r\n    }\r\n\r\n    .testimonials-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 30px;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .testimonial-card {\r\n      background: #fcf9f6;\r\n      border-radius: 32px;\r\n      padding: 36px;\r\n      border: 1px solid #f5ede7;\r\n    }\r\n\r\n    .testimonial-rating {\r\n      color: #ffb347;\r\n      font-size: 20px;\r\n      margin-bottom: 20px;\r\n    }\r\n\r\n    .testimonial-text {\r\n      font-size: 17px;\r\n      line-height: 1.7;\r\n      color: #5f5248;\r\n      margin-bottom: 28px;\r\n      font-style: italic;\r\n    }\r\n\r\n    .testimonial-author {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .testimonial-avatar {\r\n      width: 56px;\r\n      height: 56px;\r\n      background: #e8ddd2;\r\n      border-radius: 18px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      font-size: 24px;\r\n      color: #b2845a;\r\n    }\r\n\r\n    /* SECTION NEWSLETTER */\r\n    .hotel-newsletter {\r\n      background: linear-gradient(145deg, #b2845a, #9f7350);\r\n      border-radius: 48px;\r\n      margin: 40px 60px 60px;\r\n      padding: 56px 64px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      flex-wrap: wrap;\r\n      color: white;\r\n    }\r\n\r\n    .newsletter-left h3 {\r\n      font-size: 34px;\r\n      font-weight: 700;\r\n      margin: 0 0 12px 0;\r\n      color: white;\r\n      letter-spacing: -1px;\r\n    }\r\n\r\n    .newsletter-left p {\r\n      font-size: 18px;\r\n      color: rgba(255,255,255,0.85);\r\n      margin: 0;\r\n    }\r\n\r\n    .newsletter-form {\r\n      display: flex;\r\n      gap: 16px;\r\n      background: white;\r\n      border-radius: 60px;\r\n      padding: 6px;\r\n    }\r\n\r\n    .newsletter-input {\r\n      border: none;\r\n      padding: 14px 24px;\r\n      border-radius: 60px;\r\n      font-size: 16px;\r\n      width: 260px;\r\n      outline: none;\r\n    }\r\n\r\n    .newsletter-btn {\r\n      background: #b2845a;\r\n      color: white;\r\n      border: none;\r\n      border-radius: 60px;\r\n      padding: 14px 36px;\r\n      font-weight: 700;\r\n      font-size: 16px;\r\n    }\r\n\r\n    /* FOOTER HÔTEL */\r\n    .hotel-footer {\r\n      background: #2e2a27;\r\n      color: white;\r\n      padding: 60px 60px 30px;\r\n    }\r\n\r\n    .footer-main {\r\n      display: grid;\r\n      grid-template-columns: 2fr 1fr 1fr 1.5fr;\r\n      gap: 50px;\r\n      margin-bottom: 50px;\r\n    }\r\n\r\n    .footer-logo {\r\n      font-size: 28px;\r\n      font-weight: 700;\r\n      color: white;\r\n      margin-bottom: 20px;\r\n    }\r\n\r\n    .footer-about p {\r\n      color: rgba(255,255,255,0.6);\r\n      line-height: 1.7;\r\n    }\r\n\r\n    .footer-links {\r\n      display: flex;\r\n      flex-direction: column;\r\n      gap: 16px;\r\n    }\r\n\r\n    .footer-links a {\r\n      text-decoration: none;\r\n      color: rgba(255,255,255,0.6);\r\n      font-size: 15px;\r\n      transition: 0.2s;\r\n    }\r\n\r\n    .footer-links a:hover {\r\n      color: white;\r\n    }\r\n\r\n    .footer-title {\r\n      font-weight: 700;\r\n      color: white;\r\n      margin-bottom: 12px;\r\n      font-size: 18px;\r\n    }\r\n\r\n    .footer-bottom {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      padding-top: 30px;\r\n      border-top: 1px solid rgba(255,255,255,0.1);\r\n      color: rgba(255,255,255,0.5);\r\n    }\r\n\r\n    .footer-social {\r\n      display: flex;\r\n      gap: 28px;\r\n      font-size: 22px;\r\n    }\r\n\r\n    /* RESPONSIVE */\r\n    @media (max-width: 1100px) {\r\n      .rooms-grid,\r\n      .amenities-grid,\r\n      .gallery-grid,\r\n      .testimonials-grid,\r\n      .footer-main {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n    }\r\n\r\n    @media (max-width: 900px) {\r\n      .offers-grid {\r\n        grid-template-columns: 1fr;\r\n      }\r\n      .hotel-header {\r\n        flex-direction: column;\r\n        gap: 20px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 700px) {\r\n      .rooms-grid,\r\n      .amenities-grid,\r\n      .gallery-grid,\r\n      .testimonials-grid,\r\n      .footer-main {\r\n        grid-template-columns: 1fr;\r\n      }\r\n      .hotel-hero,\r\n      .hotel-rooms,\r\n      .hotel-amenities,\r\n      .hotel-gallery,\r\n      .hotel-offers,\r\n      .hotel-testimonials {\r\n        padding: 40px 24px;\r\n      }\r\n    }\r\n\r\n    .gjs-draggable { cursor: move; }', NULL, NULL, NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL);
INSERT INTO `templates` (`id`, `categorie_id`, `name`, `url`, `description`, `html_content`, `css_content`, `js_content`, `assets_folder`, `assets_data`, `thumbnail`, `metadata`, `user_id`, `website_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(94, NULL, 'Startup', NULL, NULL, ' <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css\">\n  <!-- Google Fonts Inter -->\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n  \n<body>\n\n  <!-- ===== NAVBAR ===== -->\n  <nav class=\"ns-navbar\">\n    <div class=\"ns-container\">\n      <a href=\"#\" class=\"ns-logo\">NOVA</a>\n      <div class=\"ns-nav-links\">\n        <a href=\"#\">Produit</a>\n        <a href=\"#\">Fonctionnalités</a>\n        <a href=\"#\">Tarifs</a>\n        <a href=\"#\">Ressources</a>\n        <a href=\"#\">Contact</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- ===== HERO ===== -->\n  <section class=\"ns-hero\">\n    <div class=\"ns-container\">\n      <div class=\"ns-hero-content\">\n        <span class=\"ns-badge ns-badge-white\">✨ LA RÉVOLUTION NOVA</span>\n        <h1 class=\"ns-h1\">L\'IA qui transforme<br>votre productivité</h1>\n        <p>NOVA analyse, organise et automatise vos tâches quotidiennes. Gagnez 10h par semaine dès le premier mois.</p>\n        <div class=\"ns-hero-buttons\">\n          <a href=\"#\" class=\"ns-btn ns-btn-primary\">Démarrer gratuitement</a>\n          <a href=\"#\" class=\"ns-btn ns-btn-outline-light\">Demander une démo</a>\n        </div>\n        <div class=\"ns-hero-stats\">\n          <div class=\"ns-stat-item\">\n            <span class=\"ns-stat-number\">+15 000</span>\n            <span class=\"ns-stat-label\">entreprises clientes</span>\n          </div>\n          <div class=\"ns-stat-item\">\n            <span class=\"ns-stat-number\">98%</span>\n            <span class=\"ns-stat-label\">de satisfaction</span>\n          </div>\n          <div class=\"ns-stat-item\">\n            <span class=\"ns-stat-number\">4.9</span>\n            <span class=\"ns-stat-label\">★ sur G2</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ===== CLIENTS ===== -->\n  <section class=\"ns-clients\">\n    <div class=\"ns-container\">\n      <div class=\"ns-clients-grid\">\n        <i class=\"fab fa-microsoft\"></i>\n        <i class=\"fab fa-google\"></i>\n        <i class=\"fab fa-amazon\"></i>\n        <i class=\"fab figma\">⚡</i>\n        <i class=\"fab fa-slack\"></i>\n        <i class=\"fab fa-shopify\"></i>\n      </div>\n    </div>\n  </section>\n\n  <!-- ===== FEATURES ===== -->\n  <section class=\"ns-section\">\n    <div class=\"ns-container\">\n      <div class=\"ns-section-title\">\n        <span class=\"ns-badge\">POURQUOI NOVA ?</span>\n        <h2 class=\"ns-h2\">Plus qu\'un outil, un assistant</h2>\n        <p class=\"ns-section-subtitle\">Automatisez, collaborez, analysez — tout en un.</p>\n      </div>\n      <div class=\"ns-grid ns-grid-3\">\n        <div class=\"ns-feature-card\">\n          <div class=\"ns-feature-icon\">\n            <i class=\"fas fa-brain\"></i>\n          </div>\n          <h3 class=\"ns-h3\">IA prédictive</h3>\n          <p style=\"color: #475569;\">Anticipe vos besoins et propose des actions avant même que vous y pensiez.</p>\n        </div>\n        <div class=\"ns-feature-card\">\n          <div class=\"ns-feature-icon\">\n            <i class=\"fas fa-bolt\"></i>\n          </div>\n          <h3 class=\"ns-h3\">Automatisation</h3>\n          <p style=\"color: #475569;\">Créez des workflows sans code en quelques clics.</p>\n        </div>\n        <div class=\"ns-feature-card\">\n          <div class=\"ns-feature-icon\">\n            <i class=\"fas fa-shield-alt\"></i>\n          </div>\n          <h3 class=\"ns-h3\">Sécurité renforcée</h3>\n          <p style=\"color: #475569;\">Chiffrement AES-256 et conformité RGPD.</p>\n        </div>\n        <div class=\"ns-feature-card\">\n          <div class=\"ns-feature-icon\">\n            <i class=\"fas fa-chart-line\"></i>\n          </div>\n          <h3 class=\"ns-h3\">Analytics avancés</h3>\n          <p style=\"color: #475569;\">Tableaux de bord personnalisables en temps réel.</p>\n        </div>\n        <div class=\"ns-feature-card\">\n          <div class=\"ns-feature-icon\">\n            <i class=\"fas fa-plug\"></i>\n          </div>\n          <h3 class=\"ns-h3\">100+ intégrations</h3>\n          <p style=\"color: #475569;\">Se connecte à tous vos outils (Slack, Notion, Salesforce).</p>\n        </div>\n        <div class=\"ns-feature-card\">\n          <div class=\"ns-feature-icon\">\n            <i class=\"fas fa-clock\"></i>\n          </div>\n          <h3 class=\"ns-h3\">Support prioritaire</h3>\n          <p style=\"color: #475569;\">Réponse sous 2h, 7j/7.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ===== HOW IT WORKS ===== -->\n  <section class=\"ns-section ns-bg-gray\">\n    <div class=\"ns-container\">\n      <div class=\"ns-section-title\">\n        <span class=\"ns-badge\">COMMENT ÇA MARCHE</span>\n        <h2 class=\"ns-h2\">Trois étapes, zéro complexité</h2>\n        <p class=\"ns-section-subtitle\">Conçu pour une adoption immédiate par toute votre équipe.</p>\n      </div>\n      <div class=\"ns-grid ns-grid-3\">\n        <div class=\"ns-step\">\n          <div class=\"ns-step-number\">1</div>\n          <h3 class=\"ns-h3\">Connectez vos outils</h3>\n          <p style=\"color: #475569;\">API sécurisée, intégration en 2 minutes.</p>\n        </div>\n        <div class=\"ns-step\">\n          <div class=\"ns-step-number\">2</div>\n          <h3 class=\"ns-h3\">Paramétrez vos règles</h3>\n          <p style=\"color: #475569;\">Interface no-code intuitive.</p>\n        </div>\n        <div class=\"ns-step\">\n          <div class=\"ns-step-number\">3</div>\n          <h3 class=\"ns-h3\">Gagnez du temps</h3>\n          <p style=\"color: #475569;\">Résultats immédiats.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ===== PRODUCT SHOWCASE ===== -->\n  <section class=\"ns-section ns-showcase\">\n    <div clas