(96, NULL, 'Royal la plage', NULL, NULL, '    <!-- Google Fonts -->\n    <link href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@300;400;500;600;700;800&family=Open+Sans:wght@300;400;600&display=swap\" rel=\"stylesheet\">\n    \n    <!-- Leaflet CSS -->\n    <link rel=\"stylesheet\" href=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.css\" />\n    \n    <!-- Bootstrap 5 CSS -->\n    <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.0-alpha1/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n    \n    <!-- Font Awesome -->\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n    \n    \n<body>\n    <!-- Navigation -->\n    <nav class=\"navbar\">\n        <div class=\"nav-container\">\n            <div class=\"logo\">\n                <div class=\"logo-icon\">RL</div>\n                <span class=\"logo-text\">Royal LePage</span>\n            </div>\n            <div class=\"nav-links\">\n                <a href=\"#\">Vendre</a>\n                <a href=\"#\">Acheter</a>\n                <a href=\"#\">Propriétés</a>\n                <a href=\"#\">Courtiers</a>\n                <a href=\"#\" class=\"nav-cta\">Contact</a>\n            </div>\n        </div>\n    </nav>\n\n    <main>\n        <!-- Hero Section -->\n        <section class=\"hero\">\n            <div class=\"container hero-grid\">\n                <div>\n                    <span class=\"hero-badge\">✦ Expertise depuis 1913</span>\n                    <h1>\n                        Vendre votre maison \n                        <span class=\"hero-highlight\">au juste prix</span>, \n                        c\'est une science\n                    </h1>\n                    <p>Obtenez une évaluation précise et un accompagnement stratégique en 8 étapes avec un courtier expert de votre quartier.</p>\n                    <div class=\"hero-actions\">\n                        <a href=\"#\" class=\"btn-primary\">Évaluation gratuite</a>\n                        <a href=\"#\" class=\"btn-secondary\">Nos propriétés</a>\n                    </div>\n                </div>\n                <div class=\"hero-image-container\">\n                    <img src=\"https://images.unsplash.com/photo-1564013799919-ab600027ffc6?w=800&h=600&fit=crop\" alt=\"Maison de luxe moderne\" style=\"width:100%; height:100%; object-fit:cover;\">\n                </div>\n            </div>\n        </section>\n\n        \n        <!-- Carte Interactive Section -->\n        <section class=\"map-section\">\n            <div class=\"container\">\n                <div class=\"section-header\">\n                    <div class=\"section-tag\">\n                        <i class=\"fas fa-map-marked-alt\"></i> CARTE GOOGLE VIDÉO \n                    </div>\n                    <h2 class=\"section-title\">Explorez nos propriétés</h2>\n                    <p class=\"section-subtitle\">Découvrez tous nos biens immobiliers sur la carte</p>\n                </div>\n                \n                <div class=\"app-container\">\n                    <!-- Carte à gauche -->\n                    <div class=\"map-container\">\n                        <div id=\"map\"></div>\n                        \n                        <!-- Overlay de chargement -->\n                        <div class=\"loading-overlay\" id=\"mapLoading\">\n                            <div class=\"text-center\">\n                                <div class=\"spinner-border text-primary\" role=\"status\">\n                                    <span class=\"visually-hidden\">Chargement de la carte...</span>\n                                </div>\n                                <p class=\"mt-2\">Chargement de la carte...</p>\n                            </div>\n                        </div>\n                        \n                        <!-- Bouton pour ouvrir/fermer sidebar sur mobile -->\n                        <button class=\"sidebar-toggle\" id=\"sidebarToggle\">\n                            <i class=\"fas fa-bars\" id=\"sidebarToggleIcon\"></i>\n                        </button>\n                    </div>\n                    \n                    <!-- Sidebar à droite -->\n                    <div class=\"sidebar-right\" id=\"sidebarRight\">\n                        <div class=\"filters-section\">\n                            <div class=\"filter-group\">\n                                <label for=\"province-filter\">Province/Région :</label>\n                                <select id=\"province-filter\" class=\"form-select\">\n                                    <option value=\"\">Toutes les provinces</option>\n                                </select>\n                            </div>\n                            \n                            <div class=\"filter-group\">\n                                <label for=\"category-filter\">Catégorie :</label>\n                                <select id=\"category-filter\" class=\"form-select\">\n                                    <option value=\"all\">Toutes les catégories</option>\n                                </select>\n                            </div>\n                            \n                            <div class=\"filter-group\">\n                                <button id=\"locate-me\" class=\"locate-btn\">\n                                    <i class=\"fas fa-location-arrow\"></i> Me localiser\n                                </button>\n                            </div>\n                            \n                            <div class=\"stats\">\n                                <p><span id=\"places-count\">0</span> lieux trouvés dans la zone</p>\n                            </div>\n                        </div>\n                        \n                        <div class=\"places-list\" id=\"places-list\">\n                            <div class=\"no-results\">\n                                <i class=\"fas fa-map-marker-alt\"></i>\n                                <h4>Aucun lieu trouvé</h4>\n                                <p>Utilisez les filtres pour trouver des lieux intéressants</p>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Propriétés Section -->\n        <section class=\"properties-section\">\n            <div class=\"container\">\n                <div class=\"section-header\">\n                    <div class=\"section-tag\">\n                        <i class=\"fas fa-home\"></i> PROPRIÉTÉS D\'EXCEPTION\n                    </div>\n                    <h2 class=\"section-title\">Nos biens à vendre</h2>\n                    <p class=\"section-subtitle\">Découvrez notre sélection de propriétés premium</p>\n                </div>\n                \n                <div class=\"properties-grid\">\n                    <!-- Carte 1 -->\n                    <div class=\"property-card\">\n                        <div class=\"property-image\">\n                            <img src=\"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=400&h=300&fit=crop\" alt=\"Propriété de luxe moderne\" style=\"width:100%; height:100%; object-fit:cover;\">\n                            <span class=\"property-tag\">À vendre</span>\n                        </div>\n                        <div class=\"property-content\">\n                            <div class=\"property-price\">$1,295,000</div>\n                            <div class=\"property-address\">3455 Av. du Musée</div>\n                            <div class=\"property-details\">\n                                <span><i class=\"fas fa-bed\"></i> 3 chambres</span>\n                                <span><i class=\"fas fa-bath\"></i> 2 salles de bain</span>\n                                <span><i class=\"fas fa-ruler-combined\"></i> 1,850 pi²</span>\n                            </div>\n                            <button class=\"btn-property\">Voir la propriété</button>\n                        </div>\n                    </div>\n                    <!-- Carte 2 -->\n                    <div class=\"property-card\">\n                        <div class=\"property-image\">\n                            <img src=\"https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?w=400&h=300&fit=crop\" alt=\"Appartement de luxe\" style=\"width:100%; height:100%; object-fit:cover;\">\n                            <span class=\"property-tag\">Nouveau</span>\n                        </div>\n                        <div class=\"property-content\">\n                            <div class=\"property-price\">$895,000</div>\n                            <div class=\"property-address\">122 Rue Saint-Paul</div>\n                            <div class=\"property-details\">\n                                <span><i class=\"fas fa-bed\"></i> 4 chambres</span>\n                                <span><i class=\"fas fa-bath\"></i> 2 salles de bain</span>\n                                <span><i class=\"fas fa-ruler-combined\"></i> 2,200 pi²</span>\n                            </div>\n                            <button class=\"btn-property\">Voir la propriété</button>\n                        </div>\n                    </div>\n                    <!-- Carte 3 -->\n                    <div class=\"property-card\">\n                        <div class=\"property-image\">\n                            <img src=\"https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?w=400&h=300&fit=crop\" alt=\"Penthouse de luxe\" style=\"width:100%; height:100%; object-fit:cover;\">\n                            <span class=\"property-tag\">Prestige</span>\n                        </div>\n                        <div class=\"property-content\">\n                            <div class=\"property-price\">$2,450,000</div>\n                            <div class=\"property-address\">1 Place Ville-Marie</div>\n                            <div class=\"property-details\">\n                                <span><i class=\"fas fa-bed\"></i> 2 chambres</span>\n                                <span><i class=\"fas fa-bath\"></i> 2 salles de bain</span>\n                                <span><i class=\"fas fa-ruler-combined\"></i> 2,100 pi²</span>\n                            </div>\n                            <button class=\"btn-property\">Voir la propriété</button>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Marketplace immobilier (e-commerce services) -->\n        <section class=\"marketplace\">\n            <div class=\"container\">\n                <div class=\"section-header\">\n                    <div class=\"section-tag\">\n                        <i class=\"fas fa-store\"></i> MARKETPLACE\n                    </div>\n                    <h2 class=\"section-title\">Marketplace immobilière</h2>\n                    <p class=\"section-subtitle\">Des services premium pour maximiser la valeur de votre bien</p>\n                </div>\n                <div class=\"marketplace-grid\">\n                    <div class=\"service-card\">\n                        <div class=\"service-icon\">📸</div>\n                        <h3>Photo & vidéo drone</h3>\n                        <p>Prise de vue professionnelle avec drone certifié</p>\n                        <div class=\"service-price\">$450</div>\n                        <button class=\"btn-service\">Réserver</button>\n                    </div>\n                    <div class=\"service-card\">\n                        <div class=\"service-icon\">🏠</div>\n                        <h3>Home staging</h3>\n                        <p>Design d\'intérieur pour valoriser votre espace</p>\n                        <div class=\"service-price\">$890</div>\n                        <button class=\"btn-service\">Réserver</button>\n                    </div>\n                    <div class=\"service-card\">\n                        <div class=\"service-icon\">📊</div>\n                        <h3>Évaluation premium</h3>\n                        <p>Analyse comparative approfondie + tendances</p>\n                        <div class=\"service-price\">$199</div>\n                        <button class=\"btn-service\">Commander</button>\n                    </div>\n                    <div class=\"service-card\">\n                        <div class=\"service-icon\">⚖️</div>\n                        <h3>Inspection pré-vente</h3>\n                        <p>Rapport d\'inspection par expert certifié</p>\n                        <div class=\"service-price\">$650</div>\n                        <button class=\"btn-service\">Réserver</button>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Agents -->\n        <section class=\"agents\">\n            <div class=\"container\">\n                <div class=\"section-header\">\n                    <div class=\"section-tag\">\n                        <i class=\"fas fa-user-tie\"></i> EXPERTS LOCAUX\n                    </div>\n                    <h2 class=\"section-title\">Votre expert local</h2>\n                    <p class=\"section-subtitle\">Des courtiers qui connaissent votre quartier sur le bout des doigts</p>\n                </div>\n                <div class=\"agents-grid\">\n                    <div class=\"agent-card\">\n                        <div class=\"agent-photo\">\n                            <img src=\"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=200&h=200&fit=crop\" alt=\"Sophie Bélanger - Courtier immobilier\" style=\"width:100%; height:100%; object-fit:cover;\">\n                        </div>\n                        <div class=\"agent-name\">Sophie Bélanger</div>\n                        <div class=\"agent-title\">Courtier immobilier - Outremont</div>\n                        <div class=\"agent-stats\">\n                            <span><i class=\"fas fa-home\"></i> 124 ventes</span>\n                            <span><i class=\"fas fa-star\"></i> 4.9</span>\n                        </div>\n                        <button class=\"btn-agent\">Contacter</button>\n                    </div>\n                    <div class=\"agent-card\">\n                        <div class=\"agent-photo\">\n                            <img src=\"https://images.unsplash.com/photo-1560250097-0b93528c311a?w=200&h=200&fit=crop\" alt=\"Marc Tremblay - Courtier immobilier\" style=\"width:100%; height:100%; object-fit:cover;\">\n                        </div>\n                        <div class=\"agent-name\">Marc Tremblay</div>\n                        <div class=\"agent-title\">Courtier - Vieux-Montréal</div>\n                        <div class=\"agent-stats\">\n                            <span><i class=\"fas fa-home\"></i> 98 ventes</span>\n                            <span><i class=\"fas fa-star\"></i> 4.8</span>\n                        </div>\n                        <button class=\"btn-agent\">Contacter</button>\n                    </div>\n                    <div class=\"agent-card\">\n                        <div class=\"agent-photo\">\n                            <img src=\"https://images.unsplash.com/photo-1580489944761-15a19d654956?w=200&h=200&fit=crop\" alt=\"Julie Lavoie - Courtier immobilier\" style=\"width:100%; height:100%; object-fit:cover;\">\n                        </div>\n                        <div class=\"agent-name\">Julie Lavoie</div>\n                        <div class=\"agent-title\">Courtier - Westmount</div>\n                        <div class=\"agent-stats\">\n                            <span><i class=\"fas fa-home\"></i> 156 ventes</span>\n                            <span><i class=\"fas fa-star\"></i> 5.0</span>\n                        </div>\n                        <button class=\"btn-agent\">Contacter</button>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Les 8 étapes -->\n        <section class=\"steps-showcase\">\n            <div class=\"container\">\n                <div class=\"section-header\">\n                    <div class=\"section-tag\">\n                        <i class=\"fas fa-chart-line\"></i> PROCESSUS ÉPROUVÉ\n                    </div>\n                    <h2 class=\"section-title\">Vendre en 8 étapes stratégiques</h2>\n                    <p class=\"section-subtitle\">Un processus scientifique, transparent et sans stress</p>\n                </div>\n                <div class=\"steps-container\">\n                    <div class=\"step-block\">\n                        <span class=\"step-number\">01</span>\n                        <div class=\"step-icon\">📋</div>\n                        <h3>Consultation</h3>\n                        <p>Analyse de vos objectifs et visite-conseil</p>\n                    </div>\n                    <div class=\"step-block\">\n                        <span class=\"step-number\">02</span>\n                        <div class=\"step-icon\">🔍</div>\n                        <h3>Évaluation</h3>\n                        <p>Étude comparative du marché local</p>\n                    </div>\n                    <div class=\"step-block\">\n                        <span class=\"step-number\">03</span>\n                        <div class=\"step-icon\">✨</div>\n                        <h3>Préparation</h3>\n                        <p>Home staging et travaux légers</p>\n                    </div>\n                    <div class=\"step-block\">\n                        <span class=\"step-number\">04</span>\n                        <div class=\"step-icon\">📸</div>\n                        <h3>Photo pro</h3>\n                        <p>Visuels haute définition et drone</p>\n                    </div>\n                    <div class=\"step-block\">\n                        <span class=\"step-number\">05</span>\n                        <div class=\"step-icon\">📢</div>\n                        <h3>Marketing</h3>\n                        <p>Diffusion multicanal premium</p>\n                    </div>\n                    <div class=\"step-block\">\n                        <span class=\"step-number\">06</span>\n                        <div class=\"step-icon\">🚪</div>\n                        <h3>Visites</h3>\n                        <p>Portes ouvertes et visites privées</p>\n                    </div>\n                    <div class=\"step-block\">\n                        <span class=\"step-number\">07</span>\n                        <div class=\"step-icon\">🤝</div>\n                        <h3>Négociation</h3>\n                        <p>Stratégie d\'offres et contre-offres</p>\n                    </div>\n                    <div class=\"step-block\">\n                        <span class=\"step-number\">08</span>\n                        <div class=\"step-icon\">🔑</div>\n                        <h3>Clôture</h3>\n                        <p>Accompagnement jusqu\'à la signature</p>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Témoignage -->\n        <section class=\"testimonials-luxury\">\n            <div class=\"container\">\n                <div class=\"testimonial-card-large\">\n                    <div class=\"testimonial-content\">\n                        <span class=\"hero-badge\">TÉMOIGNAGE</span>\n                        <h2>\"Vendu en 12 jours, au-dessus du prix\"</h2>\n                        <p class=\"testimonial-text\">Marie et Philippe ont confié leur propriété de Westmount à notre équipe. Résultat : 12 jours sur le marché, 3 offres et un prix de vente supérieur de 8% à l\'estimation.</p>\n                        <div class=\"testimonial-author\">Marie & Philippe L.</div>\n                        <div class=\"testimonial-location\">Vente - Westmount</div>\n                    </div>\n                    <div class=\"testimonial-image\">\n                        <img src=\"https://images.unsplash.com/photo-1600607687644-c7171b42498f?w=600&h=400&fit=crop\" alt=\"Propriété vendue à Westmount\" style=\"width:100%; height:100%; object-fit:cover;\">\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Formulaire -->\n        <section class=\"contact-premium\">\n            <div class=\"container\">\n                <div class=\"form-premium\">\n                    <h2 class=\"form-title\">Recevez une évaluation gratuite</h2>\n                    <form>\n                        <div class=\"form-row\">\n                            <input type=\"text\" class=\"form-input\" placeholder=\"Prénom\" required>\n                            <input type=\"text\" class=\"form-input\" placeholder=\"Nom\" required>\n                        </div>\n                        <div class=\"form-group\">\n                            <input type=\"email\" class=\"form-input\" placeholder=\"Courriel\" required>\n                        </div>\n                        <div class=\"form-group\">\n                            <input type=\"tel\" class=\"form-input\" placeholder=\"Téléphone\">\n                        </div>\n                        <div class=\"form-group\">\n                            <input type=\"text\" class=\"form-input\" placeholder=\"Adresse de la propriété\">\n                        </div>\n                        <button type=\"submit\" class=\"btn-submit\">Obtenir mon évaluation</button>\n                        <p class=\"form-note\">Sans engagement • Réponse sous 24h</p>\n                    </form>\n                </div>\n            </div>\n        </section>\n\n\n        <!-- Modal pour les détails -->\n        <div id=\"place-modal\" class=\"modal\">\n            <div class=\"modal-content\">\n                <button class=\"close-modal\">&times;</button>\n                <div id=\"modal-content\"></div>\n            </div>\n        </div>\n    </main>\n\n    <!-- Footer -->\n    <footer class=\"site-footer\">\n        <div class=\"container\">\n            <div class=\"footer-links\">\n                <a href=\"#\">Vendre</a>\n                <a href=\"#\">Acheter</a>\n                <a href=\"#\">Propriétés</a>\n                <a href=\"#\">Courtiers</a>\n                <a href=\"#\">Contact</a>\n                <a href=\"#\">Confidentialité</a>\n            </div>\n            <p>© 2026 Royal LePage Real Estate Services. Marque déposée.</p>\n            <p style=\"margin-top: 1rem;\">Toutes les propriétés sont présentées à titre indicatif.</p>\n        </div>\n    </footer>\n\n\n    <!-- Scripts -->\n    <script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.0-alpha1/dist/js/bootstrap.bundle.min.js\"></script>\n    <script src=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.js\"></script>\n   <script src=\"https://goexploriabusiness.com/theme-map.js\"></script>\n   \n</body>', ':root {\n            --primary: #1b4f6b;\n            --primary-dark: #0a2942;\n            --secondary: #00c9b7;\n            --dark: #1a1d28;\n            --light: #f8f9fa;\n            --gray: #6c757d;\n            --light-gray: #e9ecef;\n            --transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.1);\n            --shadow: 0 10px 30px rgba(0, 0, 0, 0.08);\n            --shadow-hover: 0 20px 40px rgba(0, 0, 0, 0.12);\n        }\n\n        body {\n            background-color: #f5f7ff;\n            color: var(--dark);\n            font-family: \'Montserrat\', \'Segoe UI\', system-ui, sans-serif;\n            line-height: 1.6;\n        }\n\n        .container {\n            max-width: 1400px;\n            margin: 0 auto;\n            padding: 0 2rem;\n        }\n\n        /* Navigation */\n        .navbar {\n            background: rgba(255, 255, 255, 0.95);\n            backdrop-filter: blur(10px);\n            position: sticky;\n            top: 0;\n            z-index: 1000;\n            border-bottom: 1px solid rgba(0, 0, 0, 0.05);\n            padding: 1rem 0;\n        }\n\n        .nav-container {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            max-width: 1400px;\n            margin: 0 auto;\n            padding: 0 2rem;\n        }\n\n        .logo {\n            display: flex;\n            align-items: center;\n            gap: 0.5rem;\n        }\n\n        .logo-icon {\n            background: linear-gradient(135deg, #0a2942, #1b4f6b);\n            width: 40px;\n            height: 40px;\n            border-radius: 12px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            color: white;\n            font-weight: 700;\n            font-size: 1.2rem;\n        }\n\n        .logo-text {\n            font-weight: 700;\n            font-size: 1.4rem;\n            color: #0a2942;\n            letter-spacing: -0.02em;\n        }\n\n        .nav-links {\n            display: flex;\n            gap: 2.5rem;\n            align-items: center;\n        }\n\n        .nav-links a {\n            text-decoration: none;\n            color: #2c3e50;\n            font-weight: 500;\n            transition: color 0.2s;\n        }\n\n        .nav-links a:hover {\n            color: #1b4f6b;\n        }\n\n        .nav-cta {\n            background: linear-gradient(135deg, #0a2942, #1b4f6b);\n            color: white !important;\n            padding: 0.6rem 1.5rem;\n            border-radius: 40px;\n            font-weight: 600 !important;\n            text-decoration: none;\n        }\n\n        /* Section Header */\n        .section-header {\n            text-align: center;\n            margin: 60px 0;\n            padding: 0 20px;\n        }\n\n        .section-tag {\n            display: inline-block;\n            background: linear-gradient(90deg, var(--primary), var(--secondary));\n            color: white;\n            padding: 8px 20px;\n            border-radius: 50px;\n            font-size: 0.9rem;\n            font-weight: 600;\n            letter-spacing: 1px;\n            margin-bottom: 20px;\n            box-shadow: var(--shadow);\n        }\n\n        .section-title {\n            font-size: 2.5rem;\n            font-weight: 800;\n            margin-bottom: 15px;\n            background: linear-gradient(90deg, var(--dark), var(--primary));\n            -webkit-background-clip: text;\n            background-clip: text;\n            color: transparent;\n        }\n\n        .section-subtitle {\n            font-size: 1.2rem;\n            color: var(--gray);\n            max-width: 700px;\n            margin: 0 auto;\n        }\n\n        /* Hero Section */\n        .hero {\n            background: linear-gradient(145deg, #f0f5fa 0%, #ffffff 100%);\n            padding: 4rem 0;\n            position: relative;\n        }\n\n        .hero-grid {\n            display: grid;\n            grid-template-columns: 1.2fr 0.8fr;\n            gap: 4rem;\n            align-items: center;\n        }\n\n        .hero-badge {\n            background: rgba(27, 79, 107, 0.1);\n            color: #1b4f6b;\n            padding: 0.4rem 1.2rem;\n            border-radius: 60px;\n            font-size: 0.9rem;\n            font-weight: 600;\n            display: inline-block;\n            margin-bottom: 1.5rem;\n        }\n\n        .hero h1 {\n            font-size: clamp(2.5rem, 5vw, 4rem);\n            font-weight: 800;\n            line-height: 1.1;\n            color: #0a1a2a;\n            margin-bottom: 1.5rem;\n        }\n\n        .hero-highlight {\n            color: #1b4f6b;\n            position: relative;\n            display: inline-block;\n        }\n\n        .hero p {\n            font-size: 1.2rem;\n            color: #4a5a6a;\n            margin-bottom: 2rem;\n            max-width: 550px;\n        }\n\n        .hero-image-container {\n            background: #d9e6f2;\n            border-radius: 40px;\n            overflow: hidden;\n            box-shadow: 0 30px 60px rgba(0, 20, 30, 0.2);\n            aspect-ratio: 4/3;\n        }\n\n        .hero-image-container img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n        }\n\n        .hero-actions {\n            display: flex;\n            gap: 1rem;\n        }\n\n        .btn-primary {\n            background: linear-gradient(135deg, #0a2942, #1b4f6b);\n            color: white;\n            padding: 1rem 2rem;\n            border-radius: 40px;\n            text-decoration: none;\n            font-weight: 600;\n            transition: var(--transition);\n            display: inline-block;\n        }\n\n        .btn-primary:hover {\n            transform: translateY(-3px);\n            box-shadow: 0 10px 25px rgba(27, 79, 107, 0.3);\n        }\n\n        .btn-secondary {\n            background: transparent;\n            color: #1b4f6b;\n            padding: 1rem 2rem;\n            border: 2px solid #1b4f6b;\n            border-radius: 40px;\n            text-decoration: none;\n            font-weight: 600;\n            transition: var(--transition);\n            display: inline-block;\n        }\n\n        .btn-secondary:hover {\n            background: #1b4f6b;\n            color: white;\n        }\n\n        /* Propriétés Section */\n        .properties-section {\n            padding: 5rem 0;\n            background: white;\n        }\n\n        .properties-grid {\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\n            gap: 2rem;\n            margin-top: 2rem;\n        }\n\n        .property-card {\n            background: white;\n            border-radius: 32px;\n            overflow: hidden;\n            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.03);\n            transition: transform 0.3s;\n            border: 1px solid #edf2f7;\n        }\n\n        .property-card:hover {\n            transform: translateY(-8px);\n            box-shadow: 0 25px 50px rgba(27, 79, 107, 0.1);\n        }\n\n        .property-image {\n            height: 240px;\n            background: #cbdae9;\n            position: relative;\n            overflow: hidden;\n        }\n\n        .property-image img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n        }\n\n        .property-tag {\n            position: absolute;\n            top: 1rem;\n            right: 1rem;\n            background: #1b4f6b;\n            color: white;\n            padding: 0.4rem 1rem;\n            border-radius: 40px;\n            font-size: 0.8rem;\n            font-weight: 600;\n            z-index: 2;\n        }\n\n        .property-content {\n            padding: 1.8rem;\n        }\n\n        .property-price {\n            font-size: 1.8rem;\n            font-weight: 700;\n            color: #1b4f6b;\n            margin-bottom: 0.5rem;\n        }\n\n        .property-address {\n            font-weight: 600;\n            font-size: 1.2rem;\n            margin-bottom: 0.5rem;\n        }\n\n        .property-details {\n            display: flex;\n            gap: 1.5rem;\n            margin: 1rem 0;\n            color: #5a6b7a;\n        }\n\n        .property-details span {\n            display: flex;\n            align-items: center;\n            gap: 0.3rem;\n        }\n\n        .btn-property {\n            width: 100%;\n            padding: 1rem;\n            background: #f0f5fa;\n            border: none;\n            border-radius: 60px;\n            font-weight: 600;\n            color: #1b4f6b;\n            cursor: pointer;\n            transition: all 0.2s;\n            margin-top: 1rem;\n        }\n\n        .btn-property:hover {\n            background: #1b4f6b;\n            color: white;\n        }\n\n        /* Section Marketplace */\n        .marketplace {\n            padding: 5rem 0;\n            background: #0a1a2a;\n            color: white;\n        }\n\n        .marketplace .section-header h2,\n        .marketplace .section-header p {\n            color: white;\n        }\n\n        .marketplace-grid {\n            display: grid;\n            grid-template-columns: repeat(4, 1fr);\n            gap: 1.5rem;\n            margin-top: 3rem;\n        }\n\n        .service-card {\n            background: rgba(255, 255, 255, 0.05);\n            backdrop-filter: blur(10px);\n            border: 1px solid rgba(255, 255, 255, 0.1);\n            border-radius: 24px;\n            padding: 2rem 1.5rem;\n            transition: transform 0.2s;\n        }\n\n        .service-card:hover {\n            transform: translateY(-5px);\n            background: rgba(255, 255, 255, 0.08);\n        }\n\n        .service-icon {\n            font-size: 2.5rem;\n            margin-bottom: 1.5rem;\n        }\n\n        .service-price {\n            font-size: 1.5rem;\n            font-weight: 700;\n            margin: 1rem 0;\n            color: #ffd966;\n        }\n\n        .btn-service {\n            background: transparent;\n            border: 2px solid rgba(255, 255, 255, 0.3);\n            color: white;\n            padding: 0.8rem 1.5rem;\n            border-radius: 40px;\n            width: 100%;\n            font-weight: 600;\n            cursor: pointer;\n            transition: all 0.2s;\n        }\n\n        .btn-service:hover {\n            background: white;\n            color: #0a1a2a;\n            border-color: white;\n        }\n\n        /* Section Agents */\n        .agents {\n            padding: 5rem 0;\n            background: white;\n        }\n\n        .agents-grid {\n            display: grid;\n            grid-template-columns: repeat(3, 1fr);\n            gap: 2rem;\n            margin-top: 3rem;\n        }\n\n        .agent-card {\n            text-align: center;\n            background: #f8fbfe;\n            border-radius: 40px;\n            padding: 2rem;\n            transition: var(--transition);\n        }\n\n        .agent-card:hover {\n            transform: translateY(-8px);\n            box-shadow: var(--shadow-hover);\n        }\n\n        .agent-photo {\n            width: 160px;\n            height: 160px;\n            border-radius: 50%;\n            margin: 0 auto 1.5rem;\n            background: #cbdae9;\n            position: relative;\n            overflow: hidden;\n        }\n\n        .agent-photo img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n        }\n\n        .photo-placeholder {\n            width: 100%;\n            height: 100%;\n            background: linear-gradient(145deg, #8fb4d4, #5a7a9a);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            color: white;\n            font-size: 2rem;\n        }\n\n        .agent-name {\n            font-size: 1.4rem;\n            font-weight: 700;\n            margin-bottom: 0.3rem;\n            color: var(--dark);\n        }\n\n        .agent-title {\n            color: #1b4f6b;\n            font-weight: 600;\n            margin-bottom: 1rem;\n        }\n\n        .agent-stats {\n            display: flex;\n            justify-content: center;\n            gap: 1.5rem;\n            margin: 1.5rem 0;\n            color: #5a6b7a;\n        }\n\n        .agent-stats span {\n            display: flex;\n            align-items: center;\n            gap: 0.3rem;\n        }\n\n        .btn-agent {\n            background: #1b4f6b;\n            color: white;\n            border: none;\n            padding: 0.8rem 2rem;\n            border-radius: 40px;\n            font-weight: 600;\n            cursor: pointer;\n            transition: var(--transition);\n            width: 100%;\n        }\n\n        .btn-agent:hover {\n            background: var(--primary-dark);\n            transform: scale(1.02);\n        }\n\n        /* Section 8 étapes */\n        .steps-showcase {\n            padding: 5rem 0;\n            background: linear-gradient(135deg, #f8fbfe 0%, #ffffff 100%);\n        }\n\n        .steps-container {\n            display: grid;\n            grid-template-columns: repeat(4, 1fr);\n            gap: 1.5rem;\n            margin-top: 3rem;\n        }\n\n        .step-block {\n            background: white;\n            border-radius: 30px;\n            padding: 2rem 1.5rem;\n            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.02);\n            border: 1px solid #eef4f9;\n            position: relative;\n            transition: var(--transition);\n        }\n\n        .step-block:hover {\n            transform: translateY(-5px);\n            box-shadow: var(--shadow-hover);\n        }\n\n        .step-number {\n            font-size: 3rem;\n            font-weight: 800;\n            color: rgba(27, 79, 107, 0.1);\n            position: absolute;\n            top: 1rem;\n            right: 1.5rem;\n            line-height: 1;\n        }\n\n        .step-icon {\n            font-size: 2rem;\n            margin-bottom: 1.5rem;\n        }\n\n        .step-block h3 {\n            font-size: 1.3rem;\n            margin-bottom: 0.8rem;\n            color: var(--dark);\n        }\n\n        .step-block p {\n            color: var(--gray);\n            font-size: 0.95rem;\n        }\n\n        /* Section Témoignages */\n        .testimonials-luxury {\n            padding: 5rem 0;\n            background: #fafbfc;\n        }\n\n        .testimonial-card-large {\n            background: white;\n            border-radius: 40px;\n            padding: 3rem;\n            display: grid;\n            grid-template-columns: 1fr 1fr;\n            gap: 3rem;\n            align-items: center;\n            box-shadow: 0 30px 60px rgba(0, 0, 0, 0.03);\n        }\n\n        .testimonial-content h2 {\n            font-size: 2rem;\n            margin: 1rem 0;\n            color: var(--dark);\n        }\n\n        .testimonial-text {\n            font-size: 1.1rem;\n            color: #4a5a6a;\n            margin-bottom: 2rem;\n            line-height: 1.6;\n        }\n\n        .testimonial-author {\n            font-weight: 700;\n            color: var(--dark);\n            margin-bottom: 0.3rem;\n        }\n\n        .testimonial-location {\n            color: #1b4f6b;\n        }\n\n        .testimonial-image {\n            height: 300px;\n            background: #b8d1e5;\n            border-radius: 30px;\n            overflow: hidden;\n        }\n\n        .testimonial-image img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n        }\n\n        /* Formulaire */\n        .contact-premium {\n            padding: 5rem 0;\n            background: white;\n        }\n\n        .form-premium {\n            background: #f8fbfe;\n            border-radius: 50px;\n            padding: 3rem;\n            max-width: 700px;\n            margin: 0 auto;\n            box-shadow: var(--shadow-hover);\n            border: 1px solid #eef4f9;\n        }\n\n        .form-title {\n            font-size: 2rem;\n            margin-bottom: 2rem;\n            color: var(--dark);\n            text-align: center;\n        }\n\n        .form-row {\n            display: grid;\n            grid-template-columns: 1fr 1fr;\n            gap: 1rem;\n            margin-bottom: 1rem;\n        }\n\n        .form-group {\n            margin-bottom: 1.5rem;\n        }\n\n        .form-input {\n            width: 100%;\n            padding: 1.2rem 1.5rem;\n            border: 2px solid #e0e9f0;\n            border-radius: 60px;\n            font-size: 1rem;\n            background: white;\n            transition: all 0.2s;\n            font-family: inherit;\n        }\n\n        .form-input:focus {\n            outline: none;\n            border-color: #1b4f6b;\n            box-shadow: 0 0 0 4px rgba(27, 79, 107, 0.1);\n        }\n\n        .btn-submit {\n            background: linear-gradient(135deg, #0a2942, #1b4f6b);\n            color: white;\n            border: none;\n            padding: 1.2rem 2rem;\n            border-radius: 60px;\n            font-weight: 700;\n            font-size: 1.1rem;\n            cursor: pointer;\n            width: 100%;\n            transition: transform 0.2s;\n            font-family: inherit;\n        }\n\n        .btn-submit:hover {\n            transform: scale(1.02);\n        }\n\n        .form-note {\n            text-align: center;\n            margin-top: 1.5rem;\n            color: #7f8c8d;\n            font-size: 0.9rem;\n        }\n\n        /* Styles pour la carte interactive */\n        .map-section {\n            padding: 5rem 0;\n            background: linear-gradient(135deg, #f8fbfe 0%, #ffffff 100%);\n        }\n\n        .app-container {\n            width: 100%;\n            height: 600px;\n            position: relative;\n            border-radius: 40px;\n            overflow: hidden;\n            box-shadow: var(--shadow-hover);\n            margin: 40px auto;\n            border: 1px solid rgba(0,0,0,0.05);\n        }\n\n        .map-container {\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n        }\n\n        #map {\n            width: 100%;\n            height: 100%;\n            z-index: 1;\n        }\n\n        .sidebar-right {\n            position: absolute;\n            top: 0;\n            right: 0;\n            bottom: 0;\n            width: 350px;\n            background: white;\n            box-shadow: -5px 0 20px rgba(0,0,0,0.1);\n            overflow-y: auto;\n            transform: translateX(0);\n            transition: transform 0.3s ease;\n            z-index: 1000;\n        }\n\n        .sidebar-toggle {\n            position: absolute;\n            top: 20px;\n            right: 370px;\n            z-index: 1001;\n            background: white;\n            border: none;\n            width: 50px;\n            height: 50px;\n            border-radius: 50%;\n            box-shadow: var(--shadow);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            cursor: pointer;\n            transition: var(--transition);\n        }\n\n        .sidebar-toggle:hover {\n            background: var(--primary);\n            color: white;\n        }\n\n        .loading-overlay {\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            background: rgba(255,255,255,0.9);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            z-index: 1002;\n        }\n\n        /* Styles pour les marqueurs immobiliers */\n        .custom-marker {\n            background: transparent;\n            border: none;\n        }\n\n        .marker-icon {\n            width: 40px;\n            height: 40px;\n            border-radius: 50%;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            color: white;\n            font-size: 18px;\n            box-shadow: 0 3px 10px rgba(0,0,0,0.2);\n            transition: all 0.3s ease;\n            cursor: pointer;\n            background: #1b4f6b;\n        }\n\n        .marker-icon:hover {\n            transform: scale(1.1);\n            box-shadow: 0 5px 15px rgba(0,0,0,0.3);\n        }\n\n        .marker-icon.highlighted {\n            transform: scale(1.2);\n            box-shadow: 0 0 0 3px rgba(27, 79, 107, 0.5);\n        }\n\n        .user-marker-icon {\n            width: 50px;\n            height: 50px;\n            background: linear-gradient(135deg, #00c9b7, #1b4f6b);\n            border-radius: 50%;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            color: white;\n            font-size: 22px;\n            box-shadow: 0 3px 15px rgba(0,0,0,0.3);\n            border: 3px solid white;\n            animation: userMarkerPulse 2s infinite;\n        }\n\n        @keyframes userMarkerPulse {\n            0% { transform: scale(1); box-shadow: 0 0 0 0 rgba(27, 79, 107, 0.7); }\n            70% { transform: scale(1.05); box-shadow: 0 0 0 10px rgba(27, 79, 107, 0); }\n            100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(27, 79, 107, 0); }\n        }\n\n        /* Filtres Sidebar */\n        .filters-section {\n            padding: 20px;\n            border-bottom: 1px solid var(--light-gray);\n        }\n\n        .filter-group {\n            margin-bottom: 15px;\n        }\n\n        .filter-group label {\n            display: block;\n            margin-bottom: 5px;\n            font-weight: 500;\n            color: var(--dark);\n        }\n\n        .form-select {\n            width: 100%;\n            padding: 10px;\n            border: 1px solid #ddd;\n            border-radius: 8px;\n            font-size: 0.9rem;\n            transition: var(--transition);\n        }\n\n        .form-select:focus {\n            outline: none;\n            border-color: var(--primary);\n            box-shadow: 0 0 0 3px rgba(27, 79, 107, 0.1);\n        }\n\n        .locate-btn {\n            width: 100%;\n            padding: 12px;\n            background: linear-gradient(90deg, var(--primary), var(--primary-dark));\n            color: white;\n            border: none;\n            border-radius: 8px;\n            font-weight: 500;\n            cursor: pointer;\n            transition: var(--transition);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            gap: 8px;\n        }\n\n        .locate-btn:hover {\n            background: linear-gradient(90deg, var(--primary-dark), var(--primary));\n            transform: translateY(-2px);\n        }\n\n        .stats {\n            text-align: center;\n            padding: 15px;\n            background: var(--light-gray);\n            border-radius: 8px;\n            margin-top: 15px;\n        }\n\n        .places-list {\n            padding: 20px;\n        }\n\n        .place-item {\n            background: white;\n            border-radius: 12px;\n            overflow: hidden;\n            margin-bottom: 20px;\n            box-shadow: 0 3px 10px rgba(0,0,0,0.08);\n            transition: var(--transition);\n            cursor: pointer;\n        }\n\n        .place-item:hover {\n            transform: translateY(-5px);\n            box-shadow: 0 10px 25px rgba(0,0,0,0.15);\n        }\n\n        .place-item.active {\n            border: 2px solid var(--primary);\n            box-shadow: 0 5px 20px rgba(27, 79, 107, 0.3);\n        }\n\n        .place-image {\n            height: 150px;\n            overflow: hidden;\n        }\n\n        .place-image img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n            transition: transform 0.5s ease;\n        }\n\n        .place-item:hover .place-image img {\n            transform: scale(1.05);\n        }\n\n        .place-info {\n            padding: 15px;\n        }\n\n        .place-info h4 {\n            margin: 0 0 10px 0;\n            font-size: 1.2rem;\n            color: var(--dark);\n        }\n\n        .place-category {\n            display: inline-block;\n            padding: 4px 12px;\n            background: var(--primary);\n            color: white;\n            border-radius: 20px;\n            font-size: 0.8rem;\n            font-weight: 500;\n            margin-bottom: 10px;\n        }\n\n        .place-actions {\n            display: flex;\n            gap: 10px;\n        }\n\n        .place-actions button {\n            flex: 1;\n            padding: 8px 12px;\n            border: none;\n            border-radius: 6px;\n            font-size: 0.9rem;\n            cursor: pointer;\n            transition: var(--transition);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            gap: 5px;\n        }\n\n        .view-details-btn {\n            background: var(--primary);\n            color: white;\n        }\n\n        .locate-btn-small {\n            background: var(--light-gray);\n            color: var(--dark);\n        }\n\n        /* Modal */\n        .modal {\n            display: none;\n            position: fixed;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            background: rgba(0,0,0,0.8);\n            z-index: 2000;\n            overflow-y: auto;\n        }\n\n        .modal-content {\n            position: relative;\n            background: white;\n            margin: 50px auto;\n            width: 90%;\n            max-width: 900px;\n            border-radius: 20px;\n            overflow: hidden;\n            animation: modalSlideIn 0.3s ease;\n        }\n\n        @keyframes modalSlideIn {\n            from { transform: translateY(-50px); opacity: 0; }\n            to { transform: translateY(0); opacity: 1; }\n        }\n\n        .close-modal {\n            position: absolute;\n            top: 20px;\n            right: 20px;\n            background: rgba(0,0,0,0.5);\n            color: white;\n            border: none;\n            width: 40px;\n            height: 40px;\n            border-radius: 50%;\n            font-size: 20px;\n            cursor: pointer;\n            z-index: 2001;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            transition: var(--transition);\n        }\n\n        .close-modal:hover {\n            background: rgba(0,0,0,0.8);\n            transform: rotate(90deg);\n        }\n\n        /* Popups Leaflet personnalisés */\n        .leaflet-popup {\n            margin-bottom: 20px;\n        }\n        \n        .leaflet-popup-content-wrapper {\n            border-radius: 12px;\n            box-shadow: 0 5px 20px rgba(0,0,0,0.15);\n            border: 2px solid var(--primary);\n            overflow: hidden;\n        }\n        \n        .leaflet-popup-content {\n            margin: 0;\n            padding: 0;\n            min-width: 280px;\n        }\n\n        .youtube-video-container {\n            position: relative;\n            width: 100%;\n            padding-bottom: 56.25%;\n            height: 0;\n            overflow: hidden;\n            border-radius: 8px;\n            margin: 8px 0;\n            background: #000;\n        }\n        \n        .youtube-video-container iframe {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            border: none;\n        }\n        \n        .youtube-badge {\n            position: absolute;\n            top: 8px;\n            right: 8px;\n            background: rgba(255, 0, 0, 0.9);\n            color: white;\n            padding: 4px 8px;\n            border-radius: 4px;\n            font-size: 10px;\n            font-weight: 600;\n            z-index: 10;\n            display: flex;\n            align-items: center;\n            gap: 4px;\n        }\n\n        /* No results */\n        .no-results {\n            text-align: center;\n            padding: 40px 20px;\n            color: var(--gray);\n        }\n\n        .no-results i {\n            font-size: 3rem;\n            color: #ddd;\n            margin-bottom: 20px;\n        }\n\n        .no-results h4 {\n            margin-bottom: 10px;\n            color: var(--dark);\n        }\n\n        /* Footer */\n        .site-footer {\n            background-color: #1a2632;\n            color: #b0c4d9;\n            padding: 3rem 0;\n            text-align: center;\n        }\n\n        .footer-links {\n            display: flex;\n            justify-content: center;\n            gap: 2rem;\n            margin: 1.5rem 0;\n            flex-wrap: wrap;\n        }\n\n        .footer-links a {\n            color: #b0c4d9;\n            text-decoration: none;\n            transition: color 0.2s;\n        }\n\n        .footer-links a:hover {\n            color: white;\n        }\n\n        /* Responsive */\n        @media (max-width: 1024px) {\n            .steps-container,\n            .marketplace-grid,\n            .agents-grid {\n                grid-template-columns: repeat(2, 1fr);\n            }\n        }\n\n        @media (max-width: 992px) {\n            .hero-grid,\n            .testimonial-card-large {\n                grid-template-columns: 1fr;\n            }\n            \n            .nav-links {\n                display: none;\n            }\n            \n            .sidebar-right {\n                width: 300px;\n            }\n            \n            .sidebar-toggle {\n                right: 320px;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .hero-actions {\n                flex-direction: column;\n            }\n            \n            .form-row {\n                grid-template-columns: 1fr;\n            }\n            \n            .sidebar-right {\n                width: 100%;\n                transform: translateX(100%);\n            }\n            \n            .sidebar-right.active {\n                transform: translateX(0);\n            }\n            \n            .sidebar-toggle {\n                right: 20px;\n            }\n            \n            .app-container {\n                height: 500px;\n            }\n            \n            .steps-container,\n            .marketplace-grid,\n            .agents-grid {\n                grid-template-columns: 1fr;\n            }\n        }', NULL, NULL, NULL, 'https://via.placeholder.com/300x200/8b5cf6/ffffff?text=RLRoyal+LePageVendre', NULL, 3, NULL, '2026-02-16 12:58:36', '2026-03-06 00:15:07', NULL);
INSERT INTO `templates` (`id`, `categorie_id`, `name`, `url`, `description`, `html_content`, `css_content`, `js_content`, `assets_folder`, `assets_data`, `thumbnail`, `metadata`, `user_id`, `website_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(97, NULL, 'Boulangerie Bouchard', NULL, NULL, '<body><!-- ========== HEADER ========== --><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"/><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin=\"\"/><link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600;700&amp;family=Inter:wght@300;400;500;600&amp;display=swap\" rel=\"stylesheet\"/><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css\"/><header class=\"container\"><nav class=\"navbar\"><div class=\"logo\">Boulangerie Bouchard<span>artisan boulanger depuis 1984</span></div><div class=\"nav-links\"><a href=\"#\" id=\"i7jaq\">Pains</a><a href=\"#\">Pâtisseries</a><a href=\"#\">Terroir</a><a href=\"#\">Savoir-faire</a><a href=\"#\">Contact</a></div></nav></header><!-- ========== HERO : accueil chaleureux + image réelle ========== --><section class=\"hero\"><div class=\"container\"><div id=\"iexwt\" class=\"grid-2\"><div class=\"hero-content\"><h1>Une halte gourmande <br/>authentiquement Charlevoisienne</h1><p class=\"sous-titre\">Entrez dans notre boulangerie artisanale c\'est découvrir une gamme de produits régionaux, avec ses pains, ses pâtés croches, ses délicieuses brioches et ses incontournables tartes Grand-mère et au sucre.</p><a type=\"button\" href=\"#\" class=\"btn\">Send</a><a type=\"button\" href=\"#\" id=\"i3jeq\" class=\"btn btn-outline\">Notre histoire</a></div><div><!-- Image réelle boulangerie (Unsplash) --><img src=\"https://images.unsplash.com/photo-1509440159596-0249088772ff?w=1200&amp;auto=format&amp;fit=crop&amp;q=80\" alt=\"Vitrine boulangerie artisanale\" id=\"ix9qt-2\" class=\"img-artisanale\"/><img src=\"data:image/jpeg;base64,\" alt=\"Vitrine boulangerie artisanale\" id=\"ix9qt-2-2\" class=\"img-artisanale\"/></div></div></div></section><!-- ========== SECTION \"NOTRE HAVRE DE PAIN\" (vidéo YouTube iframe) ========== --><section id=\"iv8k7f\"><div id=\"iu9dcb\" class=\"container\"><h2 id=\"io42ji\">RESTONS EN CONTACT</h2><form method=\"get\" id=\"ich9k8\"><div id=\"i5qodq\"><label id=\"ivhe5k\">Full Name</label><input type=\"text\" placeholder=\"John Doe\" id=\"im9rpc\"/></div><div id=\"ijkhqq\"><label id=\"imaraf\">Email Address</label><input type=\"email\" placeholder=\"john@example.com\" id=\"iytaxn\"/></div><div id=\"ind73n\"><label id=\"ik9mpf\">Message</label><textarea placeholder=\"Your message...\" rows=\"5\" id=\"i95qie\"></textarea></div><button type=\"submit\" id=\"itf5tp\">Send Message</button></form></div></section><section><div class=\"container\"><div id=\"is65k\"><span class=\"badge-terroir\">🍞 Le geste traditionnel</span><h2>Découvrez notre Havre de pain</h2><p>Plongez au cœur de notre fournil avec cette vidéo qui montre le façonnage à la main de nos pains de campagne. Un savoir-faire transmis depuis trois générations.</p></div><div id=\"iolk2\" class=\"grid-2\"><iframe allowfullscreen=\"allowfullscreen\" src=\"https://www.youtube.com/embed/YJot6z2wdj4?\" class=\"video-wrapper\">&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;!-- iframe YouTube (vidéo boulangerie réaliste) --&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;iframe allowfullscreen=\"\" src=\"https://www.youtube.com/embed/8Wg_3xV72W0?\" title=\"Fabrication pain artisanal\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;</iframe><div><h3>Des méthodes traditionnelles pour un goût unique</h3><p id=\"irwhl\">Notre pain au levain fermente lentement, développant des arômes complexes. Chaque boule est façonnée à la main et cuite au feu de bois dans notre four rénové.</p><p id=\"ifpeb\"><i id=\"iivoo\" class=\"fas fa-check-circle\"></i> <span>Farine bio moulue sur pierre</span></p><p><i id=\"ixlqc\" class=\"fas fa-check-circle\"></i> <span>Levain naturel sans additif</span></p></div></div></div></section><!-- ========== GRILLE PRODUITS ICONIQUES (pâté croche, brioches, tartes) ========== --><section class=\"bg-tendrel\"><div class=\"container\"><div id=\"ixibd\"><span class=\"badge-terroir\">🧑‍🍳 Spécialités maison</span><h2>Nos incontournables</h2></div><div class=\"grid-3\"><!-- Carte 1 : Pâté croche (image réelle) --><div class=\"card-produit\"><img src=\"data:image/jpeg;base64,\" alt=\"Pâté croche maison\" id=\"ih243\"/><div class=\"card-content\"><h4>Pâté croche</h4><p>Notre recette secrète, mijotée longuement avec des épices douces. Une texture fondante et un goût authentique.</p><div class=\"prix\">9,50 € / pièce</div></div></div><!-- Carte 2 : Brioche tressée --><div class=\"card-produit\"><img src=\"https://images.unsplash.com/photo-1608198093002-ad4e005484ec?w=800&amp;auto=format&amp;fit=crop&amp;q=70\" alt=\"Brioche feuilletée\"/><div class=\"card-content\"><h4>Brioche feuilletée</h4><p>Dorée au beurre d\'Échiré, elle se déchire en fines couches. Parfaite au petit-déjeuner.</p><div class=\"prix\">4,80 €</div></div></div><!-- Carte 3 : Tarte Grand-mère --><div class=\"card-produit\"><img src=\"data:image/jpeg;base64,\" alt=\"Tarte aux pommes traditionnelle\" id=\"iameqh\"/><div class=\"card-content\"><h4>Tarte Grand-mère</h4><p>Pâte sablée croustillante, compote de pommes et une généreuse couche de sucre à la cannelle.</p><div class=\"prix\">22,00 € (6 pers.)</div></div></div></div></div></section><!-- ========== SECTION PRODUITS DU TERROIR & PARTENARIAT ========== --><section><div class=\"container\"><div id=\"ib5pfg\" class=\"grid-2\"><img src=\"data:image/jpeg;base64,\" alt=\"Produits régionaux fromages et confits\" class=\"img-artisanale\"/><div><span class=\"badge-terroir\"><i class=\"fas fa-leaf\"></i> Route des Saveurs de Charlevoix</span><h2>Fier partenaire de La Route des Saveurs de Charlevoix</h2><p>Nous sélectionnons avec soin des fromages affinés, des confits de canard, des rillettes, ketchups maison et autres trésors du terroir. Retrouvez également nos sandwichs et pains-pizzas préparés chaque matin.</p><p id=\"izgehh\"><strong>👉 Comptoir sandwich &amp; sous-marin ouvert du mardi au samedi.</strong></p><a type=\"button\" href=\"#\" id=\"isap1i\" class=\"btn btn-outline\">Voir tous nos produits du terroir</a></div></div></div></section><!-- ========== GALERIE D\'IMAGES RÉELLES (pains artisanaux + détails) ========== --><section class=\"timeline-section\"><div class=\"timeline-container\"><div class=\"timeline-header\"><h2>Notre histoire</h2><p>Les moments clés qui ont façonné notre entreprise.</p></div><div class=\"timeline\"><div class=\"timeline-item\"><div class=\"timeline-dot\"></div><div class=\"timeline-content\"><div class=\"timeline-year\">2015</div><h3 class=\"timeline-title\">Fondation</h3><p class=\"timeline-desc\">Création de l\'entreprise avec une vision innovante du digital.</p></div></div><div class=\"timeline-item\"><div class=\"timeline-dot\"></div><div class=\"timeline-content\"><div class=\"timeline-year\">2018</div><h3 class=\"timeline-title\">Expansion nationale</h3><p class=\"timeline-desc\">Ouverture de 3 agences en France et première centaine de clients.</p></div></div><div class=\"timeline-item\"><div class=\"timeline-dot\"></div><div class=\"timeline-content\"><div class=\"timeline-year\">2021</div><h3 class=\"timeline-title\">Innovation lab</h3><p class=\"timeline-desc\">Lancement de notre laboratoire de recherche et développement.</p></div></div><div class=\"timeline-item\"><div class=\"timeline-dot\"></div><div class=\"timeline-content\"><div class=\"timeline-year\">2024</div><h3 class=\"timeline-title\">International</h3><p class=\"timeline-desc\">Déploiement à l\'international avec des clients dans 15 pays.</p></div></div></div></div></section><section class=\"bg-tendrel\"><div class=\"container\"><div id=\"iavw9c\"><span class=\"badge-terroir\">📸 Voir c\'est craquer</span><h2>L\'œil du boulanger</h2></div><div class=\"grid-4\"><img src=\"data:image/jpeg;base64,\" alt=\"Pain de campagne\" id=\"igm8sf\" class=\"img-artisanale\"/><img src=\"https://images.unsplash.com/photo-1509365465985-25d11c17e812?w=600&amp;auto=format&amp;fit=crop&amp;q=70\" alt=\"Baguette tradition\" id=\"id1lwo\" class=\"img-artisanale\"/><img src=\"data:image/jpeg;base64,\" alt=\"Viennoiseries\" id=\"ivj74n\" class=\"img-artisanale\"/><img src=\"data:image/jpeg;base64,\" alt=\"Tarte au sucre\" id=\"ipqq0g\" class=\"img-artisanale\"/></div><p id=\"infb8z\">Pains de campagne, tradition, viennoiseries feuilletées, tarte au sucre… tout est fait maison.</p></div></section><!-- ========== MINI TÉMOIGNAGE (image avatar + vidéo complice) ========== --><section id=\"i79ish\"><div class=\"container\"><div id=\"iq7k9g\" class=\"grid-2\"><div id=\"iajtvo\"><img src=\"https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=200&amp;auto=format&amp;fit=crop&amp;q=60\" alt=\"cliente souriante\" id=\"i5lgfp\"/><div><p id=\"ie4lxh\"><i id=\"irw2eo\" class=\"fas fa-quote-left\"></i> Leurs tartes Grand-mère me rappellent celles de mon enfance. Un vrai voyage gustatif.</p><strong>— Madeleine T., cliente fidèle</strong></div></div><iframe allowfullscreen=\"allowfullscreen\" id=\"i6jr82\" controls=\"\" src=\"https://www.youtube.com/embed/YJot6z2wdj4?\" class=\"video-wrapper\">&amp;amp;amp;amp;amp;amp;amp;amp;lt;iframe allowfullscreen=\"\" src=\"https://www.youtube.com/embed/-dLz-EfB1CQ?\" title=\"Ambiance boulangerie\"&amp;amp;amp;amp;amp;amp;amp;amp;gt;</iframe></div></div></section><!-- ========== APPEL À VISITE / CONTACT ========== --><section id=\"imyzp7\"><div class=\"container\"><div id=\"iczwq9\" class=\"card-produit\"><div id=\"i25frk\" class=\"grid-2\"><div><h2>Passez nous voir au fournil</h2><p id=\"ioqwmq\">24 rue du Moulin, 7190 Charlevoix — Ouvert du mardi au dimanche de 7h à 19h.</p><a type=\"button\" href=\"#\" title=\"\" class=\"btn\">Envoyer</a></div><img src=\"data:image/jpeg;base64,\" alt=\"devanture boulangerie\" id=\"iiruku\" class=\"img-artisanale\"/></div></div></div><section class=\"insta-section\"><div class=\"insta-container\"><!-- HEADER ÉDITABLE --><div class=\"insta-header\"><div class=\"insta-badge\"><i id=\"id0cx5\" class=\"fab fa-instagram\"></i><span>@notre_compte</span></div><h2>Suivez-nous sur Instagram</h2><p>Découvrez nos coulisses, nos créations et nos inspirations au quotidien.</p></div><!-- GRILLE INSTAGRAM ÉDITABLE --><div class=\"insta-grid\"><!-- POST 1 --><div class=\"insta-card\"><img src=\"data:image/jpeg;base64,\" alt=\"Instagram post\" id=\"i58i86\"/><div class=\"insta-icon\"><i class=\"fab fa-instagram\"></i></div><div class=\"insta-overlay\"><p class=\"likes\"><i class=\"fas fa-heart\"></i> <span>2 345</span> likes</p><p class=\"hashtag\">#instant créatif</p></div></div><!-- POST 2 --><div class=\"insta-card\"><img src=\"data:image/jpeg;base64,\" alt=\"Instagram post\" id=\"ibilzv\"/><div class=\"insta-icon\"><i class=\"fab fa-instagram\"></i></div><div class=\"insta-overlay\"><p class=\"likes\"><i class=\"fas fa-heart\"></i> <span>1 892</span> likes</p><p class=\"hashtag\">#naturelovers</p></div></div><!-- POST 3 --><div class=\"insta-card\"><img src=\"data:image/jpeg;base64,\" alt=\"Instagram post\" id=\"ih9sme\"/><div class=\"insta-icon\"><i class=\"fab fa-instagram\"></i></div><div class=\"insta-overlay\"><p class=\"likes\"><i class=\"fas fa-heart\"></i> <span>3 567</span> likes</p><p class=\"hashtag\">#shoplocal</p></div></div><!-- POST 4 --><div class=\"insta-card\"><img src=\"data:image/webp;base64,\" alt=\"Instagram post\" id=\"ivlemh\"/><div class=\"insta-icon\"><i class=\"fab fa-instagram\"></i></div><div class=\"insta-overlay\"><p class=\"likes\"><i class=\"fas fa-heart\"></i> <span>4 210</span> likes</p><p class=\"hashtag\">#explore</p></div></div><!-- POST 5 --><div class=\"insta-card\"><img src=\"data:image/jpeg;base64,\" alt=\"Instagram post\" id=\"ijfb3m\"/><div class=\"insta-icon\"><i class=\"fab fa-instagram\"></i></div><div class=\"insta-overlay\"><p class=\"likes\"><i class=\"fas fa-heart\"></i> <span>5 678</span> likes</p><p class=\"hashtag\">#vacationmode</p></div></div><!-- POST 6 --><div class=\"insta-card\"><img src=\"https://images.unsplash.com/photo-1444418776041-9c7e33cc5a9c?w=800&amp;auto=format&amp;fit=crop&amp;q=70\" alt=\"Instagram post\" id=\"ijrmly\"/><div class=\"insta-icon\"><i class=\"fab fa-instagram\"></i></div><div class=\"insta-overlay\"><p class=\"likes\"><i class=\"fas fa-heart\"></i> <span>3 921</span> likes</p><p class=\"hashtag\">#creative</p></div></div></div><!-- BOUTON ÉDITABLE --></div></section><section class=\"pinterest-section\"><div class=\"pinterest-container\"><!-- HEADER ÉDITABLE --><div class=\"pinterest-header\"><div class=\"pinterest-badge\"><i id=\"iqaayv\" class=\"fab fa-pinterest\"></i><span>@notre_tableau</span></div><h2>Trouvez l\'inspiration sur Pinterest</h2><p>Des idées, des styles, des ambiances... épinglez vos coups de cœur !</p></div><!-- GRILLE PINTEREST ÉDITABLE --><div class=\"pinterest-grid\"><!-- ÉPINGLE 1 (grande) --><div class=\"pin-card large\"><img src=\"data:image/jpeg;base64,\" alt=\"Pinterest pin\" id=\"ii380k\"/><div class=\"pin-label\"><i id=\"ikwmay\" class=\"fab fa-pinterest\"></i><span>5,2k épingles</span></div></div><!-- ÉPINGLE 2 --><div class=\"pin-card\"><img src=\"data:image/jpeg;base64,\" alt=\"Pinterest\" id=\"ikfavu\"/><div class=\"pin-category\">🍽️ Cuisine</div></div><!-- ÉPINGLE 3 --><div class=\"pin-card\"><img src=\"data:image/jpeg;base64,\" alt=\"Pinterest\" id=\"iwetgd\"/><div class=\"pin-category\">🛋️ Déco</div></div><!-- ÉPINGLE 4 --><div class=\"pin-card\"><img src=\"data:image/jpeg;base64,\" alt=\"Pinterest\" id=\"ijxdwh\"/><div class=\"pin-category\">🌿 Jardin</div></div><!-- ÉPINGLE 5 --><div class=\"pin-card\"><img src=\"data:image/jpeg;base64,\" alt=\"Pinterest\" id=\"i0dd0o\"/><div class=\"pin-category\">👗 Mode</div></div><!-- ÉPINGLE 6 --><div class=\"pin-card\"><div class=\"pin-category\">👜 Accessoires</div></div></div><!-- BOUTON ÉDITABLE --><div class=\"pinterest-cta\"><a type=\"button\" href=\"#\" class=\"pinterest-button\">Send</a></div></div></section><section class=\"facebook-section\"><div class=\"facebook-container\"><!-- HEADER ÉDITABLE --><div class=\"facebook-header\"><div class=\"facebook-badge\"><i id=\"i43z2n\" class=\"fab fa-facebook\"></i><span>/notrepage</span></div><h2>Rejoignez notre communauté Facebook</h2><p>Actualités, événements et échanges avec notre communauté.</p></div><!-- GRILLE POSTS ÉDITABLE --><div class=\"facebook-grid\"><!-- POST 1 --><div class=\"fb-post\"><div class=\"fb-post-header\"><img src=\"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&amp;auto=format&amp;fit=crop&amp;q=60\" alt=\"avatar\" class=\"fb-avatar\"/><div><h4>Notre Page</h4><p>il y a 2 heures</p></div></div><p>Découvrez les coulisses de notre nouveau projet ! 🌟</p><img src=\"data:image/jpeg;base64,\" alt=\"post\" class=\"fb-post-image\"/><div class=\"fb-stats\"><span><i class=\"far fa-heart\"></i> 234</span><span><i class=\"far fa-comment\"></i> 18</span><span><i class=\"far fa-share-square\"></i> 7</span></div></div><!-- POST 2 --><div class=\"fb-post\"><div class=\"fb-post-header\"><img src=\"https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&amp;auto=format&amp;fit=crop&amp;q=60\" alt=\"avatar\" class=\"fb-avatar\"/><div><h4>Notre Page</h4><p>hier</p></div></div><p>Événement spécial cette fin de semaine ! Venez nombreux 🎉</p><img src=\"data:image/jpeg;base64,\" alt=\"event\" class=\"fb-post-image\"/><div class=\"fb-stats\"><span><i class=\"far fa-heart\"></i> 567</span><span><i class=\"far fa-comment\"></i> 42</span><span><i class=\"far fa-share-square\"></i> 15</span></div></div></div><!-- ALBUMS ÉDITABLES --><div class=\"fb-albums-grid\"><div class=\"fb-album\"><img src=\"data:image/jpeg;base64,\" alt=\"album\" id=\"izshm4\"/><div class=\"fb-album-overlay\"><i class=\"fas fa-video\"></i> <span>5 vidéos</span></div></div><div class=\"fb-album\"><img src=\"data:image/jpeg;base64,\" alt=\"album\" id=\"in1oyj\"/><div class=\"fb-album-overlay\"><i class=\"fas fa-images\"></i> <span>24 photos</span></div></div><div class=\"fb-album\"><img src=\"data:image/jpeg;base64,\" alt=\"album\" id=\"ibd6kg\"/><div class=\"fb-album-overlay\"><i class=\"fas fa-calendar\"></i> <span>Événements</span></div></div><div class=\"fb-album\"><img src=\"data:image/jpeg;base64,\" alt=\"album\" id=\"i3u7wa\"/><div class=\"fb-album-overlay\"><i class=\"fas fa-users\"></i> <span>Communauté</span></div></div></div><!-- BOUTON ÉDITABLE --><div class=\"fb-cta\"></div></div></section><section class=\"testimonials-section\"><div class=\"container\"><div class=\"section-header\"><h2 class=\"section-title\">Ce que disent <span class=\"highlight\">nos clients</span></h2><p class=\"section-subtitle\">Découvrez pourquoi nos clients reviennent toujours</p></div><div class=\"testimonials-slider\"><div class=\"testimonial-card\"><div class=\"rating\"><i class=\"fa fa-star\"></i><i class=\"fa fa-star\"></i><i class=\"fa fa-star\"></i><i class=\"fa fa-star\"></i><i class=\"fa fa-star\"></i></div><div class=\"client-info\"><img src=\"https://randomuser.me/api/portraits/women/32.jpg\" alt=\"Marie L.\" class=\"client-avatar\"/><div class=\"client-details\"><h4>Marie L.</h4><p>Client fidèle depuis 2 ans</p></div></div></div><div class=\"testimonial-card\"><div class=\"rating\"><i class=\"fa fa-star\"></i><i class=\"fa fa-star\"></i><i class=\"fa fa-star\"></i><i class=\"fa fa-star\"></i><i class=\"fa fa-star-half-alt\"></i></div><div class=\"client-info\"><img src=\"https://randomuser.me/api/portraits/men/54.jpg\" alt=\"Thomas B.\" class=\"client-avatar\"/><div class=\"client-details\"><h4>Thomas B.</h4><p>Commande chaque semaine</p></div></div></div><div class=\"testimonial-card\"><div class=\"rating\"><i class=\"fa fa-star\"></i><i class=\"fa fa-star\"></i><i class=\"fa fa-star\"></i><i class=\"fa fa-star\"></i><i class=\"fa fa-star\"></i></div><div class=\"client-info\"><img src=\"https://randomuser.me