      const edgeEpsilon = 2;\n            let autoTimer = null;\n            let autoPaused = false;\n\n            const hasInfiniteLoop = () => linksRow.dataset.snbLoopReady === \'1\';\n            const getCycleWidth = () => hasInfiniteLoop() ? (linksRow.scrollWidth / 2) : 0;\n            const normalizeLoopPosition = () => {\n                if (!hasInfiniteLoop()) return;\n                const cycleWidth = getCycleWidth();\n                if (cycleWidth <= 0) return;\n\n                if (linksRow.scrollLeft >= cycleWidth) {\n                    linksRow.scrollLeft = linksRow.scrollLeft - cycleWidth;\n                } else if (linksRow.scrollLeft < 0) {\n                    linksRow.scrollLeft = linksRow.scrollLeft + cycleWidth;\n                }\n            };\n\n            const scrollByStep = (direction) => {\n                if (hasInfiniteLoop()) {\n                    const cycleWidth = getCycleWidth();\n                    if (cycleWidth <= 0) return;\n\n                    if (direction < 0 && linksRow.scrollLeft <= step) {\n                        linksRow.scrollLeft = linksRow.scrollLeft + cycleWidth;\n                    }\n\n                    linksRow.scrollTo({\n                        left: linksRow.scrollLeft + (direction * step),\n                        behavior: \'smooth\'\n                    });\n                    setTimeout(normalizeLoopPosition, 420);\n                    return;\n                }\n\n                const maxLeft = linksRow.scrollWidth - linksRow.clientWidth;\n                if (maxLeft <= 0) return;\n\n                const current = linksRow.scrollLeft;\n\n                if (direction > 0) {\n                    if (current >= maxLeft - edgeEpsilon) {\n                        linksRow.scrollTo({ left: 0, behavior: \'auto\' });\n                        return;\n                    }\n                    linksRow.scrollTo({ left: Math.min(current + step, maxLeft), behavior: \'smooth\' });\n                    return;\n                }\n\n                if (current <= edgeEpsilon) {\n                    linksRow.scrollTo({ left: maxLeft, behavior: \'auto\' });\n                    return;\n                }\n\n                linksRow.scrollTo({ left: Math.max(current - step, 0), behavior: \'smooth\' });\n            };\n\n            const autoTick = () => {\n                if (autoPaused) return;\n                if (hasInfiniteLoop()) {\n                    const cycleWidth = getCycleWidth();\n                    if (cycleWidth <= 0) return;\n                    linksRow.scrollLeft = linksRow.scrollLeft + autoSpeed;\n                    if (linksRow.scrollLeft >= cycleWidth) {\n                        linksRow.scrollLeft = linksRow.scrollLeft - cycleWidth;\n                    }\n                    return;\n                }\n\n                const maxLeft = linksRow.scrollWidth - linksRow.clientWidth;\n                if (maxLeft <= 0) return;\n                const next = linksRow.scrollLeft + autoSpeed;\n                if (next >= maxLeft - edgeEpsilon) {\n                    linksRow.scrollLeft = 0;\n                    return;\n                }\n                linksRow.scrollLeft = next;\n            };\n\n            const startAuto = () => {\n                if (autoTimer) return;\n                autoTimer = setInterval(autoTick, 16);\n            };\n\n            const stopAuto = () => {\n                if (!autoTimer) return;\n                clearInterval(autoTimer);\n                autoTimer = null;\n            };\n\n            if (leftBtn) {\n                leftBtn.addEventListener(\'click\', function () {\n                    scrollByStep(-1);\n                });\n            }\n\n            if (rightBtn) {\n                rightBtn.addEventListener(\'click\', function () {\n                    scrollByStep(1);\n                });\n            }\n\n            nav.addEventListener(\'mouseenter\', function () { autoPaused = true; });\n            nav.addEventListener(\'mouseleave\', function () { autoPaused = false; });\n            nav.addEventListener(\'focusin\', function () { autoPaused = true; });\n            nav.addEventListener(\'focusout\', function () { autoPaused = false; });\n\n                startAuto();\n            document.addEventListener(\'visibilitychange\', function () {\n                if (document.hidden) {\n                    stopAuto();\n                } else {\n                    startAuto();\n                }\n            });\n        };\n\n        navs.forEach(initNav);\n    })();\n\n(function () {\n    var section = document.getElementById(\'vp-chaine\');\n    if (!section) return;\n\n    var destinationData = [{\"continent\":{\"slug\":\"amerique-nord\",\"name\":\"Amérique du Nord\"},\"country\":{\"slug\":\"canada\",\"name\":\"Canada\"},\"provinces\":[{\"slug\":\"quebec\",\"name\":\"Québec\",\"regions\":[\"Région de Québec\",\"Montréal Métro\",\"Mauricie\",\"Gaspésie\",\"Saguenay\"]},{\"slug\":\"ontario\",\"name\":\"Ontario\",\"regions\":[\"Toronto\",\"Ottawa\",\"Niagara\",\"Kingston\",\"Muskoka\"]},{\"slug\":\"alberta\",\"name\":\"Alberta\",\"regions\":[\"Calgary\",\"Edmonton\",\"Banff\",\"Jasper\",\"Red Deer\"]},{\"slug\":\"colombie-britannique\",\"name\":\"Colombie-Britannique\",\"regions\":[\"Vancouver\",\"Victoria\",\"Whistler\",\"Kelowna\",\"Tofino\"]},{\"slug\":\"nouvelle-ecosse\",\"name\":\"Nouvelle-Écosse\",\"regions\":[\"Halifax\",\"Cape Breton\",\"Lunenburg\",\"Annapolis\",\"Yarmouth\"]}]},{\"continent\":{\"slug\":\"europe\",\"name\":\"Europe\"},\"country\":{\"slug\":\"france\",\"name\":\"France\"},\"provinces\":[{\"slug\":\"ile-de-france\",\"name\":\"Île-de-France\",\"regions\":[\"Paris\",\"Versailles\",\"Saint-Denis\",\"Fontainebleau\",\"Meaux\"]},{\"slug\":\"provence\",\"name\":\"Provence\",\"regions\":[\"Marseille\",\"Aix-en-Provence\",\"Cassis\",\"Arles\",\"Avignon\"]},{\"slug\":\"normandie\",\"name\":\"Normandie\",\"regions\":[\"Rouen\",\"Caen\",\"Deauville\",\"Étretat\",\"Le Havre\"]},{\"slug\":\"bretagne\",\"name\":\"Bretagne\",\"regions\":[\"Rennes\",\"Saint-Malo\",\"Quimper\",\"Brest\",\"Vannes\"]},{\"slug\":\"alpes\",\"name\":\"Alpes\",\"regions\":[\"Chamonix\",\"Annecy\",\"Grenoble\",\"Megève\",\"Val d’Isère\"]}]},{\"continent\":{\"slug\":\"afrique\",\"name\":\"Afrique\"},\"country\":{\"slug\":\"maroc\",\"name\":\"Maroc\"},\"provinces\":[{\"slug\":\"casablanca-settat\",\"name\":\"Casablanca-Settat\",\"regions\":[\"Casablanca\",\"Settat\",\"El Jadida\",\"Mohammedia\",\"Berrechid\"]},{\"slug\":\"rabat-sale-kenitra\",\"name\":\"Rabat-Salé-Kénitra\",\"regions\":[\"Rabat\",\"Salé\",\"Kénitra\",\"Skhirat\",\"Témara\"]},{\"slug\":\"marrakech-safi\",\"name\":\"Marrakech-Safi\",\"regions\":[\"Marrakech\",\"Essaouira\",\"Safi\",\"Ouarzazate\",\"Chichaoua\"]},{\"slug\":\"fes-meknes\",\"name\":\"Fès-Meknès\",\"regions\":[\"Fès\",\"Meknès\",\"Ifrane\",\"Sefrou\",\"Taza\"]},{\"slug\":\"souss-massa\",\"name\":\"Souss-Massa\",\"regions\":[\"Agadir\",\"Taroudant\",\"Tiznit\",\"Chtouka\",\"Tata\"]}]},{\"continent\":{\"slug\":\"asie\",\"name\":\"Asie\"},\"country\":{\"slug\":\"japon\",\"name\":\"Japon\"},\"provinces\":[{\"slug\":\"tokyo\",\"name\":\"Tokyo\",\"regions\":[\"Shinjuku\",\"Shibuya\",\"Asakusa\",\"Ueno\",\"Odaiba\"]},{\"slug\":\"osaka\",\"name\":\"Osaka\",\"regions\":[\"Namba\",\"Umeda\",\"Sakai\",\"Tennoji\",\"Minoh\"]},{\"slug\":\"kyoto\",\"name\":\"Kyoto\",\"regions\":[\"Gion\",\"Arashiyama\",\"Fushimi\",\"Uji\",\"Kameoka\"]},{\"slug\":\"hokkaido\",\"name\":\"Hokkaido\",\"regions\":[\"Sapporo\",\"Otaru\",\"Niseko\",\"Hakodate\",\"Furano\"]},{\"slug\":\"okinawa\",\"name\":\"Okinawa\",\"regions\":[\"Naha\",\"Nago\",\"Ishigaki\",\"Miyakojima\",\"Onna\"]}]},{\"continent\":{\"slug\":\"amerique-sud\",\"name\":\"Amérique du Sud\"},\"country\":{\"slug\":\"bresil\",\"name\":\"Brésil\"},\"provinces\":[{\"slug\":\"sao-paulo\",\"name\":\"São Paulo\",\"regions\":[\"Centro\",\"Campinas\",\"Santos\",\"Guarulhos\",\"Ribeirão Preto\"]},{\"slug\":\"rio-de-janeiro\",\"name\":\"Rio de Janeiro\",\"regions\":[\"Copacabana\",\"Ipanema\",\"Niterói\",\"Petrópolis\",\"Barra da Tijuca\"]},{\"slug\":\"bahia\",\"name\":\"Bahia\",\"regions\":[\"Salvador\",\"Ilhéus\",\"Porto Seguro\",\"Feira de Santana\",\"Chapada\"]},{\"slug\":\"parana\",\"name\":\"Paraná\",\"regions\":[\"Curitiba\",\"Londrina\",\"Maringá\",\"Foz do Iguaçu\",\"Ponta Grossa\"]},{\"slug\":\"ceara\",\"name\":\"Ceará\",\"regions\":[\"Fortaleza\",\"Jericoacoara\",\"Sobral\",\"Crato\",\"Canoa Quebrada\"]}]},{\"continent\":{\"slug\":\"oceanie\",\"name\":\"Océanie\"},\"country\":{\"slug\":\"australie\",\"name\":\"Australie\"},\"provinces\":[{\"slug\":\"nouvelle-galles-du-sud\",\"name\":\"Nouvelle-Galles du Sud\",\"regions\":[\"Sydney\",\"Newcastle\",\"Byron Bay\",\"Wollongong\",\"Blue Mountains\"]},{\"slug\":\"victoria\",\"name\":\"Victoria\",\"regions\":[\"Melbourne\",\"Geelong\",\"Great Ocean Road\",\"Ballarat\",\"Bendigo\"]},{\"slug\":\"queensland\",\"name\":\"Queensland\",\"regions\":[\"Brisbane\",\"Gold Coast\",\"Cairns\",\"Townsville\",\"Whitsundays\"]},{\"slug\":\"tasmanie\",\"name\":\"Tasmanie\",\"regions\":[\"Hobart\",\"Launceston\",\"Freycinet\",\"Devonport\",\"Cradle Mountain\"]},{\"slug\":\"australie-occidentale\",\"name\":\"Australie-Occidentale\",\"regions\":[\"Perth\",\"Broome\",\"Margaret River\",\"Albany\",\"Fremantle\"]}]}];\n    var continentSelect = section.querySelector(\'#vp-continent-select\');\n    var countrySelect = section.querySelector(\'#vp-country-select\');\n    var provinceSelect = section.querySelector(\'#vp-province-select\');\n    var regionSelect = section.querySelector(\'#vp-region-select\');\n    var categoryBtns = section.querySelectorAll(\'.products-vedette-v2-filter-btn[data-filter]\');\n    var playlistItems = Array.prototype.slice.call(section.querySelectorAll(\'.video-player-v2-playlist-item\'));\n    var mediaCounter = section.querySelector(\'#mediaCounter\');\n    var playlistVisibleCount = section.querySelector(\'#vpPlaylistVisibleCount\');\n    var iframeEl = section.querySelector(\'#mainVideoPlayerIframe\');\n    var titleEl = section.querySelector(\'#videoTitle\');\n    var descEl = section.querySelector(\'#videoDescription\');\n\n    if (!continentSelect || !countrySelect || !provinceSelect || !regionSelect || !playlistItems.length) return;\n\n    function fillSelect(selectEl, items) {\n        selectEl.innerHTML = items.map(function (item) {\n            return \'<option value=\"\' + item.slug + \'\">\' + item.name + \'</option>\';\n        }).join(\'\');\n    }\n\n    function getActiveCategory() {\n        var active = section.querySelector(\'.products-vedette-v2-filter-btn.active\');\n        return active ? active.getAttribute(\'data-filter\') : \'all\';\n    }\n\n    function getCurrentContinentData() {\n        return destinationData.find(function (entry) {\n            return entry.continent.slug === continentSelect.value;\n        }) || destinationData[0];\n    }\n\n    function getCurrentCountryData() {\n        var continentData = getCurrentContinentData();\n        return continentData.country;\n    }\n\n    function getCurrentProvinces() {\n        return getCurrentContinentData().provinces || [];\n    }\n\n    function getCurrentProvince() {\n        var provinces = getCurrentProvinces();\n        return provinces.find(function (p) { return p.slug === provinceSelect.value; }) || provinces[0];\n    }\n\n    function buildRegionOptions(province) {\n        var regionList = (province && province.regions) ? province.regions : [];\n        return regionList.map(function (name) {\n            return {\n                slug: name.toLowerCase().replace(/[’\']/g, \'\').replace(/\\s+/g, \'-\'),\n                name: name\n            };\n        });\n    }\n\n    function getVisibleItems() {\n        return playlistItems.filter(function (item) {\n            return item.style.display !== \'none\';\n        });\n    }\n\n    function playItem(item) {\n        if (!item || !iframeEl) return;\n\n        playlistItems.forEach(function (it) { it.classList.remove(\'active\'); });\n        item.classList.add(\'active\');\n\n        var src = item.getAttribute(\'data-src\') || \'\';\n        var title = item.getAttribute(\'data-title\') || \'\';\n        var description = item.getAttribute(\'data-description\') || \'\';\n\n        if (src) {\n            iframeEl.src = src;\n        }\n\n        if (titleEl) {\n            titleEl.textContent = title;\n        }\n        if (descEl) {\n            descEl.textContent = description;\n        }\n\n        syncCounters();\n    }\n\n    function syncCounters() {\n        var visibleItems = getVisibleItems();\n        var activeIndex = visibleItems.findIndex(function (item) {\n            return item.classList.contains(\'active\');\n        });\n\n        if (playlistVisibleCount) {\n            playlistVisibleCount.textContent = String(visibleItems.length);\n        }\n\n        if (mediaCounter) {\n            if (!visibleItems.length) {\n                mediaCounter.textContent = \'0 / 0\';\n            } else {\n                mediaCounter.textContent = String((activeIndex >= 0 ? activeIndex : 0) + 1) + \' / \' + String(visibleItems.length);\n            }\n        }\n    }\n\n    function applyPlaylistFilters() {\n        var country = countrySelect.value;\n        var category = getActiveCategory();\n\n        playlistItems.forEach(function (item) {\n            var itemCountry = item.getAttribute(\'data-country\') || \'\';\n            var itemCategory = item.getAttribute(\'data-category\') || \'\';\n            var show = (itemCountry === country) && (category === \'all\' || itemCategory === category);\n            item.style.display = show ? \'\' : \'none\';\n            if (!show) {\n                item.classList.remove(\'active\');\n            }\n        });\n\n        var visibleItems = getVisibleItems();\n        if (visibleItems.length > 0) {\n            playItem(visibleItems[0]);\n        }\n\n        syncCounters();\n    }\n\n    function refreshRegions() {\n        var province = getCurrentProvince();\n        var regions = buildRegionOptions(province).slice(0, 5);\n        fillSelect(regionSelect, regions);\n    }\n\n    function refreshProvinces() {\n        var provinces = getCurrentProvinces().map(function (p) {\n            return { slug: p.slug, name: p.name };\n        }).slice(0, 5);\n\n        fillSelect(provinceSelect, provinces);\n        refreshRegions();\n    }\n\n    function refreshCountryAndBelow() {\n        var country = getCurrentCountryData();\n        fillSelect(countrySelect, [{ slug: country.slug, name: country.name }]);\n        refreshProvinces();\n        applyPlaylistFilters();\n    }\n\n    fillSelect(continentSelect, destinationData.map(function (entry) {\n        return { slug: entry.continent.slug, name: entry.continent.name };\n    }));\n\n    continentSelect.addEventListener(\'change\', refreshCountryAndBelow);\n    countrySelect.addEventListener(\'change\', applyPlaylistFilters);\n    provinceSelect.addEventListener(\'change\', refreshRegions);\n\n    categoryBtns.forEach(function (btn) {\n        btn.addEventListener(\'click\', function () {\n            categoryBtns.forEach(function (b) { b.classList.remove(\'active\'); });\n            btn.classList.add(\'active\');\n            applyPlaylistFilters();\n        });\n    });\n\n    playlistItems.forEach(function (item) {\n        item.addEventListener(\'click\', function () {\n            playItem(item);\n            setTimeout(syncCounters, 0);\n        });\n    });\n\n    refreshCountryAndBelow();\n})();', 'builder', 'grapesjs', NULL, 'fa-cube', 10, 1, '2026-07-13 12:20:18', '2026-07-22 15:08:59');
INSERT INTO `welcome_sections` (`id`, `zone_id`, `name`, `slug`, `view`, `html_content`, `css_content`, `js_content`, `content_source`, `editor`, `settings`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(2, 1, 'Carrousel de visionnage', 'medias-espace-mediaviewingcarousel', 'welcome-home.components.espace_media.ViewingCarousel', '<section id=\"my-tube\" class=\"gxt-section\">\n\n    \n    <div class=\"resto-header-block\">\n\n        <div class=\"resto-header-main\">\n\n            \n            <div class=\"resto-header-logo-left\" style=\"display:none;\">\n                <a href=\"#\" class=\"resto-accord-btn\" title=\"GoExploria\">\n                    <div class=\"logo-wrapper\">\n                        <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/logo.png\" alt=\"GoExploria\">\n                    </div>\n                    <span class=\"resto-accord-btn-label\">GoExploria</span>\n                    <span class=\"resto-accord-btn-cta\">\n                        <i class=\"fas fa-external-link-alt\"></i> Visit\n                    </span>\n                </a>\n            </div>\n\n            \n            <div class=\"resto-header-center\">\n                <div class=\"gxt-header-brand gxt-header-brand--hero\">\n                    <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/GO-EXPLORIA-MY-TUBE.png\" alt=\"GoExploria MyTUBE\" class=\"gxt-logo\">\n                </div>\n                <h1 class=\"resto-header-title\">GOEXPLORIA MYTUBE</h1>\n                <p class=\"resto-header-subtitle\">\n                    Films · Documentaries · Outdoors · Gastronomy — Explore Quebec in images with the official GoExploria video channel.\n                </p></div>\n\n            \n            \n            <div class=\"resto-header-logo-right\">\n                \n                <a href=\"https://goexploriabusiness.com/page-videos\" title=\"Learn more\" target=\"_blank\" rel=\"noopener noreferrer\">\n                    <!-- <i class=\"fas fa-circle-info\"></i>\n                    <span>Go Next Level</span> -->\n                    <img\n                    class=\"bt-next-level-image\"\n                    src=\"https://goexploriabusiness.com/images/Next-level.png\"\n                    alt=\"Next Level\"\n                    loading=\"lazy\"\n                >\n                </a>\n            </div>\n\n        </div>\n            <nav class=\"snb-bar\" data-snb-media-nav=\"1\" aria-label=\"Section navigation\">\n    <div class=\"snb-inner\">\n        <ul class=\"snb-links\">\n            <li>\n                <a href=\"#business-tourism\" class=\"snb-link\">\n                    <i class=\"fas fa-briefcase\"></i>\n                    <span>TOURISM AND BUSINESS AREAS</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#geo-carte-videos\" class=\"snb-link\">\n                    <i class=\"fas fa-globe\"></i>\n                    <span>GEO-MAP-VIDEOS SPACE</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#vp-chaine\" class=\"snb-link\">\n                    <i class=\"fas fa-film\"></i>\n                    <span>VIDEO CHANNEL SPACES</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#my-tube\" class=\"snb-link\">\n                    <i class=\"fas fa-videos\"></i>\n                    <span>MY-TUBE SPACES</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#go-tik-tok\" class=\"snb-link\">\n                    <i class=\"fas fa-tiktok\"></i>\n                    <span>ESPACES GO-TIK-TOK</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#photos\" class=\"snb-link\">\n                    <i class=\"fas fa-camera\"></i>\n                    <span>PHOTO AREAS</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#slideshow\" class=\"snb-link\">\n                    <i class=\"fas fa-images\"></i>\n                    <span>MULTIPLE SLIDE-SHOW SPACES</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#section-vedettes\" class=\"snb-link\">\n                    <i class=\"fas fa-language\"></i>\n                    <span>MULTILINGUAL SPACES</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#reseaux-sociaux\" class=\"snb-link\">\n                    <i class=\"fas fa-share-alt\"></i>\n                    <span>SOCIAL NETWORK AREAS</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#avis-clients\" class=\"snb-link\">\n                    <i class=\"fas fa-star\"></i>\n                    <span>CUSTOMER REVIEW AREAS</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#espace-templates\" class=\"snb-link\">\n                    <i class=\"fas fa-layer-group\"></i>\n                    <span>ESPACES TEMPLATES</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#espace-mail-marketing\" class=\"snb-link\">\n                    <i class=\"fas fa-envelope\"></i>\n                    <span>ESPACES MAIL MARKETING</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#espace-chat\" class=\"snb-link\">\n                    <i class=\"fas fa-comments\"></i>\n                    <span>CAT MODULE SPACES</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#espace-blog\" class=\"snb-link\">\n                    <i class=\"fas fa-rss\"></i>\n                    <span>BLOG AREAS</span>\n                </a>\n            </li>\n        </ul>\n        <div class=\"snb-scroll-controls\" aria-label=\"Navigation horizontale\">\n            <button type=\"button\" class=\"snb-scroll-btn snb-scroll-left\" aria-label=\"Defiler vers la gauche\">\n                <i class=\"fas fa-chevron-left\"></i>\n            </button>\n            <button type=\"button\" class=\"snb-scroll-btn snb-scroll-right\" aria-label=\"Defil