         nav.addEventListener(\'focusin\', function () { autoPaused = true; });\n            nav.addEventListener(\'focusout\', function () { autoPaused = false; });\n\n                startAuto();\n            document.addEventListener(\'visibilitychange\', function () {\n                if (document.hidden) {\n                    stopAuto();\n                } else {\n                    startAuto();\n                }\n            });\n        };\n\n        navs.forEach(initNav);\n    })();\n\n(function () {\n    var videos  = [{\"id\":1,\"ytid\":\"xPPLbEFbCAo\",\"thumb\":\"https:\\/\\/images.unsplash.com\\/photo-1467810563316-b5476525c0f9?w=400\\u0026h=700\\u0026fit=crop\",\"user\":\"goexploria.official\",\"handle\":\"@goexploria.official\",\"date\":\"4-9\",\"views\":\"253.4K\",\"likes\":\"8 160\",\"comments\":\"1 554\",\"saves\":\"858\",\"caption\":\"Gala Saint-Sylvestre 2026 \\u2014 La soir\\u00e9e de r\\u00eave \\u00e0 Montr\\u00e9al \\ud83c\\udf89\\ud83e\\udd42 #GoExploria #Montr\\u00e9al #NewYear\",\"sound\":\"original sound - GoExploria\",\"overlay\":\"New Year’s Eve Gala\"},{\"id\":2,\"ytid\":\"xPPLbEFbCAo\",\"thumb\":\"https:\\/\\/images.unsplash.com\\/photo-1536935338788-846bb9981813?w=400\\u0026h=700\\u0026fit=crop\",\"user\":\"goexploria.aventure\",\"handle\":\"@goexploria.aventure\",\"date\":\"3-31\",\"views\":\"5.5M\",\"likes\":\"33 400\",\"comments\":\"2 100\",\"saves\":\"4 200\",\"caption\":\"Baleines \\u00e0 Tadoussac \\ud83d\\udc0b Un moment magique au Saguenay #Qu\\u00e9bec #Nature #Baleines\",\"sound\":\"original sound - GoExploria Aventure\",\"overlay\":\"\"},{\"id\":3,\"ytid\":\"xPPLbEFbCAo\",\"thumb\":\"https:\\/\\/images.unsplash.com\\/photo-1551698618-1dfe5d97d256?w=400\\u0026h=700\\u0026fit=crop\",\"user\":\"goexploria.ski\",\"handle\":\"@goexploria.ski\",\"date\":\"3-28\",\"views\":\"147.1K\",\"likes\":\"12 340\",\"comments\":\"987\",\"saves\":\"2 345\",\"caption\":\"Mont-Tremblant en hiver \\u00e2\\u203a\\u00b7\\u00ef\\u00b8\\u008f Les