:\"67 000\",\"comments\":\"4 500\",\"saves\":\"12 000\",\"caption\":\"Cabane \\u00e0 sucre authentique \\ud83c\\udf41 La vraie exp\\u00e9rience qu\\u00e9b\\u00e9coise #\\u00c9rable #Tradition\",\"sound\":\"original sound - GoExploria Cabane\",\"overlay\":\"\"},{\"id\":8,\"ytid\":\"xPPLbEFbCAo\",\"thumb\":\"https:\\/\\/images.unsplash.com\\/photo-1547592180-85f173990554?w=400\\u0026h=700\\u0026fit=crop\",\"user\":\"goexploria.road\",\"handle\":\"@goexploria.road\",\"date\":\"3-10\",\"views\":\"33.4M\",\"likes\":\"89 000\",\"comments\":\"6 200\",\"saves\":\"18 500\",\"caption\":\"3 POV\\u0027s : Road Trip Charlevoix de Qu\\u00e9bec \\u00e0 Baie-Saint-Paul \\ud83d\\ude97\",\"sound\":\"original sound - GoExploria Road\",\"overlay\":\"3 POV\\u0027s:\\nCharlevoix\\nRoad Trip\"},{\"id\":9,\"ytid\":\"xPPLbEFbCAo\",\"thumb\":\"https:\\/\\/images.unsplash.com\\/photo-1558618666-fcd25c85cd64?w=400\\u0026h=700\\u0026fit=crop\",\"user\":\"goexploria.carnaval\",\"handle\":\"@goexploria.carnaval\",\"date\":\"3-5\",\"views\":\"134.2K\",\"likes\":\"22 100\",\"comments\":\"1 890\",\"saves\":\"3 400\",\"caption\":\"brb learning how to make tire d\\u0027\\u00e9rable so I can catch up to @goexploria.gastro \\ud83d\\ude04 #TheDiscoverList #Qu\\u00e9bec\",\"sound\":\"original sound - GoExploria Carnival\",\"overlay\":\"\"},{\"id\":10,\"ytid\":\"xPPLbEFbCAo\",\"thumb\":\"https:\\/\\/images.unsplash.com\\/photo-1544025162-d76694265947?w=400\\u0026h=700\\u0026fit=crop\",\"user\":\"goexploria.events\",\"handle\":\"@goexploria.events\",\"date\":\"3-1\",\"views\":\"148.3K\",\"likes\":\"18 400\",\"comments\":\"2 300\",\"saves\":\"4 100\",\"caption\":\"You Asked, We Listened: GoExploria Radio \\ud83c\\udf99\\ufe0f #GoExploria #Radio\",\"sound\":\"original sound - GoExploria Events\",\"overlay\":\"You Asked,\\nWe Listened:\\nGoExploria Radio\"},{\"id\":11,\"ytid\":\"xPPLbEFbCAo\",\"thumb\":\"https:\\/\\/images.unsplash.com\\/photo-1550966871-3ed3cdb5ed0c?w=400\\u0026h=700\\u0026fit=crop\",\"user\":\"goexploria.destinations\",\"handle\":\"@goexploria.destinations\",\"date\":\"2-28\",\"views\":\"19M\",\"likes\":\"48 000\",\"comments\":\"3 700\",\"saves\":\"9 600\",\"caption\":\"Les \\u00celes-de-la-Madeleine - Paradis sauvage du Qu\\u00e9bec \\ud83c\\udf0a #\\u00celesdelaMadeleine #Qu\\u00e9bec\",\"sound\":\"original sound - GoExploria Destinations\",\"overlay\":\"\"},{\"id\":12,\"ytid\":\"xPPLbEFbCAo\",\"thumb\":\"https:\\/\\/images.unsplash.com\\/photo-1510812431401-41d2bd2722f3?w=400\\u0026h=700\\u0026fit=crop\",\"user\":\"goexploria.gastro\",\"handle\":\"@goexploria.gastro\",\"date\":\"2-24\",\"views\":\"151.6K\",\"likes\":\"25 300\",\"comments\":\"1 980\",\"saves\":\"5 700\",\"caption\":\"Accord Mets \\u0026 Vins masterclass avec notre sommelier \\ud83c\\udf77 #Gastronomie #Vins #Qu\\u00e9bec\",\"sound\":\"original sound - GoExploria Gastro\",\"overlay\":\"\"}];\n    var section = document.getElementById(\'goexploria-tiktok\');\n    var cards   = document.querySelectorAll(\'#ttkGrid .ttk-card\');\n    var modal   = document.getElementById(\'ttkModal\');\n    var iframe  = document.getElementById(\'ttkModalIframe\');\n    var current = 0;\n    var activeFilter = \'all\';\n\n    function applyGridFilter() {\n        cards.forEach(function (card) {\n            var category = card.getAttribute(\'data-category\') || \'all\';\n            var visible = (activeFilter === \'all\' || category === activeFilter);\n            card.style.display = visible ? \'\' : \'none\';\n        });\n    }\n\n    function openModal(index) {\n        current = index;\n        var v = videos[index];\n        iframe.src = \'https://www.youtube.com/embed/\' + v.ytid + \'?autoplay=1&rel=0&enablejsapi=1\';\n        document.getElementById(\'ttkPanelUser\').textContent    = v.user;\n        document.getElementById(\'ttkPanelDate\').textContent    = v.date;\n        document.getElementById(\'ttkPanelCaption\').textContent = v.caption;\n        document.getElementById(\'ttkPanelSound\').textContent   = v.sound;\n        document.getElementById(\'ttkPanelLikes\').textContent   = v.likes;\n        document.getElementById(\'ttkPanelComments\').textContent= v.comments;\n        document.getElementById(\'ttkPanelSaves\').textContent   = v.saves;\n        document.getElementById(\'ttkTabCommentCount\').textContent = \'(\' + v.comments + \')\';\n        document.getElementById(\'ttkPanelUrl\').textContent     = \'https://goexploria.com/tiktok/video/\' + v.id;\n        modal.classList.add(\'ttk-modal--open\');\n        document.body.style.overflow = \'hidden\';\n    }\n\n    function closeModal() {\n        iframe.src = \'\';\n        modal.classList.remove(\'ttk-modal--open\');\n        document.body.style.overflow = \'\';\n    }\n\n    function navigate(dir) {\n        current = (current + dir + videos.length) % videos.length;\n        iframe.src = \'\';\n        setTimeout(function () { openModal(current); }, 50);\n    }\n\n    cards.forEach(function (card) {\n        card.addEventListener(\'click\', function () { openModal(parseInt(card.getAttribute(\'data-index\'))); });\n        card.addEventListener(\'keydown\', function (e) { if (e.key === \'Enter\' || e.key === \' \') { e.preventDefault(); openModal(parseInt(card.getAttribute(\'data-index\'))); } });\n    });\n\n    if (section) {\n        section.querySelectorAll(\'.ttk-filter-btn\').forEach(function (btn) {\n            btn.addEventListener(\'click\', function () {\n                section.querySelectorAll(\'.ttk-filter-btn\').forEach(function (b) { b.classList.remove(\'active\'); });\n                btn.classList.add(\'active\');\n                activeFilter = btn.getAttribute(\'data-filter\') || \'all\';\n                applyGridFilter();\n            });\n        });\n    }\n\n    document.getElementById(\'ttkModalClose\').addEventListener(\'click\', closeModal);\n    document.getElementById(\'ttkNavPrev\').addEventListener(\'click\', function () { navigate(-1); });\n    document.getElementById(\'ttkNavNext\').addEventListener(\'click\', function () { navigate(1); });\n\n    modal.addEventListener(\'click\', function (e) { if (e.target === modal) closeModal(); });\n\n    document.addEventListener(\'keydown\', function (e) {\n        if (!modal.classList.contains(\'ttk-modal--open\')) return;\n        if (e.key === \'Escape\') closeModal();\n        if (e.key === \'ArrowUp\')   navigate(-1);\n        if (e.key === \'ArrowDown\') navigate(1);\n    });\n\n    document.getElementById(\'ttkLikeBtn\').addEventListener(\'click\', function () {\n        this.classList.toggle(\'ttk-liked\');\n    });\n\n    var ptabs = document.querySelectorAll(\'.ttk-ptab\');\n    ptabs.forEach(function (tab) {\n        tab.addEventListener(\'click\', function () {\n            ptabs.forEach(function (t) { t.classList.remove(\'active\'); });\n            tab.classList.add(\'active\');\n        });\n    });\n    applyGridFilter();\n})();', 'builder', 'grapesjs', NULL, 'fa-cube', 30, 1, '2026-07-13 12:20:18', '2026-07-13 12:24:53');
INSERT INTO `welcome_sections` (`id`, `zone_id`, `name`, `slug`, `view`, `html_content`, `css_content`, `js_content`, `content_source`, `editor`, `settings`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(4, 1, 'Carrousel galerie', 'medias-espace-mediagalleriecaroussel', 'welcome-home.components.espace_media.GallerieCaroussel', '<section id=\"photos\" class=\"gic-section\">\n    <div class=\"gic-container\">\n        <div class=\"resto-header-block\">\n            <div class=\"resto-header-main\">\n                <div class=\"resto-header-logo-left\">\n                    <a href=\"#\" class=\"resto-accord-btn\" title=\"GoExploria\">\n                        <div class=\"logo-wrapper\"><img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/logo.png\" alt=\"GoExploria\"></div>\n                        <span class=\"resto-accord-btn-label\">GoExploria</span>\n                        <span class=\"resto-accord-btn-cta\"><i class=\"fas fa-external-link-alt\"></i> Visit</span>\n                    </a>\n                </div>\n\n                <div class=\"resto-header-center\">\n                    <h1 class=\"resto-header-title\">PHOTO AREAS</h1>\n                    <p class=\"resto-header-subtitle\">Destinations et choix des catégories · Photos avec tags international · Création des catégories de galeries.</p></div>\n\n                \n            <div class=\"resto-header-logo-right\">\n                \n                <a href=\"https://goexploriabusiness.com/page-galerie\" title=\"Learn more\" target=\"_blank\" rel=\"noopener noreferrer\">\n                    <!-- <i class=\"fas fa-circle-info\"></i>\n                    <span>Go Next Level</span> -->\n                    <img\n                    class=\"bt-next-level-image\"\n                    src=\"https://goexploriabusiness.com/images/Next-level.png\"\n                    alt=\"Next Level\"\n                    loading=\"lazy\"\n                >\n                </a>\n            </div>\n            </div>\n            <nav class=\"snb-bar\" data-snb-media-nav=\"1\" aria-label=\"Section navigation\">\n    <div class=\"snb-inner\">\n        <ul class=\"snb-links\">\n            <li