on (link) {\n                    const targetLeft = link.offsetLeft - (linksRow.clientWidth / 2) + (link.clientWidth / 2);\n                    const maxLeft = linksRow.scrollWidth - linksRow.clientWidth;\n                    const nextLeft = Math.max(0, Math.min(targetLeft, maxLeft));\n                    linksRow.scrollTo({ left: nextLeft, behavior: \'smooth\' });\n                };\n\n                const setActive = function (link, shouldCenter = true) {\n                    links.forEach(function (item) { item.classList.remove(\'active\'); });\n                    link.classList.add(\'active\');\n                    if (shouldCenter) centerLink(link);\n                };\n\n                links.forEach(function (link) {\n                    link.addEventListener(\'click\', function () {\n                        setActive(link, true);\n                    });\n                });\n\n                const activateFromHash = function (shouldCenter = false) {\n                    const hash = window.location.hash;\n                    const found = links.find(function (link) { return link.getAttribute(\'href\') === hash; });\n                    if (found) {\n                        setActive(found, shouldCenter);\n                        return true;\n                    }\n                    return false;\n                };\n\n                if (!activateFromHash(false)) {\n                    setActive(links[0], false);\n                }\n\n                window.addEventListener(\'hashchange\', function () {\n                    activateFromHash(true);\n                });\n\n                const step = 320;\n                const autoSpeed = 1.4;\n                const edgeEpsilon = 2;\n                let autoTimer = null;\n                let autoPaused = false;\n\n                const hasInfiniteLoop = function () {\n                    return linksRow.dataset.snbLoopReady === \'1\';\n                };\n\n                const getCycleWidth = function () {\n                    return hasInfiniteLoop() ? (linksRow.scrollWidth / 2) : 0;\n                };\n\n                const normalizeLoopPosition = function () {\n                    if (!hasInfiniteLoop()) return;\n                    const cycleWidth = getCycleWidth();\n                    if (cycleWidth <= 0) return;\n\n                    if (linksRow.scrollLeft >= cycleWidth) {\n                        linksRow.scrollLeft = linksRow.scrollLeft - cycleWidth;\n                    } else if (linksRow.scrollLeft < 0) {\n                        linksRow.scrollLeft = linksRow.scrollLeft + cycleWidth;\n                    }\n                };\n\n                const scrollByStep = function (direction) {\n                    if (hasInfiniteLoop()) {\n                        const cycleWidth = getCycleWidth();\n                        if (cycleWidth <= 0) return;\n\n                        if (direction < 0 && linksRow.scrollLeft <= step) {\n                            linksRow.scrollLeft = linksRow.scrollLeft + cycleWidth;\n                        }\n\n                        linksRow.scrollTo({\n                            left: linksRow.scrollLeft + (direction * step),\n                            behavior: \'smooth\'\n                        });\n                        setTimeout(normalizeLoopPosition, 420);\n                        return;\n                    }\n\n                    const maxLeft = linksRow.scrollWidth - linksRow.clientWidth;\n                    if (maxLeft <= 0) return;\n\n                    const current = linksRow.scrollLeft;\n\n                    if (direction > 0) {\n                        if (current >= maxLeft - edgeEpsilon) {\n                            linksRow.scrollTo({ left: 0, behavior: \'auto\' });\n                            return;\n                        }\n                        linksRow.scrollTo({ left: Math.min(current + step, maxLeft), behavior: \'smooth\' });\n                        return;\n                    }\n\n                    if (current <= edgeEpsilon) {\n                        linksRow.scrollTo({ left: maxLeft, behavior: \'auto\' });\n                        return;\n                    }\n\n                    linksRow.scrollTo({ left: Math.max(current - step, 0), behavior: \'smooth\' });\n                };\n\n                const autoTick = function () {\n                    if (autoPaused) return;\n                    if (hasInfiniteLoop()) {\n                        const cycleWidth = getCycleWidth();\n                        if (cycleWidth <= 0) return;\n                        linksRow.scrollLeft = linksRow.scrollLeft + autoSpeed;\n                        if (linksRow.scrollLeft >= cycleWidth) {\n                            linksRow.scrollLeft = linksRow.scrollLeft - cycleWidth;\n                        }\n                        return;\n                    }\n\n                    const maxLeft = linksRow.scrollWidth - linksRow.clientWidth;\n                    if (maxLeft <= 0) return;\n                    const next = linksRow.scrollLeft + autoSpeed;\n                    if (next >= maxLeft - edgeEpsilon) {\n                        linksRow.scrollLeft = 0;\n                        return;\n                    }\n                    linksRow.scrollLeft = next;\n                };\n\n                const startAuto = function () {\n                    if (autoTimer) return;\n                    autoTimer = setInterval(autoTick, 16);\n                };\n\n                const stopAuto = function () {\n                    if (!autoTimer) return;\n                    clearInterval(autoTimer);\n                    autoTimer = null;\n                };\n\n                if (leftBtn) {\n                    leftBtn.addEventListener(\'click\', function () {\n                        scrollByStep(-1);\n                    });\n                }\n\n                if (rightBtn) {\n                    rightBtn.addEventListener(\'click\', function () {\n                        scrollByStep(1);\n                    });\n                }\n\n                nav.addEventListener(\'mouseenter\', function () { autoPaused = true; });\n                nav.addEventListener(\'mouseleave\', function () { autoPaused = false; });\n                nav.addEventListener(\'focusin\', function () { autoPaused = true; });\n                nav.addEventListener(\'focusout\', function () { autoPaused = false; });\n\n                startAuto();\n                document.addEventListener(\'visibilitychange\', function () {\n                    if (document.hidden) {\n                        stopAuto();\n                    } else {\n                        startAuto();\n                    }\n                });\n            });\n        };\n\n        if (!window.__snbNextNavBooted) {\n            window.__snbNextNavBooted = true;\n            window.__initSnbNextNav = initAll;\n\n            if (document.readyState === \'loading\') {\n                document.addEventListener(\'DOMContentLoaded\', initAll);\n            } else {\n                initAll();\n            }\n\n            window.addEventListener(\'load\', initAll);\n            setTimeout(initAll, 0);\n            setTimeout(initAll, 300);\n        } else if (typeof window.__initSnbNextNav === \'function\') {\n            window.__initSnbNextNav();\n        }\n    })();\n\ndocument.getElementById(\'nlAuditForm\')?.addEventListener(\'submit\', function(e) {\n    e.preventDefault();\n    alert(\'Merci ! Votre demande d\\\'audit SEO a été envoyée. Un expert vous contacte sous 48h.\');\n    this.reset();\n});', 'builder', 'grapesjs', NULL, 'fa-cube', 60, 0, '2026-07-13 12:20:18', '2026-07-20 14:24:19');
INSERT INTO `welcome_sections` (`id`, `zone_id`, `name`, `slug`, `view`, `html_content`, `css_content`, `js_content`, `content_source`, `editor`, `settings`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(19, 2, 'Télé-positionnement', 'next-level-espace-next-level07-espaces-tele-positionnement', 'welcome-home.components.espace_next_level.07_Espaces_Tele_Positionnement', '<section class=\"cd-section\" id=\"nl-tele-positionnement\">\n\n    \n    <div class=\"resto-header-block\">\n        <div class=\"resto-header-main\">\n            <div class=\"resto-header-logo-left\">\n                <a href=\"#\" class=\"resto-accord-btn\" title=\"Contact Direct GoExploria\">\n                    <div class=\"logo-wrapper\">\n                        <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/images/Next-level.png\" alt=\"Next Level\">\n                    </div>\n                    <span class=\"resto-accord-btn-label\">Contact Direct</span>\n                    <span class=\"resto-accord-btn-cta\"><i class=\"fas fa-user-headset\"></i> Pro</span>\n                </a>\n            </div>\n            <div class=\"resto-header-center\">\n                <h1 class=\"resto-header-title\">ESPACES TÉLÉ-POSITIONNEMENT · CONTACT DIRECT</h1>\n                <h2 class=\"resto-header-eyebrow\">Avatar · Diffuseur d&#039;Information · Mix Médias · Courriel Professionnel</h2>\n                <p class=\"resto-header-subtitle\">La meilleure façon de diffuser vos informations en direct chez vos clients cibles grâce au diffuseur d&#039;information, au mix médias contact direct et à l&#039;envoi de courriel avec visuels professionnels.</p>\n            </div>\n            <div class=\"resto-header-logo-right\">\n                <a href=\"https://goexploriabusiness.com/espace-next-level/tele-positionnement\" title=\"Découvrir\" target=\"_blank\" rel=\"noopener noreferrer\">\n                    <img class=\"bt-next-level-image\" src=\"https://goexploriabusiness.com/images/Next-level.png\" alt=\"Next Level\" loading=\"lazy\">\n                </a>\n            </div>\n        </div>\n        \n<nav class=\"snb-bar\" data-snb-next-nav=\"1\" aria-label=\"Section navigation\">\n    <div class=\"snb-inner\">\n        <ul class=\"snb-links\">\n            <li>\n                <a href=\"#activez-entreprises\" class=\"snb-link\">\n                    <i class=\"fas fa-briefcase\"></i>\n                    <span>Conseils Entreprises</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#nl-plans\" class=\"snb-link\">\n                    <i class=\"fas fa-chart-line\"></i>\n                    <span>Plans NEXT LEVEL</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#nl-editeur\" class=\"snb-link\">\n                    <i class=\"fas fa-edit\"></i>\n                    <span>Espace Editeur</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#nl-api\" class=\"snb-link\">\n                    <i class=\"fas fa-code\"></i>\n                    <span>Espace API</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#nl-formulaires\" class=\"snb-link\">\n                    <i class=\"fas fa-file-alt\"></i>\n                    <span>Espace Formulaire</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#nl-seo\" class=\"snb-link\">\n                    <i class=\"fas fa-file-alt\"></i>\n                    <span>Espace SEO</span>\n                </a>\n            </li>\n            <li>\n                <a href=\"#nl-tele-positionnement\" class=\"snb-link\">\n                    <i class=\"fas fa-map-marker-alt\"></i>\n                    <span>Espace Télé Positionnement</span>\n                </a>\n            </li>\n        </ul>\n        <div class=\"snb-scroll-controls\" aria-label=\"Navigation horizontale\">\n            <button type=\"button\" class=\"snb-scroll-btn snb-scroll-left\" aria-label=\"Defiler vers la gauche\">\n                <i class=\"fas fa-chevron-left\"></i>\n            </button>\n            <button type=\"button\" class=\"snb-scroll-btn snb-scroll-right\" aria-label=\"Defiler vers la droite\">\n                <i class=\"fas fa-chevron-right\"></i>\n            </button>\n        </div>\n    </div>\n</nav>\n\n        <div class=\"resto-header-shimmer\"></div>\n    </div>\n\n    <div class=\"cd-body\">\n\n        \n        <div class=\"cd-hero\">\n            <div class=\"cd-hero-content\">\n                <div class=\"cd-badge\">\n                    <i class=\"fas fa-broadcast-tower\"></i>\n                    Diffusion en Direct · Mix Médias Intelligent\n                </div>\n                <h2>\n                    La meilleure façon de diffuser<br>\n                    <em>vos informations chez vos clients cibles</em>\n                </h2>\n                <p>Grâce au diffuseur d&#039;information et au mix médias contact direct client cible, diffusez vos messages en temps réel avec un avatar professionnel, des courriels visuels et un ciblage précis.</p>\n                <div class=\"cd-stats\">\n                    <div class=\"cd-stat\"><i class=\"fas fa-user-headset\"></i><div><strong>100%</strong><span>Personnalisé</span></div></div>\n                    <div class=\"cd-stat\"><i class=\"fas fa-bolt\"></i><div><strong>&lt;2s</strong><span>Diffusion</span></div></div>\n                    <div class=\"cd-stat\"><i class=\"fas fa-layer-group\"></i><div><strong>Multi</strong><span>Canaux</span></div></div>\n                    <div class=\"cd-stat\"><i class=\"fas fa-shield-alt\"></i><div><strong>RGPD</strong><span>Conforme</span></div></div>\n                </div>\n                <div class=\"cd-actions\">\n                    <a href=\"https://goexploriabusiness.com/devis\" class=\"nl-btn-primary\" target=\"_blank\">\n                        <i class=\"fas fa-paper-plane\"></i> Démarrer maintenant\n                    </a>\n                </div>\n            </div>\n\n            \n            <div class=\"cd-hero-visual\">\n\n                \n                <div class=\"cd-avatar-card\">\n                    <div class=\"cd-avatar-img-wrap\">\n                        <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/images/ASSISTANT-WEB-G-EX.png\"\n                             alt=\"Assistant Web GoExploria\"\n                             class=\"cd-avatar-img\"\n                             loading=\"lazy\">\n                        <span class=\"cd-avatar-live\"><i class=\"fas fa-circle\"></i> En direct</span>\n                    </div>\n                    <div class=\"cd-avatar-info\">\n                        <strong>Assistants Web</strong>\n                        <span>Contact Direct · GoExploria</span>\n                    </div>\n                    <div class=\"cd-avatar-wave\">\n                        <span></span><span></span><span></span><span></span><span></span>\n                    </div>\n                </div>\n\n                \n                <div class=\"cd-email-mock\">\n                    <div class=\"cd-email-header\">\n                        <div class=\"cd-email-dots\">\n                            <span style=\"background:#ef4444\"></span>\n                            <span style=\"background:#f59e0b\"></span>\n                            <span style=\"background:#10b981\"></span>\n                        </div>\n                        <span class=\"cd-email-title\"><i class=\"fas fa-envelope\"></i> Nouveau message</span>\n                    </div>\n                    <div class=\"cd-email-meta\">\n                        <div class=\"cd-email-row\"><label>De :</label><span>contact@goexploria.com</span></div>\n                        <div class=\"cd-email-row\"><label>À :</label><span>client.cible@entreprise.com</span></div>\n                        <div class=\"cd-email-row\"><label>Objet :</label><span class=\"cd-email-subject\">🚀 Votre offre personnalisée est prête</span></div>\n                    </div>\n                    <div class=\"cd-email-body\">\n                        <div class=\"cd-email-banner\">\n                            <i class=\"fas fa-user-headset\"></i>\n                            <div>\n                                <strong>GoExploria · Assistants Web</strong>\n                                <span>Solutions de communication directe</span>\n                            </div>\n                        </div>\n                        <div class=\"cd-email-text\">\n                            <div class=\"cd-email-line cd-line-lg\"></div>\n                            <div class=\"cd-email-line cd-line-md\"></div>\n                            <div class=\"cd-email-line cd-line-sm\"></div>\n                            <div class=\"cd-email-line cd-line-md\"></div>\n                        </div>\n                        <div class=\"cd-email-cta-btn\">\n                            <i class=\"fas fa-arrow-right\"></i> Voir mon offre\n                        </div>\n                        <div class=\"cd-email-footer-mock\">\n                            <div class=\"cd-email-line cd-line-sm\" style=\"width:40%\"></div>\n                        </div>\n                    </div>\n                </div>\n\n                \n                <div class=\"cd-floating-notif\">\n                    <i class=\"fas fa-check-circle\"></i>\n                    <div>\n                        <strong>Message envoyé !</strong>\n                        <span>1 240 clients atteints · 14:32</span>\n                    </div>\n                </div>\n\n            </div>\n        </div>\n\n        \n        <div class=\"cd-features\" id=\"cd-features\">\n            <div class=\"cd-section-header\">\n                <span class=\"cd-eyebrow\"><i class=\"fas fa-cogs\"></i> Fonctionnalités</span>\n                <h3>Une solution complète de<br><span class=\"cd-gradient-text\">communication directe</span></h3>\n                <p>Combinez avatar, diffusion et courriel professionnel pour toucher vos clients cibles avec impact.</p>\n            </div>\n            <div class=\"cd-features-grid\">\n                                <div class=\"cd-feature-card\">\n                    <div class=\"cd-feature-icon\" style=\"background:#e8761a20;color:#e8761a\">\n                        <i class=\"fas fa-user-headset\"></i>\n                    </div>\n                    <h4>Contact Direct Avatar</h4>\n                    <p>Un avatar professionnel avec casque d&#039;écoute prend en charge vos clients cibles en temps réel. Interaction humaine et digitale fusionnée.</p>\n                    <div class=\"cd-feature-tag\" style=\"background:#e8761a15;color:#e8761a\">Avatar Live</div>\n                </div>\n                                <div class=\"cd-feature-card\">\n                    <div class=\"cd-feature-icon\" style=\"background:#3b82f620;color:#3b82f6\">\n                        <i class=\"fas fa-broadcast-tower\"></i>\n                    </div>\n                    <h4>Diffuseur d&#039;Information</h4>\n                    <p>Diffusez vos messages directement chez vos clients cibles via le mix médias : SMS, push, audio et visual broadcasting en simultané.</p>\n                    <div class=\"cd-feature-tag\" style=\"background:#3b82f615;color:#3b82f6\">Broadcast</div>\n                </div>\n                                <div class=\"cd-feature-card\">\n                    <div class=\"cd-feature-icon\" style=\"background:#10b98120;color:#10b981\">\n                        <i class=\"fas fa-envelope-open-text\"></i>\n                    </div>\n                    <h4>Envoi de Courriel Professionnel</h4>\n                    <p>Créez et envoyez des courriels avec visuels professionnels adaptés à vos services. Templates responsive, brandés et percutants.</p>\n                    <div class=\"cd-feature-tag\" style=\"background:#10b98115;color:#10b981\">Email Pro</div>\n                </div>\n                                <div class=\"cd-feature-card\">\n                    <div class=\"cd-feature-icon\" style=\"background:#8b5cf620;color:#8b5cf6\">\n                        <i class=\"fas fa-photo-video\"></i>\n                    </div>\n                    <h4>Visuel Adapté à Vos Services</h4>\n                    <p>Chaque communication inclut un visuel professionnel sur-mesure. Images, bannières et médias riches adaptés à votre identité.</p>\n                    <div class=\"cd-feature-tag\" style=\"background:#8b5cf615;color:#8b5cf6\">Rich Media</div>\n                </div>\n                                <div class=\"cd-feature-card\">\n                    <div class=\"cd-feature-icon\" style=\"background:#f59e0b20;color:#f59e0b\">\n                        <i class=\"fas fa-bullseye\"></i>\n                    </div>\n                    <h4>Ciblage Client Précis</h4>\n                    <p>Atteignez exactement vos clients cibles grâce au mix médias intelligent. Segmentation avancée et personnalisation de masse.</p>\n                    <div class=\"cd-feature-tag\" style=\"background:#f59e0b15;color:#f59e0b\">Targeting</div>\n                </div>\n                                <div class=\"cd-feature-card\">\n                    <div class=\"cd-feature-icon\" style=\"background:#ef444420;color:#ef4444\">\n                        <i class=\"fas fa-chart-bar\"></i>\n                    </div>\n                    <h4>Suivi &amp; Performance</h4>\n                    <p>Mesurez l&#039;impact de chaque diffusion en temps réel : taux d&#039;ouverture, clics, conversions et retour sur investissement.</p>\n                    <div class=\"cd-feature-tag\" style=\"background:#ef444415;color:#ef4444\">Analytics</div>\n                </div>\n                            </div>\n        </div>\n\n        \n        <div class=\"cd-cta\">\n            <div class=\"cd-cta-content\">\n                <i class=\"fas fa-user-headset\"></i>\n                <h3>Prêt à communiquer directement avec vos clients ?</h3>\n                <p>Rejoignez des centaines d&#039;entreprises qui diffusent leurs informations en direct grâce à nos solutions de contact direct.</p>\n            </div>\n            <div class=\"cd-cta-buttons\">\n                <a href=\"https://goexploriabusiness.com/devis\" class=\"cd-cta-primary\" target=\"_blank\">\n                    <i class=\"fas fa-headset\"></i> Parler à un expert\n                </a>\n            </div>\n        </div>\n\n    </div>\n</section>', '[data-snb-next-nav] .snb-links {\n        scroll-behavior: smooth;\n    }\n\n    [data-snb-next-nav] .snb-scroll-controls {\n        display: inline-flex;\n        align-items: center;\n        gap: 6px;\n        margin-left: 10px;\n        flex-shrink: 0;\n    }\n\n    [data-snb-next-nav] .snb-scroll-btn {\n        width: 30px;\n        height: 30px;\n        border-radius: 50%;\n        border: 1px solid rgba(212, 175, 55, 0.45);\n        background: #fff;\n        color: #1a2942;\n        cursor: pointer;\n        display: inline-flex;\n        align-items: center;\n        justify-content: center;\n        transition: all .2s ease;\n    }\n\n    [data-snb-next-nav] .snb-scroll-btn:hover {\n        background: #d4af37;\n        color: #fff;\n        border-color: #d4af37;\n    }\n\n    @media (max-width: 768px) {\n        [data-snb-next-nav] .snb-scroll-controls {\n            gap: 4px;\n            margin-left: 6px;\n        }\n\n        [data-snb-next-nav] .snb-scroll-btn {\n            width: 28px;\n            height: 28px;\n        }\n    }\n\n/* ══════════════════════════════════════════════════\n   CONTACT DIRECT — STYLES\n   ══════════════════════════════════════════════════ */\n.cd-section { background: linear-gradient(180deg,#f8faff 0%,#fff 100%); }\n.cd-body    { padding: 0 40px 60px; }\n\n/* ── Gradient text ── */\n.cd-gradient-text {\n    background: linear-gradient(135deg,#e8761a,#f59e0b);\n    -webkit-background-clip: text;\n    background-clip: text;\n    color: transparent;\n}\n\n/* ── Section header ── */\n.cd-section-header { text-align: center; margin-bottom: 40px; }\n.cd-eyebrow {\n    display: inline-flex; align-items: center; gap: 6px;\n    font-size: 11px; font-weight: 700; text-transform: uppercase;\n    letter-spacing: 1.5px; color: #e8761a; background: #fef3ea;\n    padding: 6px 14px; border-radius: 999px; margin-bottom: 16px;\n}\n.cd-section-header h3 {\n    font-family: \'Playfair Display\', serif; font-size: 28px;\n    color: #1a1a1a; margin-bottom: 12px;\n}\n.cd-section-header p { font-size: 15px; color: #666; max-width: 580px; margin: 0 auto; }\n\n/* ── Hero ── */\n.cd-hero {\n    background: linear-gradient(135deg,#0a1628 0%,#1a2a4a 100%);\n    border-radius: 28px; margin: 24px 0 48px; padding: 56px 64px;\n    display: grid; grid-template-columns: 1fr 1fr; gap: 50px;\n    align-items: center; position: relative; overflow: hidden;\n}\n.cd-hero::before {\n    content: \'\'; position: absolute; top: -30%; left: -20%; width: 70%; height: 160%;\n    background: radial-gradient(circle,rgba(232,118,26,.08) 0%,transparent 70%);\n    pointer-events: none;\n}\n\n.cd-badge {\n    display: inline-flex; align-items: center; gap: 8px;\n    background: rgba(52,211,153,.15); border: 1px solid rgba(52,211,153,.3);\n    color: #34d399; border-radius: 999px; padding: 6px 16px;\n    font-size: 11px; font-weight: 700; text-transform: uppercase;\n    letter-spacing: 1px; margin-bottom: 24px;\n}\n.cd-hero h2 {\n    font-family: \'Playfair Display\', serif;\n    font-size: clamp(28px,3vw,42px); color: #fff;\n    line-height: 1.15; margin-bottom: 20px;\n}\n.cd-hero h2 em { font-style: italic; color: #e8761a; }\n.cd-hero > p, .cd-hero-content > p {\n    font-size: 15px; color: rgba(255,255,255,.7); line-height: 1.8; margin-bottom: 28px;\n}\n\n/* Stats */\n.cd-stats { display: flex; gap: 18px; margin-bottom: 32px; flex-wrap: wrap; }\n.cd-stat {\n    display: flex; align-items: center; gap: 10px;\n    background: rgba(255,255,255,.05); padding: 10px 16px;\n    border-radius: 12px; border: 1px solid rgba(255,255,255,.1);\n}\n.cd-stat i { font-size: 22px; color: #e8761a; }\n.cd-stat strong { display: block; font-family:\'Bebas Neue\',sans-serif; font-size: 20px; color: #fff; line-height: 1; }\n.cd-stat span   { font-size: 10px; color: rgba(255,255,255,.6); text-transform: uppercase; letter-spacing: .5px; }\n\n.cd-actions { display: flex; gap: 14px; flex-wrap: wrap; }\n\n/* ── Hero Visual ── */\n.cd-hero-visual { position: relative; display: flex; flex-direction: column; gap: 20px; }\n\n/* Avatar card */\n.cd-avatar-card {\n    background: rgba(255,255,255,.07); border: 1px solid rgba(255,255,255,.12);\n    border-radius: 20px; padding: 20px 24px;\n    display: flex; align-items: center; gap: 16px;\n    backdrop-filter: blur(12px);\n}\n.cd-avatar-img-wrap { position: relative; flex-shrink: 0; }\n.cd-avatar-img { width: 90px; height: 90px; border-radius: 50%; object-fit: cover; object-position: top; border: 3px solid #e8761a; }\n.cd-avatar-live {\n    position: absolute; bottom: -4px; left: 50%; transform: translateX(-50%);\n    background: #10b981; color: #fff; font-size: 8px; font-weight: 700;\n    padding: 2px 8px; border-radius: 999px; white-space: nowrap;\n    display: flex; align-items: center; gap: 4px;\n}\n.cd-avatar-live i { font-size: 6px; animation: cdBlink 1.5s infinite; }\n@keyframes cdBlink { 0%,100%{opacity:1} 50%{opacity:.2} }\n.cd-avatar-info strong { display: block; font-size: 14px; color: #fff; font-weight: 700; }\n.cd-avatar-info span   { font-size: 11px; color: rgba(255,255,255,.5); }\n\n/* Voice wave animation */\n.cd-avatar-wave { display: flex; align-items: center; gap: 3px; margin-left: auto; }\n.cd-avatar-wave span {\n    display: block; width: 4px; border-radius: 99px; background: #e8761a;\n    animation: cdWave 1.2s ease-in-out infinite;\n}\n.cd-avatar-wave span:nth-child(1){ height:8px;  animation-delay:0s; }\n.cd-avatar-wave span:nth-child(2){ height:16px; animation-delay:.1s; }\n.cd-avatar-wave span:nth-child(3){ height:24px; animation-delay:.2s; }\n.cd-avatar-wave span:nth-child(4){ height:16px; animation-delay:.3s; }\n.cd-avatar-wave span:nth-child(5){ height:8px;  animation-delay:.4s; }\n@keyframes cdWave {\n    0%,100%{ transform: scaleY(1); opacity:.6; }\n    50%     { transform: scaleY(1.8); opacity:1; }\n}\n\n/* Email mock */\n.cd-email-mock {\n    background: #fff; border-radius: 16px; overflow: hidden;\n    box-shadow: 0 12px 40px rgba(0,0,0,.18);\n}\n.cd-email-header {\n    background: #f3f4f6; padding: 10px 16px;\n    display: flex; align-items: center; gap: 10px;\n    border-bottom: 1px solid #e5e7eb;\n}\n.cd-email-dots { display: flex; gap: 5px; }\n.cd-email-dots span { width: 10px; height: 10px; border-radius: 50%; display: block; }\n.cd-email-title { font-size: 12px; font-weight: 600; color: #555; display: flex; align-items: center; gap: 6px; }\n.cd-email-title i { color: #e8761a; }\n\n.cd-email-meta { padding: 10px 16px; border-bottom: 1px solid #f0f0f0; }\n.cd-email-row  { display: flex; gap: 8px; font-size: 11px; padding: 2px 0; }\n.cd-email-row label { color: #999; min-width: 36px; }\n.cd-email-row span  { color: #555; }\n.cd-email-subject   { color: #1a1a1a; font-weight: 700; }\n\n.cd-email-body { padding: 14px 16px; }\n.cd-email-banner {\n    background: linear-gradient(135deg,#0a1628,#1e3a5f);\n    border-radius: 10px; padding: 12px 16px;\n    display: flex; align-items: center; gap: 12px; margin-bottom: 14px;\n}\n.cd-email-banner i { font-size: 24px; color: #e8761a; }\n.cd-email-banner strong { display: block; font-size: 12px; color: #fff; }\n.cd-email-banner span  { font-size: 10px; color: rgba(255,255,255,.6); }\n\n.cd-email-text { margin-bottom: 12px; display: flex; flex-direction: column; gap: 6px; }\n.cd-email-line { height: 8px; background: #f0f0f0; border-radius: 4px; }\n.cd-line-lg { width: 90%; }\n.cd-line-md { width: 70%; }\n.cd-line-sm { width: 50%; }\n\n.cd-email-cta-btn {\n    background: linear-gradient(135deg,#e8761a,#c04f10);\n    color: #fff; border-radius: 8px; padding: 10px 18px;\n    font-size: 12px; font-weight: 700; display: inline-flex; align-items: center; gap: 6px;\n    margin-bottom: 12px;\n}\n.cd-email-footer-mock { padding-top: 10px; border-top: 1px solid #f0f0f0; }\n\n/* Floating notification */\n.cd-floating-notif {\n    position: absolute; bottom: -16px; left: -16px;\n    background: #fff; border-radius: 12px; padding: 10px 14px;\n    display: flex; align-items: center; gap: 10px;\n    box-shadow: 0 8px 20px rgba(0,0,0,.15);\n}\n.cd-floating-notif i { font-size: 18px; color: #10b981; }\n.cd-floating-notif strong { display: block; font-size: 11px; color: #1a1a1a; }\n.cd-floating-notif span  { font-size: 10px; color: #666; }\n\n/* ── Features grid ── */\n.cd-features { margin-bottom: 60px; }\n.cd-features-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; }\n.cd-feature-card {\n    background: #fff; border: 1.5px solid #e5e7eb;\n    border-radius: 20px; padding: 32px; transition: all .3s;\n}\n.cd-feature-card:hover { transform: translateY(-4px); border-color: #e8761a; box-shadow: 0 20px 40px rgba(0,0,0,.08); }\n.cd-feature-icon {\n    width: 52px; height: 52px; border-radius: 14px;\n    display: flex; align-items: center; justify-content: center;\n    font-size: 22px; margin-bottom: 18px;\n}\n.cd-feature-card h4 { font-size: 16px; font-weight: 700; color: #1a1a1a; margin-bottom: 10px; }\n.cd-feature-card p  { font-size: 13px; color: #666; line-height: 1.7; margin-bottom: 16px; }\n.cd-feature-tag {\n    display: inline-block; font-size: 10px; font-weight: 700;\n    text-transform: uppercase; letter-spacing: .8px; padding: 4px 10px; border-radius: 6px;\n}\n\n/* ── How it works ── */\n.cd-how {\n    background: linear-gradient(135deg,#0a1628,#1e3a5f);\n    border-radius: 28px; padding: 56px 48px; margin-bottom: 60px;\n}\n.cd-how .cd-section-header h3 { color: #fff; }\n.cd-how .cd-section-header p  { color: rgba(255,255,255,.6); }\n.cd-how .cd-eyebrow { background: rgba(232,118,26,.2); }\n\n.cd-steps { display: flex; align-items: center; gap: 16px; justify-content: center; flex-wrap: wrap; }\n.cd-step {\n    flex: 1; min-width: 200px; max-width: 260px; text-align: center;\n    background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.1);\n    border-radius: 20px; padding: 32px 24px; position: relative;\n}\n.cd-step-num {\n    position: absolute; top: -14px; left: 50%; transform: translateX(-50%);\n    font-family: \'Bebas Neue\', sans-serif; font-size: 28px; color: #e8761a;\n    background: #0a1628; padding: 0 8px; line-height: 1;\n}\n.cd-step-icon {\n    width: 60px; height: 60px; background: rgba(232,118,26,.15);\n    border-radius: 18px; display: flex; align-items: center; justify-content: center;\n    font-size: 26px; color: #e8761a; margin: 16px auto 20px;\n}\n.cd-step h4 { font-size: 18px; color: #fff; margin-bottom: 10px; font-weight: 700; }\n.cd-step p  { font-size: 13px; color: rgba(255,255,255,.6); line-height: 1.7; }\n\n.cd-step-arrow { font-size: 24px; color: rgba(255,255,255,.2); flex-shrink: 0; }\n\n/* ── Sectors ── */\n.cd-sectors {\n    background: #fff; border: 1px solid #e5e7eb;\n    border-radius: 28px; padding: 48px; margin-bottom: 60px;\n}\n.cd-sectors-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; margin-top: 8px; }\n.cd-sector-card {\n    text-align: center; padding: 24px; background: #f8faff;\n    border-radius: 20px; transition: all .3s;\n}\n.cd-sector-card:hover { transform: translateY(-4px); background: #fff; box-shadow: 0 12px 24px rgba(0,0,0,.08); }\n.cd-sector-icon {\n    width: 60px; height: 60px; background: linear-gradient(135deg,#e8761a20,#f59e0b20);\n    border-radius: 20px; display: flex; align-items: center; justify-content: center;\n    margin: 0 auto 16px; font-size: 28px; color: #e8761a;\n}\n.cd-sector-card h4 { font-size: 15px; margin-bottom: 6px; font-weight: 700; color: #1a1a1a; }\n.cd-sector-card p  { font-size: 12px; color: #888; }\n\n/* ── Form ── */\n.cd-form {\n    background: linear-gradient(135deg,#fff,#f8faff);\n    border: 1px solid #e5e7eb; border-radius: 28px; padding: 56px;\n    display: grid; grid-template-columns: 1fr 1fr; gap: 60px; margin-bottom: 60px;\n}\n.cd-form-badge {\n    display: inline-flex; align-items: center; gap: 6px;\n    font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px;\n    color: #10b981; background: rgba(16,185,129,.1); padding: 6px 14px;\n    border-radius: 999px; margin-bottom: 16px;\n}\n.cd-form-left h3 { font-family:\'Playfair Display\',serif; font-size: 26px; margin-bottom: 14px; }\n.cd-form-left h3 em { font-style: italic; color: #e8761a; }\n.cd-form-left p  { font-size: 15px; color: #666; line-height: 1.8; margin-bottom: 24px; }\n.cd-benefits { list-style: none; display: flex; flex-direction: column; gap: 12px; }\n.cd-benefits li { font-size: 14px; color: #444; display: flex; align-items: center; gap: 10px; }\n.cd-benefits li i { color: #10b981; }\n\n.cd-form-group  { margin-bottom: 16px; }\n.cd-form-row    { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }\n.cd-form-group label {\n    display: block; font-size: 12px; font-weight: 700; color: #374151; margin-bottom: 6px;\n}\n.cd-form-group input,\n.cd-form-group select {\n    width: 100%; border: 1.5px solid #e5e7eb; border-radius: 10px;\n    padding: 12px 14px; font-size: 14px; transition: border-color .2s;\n}\n.cd-form-group input:focus,\n.cd-form-group select:focus { outline: none; border-color: #e8761a; }\n.cd-btn-submit {\n    width: 100%; background: linear-gradient(135deg,#e8761a,#c04f10);\n    color: #fff; border: none; border-radius: 10px; padding: 14px;\n    font-size: 14px; font-weight: 700; cursor: pointer;\n    display: flex; align-items: center; justify-content: center; gap: 8px;\n    transition: all .2s; margin-top: 8px;\n}\n.cd-btn-submit:hover { transform: translateY(-2px); box-shadow: 0 12px 32px rgba(232,118,26,.35); }\n.cd-form-note { font-size: 11px; color: #9ca3af; text-align: center; margin-top: 12px; }\n\n/* ── CTA ── */\n.cd-cta {\n    background: linear-gradient(135deg,#0f2240,#1e3a5f);\n    border-radius: 24px; padding: 48px 56px;\n    display: flex; justify-content: space-between; align-items: center;\n    gap: 40px; flex-wrap: wrap;\n}\n.cd-cta-content { display: flex; flex-direction: column; align-items: flex-start; }\n.cd-cta-content i  { font-size: 36px; color: #e8761a; margin-bottom: 12px; }\n.cd-cta-content h3 { font-size: 22px; color: #fff; margin-bottom: 8px; }\n.cd-cta-content p  { font-size: 14px; color: rgba(255,255,255,.7); max-width: 500px; }\n.cd-cta-buttons    { display: flex; gap: 14px; flex-wrap: wrap; }\n.cd-cta-primary {\n    background: #e8761a; color: #fff; padding: 14px 28px; border-radius: 10px;\n    font-weight: 700; font-size: 14px; text-decoration: none;\n    display: inline-flex; align-items: center; gap: 8px; transition: all .2s;\n}\n.cd-cta-primary:hover { background: #c45e0e; transform: translateY(-2px); color: #fff; }\n.cd-cta-secondary {\n    border: 2px solid rgba(255,255,255,.3); color: #fff; padding: 14px 28px;\n    border-radius: 10px; font-weight: 700; font-size: 14px; text-decoration: none;\n    display: inline-flex; align-items: center; gap: 8px; transition: all .2s;\n}\n.cd-cta-secondary:hover { border-color: #fff; background: rgba(255,255,255,.08); color: #fff; }\n\n/* ── Responsive ── */\n@media (max-width:1100px) {\n    .cd-hero        { grid-template-columns: 1fr; padding: 40px; }\n    .cd-features-grid { grid-template-columns: repeat(2,1fr); }\n    .cd-sectors-grid  { grid-template-columns: repeat(2,1fr); }\n    .cd-form        { grid-template-columns: 1fr; gap: 32px; }\n    .cd-steps       { flex-direction: column; align-items: stretch; }\n    .cd-step-arrow  { transform: rotate(90deg); text-align: center; }\n}\n@media (max-width:768px) {\n    .cd-body        { padding: 0 20px 40px; }\n    .cd-features-grid { grid-template-columns: 1fr; }\n    .cd-sectors-grid  { grid-template-columns: 1fr; }\n    .cd-cta         { flex-direction: column; text-align: center; padding: 32px 24px; }\n    .cd-cta-content { align-items: center; text-align: center; }\n    .cd-form .cd-form-row { grid-template-columns: 1fr; }\n    .cd-floating-notif { position: static; margin-top: 8px; }\n}', '(function () {\n        const initAll = function () {\n            const navs = document.querySelectorAll(\'nav[data-snb-next-nav]\');\n            if (!navs.length) return;\n\n            navs.forEach(function (nav) {\n                if (nav.dataset.snbNextInit === \'1\') return;\n                nav.dataset.snbNextInit = \'1\';\n\n                let links = Array.from(nav.querySelectorAll(\'.snb-link[href^=\"#\"]\'));\n                const linksRow = nav.querySelector(\'.snb-links\');\n                const leftBtn = nav.querySelector(\'.snb-scroll-left\');\n                const rightBtn = nav.querySelector(\'.snb-scroll-right\');\n                if (!links.length || !linksRow) return;\n\n                const setupInfiniteLoop = function () {\n                    if (linksRow.dataset.snbLoopReady === \'1\') return;\n                    if (links.length <= 1) return;\n\n                    Array.from(linksRow.children).forEach(function (child) {\n                        const clone = child.cloneNode(true);\n                        clone.dataset.snbClone = \'1\';\n                        clone.setAttribute(\'aria-hidden\', \'true\');\n                        clone.querySelectorAll(\'a, button\').forEach(function (item) {\n                            item.setAttribute(\'tabindex\', \'-1\');\n                        });\n                        linksRow.appendChild(clone);\n                    });\n\n                    linksRow.dataset.snbLoopReady = \'1\';\n                    links = Array.from(nav.querySelectorAll(\'.snb-link[href^=\"#\"]\'));\n                };\n\n                setupInfiniteLoop();\n\n                const centerLink = function (link) {\n                    const targetLeft = link.offsetLeft - (linksRow.clientWidth / 2) + (link.clientWidth / 2);\n                    const maxLeft = linksRow.scrollWidth - linksRow.clientWidth;\n                    const nextLeft = Math.max(0, Math.min(targetLeft, maxLeft));\n                    linksRow.scrollTo({ left: nextLeft, behavior: \'smooth\' });\n                };\n\n                const setActive = function (link, shouldCenter = true) {\n                    links.forEach(function (item) { item.classList.remove(\'active\'); });\n                    link.classList.add(\'active\');\n                    if (shouldCenter) centerLink(link);\n                };\n\n                links.forEach(function (link) {\n                    link.addEventListener(\'click\', function () {\n                        setActive(link, true);\n                    });\n                });\n\n                const activateFromHash = function (shouldCenter = false) {\n                    const hash = window.location.hash;\n                    const found = links.find(function (link) { return link.getAttribute(\'href\') === hash; });\n                    if (found) {\n                        setActive(found, shouldCenter);\n                        return true;\n                    }\n                    return false;\n                };\n\n                if (!activateFromHash(false)) {\n                    setActive(links[0], false);\n                }\n\n                window.addEventListener(\'hashchange\', function () {\n                    activateFromHash(true);\n                });\n\n                const step = 320;\n                const autoSpeed = 1.4;\n                const edgeEpsilon = 2;\n                let autoTimer = null;\n                let autoPaused = false;\n\n                const hasInfiniteLoop = function () {\n                    return linksRow.dataset.snbLoopReady === \'1\';\n                };\n\n                const getCycleWidth = function () {\n                    return hasInfiniteLoop() ? (linksRow.scrollWidth / 2) : 0;\n                };\n\n                const normalizeLoopPosition = function () {\n                    if (!hasInfiniteLoop()) return;\n                    const cycleWidth = getCycleWidth();\n                    if (cycleWidth <= 0) return;\n\n                    if (linksRow.scrollLeft >= cycleWidth) {\n                        linksRow.scrollLeft = linksRow.scrollLeft - cycleWidth;\n                    } else if (linksRow.scrollLeft < 0) {\n                        linksRow.scrollLeft = linksRow.scrollLeft + cycleWidth;\n                    }\n                };\n\n                const scrollByStep = function (direction) {\n                    if (hasInfiniteLoop()) {\n                        const cycleWidth = getCycleWidth();\n                        if (cycleWidth <= 0) return;\n\n                        if (direction < 0 && linksRow.scrollLeft <= step) {\n                            linksRow.scrollLeft = linksRow.scrollLeft + cycleWidth;\n                        }\n\n                        linksRow.scrollTo({\n                            left: linksRow.scrollLeft + (direction * step),\n                            behavior: \'smooth\'\n                        });\n                        setTimeout(normalizeLoopPosition, 420);\n                        return;\n                    }\n\n                    const maxLeft = linksRow.scrollWidth - linksRow.clientWidth;\n                    if (maxLeft <= 0) return;\n\n                    const current = linksRow.scrollLeft;\n\n                    if (direction > 0) {\n                        if (current >= maxLeft - edgeEpsilon) {\n                            linksRow.scrollTo({ left: 0, behavior: \'auto\' });\n                            return;\n                        }\n                        linksRow.scrollTo({ left: Math.min(current + step, maxLeft), behavior: \'smooth\' });\n                        return;\n                    }\n\n                    if (current <= edgeEpsilon) {\n                        linksRow.scrollTo({ left: maxLeft, behavior: \'auto\' });\n                        return;\n                    }\n\n                    linksRow.scrollTo({ left: Math.max(current - step, 0), behavior: \'smooth\' });\n                };\n\n                const autoTick = function () {\n                    if (autoPaused) return;\n                    if (hasInfiniteLoop()) {\n                        const cycleWidth = getCycleWidth();\n                        if (cycleWidth <= 0) return;\n                        linksRow.scrollLeft = linksRow.scrollLeft + autoSpeed;\n                        if (linksRow.scrollLeft >= cycleWidth) {\n                            linksRow.scrollLeft = linksRow.scrollLeft - cycleWidth;\n                        }\n                        return;\n                    }\n\n                    const maxLeft = linksRow.scrollWidth - linksRow.clientWidth;\n                    if (maxLeft <= 0) return;\n                    const next = linksRow.scrollLeft + autoSpeed;\n                    if (next >= maxLeft - edgeEpsilon) {\n                        linksRow.scrollLeft = 0;\n                        return;\n                    }\n                    linksRow.scrollLeft = next;\n                };\n\n                const startAuto = function () {\n                    if (autoTimer) return;\n                    autoTimer = setInterval(autoTick, 16);\n                };\n\n                const stopAuto = function () {\n                    if (!autoTimer) return;\n                    clearInterval(autoTimer);\n                    autoTimer = null;\n                };\n\n                if (leftBtn) {\n                    leftBtn.addEventListener(\'click\', function () {\n                        scrollByStep(-1);\n                    });\n                }\n\n                if (rightBtn) {\n                    rightBtn.addEventListener(\'click\', function () {\n                        scrollByStep(1);\n                    });\n                }\n\n                nav.addEventListener(\'mouseenter\', function () { autoPaused = true; });\n                nav.addEventListener(\'mouseleave\', function () { autoPaused = false; });\n                nav.addEventListener(\'focusin\', function () { autoPaused = true; });\n                nav.addEventListener(\'focusout\', function () { autoPaused = false; });\n\n                startAuto();\n                document.addEventListener(\'visibilitychange\', function () {\n                    if (document.hidden) {\n                        stopAuto();\n                    } else {\n                        startAuto();\n                    }\n                });\n            });\n        };\n\n        if (!window.__snbNextNavBooted) {\n            window.__snbNextNavBooted = true;\n            window.__initSnbNextNav = initAll;\n\n            if (document.readyState === \'loading\') {\n                document.addEventListener(\'DOMContentLoaded\', initAll);\n            } else {\n                initAll();\n            }\n\n            window.addEventListener(\'load\', initAll);\n            setTimeout(initAll, 0);\n            setTimeout(initAll, 300);\n        } else if (typeof window.__initSnbNextNav === \'function\') {\n            window.__initSnbNextNav();\n        }\n    })();\n\ndocument.getElementById(\'cdContactForm\')?.addEventListener(\'submit\', function(e) {\n    e.preventDefault();\n    alert(\'Merci ! Votre demande de démo a été enregistrée. Notre équipe vous contacte sous 24h pour activer votre accès.\');\n    this.reset();\n});', 'builder', 'grapesjs', NULL, 'fa-cube', 70, 0, '2026-07-13 12:20:18', '2026-07-20 14:24:23');
INSERT INTO `welcome_sections` (`id`, `zone_id`, `name`, `slug`, `view`, `html_content`, `css_content`, `js_content`, `content_source`, `editor`, `settings`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(20, 3, 'Restaurant ambiance vedette', 'restaurants-espace-restaurantrestaurantambiancevedettev2', 'welcome-home.components.espace_restaurant.RestaurantAmbianceVedetteV2', '<section class=\"products-vedette-v2-section\" id=\"resto-ambiance-vedette-v2\">\n    <div class=\"products-vedette-v2-container\">\n\n        <div class=\"resto-header-block\">\n            <div class=\"resto-header-main\">\n                <div class=\"resto-header-logo-left\">\n                    <a href=\"#\"\n                       class=\"resto-accord-btn\"\n                       title=\"Restaurant Logo\"\n                       target=\"_blank\"\n                       rel=\"noopener noreferrer\">\n                        <div class=\"logo-wrapper\">\n                            <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/logo.png\"\n                                 alt=\"Restaurant Logo\">\n                        </div>\n                        <span class=\"resto-accord-btn-label\">Restaurant Logo</span>\n                        <span class=\"resto-accord-btn-cta\">\n                            <i class=\"fas fa-external-link-alt\"></i> Visit\n                        </span>\n                    </a>\n                </div>\n\n                <div class=\"resto-header-center\">\n                    <h1 class=\"resto-header-title\" id=\"restoHeaderTitle\">AMBIANCE RESTO - ACCORD METS ET VIN</h1>\n                    <p class=\"resto-header-subtitle\" id=\"restoHeaderSubtitle\">Entrees - Mets principaux - Desserts - Vins. Decouvrez des cartes gastronomiques et accords soignes.</p>\n                    <div class=\"resto-header-tabs\" id=\"restoHeaderTabs\" role=\"tablist\">\n                                                <button class=\"resto-tab-btn active\" role=\"tab\" data-cat=\"all\" aria-selected=\"true\">\n                            <span class=\"resto-tab-count\">28</span> All formulas\n                        </button>\n                      