;font-size:0.8rem;margin:0;\">\' + unavailableHint + \'</p>\' +\n                \'</div></div>\';\n            window.addEventListener(\'message\', ytMsgHandler);\n        }\n        modal.classList.add(\'mss-gallery-modal--active\');\n        document.body.style.overflow = \'hidden\';\n        stopAuto();\n    }\n\n    function closeModal() {\n        if (!modal) return;\n        modal.classList.remove(\'mss-gallery-modal--active\');\n        if (videoEl) videoEl.innerHTML = \'\';\n        document.body.style.overflow = \'\';\n        window.removeEventListener(\'message\', ytMsgHandler);\n        startAuto();\n    }\n\n    track.querySelectorAll(\'.mss-gallery-item\').forEach(function (item) {\n        item.addEventListener(\'click\', function () {\n            openModal(this.dataset.video, this.dataset.title);\n        });\n        var playBtn = item.querySelector(\'.mss-gallery-play\');\n        if (playBtn) {\n            playBtn.addEventListener(\'click\', function (e) {\n                e.stopPropagation();\n                openModal(item.dataset.video, item.dataset.title);\n            });\n        }\n    });\n\n    if (closeBtn) closeBtn.addEventListener(\'click\', closeModal);\n    if (modal)    modal.addEventListener(\'click\', function (e) { if (e.target === modal) closeModal(); });\n\n    document.addEventListener(\'keydown\', function (e) {\n        if (e.key === \'Escape\' && modal && modal.classList.contains(\'mss-gallery-modal--active\')) closeModal();\n    });\n\n    /* ---- Init ---- */\n    startAuto();\n})();\n\n(function () {\n    var wrapper = document.getElementById(\"restaurant-vedetteGrid\");\n    var section = wrapper ? wrapper.closest(\'section\') : null;\n    if (!wrapper || !section) return;\n\n    var GAP = 20;\n    var PAUSE = 3500;\n    var ANIM = 480;\n    var timer = null;\n    var busy = false;\n\n    function visibleCards() {\n        return Array.from(wrapper.children).filter(function (card) { return card.style.display !== \'none\'; });\n    }\n\n    function resetBar() {\n        var bar = document.getElementById(\"restaurant-vedetteBar\");\n        if (!bar) return;\n        bar.style.transition = \'none\';\n        bar.style.width = \'0%\';\n        if (bar) bar.offsetWidth;\n        bar.style.transition = \'width \' + PAUSE + \'ms linear\';\n        bar.style.width = \'100%\';\n    }\n\n    function shiftLeft() {\n        var cards = visibleCards();\n        if (busy || cards.length < 2) return;\n        busy = true;\n        if (!cards[0]) { busy = false; return; }\n        var shift = cards[0].offsetWidth + GAP;\n        wrapper.style.transition = \'transform \' + ANIM + \'ms cubic-bezier(0.4,0,0.2,1)\';\n        wrapper.style.transform = \'translateX(-\' + shift + \'px)\';\n        setTimeout(function () {\n            wrapper.style.transition = \'none\';\n            wrapper.style.transform = \'translateX(0)\';\n            wrapper.appendChild(cards[0]);\n            busy = false;\n            resetBar();\n        }, ANIM + 20);\n    }\n\n    function shiftRight() {\n        var cards = visibleCards();\n        if (busy || cards.length < 2) return;\n        busy = true;\n        var last = cards[cards.length - 1];\n        if (!last) { busy = false; return; }\n        var shift = last.offsetWidth + GAP;\n        wrapper.style.transition = \'none\';\n        wrapper.insertBefore(last, wrapper.firstChild);\n        wrapper.style.transform = \'translateX(-\' + shift + \'px)\';\n        if (wrapper) wrapper.offsetWidth;\n        wrapper.style.transition = \'transform \' + ANIM + \'ms cubic-bezier(0.4,0,0.2,1)\';\n        wrapper.style.transform = \'translateX(0)\';\n        setTimeout(function () { busy = false; resetBar(); }, ANIM + 20);\n    }\n\n    function startAuto() { timer = setInterval(shiftLeft, PAUSE); }\n    function stopAuto() { clearInterval(timer); }\n\n    resetBar();\n    section.addEventListener(\'mouseenter\', stopAuto);\n    section.addEventListener(\'mouseleave\', startAuto);\n    startAuto();\n\n    var prev = document.getElementById(\"restaurant-vedettePrev\");\n    var next = document.getElementById(\"restaurant-vedetteNext\");\n    if (prev) prev.addEventListener(\'click\', function () { stopAuto(); shiftRight(); startAuto(); });\n    if (next) next.addEventListener(\'click\', function () { stopAuto(); shiftLeft(); startAuto(); });\n\n    section.querySelectorAll(\'.events-vedette-v2-filter-btn\').forEach(function (btn) {\n        btn.addEventListener(\'click\', function () {\n            section.querySelectorAll(\'.events-vedette-v2-filter-btn\').forEach(function (item) { item.classList.remove(\'active\'); });\n            btn.classList.add(\'active\');\n            var filter = btn.getAttribute(\'data-filter\');\n            Array.from(wrapper.children).forEach(function (card) {\n                var category = card.getAttribute(\'data-category\') || \'\';\n                card.style.display = (filter === \'all\' || category === filter) ? \'\' : \'none\';\n            });\n            wrapper.style.transition = \'none\';\n            wrapper.style.transform = \'translateX(0)\';\n            busy = false;\n            resetBar();\n            stopAuto();\n            startAuto();\n        });\n    });\n})();', 'builder', 'grapesjs', NULL, 'fa-cube', 30, 1, '2026-07-13 12:20:18', '2026-07-13 12:24:53');
INSERT INTO `welcome_sections` (`id`, `zone_id`, `name`, `slug`, `view`, `html_content`, `css_content`, `js_content`, `content_source`, `editor`, `settings`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(24, 4, 'Destinations vedette', 'vedettes-espace-evenement-videttedestinationvedette', 'welcome-home.components.espace_evenement_vidette.DestinationVedette', '<section class=\"events-vedette-v2-section featured-space-v2-section\" id=\"destination-vedette\">\n    <div class=\"events-vedette-v2-container\">\n        <div class=\"resto-header-block\">\n            <div class=\"resto-header-main\">\n                <div class=\"resto-header-logo-left\">\n                    <a href=\"#\" class=\"resto-accord-btn\" title=\"GoExploria\">\n                        <div class=\"logo-wrapper\">\n                            <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/logo.png\" alt=\"GoExploria\">\n                        </div>\n                        <span class=\"resto-accord-btn-label\">GoExploria</span>\n                        <span class=\"resto-accord-btn-cta\">\n                            <i class=\"fas fa-external-link-alt\"></i> Visit\n                        </span>\n                    </a>\n                </div>\n\n                <div class=\"resto-header-center\">\n                    <h1 class=\"resto-header-title\">ESPACE DESTINATION VEDETTE</h1>\n                    <p class=\"resto-header-subtitle\">Régions · villes · nature · patrimoine — Les destinations qui méritent une visibilité premium.</p>\n                </div>\n\n                <div class=\"resto-header-logo-right\">\n                    <a href=\"https://goexploriabusiness.com/destinations\" title=\"Find out\" target=\"_blank\" rel=\"noopener noreferrer\">\n                        <img class=\"bt-next-level-image\" src=\"https://goexploriabusiness.com/images/Next-level.png\" alt=\"Next Level\" loading=\"lazy\">\n                    </a>\n                </div>\n            </div>\n\n            <div class=\"resto-header-destinations-bar\">\n                <div class=\"resto-dest-row\">\n                    <div class=\"resto-dest-icon-box\">\n                        <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/REDI.png\" alt=\"Destinations\">\n                        <span>Destinations</span>\n                    </div>\n\n                    <div class=\"resto-dest-breadcrumb vp-dest-breadcrumb\">\n                        <select id=\"destination-vedette-continent-select\" class=\"vp-dest-select\" aria-label=\"Continent\">\n                            <option value=\"amerique-nord\">North America</option>\n                            <option value=\"europe\">Europe</option>\n                            <option value=\"afrique\">Africa</option>\n                            <option value=\"asie\">Asia</option>\n                            <option value=\"amerique-sud\">Amérique du Sud</option>\n                            <option value=\"oceanie\">Océanie</option>\n                        </select>\n                        <span class=\"resto-dest-sep\">/</span>\n                        <select id=\"destination-vedette-country-select\" class=\"vp-dest-select\" aria-label=\"Pays\">\n                            <option value=\"canada\">Canada</option>\n                        </select>\n                        <span class=\"resto-dest-sep\">/</span>\n                        <select id=\"destination-vedette-province-select\" class=\"vp-dest-select\" aria-label=\"Province\">\n                            <option value=\"quebec\">Quebec</option>\n                            <option value=\"ontario\">Ontario</option>\n                            <option value=\"alberta\">Alberta</option>\n                            <option value=\"colombie-britannique\">Colombie-Britannique</option>\n                            <option value=\"nouvelle-ecosse\">Nouvelle-Écosse</option>\n                        </select>\n                        <span class=\"resto-dest-sep\">/</span>\n                        <select id=\"destination-vedette-region-select\" class=\"vp-dest-select\" aria-label=\"Région\">\n                            <option value=\"region-de-quebec\">Quebec region</option>\n                            <option value=\"montreal-metro\">Montréal Métro</option>\n                            <option value=\"mauricie\">Mauricie</option>\n                            <option value=\"gaspesie\">Gaspésie</option>\n                            <option value=\"saguenay\">Saguenay</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class=\"resto-actions-row\">\n                    <div class=\"resto-header-ctas\">\n                        <div class=\"events-vedette-v2-filters\">\n                            <button class=\"events-vedette-v2-filter-btn active\" data-filter=\"all\">\n                                <i class=\"fas fa-th-large\"></i> All options\n                            </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"villes\">\n                                    <i class=\"fas fa-city\"></i> Towns &amp; Cities\n                                </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"nature\">\n                                    <i class=\"fas fa-mountain-sun\"></i> Nature\n                                </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"culture\">\n                                    <i class=\"fas fa-landmark\"></i> Culture\n                                </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"pleinair\">\n                                    <i class=\"fas fa-person-hiking\"></i> Plein air\n                                </button>\n                                                    </div>\n                        <a href=\"https://goexploriabusiness.com/destinations\" class=\"resto-cta-btn secondary\" target=\"_blank\" rel=\"noopener noreferrer\">\n                            Find out <span class=\"cta-plus\">+</span>\n                        </a>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"resto-header-shimmer\"></div>\n        </div>\n\n        <div class=\"vedette-carousel-outer\">\n            <button class=\"vedette-carousel-btn vedette-carousel-prev\" id=\"destination-vedettePrev\" aria-label=\"Previous\"><i class=\"fas fa-chevron-left\"></i></button>\n            <div class=\"events-vedette-v2-scroll-wrapper\">\n                <div class=\"events-vedette-v2-scroll-container\" id=\"destination-vedetteGrid\">\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"villes\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1519178614-68673b201f36?w=600&amp;h=400&amp;fit=crop\" alt=\"Vieux-Québec historique\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Ville</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Vieux-Québec historique</h3>\n                                <p class=\"events-vedette-v2-card-description\">Patrimoine UNESCO, ruelles charmantes et expériences culturelles.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Quebec</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Patrimoine</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"nature\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=600&amp;h=400&amp;fit=crop\" alt=\"Charlevoix grandeur nature\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Nature</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Charlevoix grandeur nature</h3>\n                                <p class=\"events-vedette-v2-card-description\">Paysages spectaculaires, fleuve, montagnes et art de vivre.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Charlevoix</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Nature</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"culture\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?w=600&amp;h=400&amp;fit=crop\" alt=\"Montréal créative\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Culture</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Montréal créative</h3>\n                                <p class=\"events-vedette-v2-card-description\">Quartiers vivants, festivals, gastronomie et scène artistique.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Montreal</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Culture</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"pleinair\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=600&amp;h=400&amp;fit=crop\" alt=\"Mont-Tremblant actif\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Ski</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Mont-Tremblant actif</h3>\n                                <p class=\"events-vedette-v2-card-description\">Station quatre saisons pour ski, randonnée, vélo et détente.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Laurentians</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Plein air</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"nature\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=600&amp;h=400&amp;fit=crop\" alt=\"Mauricie sauvage\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Forêt</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Mauricie sauvage</h3>\n                                <p class=\"events-vedette-v2-card-description\">Parcs, lacs, forêts et expériences nature authentiques.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Mauricie</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Forêt</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"culture\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=600&amp;h=400&amp;fit=crop\" alt=\"Magdalen Islands\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Mer</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Magdalen Islands</h3>\n                                <p class=\"events-vedette-v2-card-description\">Falaises rouges, plages, culture acadienne et horizons marins.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Golfe du Saint-Laurent</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Culture maritime</span>\n                                </div>\n                            </div>\n                        </article>\n                                    </div>\n            </div>\n            <button class=\"vedette-carousel-btn vedette-carousel-next\" id=\"destination-vedetteNext\" aria-label=\"Next\"><i class=\"fas fa-chevron-right\"></i></button>\n        </div>\n        <div class=\"vedette-carousel-progress\"><div class=\"vedette-carousel-bar\" id=\"destination-vedetteBar\"></div></div>\n\n                    <div class=\"mss-gallery-wrapper\">\n\n    <div class=\"mss-gallery-container\">\n        <div class=\"mss-gallery-track\" id=\"destination-vedetteMediaTrack\">\n\n                                    <div class=\"mss-gallery-slide\">\n\n                \n                <div class=\"mss-gallery-col mss-gallery-col--half mss-gallery-main mss-gallery-item\"\n                     data-video=\"M-2eAiU09qg\"\n                     data-title=\"Destinations vedettes\">\n                                            <div class=\"mss-gallery-badge mss-gallery-badge--trending\">trending</div>\n                                        <img src=\"https://images.unsplash.com/photo-1519178614-68673b201f36?w=900&amp;h=500&amp;fit=crop\" alt=\"Destinations vedettes\" loading=\"eager\">\n                    <div class=\"mss-gallery-overlay\">\n                        <div class=\"mss-gallery-title\">Destinations vedettes</div>\n                        <div class=\"mss-gallery-desc\">Des lieux iconiques à présenter avec une narration forte et commerciale.</div>\n                    </div>\n                    <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                </div>\n\n                \n                <div class=\"mss-gallery-col mss-gallery-col--half mss-gallery-grid\">\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Nature grandiose\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--hot\">hot</div>\n                                                <img src=\"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=500&amp;h=300&amp;fit=crop\" alt=\"Nature grandiose\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Nature grandiose</div>\n                            <div class=\"mss-gallery-desc\">Paysages et parcs</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Culture urbaine\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--popular\">popular</div>\n                                                <img src=\"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?w=500&amp;h=300&amp;fit=crop\" alt=\"Culture urbaine\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Culture urbaine</div>\n                            <div class=\"mss-gallery-desc\">Arts et quartiers</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Plein air\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--new\">new</div>\n                                                <img src=\"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=500&amp;h=300&amp;fit=crop\" alt=\"Plein air\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Plein air</div>\n                            <div class=\"mss-gallery-desc\">Aventures quatre saisons</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Bord de mer\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--trending\">trending</div>\n                                                <img src=\"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=500&amp;h=300&amp;fit=crop\" alt=\"Bord de mer\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Bord de mer</div>\n                            <div class=\"mss-gallery-desc\">Évasion maritime</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                    </div>\n\n            </div>\n            \n        </div>\n    </div>\n\n    \n    <div class=\"mss-gallery-nav\">\n        <button class=\"mss-gallery-nav-btn\" id=\"destination-vedetteMediaPrev\" aria-label=\"Previous\">\n            <i class=\"fas fa-chevron-left\"></i>\n        </button>\n        <div class=\"mss-gallery-dots\" id=\"destination-vedetteMediaDots\">\n                            <div class=\"mss-gallery-dot mss-gallery-dot--active\"\n                     data-idx=\"0\"></div>\n                    </div>\n        <button class=\"mss-gallery-nav-btn\" id=\"destination-vedetteMediaNext\" aria-label=\"Next\">\n            <i class=\"fas fa-chevron-right\"></i>\n        </button>\n    </div>\n\n</div>\n\n<div class=\"mss-gallery-modal\" id=\"destination-vedetteMediaModal\">\n    <div class=\"mss-gallery-modal-content\">\n        <div class=\"mss-gallery-modal-header\">\n            <h3 class=\"mss-gallery-modal-title\" id=\"destination-vedetteMediaModalTitle\">Video</h3>\n            <button class=\"mss-gallery-modal-close\" id=\"destination-vedetteMediaCloseModal\">&times;</button>\n        </div>\n        <div class=\"mss-gallery-video-container\" id=\"destination-vedetteMediaVideoCont\"></div>\n    </div>\n</div>\n\n            </div>\n</section>', NULL, '(function () {\n    \'use strict\';\n\n    var SLIDE_DURATION = 8000;\n    var TRANS_DURATION = 1500;\n\n    var track      = document.getElementById(\'destination-vedetteMediaTrack\');\n    var dotsWrap   = document.getElementById(\'destination-vedetteMediaDots\');\n    var modal      = document.getElementById(\'destination-vedetteMediaModal\');\n    var videoEl    = document.getElementById(\'destination-vedetteMediaVideoCont\');\n    var modalTitle = document.getElementById(\'destination-vedetteMediaModalTitle\');\n    var closeBtn   = document.getElementById(\'destination-vedetteMediaCloseModal\');\n    if (!track) return;\n\n    var total       = 1;\n    var current     = 0;\n    var position    = total > 1 ? 1 : 0;\n    var isAnimating = false;\n    var autoTimer   = null;\n    var dots        = dotsWrap ? Array.from(dotsWrap.querySelectorAll(\'.mss-gallery-dot\')) : [];\n\n    if (total > 1) {\n        var originalSlides = Array.from(track.children);\n        var firstClone = originalSlides[0].cloneNode(true);\n        var lastClone = originalSlides[originalSlides.length - 1].cloneNode(true);\n        firstClone.dataset.mssClone = \'first\';\n        lastClone.dataset.mssClone = \'last\';\n        track.appendChild(firstClone);\n        track.insertBefore(lastClone, originalSlides[0]);\n        track.style.transition = \'none\';\n        track.style.transform = \'translateX(-100%)\';\n    }\n\n    function updateDots() {\n        dots.forEach(function (d, i) {\n            d.classList.toggle(\'mss-gallery-dot--active\', i === current);\n        });\n    }\n\n    function settleLoopPosition() {\n        if (position === 0) {\n            position = total;\n            track.style.transition = \'none\';\n            track.style.transform = \'translateX(-\' + (position * 100) + \'%)\';\n            if (track) track.offsetWidth;\n        } else if (position === total + 1) {\n            position = 1;\n            track.style.transition = \'none\';\n            track.style.transform = \'translateX(-\' + (position * 100) + \'%)\';\n            if (track) track.offsetWidth;\n        }\n        isAnimating = false;\n    }\n\n    function moveToPosition(nextPosition, nextCurrent) {\n        if (isAnimating || total <= 1) return;\n        isAnimating = true;\n        position = nextPosition;\n        current = nextCurrent;\n        track.style.transition = \'transform \' + TRANS_DURATION + \'ms cubic-bezier(0.25, 0.46, 0.45, 0.94)\';\n        track.style.transform = \'translateX(-\' + (position * 100) + \'%)\';\n        updateDots();\n        setTimeout(settleLoopPosition, TRANS_DURATION + 30);\n    }\n\n    /* ---- Navigation ---- */\n    function goTo(n) {\n        if (isAnimating || total <= 1) return;\n        var nextCurrent = ((n % total) + total) % total;\n        var nextPosition = nextCurrent + 1;\n\n        if (current === total - 1 && nextCurrent === 0 && n > current) {\n            nextPosition = total + 1;\n        } else if (current === 0 && nextCurrent === total - 1 && n < current) {\n            nextPosition = 0;\n        }\n\n        moveToPosition(nextPosition, nextCurrent);\n    }\n\n    /* ---- Auto-play ---- */\n    function startAuto() {\n        clearInterval(autoTimer);\n        autoTimer = setInterval(function () { goTo(current + 1); }, SLIDE_DURATION);\n    }\n\n    function stopAuto() {\n        clearInterval(autoTimer);\n        autoTimer = null;\n    }\n\n    document.getElementById(\'destination-vedetteMediaPrev\').addEventListener(\'click\', function () {\n        stopAuto(); goTo(current - 1); startAuto();\n    });\n    document.getElementById(\'destination-vedetteMediaNext\').addEventListener(\'click\', function () {\n        stopAuto(); goTo(current + 1); startAuto();\n    });\n\n    dots.forEach(function (dot, i) {\n        dot.addEventListener(\'click\', function () { stopAuto(); goTo(i); startAuto(); });\n    });\n\n    /* ---- Modal vidéo ---- */\n    var ytFrameId = \'destination-vedetteMediaYtFrame\';\n    var ytErrId   = \'destination-vedetteMediaYtErr\';\n    var unavailableLabel = \"Vid\\u00e9o non disponible\";\n    var unavailableHint = \"Vid\\u00e9o introuvable ou non autoris\\u00e9e en int\\u00e9gration\";\n\n    var ytMsgHandler = function (e) {\n        if (!e.data) return;\n        try {\n            var msg = JSON.parse(e.data);\n            if (msg.event === \'onError\') {\n                var errDiv = document.getElementById(ytErrId);\n                var frame  = document.getElementById(ytFrameId);\n                if (errDiv) { errDiv.style.display = \'flex\'; }\n                if (frame)  { frame.style.display  = \'none\'; }\n            }\n        } catch (_) {}\n    };\n\n    function openModal(videoSrc, title) {\n        if (!modal || !videoSrc) return;\n        if (modalTitle) modalTitle.textContent = title || \'\';\n        if (videoSrc.indexOf(\'http\') === 0) {\n            videoEl.innerHTML = \'<video src=\"\' + videoSrc + \'\" controls autoplay style=\"width:100%;display:block;max-height:520px;background:#000;\"></video>\';\n        } else {\n            var origin = window.location.origin;\n            videoEl.innerHTML =\n                \'<div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;background:#000;\">\' +\n                \'<iframe id=\"\' + ytFrameId + \'\"\' +\n                \' src=\"https://www.youtube.com/embed/\' + videoSrc + \'?autoplay=1&rel=0&enablejsapi=1&origin=\' + origin + \'\"\' +\n                \' style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:none;\"\' +\n                \' allow=\"accelerometer;autoplay;clipboard-write;encrypted-media;gyroscope;picture-in-picture\" allowfullscreen></iframe>\' +\n                \'<div id=\"\' + ytErrId + \'\" style=\"display:none;position:absolute;inset:0;background:#0a1628;flex-direction:column;align-items:center;justify-content:center;gap:14px;\">\' +\n                \'<i class=\"fas fa-video-slash\" style=\"font-size:3rem;color:#f26522;\"></i>\' +\n                \'<p style=\"color:#fff;font-family:Montserrat,sans-serif;font-weight:700;margin:0;\">\' + unavailableLabel + \'</p>\' +\n                \'<p style=\"color:rgba(255,255,255,0.6);font-family:Montserrat,sans-serif;font-size:0.8rem;margin:0;\">\' + unavailableHint + \'</p>\' +\n                \'</div></div>\';\n            window.addEventListener(\'message\', ytMsgHandler);\n        }\n        modal.classList.add(\'mss-gallery-modal--active\');\n        document.body.style.overflow = \'hidden\';\n        stopAuto();\n    }\n\n    function closeModal() {\n        if (!modal) return;\n        modal.classList.remove(\'mss-gallery-modal--active\');\n        if (videoEl) videoEl.innerHTML = \'\';\n        document.body.style.overflow = \'\';\n        window.removeEventListener(\'message\', ytMsgHandler);\n        startAuto();\n    }\n\n    track.querySelectorAll(\'.mss-gallery-item\').forEach(function (item) {\n        item.addEventListener(\'click\', function () {\n            openModal(this.dataset.video, this.dataset.title);\n        });\n        var playBtn = item.querySelector(\'.mss-gallery-play\');\n        if (playBtn) {\n            playBtn.addEventListener(\'click\', function (e) {\n                e.stopPropagation();\n                openModal(item.dataset.video, item.dataset.title);\n            });\n        }\n    });\n\n    if (closeBtn) closeBtn.addEventListener(\'click\', closeModal);\n    if (modal)    modal.addEventListener(\'click\', function (e) { if (e.target === modal) closeModal(); });\n\n    document.addEventListener(\'keydown\', function (e) {\n        if (e.key === \'Escape\' && modal && modal.classList.contains(\'mss-gallery-modal--active\')) closeModal();\n    });\n\n    /* ---- Init ---- */\n    startAuto();\n})();\n\n(function () {\n    var wrapper = document.getElementById(\"destination-vedetteGrid\");\n    var section = wrapper ? wrapper.closest(\'section\') : null;\n    if (!wrapper || !section) return;\n\n    var GAP = 20;\n    var PAUSE = 3500;\n    var ANIM = 480;\n    var timer = null;\n    var busy = false;\n\n    function visibleCards() {\n        return Array.from(wrapper.children).filter(function (card) { return card.style.display !== \'none\'; });\n    }\n\n    function resetBar() {\n        var bar = document.getElementById(\"destination-vedetteBar\");\n        if (!bar) return;\n        bar.style.transition = \'none\';\n        bar.style.width = \'0%\';\n        if (bar) bar.offsetWidth;\n        bar.style.transition = \'width \' + PAUSE + \'ms linear\';\n        bar.style.width = \'100%\';\n    }\n\n    function shiftLeft() {\n        var cards = visibleCards();\n        if (busy || cards.length < 2) return;\n        busy = true;\n        if (!cards[0]) { busy = false; return; }\n        var shift = cards[0].offsetWidth + GAP;\n        wrapper.style.transition = \'transform \' + ANIM + \'ms cubic-bezier(0.4,0,0.2,1)\';\n        wrapper.style.transform = \'translateX(-\' + shift + \'px)\';\n        setTimeout(function () {\n            wrapper.style.transition = \'none\';\n            wrapper.style.transform = \'translateX(0)\';\n            wrapper.appendChild(cards[0]);\n            busy = false;\n            resetBar();\n        }, ANIM + 20);\n    }\n\n    function shiftRight() {\n        var cards = visibleCards();\n        if (busy || cards.length < 2) return;\n        busy = true;\n        var last = cards[cards.length - 1];\n        if (!last) { busy = false; return; }\n        var shift = last.offsetWidth + GAP;\n        wrapper.style.transition = \'none\';\n        wrapper.insertBefore(last, wrapper.firstChild);\n        wrapper.style.transform = \'translateX(-\' + shift + \'px)\';\n        if (wrapper) wrapper.offsetWidth;\n        wrapper.style.transition = \'transform \' + ANIM + \'ms cubic-bezier(0.4,0,0.2,1)\';\n        wrapper.style.transform = \'translateX(0)\';\n        setTimeout(function () { busy = false; resetBar(); }, ANIM + 20);\n    }\n\n    function startAuto() { timer = setInterval(shiftLeft, PAUSE); }\n    function stopAuto() { clearInterval(timer); }\n\n    resetBar();\n    section.addEventListener(\'mouseenter\', stopAuto);\n    section.addEventListener(\'mouseleave\', startAuto);\n    startAuto();\n\n    var prev = document.getElementById(\"destination-vedettePrev\");\n    var next = document.getElementById(\"destination-vedetteNext\");\n    if (prev) prev.addEventListener(\'click\', function () { stopAuto(); shiftRight(); startAuto(); });\n    if (next) next.addEventListener(\'click\', function () { stopAuto(); shiftLeft(); startAuto(); });\n\n    section.querySelectorAll(\'.events-vedette-v2-filter-btn\').forEach(function (btn) {\n        btn.addEventListener(\'click\', function () {\n            section.querySelectorAll(\'.events-vedette-v2-filter-btn\').forEach(function (item) { item.classList.remove(\'active\'); });\n            btn.classList.add(\'active\');\n            var filter = btn.getAttribute(\'data-filter\');\n            Array.from(wrapper.children).forEach(function (card) {\n                var category = card.getAttribute(\'data-category\') || \'\';\n                card.style.display = (filter === \'all\' || category === filter) ? \'\' : \'none\';\n            });\n            wrapper.style.transition = \'none\';\n            wrapper.style.transform = \'translateX(0)\';\n            busy = false;\n            resetBar();\n            stopAuto();\n            startAuto();\n        });\n    });\n})();', 'builder', 'grapesjs', NULL, 'fa-cube', 40, 1, '2026-07-13 12:20:18', '2026-07-13 12:24:53');
INSERT INTO `welcome_sections` (`id`, `zone_id`, `name`, `slug`, `view`, `html_content`, `css_content`, `js_content`, `content_source`, `editor`, `settings`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(25, 4, 'Hébergements vedette', 'vedettes-espace-evenement-videttehebergementvedette', 'welcome-home.components.espace_evenement_vidette.HebergementVedette', '<section class=\"events-vedette-v2-section featured-space-v2-section\" id=\"hebergement-vedette\">\n    <div class=\"events-vedette-v2-container\">\n        <div class=\"resto-header-block\">\n            <div class=\"resto-header-main\">\n                <div class=\"resto-header-logo-left\">\n                    <a href=\"#\" class=\"resto-accord-btn\" title=\"GoExploria\">\n                        <div class=\"logo-wrapper\">\n                            <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/logo.png\" alt=\"GoExploria\">\n                        </div>\n                        <span class=\"resto-accord-btn-label\">GoExploria</span>\n                        <span class=\"resto-accord-btn-cta\">\n                            <i class=\"fas fa-external-link-alt\"></i> Visit\n                        </span>\n                    </a>\n                </div>\n\n                <div class=\"resto-header-center\">\n                    <h1 class=\"resto-header-title\">ESPACE HÉBERGEMENT VEDETTE</h1>\n                    <p class=\"resto-header-subtitle\">Hôtels · chalets · auberges · hébergements insolites — Les séjours qui déclenchent la réservation.</p>\n                </div>\n\n                <div class=\"resto-header-logo-right\">\n                    <a href=\"https://goexploriabusiness.com/hebergements\" title=\"Find out\" target=\"_blank\" rel=\"noopener noreferrer\">\n                        <img class=\"bt-next-level-image\" src=\"https://goexploriabusiness.com/images/Next-level.png\" alt=\"Next Level\" loading=\"lazy\">\n                    </a>\n                </div>\n            </div>\n\n            <div class=\"resto-header-destinations-bar\">\n                <div class=\"resto-dest-row\">\n                    <div class=\"resto-dest-icon-box\">\n                        <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/REDI.png\" alt=\"Destinations\">\n                        <span>Destinations</span>\n                    </div>\n\n                    <div class=\"resto-dest-breadcrumb vp-dest-breadcrumb\">\n                        <select id=\"hebergement-vedette-continent-select\" class=\"vp-dest-select\" aria-label=\"Continent\">\n                            <option value=\"amerique-nord\">North America</option>\n                            <option value=\"europe\">Europe</option>\n                            <option value=\"afrique\">Africa</option>\n                            <option value=\"asie\">Asia</option>\n                            <option value=\"amerique-sud\">Amérique du Sud</option>\n                            <option value=\"oceanie\">Océanie</option>\n                        </select>\n                        <span class=\"resto-dest-sep\">/</span>\n                        <select id=\"hebergement-vedette-country-select\" class=\"vp-dest-select\" aria-label=\"Pays\">\n                            <option value=\"canada\">Canada</option>\n                        </select>\n                        <span class=\"resto-dest-sep\">/</span>\n                        <select id=\"hebergement-vedette-province-select\" class=\"vp-dest-select\" aria-label=\"Province\">\n                            <option value=\"quebec\">Quebec</option>\n                            <option value=\"ontario\">Ontario</option>\n                            <option value=\"alberta\">Alberta</option>\n                            <option value=\"colombie-britannique\">Colombie-Britannique</option>\n                            <option value=\"nouvelle-ecosse\">Nouvelle-Écosse</option>\n                        </select>\n                        <span class=\"resto-dest-sep\">/</span>\n                        <select id=\"hebergement-vedette-region-select\" class=\"vp-dest-select\" aria-label=\"Région\">\n                            <option value=\"region-de-quebec\">Quebec region</option>\n                            <option value=\"montreal-metro\">Montréal Métro</option>\n                            <option value=\"mauricie\">Mauricie</option>\n                            <option value=\"gaspesie\">Gaspésie</option>\n                            <option value=\"saguenay\">Saguenay</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class=\"resto-actions-row\">\n                    <div class=\"resto-header-ctas\">\n                        <div class=\"events-vedette-v2-filters\">\n                            <button class=\"events-vedette-v2-filter-btn active\" data-filter=\"all\">\n                                <i class=\"fas fa-th-large\"></i> All options\n                            </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"hotel\">\n                                    <i class=\"fas fa-hotel\"></i> Hotels\n                                </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"chalet\">\n                                    <i class=\"fas fa-house-chimney\"></i> Chalets\n                                </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"auberge\">\n                                    <i class=\"fas fa-bed\"></i> Auberges\n                                </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"insolite\">\n                                    <i class=\"fas fa-campground\"></i> Insolites\n                                </button>\n                                                    </div>\n                        <a href=\"https://goexploriabusiness.com/hebergements\" class=\"resto-cta-btn secondary\" target=\"_blank\" rel=\"noopener noreferrer\">\n                            Find out <span class=\"cta-plus\">+</span>\n                        </a>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"resto-header-shimmer\"></div>\n        </div>\n\n        <div class=\"vedette-carousel-outer\">\n            <button class=\"vedette-carousel-btn vedette-carousel-prev\" id=\"hebergement-vedettePrev\" aria-label=\"Previous\"><i class=\"fas fa-chevron-left\"></i></button>\n            <div class=\"events-vedette-v2-scroll-wrapper\">\n                <div class=\"events-vedette-v2-scroll-container\" id=\"hebergement-vedetteGrid\">\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"hotel\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1566073771259-6a8506099945?w=600&amp;h=400&amp;fit=crop\" alt=\"Hôtel boutique centre-ville\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Hôtel</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Hôtel boutique centre-ville</h3>\n                                <p class=\"events-vedette-v2-card-description\">Confort, design et accès rapide aux attraits touristiques.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Montreal</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Hôtel</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"chalet\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1518780664697-55e3ad937233?w=600&amp;h=400&amp;fit=crop\" alt=\"Chalet bord de lac\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Chalet</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Chalet bord de lac</h3>\n                                <p class=\"events-vedette-v2-card-description\">Un refuge chaleureux pour escapades familiales et week-ends nature.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Laurentians</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Chalet</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"auberge\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1501117716987-c8e1ecb210e0?w=600&amp;h=400&amp;fit=crop\" alt=\"Auberge de charme terroir\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Auberge</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Auberge de charme terroir</h3>\n                                <p class=\"events-vedette-v2-card-description\">Accueil humain, cuisine locale et atmosphère de village.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Charlevoix</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Auberge</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"insolite\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1504851149312-7a075b496cc7?w=600&amp;h=400&amp;fit=crop\" alt=\"Dôme nature panoramique\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Insolite</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Dôme nature panoramique</h3>\n                                <p class=\"events-vedette-v2-card-description\">Dormir sous les étoiles avec confort et vue immersive.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Estrie</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Insolite</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"hotel\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?w=600&amp;h=400&amp;fit=crop\" alt=\"Resort spa &amp; détente\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Spa</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Resort spa &amp; détente</h3>\n                                <p class=\"events-vedette-v2-card-description\">Séjour bien-être, piscines, soins et gastronomie.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Quebec</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Spa</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"chalet\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1523217582562-09d0def993a6?w=600&amp;h=400&amp;fit=crop\" alt=\"Chalet familial premium\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Famille</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Chalet familial premium</h3>\n                                <p class=\"events-vedette-v2-card-description\">Grand espace, cuisine complète et accès aux activités.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Mauricie</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Famille</span>\n                                </div>\n                            </div>\n                        </article>\n                                    </div>\n            </div>\n            <button class=\"vedette-carousel-btn vedette-carousel-next\" id=\"hebergement-vedetteNext\" aria-label=\"Next\"><i class=\"fas fa-chevron-right\"></i></button>\n        </div>\n        <div class=\"vedette-carousel-progress\"><div class=\"vedette-carousel-bar\" id=\"hebergement-vedetteBar\"></div></div>\n\n                    <div class=\"mss-gallery-wrapper\">\n\n    <div class=\"mss-gallery-container\">\n        <div class=\"mss-gallery-track\" id=\"hebergement-vedetteMediaTrack\">\n\n                                    <div class=\"mss-gallery-slide\">\n\n                \n                <div class=\"mss-gallery-col mss-gallery-col--half mss-gallery-main mss-gallery-item\"\n                     data-video=\"M-2eAiU09qg\"\n                     data-title=\"Hébergements vedettes\">\n                                            <div class=\"mss-gallery-badge mss-gallery-badge--new\">new</div>\n                                        <img src=\"https://images.unsplash.com/photo-1566073771259-6a8506099945?w=900&amp;h=500&amp;fit=crop\" alt=\"Hébergements vedettes\" loading=\"eager\">\n                    <div class=\"mss-gallery-overlay\">\n                        <div class=\"mss-gallery-title\">Hébergements vedettes</div>\n                        <div class=\"mss-gallery-desc\">Une vitrine visuelle qui transforme l’envie de séjour en réservation.</div>\n                    </div>\n                    <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                </div>\n\n                \n                <div class=\"mss-gallery-col mss-gallery-col--half mss-gallery-grid\">\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Chalets nature\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--hot\">hot</div>\n                                                <img src=\"https://images.unsplash.com/photo-1518780664697-55e3ad937233?w=500&amp;h=300&amp;fit=crop\" alt=\"Chalets nature\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Chalets nature</div>\n                            <div class=\"mss-gallery-desc\">Séjours au calme</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Auberges\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--popular\">popular</div>\n                                                <img src=\"https://images.unsplash.com/photo-1501117716987-c8e1ecb210e0?w=500&amp;h=300&amp;fit=crop\" alt=\"Auberges\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Auberges</div>\n                            <div class=\"mss-gallery-desc\">Accueil local</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Insolite\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--trending\">trending</div>\n                                                <img src=\"https://images.unsplash.com/photo-1504851149312-7a075b496cc7?w=500&amp;h=300&amp;fit=crop\" alt=\"Insolite\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Insolite</div>\n                            <div class=\"mss-gallery-desc\">Expériences mémorables</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Spa &amp; resort\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--new\">new</div>\n                                                <img src=\"https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?w=500&amp;h=300&amp;fit=crop\" alt=\"Spa &amp; resort\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Spa &amp; resort</div>\n                            <div class=\"mss-gallery-desc\">Détente premium</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                    </div>\n\n            </div>\n            \n        </div>\n    </div>\n\n    \n    <div class=\"mss-gallery-nav\">\n        <button class=\"mss-gallery-nav-btn\" id=\"hebergement-vedetteMediaPrev\" aria-label=\"Previous\">\n            <i class=\"fas fa-chevron-left\"></i>\n        </button>\n        <div class=\"mss-gallery-dots\" id=\"hebergement-vedetteMediaDots\">\n                            <div class=\"mss-gallery-dot mss-gallery-dot--active\"\n                     data-idx=\"0\"></div>\n                    </div>\n        <button class=\"mss-gallery-nav-btn\" id=\"hebergement-vedetteMediaNext\" aria-label=\"Next\">\n            <i class=\"fas fa-chevron-right\"></i>\n        </button>\n    </div>\n\n</div>\n\n<div class=\"mss-gallery-modal\" id=\"hebergement-vedetteMediaModal\">\n    <div class=\"mss-gallery-modal-content\">\n        <div class=\"mss-gallery-modal-header\">\n            <h3 class=\"mss-gallery-modal-title\" id=\"hebergement-vedetteMediaModalTitle\">Video</h3>\n            <button class=\"mss-gallery-modal-close\" id=\"hebergement-vedetteMediaCloseModal\">&times;</button>\n        </div>\n        <div class=\"mss-gallery-video-container\" id=\"hebergement-vedetteMediaVideoCont\"></div>\n    </div>\n</div>\n\n            </div>\n</section>', NULL, '(function () {\n    \'use strict\';\n\n    var SLIDE_DURATION = 8000;\n    var TRANS_DURATION = 1500;\n\n    var track      = document.getElementById(\'hebergement-vedetteMediaTrack\');\n    var dotsWrap   = document.getElementById(\'hebergement-vedetteMediaDots\');\n    var modal      = document.getElementById(\'hebergement-vedetteMediaModal\');\n    var videoEl    = document.getElementById(\'hebergement-vedetteMediaVideoCont\');\n    var modalTitle = document.getElementById(\'hebergement-vedetteMediaModalTitle\');\n    var closeBtn   = document.getElementById(\'hebergement-vedetteMediaCloseModal\');\n    if (!track) return;\n\n    var total       = 1;\n    var current     = 0;\n    var position    = total > 1 ? 1 : 0;\n    var isAnimating = false;\n    var autoTimer   = null;\n    var dots        = dotsWrap ? Array.from(dotsWrap.querySelectorAll(\'.mss-gallery-dot\')) : [];\n\n    if (total > 1) {\n        var originalSlides = Array.from(track.children);\n        var firstClone = originalSlides[0].cloneNode(true);\n        var lastClone = originalSlides[originalSlides.length - 1].cloneNode(true);\n        firstClone.dataset.mssClone = \'first\';\n        lastClone.dataset.mssClone = \'last\';\n        track.appendChild(firstClone);\n        track.insertBefore(lastClone, originalSlides[0]);\n        track.style.transition = \'none\';\n        track.style.transform = \'translateX(-100%)\';\n    }\n\n    function updateDots() {\n        dots.forEach(function (d, i) {\n            d.classList.toggle(\'mss-gallery-dot--active\', i === current);\n        });\n    }\n\n    function settleLoopPosition() {\n        if (position === 0) {\n            position = total;\n            track.style.transition = \'none\';\n            track.style.transform = \'translateX(-\' + (position * 100) + \'%)\';\n            if (track) track.offsetWidth;\n        } else if (position === total + 1) {\n            position = 1;\n            track.style.transition = \'none\';\n            track.style.transform = \'translateX(-\' + (position * 100) + \'%)\';\n            if (track) track.offsetWidth;\n        }\n        isAnimating = false;\n    }\n\n    function moveToPosition(nextPosition, nextCurrent) {\n        if (isAnimating || total <= 1) return;\n        isAnimating = true;\n        position = nextPosition;\n        current = nextCurrent;\n        track.style.transition = \'transform \' + TRANS_DURATION + \'ms cubic-bezier(0.25, 0.46, 0.45, 0.94)\';\n        track.style.transform = \'translateX(-\' + (position * 100) + \'%)\';\n        updateDots();\n        setTimeout(settleLoopPosition, TRANS_DURATION + 30);\n    }\n\n    /* ---- Navigation ---- */\n    function goTo(n) {\n        if (isAnimating || total <= 1) return;\n        var nextCurrent = ((n % total) + total) % total;\n        var nextPosition = nextCurrent + 1;\n\n        if (current === total - 1 && nextCurrent === 0 && n > current) {\n            nextPosition = total + 1;\n        } else if (current === 0 && nextCurrent === total - 1 && n < current) {\n            nextPosition = 0;\n        }\n\n        moveToPosition(nextPosition, nextCurrent);\n    }\n\n    /* ---- Auto-play ---- */\n    function startAuto() {\n        clearInterval(autoTimer);\n        autoTimer = setInterval(function () { goTo(current + 1); }, SLIDE_DURATION);\n    }\n\n    function stopAuto() {\n        clearInterval(autoTimer);\n        autoTimer = null;\n    }\n\n    document.getElementById(\'hebergement-vedetteMediaPrev\').addEventListener(\'click\', function () {\n        stopAuto(); goTo(current - 1); startAuto();\n    });\n    document.getElementById(\'hebergement-vedetteMediaNext\').addEventListener(\'click\', function () {\n        stopAuto(); goTo(current + 1); startAuto();\n    });\n\n    dots.forEach(function (dot, i) {\n        dot.addEventListener(\'click\', function () { stopAuto(); goTo(i); startAuto(); });\n    });\n\n    /* ---- Modal vidéo ---- */\n    var ytFrameId = \'hebergement-vedetteMediaYtFrame\';\n    var ytErrId   = \'hebergement-vedetteMediaYtErr\';\n    var unavailableLabel = \"Vid\\u00e9o non disponible\";\n    var unavailableHint = \"Vid\\u00e9o introuvable ou non autoris\\u00e9e en int\\u00e9gration\";\n\n    var ytMsgHandler = function (e) {\n        if (!e.data) return;\n        try {\n            var msg = JSON.parse(e.data);\n            if (msg.event === \'onError\') {\n                var errDiv = document.getElementById(ytErrId);\n                var frame  = document.getElementById(ytFrameId);\n                if (errDiv) { errDiv.style.display = \'flex\'; }\n                if (frame)  { frame.style.display  = \'none\'; }\n            }\n        } catch (_) {}\n    };\n\n    function openModal(videoSrc, title) {\n        if (!modal || !videoSrc) return;\n        if (modalTitle) modalTitle.textContent = title || \'\';\n        if (videoSrc.indexOf(\'http\') === 0) {\n            videoEl.innerHTML = \'<video src=\"\' + videoSrc + \'\" controls autoplay style=\"width:100%;display:block;max-height:520px;background:#000;\"></video>\';\n        } else {\n            var origin = window.location.origin;\n            videoEl.innerHTML =\n                \'<div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;background:#000;\">\' +\n                \'<iframe id=\"\' + ytFrameId + \'\"\' +\n                \' src=\"https://www.youtube.com/embed/\' + videoSrc + \'?autoplay=1&rel=0&enablejsapi=1&origin=\' + origin + \'\"\' +\n                \' style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:none;\"\' +\n                \' allow=\"accelerometer;autoplay;clipboard-write;encrypted-media;gyroscope;picture-in-picture\" allowfullscreen></iframe>\' +\n                \'<div id=\"\' + ytErrId + \'\" style=\"display:none;position:absolute;inset:0;background:#0a1628;flex-direction:column;align-items:center;justify-content:center;gap:14px;\">\' +\n                \'<i class=\"fas fa-video-slash\" style=\"font-size:3rem;color:#f26522;\"></i>\' +\n                \'<p style=\"color:#fff;font-family:Montserrat,sans-serif;font-weight:700;margin:0;\">\' + unavailableLabel + \'</p>\' +\n                \'<p style=\"color:rgba(255,255,255,0.6);font-family:Montserrat,sans-serif;font-size:0.8rem;margin:0;\">\' + unavailableHint + \'</p>\' +\n                \'</div></div>\';\n            window.addEventListener(\'message\', ytMsgHandler);\n        }\n        modal.classList.add(\'mss-gallery-modal--active\');\n        document.body.style.overflow = \'hidden\';\n        stopAuto();\n    }\n\n    function closeModal() {\n        if (!modal) return;\n        modal.classList.remove(\'mss-gallery-modal--active\');\n        if (videoEl) videoEl.innerHTML = \'\';\n        document.body.style.overflow = \'\';\n        window.removeEventListener(\'message\', ytMsgHandler);\n        startAuto();\n    }\n\n    track.querySelectorAll(\'.mss-gallery-item\').forEach(function (item) {\n        item.addEventListener(\'click\', function () {\n            openModal(this.dataset.video, this.dataset.title);\n        });\n        var playBtn = item.querySelector(\'.mss-gallery-play\');\n        if (playBtn) {\n            playBtn.addEventListener(\'click\', function (e) {\n                e.stopPropagation();\n                openModal(item.dataset.video, item.dataset.title);\n            });\n        }\n    });\n\n    if (closeBtn) closeBtn.addEventListener(\'click\', closeModal);\n    if (modal)    modal.addEventListener(\'click\', function (e) { if (e.target === modal) closeModal(); });\n\n    document.addEventListener(\'keydown\', function (e) {\n        if (e.key === \'Escape\' && modal && modal.classList.contains(\'mss-gallery-modal--active\')) closeModal();\n    });\n\n    /* ---- Init ---- */\n    startAuto();\n})();\n\n(function () {\n    var wrapper = document.getElementById(\"hebergement-vedetteGrid\");\n    var section = wrapper ? wrapper.closest(\'section\') : null;\n    if (!wrapper || !section) return;\n\n    var GAP = 20;\n    var PAUSE = 3500;\n    var ANIM = 480;\n    var timer = null;\n    var busy = false;\n\n    function visibleCards() {\n        return Array.from(wrapper.children).filter(function (card) { return card.style.display !== \'none\'; });\n    }\n\n    function resetBar() {\n        var bar = document.getElementById(\"hebergement-vedetteBar\");\n        if (!bar) return;\n        bar.style.transition = \'none\';\n        bar.style.width = \'0%\';\n        if (bar) bar.offsetWidth;\n        bar.style.transition = \'width \' + PAUSE + \'ms linear\';\n        bar.style.width = \'100%\';\n    }\n\n    function shiftLeft() {\n        var cards = visibleCards();\n        if (busy || cards.length < 2) return;\n        busy = true;\n        if (!cards[0]) { busy = false; return; }\n        var shift = cards[0].offsetWidth + GAP;\n        wrapper.style.transition = \'transform \' + ANIM + \'ms cubic-bezier(0.4,0,0.2,1)\';\n        wrapper.style.transform = \'translateX(-\' + shift + \'px)\';\n        setTimeout(function () {\n            wrapper.style.transition = \'none\';\n            wrapper.style.transform = \'translateX(0)\';\n            wrapper.appendChild(cards[0]);\n            busy = false;\n            resetBar();\n        }, ANIM + 20);\n    }\n\n    function shiftRight() {\n        var cards = visibleCards();\n        if (busy || cards.length < 2) return;\n        busy = true;\n        var last = cards[cards.length - 1];\n        if (!last) { busy = false; return; }\n        var shift = last.offsetWidth + GAP;\n        wrapper.style.transition = \'none\';\n        wrapper.insertBefore(last, wrapper.firstChild);\n        wrapper.style.transform = \'translateX(-\' + shift + \'px)\';\n        if (wrapper) wrapper.offsetWidth;\n        wrapper.style.transition = \'transform \' + ANIM + \'ms cubic-bezier(0.4,0,0.2,1)\';\n        wrapper.style.transform = \'translateX(0)\';\n        setTimeout(function () { busy = false; resetBar(); }, ANIM + 20);\n    }\n\n    function startAuto() { timer = setInterval(shiftLeft, PAUSE); }\n    function stopAuto() { clearInterval(timer); }\n\n    resetBar();\n    section.addEventListener(\'mouseenter\', stopAuto);\n    section.addEventListener(\'mouseleave\', startAuto);\n    startAuto();\n\n    var prev = document.getElementById(\"hebergement-vedettePrev\");\n    var next = document.getElementById(\"hebergement-vedetteNext\");\n    if (prev) prev.addEventListener(\'click\', function () { stopAuto(); shiftRight(); startAuto(); });\n    if (next) next.addEventListener(\'click\', function () { stopAuto(); shiftLeft(); startAuto(); });\n\n    section.querySelectorAll(\'.events-vedette-v2-filter-btn\').forEach(function (btn) {\n        btn.addEventListener(\'click\', function () {\n            section.querySelectorAll(\'.events-vedette-v2-filter-btn\').forEach(function (item) { item.classList.remove(\'active\'); });\n            btn.classList.add(\'active\');\n            var filter = btn.getAttribute(\'data-filter\');\n            Array.from(wrapper.children).forEach(function (card) {\n                var category = card.getAttribute(\'data-category\') || \'\';\n                card.style.display = (filter === \'all\' || category === filter) ? \'\' : \'none\';\n            });\n            wrapper.style.transition = \'none\';\n            wrapper.style.transform = \'translateX(0)\';\n            busy = false;\n            resetBar();\n            stopAuto();\n            startAuto();\n        });\n    });\n})();', 'builder', 'grapesjs', NULL, 'fa-cube', 50, 1, '2026-07-13 12:20:18', '2026-07-13 12:24:53');
INSERT INTO `welcome_sections` (`id`, `zone_id`, `name`, `slug`, `view`, `html_content`, `css_content`, `js_content`, `content_source`, `editor`, `settings`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(26, 4, 'Produits vedette', 'vedettes-espace-evenement-videtteproduitvedette', 'welcome-home.components.espace_evenement_vidette.ProduitVedette', '<section class=\"events-vedette-v2-section featured-space-v2-section\" id=\"produit-vedette-evenement\">\n    <div class=\"events-vedette-v2-container\">\n        <div class=\"resto-header-block\">\n            <div class=\"resto-header-main\">\n                <div class=\"resto-header-logo-left\">\n                    <a href=\"#\" class=\"resto-accord-btn\" title=\"GoExploria\">\n                        <div class=\"logo-wrapper\">\n                            <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/logo.png\" alt=\"GoExploria\">\n                        </div>\n                        <span class=\"resto-accord-btn-label\">GoExploria</span>\n                        <span class=\"resto-accord-btn-cta\">\n                            <i class=\"fas fa-external-link-alt\"></i> Visit\n                        </span>\n                    </a>\n                </div>\n\n                <div class=\"resto-header-center\">\n                    <h1 class=\"resto-header-title\">ESPACE PRODUIT VEDETTE</h1>\n                    <p class=\"resto-header-subtitle\">Produits locaux · boutiques · souvenirs · cadeaux — Les articles qui méritent une mise en avant commerciale.</p>\n                </div>\n\n                <div class=\"resto-header-logo-right\">\n                    <a href=\"https://goexploriabusiness.com/produits\" title=\"Find out\" target=\"_blank\" rel=\"noopener noreferrer\">\n                        <img class=\"bt-next-level-image\" src=\"https://goexploriabusiness.com/images/Next-level.png\" alt=\"Next Level\" loading=\"lazy\">\n                    </a>\n                </div>\n            </div>\n\n            <div class=\"resto-header-destinations-bar\">\n                <div class=\"resto-dest-row\">\n                    <div class=\"resto-dest-icon-box\">\n                        <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/REDI.png\" alt=\"Destinations\">\n                        <span>Destinations</span>\n                    </div>\n\n                    <div class=\"resto-dest-breadcrumb vp-dest-breadcrumb\">\n                        <select id=\"produit-vedette-evenement-continent-select\" class=\"vp-dest-select\" aria-label=\"Continent\">\n                            <option value=\"amerique-nord\">North America</option>\n                            <option value=\"europe\">Europe</option>\n                            <option value=\"afrique\">Africa</option>\n                            <option value=\"asie\">Asia</option>\n                            <option value=\"amerique-sud\">Amérique du Sud</option>\n                            <option value=\"oceanie\">Océanie</option>\n                        </select>\n                        <span class=\"resto-dest-sep\">/</span>\n                        <select id=\"produit-vedette-evenement-country-select\" class=\"vp-dest-select\" aria-label=\"Pays\">\n                            <option value=\"canada\">Canada</option>\n                        </select>\n                        <span class=\"resto-dest-sep\">/</span>\n                        <select id=\"produit-vedette-evenement-province-select\" class=\"vp-dest-select\" aria-label=\"Province\">\n                            <option value=\"quebec\">Quebec</option>\n                            <option value=\"ontario\">Ontario</option>\n                            <option value=\"alberta\">Alberta</option>\n                            <option value=\"colombie-britannique\">Colombie-Britannique</option>\n                            <option value=\"nouvelle-ecosse\">Nouvelle-Écosse</option>\n                        </select>\n                        <span class=\"resto-dest-sep\">/</span>\n                        <select id=\"produit-vedette-evenement-region-select\" class=\"vp-dest-select\" aria-label=\"Région\">\n                            <option value=\"region-de-quebec\">Quebec region</option>\n                            <option value=\"montreal-metro\">Montréal Métro</option>\n                            <option value=\"mauricie\">Mauricie</option>\n                            <option value=\"gaspesie\">Gaspésie</option>\n                            <option value=\"saguenay\">Saguenay</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class=\"resto-actions-row\">\n                    <div class=\"resto-header-ctas\">\n                        <div class=\"events-vedette-v2-filters\">\n                            <button class=\"events-vedette-v2-filter-btn active\" data-filter=\"all\">\n                                <i class=\"fas fa-th-large\"></i> All options\n                            </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"terroir\">\n                                    <i class=\"fas fa-jar\"></i> Terroir\n                                </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"artisanat\">\n                                    <i class=\"fas fa-hands-holding\"></i> Artisanat\n                                </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"cadeaux\">\n                                    <i class=\"fas fa-gift\"></i> Cadeaux\n                                </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"pleinair\">\n                                    <i class=\"fas fa-campground\"></i> Plein air\n                                </button>\n                                                    </div>\n                        <a href=\"https://goexploriabusiness.com/produits\" class=\"resto-cta-btn secondary\" target=\"_blank\" rel=\"noopener noreferrer\">\n                            Find out <span class=\"cta-plus\">+</span>\n                        </a>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"resto-header-shimmer\"></div>\n        </div>\n\n        <div class=\"vedette-carousel-outer\">\n            <button class=\"vedette-carousel-btn vedette-carousel-prev\" id=\"produit-vedette-evenementPrev\" aria-label=\"Previous\"><i class=\"fas fa-chevron-left\"></i></button>\n            <div class=\"events-vedette-v2-scroll-wrapper\">\n                <div class=\"events-vedette-v2-scroll-container\" id=\"produit-vedette-evenementGrid\">\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"terroir\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1606787366850-de6330128bfc?w=600&amp;h=400&amp;fit=crop\" alt=\"Sirop d’érable premium\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Terroir</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Sirop d’érable premium</h3>\n                                <p class=\"events-vedette-v2-card-description\">Produit local emblématique pour touristes, familles et entreprises.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Quebec</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Gourmand</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"artisanat\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1513542789411-b6a5d4f31634?w=600&amp;h=400&amp;fit=crop\" alt=\"Affiche vintage Québec\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Artisan</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Affiche vintage Québec</h3>\n                                <p class=\"events-vedette-v2-card-description\">Souvenir design inspiré des destinations et quartiers iconiques.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Montreal</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Artisanat</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"cadeaux\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1513885535751-8b9238bd345a?w=600&amp;h=400&amp;fit=crop\" alt=\"Coffret découverte local\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Cadeau</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Coffret découverte local</h3>\n                                <p class=\"events-vedette-v2-card-description\">Une sélection cadeau prête à offrir pour toutes les occasions.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Canada</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Cadeau</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"pleinair\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1504280390367-361c6d9f38f4?w=600&amp;h=400&amp;fit=crop\" alt=\"Tente aventure 4 saisons\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Outdoor</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Tente aventure 4 saisons</h3>\n                                <p class=\"events-vedette-v2-card-description\">Produit vedette pour explorateurs et amateurs de plein air.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Laurentians</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Plein air</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"terroir\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1542838132-92c53300491e?w=600&amp;h=400&amp;fit=crop\" alt=\"Panier gourmand terroir\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Shopping cart</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Panier gourmand terroir</h3>\n                                <p class=\"events-vedette-v2-card-description\">Produits régionaux emballés pour cadeaux et événements.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Charlevoix</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Terroir</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"cadeaux\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1549465220-1a8b9238cd48?w=600&amp;h=400&amp;fit=crop\" alt=\"Carte cadeau destination\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Premium</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Carte cadeau destination</h3>\n                                <p class=\"events-vedette-v2-card-description\">Offrez une expérience GoExploria personnalisable.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">International</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Carte cadeau</span>\n                                </div>\n                            </div>\n                        </article>\n                                    </div>\n            </div>\n            <button class=\"vedette-carousel-btn vedette-carousel-next\" id=\"produit-vedette-evenementNext\" aria-label=\"Next\"><i class=\"fas fa-chevron-right\"></i></button>\n        </div>\n        <div class=\"vedette-carousel-progress\"><div class=\"vedette-carousel-bar\" id=\"produit-vedette-evenementBar\"></div></div>\n\n                    <div class=\"mss-gallery-wrapper\">\n\n    <div class=\"mss-gallery-container\">\n        <div class=\"mss-gallery-track\" id=\"produit-vedette-evenementMediaTrack\">\n\n                                    <div class=\"mss-gallery-slide\">\n\n                \n                <div class=\"mss-gallery-col mss-gallery-col--half mss-gallery-main mss-gallery-item\"\n                     data-video=\"M-2eAiU09qg\"\n                     data-title=\"Produits vedettes\">\n                                            <div class=\"mss-gallery-badge mss-gallery-badge--popular\">popular</div>\n                                        <img src=\"https://images.unsplash.com/photo-1513885535751-8b9238bd345a?w=900&amp;h=500&amp;fit=crop\" alt=\"Produits vedettes\" loading=\"eager\">\n                    <div class=\"mss-gallery-overlay\">\n                        <div class=\"mss-gallery-title\">Produits vedettes</div>\n                        <div class=\"mss-gallery-desc\">Mettez vos meilleurs produits au premier plan avec une vitrine dynamique.</div>\n                    </div>\n                    <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                </div>\n\n                \n                <div class=\"mss-gallery-col mss-gallery-col--half mss-gallery-grid\">\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Terroir\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--hot\">hot</div>\n                                                <img src=\"https://images.unsplash.com/photo-1606787366850-de6330128bfc?w=500&amp;h=300&amp;fit=crop\" alt=\"Terroir\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Terroir</div>\n                            <div class=\"mss-gallery-desc\">Saveurs locales</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Artisanat\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--new\">new</div>\n                                                <img src=\"https://images.unsplash.com/photo-1513542789411-b6a5d4f31634?w=500&amp;h=300&amp;fit=crop\" alt=\"Artisanat\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Artisanat</div>\n                            <div class=\"mss-gallery-desc\">Créations uniques</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Paniers cadeaux\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--trending\">trending</div>\n                                                <img src=\"https://images.unsplash.com/photo-1542838132-92c53300491e?w=500&amp;h=300&amp;fit=crop\" alt=\"Paniers cadeaux\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Paniers cadeaux</div>\n                            <div class=\"mss-gallery-desc\">Offres premium</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Plein air\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--popular\">popular</div>\n                                                <img src=\"https://images.unsplash.com/photo-1504280390367-361c6d9f38f4?w=500&amp;h=300&amp;fit=crop\" alt=\"Plein air\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Plein air</div>\n                            <div class=\"mss-gallery-desc\">Équipement vedette</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                    </div>\n\n            </div>\n            \n        </div>\n    </div>\n\n    \n    <div class=\"mss-gallery-nav\">\n        <button class=\"mss-gallery-nav-btn\" id=\"produit-vedette-evenementMediaPrev\" aria-label=\"Previous\">\n            <i class=\"fas fa-chevron-left\"></i>\n        </button>\n        <div class=\"mss-gallery-dots\" id=\"produit-vedette-evenementMediaDots\">\n                            <div class=\"mss-gallery-dot mss-gallery-dot--active\"\n                     data-idx=\"0\"></div>\n                    </div>\n        <button class=\"mss-gallery-nav-btn\" id=\"produit-vedette-evenementMediaNext\" aria-label=\"Next\">\n            <i class=\"fas fa-chevron-right\"></i>\n        </button>\n    </div>\n\n</div>\n\n<div class=\"mss-gallery-modal\" id=\"produit-vedette-evenementMediaModal\">\n    <div class=\"mss-gallery-modal-content\">\n        <div class=\"mss-gallery-modal-header\">\n            <h3 class=\"mss-gallery-modal-title\" id=\"produit-vedette-evenementMediaModalTitle\">Video</h3>\n            <button class=\"mss-gallery-modal-close\" id=\"produit-vedette-evenementMediaCloseModal\">&times;</button>\n        </div>\n        <div class=\"mss-gallery-video-container\" id=\"produit-vedette-evenementMediaVideoCont\"></div>\n    </div>\n</div>\n\n            </div>\n</section>', NULL, '(function () {\n    \'use strict\';\n\n    var SLIDE_DURATION = 8000;\n    var TRANS_DURATION = 1500;\n\n    var track      = document.getElementById(\'produit-vedette-evenementMediaTrack\');\n    var dotsWrap   = document.getElementById(\'produit-vedette-evenementMediaDots\');\n    var modal      = document.getElementById(\'produit-vedette-evenementMediaModal\');\n    var videoEl    = document.getElementById(\'produit-vedette-evenementMediaVideoCont\');\n    var modalTitle = document.getElementById(\'produit-vedette-evenementMediaModalTitle\');\n    var closeBtn   = document.getElementById(\'produit-vedette-evenementMediaCloseModal\');\n    if (!track) return;\n\n    var total       = 1;\n    var current     = 0;\n    var position    = total > 1 ? 1 : 0;\n    var isAnimating = false;\n    var autoTimer   = null;\n    var dots        = dotsWrap ? Array.from(dotsWrap.querySelectorAll(\'.mss-gallery-dot\')) : [];\n\n    if (total > 1) {\n        var originalSlides = Array.from(track.children);\n        var firstClone = originalSlides[0].cloneNode(true);\n        var lastClone = originalSlides[originalSlides.length - 1].cloneNode(true);\n        firstClone.dataset.mssClone = \'first\';\n        lastClone.dataset.mssClone = \'last\';\n        track.appendChild(firstClone);\n        track.insertBefore(lastClone, originalSlides[0]);\n        track.style.transition = \'none\';\n        track.style.transform = \'translateX(-100%)\';\n    }\n\n    function updateDots() {\n        dots.forEach(function (d, i) {\n            d.classList.toggle(\'mss-gallery-dot--active\', i === current);\n        });\n    }\n\n    function settleLoopPosition() {\n        if (position === 0) {\n            position = total;\n            track.style.transition = \'none\';\n            track.style.transform = \'translateX(-\' + (position * 100) + \'%)\';\n            if (track) track.offsetWidth;\n        } else if (position === total + 1) {\n            position = 1;\n            track.style.transition = \'none\';\n            track.style.transform = \'translateX(-\' + (position * 100) + \'%)\';\n            if (track) track.offsetWidth;\n        }\n        isAnimating = false;\n    }\n\n    function moveToPosition(nextPosition, nextCurrent) {\n        if (isAnimating || total <= 1) return;\n        isAnimating = true;\n        position = nextPosition;\n        current = nextCurrent;\n        track.style.transition = \'transform \' + TRANS_DURATION + \'ms cubic-bezier(0.25, 0.46, 0.45, 0.94)\';\n        track.style.transform = \'translateX(-\' + (position * 100) + \'%)\';\n        updateDots();\n        setTimeout(settleLoopPosition, TRANS_DURATION + 30);\n    }\n\n    /* ---- Navigation ---- */\n    function goTo(n) {\n        if (isAnimating || total <= 1) return;\n        var nextCurrent = ((n % total) + total) % total;\n        var nextPosition = nextCurrent + 1;\n\n        if (current === total - 1 && nextCurrent === 0 && n > current) {\n            nextPosition = total + 1;\n        } else if (current === 0 && nextCurrent === total - 1 && n < current) {\n            nextPosition = 0;\n        }\n\n        moveToPosition(nextPosition, nextCurrent);\n    }\n\n    /* ---- Auto-play ---- */\n    function startAuto() {\n        clearInterval(autoTimer);\n        autoTimer = setInterval(function () { goTo(current + 1); }, SLIDE_DURATION);\n    }\n\n    function stopAuto() {\n        clearInterval(autoTimer);\n        autoTimer = null;\n    }\n\n    document.getElementById(\'produit-vedette-evenementMediaPrev\').addEventListener(\'click\', function () {\n        stopAuto(); goTo(current - 1); startAuto();\n    });\n    document.getElementById(\'produit-vedette-evenementMediaNext\').addEventListener(\'click\', function () {\n        stopAuto(); goTo(current + 1); startAuto();\n    });\n\n    dots.forEach(function (dot, i) {\n        dot.addEventListener(\'click\', function () { stopAuto(); goTo(i); startAuto(); });\n    });\n\n    /* ---- Modal vidéo ---- */\n    var ytFrameId = \'produit-vedette-evenementMediaYtFrame\';\n    var ytErrId   = \'produit-vedette-evenementMediaYtErr\';\n    var unavailableLabel = \"Vid\\u00e9o non disponible\";\n    var unavailableHint = \"Vid\\u00e9o introuvable ou non autoris\\u00e9e en int\\u00e9gration\";\n\n    var ytMsgHandler = function (e) {\n        if (!e.data) return;\n        try {\n            var msg = JSON.parse(e.data);\n            if (msg.event === \'onError\') {\n                var errDiv = document.getElementById(ytErrId);\n                var frame  = document.getElementById(ytFrameId);\n                if (errDiv) { errDiv.style.display = \'flex\'; }\n                if (frame)  { frame.style.display  = \'none\'; }\n            }\n        } catch (_) {}\n    };\n\n    function openModal(videoSrc, title) {\n        if (!modal || !videoSrc) return;\n        if (modalTitle) modalTitle.textContent = title || \'\';\n        if (videoSrc.indexOf(\'http\') === 0) {\n            videoEl.innerHTML = \'<video src=\"\' + videoSrc + \'\" controls autoplay style=\"width:100%;display:block;max-height:520px;background:#000;\"></video>\';\n        } else {\n            var origin = window.location.origin;\n            videoEl.innerHTML =\n                \'<div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;background:#000;\">\' +\n                \'<iframe id=\"\' + ytFrameId + \'\"\' +\n                \' src=\"https://www.youtube.com/embed/\' + videoSrc + \'?autoplay=1&rel=0&enablejsapi=1&origin=\' + origin + \'\"\' +\n                \' style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:none;\"\' +\n                \' allow=\"accelerometer;autoplay;clipboard-write;encrypted-media;gyroscope;picture-in-picture\" allowfullscreen></iframe>\' +\n                \'<div id=\"\' + ytErrId + \'\" style=\"display:none;position:absolute;inset:0;background:#0a1628;flex-direction:column;align-items:center;justify-content:center;gap:14px;\">\' +\n                \'<i class=\"fas fa-video-slash\" style=\"font-size:3rem;color:#f26522;\"></i>\' +\n                \'<p style=\"color:#fff;font-family:Montserrat,sans-serif;font-weight:700;margin:0;\">\' + unavailableLabel + \'</p>\' +\n                \'<p style=\"color:rgba(255,255,255,0.6);font-family:Montserrat,sans-serif;font-size:0.8rem;margin:0;\">\' + unavailableHint + \'</p>\' +\n                \'</div></div>\';\n            window.addEventListener(\'message\', ytMsgHandler);\n        }\n        modal.classList.add(\'mss-gallery-modal--active\');\n        document.body.style.overflow = \'hidden\';\n        stopAuto();\n    }\n\n    function closeModal() {\n        if (!modal) return;\n        modal.classList.remove(\'mss-gallery-modal--active\');\n        if (videoEl) videoEl.innerHTML = \'\';\n        document.body.style.overflow = \'\';\n        window.removeEventListener(\'message\', ytMsgHandler);\n        startAuto();\n    }\n\n    track.querySelectorAll(\'.mss-gallery-item\').forEach(function (item) {\n        item.addEventListener(\'click\', function () {\n            openModal(this.dataset.video, this.dataset.title);\n        });\n        var playBtn = item.querySelector(\'.mss-gallery-play\');\n        if (playBtn) {\n            playBtn.addEventListener(\'click\', function (e) {\n                e.stopPropagation();\n                openModal(item.dataset.video, item.dataset.title);\n            });\n        }\n    });\n\n    if (closeBtn) closeBtn.addEventListener(\'click\', closeModal);\n    if (modal)    modal.addEventListener(\'click\', function (e) { if (e.target === modal) closeModal(); });\n\n    document.addEventListener(\'keydown\', function (e) {\n        if (e.key === \'Escape\' && modal && modal.classList.contains(\'mss-gallery-modal--active\')) closeModal();\n    });\n\n    /* ---- Init ---- */\n    startAuto();\n})();\n\n(function () {\n    var wrapper = document.getElementById(\"produit-vedette-evenementGrid\");\n    var section = wrapper ? wrapper.closest(\'section\') : null;\n    if (!wrapper || !section) return;\n\n    var GAP = 20;\n    var PAUSE = 3500;\n    var ANIM = 480;\n    var timer = null;\n    var busy = false;\n\n    function visibleCards() {\n        return Array.from(wrapper.children).filter(function (card) { return card.style.display !== \'none\'; });\n    }\n\n    function resetBar() {\n        var bar = document.getElementById(\"produit-vedette-evenementBar\");\n        if (!bar) return;\n        bar.style.transition = \'none\';\n        bar.style.width = \'0%\';\n        if (bar) bar.offsetWidth;\n        bar.style.transition = \'width \' + PAUSE + \'ms linear\';\n        bar.style.width = \'100%\';\n    }\n\n    function shiftLeft() {\n        var cards = visibleCards();\n        if (busy || cards.length < 2) return;\n        busy = true;\n        if (!cards[0]) { busy = false; return; }\n        var shift = cards[0].offsetWidth + GAP;\n        wrapper.style.transition = \'transform \' + ANIM + \'ms cubic-bezier(0.4,0,0.2,1)\';\n        wrapper.style.transform = \'translateX(-\' + shift + \'px)\';\n        setTimeout(function () {\n            wrapper.style.transition = \'none\';\n            wrapper.style.transform = \'translateX(0)\';\n            wrapper.appendChild(cards[0]);\n            busy = false;\n            resetBar();\n        }, ANIM + 20);\n    }\n\n    function shiftRight() {\n        var cards = visibleCards();\n        if (busy || cards.length < 2) return;\n        busy = true;\n        var last = cards[cards.length - 1];\n        if (!last) { busy = false; return; }\n        var shift = last.offsetWidth + GAP;\n        wrapper.style.transition = \'none\';\n        wrapper.insertBefore(last, wrapper.firstChild);\n        wrapper.style.transform = \'translateX(-\' + shift + \'px)\';\n        if (wrapper) wrapper.offsetWidth;\n        wrapper.style.transition = \'transform \' + ANIM + \'ms cubic-bezier(0.4,0,0.2,1)\';\n        wrapper.style.transform = \'translateX(0)\';\n        setTimeout(function () { busy = false; resetBar(); }, ANIM + 20);\n    }\n\n    function startAuto() { timer = setInterval(shiftLeft, PAUSE); }\n    function stopAuto() { clearInterval(timer); }\n\n    resetBar();\n    section.addEventListener(\'mouseenter\', stopAuto);\n    section.addEventListener(\'mouseleave\', startAuto);\n    startAuto();\n\n    var prev = document.getElementById(\"produit-vedette-evenementPrev\");\n    var next = document.getElementById(\"produit-vedette-evenementNext\");\n    if (prev) prev.addEventListener(\'click\', function () { stopAuto(); shiftRight(); startAuto(); });\n    if (next) next.addEventListener(\'click\', function () { stopAuto(); shiftLeft(); startAuto(); });\n\n    section.querySelectorAll(\'.events-vedette-v2-filter-btn\').forEach(function (btn) {\n        btn.addEventListener(\'click\', function () {\n            section.querySelectorAll(\'.events-vedette-v2-filter-btn\').forEach(function (item) { item.classList.remove(\'active\'); });\n            btn.classList.add(\'active\');\n            var filter = btn.getAttribute(\'data-filter\');\n            Array.from(wrapper.children).forEach(function (card) {\n                var category = card.getAttribute(\'data-category\') || \'\';\n                card.style.display = (filter === \'all\' || category === filter) ? \'\' : \'none\';\n            });\n            wrapper.style.transition = \'none\';\n            wrapper.style.transform = \'translateX(0)\';\n            busy = false;\n            resetBar();\n            stopAuto();\n            startAuto();\n        });\n    });\n})();', 'builder', 'grapesjs', NULL, 'fa-cube', 60, 1, '2026-07-13 12:20:18', '2026-07-13 12:24:53');
INSERT INTO `welcome_sections` (`id`, `zone_id`, `name`, `slug`, `view`, `html_content`, `css_content`, `js_content`, `content_source`, `editor`, `settings`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(27, 4, 'Entreprises vedette', 'vedettes-espace-evenement-videtteentreprisevedette', 'welcome-home.components.espace_evenement_vidette.EntrepriseVedette', '<section class=\"events-vedette-v2-section featured-space-v2-section\" id=\"entreprise-vedette\">\n    <div class=\"events-vedette-v2-container\">\n        <div class=\"resto-header-block\">\n            <div class=\"resto-header-main\">\n                <div class=\"resto-header-logo-left\">\n                    <a href=\"#\" class=\"resto-accord-btn\" title=\"GoExploria\">\n                        <div class=\"logo-wrapper\">\n                            <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/logo.png\" alt=\"GoExploria\">\n                        </div>\n                        <span class=\"resto-accord-btn-label\">GoExploria</span>\n                        <span class=\"resto-accord-btn-cta\">\n                            <i class=\"fas fa-external-link-alt\"></i> Visit\n                        </span>\n                    </a>\n                </div>\n\n                <div class=\"resto-header-center\">\n                    <h1 class=\"resto-header-title\">ESPACE ENTREPRISE VEDETTE</h1>\n                    <p class=\"resto-header-subtitle\">Entreprises locales · partenaires certifiés · services professionnels — Les marques à mettre en avant.</p>\n                </div>\n\n                <div class=\"resto-header-logo-right\">\n                    <a href=\"https://goexploriabusiness.com/entreprises\" title=\"Find out\" target=\"_blank\" rel=\"noopener noreferrer\">\n                        <img class=\"bt-next-level-image\" src=\"https://goexploriabusiness.com/images/Next-level.png\" alt=\"Next Level\" loading=\"lazy\">\n                    </a>\n                </div>\n            </div>\n\n            <div class=\"resto-header-destinations-bar\">\n                <div class=\"resto-dest-row\">\n                    <div class=\"resto-dest-icon-box\">\n             