                     <option value=\"region-de-quebec\">Quebec region</option>\n                            <option value=\"montreal-metro\">Montréal Métro</option>\n                            <option value=\"mauricie\">Mauricie</option>\n                            <option value=\"gaspesie\">Gaspésie</option>\n                            <option value=\"saguenay\">Saguenay</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class=\"resto-actions-row\">\n                    <div class=\"resto-header-ctas\">\n                        <div class=\"events-vedette-v2-filters\">\n                            <button class=\"events-vedette-v2-filter-btn active\" data-filter=\"all\">\n                                <i class=\"fas fa-th-large\"></i> All options\n                            </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"services\">\n                                    <i class=\"fas fa-briefcase\"></i> Services\n                                </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"tourisme\">\n                                    <i class=\"fas fa-route\"></i> Tourisme\n                                </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"commerce\">\n                                    <i class=\"fas fa-store\"></i> Commerce\n                                </button>\n                                                            <button class=\"events-vedette-v2-filter-btn\" data-filter=\"innovation\">\n                                    <i class=\"fas fa-lightbulb\"></i> Innovation\n                                </button>\n                                                    </div>\n                        <a href=\"https://goexploriabusiness.com/entreprises\" class=\"resto-cta-btn secondary\" target=\"_blank\" rel=\"noopener noreferrer\">\n                            Find out <span class=\"cta-plus\">+</span>\n                        </a>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"resto-header-shimmer\"></div>\n        </div>\n\n        <div class=\"vedette-carousel-outer\">\n            <button class=\"vedette-carousel-btn vedette-carousel-prev\" id=\"entreprise-vedettePrev\" aria-label=\"Previous\"><i class=\"fas fa-chevron-left\"></i></button>\n            <div class=\"events-vedette-v2-scroll-wrapper\">\n                <div class=\"events-vedette-v2-scroll-container\" id=\"entreprise-vedetteGrid\">\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"services\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1556761175-4b46a572b786?w=600&amp;h=400&amp;fit=crop\" alt=\"Agence expérience client\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Service</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Agence expérience client</h3>\n                                <p class=\"events-vedette-v2-card-description\">Accompagnement, visibilité et solutions web pour développer une marque locale.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Quebec</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Services</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"tourisme\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1521791136064-7986c2920216?w=600&amp;h=400&amp;fit=crop\" alt=\"Partenaire tourisme régional\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Tourisme</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Partenaire tourisme régional</h3>\n                                <p class=\"events-vedette-v2-card-description\">Entreprise experte en accueil, circuits et expériences de destination.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Charlevoix</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Tourisme</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"commerce\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1556740758-90de374c12ad?w=600&amp;h=400&amp;fit=crop\" alt=\"Boutique locale certifiée\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Commerce</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Boutique locale certifiée</h3>\n                                <p class=\"events-vedette-v2-card-description\">Produits, cadeaux, services et offres commerciales à forte valeur ajoutée.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Montreal</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Commerce</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"innovation\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1497366754035-f200968a6e72?w=600&amp;h=400&amp;fit=crop\" alt=\"Studio numérique touristique\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Innovation</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Studio numérique touristique</h3>\n                                <p class=\"events-vedette-v2-card-description\">Solutions digitales pour transformer les visiteurs en clients.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Canada</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Innovation</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"services\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1551836022-d5d88e9218df?w=600&amp;h=400&amp;fit=crop\" alt=\"Consultants croissance locale\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">Conseil</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Consultants croissance locale</h3>\n                                <p class=\"events-vedette-v2-card-description\">Stratégie, contenu, référencement et conversion pour entreprises.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">Laval</span>\n                                    <span class=\"events-vedette-v2-card-tag\">Conseil</span>\n                                </div>\n                            </div>\n                        </article>\n                                            <article class=\"events-vedette-v2-card featured-space-v2-card\" data-category=\"commerce\">\n                            <div class=\"events-vedette-v2-card-image\">\n                                <img src=\"https://images.unsplash.com/photo-1556761175-b413da4baf72?w=600&amp;h=400&amp;fit=crop\" alt=\"Réseau partenaires affaires\" loading=\"lazy\">\n                                <div class=\"events-vedette-v2-card-date featured-space-v2-badge\">\n                                    <span class=\"events-vedette-v2-date-text\">B2B</span>\n                                </div>\n                            </div>\n                            <div class=\"events-vedette-v2-card-content\">\n                                <h3 class=\"events-vedette-v2-card-title\">Réseau partenaires affaires</h3>\n                                <p class=\"events-vedette-v2-card-description\">Mise en relation, offres croisées et visibilité entre partenaires.</p>\n                                <div class=\"events-vedette-v2-card-footer\">\n                                    <span class=\"events-vedette-v2-card-location\">International</span>\n                                    <span class=\"events-vedette-v2-card-tag\">B2B</span>\n                                </div>\n                            </div>\n                        </article>\n                                    </div>\n            </div>\n            <button class=\"vedette-carousel-btn vedette-carousel-next\" id=\"entreprise-vedetteNext\" aria-label=\"Next\"><i class=\"fas fa-chevron-right\"></i></button>\n        </div>\n        <div class=\"vedette-carousel-progress\"><div class=\"vedette-carousel-bar\" id=\"entreprise-vedetteBar\"></div></div>\n\n                    <div class=\"mss-gallery-wrapper\">\n\n    <div class=\"mss-gallery-container\">\n        <div class=\"mss-gallery-track\" id=\"entreprise-vedetteMediaTrack\">\n\n                                    <div class=\"mss-gallery-slide\">\n\n                \n                <div class=\"mss-gallery-col mss-gallery-col--half mss-gallery-main mss-gallery-item\"\n                     data-video=\"M-2eAiU09qg\"\n                     data-title=\"Entreprises vedettes\">\n                                            <div class=\"mss-gallery-badge mss-gallery-badge--new\">new</div>\n                                        <img src=\"https://images.unsplash.com/photo-1556761175-4b46a572b786?w=900&amp;h=500&amp;fit=crop\" alt=\"Entreprises vedettes\" loading=\"eager\">\n                    <div class=\"mss-gallery-overlay\">\n                        <div class=\"mss-gallery-title\">Entreprises vedettes</div>\n                        <div class=\"mss-gallery-desc\">Une vitrine professionnelle pour valoriser les partenaires, commerces et services.</div>\n                    </div>\n                    <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                </div>\n\n                \n                <div class=\"mss-gallery-col mss-gallery-col--half mss-gallery-grid\">\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Partenaires tourisme\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--hot\">hot</div>\n                                                <img src=\"https://images.unsplash.com/photo-1521791136064-7986c2920216?w=500&amp;h=300&amp;fit=crop\" alt=\"Partenaires tourisme\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Partenaires tourisme</div>\n                            <div class=\"mss-gallery-desc\">Réseau destination</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Commerces locaux\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--popular\">popular</div>\n                                                <img src=\"https://images.unsplash.com/photo-1556740758-90de374c12ad?w=500&amp;h=300&amp;fit=crop\" alt=\"Commerces locaux\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Commerces locaux</div>\n                            <div class=\"mss-gallery-desc\">Offres à découvrir</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Innovation\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--trending\">trending</div>\n                                                <img src=\"https://images.unsplash.com/photo-1497366754035-f200968a6e72?w=500&amp;h=300&amp;fit=crop\" alt=\"Innovation\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Innovation</div>\n                            <div class=\"mss-gallery-desc\">Solutions digitales</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                        <div class=\"mss-gallery-tile mss-gallery-item\"\n                         data-video=\"M-2eAiU09qg\"\n                         data-title=\"Conseil\">\n                                                    <div class=\"mss-gallery-badge mss-gallery-badge--new\">new</div>\n                                                <img src=\"https://images.unsplash.com/photo-1551836022-d5d88e9218df?w=500&amp;h=300&amp;fit=crop\" alt=\"Conseil\" loading=\"lazy\">\n                        <div class=\"mss-gallery-overlay\">\n                            <div class=\"mss-gallery-title\">Conseil</div>\n                            <div class=\"mss-gallery-desc\">Croissance locale</div>\n                        </div>\n                        <div class=\"mss-gallery-play\"><i class=\"fas fa-play\"></i></div>\n                    </div>\n                                    </div>\n\n            </div>\n            \n        </div>\n    </div>\n\n    \n    <div class=\"mss-gallery-nav\">\n        <button class=\"mss-gallery-nav-btn\" id=\"entreprise-vedetteMediaPrev\" aria-label=\"Previous\">\n            <i class=\"fas fa-chevron-left\"></i>\n        </button>\n        <div class=\"mss-gallery-dots\" id=\"entreprise-vedetteMediaDots\">\n                            <div class=\"mss-gallery-dot mss-gallery-dot--active\"\n                     data-idx=\"0\"></div>\n                    </div>\n        <button class=\"mss-gallery-nav-btn\" id=\"entreprise-vedetteMediaNext\" aria-label=\"Next\">\n            <i class=\"fas fa-chevron-right\"></i>\n        </button>\n    </div>\n\n</div>\n\n<div class=\"mss-gallery-modal\" id=\"entreprise-vedetteMediaModal\">\n    <div class=\"mss-gallery-modal-content\">\n        <div class=\"mss-gallery-modal-header\">\n            <h3 class=\"mss-gallery-modal-title\" id=\"entreprise-vedetteMediaModalTitle\">Video</h3>\n            <button class=\"mss-gallery-modal-close\" id=\"entreprise-vedetteMediaCloseModal\">&times;</button>\n        </div>\n        <div class=\"mss-gallery-video-container\" id=\"entreprise-vedetteMediaVideoCont\"></div>\n    </div>\n</div>\n\n            </div>\n</section>', NULL, '(function () {\n    \'use strict\';\n\n    var SLIDE_DURATION = 8000;\n    var TRANS_DURATION = 1500;\n\n    var track      = document.getElementById(\'entreprise-vedetteMediaTrack\');\n    var dotsWrap   = document.getElementById(\'entreprise-vedetteMediaDots\');\n    var modal      = document.getElementById(\'entreprise-vedetteMediaModal\');\n    var videoEl    = document.getElementById(\'entreprise-vedetteMediaVideoCont\');\n    var modalTitle = document.getElementById(\'entreprise-vedetteMediaModalTitle\');\n    var closeBtn   = document.getElementById(\'entreprise-vedetteMediaCloseModal\');\n    if (!track) return;\n\n    var total       = 1;\n    var current     = 0;\n    var position    = total > 1 ? 1 : 0;\n    var isAnimating = false;\n    var autoTimer   = null;\n    var dots        = dotsWrap ? Array.from(dotsWrap.querySelectorAll(\'.mss-gallery-dot\')) : [];\n\n    if (total > 1) {\n        var originalSlides = Array.from(track.children);\n        var firstClone = originalSlides[0].cloneNode(true);\n        var lastClone = originalSlides[originalSlides.length - 1].cloneNode(true);\n        firstClone.dataset.mssClone = \'first\';\n        lastClone.dataset.mssClone = \'last\';\n        track.appendChild(firstClone);\n        track.insertBefore(lastClone, originalSlides[0]);\n        track.style.transition = \'none\';\n        track.style.transform = \'translateX(-100%)\';\n    }\n\n    function updateDots() {\n        dots.forEach(function (d, i) {\n            d.classList.toggle(\'mss-gallery-dot--active\', i === current);\n        });\n    }\n\n    function settleLoopPosition() {\n        if (position === 0) {\n            position = total;\n            track.style.transition = \'none\';\n            track.style.transform = \'translateX(-\' + (position * 100) + \'%)\';\n            if (track) track.offsetWidth;\n        } else if (position === total + 1) {\n            position = 1;\n            track.style.transition = \'none\';\n            track.style.transform = \'translateX(-\' + (position * 100) + \'%)\';\n            if (track) track.offsetWidth;\n        }\n        isAnimating = false;\n    }\n\n    function moveToPosition(nextPosition, nextCurrent) {\n        if (isAnimating || total <= 1) return;\n        isAnimating = true;\n        position = nextPosition;\n        current = nextCurrent;\n        track.style.transition = \'transform \' + TRANS_DURATION + \'ms cubic-bezier(0.25, 0.46, 0.45, 0.94)\';\n        track.style.transform = \'translateX(-\' + (position * 100) + \'%)\';\n        updateDots();\n        setTimeout(settleLoopPosition, TRANS_DURATION + 30);\n    }\n\n    /* ---- Navigation ---- */\n    function goTo(n) {\n        if (isAnimating || total <= 1) return;\n        var nextCurrent = ((n % total) + total) % total;\n        var nextPosition = nextCurrent + 1;\n\n        if (current === total - 1 && nextCurrent === 0 && n > current) {\n            nextPosition = total + 1;\n        } else if (current === 0 && nextCurrent === total - 1 && n < current) {\n            nextPosition = 0;\n        }\n\n        moveToPosition(nextPosition, nextCurrent);\n    }\n\n    /* ---- Auto-play ---- */\n    function startAuto() {\n        clearInterval(autoTimer);\n        autoTimer = setInterval(function () { goTo(current + 1); }, SLIDE_DURATION);\n    }\n\n    function stopAuto() {\n        clearInterval(autoTimer);\n        autoTimer = null;\n    }\n\n    document.getElementById(\'entreprise-vedetteMediaPrev\').addEventListener(\'click\', function () {\n        stopAuto(); goTo(current - 1); startAuto();\n    });\n    document.getElementById(\'entreprise-vedetteMediaNext\').addEventListener(\'click\', function () {\n        stopAuto(); goTo(current + 1); startAuto();\n    });\n\n    dots.forEach(function (dot, i) {\n        dot.addEventListener(\'click\', function () { stopAuto(); goTo(i); startAuto(); });\n    });\n\n    /* ---- Modal vidéo ---- */\n    var ytFrameId = \'entreprise-vedetteMediaYtFrame\';\n    var ytErrId   = \'entreprise-vedetteMediaYtErr\';\n    var unavailableLabel = \"Vid\\u00e9o non disponible\";\n    var unavailableHint = \"Vid\\u00e9o introuvable ou non autoris\\u00e9e en int\\u00e9gration\";\n\n    var ytMsgHandler = function (e) {\n        if (!e.data) return;\n        try {\n            var msg = JSON.parse(e.data);\n            if (msg.event === \'onError\') {\n                var errDiv = document.getElementById(ytErrId);\n                var frame  = document.getElementById(ytFrameId);\n                if (errDiv) { errDiv.style.display = \'flex\'; }\n                if (frame)  { frame.style.display  = \'none\'; }\n            }\n        } catch (_) {}\n    };\n\n    function openModal(videoSrc, title) {\n        if (!modal || !videoSrc) return;\n        if (modalTitle) modalTitle.textContent = title || \'\';\n        if (videoSrc.indexOf(\'http\') === 0) {\n            videoEl.innerHTML = \'<video src=\"\' + videoSrc + \'\" controls autoplay style=\"width:100%;display:block;max-height:520px;background:#000;\"></video>\';\n        } else {\n            var origin = window.location.origin;\n            videoEl.innerHTML =\n                \'<div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;background:#000;\">\' +\n                \'<iframe id=\"\' + ytFrameId + \'\"\' +\n                \' src=\"https://www.youtube.com/embed/\' + videoSrc + \'?autoplay=1&rel=0&enablejsapi=1&origin=\' + origin + \'\"\' +\n                \' style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:none;\"\' +\n                \' allow=\"accelerometer;autoplay;clipboard-write;encrypted-media;gyroscope;picture-in-picture\" allowfullscreen></iframe>\' +\n                \'<div id=\"\' + ytErrId + \'\" style=\"display:none;position:absolute;inset:0;background:#0a1628;flex-direction:column;align-items:center;justify-content:center;gap:14px;\">\' +\n                \'<i class=\"fas fa-video-slash\" style=\"font-size:3rem;color:#f26522;\"></i>\' +\n                \'<p style=\"color:#fff;font-family:Montserrat,sans-serif;font-weight:700;margin:0;\">\' + unavailableLabel + \'</p>\' +\n                \'<p style=\"color:rgba(255,255,255,0.6);font-family:Montserrat,sans-serif;font-size:0.8rem;margin:0;\">\' + unavailableHint + \'</p>\' +\n                \'</div></div>\';\n            window.addEventListener(\'message\', ytMsgHandler);\n        }\n        modal.classList.add(\'mss-gallery-modal--active\');\n        document.body.style.overflow = \'hidden\';\n        stopAuto();\n    }\n\n    function closeModal() {\n        if (!modal) return;\n        modal.classList.remove(\'mss-gallery-modal--active\');\n        if (videoEl) videoEl.innerHTML = \'\';\n        document.body.style.overflow = \'\';\n        window.removeEventListener(\'message\', ytMsgHandler);\n        startAuto();\n    }\n\n    track.querySelectorAll(\'.mss-gallery-item\').forEach(function (item) {\n        item.addEventListener(\'click\', function () {\n            openModal(this.dataset.video, this.dataset.title);\n        });\n        var playBtn = item.querySelector(\'.mss-gallery-play\');\n        if (playBtn) {\n            playBtn.addEventListener(\'click\', function (e) {\n                e.stopPropagation();\n                openModal(item.dataset.video, item.dataset.title);\n            });\n        }\n    });\n\n    if (closeBtn) closeBtn.addEventListener(\'click\', closeModal);\n    if (modal)    modal.addEventListener(\'click\', function (e) { if (e.target === modal) closeModal(); });\n\n    document.addEventListener(\'keydown\', function (e) {\n        if (e.key === \'Escape\' && modal && modal.classList.contains(\'mss-gallery-modal--active\')) closeModal();\n    });\n\n    /* ---- Init ---- */\n    startAuto();\n})();\n\n(function () {\n    var wrapper = document.getElementById(\"entreprise-vedetteGrid\");\n    var section = wrapper ? wrapper.closest(\'section\') : null;\n    if (!wrapper || !section) return;\n\n    var GAP = 20;\n    var PAUSE = 3500;\n    var ANIM = 480;\n    var timer = null;\n    var busy = false;\n\n    function visibleCards() {\n        return Array.from(wrapper.children).filter(function (card) { return card.style.display !== \'none\'; });\n    }\n\n    function resetBar() {\n        var bar = document.getElementById(\"entreprise-vedetteBar\");\n        if (!bar) return;\n        bar.style.transition = \'none\';\n        bar.style.width = \'0%\';\n        if (bar) bar.offsetWidth;\n        bar.style.transition = \'width \' + PAUSE + \'ms linear\';\n        bar.style.width = \'100%\';\n    }\n\n    function shiftLeft() {\n        var cards = visibleCards();\n        if (busy || cards.length < 2) return;\n        busy = true;\n        if (!cards[0]) { busy = false; return; }\n        var shift = cards[0].offsetWidth + GAP;\n        wrapper.style.transition = \'transform \' + ANIM + \'ms cubic-bezier(0.4,0,0.2,1)\';\n        wrapper.style.transform = \'translateX(-\' + shift + \'px)\';\n        setTimeout(function () {\n            wrapper.style.transition = \'none\';\n            wrapper.style.transform = \'translateX(0)\';\n            wrapper.appendChild(cards[0]);\n            busy = false;\n            resetBar();\n        }, ANIM + 20);\n    }\n\n    function shiftRight() {\n        var cards = visibleCards();\n        if (busy || cards.length < 2) return;\n        busy = true;\n        var last = cards[cards.length - 1];\n        if (!last) { busy = false; return; }\n        var shift = last.offsetWidth + GAP;\n        wrapper.style.transition = \'none\';\n        wrapper.insertBefore(last, wrapper.firstChild);\n        wrapper.style.transform = \'translateX(-\' + shift + \'px)\';\n        if (wrapper) wrapper.offsetWidth;\n        wrapper.style.transition = \'transform \' + ANIM + \'ms cubic-bezier(0.4,0,0.2,1)\';\n        wrapper.style.transform = \'translateX(0)\';\n        setTimeout(function () { busy = false; resetBar(); }, ANIM + 20);\n    }\n\n    function startAuto() { timer = setInterval(shiftLeft, PAUSE); }\n    function stopAuto() { clearInterval(timer); }\n\n    resetBar();\n    section.addEventListener(\'mouseenter\', stopAuto);\n    section.addEventListener(\'mouseleave\', startAuto);\n    startAuto();\n\n    var prev = document.getElementById(\"entreprise-vedettePrev\");\n    var next = document.getElementById(\"entreprise-vedetteNext\");\n    if (prev) prev.addEventListener(\'click\', function () { stopAuto(); shiftRight(); startAuto(); });\n    if (next) next.addEventListener(\'click\', function () { stopAuto(); shiftLeft(); startAuto(); });\n\n    section.querySelectorAll(\'.events-vedette-v2-filter-btn\').forEach(function (btn) {\n        btn.addEventListener(\'click\', function () {\n            section.querySelectorAll(\'.events-vedette-v2-filter-btn\').forEach(function (item) { item.classList.remove(\'active\'); });\n            btn.classList.add(\'active\');\n            var filter = btn.getAttribute(\'data-filter\');\n            Array.from(wrapper.children).forEach(function (card) {\n                var category = card.getAttribute(\'data-category\') || \'\';\n                card.style.display = (filter === \'all\' || category === filter) ? \'\' : \'none\';\n            });\n            wrapper.style.transition = \'none\';\n            wrapper.style.transform = \'translateX(0)\';\n            busy = false;\n            resetBar();\n            stopAuto();\n            startAuto();\n        });\n    });\n})();', 'builder', 'grapesjs', NULL, 'fa-cube', 70, 0, '2026-07-13 12:20:18', '2026-07-20 14:24:37');
INSERT INTO `welcome_sections` (`id`, `zone_id`, `name`, `slug`, `view`, `html_content`, `css_content`, `js_content`, `content_source`, `editor`, `settings`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(28, 4, 'Galerie vedette', 'vedettes-espace-evenement-videttegallerievedette', 'welcome-home.components.espace_evenement_vidette.GallerieVedette', '<section class=\"events-vedette-v2-section featured-space-v2-section\" id=\"gallerie-vedette\">\n    <div class=\"events-vedette-v2-container\">\n        <div class=\"resto-header-block\">\n            <div class=\"resto-header-main\">\n                <div class=\"resto-header-logo-left\">\n                    <a href=\"#\" class=\"resto-accord-btn\" title=\"GoExploria\">\n                        <div class=\"logo-wrapper\">\n                            <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/logo.png\" alt=\"GoExploria\">\n                        </div>\n                        <span class=\"resto-accord-btn-label\">GoExploria</span>\n                        <span class=\"resto-accord-btn-cta\">\n                            <i class=\"fas fa-external-link-alt\"></i> Visit\n                        </span>\n                    </a>\n                </div>\n\n                <div class=\"resto-header-center\">\n                    <h1 class=\"resto-header-title\">ESPACE GALLERIE VEDETTE</h1>\n                    <p class=\"resto-header-subtitle\">Photos premium · albums · inspirations visuelles · galeries thématiques — Les images qui déclenchent l’envie.</p>\n                </div>\n\n                <div class=\"resto-header-logo-right\">\n                    <a href=\"https://goexploriabusiness.com/galeries\" title=\"Find out\" target=\"_blank\" rel=\"noopener noreferrer\">\n                        <img class=\"bt-next-level-image\" src=\"https://goexploriabusiness.com/images/Next-level.png\" alt=\"Next Level\" loading=\"lazy\">\n                    </a>\n                </div>\n            </div>\n\n            <div class=\"resto-header-destinations-bar\">\n                <div class=\"resto-dest-row\">\n                    <div class=\"resto-dest-icon-box\">\n                        <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/REDI.png\" alt=\"Destinations\">\n                        <span>Destinations</span>\n                    </div>\n\n                    <div class=\"resto-dest-breadcrumb vp-dest-breadcrumb\">\n                        <select id=\"gallerie-vedette-continent-select\" class=\"vp-dest-select\" aria-label=\"Continent\">\n                            <option value=\"amerique-nord\">North America</option>\n                            <option value=\"europe\">Europe</option>\n                            <option value=\"afrique\">Africa</option>\n                            <option value=\"asie\">Asia</option>\n                            <option value=\"amerique-sud\">Amérique du Sud</option>\n                            <option value=\"oceanie\">Océanie</option>\n                        </select>\n                        <span class=\"resto-dest-sep\">/</span>\n                        <select id=\"gallerie-vedette-country-select\" class=\"vp-dest-select\" aria-label=\"Pays\">\n                            <option value=\"canada\">Canada</option>\n                        </select>\n                        <span class=\"resto-dest-sep\">/</span>\n                        <select id=\"gallerie-vedette-province-select\" class=\"vp-dest-select\" aria-label=\"Province\">\n                            <option value=\"quebec\">Quebec</option>\n                            <option value=\"ontario\">Ontario</option>\n                            <option value=\"alberta\">Alberta</option>\n                            <option value=\"colombie-britannique\">Colombie-Britannique</option>\n                            <option value=\"nouvelle-ecosse\">Nouvelle-Écosse</option>\n                        </select>\n                        <span class=\"resto-dest-sep\">/</span>\n                        <select id=\"gallerie-vedette-region-select\" class=\"vp-dest-select\" aria-label=\"Région\">\n                       