        }\n        modal.classList.add(\'mss-gallery-modal--active\');\n        document.body.style.overflow = \'hidden\';\n        stopAuto();\n    }\n\n    function closeModal() {\n        if (!modal) return;\n        modal.classList.remove(\'mss-gallery-modal--active\');\n        if (videoEl) videoEl.innerHTML = \'\';\n        document.body.style.overflow = \'\';\n        window.removeEventListener(\'message\', ytMsgHandler);\n        startAuto();\n    }\n\n    track.querySelectorAll(\'.mss-gallery-item\').forEach(function (item) {\n        item.addEventListener(\'click\', function () {\n            openModal(this.dataset.video, this.dataset.title);\n        });\n        var playBtn = item.querySelector(\'.mss-gallery-play\');\n        if (playBtn) {\n            playBtn.addEventListener(\'click\', function (e) {\n                e.stopPropagation();\n                openModal(item.dataset.video, item.dataset.title);\n            });\n        }\n    });\n\n    if (closeBtn) closeBtn.addEventListener(\'click\', closeModal);\n    if (modal)    modal.addEventListener(\'click\', function (e) { if (e.target === modal) closeModal(); });\n\n    document.addEventListener(\'keydown\', function (e) {\n        if (e.key === \'Escape\' && modal && modal.classList.contains(\'mss-gallery-modal--active\')) closeModal();\n    });\n\n    /* ---- Init ---- */\n    startAuto();\n})();\n\n(function () {\n    var wrapper = document.getElementById(\"gallerie-vedetteGrid\");\n    var section = wrapper ? wrapper.closest(\'section\') : null;\n    if (!wrapper || !section) return;\n\n    var GAP = 20;\n    var PAUSE = 3500;\n    var ANIM = 480;\n    var timer = null;\n    var busy = false;\n\n    function visibleCards() {\n        return Array.from(wrapper.children).filter(function (card) { return card.style.display !== \'none\'; });\n    }\n\n    function resetBar() {\n        var bar = document.getElementById(\"gallerie-vedetteBar\");\n        if (!bar) return;\n        bar.style.transition = \'none\';\n        bar.style.width = \'0%\';\n        if (bar) bar.offsetWidth;\n        bar.style.transition = \'width \' + PAUSE + \'ms linear\';\n        bar.style.width = \'100%\';\n    }\n\n    function shiftLeft() {\n        var cards = visibleCards();\n        if (busy || cards.length < 2) return;\n        busy = true;\n        if (!cards[0]) { busy = false; return; }\n        var shift = cards[0].offsetWidth + GAP;\n        wrapper.style.transition = \'transform \' + ANIM + \'ms cubic-bezier(0.4,0,0.2,1)\';\n        wrapper.style.transform = \'translateX(-\' + shift + \'px)\';\n        setTimeout(function () {\n            wrapper.style.transition = \'none\';\n            wrapper.style.transform = \'translateX(0)\';\n            wrapper.appendChild(cards[0]);\n            busy = false;\n            resetBar();\n        }, ANIM + 20);\n    }\n\n    function shiftRight() {\n        var cards = visibleCards();\n        if (busy || cards.length < 2) return;\n        busy = true;\n        var last = cards[cards.length - 1];\n        if (!last) { busy = false; return; }\n        var shift = last.offsetWidth + GAP;\n        wrapper.style.transition = \'none\';\n        wrapper.insertBefore(last, wrapper.firstChild);\n        wrapper.style.transform = \'translateX(-\' + shift + \'px)\';\n        if (wrapper) wrapper.offsetWidth;\n        wrapper.style.transition = \'transform \' + ANIM + \'ms cubic-bezier(0.4,0,0.2,1)\';\n        wrapper.style.transform = \'translateX(0)\';\n        setTimeout(function () { busy = false; resetBar(); }, ANIM + 20);\n    }\n\n    function startAuto() { timer = setInterval(shiftLeft, PAUSE); }\n    function stopAuto() { clearInterval(timer); }\n\n    resetBar();\n    section.addEventListener(\'mouseenter\', stopAuto);\n    section.addEventListener(\'mouseleave\', startAuto);\n    startAuto();\n\n    var prev = document.getElementById(\"gallerie-vedettePrev\");\n    var next = document.getElementById(\"gallerie-vedetteNext\");\n    if (prev) prev.addEventListener(\'click\', function () { stopAuto(); shiftRight(); startAuto(); });\n    if (next) next.addEventListener(\'click\', function () { stopAuto(); shiftLeft(); startAuto(); });\n\n    section.querySelectorAll(\'.events-vedette-v2-filter-btn\').forEach(function (btn) {\n        btn.addEventListener(\'click\', function () {\n            section.querySelectorAll(\'.events-vedette-v2-filter-btn\').forEach(function (item) { item.classList.remove(\'active\'); });\n            btn.classList.add(\'active\');\n            var filter = btn.getAttribute(\'data-filter\');\n            Array.from(wrapper.children).forEach(function (card) {\n                var category = card.getAttribute(\'data-category\') || \'\';\n                card.style.display = (filter === \'all\' || category === filter) ? \'\' : \'none\';\n            });\n            wrapper.style.transition = \'none\';\n            wrapper.style.transform = \'translateX(0)\';\n            busy = false;\n            resetBar();\n            stopAuto();\n            startAuto();\n        });\n    });\n})();', 'builder', 'grapesjs', NULL, 'fa-cube', 80, 1, '2026-07-13 12:20:18', '2026-07-13 12:24:53'),
(29, 5, 'Immobilier (Real Estate)', 'marketplace-espace-marketplacerealestatesection', 'welcome-home.components.espace_marketplace.RealEstateSection', '<section class=\"immo-v2-section\" id=\"real-estate-section\">\n\n    \n    <div class=\"resto-header-block\">\n        <div class=\"resto-header-main\">\n            <div class=\"resto-header-logo-left\">\n                <a href=\"#\" class=\"resto-accord-btn\" title=\"GoExploria\">\n                    <div class=\"logo-wrapper\">\n                        <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/logo.png\" alt=\"GoExploria\">\n                    </div>\n                    <span class=\"resto-accord-btn-label\">GoExploria</span>\n                    <span class=\"resto-accord-btn-cta\">\n                        <i class=\"fas fa-external-link-alt\"></i> Visit\n                    </span>\n                </a>\n            </div>\n            <div class=\"resto-header-center\">\n                <h1 class=\"resto-header-title\">FIND THE PROPERTY OF YOUR DREAMS</h1>\n                <p class=\"resto-header-subtitle\">\n                    Houses · Apartments · Villas · Studios — Properties selected to match your projects and your budget.\n                </p></div>\n            <div class=\"resto-header-logo-right\">\n                <a href=\"#\" class=\"resto-accord-btn\" title=\"Web Go Plans\">\n                    <div class=\"logo-wrapper\">\n                        <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/plan-n-go.png\" alt=\"Web Go Plans\">\n                    </div>\n                    <span class=\"resto-accord-btn-label\">Web Go Plans</span>\n                    <span class=\"resto-accord-btn-cta\">\n                        <i class=\"fas fa-external-link-alt\"></i> Visit\n                    </span>\n                </a>\n            </div>\n        </div>\n        <div class=\"resto-header-destinations-bar\">\n            <div class=\"resto-dest-row\">\n    <div class=\"resto-dest-icon-box\">\n        <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/REDI.png\" alt=\"Destinations\">\n        <span>Destinations</span>\n    </div>\n\n    <div class=\"resto-dest-breadcrumb vp-dest-breadcrumb\">\n        <select id=\"vp-continent-select\" class=\"vp-dest-select\" aria-label=\"Continent\">\n            <option value=\"amerique-nord\">North America</option>\n            <option value=\"europe\">Europe</option>\n            <option value=\"afrique\">Africa</option>\n            <option value=\"asie\">Asia</option>\n            <option value=\"amerique-sud\">Amérique du Sud</option>\n            <option value=\"oceanie\">Océanie</option>\n        </select>\n        <span class=\"resto-dest-sep\">/</span>\n        <select id=\"vp-country-select\" class=\"vp-dest-select\" aria-label=\"Pays\">\n            <option value=\"canada\">Canada</option>\n        </select>\n        <span class=\"resto-dest-sep\">/</span>\n        <select id=\"vp-province-select\" class=\"vp-dest-select\" aria-label=\"Province\">\n            <option value=\"quebec\">Quebec</option>\n            <option value=\"ontario\">Ontario</option>\n            <option value=\"alberta\">Alberta</option>\n            <option value=\"colombie-britannique\">Colombie-Britannique</option>\n            <option value=\"nouvelle-ecosse\">Nouvelle-Écosse</option>\n        </select>\n        <span class=\"resto-dest-sep\">/</span>\n        <select id=\"vp-region-select\" class=\"vp-dest-select\" aria-label=\"Region\">\n            <option value=\"region-de-quebec\">Quebec region</option>\n            <option value=\"montreal-metro\">Montréal Métro</option>\n            <option value=\"mauricie\">Mauricie</option>\n            <option value=\"gaspesie\">Gaspésie</option>\n            <option value=\"saguenay\">Saguenay</option>\n        </select>\n    </div>\n</div>\n        </div>\n    </div>\n\n    \n    <div class=\"immo-v2-container\">\n\n        <!-- GRILLE DE CARTES (4 propriétés) -->\n        <div class=\"immo-v2-grid\">\n            <!-- Carte 1 : Appartement moderne -->\n            <article class=\"immo-v2-card\">\n                <div class=\"immo-v2-card-img\">\n                    <img loading=\"lazy\" decoding=\"async\" src=\"https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=800&auto=format&fit=crop&q=70\" alt=\"Modern apartment\">\n                    <span class=\"immo-v2-img-badge\">For sale</span>\n                </div>\n                <div class=\"immo-v2-card-content\">\n                    <div class=\"immo-v2-price\">345 000 â‚¬</div>\n                    <h3 class=\"immo-v2-card-title\">Light Apartment</h3>\n                    <div class=\"immo-v2-location\"><i class=\"fas fa-map-pin\"></i> Center district, Lyon</div>\n                    <div class=\"immo-v2-features\">\n                        <span class=\"immo-v2-feature-item\"><i class=\"fas fa-arrows-alt\"></i> 85 m²</span>\n                        <span class=\"immo-v2-feature-item\"><i class=\"fas fa-bed\"></i> 3 bedrooms</span>\n                        <span class=\"immo-v2-feature-item\"><i class=\"fas fa-bath\"></i> 2 bathrooms</span>\n                    </div>\n                    <a href=\"#\" class=\"immo-v2-btn\">See details <i class=\"fas fa-arrow-right\"></i></a>\n                </div>\n            </article>\n\n            <!-- Carte 2 : Maison contemporaine -->\n            <article class=\"immo-v2-card\">\n                <div class=\"immo-v2-card-img\">\n                    <img loading=\"lazy\" decoding=\"async\" src=\"https://images.unsplash.com/photo-1564013799919-ab600027ffc6?w=800&auto=format&fit=crop&q=70\" alt=\"Contemporary house\">\n                    <span class=\"immo-v2-img-badge\">Favorite</span>\n                </div>\n                <div class=\"immo-v2-card-content\">\n                    <div class=\"immo-v2-price\">895 000 â‚¬</div>\n                    <h3 class=\"immo-v2-card-title\">Modern Villa</h3>\n                    <div class=\"immo-v2-location\"><i class=\"fas fa-map-pin\"></i> Saint-Germain, Paris</div>\n                    <div class=\"immo-v2-features\">\n                        <span class=\"immo-v2-feature-item\"><i class=\"fas fa-arrows-alt\"></i> 160 m²</span>\n                        <span class=\"immo-v2-feature-item\"><i class=\"fas fa-bed\"></i> 5 bedrooms</span>\n                        <span class=\"immo-v2-feature-item\"><i class=\"fas fa-tree\"></i> Garden 300 m²</span>\n                    </div>\n                    <a href=\"#\" class=\"immo-v2-btn\">See details <i class=\"fas fa-arrow-right\"></i></a>\n                </div>\n            </article>\n\n            <!-- Carte 3 : Studio investissement -->\n            <article class=\"immo-v2-card\">\n                <div class=\"immo-v2-card-img\">\n                    <img loading=\"lazy\" decoding=\"async\" src=\"https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800&auto=format&fit=crop&q=70\" alt=\"Renovated studio\">\n                    <span class=\"immo-v2-img-badge\">Investment</span>\n                </div>\n                <div class=\"immo-v2-card-content\">\n                    <div class=\"immo-v2-price\">125 000 â‚¬</div>\n                    <h3 class=\"immo-v2-card-title\">Studio Center</h3>\n                    <div class=\"immo-v2-location\"><i class=\"fas fa-map-pin\"></i> Bordeaux Center</div>\n                    <div class=\"immo-v2-features\">\n                        <span class=\"immo-v2-feature-item\"><i class=\"fas fa-arrows-alt\"></i> 32 m²</span>\n                        <span class=\"immo-v2-feature-item\"><i class=\"fas fa-door-open\"></i> 1 piece</span>\n                        <span class=\"immo-v2-feature-item\"><i class=\"fas fa-chart-line\"></i> Yield 6%</span>\n                    </div>\n                    <a href=\"#\" class=\"immo-v2-btn\">See details <i class=\"fas fa-arrow-right\"></i></a>\n                </div>\n            </article>\n\n            <!-- Carte 4 : Duplex de standing -->\n            <article class=\"immo-v2-card\">\n                <div class=\"immo-v2-card-img\">\n                    <img loading=\"lazy\" decoding=\"async\" src=\"https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=800&auto=format&fit=crop&q=70\" alt=\"Duplex terrace\">\n                    <span class=\"immo-v2-img-badge\">Exclusivity</span>\n                </div>\n                <div class=\"immo-v2-card-content\">\n                    <div class=\"immo-v2-price\">580 000 â‚¬</div>\n                    <h3 class=\"immo-v2-card-title\">Duplex Terrace</h3>\n                    <div class=\"immo-v2-location\"><i class=\"fas fa-map-pin\"></i> Montpellier</div>\n                    <div class=\"immo-v2-features\">\n                        <span class=\"immo-v2-feature-item\"><i class=\"fas fa-arrows-alt\"></i> 110 m²</span>\n                        <span class=\"immo-v2-feature-item\"><i class=\"fas fa-bed\"></i> 4 bedrooms</span>\n                        <span class=\"immo-v2-feature-item\"><i class=\"fas fa-sun\"></i> Terrace 40 m²</span>\n                    </div>\n                    <a href=\"#\" class=\"immo-v2-btn\">See details <i class=\"fas fa-arrow-right\"></i></a>\n                </div>\n            </article>\n        </div>\n\n        <!-- BLOC AGENT / CONTACT ÉDITABLE -->\n        <div class=\"immo-v2-agent-cta\">\n            <div class=\"immo-v2-agent-info\">\n                <img loading=\"lazy\" decoding=\"async\" class=\"immo-v2-agent-img\" src=\"https://images.unsplash.com/photo-1580489944761-15a19d654956?w=200&auto=format&fit=crop&q=60\" alt=\"Sophie Martin\">\n                <div class=\"immo-v2-agent-details\">\n                    <h4>Sophie Martin</h4>\n                    <p>Real estate advisor specializing in city centers</p>\n                    <p style=\"font-weight: 700; margin-top: 5px; color: #1a3a8f;\"><i class=\"fas fa-phone-alt\"></i> 06 12 34 56 78</p>\n                </div>\n            </div>\n            <a href=\"#\" class=\"immo-v2-contact-btn\"><i class=\"fas fa-envelope\"></i> Contact agent</a>\n        </div>\n    </div>\n</section>', NULL, NULL, 'builder', 'grapesjs', NULL, 'fa-cube', 10, 1, '2026-07-13 12:20:18', '2026-07-13 12:24:53');
