(30, 5, 'Produits vedette', 'marketplace-espace-marketplaceproductsvedette', 'welcome-home.components.espace_marketplace.ProductsVedette', '<section class=\"products-vedette-v2-section\" id=\"produits-vedette\">\n    <div class=\"products-vedette-v2-container\">\n\n        \n        <div class=\"resto-header-block\">\n\n            <div class=\"resto-header-main\">\n\n                \n                <div class=\"resto-header-logo-left\">\n                    <a href=\"#\" class=\"resto-accord-btn\" title=\"GoExploria\">\n                        <div class=\"logo-wrapper\">\n                            <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/logo.png\" alt=\"GoExploria\">\n                        </div>\n                        <span class=\"resto-accord-btn-label\">GoExploria</span>\n                        <span class=\"resto-accord-btn-cta\">\n                            <i class=\"fas fa-external-link-alt\"></i> Visit\n                        </span>\n                    </a>\n                </div>\n\n                \n                <div class=\"resto-header-center\">\n                    <h1 class=\"resto-header-title\">GOEXPLORIA SHOP — FEATURED PRODUCTS</h1>\n                    <p class=\"resto-header-subtitle\">\n                        Clothing · Shoes · Accessories · Equipment · Souvenirs — The official GoExploria selection inspired by Quebec.\n                    </p></div>\n\n                \n                <div class=\"resto-header-logo-right\">\n                    <a href=\"#\" class=\"resto-accord-btn\" title=\"GoExploria Store\">\n                        <div class=\"logo-wrapper\">\n                            <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/plan-n-go.png\" alt=\"GoExploria Store\">\n                        </div>\n                        <span class=\"resto-accord-btn-label\">Shop</span>\n                        <span class=\"resto-accord-btn-cta\">\n                            <i class=\"fas fa-shopping-bag\"></i> Buy\n                        </span>\n                    </a>\n                </div>\n\n            </div>\n\n            \n            <div class=\"resto-header-destinations-bar\">\n\n                <div class=\"resto-dest-row\">\n    <div class=\"resto-dest-icon-box\">\n        <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/REDI.png\" alt=\"Destinations\">\n        <span>Destinations</span>\n    </div>\n\n    <div class=\"resto-dest-breadcrumb vp-dest-breadcrumb\">\n        <select id=\"vp-continent-select\" class=\"vp-dest-select\" aria-label=\"Continent\">\n            <option value=\"amerique-nord\">North America</option>\n            <option value=\"europe\">Europe</option>\n            <option value=\"afrique\">Africa</option>\n            <option value=\"asie\">Asia</option>\n            <option value=\"amerique-sud\">Amérique du Sud</option>\n            <option value=\"oceanie\">Océanie</option>\n        </select>\n        <span class=\"resto-dest-sep\">/</span>\n        <select id=\"vp-country-select\" class=\"vp-dest-select\" aria-label=\"Pays\">\n            <option value=\"canada\">Canada</option>\n        </select>\n        <span class=\"resto-dest-sep\">/</span>\n        <select id=\"vp-province-select\" class=\"vp-dest-select\" aria-label=\"Province\">\n            <option value=\"quebec\">Quebec</option>\n            <option value=\"ontario\">Ontario</option>\n            <option value=\"alberta\">Alberta</option>\n            <option value=\"colombie-britannique\">Colombie-Britannique</option>\n            <option value=\"nouvelle-ecosse\">Nouvelle-Écosse</option>\n        </select>\n        <span class=\"resto-dest-sep\">/</span>\n        <select id=\"vp-region-select\" class=\"vp-dest-select\" aria-label=\"Region\">\n            <option value=\"region-de-quebec\">Quebec region</option>\n            <option value=\"montreal-metro\">Montréal Métro</option>\n            <option value=\"mauricie\">Mauricie</option>\n            <option value=\"gaspesie\">Gaspésie</option>\n            <option value=\"saguenay\">Saguenay</option>\n        </select>\n    </div>\n</div>\n\n                <div class=\"resto-actions-row\">\n                    <div class=\"resto-header-ctas\">\n                        <div class=\"products-vedette-v2-filters\">\n                            <button class=\"products-vedette-v2-filter-btn active\" data-filter=\"all\">\n                                <i class=\"fas fa-th-large\"></i> All categories\n                            </button>\n                                                            <button class=\"products-vedette-v2-filter-btn\" data-filter=\"vetements\">\n                                    <i class=\"fas fa-shirt\"></i> Vêtements\n                                </button>\n                                                            <button class=\"products-vedette-v2-filter-btn\" data-filter=\"chaussures\">\n                                    <i class=\"fas fa-shoe-prints\"></i> Chaussures\n                                </button>\n                                                            <button class=\"products-vedette-v2-filter-btn\" data-filter=\"accessoires\">\n                                    <i class=\"fas fa-hat-cowboy\"></i> Accessoires\n                                </button>\n                                                            <button class=\"products-vedette-v2-filter-btn\" data-filter=\"equipement\">\n                                    <i class=\"fas fa-campground\"></i> Équipement\n                                </button>\n                                                            <button class=\"products-vedette-v2-filter-btn\" data-filter=\"souvenirs\">\n                                    <i class=\"fas fa-gift\"></i> Souvenirs\n                                </button>\n                                                    </div>\n                        <a href=\"#\" class=\"resto-cta-btn secondary\">\n                            Find out <span class=\"cta-plus\">+</span>\n                        </a>\n                    </div>\n                </div>\n\n            </div>\n\n            <div class=\"resto-header-shimmer\"></div>\n        </div>\n\n        \n        <div class=\"vedette-carousel-outer products-vedette-v2-carousel\">\n            <button class=\"vedette-carousel-btn vedette-carousel-prev\" id=\"productsCarouselPrev\" aria-label=\"Previous\"><i class=\"fas fa-chevron-left\"></i></button>\n            <div class=\"products-vedette-v2-scroll-wrapper\">\n                <div class=\"products-vedette-v2-scroll-container\" id=\"productsVedetteGrid\">\n                                        <article class=\"products-vedette-v2-card\"\n                             data-category=\"vetements\"\n                             data-badge=\"promo\">\n                        <div class=\"products-vedette-v2-card-image\">\n                            <img src=\"https://images.unsplash.com/photo-1551028719-00167b16eac5?w=600&amp;h=600&amp;fit=crop\" alt=\"Parka Grand Nord Explorer\" loading=\"lazy\">\n\n                                                            <span class=\"products-vedette-v2-badge products-vedette-v2-badge--promo\">\n                                        <i class=\"fas fa-tag\"></i> PROMO                                 </span>\n                            \n                            <button class=\"products-vedette-v2-fav\" aria-label=\"Add to favorites\">\n                                <i class=\"far fa-heart\"></i>\n                            </button>\n\n                            <div class=\"products-vedette-v2-quick\">\n                                <button class=\"products-vedette-v2-quick-btn\" type=\"button\">\n                                    <i class=\"fas fa-eye\"></i> Quick view\n                                </button>\n                            </