(43, 8, 'Nouvelles régionales', 'info-espace-go-exp-infobloc-nouvelles-regionales', 'welcome-home.components.espace_go_exp_info.bloc-nouvelles-regionales', '<section class=\"nv-section\" id=\"nv-nouvelles\">\n\n    \n    <div class=\"resto-header-block\">\n        <div class=\"resto-header-main\">\n            <div class=\"resto-header-logo-left\">\n                <a href=\"#\" class=\"resto-accord-btn\" title=\"GoExploria\">\n                    <div class=\"logo-wrapper\">\n                        <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/logo.png\" alt=\"GoExploria\">\n                    </div>\n                    <span class=\"resto-accord-btn-label\">GoExploria</span>\n                    <span class=\"resto-accord-btn-cta\"><i class=\"fas fa-external-link-alt\"></i> Visit</span>\n                </a>\n            </div>\n            <div class=\"resto-header-center\">\n                <h1 class=\"resto-header-title\">NOUVELLES RÉGIONALES, NATIONALES &amp; INTERNATIONALES</h1>\n                <h2 class=\"resto-header-eyebrow\">Info locale &amp; régionale · Articles récents par région · Alertes Nouvelles</h2>\n                <p class=\"resto-header-subtitle\">Restez informé en temps réel avec les actualités les plus récentes par région — Afrique · Europe · Asie · Amériques. Inscrivez-vous aux Alertes Nouvelles régionales.</p>\n            </div>\n            \n            <div class=\"resto-header-logo-right\">\n                \n                <a href=\"\" title=\"Learn more\" target=\"_blank\" rel=\"noopener noreferrer\">\n                    <!-- <i class=\"fas fa-circle-info\"></i>\n                    <span>Go Next Level</span> -->\n                    <img\n                    class=\"bt-next-level-image\"\n                    src=\"https://goexploriabusiness.com/images/Next-level.png\"\n                    alt=\"Next Level\"\n                    loading=\"lazy\"\n                >\n                </a>\n            </div>\n        </div>\n\n        \n        <div class=\"resto-header-destinations-bar\">\n            <div class=\"resto-dest-row\">\n                <div class=\"resto-dest-icon-box\">\n                    <img loading=\"lazy\" decoding=\"async\" src=\"https://goexploriabusiness.com/REDI.png\" alt=\"Destinations\">\n                    <span>Destinations</span>\n                </div>\n                <div class=\"resto-dest-breadcrumb vp-dest-breadcrumb\">\n                    <select id=\"nv-continent-select\" class=\"vp-dest-select\" aria-label=\"Continent\">\n                        <option value=\"amerique-nord\">North America</option>\n                        <option value=\"europe\">Europe</option>\n                        <option value=\"afrique\">Africa</option>\n                        <option value=\"asie\">Asia</option>\n                        <option value=\"amerique-sud\">Amérique du Sud</option>\n                        <option value=\"oceanie\">Océanie</option>\n                    </select>\n                    <span class=\"resto-dest-sep\">/</span>\n                    <select id=\"nv-country-select\" class=\"vp-dest-select\" aria-label=\"Pays\">\n                        <option value=\"canada\">Canada</option>\n                    </select>\n                    <span class=\"resto-dest-sep\">/</span>\n                    <select id=\"nv-province-select\" class=\"vp-dest-select\" aria-label=\"Province\">\n                        <option value=\"quebec\">Quebec</option>\n                        <option value=\"ontario\">Ontario</option>\n                        <option value=\"alberta\">Alberta</option>\n                        <option value=\"colombie-britannique\">Colombie-Britannique</option>\n                        <option value=\"nouvelle-ecosse\">Nouvelle-Écosse</option>\n                    </select>\n                    <span class=\"resto-dest-sep\">/</span>\n                    <select id=\"nv-region-select\" class=\"vp-dest-select\" aria-label=\"Region\">\n                        <option value=\"region-de-quebec\">Quebec region</option>\n                        <option value=\"montreal-metro\">Montréal Métro</option>\n                        <option value=\"mauricie\">Mauricie</option>\n                        <option value=\"gaspesie\">Gaspésie</option>\n                        <option value=\"saguenay\">Saguenay</option>\n                    </select>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"resto-header-shimmer\"></div>\n    </div>\n\n    \n    <div class=\"nv-body\">\n\n        \n        <div class=\"nv-ticker\">\n            <div class=\"nv-ticker-label\"><i class=\"fas fa-circle\"></i> LIVE</div>\n            <div class=\"nv-ticker-track\">\n                <div class=\"nv-ticker-inner\">\n                    <span>🌍 Afrique : Nouveau sommet de l\'UA convoqué à Addis-Abeba</span>\n                    <span>🌍 Europe : La Commission européenne présente son plan énergie 2030</span>\n                    <span>🌏 Asie : Tokyo enregistre sa plus forte hausse boursière de l\'année</span>\n                    <span>🌎 Amériques : Le G7 se réunit à Ottawa pour la sécurité alimentaire</span>\n                    <span>🇨🇦 Canada : Québec annonce 3,2 Md$ pour l\'infrastructure régionale</span>\n                    <span>🌍 Afrique : Nouveau sommet de l\'UA convoqué à Addis-Abeba</span>\n                    <span>🌍 Europe : La Commission européenne présente son plan énergie 2030</span>\n                    <span>🌏 Asie : Tokyo enregistre sa plus forte hausse boursière de l\'année</span>\n                </div>\n            </div>\n        </div>\n\n        \n        <div class=\"nv-hero\">\n            <div class=\"nv-hero-featured\">\n                <div class=\"nv-hero-img-wrap\">\n                    <img loading=\"lazy\" decoding=\"async\" src=\"https://images.unsplash.com/photo-1504711434969-e33886168f5c?w=1200&q=80\"\n                         alt=\"Article vedette\" class=\"nv-hero-img\">\n                    <div class=\"nv-hero-overlay\">\n                        <span class=\"nv-hero-badge\"><i class=\"fas fa-fire\"></i> À la une</span>\n                        <div class=\"nv-hero-regions\">\n                            <span class=\"nv-region-pill\" style=\"background:#e8761a\">🌍 Mondial</span>\n                            <span class=\"nv-region-pill\" style=\"background:#1a3a8f\">International</span>\n                        </div>\n                        <h2 class=\"nv-hero-title\">Conférence mondiale sur le climat : 150 nations s&#039;engagent pour la neutralité carbone</h2>\n                        <p class=\"nv-hero-desc\">Un accord historique signé à Genève réunit les principales puissances mondiales autour d&#039;objectifs contraignants de réduction des émissions pour 2030 et 2050.</p>\n                        <div class=\"nv-hero-meta\">\n                            <span><i class=\"far fa-clock\"></i> Il y a 1 heure</span>\n                            <span><i class=\"far fa-eye\"></i> 48 200 lectures</span>\n                            <a href=\"https://goexploriabusiness.com/nouvelles/article/conference-mondiale-climat\" class=\"nv-hero-read-btn\" target=\"_blank\">\n                                Lire l&#039;article <i class=\"fas fa-arrow-right\"></i>\n                            </a>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            \n            <div class=\"nv-hero-sidebar\">\n                <div class=\"nv-sidebar-label\">\n                    <i class=\"fas fa-bolt\"></i> Dernière heure\n                </div>\n                                <a href=\"#\" class=\"nv-mini-article\">\n                    <div class=\"nv-mini-meta\">\n                        <span class=\"nv-mini-time\"><i class=\"far fa-clock\"></i> 12 min</span>\n                        <span class=\"nv-mini-cat\">Africa</span>\n                    </div>\n                    <p class=\"nv-mini-title\">Le Ghana inaugure son plus grand parc solaire d&#039;Afrique subsaharienne</p>\n                </a>\n                                <a href=\"#\" class=\"nv-mini-article\">\n                    <div class=\"nv-mini-meta\">\n                        <span class=\"nv-mini-time\"><i class=\"far fa-clock\"></i> 34 min</span>\n                        <span class=\"nv-mini-cat\">Europe</span>\n                    </div>\n                    <p class=\"nv-mini-title\">La France et l&#039;Allemagne signent un nouveau pacte de défense commune</p>\n                </a>\n                                <a href=\"#\" class=\"nv-mini-article\">\n                    <div class=\"nv-mini-meta\">\n                        <span class=\"nv-mini-time\"><i class=\"far fa-clock\"></i> 51 min</span>\n                        <span class=\"nv-mini-cat\">Asia</span>\n                    </div>\n                    <p class=\"nv-mini-title\">L&#039;Inde franchit le cap des 1,5 milliard d&#039;habitants connectés</p>\n                </a>\n                                <a href=\"#\" class=\"nv-mini-article\">\n                    <div class=\"nv-mini-meta\">\n                        <span class=\"nv-mini-time\"><i class=\"far fa-clock\"></i> 1h 12</span>\n                        <span class=\"nv-mini-cat\">Americas</span>\n                    </div>\n                    <p class=\"nv-mini-title\">Mexique : découverte archéologique majeure dans le Yucatán</p>\n                </a>\n                                <a href=\"#\" class=\"nv-mini-article\">\n                    <div class=\"nv-mini-meta\">\n                        <span class=\"nv-mini-time\"><i class=\"far fa-clock\"></i> 1h 45</span>\n                        <span class=\"nv-mini-cat\">Canada</span>\n                    </div>\n                    <p class=\"nv-mini-title\">Montréal classée 3e ville la plus connectée d&#039;Amérique du Nord</p>\n                </a>\n                            </div>\n        </div>\n\n        \n        <div class=\"nv-regions-block\" id=\"nv-regions\">\n            <div class=\"nv-block-header\">\n                <div>\n                    <span class=\"nv-eyebrow\"><i class=\"fas fa-globe-americas\"></i> Par région</span>\n                    <h3 class=\"nv-block-title\">Actualités <span class=\"nv-grad-text\">par région du monde</span></h3>\n                </div>\n                <a href=\"https://goexploriabusiness.com/nouvelles\" class=\"nv-see-all\" target=\"_blank\">\n                    Toutes les nouvelles <i class=\"fas fa-arrow-right\"></i>\n                </a>\n            </div>\n\n            \n            <div class=\"nv-tabs\" role=\"tablist\">\n                                <button class=\"nv-tab active\"\n                        data-tab=\"nv-tab-afrique\"\n                        style=\"--tab-color:#e8761a\"\n                        role=\"tab\"\n                        aria-selected=\"true\">\n                    <span class=\"nv-tab-flag\">🌍</span>\n                    Africa\n                    <span class=\"nv-tab-count\" style=\"background:#e8761a20;color:#e8761a\">245</span>\n                </button>\n                                <button class=\"nv-tab \"\n                        data-tab=\"nv-tab-europe\"\n                        style=\"--tab-color:#1a3a8f\"\n                        role=\"tab\"\n                        aria-selected=\"false\">\n                    <span class=\"nv-tab-flag\">🌍</span>\n                    Europe\n                    <span class=\"nv-tab-count\" style=\"background:#1a3a8f20;color:#1a3a8f\">189</span>\n                </button>\n                                <button class=\"nv-tab \"\n                        data-tab=\"nv-tab-asie\"\n                        style=\"--tab-color:#10b981\"\n                        role=\"tab\"\n                        aria-selected=\"false\">\n                    <span class=\"nv-tab-flag\">🌏</span>\n                    Asia\n                    <span class=\"nv-tab-count\" style=\"background:#10b98120;color:#10b981\">312</span>\n                </button>\n                                <button class=\"nv-tab \"\n                        data-tab=\"nv-tab-ameriques\"\n                        style=\"--tab-color:#8b5cf6\"\n                        role=\"tab\"\n                        aria-selected=\"false\">\n                    <span class=\"nv-tab-flag\">🌎</span>\n                    Americas\n                    <span class=\"nv-tab-count\" style=\"background:#8b5cf620;color:#8b5cf6\">278</span>\n                </button>\n                            </div>\n\n            \n                        <div class=\"nv-tab-panel active\" id=\"nv-tab-afrique\" role=\"tabpanel\">\n                <div class=\"nv-articles-grid\">\n                                        <div class=\"nv-article-card\">\n                        <div class=\"nv-article-img-wrap\">\n                            <img src=\"https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?w=600&amp;q=80\" alt=\"Record growth in West African economies\" class=\"nv-article-img\" loading=\"lazy\">\n                            <span class=\"nv-article-region-badge\" style=\"background:#e8761a\">Africa</span>\n                        </div>\n                        <div class=\"nv-article-body\">\n                            <span class=\"nv-article-cat\" style=\"color:#e8761a\">Économie</span>\n                            <h4 class=\"nv-article-title\">Croissance record des économies d&#039;Afrique de l&#039;Ouest</h4>\n                            <p class=\"nv-article-desc\">La CEDEAO annonce une croissance de 6.2% pour le dernier trimestre, dépassant toutes les prévisions des analystes.</p>\n                            <div class=\"nv-article-footer\">\n                                <span class=\"nv-article-time\"><i class=\"far fa-clock\"></i> Il y a 3h</span>\n                                <a href=\"#\" class=\"nv-article-read\" style=\"color:#e8761a\">\n                                    Read <i class=\"fas fa-chevron-right\"></i>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                                        <div class=\"nv-article-card\">\n                        <div class=\"nv-article-img-wrap\">\n                            <img src=\"https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=600&amp;q=80\" alt=\"Le festival Afropop attire 2 millions de visiteurs\" class=\"nv-article-img\" loading=\"lazy\">\n                            <span class=\"nv-article-region-badge\" style=\"background:#e8761a\">Africa</span>\n                        </div>\n                        <div class=\"nv-article-body\">\n                            <span class=\"nv-article-cat\" style=\"color:#e8761a\">Culture</span>\n                            <h4 class=\"nv-article-title\">Le festival Afropop attire 2 millions de visiteurs</h4>\n                            <p class=\"nv-article-desc\">Un record d&#039;affluence pour cette édition panafricaine célébrant la musique et l&#039;art contemporain.</p>\n                            <div class=\"nv-article-footer\">\n                                <span class=\"nv-article-time\"><i class=\"far fa-clock\"></i> Il y a 5h</span>\n                                <a href=\"#\" class=\"nv-article-read\" style=\"color:#e8761a\">\n                                    Read <i class=\"fas fa-chevron-right\"></i>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    \n                    \n                    <div class=\"nv-article-card nv-explore-more\" style=\"background:#fff3e6;border-color:#e8761a30\">\n                        <div class=\"nv-explore-icon\" style=\"color:#e8761a\">\n                            <i class=\"fas fa-globe\"></i>\n                        </div>\n                        <h4 style=\"color:#e8761a\">Explorer Afrique</h4>\n                        <p>245 nouvelles aujourd&#039;hui</p>\n                        <a href=\"https://goexploriabusiness.com/nouvelles/afrique\" class=\"nv-explore-btn\" style=\"background:#e8761a\" target=\"_blank\">\n                            <i class=\"fas fa-newspaper\"></i> Voir tout\n                        </a>\n                    </div>\n                </div>\n            </div>\n                        <div class=\"nv-tab-panel \" id=\"nv-tab-europe\" role=\"tabpanel\">\n                <div class=\"nv-articles-grid\">\n                                        <div class=\"nv-article-card\">\n                        <div class=\"nv-article-img-wrap\">\n                            <img src=\"https://images.unsplash.com/photo-1526628953301-3e589a6a8b74?w=600&amp;q=80\" alt=\"New migration policy of the European Union\" class=\"nv-article-img\" loading=\"lazy\">\n                            <span class=\"nv-article-region-badge\" style=\"background:#1a3a8f\">Europe</span>\n                        </div>\n                        <div class=\"nv-article-body\">\n                            <span class=\"nv-article-cat\" style=\"color:#1a3a8f\">Politique</span>\n                            <h4 class=\"nv-article-title\">Nouvelle politique migratoire de l&#039;Union Européenne</h4>\n                            <p class=\"nv-article-desc\">Les membres de l&#039;UE trouvent un accord sur une approche commune pour la gestion des frontières extérieures.</p>\n                            <div class=\"nv-article-footer\">\n                                <span class=\"nv-article-time\"><i class=\"far fa-clock\"></i> Il y a 6h</span>\n                                <a href=\"#\" class=\"nv-article-read\" style=\"color:#1a3a8f\">\n                                    Read <i class=\"fas fa-chevron-right\"></i>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                                        <div class=\"nv-article-card\">\n                        <div class=\"nv-article-img-wrap\">\n                            <img src=\"https://images.unsplash.com/photo-1467803738586-46b7eb7b16a1?w=600&amp;q=80\" alt=\"La BCE maintient ses taux directeurs stables\" class=\"nv-article-img\" loading=\"lazy\">\n                            <span class=\"nv-article-region-badge\" style=\"background:#1a3a8f\">Europe</span>\n                        </div>\n                        <div class=\"nv-article-body\">\n                            <span class=\"nv-article-cat\" style=\"color:#1a3a8f\">Économie</span>\n                            <h4 class=\"nv-article-title\">La BCE maintient ses taux directeurs stables</h4>\n                            <p class=\"nv-article-desc\">Face aux incertitudes mondiales, la Banque Centrale Européenne choisit la prudence pour le second semestre.</p>\n                            <div class=\"nv-article-footer\">\n                                <span class=\"nv-article-time\"><i class=\"far fa-clock\"></i> Il y a 9h</span>\n                                <a href=\"#\" class=\"nv-article-read\" style=\"color:#1a3a8f\">\n                                    Read <i class=\"fas fa-chevron-right\"></i>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    \n                    \n                    <div class=\"nv-article-card nv-explore-more\" style=\"background:#eef1fb;border-color:#1a3a8f30\">\n                        <div class=\"nv-explore-icon\" style=\"color:#1a3a8f\">\n                            <i class=\"fas fa-globe\"></i>\n                        </div>\n                        <h4 style=\"color:#1a3a8f\">Explorer Europe</h4>\n                        <p>189 nouvelles aujourd&#039;hui</p>\n                        <a href=\"https://goexploriabusiness.com/nouvelles/europe\" class=\"nv-explore-btn\" style=\"background:#1a3a8f\" target=\"_blank\">\n                            <i class=\"fas fa-newspaper\"></i> Voir tout\n                        </a>\n                    </div>\n                </div>\n            </div>\n                        <div class=\"nv-tab-panel \" id=\"nv-tab-asie\" role=\"tabpanel\">\n                <div class=\"nv-articles-grid\">\n                                        <div class=\"nv-article-card\">\n                        <div class=\"nv-article-img-wrap\">\n                            <img src=\"https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?w=600&amp;q=80\" alt=\"Japan launches its largest observation satellite\" class=\"nv-article-img\" loading=\"lazy\">\n                            <span class=\"nv-article-region-badge\" style=\"background:#10b981\">Asia</span>\n                        </div>\n                        <div class=\"nv-article-body\">\n                            <span class=\"nv-article-cat\" style=\"color:#10b981\">Innovation</span>\n                            <h4 class=\"nv-article-title\">Le Japon lance son plus grand satellite d&#039;observation</h4>\n                            <p class=\"nv-article-desc\">A major breakthrough for climate monitoring and natural disaster prevention in Asia-Pacific.</p>\n                            <div class=\"nv-article-footer\">\n                                <span class=\"nv-article-time\"><i class=\"far fa-clock\"></i> Il y a 8h</span>\n                                <a href=\"#\" class=\"nv-article-read\" style=\"color:#10b981\">\n                                    Read <i class=\"fas fa-chevron-right\"></i>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                                        <div class=\"nv-article-card\">\n                        <div class=\"nv-article-img-wrap\">\n                            <img src=\"https://images.unsplash.com/photo-1480714378408-67cf0d13bc1b?w=600&amp;q=80\" alt=\"Corée du Sud : boom de l&#039;intelligence artificielle\" class=\"nv-article-img\" loading=\"lazy\">\n                            <span class=\"nv-article-region-badge\" style=\"background:#10b981\">Asia</span>\n                        </div>\n                        <div class=\"nv-article-body\">\n                            <span class=\"nv-article-cat\" style=\"color:#10b981\">Tech</span>\n                            <h4 class=\"nv-article-title\">Corée du Sud : boom de l&#039;intelligence artificielle</h4>\n                            <p class=\"nv-article-desc\">Seoul devient le nouveau hub mondial de l&#039;IA avec 40 milliards d&#039;investissements annoncés pour 2026.</p>\n                            <div class=\"nv-article-footer\">\n                                <span class=\"nv-article-time\"><i class=\"far fa-clock\"></i> Il y a 11h</span>\n                                <a href=\"#\" class=\"nv-article-read\" style=\"color:#10b981\">\n                                    Read <i class=\"fas fa-chevron-right\"></i>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    \n                    \n                    <div class=\"nv-article-card nv-explore-more\" style=\"background:#edfaf5;border-color:#10b98130\">\n                        <div class=\"nv-explore-icon\" style=\"color:#10b981\">\n                            <i class=\"fas fa-globe\"></i>\n                        </div>\n                        <h4 style=\"color:#10b981\">Explorer Asie</h4>\n                        <p>312 nouvelles aujourd&#039;hui</p>\n                        <a href=\"https://goexploriabusiness.com/nouvelles/asie\" class=\"nv-explore-btn\" style=\"background:#10b981\" target=\"_blank\">\n                            <i class=\"fas fa-newspaper\"></i> Voir tout\n                        </a>\n                    </div>\n                </div>\n            </div>\n                        <div class=\"nv-tab-panel \" id=\"nv-tab-ameriques\" role=\"tabpanel\">\n                <div class=\"nv-articles-grid\">\n                                        <div class=\"nv-article-card\">\n                        <div class=\"nv-article-img-wrap\">\n                            <img src=\"https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=600&amp;q=80\" alt=\"Sommet des Amériques : accord historique sur le climat\" class=\"nv-article-img\" loading=\"lazy\">\n                            <span class=\"nv-article-region-badge\" style=\"background:#8b5cf6\">Americas</span>\n                        </div>\n                        <div class=\"nv-article-body\">\n                            <span class=\"nv-article-cat\" style=\"color:#8b5cf6\">Politique</span>\n                            <h4 class=\"nv-article-title\">Sommet des Amériques : accord historique sur le climat</h4>\n                            <p class=\"nv-article-desc\">Les 35 nations membres signent un engagement commun pour réduire de 45% leurs émissions d&#039;ici 2035.</p>\n                            <div class=\"nv-article-footer\">\n                                <span class=\"nv-article-time\"><i class=\"far fa-clock\"></i> 2 hours ago</span>\n                                <a href=\"#\" class=\"nv-article-read\" style=\"color:#8b5cf6\">\n                                    Read <i class=\"fas fa-chevron-right\"></i>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                                        <div class=\"nv-article-card\">\n                        <div class=\"nv-article-img-wrap\">\n                            <img src=\"https://images.unsplash.com/photo-1483729558449-99ef09a8c325?w=600&amp;q=80\" alt=\"Le Brésil dépasse le Canada comme 9e économie mondiale\" class=\"nv-article-img\" loading=\"lazy\">\n                            <span class=\"nv-article-region-badge\" style=\"background:#8b5cf6\">Americas</span>\n                        </div>\n                        <div class=\"nv-article-body\">\n                            <span class=\"nv-article-cat\" style=\"color:#8b5cf6\">Économie</span>\n                            <h4 class=\"nv-article-title\">Le Brésil dépasse le Canada comme 9e économie mondiale</h4>\n                            <p class=\"nv-article-desc\">Une progression portée par les exportations agricoles et la montée en puissance du secteur technologique brésilien.</p>\n                            <div class=\"nv-article-footer\">\n                                <span class=\"nv-article-time\"><i class=\"far fa-clock\"></i> Il y a 14h</span>\n                                <a href=\"#\" class=\"nv-article-read\" style=\"color:#8b5cf6\">\n                                    Read <i class=\"fas fa-chevron-right\"></i>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    \n                    \n                    <div class=\"nv-article-card nv-explore-more\" style=\"background:#f5f0ff;border-color:#8b5cf630\">\n                        <div class=\"nv-explore-icon\" style=\"color:#8b5cf6\">\n                            <i class=\"fas fa-globe\"></i>\n                        </div>\n                        <h4 style=\"color:#8b5cf6\">Explorer Amériques</h4>\n                        <p>278 nouvelles aujourd&#039;hui</p>\n                        <a href=\"https://goexploriabusiness.com/nouvelles/ameriques\" class=\"nv-explore-btn\" style=\"background:#8b5cf6\" target=\"_blank\">\n                            <i class=\"fas fa-newspaper\"></i> Voir tout\n                        </a>\n                    </div>\n                </div>\n            </div>\n                    </div>\n\n        \n        <div class=\"nv-quick-regions\">\n            <div class=\"nv-block-header\" style=\"margin-bottom:24px\">\n                <span class=\"nv-eyebrow\"><i class=\"fas fa-map-marked-alt\"></i> Couverture mondiale</span>\n            </div>\n            <div class=\"nv-quick-grid\">\n                                <a href=\"https://goexploriabusiness.com/nouvelles/afrique\" class=\"nv-quick-card\" style=\"--qc:#e8761a\" target=\"_blank\">\n                    <span class=\"nv-quick-flag\">🌍</span>\n                    <span class=\"nv-quick-label\">Africa</span>\n                    <span class=\"nv-quick-count\" style=\"color:#e8761a\">245 nouvelles</span>\n                </a>\n                                <a href=\"https://goexploriabusiness.com/nouvelles/europe\" class=\"nv-quick-card\" style=\"--qc:#1a3a8f\" target=\"_blank\">\n                    <span class=\"nv-quick-flag\">🌍</span>\n                    <span class=\"nv-quick-label\">Europe</span>\n                    <span class=\"nv-quick-count\" style=\"color:#1a3a8f\">189 nouvelles</span>\n                </a>\n                                <a href=\"https://goexploriabusiness.com/nouvelles/asie\" class=\"nv-quick-card\" style=\"--qc:#10b981\" target=\"_blank\">\n                    <span class=\"nv-quick-flag\">🌏</span>\n                    <span class=\"nv-quick-label\">Asia</span>\n                    <span class=\"nv-quick-count\" style=\"color:#10b981\">312 nouvelles</span>\n                </a>\n                                <a href=\"https://goexploriabusiness.com/nouvelles/ameriques\" class=\"nv-quick-card\" style=\"--qc:#8b5cf6\" target=\"_blank\">\n                    <span class=\"nv-quick-flag\">🌎</span>\n                    <span class=\"nv-quick-label\">Americas</span>\n                    <span class=\"nv-quick-count\" style=\"color:#8b5cf6\">278 nouvelles</span>\n                </a>\n                                <a href=\"https://goexploriabusiness.com/nouvelles/canada\" class=\"nv-quick-card\" style=\"--qc:#ef4444\" target=\"_blank\">\n                    <span class=\"nv-quick-flag\">🇨🇦</span>\n                    <span class=\"nv-quick-label\">Canada</span>\n                    <span class=\"nv-quick-count\" style=\"color:#ef4444\">134 nouvelles</span>\n                </a>\n                                <a href=\"https://goexploriabusiness.com/nouvelles/international\" class=\"nv-quick-card\" style=\"--qc:#f59e0b\" target=\"_blank\">\n                    <span class=\"nv-quick-flag\">🌐</span>\n                    <span class=\"nv-quick-label\">International</span>\n                    <span class=\"nv-quick-count\" style=\"color:#f59e0b\">421 nouvelles</span>\n                </a>\n                            </div>\n        </div>\n\n        \n        <div class=\"nv-alerts-block\" id=\"nv-alertes\">\n            <div class=\"nv-alerts-left\">\n                <div class=\"nv-alerts-badge\"><i class=\"fas fa-bell\"></i> Alertes Nouvelles</div>\n                <h3>Recevez les nouvelles<br><em>régionales en temps réel</em></h3>\n                <p>Inscrivez-vous et recevez instantanément les alertes nouvelles régionales, nationales et internationales qui vous concernent, directement dans votre boîte mail.</p>\n                <ul class=\"nv-alerts-features\">\n                    <li><i class=\"fas fa-check-circle\"></i> Alertes personnalisées par région</li>\n                    <li><i class=\"fas fa-check-circle\"></i> Notification instantanée</li>\n                    <li><i class=\"fas fa-check-circle\"></i> Résumé quotidien</li>\n                    <li><i class=\"fas fa-check-circle\"></i> Sans publicité</li>\n                </ul>\n            </div>\n            <div class=\"nv-alerts-right\">\n                <form class=\"nv-alert-form\" id=\"nvAlertForm\">\n                    <div class=\"nv-form-group\">\n                        <label>Votre adresse courriel</label>\n                        <input type=\"email\" placeholder=\"votre@courriel.com\" required>\n                    </div>\n                    <div class=\"nv-form-group\">\n                        <label>Choisissez vos régions d&#039;intérêt</label>\n                        <div class=\"nv-region-checkboxes\">\n                                                        <label class=\"nv-checkbox-label\">\n                                <input type=\"checkbox\" name=\"regions[]\" value=\"afrique\">\n                                <span class=\"nv-checkbox-pill\" style=\"--cc:#e8761a\">🌍 Afrique</span>\n                            </label>\n                                                        <label class=\"nv-checkbox-label\">\n                                <input type=\"checkbox\" name=\"regions[]\" value=\"europe\">\n                                <span class=\"nv-checkbox-pill\" style=\"--cc:#1a3a8f\">🌍 Europe</span>\n                            </label>\n                                                        <label class=\"nv-checkbox-label\">\n                                <input type=\"checkbox\" name=\"regions[]\" value=\"asie\">\n                                <span class=\"nv-checkbox-pill\" style=\"--cc:#10b981\">🌏 Asie</span>\n                            </label>\n                                                        <label class=\"nv-checkbox-label\">\n                                <input type=\"checkbox\" name=\"regions[]\" value=\"ameriques\">\n                                <span class=\"nv-checkbox-pill\" style=\"--cc:#8b5cf6\">🌎 Amériques</span>\n                            </label>\n                                                        <label class=\"nv-checkbox-label\">\n                                <input type=\"checkbox\" name=\"regions[]\" value=\"canada\">\n                                <span class=\"nv-checkbox-pill\" style=\"--cc:#ef4444\">🇨🇦 Canada</span>\n                            </label>\n                                                        <label class=\"nv-checkbox-label\">\n                                <input type=\"checkbox\" name=\"regions[]\" value=\"international\">\n                                <span class=\"nv-checkbox-pill\" style=\"--cc:#f59e0b\">🌐 International</span>\n                            </label>\n                                                    </div>\n                    </div>\n                    <div class=\"nv-form-group\">\n                        <label>Fréquence des alertes</label>\n                        <select>\n                            <option value=\"instant\">Instantané (breaking news)</option>\n                            <option value=\"daily\">Résumé quotidien</option>\n                            <option value=\"weekly\">Hebdomadaire</option>\n                        </select>\n                    </div>\n                    <button type=\"submit\" class=\"nv-btn-submit\">\n                        <i class=\"fas fa-bell\"></i> M&#039;inscrire aux alertes\n                    </button>\n                    <p class=\"nv-form-note\">Gratuit · Désabonnement en 1 clic · RGPD conforme</p>\n                </form>\n            </div>\n        </div>\n\n        \n        <div class=\"nv-cta\">\n            <div class=\"nv-cta-content\">\n                <i class=\"fas fa-newspaper\"></i>\n                <h3>Explorez toute l&#039;actualité mondiale</h3>\n                <p>Des milliers d&#039;articles mis à jour chaque heure, organisés par région, pays et thématique.</p>\n            </div>\n            <div class=\"nv-cta-buttons\">\n                <a href=\"https://goexploriabusiness.com/nouvelles\" class=\"nv-cta-primary\" target=\"_blank\">\n                    <i class=\"fas fa-globe\"></i> Toutes les nouvelles\n                </a>\n                <a href=\"#nv-alertes\" class=\"nv-cta-secondary\">\n                    <i class=\"fas fa-bell\"></i> Alertes gratuites\n                </a>\n            </div>\n        </div>\n\n    </div>\n</section>', '/* ── Variables ── */\n:root {\n    --nv-blue:   #1a3a8f;\n    --nv-orange: #e8761a;\n    --nv-green:  #10b981;\n    --nv-purple: #8b5cf6;\n    --nv-dark:   #0d1f3c;\n    --nv-light:  #f8faff;\n    --nv-border: #e5e7eb;\n}\n\n.nv-section { background: linear-gradient(180deg,#f8faff 0%,#fff 100%); }\n.nv-body    { padding: 0 40px 60px; }\n\n/* ── Gradient text ── */\n.nv-grad-text {\n    background: linear-gradient(135deg, var(--nv-orange), #f59e0b);\n    -webkit-background-clip: text;\n    background-clip: text;\n    color: transparent;\n}\n\n/* ── Eyebrow / block header ── */\n.nv-eyebrow {\n    display: inline-flex; align-items: center; gap: 6px;\n    font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px;\n    color: var(--nv-orange); background: #fef3ea;\n    padding: 5px 14px; border-radius: 999px; margin-bottom: 10px;\n}\n.nv-block-header {\n    display: flex; justify-content: space-between; align-items: flex-end;\n    margin-bottom: 28px; flex-wrap: wrap; gap: 12px;\n}\n.nv-block-title {\n    font-family: \'Playfair Display\', Georgia, serif;\n    font-size: 26px; color: #1a1a1a; margin: 0;\n}\n.nv-see-all {\n    font-size: 13px; font-weight: 700; color: var(--nv-orange);\n    text-decoration: none; display: flex; align-items: center; gap: 6px; white-space: nowrap;\n}\n.nv-see-all:hover { text-decoration: underline; }\n\n/* ══════════════════════════\n   TICKER\n══════════════════════════ */\n.nv-ticker {\n    background: var(--nv-dark); border-radius: 10px; padding: 0;\n    display: flex; align-items: stretch; margin: 20px 0 32px;\n    overflow: hidden; height: 40px;\n}\n.nv-ticker-label {\n    background: var(--nv-orange); color: #fff; padding: 0 16px;\n    font-size: 11px; font-weight: 800; letter-spacing: 1.5px; text-transform: uppercase;\n    display: flex; align-items: center; gap: 6px; flex-shrink: 0;\n}\n.nv-ticker-label i { font-size: 7px; animation: nvBlink 1.2s infinite; }\n@keyframes nvBlink { 0%,100%{opacity:1} 50%{opacity:.1} }\n.nv-ticker-track {\n    flex: 1; overflow: hidden; display: flex; align-items: center;\n}\n.nv-ticker-inner {\n    display: flex; gap: 60px; white-space: nowrap;\n    animation: nvTicker 40s linear infinite; padding-left: 24px;\n}\n.nv-ticker-inner span { font-size: 13px; color: rgba(255,255,255,.85); flex-shrink: 0; }\n@keyframes nvTicker { 0%{transform:translateX(0)} 100%{transform:translateX(-50%)} }\n\n/* ══════════════════════════\n   HERO FEATURED\n══════════════════════════ */\n.nv-hero {\n    display: grid; grid-template-columns: 1fr 340px;\n    gap: 24px; margin-bottom: 48px; align-items: stretch;\n}\n.nv-hero-img-wrap {\n    position: relative; border-radius: 20px; overflow: hidden;\n    min-height: 380px;\n}\n.nv-hero-img {\n    width: 100%; height: 100%; object-fit: cover;\n    transition: transform .5s;\n}\n.nv-hero-img-wrap:hover .nv-hero-img { transform: scale(1.04); }\n.nv-hero-overlay {\n    position: absolute; inset: 0;\n    background: linear-gradient(0deg, rgba(10,22,40,.92) 0%, rgba(10,22,40,.3) 60%, transparent 100%);\n    padding: 28px 32px; display: flex; flex-direction: column; justify-content: flex-end;\n}\n.nv-hero-badge {\n    display: inline-flex; align-items: center; gap: 6px;\n    background: var(--nv-orange); color: #fff;\n    font-size: 10px; font-weight: 800; text-transform: uppercase; letter-spacing: 1px;\n    padding: 4px 12px; border-radius: 6px; margin-bottom: 12px; align-self: flex-start;\n}\n.nv-hero-regions { display: flex; gap: 8px; margin-bottom: 14px; flex-wrap: wrap; }\n.nv-region-pill {\n    font-size: 10px; font-weight: 700; color: #fff;\n    padding: 3px 10px; border-radius: 999px;\n}\n.nv-hero-title {\n    font-family: \'Playfair Display\', Georgia, serif;\n    font-size: clamp(20px, 2.2vw, 30px); color: #fff;\n    line-height: 1.25; margin-bottom: 12px;\n}\n.nv-hero-desc { font-size: 14px; color: rgba(255,255,255,.75); line-height: 1.7; margin-bottom: 18px; }\n.nv-hero-meta {\n    display: flex; align-items: center; gap: 20px; flex-wrap: wrap;\n}\n.nv-hero-meta span { font-size: 12px; color: rgba(255,255,255,.6); display: flex; align-items: center; gap: 5px; }\n.nv-hero-read-btn {\n    background: var(--nv-orange); color: #fff; padding: 8px 18px; border-radius: 8px;\n    font-size: 13px; font-weight: 700; text-decoration: none;\n    display: inline-flex; align-items: center; gap: 7px; transition: background .2s;\n    margin-left: auto;\n}\n.nv-hero-read-btn:hover { background: #c45e0e; color: #fff; }\n\n/* Sidebar */\n.nv-hero-sidebar {\n    background: #fff; border: 1.5px solid var(--nv-border);\n    border-radius: 20px; overflow: hidden; display: flex; flex-direction: column;\n}\n.nv-sidebar-label {\n    background: var(--nv-dark); color: #fff;\n    padding: 12px 18px; font-size: 11px; font-weight: 700;\n    text-transform: uppercase; letter-spacing: 1px;\n    display: flex; align-items: center; gap: 7px;\n}\n.nv-sidebar-label i { color: var(--nv-orange); }\n.nv-mini-article {\n    padding: 12px 18px; border-bottom: 1px solid #f0f0f0;\n    text-decoration: none; display: block; transition: background .2s;\n}\n.nv-mini-article:last-child { border-bottom: none; }\n.nv-mini-article:hover { background: var(--nv-light); }\n.nv-mini-meta { display: flex; align-items: center; gap: 8px; margin-bottom: 5px; }\n.nv-mini-time { font-size: 10px; color: #999; display: flex; align-items: center; gap: 4px; }\n.nv-mini-cat  { font-size: 9px; font-weight: 700; text-transform: uppercase; color: var(--nv-orange); background: #fef3ea; padding: 2px 7px; border-radius: 4px; }\n.nv-mini-title { font-size: 13px; font-weight: 600; color: #1a1a1a; line-height: 1.45; margin: 0; }\n\n/* ══════════════════════════\n   ONGLETS RÉGIONS\n══════════════════════════ */\n.nv-regions-block { margin-bottom: 48px; }\n.nv-tabs {\n    display: flex; gap: 8px; margin-bottom: 24px;\n    border-bottom: 2px solid var(--nv-border); padding-bottom: 0;\n    overflow-x: auto; scrollbar-width: none; flex-wrap: nowrap;\n}\n.nv-tabs::-webkit-scrollbar { display: none; }\n.nv-tab {\n    display: flex; align-items: center; gap: 7px;\n    padding: 10px 20px; border: none; background: transparent;\n    font-size: 14px; font-weight: 600; color: #666; cursor: pointer;\n    border-bottom: 3px solid transparent; margin-bottom: -2px;\n    white-space: nowrap; transition: all .2s; border-radius: 0;\n}\n.nv-tab:hover { color: var(--tab-color); }\n.nv-tab.active { color: var(--tab-color); border-bottom-color: var(--tab-color); }\n.nv-tab-flag  { font-size: 16px; }\n.nv-tab-count {\n    font-size: 10px; font-weight: 700; padding: 2px 7px; border-radius: 999px;\n}\n\n/* Tab panels */\n.nv-tab-panel { display: none; }\n.nv-tab-panel.active { display: block; }\n.nv-articles-grid {\n    display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px;\n}\n.nv-article-card {\n    background: #fff; border: 1.5px solid var(--nv-border);\n    border-radius: 18px; overflow: hidden; transition: all .3s;\n    display: flex; flex-direction: column;\n}\n.nv-article-card:hover { transform: translateY(-4px); box-shadow: 0 16px 40px rgba(0,0,0,.08); border-color: var(--nv-orange); }\n.nv-article-img-wrap { position: relative; height: 180px; overflow: hidden; }\n.nv-article-img      { width: 100%; height: 100%; object-fit: cover; transition: transform .4s; }\n.nv-article-card:hover .nv-article-img { transform: scale(1.06); }\n.nv-article-region-badge {\n    position: absolute; top: 10px; left: 10px;\n    color: #fff; font-size: 9px; font-weight: 800; text-transform: uppercase;\n    letter-spacing: .8px; padding: 3px 9px; border-radius: 5px;\n}\n.nv-article-body { padding: 18px 20px; flex: 1; display: flex; flex-direction: column; }\n.nv-article-cat  { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .8px; margin-bottom: 8px; }\n.nv-article-title { font-family: \'Playfair Display\', Georgia, serif; font-size: 16px; font-weight: 700; color: #1a1a1a; line-height: 1.4; margin-bottom: 10px; }\n.nv-article-desc  { font-size: 12px; color: #666; line-height: 1.65; flex: 1; margin-bottom: 14px; }\n.nv-article-footer { display: flex; justify-content: space-between; align-items: center; }\n.nv-article-time   { font-size: 11px; color: #999; display: flex; align-items: center; gap: 4px; }\n.nv-article-read   { font-size: 12px; font-weight: 700; text-decoration: none; display: flex; align-items: center; gap: 4px; }\n.nv-article-read:hover { text-decoration: underline; }\n\n/* Explore more card */\n.nv-explore-more {\n    display: flex !important; flex-direction: column !important;\n    align-items: center; justify-content: center; text-align: center;\n    padding: 32px 24px; border-width: 2px; border-style: dashed;\n}\n.nv-explore-icon { font-size: 44px; margin-bottom: 14px; }\n.nv-explore-more h4 { font-size: 18px; font-weight: 700; margin-bottom: 8px; }\n.nv-explore-more p  { font-size: 13px; color: #888; margin-bottom: 20px; }\n.nv-explore-btn {\n    color: #fff; padding: 10px 22px; border-radius: 10px;\n    font-size: 13px; font-weight: 700; text-decoration: none;\n    display: inline-flex; align-items: center; gap: 7px; transition: opacity .2s;\n}\n.nv-explore-btn:hover { opacity: .88; color: #fff; }\n\n/* ══════════════════════════\n   QUICK REGIONS GRID\n══════════════════════════ */\n.nv-quick-regions { margin-bottom: 48px; }\n.nv-quick-grid {\n    display: grid; grid-template-columns: repeat(6, 1fr); gap: 14px;\n}\n.nv-quick-card {\n    background: #fff; border: 1.5px solid var(--nv-border);\n    border-radius: 14px; padding: 18px 14px; text-decoration: none;\n    display: flex; flex-direction: column; align-items: center; text-align: center; gap: 6px;\n    transition: all .25s;\n    border-top: 3px solid var(--qc, var(--nv-orange));\n}\n.nv-quick-card:hover { transform: translateY(-3px); box-shadow: 0 8px 20px rgba(0,0,0,.07); }\n.nv-quick-flag  { font-size: 28px; }\n.nv-quick-label { font-size: 13px; font-weight: 700; color: #1a1a1a; }\n.nv-quick-count { font-size: 11px; font-weight: 600; }\n\n/* ══════════════════════════\n   ALERTES INSCRIPTION\n══════════════════════════ */\n.nv-alerts-block {\n    background: linear-gradient(135deg, #0d1f3c, #1a3a8f);\n    border-radius: 28px; padding: 56px; margin-bottom: 48px;\n    display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: start;\n}\n.nv-alerts-badge {\n    display: inline-flex; align-items: center; gap: 7px;\n    background: rgba(232,118,26,.2); border: 1px solid rgba(232,118,26,.35);\n    color: #e8761a; padding: 5px 14px; border-radius: 999px;\n    font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px;\n    margin-bottom: 18px;\n}\n.nv-alerts-left h3 {\n    font-family: \'Playfair Display\', Georgia, serif;\n    font-size: 28px; color: #fff; line-height: 1.2; margin-bottom: 14px;\n}\n.nv-alerts-left h3 em { font-style: italic; color: var(--nv-orange); }\n.nv-alerts-left p { font-size: 14px; color: rgba(255,255,255,.7); line-height: 1.8; margin-bottom: 22px; }\n.nv-alerts-features { list-style: none; display: flex; flex-direction: column; gap: 10px; }\n.nv-alerts-features li { font-size: 13px; color: rgba(255,255,255,.8); display: flex; align-items: center; gap: 9px; }\n.nv-alerts-features li i { color: var(--nv-green); }\n\n/* Form */\n.nv-form-group  { margin-bottom: 16px; }\n.nv-form-group label {\n    display: block; font-size: 12px; font-weight: 700;\n    color: rgba(255,255,255,.8); margin-bottom: 7px;\n}\n.nv-form-group input,\n.nv-form-group select {\n    width: 100%; background: rgba(255,255,255,.08);\n    border: 1.5px solid rgba(255,255,255,.15);\n    border-radius: 10px; padding: 12px 14px;\n    font-size: 14px; color: #fff; transition: border-color .2s;\n}\n.nv-form-group input::placeholder { color: rgba(255,255,255,.4); }\n.nv-form-group select option { background: #1a3a8f; color: #fff; }\n.nv-form-group input:focus,\n.nv-form-group select:focus { outline: none; border-color: var(--nv-orange); }\n\n/* Checkboxes régions */\n.nv-region-checkboxes { display: flex; flex-wrap: wrap; gap: 8px; }\n.nv-checkbox-label    { cursor: pointer; }\n.nv-checkbox-label input { display: none; }\n.nv-checkbox-pill {\n    display: inline-block; padding: 5px 12px; border-radius: 999px;\n    font-size: 12px; font-weight: 600; color: rgba(255,255,255,.7);\n    background: rgba(255,255,255,.08); border: 1.5px solid rgba(255,255,255,.15);\n    transition: all .2s; cursor: pointer;\n}\n.nv-checkbox-label input:checked + .nv-checkbox-pill {\n    background: var(--cc, var(--nv-orange)); color: #fff;\n    border-color: var(--cc, var(--nv-orange));\n}\n.nv-btn-submit {\n    width: 100%; background: linear-gradient(135deg, var(--nv-orange), #c04f10);\n    color: #fff; border: none; border-radius: 10px; padding: 14px;\n    font-size: 14px; font-weight: 700; cursor: pointer;\n    display: flex; align-items: center; justify-content: center; gap: 8px;\n    transition: all .2s; margin-top: 6px;\n}\n.nv-btn-submit:hover { transform: translateY(-2px); box-shadow: 0 12px 32px rgba(232,118,26,.4); }\n.nv-form-note { font-size: 11px; color: rgba(255,255,255,.4); text-align: center; margin-top: 10px; }\n\n/* ══════════════════════════\n   CTA FINAL\n══════════════════════════ */\n.nv-cta {\n    background: linear-gradient(135deg, #fef3ea, #fff3e6);\n    border-radius: 24px; padding: 40px 48px;\n    display: flex; justify-content: space-between; align-items: center;\n    gap: 32px; flex-wrap: wrap;\n}\n.nv-cta-content { display: flex; flex-direction: column; }\n.nv-cta-content i  { font-size: 32px; color: var(--nv-orange); margin-bottom: 10px; }\n.nv-cta-content h3 { font-size: 22px; color: #1a1a1a; margin-bottom: 6px; }\n.nv-cta-content p  { font-size: 14px; color: #666; }\n.nv-cta-buttons { display: flex; gap: 12px; flex-wrap: wrap; }\n.nv-cta-primary {\n    background: var(--nv-orange); color: #fff; padding: 12px 24px;\n    border-radius: 10px; font-weight: 700; font-size: 14px; text-decoration: none;\n    display: inline-flex; align-items: center; gap: 7px; transition: all .2s;\n}\n.nv-cta-primary:hover { background: #c45e0e; transform: translateY(-2px); color: #fff; }\n.nv-cta-secondary {\n    border: 2px solid var(--nv-orange); color: var(--nv-orange); padding: 12px 24px;\n    border-radius: 10px; font-weight: 700; font-size: 14px; text-decoration: none;\n    display: inline-flex; align-items: center; gap: 7px; transition: all .2s;\n}\n.nv-cta-secondary:hover { background: var(--nv-orange); color: #fff; }\n\n/* ══════════════════════════\n   RESPONSIVE\n══════════════════════════ */\n@media(max-width:1200px) {\n    .nv-quick-grid { grid-template-columns: repeat(3, 1fr); }\n    .nv-hero       { grid-template-columns: 1fr; }\n    .nv-hero-sidebar { min-height: 0; }\n    .nv-alerts-block { grid-template-columns: 1fr; gap: 36px; }\n}\n@media(max-width:900px) {\n    .nv-body           { padding: 0 20px 40px; }\n    .nv-articles-grid  { grid-template-columns: 1fr 1fr; }\n    .nv-quick-grid     { grid-template-columns: repeat(2, 1fr); }\n    .nv-alerts-block   { padding: 36px 24px; }\n    .nv-cta            { flex-direction: column; text-align: center; }\n    .nv-cta-content    { align-items: center; }\n    .nv-cta-buttons    { justify-content: center; }\n}\n@media(max-width:600px) {\n    .nv-articles-grid  { grid-template-columns: 1fr; }\n    .nv-quick-grid     { grid-template-columns: repeat(2, 1fr); }\n    .nv-tabs           { flex-wrap: nowrap; }\n    .nv-hero-overlay   { padding: 20px; }\n}', '(function () {\n    // Onglets régions\n    const tabs = document.querySelectorAll(\'#nv-nouvelles .nv-tab\');\n    const panels = document.querySelectorAll(\'#nv-nouvelles .nv-tab-panel\');\n    tabs.forEach(tab => {\n        tab.addEventListener(\'click\', () => {\n            tabs.forEach(t => { t.classList.remove(\'active\'); t.setAttribute(\'aria-selected\',\'false\'); });\n            panels.forEach(p => p.classList.remove(\'active\'));\n            tab.classList.add(\'active\');\n            tab.setAttribute(\'aria-selected\',\'true\');\n            const target = document.getElementById(tab.dataset.tab);\n            if (target) target.classList.add(\'active\');\n        });\n    });\n\n    // Formulaire alertes\n    document.getElementById(\'nvAlertForm\')?.addEventListener(\'submit\', function(e) {\n        e.preventDefault();\n        const btn = this.querySelector(\'.nv-btn-submit\');\n        btn.innerHTML = \'<i class=\"fas fa-check\"></i> Inscription confirmée !\';\n        btn.style.background = \'#10b981\';\n        setTimeout(() => {\n            btn.innerHTML = \'<i class=\"fas fa-bell\"></i> M\\\'inscrire aux alertes\';\n            btn.style.background = \'\';\n            this.reset();\n        }, 3000);\n    });\n})();', 'builder', 'grapesjs', NULL, 'fa-cube', 20, 0, '2026-07-13 12:20:18', '2026-07-20 14:23:36');
